pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual below the minimum item size (1) is impossible, but tiny
    // residuals relative to typical item sizes are near-dead space.
    let dead_threshold = 20.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Coupling with next item: if the next item fits the post-residual,
    // this is a great chain placement; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // We destroyed the ability to fit the next item: penalize.
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (avoid sprawl); with few bins, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += pressure * (post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the current item
    // leaves a large, useful residual or bins are few.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        let mut new_bin_score = 60.0;
        // Cheap to open early in the stream or when few bins are open.
        new_bin_score -= 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        new_bin_score -= (open_bins_count as f64).min(10.0) * 1.5;
        // If mean residual across open bins is small, opening fresh space is valuable.
        new_bin_score -= (mean_residual / bin_capacity as f64) * 20.0;
        // If the item would leave a large residual here, a new bin is fine too.
        if post_residual as f64 >= mean_residual {
            new_bin_score -= 10.0;
        }
        score = score.min(new_bin_score);
        // Never let the new-bin candidate win when a perfect fit exists elsewhere.
        if post_residual == 0 {
            score = 1e9;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals in [1, 12] are nearly unusable for future items.
    if post_residual > 0 && post_residual <= 12 {
        score += 30.0 + (12.0 - post_residual as f64) * 2.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room that can still host the next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (post_residual as f64 - next_item_size as f64).min(40.0) * 0.25;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual cannot host next item: mild penalty scaled by gap size.
        score += (next_item_size as f64 - post_residual as f64) * 0.4;
    }

    // Open-bin pressure: discourage spreading across many bins when few fit options exist.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins)
    // so large residuals stay available for large items.
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: opening a fresh bin is attractive only when the item
    // is large (would leave a big residual anyway) or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score = 55.0 - item_size as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin anyway
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // plausible future item (min size 1..100, but typical small item ~10)
    // are wasted capacity. Penalize small unusable gaps nonlinearly.
    if post_residual > 0 {
        if post_residual < 10 {
            // gap below the smallest possible item => pure dead space
            score += 40.0 + 3.0 * (10 - post_residual) as f64;
        } else if post_residual < 20 {
            // very likely dead space for most distributions
            score += 18.0 + 0.8 * (20 - post_residual) as f64;
        } else if post_residual < 30 {
            score += 6.0;
        }
    } else {
        // perfect fit: reward strongly
        score -= 30.0;
    }

    // Reward leaving a gap that exactly (or nearly) accommodates the lookahead item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 12.0 - slack as f64;
            }
        } else {
            // lookahead cannot fit here; mild penalty proportional to shortfall
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage using this bin when it is the last fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }
    score += 0.35 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64).max(0.1);

    // Prefer bins whose residual is below average (tighter bins first),
    // keeping looser bins available for larger future items.
    let diff = mean_residual - bin_residual as f64;
    score += 0.5 * diff;

    // Slight preference for filling fuller bins (small bin_residual)
    score += 0.2 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exact or near-exact fill.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Dead space penalty: gaps too small to ever be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        // Gap can't fit the lookahead item: penalize more if it also can't fit typical small items.
        score += 60.0 + 3.0 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Open-bins pressure: discourage scattering across many bins when residuals are plentiful.
    if open_bins_count > 2 {
        score += (open_bins_count as f64) * 2.0;
    }

    // New-bin candidate handling: only open a new bin if the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        // Base new-bin cost; cheaper when many bins already open and mean residual is low.
        score = 120.0 + poor_fit * 0.5 - (open_bins_count as f64) * 1.5 - mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= bin_residual as u32 - item_size {
            score -= 40.0; // fresh bin leaves room for lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = (mean_residual - item_size as f64).abs();
        score += 18.0 + 20.0 * progress - 0.3 * tightness;
        if next_item_size > 0 && next_item_size <= post_residual.max(item_size as u32) {
            score -= 6.0;
        }
    }

    // Mild preference for filling bins below mean residual (keeps large residuals available)
    if (bin_residual as f64) > mean_residual && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Penalize very small unusable leftovers scaled by stream position
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows super-linearly for tiny residuals.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 12.0;
        }
        // Modulo classes: residuals divisible by common item sizes are reusable.
        let pr = post_residual;
        if pr % 10 == 0 { score -= 25.0; }
        else if pr % 5 == 0 { score -= 10.0; }
        else { score += 8.0; }
        // Harmonic quartile of capacity.
        let quarter = bin_capacity / 4;
        if pr >= 3 * quarter { score -= 15.0; }
        else if pr >= 2 * quarter { score -= 5.0; }
        else if pr >= quarter { score += 5.0; }
        else { score += 20.0; }
    }

    // Lookahead coupling: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            score -= (nxt_post as f64).min(60.0) * 1.5;
            if nxt_post % 10 == 0 { score -= 15.0; }
        } else {
            // Next item won't fit here; mild penalty for stranding space.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 30.0;
        if open_bins_count == 0 { score -= 500.0; }
        if mean_residual < 20.0 { score -= 120.0; }
        if post_residual == bin_capacity { score += 0.0; }
    }

    // Prefer tighter bins overall (below mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Stream progression: near the end, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are never dead, but residuals that are small yet
    // nonzero relative to typical item sizes are wasted capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_threshold = 12.0 + 6.0 * (1.0 - progress); // stricter late in stream
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6) * 20.0;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bins pressure: penalize spreading across many open bins,
    // encouraging consolidation; but relax pressure as stream progresses.
    score += open_bins_count as f64 * (1.0 + 0.5 * (1.0 - progress));

    // Deviation from mean residual: prefer bins whose residual deviates
    // from the mean (large residual bins absorb big items better).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item can exactly fill this bin's post
    // residual, big reward; if next item won't fit post residual,
    // mild penalty for stranding the bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 5.0;
        }
    }

    // New-bin candidate: make empty bins moderately attractive so we open
    // a new bin only when existing fits are poor, but discourage opening
    // new bins when few bins are open or the item fits reasonably well.
    if bin_residual == bin_capacity {
        let base = 45.0;
        let fit_pressure = if fitting_bins_count > 0 { 25.0 } else { 0.0 };
        score = base + fit_pressure + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A small post_residual that can never host a typical future item is dead space.
    // Penalize it super-linearly: gaps in (0, 10] are pure waste, gaps just above
    // common item sizes are semi-usable.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) <= dead_threshold {
        score += (dead_threshold - post_residual as f64 + 1.0) * 40.0; // unusable gap penalty
    }

    // Tight fit reward: the closer post_residual is to 0 (but usable), the better.
    score -= (bin_capacity - post_residual) as f64 * 0.3;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // --- Usability shaping ---
    // Prefer leaving residuals that are "round" usable amounts (>= next item or >= 10).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the lookahead item: reward chaining.
            score -= 25.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // Leaves a gap the next item cannot use: penalize proportionally to waste.
            score += (next_item_size as f64 - post_residual as f64) * 1.5;
        }
    }

    // --- Open-bin pressure ---
    // Discourage scattering across many open bins; but when this is the ONLY bin
    // that fits, strongly favor using it to avoid opening a new bin.
    score += open_bins_count as f64 * 1.2;
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // --- New-bin candidate handling ---
    // Brand-new empty bin: neutral baseline; only prefer it when current bins are
    // crowded (low mean residual) or item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score = 55.0 + crowding * 30.0;
        if item_size > 70 {
            score -= 20.0; // large items start fresh bins more readily
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score += 5.0; // slight penalty for fresh bin when item could chain elsewhere
        }
    }

    // --- Stream progression: late in stream, consolidate aggressively ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits relative to bin capacity.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Open-bins pressure: discourage scattering when many bins are open.
    score += 2.5 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (avoid wasting large bins on small items).
    score += 0.2 * (bin_residual as f64 - item_size as f64).abs();

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into the resulting residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Residual too small for the next item: penalize mildly.
        score += 15.0;
    }

    // Mean residual alignment: prefer bins below the mean residual (tighter bins first).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate handling: only attractive early or when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = if fitting_bins_count == 0 { 100.0 } else { 0.0 };
        score = 100.0 + 150.0 * progress + desperation - 30.0 * (1.0 - fit_ratio);
        if fitting_bins_count == 1 {
            score += 80.0; // don't abandon the last-chance bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Bonus for exact fit.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize post-residuals that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress);

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild preference for filling fuller bins.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of bin filled by this item
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Penalize large dead space (post residual that nothing typical can use)
    if post_residual > 0 && post_residual < 10 {
        score -= 40.0; // small unusable slivers are fine (near perfect fit)
    } else if post_residual >= 10 && post_residual <= 30 {
        score += 10.0; // moderate dead space risk
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual remains useful
            score -= 15.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // placing here kills usefulness for the next item
            let waste = post_residual as f64;
            score += 8.0 + 0.5 * waste;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer new bin when open bins fit poorly and stream is early/mid
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64;
        let poor_fit_penalty = (post_residual as f64) / bin_capacity as f64;
        // Base cost of opening a bin grows with progress (fewer future items to fill it)
        score += 120.0 + 250.0 * progress - 40.0 * poor_fit_penalty - 5.0 * pressure;
        // If next item is large, a fresh bin is attractive
        if next_item_size >= 50 {
            score -= 25.0;
        }
    }

    // Global state: many open bins with high mean residual -> consolidate
    if mean_residual > 30.0 && open_bins_count > 2 && bin_residual != bin_capacity {
        score -= 0.3 * mean_residual;
    }

    // Prefer bins with smaller residual overall (best-fit flavor), scaled by progress
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (<= 10) are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += 120.0 + (10 - post_residual) as f64 * 15.0;
    } else if post_residual <= 20 {
        // Small gap: only useful if next item can use it.
        if next_item_size == 0 || next_item_size > post_residual {
            score += 25.0 + (20 - post_residual) as f64;
        } else {
            score -= 10.0; // gap is reusable by lookahead item
        }
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, prefer
    // filling existing bins; few open bins -> allow new-bin flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Mean residual coupling: penalize bins far below mean residual
    // (they are "odd" bins); prefer bins near the mean to homogenize.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no good fit exists:
        // i.e. this item leaves a large unusable gap in every open bin.
        // Give the empty bin a moderate base score; subtract when the
        // item fits perfectly (post_residual small but usable).
        score = 60.0;
        if post_residual < 10 {
            score -= 30.0; // near-perfect fit in fresh bin
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 20.0;
        // Few fitting bins -> new bin less attractive (last-chance exists).
        if fitting_bins_count <= 1 {
            score += 15.0;
        }
    }

    // Lookahead synergy: if next item exactly fills the post residual,
    // reward this placement strongly.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (1..100) are pure waste. Penalize unusable gaps hard.
    if post_residual > 0 {
        // Gap smaller than the minimum conceivable item is dead space.
        if post_residual < 10 {
            score += 200.0;
        } else if post_residual < 25 {
            score += 60.0 + (25 - post_residual) as f64 * 4.0;
        } else if post_residual < 40 {
            score += 15.0;
        }
        // Perfect or near-perfect fits are heavily rewarded.
        if post_residual == 0 {
            score -= 120.0;
        } else if post_residual <= 5 {
            score -= 40.0;
        }
    }

    // Reward using bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; penalize placements that leave mid-range gaps.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * (post_residual as f64 - mean_residual).max(0.0) * 0.5;
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin — reward unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit,
    // i.e., when this call is the fresh bin. Judge via lookahead.
    if bin_residual == bin_capacity {
        let lookahead_penalty = if next_item_size > 0 {
            // A fresh bin is good if the next item could pair with the
            // post_residual of the current placement elsewhere; here the
            // fresh bin keeps flexibility, so reward slightly when the
            // current item is large relative to capacity.
            (item_size as f64 / bin_capacity as f64) * 30.0
        } else {
            10.0
        };
        // Base cost of opening a new bin, offset by flexibility bonus.
        score += 35.0 - lookahead_penalty;
    }

    // Lookahead: if the next item exactly fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Mild stream-progression term: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (item exactly fills the bin).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly matches
    // the post-residual (perfect chain match).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let pr = post_residual as f64;
        if next_item_size == post_residual {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to tightness
            let tightness = 1.0 - (pr - ni) / bin_capacity as f64;
            score -= 50.0 * tightness;
        } else {
            // next item cannot fit here: penalize the unusable gap,
            // worse the smaller the gap (dead space).
            let gap = ni - pr;
            score += 30.0 + 2.0 * gap as f64;
        }
    }

    // Penalize leaving residual far below mean residual (fragmented bin).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.5 * dev;
    } else {
        score += 0.1 * dev; // slight reward for above-average residual bins
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New empty bin candidate: base cost high, but cheaper late in the
    // stream and when many bins are already open (amortization).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 400.0 - 150.0 * progress - 5.0 * open_bins_count as f64;
        // If no existing bin fits, opening a new bin is the only option;
        // make it clearly preferable to a bad-fit placement.
        if fitting_bins_count == 0 {
            score -= 600.0;
        }
        // If next item is huge, a fresh bin is attractive.
        if next_item_size > 60 {
            score -= 50.0;
        }
    }

    // Small tie-break toward tighter residual bins.
    score += 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize post residual, with non-linear (quadratic/cubic) coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);
    score += cap * 2.0 * norm_pr * norm_pr * (0.5 + progress);

    // Dead-space penalty grows non-linearly when residual becomes unusably small
    score += cap * 3.0 * (1.0 - norm_pr).powi(3) * norm_item * (1.0 + progress);

    // Tight fit reward (small post residual), stronger early in stream
    score -= cap * 1.5 * (1.0 - norm_pr).powi(2) * (1.2 - progress);

    // Last-chance bonus: only bin that fits -> strong reward, smooth
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= cap * 2.5 * last_chance * (1.0 - norm_pr * 0.5);

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let nx = next_item_size as f64 / cap;
        score -= cap * 1.2 * fits_next * nx * (1.0 + progress);
        // Penalize leaving residual just barely below next item (smooth near-miss penalty)
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += cap * 1.0 * gap * (1.0 - gap) * 4.0 * (1.0 - fits_next);
    }

    // Mean residual context: penalize bins far from mean (fragmentation), smooth coupling
    let dev = (pr - mean_residual) / cap;
    score += cap * 0.6 * dev * dev;

    // New-bin candidate: neutral-ish, penalize slightly more as stream progresses
    // unless open bins would create large dead space
    if bin_residual == bin_capacity {
        score = cap * 0.9 + cap * 0.8 * progress - cap * 2.0 * norm_item * (1.0 - norm_item);
        // prefer new bin if all fits would leave tiny residuals
        score -= cap * 2.0 * norm_item * (1.0 - norm_item) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

