        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // existing fits are poor (high mean residual spread) or few bins fit.
    if bin_residual == bin_capacity {
        let base_new = 55.0;
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            base_new + 20.0 * (mean_residual / bin_capacity as f64) + 15.0 * (fitting_bins_count as f64).ln().max(0.0)
        };
        score = pressure + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score -= 1.5 * (bin_capacity as f64 - waste) / bin_capacity as f64 * (100.0 - waste);

    // Strong reward for near-perfect fits.
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // Penalize dead space that no future item (min size 1, typical >=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: penalize if this placement leaves residual that barely fits next item,
    // blocking it; reward if leftover is either 0 or comfortably large.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 >= nr && (post_residual as f64 - nr) < 8.0 {
            score += 20.0; // would strand next item's fit
        }
        if post_residual == 0 {
            score -= 10.0; // perfect closure helps next item use other bins
        }
        if (post_residual as f64) < nr && post_residual > 0 && post_residual < 10 {
            score += 15.0; // tiny unusable sliver given known next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * mean_residual.max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 - 0.3 * crowded - 20.0 * (1.0 - progress);
        // If item fits poorly nowhere else (many bins but none fit well), allow new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for fuller bins early (best-fit consolidation).
    let fill_ratio = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Global state coupling: if mean residual is large, prefer bins below mean (balance).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual, with non-linear (quadratic) coupling.
    let mut score = post + 0.9 * (post * post) / cap;

    // Smooth interaction: post residual weighted by stream progress.
    score += 2.0 * post * progress * (1.0 - progress) * 4.0 * progress.max(0.05);

    // Reward tight fits (post_residual small relative to capacity).
    let tightness = 1.0 - post / cap;
    score -= 3.0 * tightness * tightness * item / cap * 10.0;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 6.0 * (nxt - post) * (0.5 + progress);
        } else {
            score -= 1.5 * (1.0 - (post - nxt) / cap) * progress;
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Prefer bins with below-average residual (fill emptier bins less, keep big residuals).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize mildly so it wins only when fits are poor;
    // penalty decays as stream progresses (consolidate late).
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress - 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer bins whose leftover is small but not dead space.
    // Aggressive 2-step lookahead: does the NEXT item fit perfectly here?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: this item leaves exactly room for the next one.
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.35;
        } else {
            // Next item won't fit here; penalize proportional to wasted opportunity,
            // but less harsh if post_residual is tiny (bin is nearly full anyway).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            if post_residual <= 5 {
                score -= 12.0; // near-perfect fill, dead space is negligible
            }
        }
    } else {
        // Last item in stream: just minimize leftover.
        score -= 25.0;
    }

    // Reward tight fits relative to the bin's current state.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Penalize creating unusable slivers (residual too small for the minimum item).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Make the empty bin moderately attractive by default...
    if bin_residual == bin_capacity {
        score -= 10.0 + 0.15 * open_bins_count as f64;
        // ...but push it away when the stream is late and open bins are loose
        // (consolidate before opening more bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        if mean_residual > 40.0 {
            score += 25.0; // plenty of loose space already; don't open a new bin
        }
    }

    // Slight preference for bins tighter than the current mean residual
    // (pack into crowded bins, keep loose bins for awkward future items).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Mild exploration penalty for very many open bins: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

