    // this placement would leave a large, awkward residual.
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin; penalize slightly so tight fits
        // in existing bins win, but allow it when fits are terrible.
        score += 40.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Penalize very small unusable residuals (dead space) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Slight preference for keeping fewer open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
