        score += 0.05 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual coupling: prefer bins deviating from mean when mean is high
    // (consolidate space), smoothly via a sigmoid-like term.
    let mr = mean_residual / cap;
    score += 0.4 * mr * norm_pr;

    // New-bin candidate handling: an empty bin has norm_pr == 1.0; make it
    // attractive only when the stream is young or residuals are large.
    if bin_residual == bin_capacity {
        score = 1.0 + 2.7 * norm_pr * (1.0 + 1.7 * norm_pr + 0.9 * norm_pr * norm_pr);
        score -= 1.5 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" classes (<= 10, <= 20) are nearly perfect fits; reward them.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class thresholds via integer division (harmonic buckets of capacity/10)
    let bucket = post_residual / 10; // 0..=10 harmonic class
    match bucket {
        0 => score -= 60.0,              // dead-space-free placement
        1 => score -= 40.0,              // leftover 10..19 : fits smallest items
        2 => score -= 25.0,              // leftover 20..29
        3 => score -= 15.0,
        4 => score -= 8.0,
        _ => {}                           // large leftovers are wasteful anyway
    }

    // Penalize leftovers that NO plausible future item (1..=100) can use well:
    // a residual strictly below the minimum item size is pure dead space.
    if post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward (perfect chaining); if next item cannot fit anywhere else
    // but fits here, reward as rescue.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            score += 12.0; // next item won't fit here; bin will be stranded
        }
    }

    // Last-chance bin: only one open bin can fit this item. Avoid opening a
    // new bin unless the fit here is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): should only win when
    // current item is huge (would strand an open bin) or many bins are open.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 2.0;
        score += 70.0 - pressure + (item_size as f64) * 0.5;
        // late in the stream, prefer filling existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 25.0;
    }

    // Mild pull toward bins with residuals matching the item's harmonic class:
    // prefer bins where item occupies a "clean" fraction of the residual.
    let frac = (item_size as f64) / (bin_residual.max(1) as f64);
    if (frac * 4.0).round() == frac * 4.0 && frac <= 1.0 {
        score -= 6.0; // quarter-class alignment (1/4, 1/2, 3/4, 1 of residual)
    }

    // Prefer filling bins far below the mean residual (imbalance correction)
    score -= ((mean_residual - post) * 0.15).max(-10.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual;
    if pr > 0 {
        if pr <= 5 {
            score += 120.0; // tiny dead space: worst outcome
        } else if pr <= 12 {
            score += 60.0;  // likely unusable for typical items
        } else if pr <= 25 {
            score += 15.0;  // marginal gap
        } else {
            score -= 5.0;   // large residual remains flexible
        }
    } else {
        score -= 80.0; // perfect fill: strongly reward
    }

    // Tight fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 40.0;
    } else if fill_ratio > 0.75 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 45.0;
        } else if slack <= 15 {
            score -= 20.0;
        }
    }
    // If next item would be blocked by a small gap, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual <= 12 {
        score += 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 + (mean_residual / 10.0).min(25.0) };
        score += pressure;
        // Early in the stream, prefer opening bins (future flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Mild alignment with mean residual: prefer bins below-average residual (tighter bins).
    score += ((post_residual as f64) - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fits (minimal dead space).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            let diff = pr - nxt;
            // Perfect chaining: next item fills this bin exactly afterward.
            if diff == 0.0 {
                score -= 400.0;
            } else {
                score -= 120.0 * (1.0 - diff / bin_capacity as f64);
            }
        } else {
            // Next item cannot use the leftover: penalize proportional dead space.
            score += 60.0 * (nxt - pr) / nxt.max(1.0) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0;

    // Penalize leaving many nearly-empty bins while a fresh one could absorb items.
    if open_bins_count > 4 && bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 18.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space: residuals too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slightly penalize hoarding capacity.
            let excess = (next_item_size - post_residual) as f64;
            score += 0.05 * excess;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64 + 1.0);
        let avg_fit_gap = mean_residual - item_size as f64;
        if avg_fit_gap < 5.0 {
            score -= 20.0; // open bins are tight; a fresh bin is fine
        } else {
            score += 15.0 + 0.3 * avg_fit_gap - 0.5 * crowding.min(20.0);
        }
        // Early in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Prefer filling bins that are already below mean residual (balance avoidance:
    // concentrate waste in fewer bins).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.08 * dev;
    }

    // Mild pressure to close out bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual (lower waste preferred)
    let mut score = pr;

    // Smooth polynomial coupling: residual waste penalized more as stream progresses
    let progress_sq = progress * progress;
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 30.0 * norm_pr * (1.0 - progress_sq);

    // Perfect/near-perfect fit reward (smooth exponential-like via polynomial)
    let fit_quality = 1.0 - norm_pr;
    score -= 25.0 * fit_quality * fit_quality * fit_quality;

    // Dead-space penalty: residuals too small for typical future items
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr < n {
            score += 15.0 * (n - pr) / cap * (0.5 + progress);
        } else {
            // reward leaving room for the lookahead item
            score -= 10.0 * (1.0 - (pr - n) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mild penalty for spreading across many open bins when residuals are already low
    let open_f = open_bins_count as f64;
    score += 0.5 * open_f * norm_pr;

    // Prefer filling bins below mean residual (consolidation)
    score += 0.2 * (pr - mean_residual);

    // New-bin candidate: penalize slightly so we prefer reusing unless fit is bad
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Perfect fit (or near-perfect) is highly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    }

    // Harmonic class thresholds: leftover space is only "usable" if it can hold
    // typical small items. Penalize dead space in bands: (0,10) great, [10,20) ok,
    // [20,40) weak, >=40 wasteful unless bin was nearly empty.
    if post_residual < 10 {
        score -= 200.0;
    } else if post_residual < 20 {
        score -= 60.0;
    } else if post_residual < 40 {
        score += 10.0;
    } else {
        score += 25.0;
    }

    // Modulo arithmetic: bins whose residual lands on multiples of common item
    // granularity (gcd-like classes of 5 and 10) pair well with future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 7.0;
    }

    // Integer division thresholds on next_item_size: can this bin also host the
    // lookahead item? If yes, strong bonus (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Extra bonus if after the next item the leftover again falls in a
        // small harmonic class (post2 residual class).
        let post2 = post_residual - next_item_size;
        if post2 < 10 {
            score -= 25.0;
        } else if post2 < 20 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize mildly, scaled by how much it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += (miss / 20.0).min(3.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is truly terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
        if post_residual < 10 {
            score -= 50.0;
        }
    }

    // New-bin candidate: residual == capacity. Only open a new bin when current
    // fit is poor (large post_residual) or stream is early and we want buffer.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 120.0;
        // Encourage opening early when few bins exist (build inventory of bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count == 0 {
            score -= 300.0;
        } else if progress < 0.3 {
            score -= 30.0;
        }
        // If the current bin's post-residual would be huge, new bin is attractive:
        // this is handled implicitly since open-bin scores carry that post_residual.
        // Slight discount when mean residual across bins is already low (bins full).
        if mean_residual < 15.0 {
            score -= 60.0;
        }
    }

    // Coupling with mean residual: prefer bins tighter than average (below-mean
    // residual means this bin is a "fuller" bin; fill the fullest first).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.5;

    // Mild pressure to close bins as stream progresses: penalize leaving many
    // open bins with medium residuals late in the stream.
    let late = step_index as f64 / (total_items.max(1) as f64);
    if late > 0.7 && post_residual >= 20 && post_residual < 40 {
        score += 20.0 * late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver given min item size 1..100; small gaps waste
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit is highly desirable
    }

    // Penalize post_residuals that can't fit the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }
    // Reward residuals that still accommodate the next item (keeps bin useful).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.20 * next_item_size as f64;
    }

    // Reward tight fits relative to residual (small waste fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: discourage spreading across many bins; favor filling existing.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when existing bins would leave bad gaps.
    if bin_residual == bin_capacity {
        score = 100.0 - 0.5 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: prefer filling bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (mean_residual - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with small slack left.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit in the residual: penalize dead space proportionally.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize leaving residuals below the smallest useful size (dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Slight preference for filling bins tighter than the current mean residual.
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize dead space, especially small unusable remnants.
    if post_residual > 0 {
        let dead = post_residual as f64;
        let unusable = if next_item_size > 0 { (next_item_size as f64 > dead) as f64 } else { 0.0 };
        score += 0.5 * dead + 25.0 * unusable * dead / bin_capacity as f64;
    } else {
        // Perfect fit: big reward.
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Time horizon: early in the stream, be conservative (keep residual space flexible);
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0 * (mean_residual / bin_capacity as f64);

    // Crowding penalty: with many open bins, discourage spreading items; encourage closing bins.
    score += 0.15 * open_bins_count as f64 * (1.0 - fill_ratio);

    // New-bin candidate handling: opening a new bin wastes capacity; make it unattractive
    // unless the item would leave a large unusable gap in every existing bin.
    if bin_residual == bin_capacity {
        let gap_elsewhere = mean_residual - item_size as f64;
        let desperate = if next_item_size > 0 && gap_elsewhere > 0.0 && (gap_elsewhere < next_item_size as f64) { 1.0 } else { 0.0 };
        score += 55.0 - 45.0 * desperate;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: prefer tight fits via non-linear post_residual coupling
    let mut score = pr + pr_norm * pr_norm * 40.0;

    // Smooth progress-based pressure: early on tolerate loose fits, later tighten
    let tightness = 1.0 + 3.0 * progress * progress;
    score *= tightness;

    // Reward filling bins nearly full (post_residual small), smooth quadratic reward
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * 30.0 * (0.5 + progress);

    // Last-chance bonus: only one bin fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when good fits exist
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 15.0 + 8.0 * openness.sqrt() + 20.0 * progress;
        // But if residual would leave huge dead space elsewhere, allow new bin
        if pr_norm > 0.7 {
            score -= 18.0 * (pr_norm - 0.7);
        }
    }

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let next_fit = next_item_size as f64 / cap;
        let gap = pr_norm - next_fit;
        if gap >= 0.0 {
            score -= 12.0 * gap * (1.0 - gap);
        } else {
            score += 6.0 * (-gap) * (1.0 + gap.abs());
        }
    }

    // Mean residual dispersion penalty: avoid deviating far from average residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (capacity fraction bands) ---
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap_f; // 0.0 .. 1.0

    // Dead-space penalty: residuals in (0, 10] are nearly unusable for items >=10,
    // but for general 1..100 streams treat small residuals as wasted.
    if post_residual <= 10 {
        score -= 25.0 * (1.0 - frac); // tiny residual = perfect packing, reward strongly
    } else if post_residual <= 20 {
        score -= 10.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    } else if post_residual > 70 {
        // Bin left mostly empty: poor fit, penalize
        score += 15.0;
    }

    // --- Modulo arithmetic on post_residual: harmonic residue classes ---
    // Residuals that are multiples of 10 pair cleanly with typical item sizes.
    let r = post_residual % 10;
    if r == 0 {
        score -= 3.0; // aligned residual
    } else if r >= 7 {
        score += 2.0; // awkward sliver class
    }

    // --- Next item lookahead: does the post residual still fit the next item? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual can host the next item: reward proportional to tightness
            let tight = 1.0 - (post_residual - next_item_size as u32) as f64 / cap_f;
            score -= 12.0 * tight;
        } else {
            // Next item won't fit here: penalize proportionally to the gap
            let gap = (next_item_size as u32 - post_residual) as f64;
            score += 0.3 * gap;
        }
        // Harmonic class of next item: large next items (>= 50) favor keeping
        // large residuals available; small next items tolerate fragmentation.
        if next_item_size >= 50 && post_residual < next_item_size as u32 {
            score += 8.0;
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit badly.
        // Base cost of a fresh bin plus bonus for large items.
        score = cap_f - 5.0 * (item_size as f64 / cap_f);
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative, must open
        }
        if post_residual == 0 {
            score -= 40.0; // perfect fit in a fresh bin
        }
    }

    // --- Stream progression: tighten packing as stream advances ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    // --- Mean residual coupling: prefer bins near the mean (balanced packing) ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<= 20) are nearly unusable
    // dead space, since items are >= 1 but typical distributions waste them.
    // Penalize hard when the leftover gap is small but nonzero.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 20 {
        score += (21.0 - pr) * 12.0; // smaller leftover => worse
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    } else {
        // Larger leftovers still mildly penalized, but less sharply.
        score += 0.0;
    }

    // Tightness reward: fraction of bin filled by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when many are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only allow a new bin if the residual we'd leave elsewhere is bad.
        score += 55.0 + open_bins_count as f64 * 3.0;
        // But if the item is huge relative to typical residuals, new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
    } else {
        // Slight reward for using existing bins as pressure builds.
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this placement (chain fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Late in the stream, be more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.05 * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact or near match with next item.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = pr - nr;
        if diff == 0.0 {
            // Perfect 2-step fit: this bin absorbs both items exactly.
            score -= 45.0;
        } else if diff > 0.0 {
            // Next item fits afterwards; reward closeness of the combined fit.
            let tightness = diff / bin_capacity as f64;
            score -= 25.0 * (1.0 - tightness);
        } else {
            // Next item won't fit here: penalize dead space relative to mean residual.
            let dead = -diff;
            score += 0.6 * dead;
            score += 0.8 * (pr - mean_residual).abs();
        }
        // If post_residual is unusably small (< min plausible item), penalize.
        if pr > 0.0 && pr < 10.0 {
            score += 20.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress;
        if open_bins_count > 0 {
            score += 5.0;
        }
    }

    // Mild preference for bins already below mean residual (balancing).
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Reward high fill ratio of the bin after placement.
    score -= 0.2 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Reward exact fills heavily.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Penalize dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
            // bonus proportional to how well next item fills the remaining space
            let next_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= (1.0 - next_tight) * 10.0;
        } else {
            score += 8.0; // leftover likely wasted
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin mildly unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual as f64 > item_size as f64 * 0.5 {
            // poor fit into an existing bin? then new bin is relatively attractive
            score -= 5.0;
        }
        // early in stream, opening bins is cheap; later, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Prefer bins with residual far from mean residual (use lumpy bins first).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.3;

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.5 * (bin_residual as f64 / bin_capacity as f64);

    // Favor fuller bins (smaller residual) slightly beyond baseline.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual, mildly compressed at large residuals.
    let mut score = pr * (1.0 + 0.35 * (pr / cap).powi(2));

    // Smooth non-linear coupling of residual waste with stream progress:
    // late in the stream, tight fits matter more.
    score -= 18.0 * (pr / cap) * (1.0 - (pr / cap)) * (progress * (2.0 - progress));

    // Perfect-fit reward, sharpened smoothly.
    score -= 25.0 * (1.0 - (pr / cap).powi(4)) * (1.0 - (pr / cap).powi(4));

    // Lookahead: reward residual that can host the next item (smooth kernel).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit = (pr - n).abs() / cap;
        score -= 12.0 * (-6.0 * fit * fit).exp();
    }

    // Penalize when many bins fit the item (weak differentiation needed),
    // reward scarcity of fitting bins (last-chance placement).
    if fitting_bins_count > 0 {
        score -= 8.0 / fitting_bins_count as f64;
    }
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: neutral-ish baseline, mildly discouraged early,
    // acceptable late or when open-bin residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = ((mean_residual - cap * 0.5) / cap).powi(2);
        score = cap as f64 * (0.55 - 0.25 * progress) + 30.0 * fragmentation * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the leftover space: leftovers that form "nice" fractions
    // of capacity (multiples of 10, 20, 25, 50) are more reusable.
    let nice = |r: u32| -> f64 {
        let r = r as f64;
        if r == 0.0 { return -40.0; } // perfect fit is ideal
        if r % 50 == 0 { -12.0 }
        else if r % 25 == 0 { -8.0 }
        else if r % 20 == 0 { -6.0 }
        else if r % 10 == 0 { -4.0 }
        else if r % 5 == 0 { -2.0 }
        else { 0.0 }
    };
    score += nice(post_residual);

    // Penalize tiny dead space (< 10, likely unusable for items >= 1 but
    // fragmenting): scale harshly for very small nonzero leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: strong reward, scaled by how well it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 + 10.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 4.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    } else {
        // last item: just minimize leftover
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // fits decently. Make the empty-bin score track the mean residual pressure.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.6;
        // cheaper to open a new bin when open bins are already quite full on average
        score -= 0.3 * mean_residual;
        // more expensive when many bins are already open (avoid bin proliferation)
        score += 2.0 * open_bins_count as f64;
        // if we're the only fitting option anyway, opening is acceptable
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // late in the stream, avoid opening new bins
        score += 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild preference for tighter bins overall (waste-awareness)
    score += 0.05 * (mean_residual - post_residual as f64).abs() * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Residuals that are too small to hold even the smallest plausible item (1..10)
    // are "dead space": penalize them super-linearly.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Small-but-usable gaps: mild quadratic penalty to prefer filling bins fully
    // while not punishing exact fits.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * (20 - post_residual) as f64 * 0.15;
    }

    // --- Reward tight fits (low post_residual relative to item size) ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Reward proportionally tight placement.
        score -= (item_size as f64 / post_residual as f64) * 10.0 * (0.5 + fill_ratio);
    }

    // --- Lookahead: keep room for the next item if it would otherwise not fit anywhere ---
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This placement strands the next item; penalize unless it was a near-perfect fit.
        score += 15.0 * (1.0 - fill_ratio);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving a usable gap for the lookahead item.
        score -= 6.0;
    }

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that fits; strongly prefer using it over opening a new bin.
        score -= 40.0;
    }

    // --- Open-bin pressure: when many bins are open, discourage spreading ---
    let open_pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure so we only open when fits are poor.
        score = bin_capacity as f64 + 25.0 + open_pressure * 10.0;
        // Allow opening if all current fits are bad (fitting bins few and residuals tight).
        if fitting_bins_count == 0 {
            score -= 1000.0; // no alternative: must open
        }
        // Slight discount late in stream to consolidate less.
        score -= (step_index as f64 / total_items.max(1) as f64) * 5.0;
    } else {
        // Mild penalty scaled by number of open bins to favor consolidation.
        score += open_pressure * 2.0;
        // Prefer bins with below-mean residual (filling emptier bins first keeps
        // tighter bins available for small items).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        // Perfect match bonus: item exactly fills space next item needs.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space smaller than next item (unusable wedge).
        if post_residual < next_item_size {
            score += 12.0 * (1.0 - post_residual as f64 / nxt);
        }
    } else {
        // Last item: prefer tightest fit.
        score += 20.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Relative-to-mean coupling: prefer bins with residuals near the mean
    // (balanced packing), avoid extreme residuals unless tight fit.
    score += 0.6 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize very small post-residuals (dead space) unless it's zero.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    // Reward perfect closure.
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are bad.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        let tightness = 1.0 / (post_residual as f64).sqrt();
        score -= 40.0 * tightness;
        // Penalize dead space that cannot hold the smallest plausible item.
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= 60.0 / (1.0 + waste as f64);
        } else {
            // Next item won't fit here anyway; slight reward for leaving large gap.
            score += 10.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // Last item of the stream: any bin that fits is fine, prefer tight fit.
        score -= 80.0;
    }

    // Prefer bins whose residual is already below mean (consolidating fullness),
    // but avoid dumping into nearly-empty bins when many bins are open.
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    if residual_frac < mean_residual / bin_capacity as f64 {
        score -= 30.0 * (mean_residual / bin_capacity as f64 - residual_frac);
    } else {
        score += 20.0 * (residual_frac - mean_residual / bin_capacity as f64);
    }

    // Time horizon: early in the stream, be pickier (keep space flexible);
    // late in the stream, prioritize closing out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (1.0 - residual_frac);

    // When many bins are open, discourage opening new ones; the new-bin candidate
    // (bin_residual == bin_capacity) gets penalized with open bin count.
    if bin_residual == bin_capacity {
        score += 90.0 + 15.0 * open_bins_count as f64;
        // Unless the item is huge relative to capacity and fits nowhere well.
        if item_size as f64 > 0.8 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 250.0;
        }
    }

    // Mild tie-break: prefer bins with more residual headroom overall.
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer tight fits (small post_residual), with a mild non-linear
    // reward so very small post_residual is disproportionately favored.
    let mut score = post + 8.0 * (post / cap).powi(3);

    // Smooth stream-progress coupling: later in the stream, dead space
    // matters more, so scale the base term with a smooth ramp.
    score *= 1.0 + 0.5 * progress * progress;

    // Interaction with mean residual: if this bin is already far below the
    // mean residual, it's "wasted" space being consumed; slight reward.
    score -= 0.05 * (mean_residual - post).max(0.0);

    // Next-item lookahead: penalize post_residuals that cannot host the
    // next item (dead space), reward ones that can.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 2.0 * (nxt - post) * (1.0 - progress);
        } else {
            score -= 1.5 * (1.0 - (post - nxt) / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly reward using the only bin that fits,
    // otherwise this item opens a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral-ish score so it wins only when all open
    // bins are poor fits. Scale mildly with open_bins_count to discourage
    // bin proliferation early on.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.02 * open_bins_count as f64) * (1.0 - 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residue modulo 10 as a "waste class"
    let pr = post_residual;
    let residue_class = (pr % 10) as f64;
    // Penalize residuals that are not multiples of 10 (dead space unlikely to be filled)
    if pr > 0 {
        score += residue_class * 0.8;
    }

    // Integer-division thresholds: classify post_residual into capacity fraction buckets
    let quarter = bin_capacity / 4;
    if pr < quarter / 2 && pr > 0 {
        // tiny dead space: strongly penalize unless it's a perfect multiple of 5
        score += if pr % 5 == 0 { 2.0 } else { 12.0 };
    } else if pr >= quarter && pr < bin_capacity / 2 {
        // mid-range residual: mild reward, good future capacity
        score -= 4.0;
    } else if pr >= bin_capacity / 2 {
        // large residual: reward, keeps flexibility
        score -= 8.0;
    }

    // Exact fit bonus (post_residual == 0)
    if pr == 0 {
        score -= 40.0;
    }

    // Harmonic coupling with next item: reward if next_item_size divides into post_residual exactly
    if next_item_size > 0 && pr >= next_item_size {
        if pr % next_item_size.max(1) == 0 {
            score -= 15.0;
        } else {
            // next item fits but leaves awkward class
            let next_class = ((pr - next_item_size) % 10) as f64;
            score += next_class * 0.4;
            score -= 3.0;
        }
    } else if next_item_size > 0 && pr < next_item_size && pr > 0 {
        // next item cannot use this residual: penalize proportional to waste
        score += (next_item_size - pr) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor fits
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base cost of opening a bin
        score += 55.0;
        // allow new bin when few fitting bins or stream is early
        score -= pressure * 60.0;
        score -= (1.0 - progress) * 10.0;
        // if mean residual is large, discourage new bin
        score += (mean_residual / cap).clamp(0.0, 1.0) * 20.0;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=12) are almost certainly unusable
    // by future items (min size 10). Penalize them hard beyond their raw value.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 * (13 - post_residual as i32) as f64;
    } else if post_residual > 12 && post_residual < 20 {
        // Medium-small gaps are risky too
        score += 12.0;
    }

    // Reward very tight fits (post_residual 0 is perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin;
    // if post-residual is smaller than next item but nonzero, it's dead space for k=2.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 15.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids wasting this bin's residual forever).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has residual == capacity, gets penalized here).
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * open_bins_count as f64;
        // But if nothing fits well elsewhere (many dead gaps), new bin is fine:
        if mean_residual < 10.0 && open_bins_count > 0 {
            score -= 20.0;
        }
    }

    // Mild global preference to keep residuals balanced early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * (post_residual as f64 - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect lookahead: next item fits with little slack left.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: penalize proportionally to wasted residual.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward small post_residual (tight packing) non-linearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score -= 20.0 * (1.0 - pr / cap).powi(4);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins whose residual is far below the mean (wasted space elsewhere).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // New empty bin candidate: discourage unless it's genuinely useful.
    if bin_residual == bin_capacity {
        score += 40.0;
        // A new bin is attractive if current item is large and lookahead also large.
        if item_size as f64 > 0.6 * cap && next_item_size as f64 > 0.5 * cap {
            score -= 55.0;
        }
    }

    // Early in the stream, allow more bins for flexibility; late, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual preferred).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable sliver is wasted capacity
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.15 * slack.min(40.0);
        } else {
            score += 6.0;
            // Perfect chain fit is ideal.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let penalty = 45.0 - 20.0 * progress - crowded.min(30.0);
        score += penalty.max(5.0);
    }

    // Prefer bins with below-average residual (consolidate emptier space usage).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.10 * dev;

    // Mild time pressure: late in the stream, be more conservative (favor exact fills).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, waste becomes more costly (convex penalty).
    let waste_weight = 1.0 + 2.0 * progress * progress;
    score += (pr / cap) * pr * 0.5 * waste_weight;

    // Dead-space penalty: post_residual too small for the lookahead item is waste.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            // smooth quadratic penalty for unusable remainder, softened early in stream
            let gap = ns - pr;
            score += gap * gap * (0.02 + 0.05 * progress);
        } else {
            // reward leaving room exactly usable by the next item (smooth bump)
            let fit_quality = 1.0 - ((pr - ns) / cap).min(1.0);
            score -= 6.0 * fit_quality * fit_quality * (1.0 - progress * 0.5);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 2 {
        // many alternatives: mild penalty to prefer tightest / avoid scattering
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Prefer bins with below-average residual (consolidate waste).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // New-bin candidate: make it attractive only when current bins fit poorly
    // (large post_residual everywhere) or stream is very early.
    if bin_residual == bin_capacity {
        let avg_waste = pr; // = capacity for empty bin
        let poor_fit_pressure = ((mean_residual / cap) - (item_size as f64 / cap)).max(0.0);
        let openness = (open_bins_count as f64).ln().max(1.0);
        score = pr * (0.9 - 0.4 * progress)
            - 20.0 * (1.0 - progress) * (1.0 - progress)
            + 25.0 * openness * (1.0 - poor_fit_pressure * 2.0).max(0.0)
            + if next_item_size > 0 { (next_item_size as f64 - pr).abs() * 0.1 } else { 0.0 };
        let _ = avg_waste;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (integer division into capacity fractions) ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post_residual * 4) / bin_capacity.max(1); // 0..3 harmonic class of leftover
    match class {
        0 => score -= 8.0,              // leftover < 25% of capacity: near-perfect fill
        1 => score -= 2.0,              // 25-50%: decent
        2 => score += 1.5,              // 50-75%: wasteful
        _ => score += 4.0,              // >75% left: barely used the bin
    }

    // Exact-fill bonus: zero dead space is gold
    if post_residual == 0 {
        score -= 25.0;
    }

    // Modulo arithmetic: leftover divisible into small common item sizes is reusable
    let reusable = |r: u32| -> f64 {
        let mut bonus = 0.0;
        for m in [10u32, 20, 25, 30, 40, 50] {
            if r >= m && r % m == 0 {
                bonus += 3.0;
            }
        }
        bonus
    };
    score -= reusable(post_residual);

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        if post_residual % next_item_size == 0 {
            score -= 5.0; // next item tiles the leftover perfectly
        }
        if post_residual - next_item_size <= 10 {
            score -= 3.0; // chain-fill toward a tight bin
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's leftover: penalize dead space proportionally
        score += (post / cap) * 3.0;
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        let crowded = mean_residual / cap < 0.35 || open_bins_count == 0;
        if crowded {
            score -= 4.0 + 3.0 * progress; // open fresh bins when residuals are low
        } else {
            score += 15.0; // discourage opening new bins when existing space is usable
        }
    }

    // Mild pressure to consolidate: prefer bins below mean residual (tighter bins)
    score += ((mean_residual - post) / cap) * 2.0;

    // Small tie-break favoring earlier-decayed bins as stream progresses
    score += 0.01 * (step_index % 7) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // future item (min size 1, but practically small gaps < ~10) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver: heavy penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill: strongly favored
    }

    // Reward tight fits (small relative post_residual) with non-linear coupling.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Open-bin pressure: discourage scattering across many bins unless the fit is tight.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this placement;
    // if next item would be stranded by a small gap, penalize.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 12.0;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Mean-residual coupling: bins far below the mean residual are more valuable to fill.
    score -= 0.10 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make opening a new bin mildly attractive only when the
    // current bin would leave a large, awkward residual and many bins are open.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; overcome only by the penalties above on bad fits.
        score += 15.0 + 0.5 * open_bins_count as f64;
    }

    // Late-stream tightening: as the stream progresses, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already base score).
    // Strong reward when the next item fits exactly into the post-residual (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - 0.5 * slack; // exact match (slack=0) gets biggest bonus
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize dead space creation
        score += 10.0 + 0.3 * (next_item_size as f64);
    }

    // Penalize bins far below mean residual (wasting large residual elsewhere is worse)
    score += 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discourage opening new bins early in the stream unless residual is tiny
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let threshold = 8.0 + 4.0 * progress;
        if post_residual as f64 > threshold {
            score += 60.0; // too much fresh space wasted -> prefer open bins
        } else {
            score -= 5.0; // small item, fresh bin is fine
        }
    }

    // Mild penalty for fragmenting large residual bins with tiny items
    if item_size < 20 && post_residual > 60 && bin_residual < bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more strongly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize dead space that is too small for likely future items.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && post_residual < next_item_size {
            (next_item_size - post_residual) as f64
        } else {
            0.0
        };
        score += dead * 0.6;
    }

    // Lookahead: favor bins whose post-residual can hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Extra reward if this bin could hold both chained items.
        if bin_residual >= item_size + next_item_size {
            score -= 3.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0; // fragmenting against the known future item
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill * open_bins_count as f64 * 0.5;

    // Time horizon: early in the stream, tolerate opening new bins; late, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses or mean residual is large.
        score += 10.0 + progress * 20.0 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 2.0;
        }
    } else {
        // Late in the stream, reward using existing space harder.
        score -= progress * 5.0;
    }

    // Mild preference for bins below mean residual (balance avoidance of waste).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: post residual (waste), scaled
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: tolerate moderate residuals; late: strongly penalize large residuals.
    let prn = pr / cap; // normalized post residual in [0,1]
    let w = 1.0 + 2.0 * progress * progress; // smooth ramp
    score += w * cap * prn * prn;

    // Reward tight fits (small post residual) with smooth quadratic bonus
    let tightness = 1.0 - prn;
    score -= 0.5 * cap * tightness * tightness * tightness;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits exactly in post residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 20.0 * (1.0 - gap / cap) - 0.1 * gap;
        } else {
            // next item cannot use residual: mild penalty proportional to residual
            score += 0.05 * pr * (0.5 + progress);
        }
    }

    // Dead-space penalty: residual too small for smallest plausible item
    if pr > 0.0 && pr < 10.0 {
        score += 2.0 * (10.0 - pr);
    }

    // Prefer bins below mean residual when many bins open (balance residuals)
    let mean_gap = (pr - mean_residual) / cap;
    score += 3.0 * mean_gap * mean_gap * cap * (open_bins_count as f64).ln().max(1.0) * 0.1;

    // New-bin candidate: keep it competitive only when current bin fit is bad
    if bin_residual == bin_capacity {
        score = 0.6 * cap + 0.4 * pr + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Harmonic class of post_residual: mod-10 classes matter for capacity 100.
    let class = post_residual % 10;
    // Dead-space penalty for small nonzero residuals (unusable fragments).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else {
        // Reward residuals that are "harmonically useful": multiples of 10 or 25.
        if post_residual % 25 == 0 {
            score -= 12.0;
        }
        if class == 0 {
            score -= 8.0;
        }
    }

    // Integer division thresholds: residual buckets.
    let bucket = post_residual / 20; // 0..=5
    score += bucket as f64 * 3.0;

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Prefer leaving room for the next item; reward closeness of fit.
            score -= 15.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize large leftover a bit.
            score += 6.0;
        }
    }

    // Last-chance bin: avoid opening a new bin if this fit is decent.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 3 {
        score -= 30.0;
    } else if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity && item_size > 0 {
        // Penalize new bins mildly when many bins are open and mean residual is healthy.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let healthy = mean_residual >= item_size as f64 + 10.0;
        if open_bins_count > 0 && healthy {
            score += 45.0 + 20.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
        // New bin wastes capacity equal to C - item_size; reflect that.
        score += (bin_capacity - item_size) as f64 * 0.3;
    }

    // Coupling with mean residual: prefer bins below mean (tighter packing).
    score += ((mean_residual - post_residual as f64).abs()) * 0.2;

    // Slight preference for filling fuller bins early in the stream.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 10.0 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible future item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Small-but-usable residuals are risky too: penalize if they cannot fit the
    // lookahead item, since the next item likely won't fit either.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward tight fits (small post_residual in the usable range).
    if post_residual >= 10 {
        score -= 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins over opening new ones; penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 0.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual is already below average (they are "nearly full"
    // and should be finished off rather than left as fragmented stragglers).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Early in the stream, be slightly more willing to open fresh bins for good
    // structure; later, squeeze everything into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward if the next item fits in the post residual ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect match: next item exactly fills leftover space
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 40.0 + 25.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize dead space creation
            score += 15.0 + 0.35 * post_residual as f64;
        }
    }

    // --- Relative-to-mean-residual adjustment ---
    if mean_residual > 0.0 {
        // Bins tighter than the mean are preferred (less fragmentation overall)
        let rel = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 8.0 * rel;
    }

    // --- Last-chance bonus: only bin that fits -> avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; discourage when an existing bin has a great fit
        score = bin_capacity as f64 - 10.0;
        if next_item_size > 0 && item_size >= next_item_size {
            // opening fresh helps if current item is large and next is smaller
            score -= 6.0;
        }
        if fitting_bins_count <= 1 {
            // no real alternative: make new bin attractive
            score -= 25.0;
        }
    }

    // --- Early stream: be slightly more conservative with open bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: fraction of bin consumed by this item.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item (min size 1) can plausibly use:
    // small post_residual is good if it's tiny (perfect fit) or large (still usable).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 8.0 * (10.0 - pr); // awkward sliver
    }

    // Lookahead: reward if next item fits in post_residual (chaining),
    // penalize if next item would be blocked.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // extra reward for near-exact pair packing
            let slack = post_residual - next_item_size;
            if slack < 5 {
                score -= 6.0;
            }
        } else {
            score += 5.0 + 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing bins are crowded (high mean residual relative to item) or few fit.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        let pressure = (item_size as f64 / bin_capacity as f64).max(crowded);
        score += 30.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    } else {
        // Prefer bins with residual closest to item (best-fit flavor),
        // modulated by global mean residual.
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.3 * gap;
        if (bin_residual as f64) < mean_residual {
            score -= 4.0; // favor tighter-than-average bins
        }
    }

    // Mild penalty for proliferation of open bins when many fit options exist.
    if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: post-residual with smooth non-linear shaping
    let mut score = pr + 12.0 * pr_norm * pr_norm;

    // Polynomial coupling of residual with stream progress:
    // early on, prefer filling bins fully (low post-residual weighted more);
    // later, residual waste matters even more quadratically.
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress) * 30.0;
    score += coupling;

    // Smooth reward for tight fits (small post_residual relative to item)
    let tightness = 1.0 - pr / (bin_residual.max(1) as f64);
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving residual that can fit next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let fit_quality = (ns / cap) * (1.0 - pr_norm);
            score -= 10.0 * fit_quality;
        } else {
            // penalize residuals too small for next item proportionally
            score += 6.0 * (ns - pr) / cap * (1.0 + progress);
        }
    }

    // Mild penalty for spreading across many open bins when residuals are large
    let mean_norm = mean_residual / cap;
    score += 0.5 * open_bins_count as f64 * mean_norm * mean_norm;

    // New-bin candidate: make empty bin attractive only when it's genuinely better
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress) - 5.0 * mean_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals are valuable insofar as they
    // can host future items. Class 0: dead space (< 10 or 1..=9 units) -> heavily penalized.
    // Class boundaries at capacity fractions: 1/4, 1/2, 3/4 of C=100.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * bin_capacity / 4;

    if post_residual == 0 {
        // Perfect fit: strongest reward.
        score -= 200.0;
    } else if post_residual < 10 {
        // Dead space class: unusable sliver.
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else {
        // Usable residual: reward proportional to its harmonic class.
        // Larger usable residuals are more flexible, but we still prefer tight fits.
        let class = if post_residual <= quarter {
            0.0
        } else if post_residual <= half {
            1.0
        } else if post_residual <= three_quarter {
            2.0
        } else {
            3.0
        };
        // Higher class (more room left) gets a mild bonus, scaled by class value.
        score -= 8.0 * class;
    }

    // Modulo-arithmetic coupling: residual that is an exact multiple of small
    // harmonics (5, 10, 20) tends to tile well with typical item sizes.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0;
        } else if pr % 5 == 0 {
            score -= 6.0;
        }
        // Penalize awkward primes / odd residues.
        if pr % 2 == 1 && pr < 30 {
            score += 5.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward, more so the tighter.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.5;
        } else {
            // Next item does not fit this residual: penalize if residual is small-ish
            // (it will likely be stranded).
            if post_residual < next_item_size && post_residual < quarter {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it a
    // moderate fallback. It should win only when all open bins give bad fits.
    if bin_residual == bin_capacity {
        // Baseline for opening a fresh bin: neutral-ish, slightly above a good fit.
        score = 70.0 + (open_bins_count as f64).ln().max(0.0) * 5.0;
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 20.0;
        }
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= half {
            score -= 15.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins whose residual is already below average (they are "used up").
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 12) are effectively dead space.
    if post_residual < 12 {
        score += 60.0 - 5.0 * post_residual as f64; // 60..15 penalty for gaps 0..11
    }

    // Penalize residuals just above a mid-size item threshold that leave
    // awkward gaps (wasted capacity the next item likely cannot use).
    if post_residual > 0 && post_residual < 25 {
        score += 0.6 * (25 - post_residual) as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // next item cannot use this gap -> mild dead-space penalty
            score += 4.0;
        }
    }

    // Open bins pressure: discourage opening new bins when many bins are open
    // and this bin fits reasonably well.
    if bin_residual != bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 2.0 + 3.0 * progress + 0.15 * open_bins_count as f64;
    } else {
        // New bin candidate: apply a fixed opening cost so it only wins when
        // fits into open bins are bad (their dead-space penalties dominate).
        score += 25.0 + 0.5 * open_bins_count as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (tighter bins get closed out sooner).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: strongly reward when next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward tight two-item packing: subtract more when leftover after next item is small
            score -= 60.0 + 2.0 * (item_size as f64) - 0.5 * slack;
            if slack == 0.0 {
                score -= 500.0; // exact two-item fill
            }
        } else {
            // next item won't fit here: penalize dead space proportionally to how unusable it is
            let dead = post_residual as f64;
            let usable = if dead >= 10.0 { dead } else { dead * 3.0 };
            score += 0.3 * usable;
            // if post_residual is very small, it's near-perfect for future tiny items; mild reward
            if post_residual < 10 {
                score -= 20.0;
            }
        }
    }

    // Compare against mean residual: prefer bins with residual close to (item + next) demand
    let demand = item_size as f64 + next_item_size as f64;
    let gap = (mean_residual - demand).abs();
    score += 0.2 * gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Prefer filling bins that are already quite full (small bin_residual before placement)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Early in stream: be less aggressive about opening new bins; late: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty when many bins are open: encourage consolidation
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score as fill ratio increases.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    // Penalize small unusable post-residuals (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits in the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 {
            // Next item won't fit here; penalize wasted residual slightly.
            score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
        // Extra reward for perfect chaining: next item fills exactly.
        if next_item_size == post_residual && post_residual > 0 {
            score -= 15.0;
        }
    }

    // Last chance: strongly favor using this bin instead of opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (mean_residual / bin_capacity as f64) < 1.0;
        let poor_fit = fill_ratio < 0.5;
        score += 30.0;
        if crowded && poor_fit {
            score -= 45.0;
        }
        // Early in stream, opening bins is cheap; late, avoid fragmentation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Global residual pressure: many open bins with high mean residual -> prefer
    // consolidating into bins with below-average residual.
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Slight preference to keep few open bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: post residual (larger leftover = lower priority since score minimized -> actually
    // we want tight fits, so reward small post_residual by starting from it and subtracting).
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, keep bins flexible (penalize very small leftovers mildly),
    // late, prefer tight packing strongly.
    let tightness = 1.0 - post_norm; // 1.0 = perfect fit
    let poly = tightness * tightness * (1.0 + 3.0 * progress) - 0.5 * post_norm * post_norm * (1.0 - progress);
    score -= 12.0 * poly;

    // Dead-space penalty: tiny unusable leftovers are bad, worse late in stream.
    let dead = if post > 0.0 && post < 10.0 { (10.0 - post) / 10.0 } else { 0.0 };
    score += 8.0 * dead * (0.5 + progress);

    // Last-chance bin bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * post_norm);
    }

    // Lookahead: reward if next item fits into post_residual (chain packing).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 6.0 * (nx / cap) * (1.0 + progress);
        } else {
            score += 2.0 * (1.0 - post / nx.max(1.0)) * progress;
        }
    }

    // Prefer bins below mean residual slightly (balance load), smooth quadratic coupling.
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0) * (0.3 + 0.7 * progress);

    // New-bin candidate: mildly penalize opening a new bin unless post residual is large
    // and few bins are open (spread early, consolidate late).
    if bin_residual == bin_capacity {
        let spread_bonus = (post_norm - 0.2) * (1.0 - progress) * 10.0
            - (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;
        score += 5.0 - spread_bonus.max(-5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual (already the seed).

    // Harmonic class of post_residual modulo capacity fractions.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;

    // Dead-space penalty: residuals that are too small to hold the
    // smallest plausible item are nearly worthless.
    let min_item = 1u32;
    if pr < min_item.max(1) {
        score += 0.0; // exact fit, perfect
    }
    if pr > 0 && pr < 10 {
        // tiny sliver: mostly dead space
        score += 12.0 * (10 - pr) as f64 / 10.0;
    }

    // Modulo harmonic classes: residuals near multiples of common
    // item-friendly sizes are more reusable.
    let class = pr % 25;
    score += match class {
        0 => -6.0,              // exact quarter-class: very reusable
        1..=5 => -2.0,          // near class boundary
        20..=24 => -2.0,
        _ => (class as f64) * 0.15, // mid-class: mild penalty
    };

    // Integer division threshold: how many "typical" items still fit.
    let slots = pr / 25;
    score -= 3.0 * slots as f64;

    // Perfect fit reward.
    if pr == 0 {
        score -= 50.0;
    } else if pr <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 8.0;
        // Harmonic bonus if next item exactly divides remaining space.
        if pr % next_item_size == 0 {
            score -= 6.0;
        }
    } else if next_item_size > pr {
        // Next item won't fit here: residual becomes dead space for lookahead.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin should only win when
    // this bin's fit is poor. Penalize fresh bin moderately; scale by
    // stream progress and current open-bin pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - progress);
        // But if mean residual across open bins is tiny (all bins tight),
        // a new bin is genuinely attractive.
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    }

    // Crowding: many open bins -> prefer consolidating into existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual alignment: prefer bins whose post_residual lands
    // near the fleet mean (keeps residual distribution coherent).
    score -= 2.0 * (-((post_residual as f64 - mean_residual) / 20.0).powi(2));

    // Half/third capacity harmonic thresholds.
    if pr == half || pr == third || pr == quarter {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold any
    // plausible future item are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += (12.0 - post_residual as f64) * 6.0; // unusable sliver penalty
    }

    // Reward tight fits (small usable residual) mildly.
    score -= (bin_residual - post_residual) as f64 * 0.35;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is close to the mean residual (balance),
    // slightly damped over stream progression.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 - mean_residual).abs() * (0.3 - 0.15 * progress);

    // Lookahead: if next item fits exactly into the post residual, reward;
    // if post residual is smaller than next item but nonzero, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or all existing fits would leave big dead space.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 8.0 + 20.0 * tightness;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual as i64 >= next_item_size as i64 {
            // next item fits exactly or near-exactly after this placement
            if gap <= 5 {
                score -= 150.0 - gap as f64 * 10.0;
            } else {
                score -= 30.0 - gap as f64 * 0.3;
            }
        } else {
            // next item will NOT fit in this bin afterwards -> penalize proportionally
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Tightness reward: small post_residual relative to mean residual is good
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when good open options exist
    if bin_residual == bin_capacity {
        score += 40.0;
        // opening a new bin is more attractive early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // new bin attractive if open bins are fragmented
        score -= mean_residual * 0.1;
    }

    // Mild penalty for leaving tiny dead space (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Favor fuller bins overall
    score += (bin_capacity as f64 - bin_residual as f64) * (-0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: penalize residuals that cannot host the next item,
    // scaled by how "wasted" the dead space is.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            let waste = (next_item_size - post_residual) as f64;
            score += 0.8 * waste;
        } else {
            // Residual can host next item: reward proportionally to snugness.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 0.5 * snug * post_residual as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize tiny unusable slivers (dead space below minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Global state: when many bins are open, prefer consolidating into
    // bins with below-average residual (fill the emptier ones less).
    if open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Time horizon: early in the stream, be more liberal about opening bins
    // (keep residuals large for future items); late, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.2 * post_residual as f64;

    // New-bin candidate: default cost, discounted when item is large or
    // stream is early (preserving flexibility), raised when many bins exist.
    if bin_residual == bin_capacity {
        score = 0.9 * bin_capacity as f64
            - 0.3 * item_size as f64
            + (1.0 - progress) * 20.0
            + 2.0 * open_bins_count as f64;
        // If only this new bin fits, it must be chosen anyway.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize leftover space with a non-linear (quadratic) dead-space term.
    let mut score = post + 0.010 * post * post / cap;

    // Reward tight fits: normalized fill ratio, smooth cubic coupling with progress.
    let tightness = 1.0 - (post / cap);
    score -= 6.0 * tightness * tightness * tightness * (0.5 + progress);

    // Exact fit gets a strong smooth bonus.
    if post_residual == 0 {
        score -= 10.0 * (0.6 + 0.4 * progress);
    }

    // Penalize bins whose residual is far below the mean (wasting scarce space elsewhere).
    score += 0.05 * (mean_residual - post).max(0.0);

    // Last-chance bin: strong smooth discount to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 * (1.0 - progress) + 2.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post - next_item_size as f64;
        score -= 3.0 * (1.0 - gap / cap) * (0.5 + 0.5 * progress);
    } else if next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving a residual too small to matter.
        score += 0.8 * (post / cap) * (1.0 - progress);
    }

    // New-bin candidate: keep it neutral-ish early, penalize later so we prefer packing.
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * progress + 0.3 * open_bins_count as f64;
    }

    // Mild congestion pressure: many open bins favors consolidation.
    score += 0.02 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals that are multiples of common
    // item sizes are "usable" and should be rewarded (score reduced).
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let common: [u32; 8] = [10, 20, 25, 30, 40, 50, 60, 80];
    let mut usable_bonus = 0.0;
    for &c in common.iter() {
        if pr >= c && pr % c == 0 {
            usable_bonus += 8.0 * (pr as f64 / c as f64).ln().max(1.0);
        }
    }
    score -= usable_bonus;

    // Integer-division dead-space class: post_residual in awkward bands
    // (small leftovers that nothing in [1,100] reliably fills) are penalized.
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr >= 10 && pr <= 15 {
        score += 6.0;
    }

    // Capacity fraction coupling: exact quarter/half fills are harmonically good.
    let fill = (bin_capacity - pr) as f64 / cap;
    if (fill * 4.0).round() / 4.0 == fill {
        score -= 12.0;
    }

    // Lookahead harmony: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // perfect closure
        } else if next_item_size < pr {
            score -= 10.0 * (next_item_size as f64 / pr as f64);
            if pr % next_item_size == 0 {
                score -= 10.0; // divisible residual
            }
        } else {
            score += 8.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // but allow it late in stream or when many bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * (1.0 - progress) - 0.5 * open_bins_count as f64;
        if mean_residual < 20.0 {
            score -= 10.0; // existing bins are fragmented; fresh bin attractive
        }
    }

    // Mild preference for tighter bins overall.
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // unusable gap
    } else if post_residual < 20 && post_residual > 0 {
        score += 12.0; // near-dead gap
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else {
        // Reward placements that leave a still-usable, well-shaped gap
        score -= 6.0 * ((post_residual as f64) / 100.0);
    }

    // Tight fit reward: item occupies a large fraction of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 18.0 * fill_ratio;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation
    score += 0.35 * open_bins_count as f64;

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item barely misses the post-residual but would fit a fresh bin, mild penalty
    if next_item_size > post_residual && next_item_size > bin_residual {
        score += 4.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high; only chosen when open bins score badly
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
        // late in stream, opening new bins is fine
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits leaving very small dead space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 25.0 - (slack as f64) * 4.0;
        }
    }
    // Next item does NOT fit in the leftover: the residual becomes pure dead space
    // relative to the lookahead, penalize proportionally to how "wasted" it is.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let usable = post_residual as f64 / next_item_size as f64;
        score += (1.0 - usable) * 15.0;
    }

    // Penalize large residuals relative to the fleet mean (dead space hoarding).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;
    // Reward bins already below mean residual (they are tight, keep filling them).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.2;

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins would leave very bad fits
    // (large post_residual with no useful lookahead match) or fleet is very tight.
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 25.0 };
        score += 10.0 + bad_fit_penalty - (open_bins_count as f64) * 0.5;
    }

    // Late in the stream, prioritize closing bins tightly (small post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where post residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this residual; penalize proportionally to wasted gap.
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 - progress);
    score += 3.0 * pressure;

    // Deviation from mean residual: prefer bins whose residual is close to mean
    // (keeps residual distribution balanced) unless it is a near-perfect fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // offers a good fit, or when the item is huge relative to mean residual.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let empty_penalty = 55.0
            - (item_size as f64 / bin_capacity as f64) * 40.0
            - pressure * 5.0
            - if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        score += empty_penalty.max(-10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted residual, modulated by stream progress
    let mut score = pr * (1.0 + 1.5 * norm_pr * (0.5 + progress));

    // Smooth coupling: prefer small post-residuals more strongly late in the stream
    score += 20.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits (near-zero post residual) with a smooth saturating bonus
    let tight = (-norm_pr * 6.0).exp();
    score -= 15.0 * tight * (0.3 + 0.7 * progress);

    // Lookahead: penalize if the next item cannot use the resulting residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 8.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            score -= 4.0 * (1.0 - ((pr - nx) / cap)) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr * 0.5);
    }

    // Mild preference for consolidating into fewer bins as stream progresses
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;

    // Penalize bins far from mean residual (fragmentation avoidance), smooth quadratic
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity fractions (quarters). Small classes are "dead space" -> penalize.
    let q = (post_residual * 4) / bin_capacity; // 0..3 integer class
    match q {
        0 => score += 40.0,                 // <25% left: nearly dead bin
        1 => score += 15.0,                 // 25-50%: mediocre
        2 => score -= 10.0,                 // 50-75%: healthy
        _ => score -= 20.0,                 // >75%: excellent leftover
    }

    // Modulo-10 harmony: residuals that are multiples of 10 pair well with
    // typical item granules; odd/prime leftovers are harder to fill.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // this is a perfect chain -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let nq = (post_residual - next_item_size) * 4 / bin_capacity;
            score -= match nq { 0 => 0.0, 1 => 6.0, 2 => 12.0, _ => 18.0 };
        } else {
            // next item cannot use this bin's leftover: slight penalty
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the current item is huge and
    // no open bin offers a decent harmonic fit.
    if bin_residual == bin_capacity {
        let huge = item_size as f64 > 0.7 * cap;
        let no_good_home = fitting_bins_count == 0 || mean_residual < item_size as f64 * 0.5;
        if huge && no_good_home {
            score -= 30.0;
        } else {
            score += 35.0;
        }
    }

    // Stream progression: late in the stream, consolidate aggressively to
    // avoid spawning bins that will never be filled.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0;
    score += progress * (post_residual as f64 / cap) * 10.0;

    // Mild pressure toward using bins with lower mean residual (fill emptier-heavy bins first).
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward filling most of the bin (high fill ratio).
    let fill = (item_size as f64) / (bin_capacity as f64);
    score -= 20.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: more open bins -> prefer consolidating into existing bins.
    score += 2.0 * open_bins_count as f64;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Penalize leaving a gap just below the next item's size (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate: make it attractive only when existing bins would create dead space
    // or when bin pressure is high.
    if bin_residual == bin_capacity {
        let dead_risk = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        score += 10.0 + 3.0 * open_bins_count as f64 - 25.0 * dead_risk;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but with a convex penalty so that
    // leaving a tiny unusable sliver is worse than leaving a moderate gap.
    let pr = post_residual as f64;
    score += (pr * pr) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (perfect pairing).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = (pr - n).abs();
        // Perfect fit for the next item: strong reward.
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Gradual penalty as the gap to fitting the next item grows.
            score += diff * 0.35;
            // If next item cannot fit here at all, mild penalty unless
            // post_residual is large enough to be generally useful.
            if n > pr {
                score += (n - pr) * 0.25;
            }
        }
        // If the next item exactly fills this bin after the current one,
        // that is a double win: extra reward.
        if next_item_size == post_residual {
            score -= 25.0;
        }
    } else {
        // Last item in the stream: strongly prefer tightest fit.
        score -= 10.0;
    }

    // Compare against mean residual: placing into a bin whose residual is
    // below the mean (a tighter bin) is preferred; large-residual bins
    // should stay flexible for big future items.
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - pr) * 0.25;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual
    // (capacity - item). Penalize opening a new bin unless the current
    // item leaves a very tight fit or open bins are scarce / residuals
    // are globally low.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (pr / bin_capacity as f64);
        // Reward new bin only when the item is large (leaves small residual)
        // or few bins are open.
        let scarcity = 1.0 / (open_bins_count as f64 + 1.0);
        score -= tightness * 30.0 + scarcity * 20.0;
        // If open bins exist and this item fits poorly anywhere, new bin
        // is attractive; approximate via mean residual comparison.
        if open_bins_count > 0 && (mean_residual - item_size as f64) < 5.0 {
            score -= 15.0;
        }
    }

    // Slight preference for consolidating into fewer bins as the stream
    // progresses (avoid bin proliferation late in the stream).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space nonlinearly; small residuals are fine.
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.35 * dead * dead / bin_capacity as f64;
    } else {
        score -= 60.0; // perfect fit bonus
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 0.25 * item_size as f64;
    }

    // Many fitting bins: slight penalty to encourage spreading / preserving tight options.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 18.0;
            // Extra reward if next item exactly consumes post-residual.
            if post_residual == next_item_size {
                score -= 22.0;
            }
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            // Dead space that next item cannot use: penalize proportionally.
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 20.0;
        }
    }

    // Global state coupling: prefer filling bins when mean residual is high (many fragmented bins).
    score -= 0.08 * mean_residual * fit_ratio;

    // Prefer placing into already-open bins over opening new ones, scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when alternatives exist.
        score += 30.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // But allow opening a new bin early if current item is huge and would leave tiny dead space elsewhere.
        if progress < 0.3 && item_size >= 70 && fitting_bins_count <= 2 {
            score -= 55.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild preference for bins with residuals near common item sizes (modular structure).
    let r = post_residual as f64;
    let near_common = (r - 10.0).abs().min((r - 20.0).abs()).min((r - 30.0).abs()).min((r - 50.0).abs());
    score += 0.15 * near_common;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Tightness: how well the item fills the bin (0..1)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;

    // Reward tight fits more strongly later in the stream (smooth coupling)
    let tight_reward = tightness * tightness * (100.0 + 200.0 * progress);
    score -= tight_reward;

    // Penalize dead space non-linearly: small post_residual is good,
    // but residual that is too small to fit typical future items is waste.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 150.0 * (1.0 - 0.5 * progress);

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            let fit_quality = 1.0 - ((post_residual as f64 - nx) / bin_capacity as f64);
            score -= 120.0 * fit_quality * (0.5 + 0.5 * progress);
        } else {
            // Next item won't fit here: penalize proportional to leftover waste
            score += 40.0 * dead * (1.0 - progress);
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Mild penalty when bin is far from mean residual (encourages balanced fills),
    // scaled by number of open bins to avoid over-penalizing early stream.
    let spread = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += spread * spread * 30.0 * (open_bins_count.min(20) as f64 / 20.0);

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score = 100.0 + 3.0 * openness + 200.0 * (1.0 - tightness);
        // If this item is small relative to capacity, discourage wasting a fresh bin
        score += (1.0 - item_size as f64 / bin_capacity as f64) * 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post residual modulo capacity fractions.
    // Residuals that are "reusable" classes (small remainders aligning with
    // typical item sizes) are less harmful than mid-range dead space.
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let pr = post_residual;

    // Penalize mid-range dead space (unusable leftovers) more than tiny gaps.
    if pr > 0 && pr < eighth {
        score -= 20.0; // tiny gap: nearly full, good
    } else if pr >= eighth && pr <= quarter {
        score += 30.0; // awkward dead zone
    } else if pr > quarter && pr < (bin_capacity / 2) {
        score += 15.0;
    }

    // Modulo-class bonus: if post_residual modulo common size classes is small,
    // a future item can still slot in.
    let classes: [u32; 6] = [10, 20, 25, 30, 40, 50];
    let mut best_mod = u32::MAX;
    for &c in &classes {
        let m = pr % c;
        if m < best_mod {
            best_mod = m;
        }
    }
    score -= (classes.len() as f64) * 2.0 - best_mod as f64 * 0.5;

    // Lookahead: if next item fits exactly in post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - pr).min(bin_capacity) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are poor fits. Give it a mild penalty so tight fits in existing bins win.
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * mean_residual.abs().min(100.0);
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 20.0 - progress * 40.0;
    }

    // Crowding: many open bins -> favor filling existing ones.
    score -= (open_bins_count.min(50) as f64) * 0.5;

    // Prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 45.0;
    }

    // Reward residual that can still host a typical future item.
    if post_residual >= 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            score -= 30.0;
        } else if post_residual > 0 {
            score += 20.0; // next item won't fit here: dead space likely
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Pressure from number of open bins: consolidate when many bins are open.
    score += (open_bins_count as f64) * 3.0;

    // New-bin candidate: only attractive when no open bin fits or item is huge.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        } else {
            score += 80.0 + (open_bins_count as f64) * 2.0; // prefer existing bins
        }
    }

    // Mild mean-residual coupling: prefer bins below mean residual (tighter packing).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with the next item is golden.
    if next_item_size > 0 {
        let post = post_residual as i64;
        let nxt = next_item_size as i64;
        let diff = (post - nxt).abs() as f64;
        // Exact match for the next item: huge reward.
        if post == nxt {
            score -= 60.0;
        } else if post > nxt {
            // Next item fits after this placement; reward closeness of fit.
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit; penalize proportionally to the gap.
            score += 10.0 + 0.5 * diff;
        }
    } else {
        // Last item: just minimize waste.
        score -= 15.0;
    }

    // Penalize post_residual being small/dead space relative to mean residual.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.6 * (mean_residual - pr);
    } else {
        score -= 0.3 * (pr - mean_residual).min(20.0);
    }

    // Dead-space penalty: tiny leftovers are hard to reuse.
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless item is huge or lookahead
    // suggests current bins are poor fits.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 30.0 * fill_ratio;
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 15.0; // a fresh bin pairs well with the next item too
        }
    }

    // Slight preference for consolidating when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
