pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening over stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr * norm_pr);

    // Smooth polynomial coupling: dead-space penalty grows quadratically as stream progresses.
    score += 12.0 * progress * norm_pr * norm_pr * cap;

    // Lookahead: reward bins whose post-residual can host the next item (smooth kernel).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = (pr - n) / cap;
        score -= 10.0 * (-8.0 * diff * diff).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty when bin residual deviates from the mean residual (keep bin pool homogeneous).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Slight pressure against proliferating open bins early in the stream.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: group post_residual into modulo-10 classes.
    let post_class = post_residual % 10;
    // Penalize leftovers that fall in "awkward" classes (hard to fill later).
    let awkward = match post_class {
        1..=3 => 6.0,   // tiny slivers, nearly dead space
        4..=7 => 3.0,   // medium slivers
        8..=9 => 1.0,   // nearly a full decile, easy to reuse
        _ => 0.0,       // exact decile (0) is ideal
    };
    score += awkward;

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bins whose leftover can host the lookahead item exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            // Perfect lookahead fit
            if slack == 0 {
                score -= 25.0;
            } else {
                // Reward proportional to how well next item fits the leftover
                let fit_ratio = next_item_size as f64 / post_residual as f64;
                score -= 15.0 * fit_ratio;
                // Bonus if resulting slack lands on a clean decile class
                if slack % 10 == 0 { score -= 5.0; }
            }
        } else {
            // Next item cannot use this bin's leftover: penalize slightly,
            // scaled by how much space would be wasted.
            let waste = next_item_size - post_residual;
            score += 0.1 * waste as f64;
        }
    }

    // Integer-division threshold on post_residual: leftovers below half of a
    // "typical small item" (assume ~10) are high-risk dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins with low mean residual: prefer consolidating into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (post_residual as f64) < mean_residual {
        score += 2.0 * (1.0 - progress);
    } else {
        score -= 1.0 * progress;
    }

    // New empty bin candidate: only attractive when no open bin is a decent host
    // or the stream is early with few bins.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += pressure;
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large gaps.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

