    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Open-bin pressure: discourage spreading when many bins are already open
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit is genuinely good
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual as f64 > mean_residual {
