    // Lookahead: if next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // dead space relative to lookahead need
    }

    // Progress-based tightening: later in the stream, be stricter about waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> big reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 40.0;
        } else {
            // Penalize mismatch, harsher when post_residual can't fit next item (dead space).
            if post_residual < next_item_size {
                score += 12.0 + diff * 0.3;
            } else {
                score += diff * 0.15;
            }
        }
        // If post_residual can fit the next item, reward proportional closeness.
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Last item: just prefer tightest fit (already via base score).
        score -= 2.0;
    }

    // Relative to mean residual: bins with more room than average are cheaper to use.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless current bin would leave unusable residue.
    if bin_residual == bin_capacity {
        let dead = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += if dead > 0.0 { 5.0 } else { 30.0 };
    }

    // Early in stream, allow opening bins more freely; late, conserve.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
