        // increased late (consolidation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 40.0 + 60.0 * progress;
        // If the next item is large, a fresh bin is valuable.
