    score -= (bin_residual as f64 - item_size as f64).max(0.0) * 0.05 * (1.0 - progress);

    // Tie-break with mean residual deviation: prefer bins below average residual
    // (i.e., fuller bins) late in the stream.
    score += (mean_residual - bin_residual as f64) * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item_f = item_size as f64;
    let next_f = next_item_size as f64;
    let mean_r = mean_residual;

    // Base: penalize wasted post-residual, with a smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post-residual waste with stream progress:
    // later in the stream, dead space becomes more costly (quadratic ramp)
    let progress_coupling = pr * (progress * progress) * 0.6;
    score += progress_coupling;

    // Reward tight fits (small post_residual relative to item) with smooth term
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * item_f * 0.25;

    // Interaction: post_residual vs mean residual — prefer bins whose leftover
    // deviates smoothly from the fleet mean to preserve diversity of gaps
    let gap_dev = (pr as f64 - mean_r) / cap;
    score += gap_dev * gap_dev * 12.0;

    // Lookahead: if next item fits in the post-residual, reward this bin smoothly
    if next_f > 0.0 && next_f <= pr {
        let fit_frac = next_f / pr;
        score -= 6.0 * fit_frac * (1.0 - fit_frac * 0.5);
    } else if next_f > 0.0 {
        // smooth penalty proportional to how much next item overshoots
        let over = (next_f - pr) / cap;
        score += over * over * 20.0;
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * tightness;
    }

    // Mild pressure against opening new bins as stream progresses (smooth)
    if bin_residual as f64 == cap {
        score += 10.0 + 15.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Slight penalty for many open bins (fragmentation), smoothed
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: items that leave tiny unusable residues are bad.
    let post = post_residual as u32;
    let cap = bin_capacity as u32;

    // Dead-space penalty: residues in (0, 10) are almost unusable (min item 10 in classic; be safe with 1..10 band)
    if post > 0 && post < 10 {
        score += 25.0 * (10.0 - post as f64) / 10.0;
    }

    // Perfect fit reward
    if post == 0 {
        score -= 40.0;
    }

    // Harmonic class via integer division: residues divisible by common item sizes are reusable
    let class = post / 10; // harmonic class 0..10
    score += class as f64 * 1.5;

    // Residue that exactly matches next item size is golden
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 35.0;
        } else if post > next_item_size && post < next_item_size + 10 {
            score += 8.0; // awkward sliver just above next item
        }
        // residue that can host next item twice or thrice (harmonic multiple)
        if post >= 2 * next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < cap {
        score -= 20.0;
    }

    // Modulo coupling: residues congruent to 0 mod 50 or 25 are structurally reusable
    if post % 50 == 0 && post > 0 {
        score -= 10.0;
    }
    if post % 25 == 0 && post > 0 {
        score -= 5.0;
    }

    // Prefer tight fits: penalize large leftover relative to capacity fraction
    let tightness = 1.0 - (post as f64 / cap as f64);
    score += (1.0 - tightness) * 10.0;

    // Late in stream, consolidate into open bins harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < cap {
        score -= 5.0 * progress;
    }

    // New-bin candidate: keep it attractive only when few bins fit or bin is very tight
    if bin_residual == cap {
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Bonus for exact fit.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize post-residuals that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress);

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild preference for filling fuller bins.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches the next item size (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward chains that leave enough room for the next item, scaled by tightness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize creating dead space below the next item's size.
        score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // Prefer bins whose residual is tight relative to the mean residual (avoid wasting open capacity).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well,
    // unless the item is large and residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // new bin can still chain the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can never be reused by typical items:
    // waste grows quadratically once residual falls below small-item threshold.
    if post_residual > 0 {
        let dead = if post_residual < 10 { post_residual as f64 } else { 0.0 };
        score += 8.0 * dead;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // big reward; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Prefer filling bins with large residual when many bins are open
    // (consolidation pressure scales with open_bins_count).
    score += (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 - post_residual as f64) * 0.15;

    // Divergence from mean residual: prefer bins below mean residual (more filled).
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.5;

    // Time horizon: early in stream, favor opening new bins less (keep packing tight);
    // late in stream, prefer using existing bins to avoid stranding capacity.
    let t = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or early stream.
        score += 15.0 + 10.0 * (1.0 - t) + (open_bins_count as f64) * 0.5;
        // But if item is huge and mean residual is small, opening a fresh bin is good.
        if item_size as f64 > mean_residual + 5.0 {
            score -= 20.0;
        }
    } else {
        score += 5.0 * t;
    }

    // Mild penalty for very large post-residual waste relative to capacity.
    score += 0.05 * post_residual as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with a smooth non-linear (quadratic) growth
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, prefer filling tightly (weight leftover more); late, be more lenient
    let progress_coupling = 1.0 - 0.5 * progress * progress;
    score *= progress_coupling;

    // Smooth interaction: small post-residual rewarded more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Reward near-perfect fits with a smooth bump
    let perfect = (pr / cap).min(1.0);
    score -= 5.0 * (1.0 - perfect) * perfect * 4.0; // peaks at pr = cap/2

    // Penalize waste relative to mean residual (smooth divergence term)
    score += 0.5 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: smooth penalty that relaxes if no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let bad_fit_penalty = (pr / cap).powi(2) * 20.0;
        score += 10.0 - bad_fit_penalty;
    }

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr as i64 - next_item_size as i64).abs() as f64;
        score += 0.05 * gap;
        let fits_next = (pr >= next_item_size) as i32 as f64;
        score -= 4.0 * fits_next * (1.0 - gap / cap);
    }

    // Mild penalty for proliferation of open bins, smoothly scaled by progress
    score += 0.3 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of post_residual via integer division thresholds (capacity / 10 classes)
    let harmonic_class = post_residual / (bin_capacity / 10).max(1);
    score += match harmonic_class {
        0 => -30.0,   // near-perfect fit: tiny dead space
        1 => -12.0,   // still compact
        2 => 0.0,     // neutral
        3 => 6.0,     // chunky gap
        _ => 12.0,    // mostly empty bin used wastefully
    };

    // Exact fill is gold
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling (k=2): dead space if next item cannot use the leftover
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            score -= 6.0;
        }
        // exact harmonic match: leftover equals next item exactly
        if next_item_size == post_residual {
            score -= 25.0;
        }
        // modulo harmony: leftover divisible into next item size class
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 18.0;
    }

    // New-bin candidate scoring
    if is_new_bin {
        score = 45.0 + mean_residual * 0.25;
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 12.0; // big next item: fresh bin attractive
        }
        // if the only fitting bin is a poor fit (large post residual elsewhere), new bin wins
        if fitting_bins_count <= 1 && mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Mild progression coupling: late in the stream, tighten up (favor tight fits more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Tight fit reward: post_residual that can still host a small item is valuable.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize wasting a large residual on a small item (poor utilization).
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    if waste > 50.0 {
        score += (waste - 50.0) * 0.8;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 2.5 * open_bins_count as f64;
    } else {
        // Last-chance bin: strongly favor using the only bin that fits.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Mild preference for existing bins proportional to open count.
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    }
    // If next item would not fit anywhere else and this bin is the only fit, extra pressure.
    if next_item_size > 0 && next_item_size > post_residual && fitting_bins_count == 1 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // in the direction of a better fill (below-mean residual = fuller bin).
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Early stream: be slightly more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if is_new_bin {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let fits_next = next_item_size > 0 && post_residual >= next_item_size;

    // Reward chains: post residual accommodating the lookahead item.
    if fits_next {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 + 8.0 * tightness;
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the next item.
        score += 6.0;
    }

    // Exact closure bonus: item perfectly fills the bin.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Compare against mean residual: placing into a bin with residual near mean
    // is neutral; leaving a much larger residual than average is wasteful.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // nothing fits well (post_residual would be large relative to item) or
    // when the stream is early and future capacity is valuable.
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0;
        // Slightly cheaper to open bins early in the stream.
        score -= 5.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
        // If many open bins but none fit well, new bin is acceptable.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        // Favor packing into existing bins generally (avoid bin proliferation).
        score -= 2.0;
        // Prefer bins with smaller residual (best-fit style) among open bins.
        score += 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space: residual that cannot fit a typical future item.
    if post_residual > 0 {
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score += 50.0;
        }
        // Non-linear waste penalty: small leftovers are costly.
        let waste = post_residual as f64;
        score += 0.35 * (waste * waste) / 100.0;
    }

    // Lookahead: penalize if post_residual can't fit the next item
    // (creates stranded space), reward if it exactly/nearly fits it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 12.0 - 0.15 * slack as f64; // perfect chain fit is best
        } else {
            score += 8.0; // this placement strands the next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins with large mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are roomy or numerous.
        score += 18.0 + 2.5 * open_bins_count as f64 + 0.25 * mean_residual;
        // Late in the stream, opening new bins wastes capacity on tail items.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    } else {
        // Existing bin: mild reward when many bins are open (consolidation).
        score -= 0.8 * open_bins_count as f64;
        // Prefer bins below mean residual (emptier bins stay flexible)? No:
        // prefer filling bins with LARGE residual to reduce bin count.
        score -= 0.10 * (bin_residual as f64 - mean_residual);
    }

    // Early-stream exploration: keep bins balanced so future items fit.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.08 * deviation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * (1.0 - progress);
    score += 12.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Dead-space penalty: residuals too small for typical items
    let dead = (norm_pr * (1.0 - norm_pr)).max(0.0); // peaks mid-range, low near 0
    score += 8.0 * (1.0 - dead) * (1.0 - dead) * norm_pr;

    // Lookahead: reward leaving space for next item, smooth quadratic
    if next_item_size > 0 {
        let gap = (norm_pr - norm_next).abs();
        score -= 6.0 * (1.0 - gap) * (1.0 - gap) * norm_next;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Prefer fuller bins relative to mean residual (smooth sigmoid-like)
    let diff = (mean_residual - pr) / cap;
    score += 5.0 * diff / (1.0 + (-4.0 * diff).abs());

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * progress;
    }

    // Slight preference for fewer open bins late in the stream
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 bands penalize awkward dead space
    let pr = post_residual;
    let class = pr % 10;
    if pr > 0 {
        // dead space penalty grows when residual falls into awkward class bands
        score += (class as f64) * 0.15;
        // very small unusable residue (<10) is nearly dead: strong penalty
        if pr < 10 {
            score += 8.0;
        } else if pr < 20 {
            score += 3.0;
        }
    } else {
        // perfect fill: reward heavily
        score -= 30.0;
    }

    // Fraction-of-capacity coupling: post_residual relative to capacity
    let frac = post_residual as f64 / cap;
    score += frac * 10.0;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to tightness
            let tight = 1.0 - ((pr - next_item_size) as f64) / (pr.max(1) as f64);
            score -= 10.0 * tight;
        } else {
            // next item cannot use this residual: penalize proportionally to wasted potential
            let waste = (next_item_size - pr) as f64;
            score += 0.08 * waste;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer it only when current fit is very poor
    if bin_residual == bin_capacity {
        // fresh bin baseline: attractive if existing bins would leave bad residue
        if pr > 0 && post_residual == bin_residual {
            // called with item not yet subtracted for new bin; residual stays full minus item
        }
        score = 0.5 * (cap - item_size as f64);
        // penalize opening new bins late in stream or when few bins open
        score += open_bins_count as f64 * 2.0;
        score += (step_index as f64 / (total_items.max(1) as f64)) * 10.0;
        // reward new bin if mean residual across open bins is small (all bins crowded)
        score -= mean_residual * 0.2;
    } else {
        // existing bin: reward keeping mean residual balanced (avoid fragmentation)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Integer-division thresholds on post_residual: quarter classes
    let quarter = pr / (bin_capacity / 4);
    score += quarter as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 200.0 * (10.0 - post_residual as f64);
    }

    // Penalize residuals that cannot fit the lookahead item but could
    // otherwise have been useful (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward residuals that exactly accommodate the next item (perfect chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Perfect fit reward: leaving exactly zero residual is ideal closure.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than spreading; penalize lightly per open bin
    // so a new bin is only chosen when dead-space cost dominates.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate guard: an empty bin has no dead space yet, but
    // opening bins is costly when pressure is high; make its base score
    // less attractive than a decent fit in an existing bin.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Early-stream mild preference for tight fits via mean residual coupling:
    // if this bin's residual is far below the mean, it is a scarce large gap;
    // using it avoids fragmentation.
    let gap = mean_residual - bin_residual as f64;
    if gap > 0.0 {
        score -= 0.15 * gap;
    }

    // Progress-scaled dead-space penalty: as the stream matures, wasted
    // small gaps matter more since fewer items remain to fill them.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 25 {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (perfect two-item packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0; // perfect 2-step chain: bin closes exactly after next item
        } else {
            let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
            // soft penalty growing with mismatch, strongest for small overshoot
            score += diff * 0.3;
            if post_residual < next_item_size {
                score += 8.0; // next item won't fit here at all
            }
        }

        // Reward when next item fits into the residual pair-wise leftover
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    // (consolidate fullness), penalize placing into already-loose bins.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin
    // would leave a large, unusable residual (dead space).
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if the item is large relative
        // to capacity and existing bins are relatively full.
        score += 30.0;
        if item_size >= 60 {
            score -= 10.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 20.0; // existing bins nearly full -> new bin is fine
        }
    } else {
        // Penalize leaving tiny unusable slivers (< 10) that nothing can use.
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }
        // Reward exact closures.
        if post_residual == 0 {
            score -= 20.0;
        }
    }

    // Slight progression-awareness: late in the stream, tighten packing
    // (avoid spreading) by penalizing loose residuals more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.25;

    // Mild pressure against proliferating many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose residual can host the next item exactly or well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits here too: mild reward proportional to tightness
            score -= 60.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // next item won't fit: penalize dead space relative to next item size
            score += 0.35 * ((next_item_size as f64) - (post_residual as f64)).max(0.0);
        }
    }

    // Tightness reward: small post_residual generally good
    score -= 2.0 * (100.0 - post_residual.min(100) as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Many fitting bins: penalize slightly to encourage consolidation into tightest ones
    if fitting_bins_count > 1 {
        score += 8.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., roomier than average) is penalized when post_residual is large
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.25 * dev * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, keep bins flexible (penalize tiny residuals);
    // late in stream, fill aggressively
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if progress < 0.5 {
        score += 0.5 * post_residual as f64 * (1.0 - progress);
    } else {
        score -= 0.5 * post_residual as f64 * progress;
    }

    // Open bins pressure: many open bins -> favor filling existing ones
    score += 3.0 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / 100.0);

    // New-bin candidate handling: only attractive when item is large relative to capacity
    // or nothing else fits well
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 120.0;                      // base cost of opening a new bin
        score -= 150.0 * large_item;         // large items justify fresh bins
        if fitting_bins_count == 0 {
            score -= 400.0;                  // no alternative: must open
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 50.0;                   // fresh bin useful for next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Smooth non-linear coupling: normalized post-residual shaped by progress
    let poly = norm_post * norm_post * (1.0 + progress) + norm_post * (1.0 - progress) * 0.5;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses (quadratic in item size)
    score -= 30.0 * norm_item * norm_item * (0.5 + progress);

    // Lookahead: penalize residual that can't fit next item (smooth sigmoid-like term)
    if next_item_size > 0 {
        let fits_next = (post - norm_next * cap).max(0.0) / cap;
        score -= 20.0 * (1.0 - (fits_next * 4.0).tanh()) * (0.3 + 0.7 * progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else {
        // Mild penalty when many bins fit, to prefer consolidation
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual coupling: penalize bins far from the mean residual (smooth)
    let dev = (post - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless residual is large / progress early
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * progress - 10.0 * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod 10 defines "dead-space classes".
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.35; // odd/small residues create unusable slivers

    // Reward residuals that are multiples of common item sizes (harmonic fit).
    let harmonics = [10u32, 20, 25, 40, 50];
    for h in harmonics {
        if post_residual % h == 0 && post_residual > 0 {
            score -= 6.0;
            break;
        }
    }

    // Integer-division thresholds on post_residual: penalize large leftovers less
    // if they form a usable capacity fraction (>= 25% of bin).
    let frac = post_residual as f64 / cap;
    if frac >= 0.25 {
        score -= 8.0 * frac;
    } else if frac > 0.0 {
        score += 10.0 * (0.25 - frac); // dead-space penalty below quarter bin
    }

    // Coupling with next item: reward leaving room that exactly (or nearly) fits it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here: leftover likely wasted
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no good harmonic fit exists.
    if bin_residual == bin_capacity {
        score += 4.0 + 0.15 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0; // reserve fresh bin for pairing current + next
        }
    }

    // Stream progression: late in the stream, tighten packing (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 * progress;
    } else {
        score -= 4.0 * progress;
    }

    // Mean-residual coupling: prefer bins close to the mean (balanced closure).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are effectively unusable; penalize them heavily.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    } else {
        // Reward near-perfect fits progressively.
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize gaps too small to fit the lookahead item (dead space w.r.t. k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward gaps that exactly accommodate the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: discourage scattering across many open bins.
    score += 1.5 * open_bins_count as f64;

    // Coupling with mean residual: bins far below the mean residual are good
    // targets (they absorb space efficiently); bins above mean are worse.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild stream-progression tightening: later in the stream, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.4;

    // New-bin candidate: only attractive when existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near-exact match of next item into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 60.0; // perfect two-item packing
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize dead space relative to next item.
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Favor bins whose residual deviates from mean residual toward tight fits.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Penalize creating tiny unusable slivers (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are quite full on average.
    if bin_residual == bin_capacity {
        score += 15.0 * (mean_residual / bin_capacity as f64);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // good for back-loading large items into fresh bins
        } else {
            score += 10.0;
        }
    }

    // Mild preference for consolidating into fewer bins as stream progresses.
    score += 0.05 * (open_bins_count as f64) * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically relative to capacity.
        let dead_frac = post_residual as f64 / bin_capacity as f64;
        if dead_frac < 0.1 {
            score -= (0.1 - dead_frac) * 400.0;
        } else {
            score += (dead_frac - 0.1) * 150.0;
        }
    }

    // Lookahead: if the next item can fit in the post-residual, reward this placement;
    // otherwise penalize leaving a residual that is useless for the known next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0 * (1.0 - (next_item_size as f64) / (bin_capacity as f64));
        } else if post_residual > 0 {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins (favor packing
    // quality); late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows over time.
        score += 40.0 + 220.0 * progress;
        // Opening a new bin is attractive when open bins are numerous and fragmented.
        score += (open_bins_count as f64).ln().max(0.0) * 15.0;
    } else {
        // Late stream: reward using existing bins more aggressively.
        score -= 80.0 * progress;
    }

    // Global fragmentation: if mean residual is low, preserve bins with large residuals
    // (don't waste big-space bins on small items).
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel > 1.5 {
            score += (rel - 1.5) * 30.0 * item_size as f64 / bin_capacity as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: penalize wasted space, with a convex quadratic shaping of residual
    let mut score = pr + 12.0 * fit_norm * fit_norm * cap;

    // Smooth stream-progress coupling: late in the stream, waste is costlier
    let late = progress * progress;
    score += 30.0 * late * fit_norm;

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tightness = 1.0 - fit_norm;
    score -= 8.0 * (0.5 + progress) * tightness * tightness;

    // Dead-space penalty: residuals too small for the smallest plausible item
    let dead = (10.0 - pr).max(0.0);
    score += 25.0 * (dead / 10.0) * (dead / 10.0);

    // Lookahead: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = nx - pr;
        if gap > 0.0 {
            score += 10.0 * (gap / cap) * (1.0 + progress);
        } else {
            score -= 6.0 * (-gap / cap);
        }
    }

    // Last-chance bonus: strongly favor this bin if it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open, encouraging consolidation early
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 2.0;

    // Encourage using bins whose residual is far above the mean (balance residuals)
    score += 0.5 * (bin_residual as f64 - mean_residual) / cap;

    // New-bin candidate: make empty bins mildly unattractive unless item is large
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Classify post_residual into harmonic buckets: tiny, small, mid, large
    let frac = pr / cap; // fraction of capacity wasted
    if frac > 0.0 && frac < 0.1 {
        score -= 40.0; // near-full bin is excellent
    } else if frac < 0.25 {
        score -= 15.0;
    } else if frac < 0.5 {
        score += 10.0;
    } else {
        score += 25.0; // large dead space
    }

    // Modulo arithmetic: residuals that are "harmonically compatible" with
    // common item sizes (divisible by 10) are more reusable.
    let pr_u = post_residual;
    if pr_u % 10 == 0 && pr_u > 0 {
        score -= 8.0;
    }
    // Dead space that no typical item can use (pr < 10) is bad unless zero
    if pr_u > 0 && pr_u < 10 {
        score += 12.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item divides the residual well
            let slack = post_residual - next_item_size;
            score -= 6.0 + (slack as f64).min(20.0) * 0.3;
            if slack % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 4.0; // next item won't fit here either
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins are bad,
    // but relax when many bins are open with high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - 0.5).max(0.0);
        score += 20.0 - frag * 30.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Stream progression: late in stream, prefer tighter packing (open fewer bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / cap);

    // Tie-break toward bins with residual close to item size (tight fit)
    score += (bin_residual as f64 - item_size as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Coupling: dead space hurts more when few bins can fit the item (last chance).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0; // prefer using the only fitting open bin over opening a new one
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size as f64 == post_residual as f64 {
        score -= 20.0;
    }
    // If next item would fit post_residual, mild reward.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 5.0;
    }
    // If next item cannot fit post_residual and post_residual is small, penalize.
    if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 && post_residual < 20 {
        score += 12.0;
    }

    // Open bins pressure: mildly discourage opening new bins when few are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus open-bin pressure.
        score += 20.0 + (open_bins_count as f64) * 3.0;
        // Late in the stream, consolidation is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Using an existing bin reduces pressure slightly with many open bins.
        score -= (open_bins_count as f64).min(10.0) * 1.5;
    }

    // Prefer bins tighter than the mean residual (better consolidation).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: exact match of post_residual with next item is ideal.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            let slack = post - next;
            // Perfect chain: next item exactly fills remaining space.
            if slack == 0.0 {
                score -= 60.0;
            } else {
                // Reward closeness of next item to post_residual.
                score -= 40.0 * (1.0 - slack / post.max(1.0));
                // Penalize leaving awkward small-but-not-matching residue.
                if slack < 10.0 {
                    score += 25.0;
                }
            }
        } else {
            // Next item cannot use the residue at all: dead space risk.
            score += 15.0 + (next - post) / bin_capacity as f64 * 20.0;
        }
    } else {
        // Last item: pure tightness.
        score -= 10.0;
    }

    // Reward relative tightness vs mean residual across open bins.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it unattractive unless the fit is terrible elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tightness: reward small post-residual non-linearly
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tight * tight;

    // Penalize dead space that no future item (10..80 or 1..100) can fill well
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // this bin is the only one that could have served the next item chain
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: prefer consolidation into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Global residual alignment: prefer bins below mean residual (fill fuller bins)
    score += 0.4 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: only attractive when current bins are poor fits
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let bad_fit = (post_residual as f64 / bin_capacity as f64) > 0.7;
        if scarcity > 0.0 || (bad_fit && open_bins_count > 0) {
            score -= 45.0 * scarcity + 20.0 * if bad_fit { 1.0 } else { 0.0 };
        } else {
            score += 40.0; // discourage opening bins when good fits exist
        }
    }

    // Late stream: tighten packing, avoid waste
    if progress > 0.8 {
        score += 0.5 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits, with a non-linear polynomial shaping of dead space.
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on (t small) tolerate larger residuals; later, penalize them super-linearly.
    let progress_weight = 1.0 + 2.0 * t * t; // smooth acceleration over the stream
    score += progress_weight * (x * x * cap) * 0.5;

    // Reward near-perfect fits with a smooth bump centered at x = 0.
    let tightness = (-x * 8.0).exp();
    score -= 12.0 * tightness * (1.0 + t);

    // Penalize waste when the leftover is just below the smallest plausible item,
    // computed smoothly from mean residual instead of a hardcoded threshold.
    let mean_x = (mean_residual / cap).clamp(0.0, 1.0);
    let dead_zone = (1.0 - x).max(0.0) * (1.0 - mean_x);
    score += 6.0 * dead_zone * dead_zone;

    // Last-chance bin: smooth urgency term when few fitting bins exist.
    if fitting_bins_count <= 1 {
        score -= 10.0 * (1.0 - x);
    }

    // Lookahead: if the next item fits the post-residual, reward this placement smoothly.
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as i32 as f64;
        let gap = (pr - next_item_size as f64) / cap;
        score -= 8.0 * fits_next * (-gap * gap * 20.0).exp();
    }

    // New empty bin candidate: penalize increasingly as stream progresses,
    // unless residuals across bins are generally large (smooth escape hatch).
    let is_new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let residual_pressure = mean_x.clamp(0.0, 1.0);
    score += is_new_bin * (20.0 + 60.0 * t) * (1.0 - 0.5 * residual_pressure);

    // Mild preference for consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: quantize into capacity fractions
    let class = (post_residual * 4) / bin_capacity; // 0..3 harmonic class
    let class_penalty = match class {
        0 => -14.0, // nearly full bin: excellent
        1 => -4.0,  // small leftover: good
        2 => 2.0,   // medium leftover: mediocre
        _ => 6.0,   // large leftover: poor
    };
    score += class_penalty;

    // Dead-space penalty: leftover that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            // leftover unusable by lookahead -> dead space until stream end
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += (nxt - post) * (0.6 + 0.8 * progress);
        } else {
            // reward if leftover is a "harmonic" fit: multiple of next item
            let fits = (post / nxt).floor();
            if fits >= 2.0 {
                score -= 3.0 * (fits - 1.0).min(3.0);
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: make empty bin attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post).max(0.0);
        score = cap - fragmentation * 0.5;
        if fitting_bins_count <= 1 {
            score += 20.0; // no real alternative, new bin fine
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // big lookahead item: fresh bin useful
        }
    }

    // Slight preference for bins already below mean residual (balance)
    score -= 0.3 * (mean_residual - post).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are "dead".
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Dead space penalty grows as the gap becomes useless.
        let gap = post_residual as f64;
        score += 30.0 + 2.0 * gap;
    }

    // Perfect-fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Penalize leaving residuals in the awkward band (1..=10) even if next item unknown.
    if post_residual >= 1 && post_residual <= 10 {
        score += 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins); with few open bins, new bins are cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: score = empty residual baseline plus pressure.
        score = bin_capacity as f64 + 15.0 * pressure;
        // Last-chance: if this is the only fitting bin, strongly avoid opening a new bin.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
        // Late in stream, opening new bins is more wasteful.
        score += 10.0 * (step_index as f64 / total_items.max(1) as f64);
    } else {
        // Existing bins get a bonus when there are many open bins.
        score -= 5.0 * pressure;
        // Last fitting bin bonus: must use it or lose efficiency.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Slight preference for bins with below-average residual (they are the fullest).
    score -= 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item still fits: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 - slack.min(50.0);
        } else {
            // Dead space: next item cannot use it. Penalize proportional to
            // how much of the residual is wasted relative to next item.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 1.5;
        }
    }

    // Penalize leaving tiny unusable slivers (below minimum plausible item size).
    if post_residual > 0 && post_residual < 5 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Compare against mean residual: prefer bins already below-average residual
    // (tighter bins), i.e. best-fit style consolidation.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // New empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 300.0 } else { 0.0 };
        score += 250.0 - desperation
            + (mean_residual * 0.3);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 100.0; // big upcoming item: fresh bin is fine
        }
    }

    // Early in stream: slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: penalize leaving a residual that the next item cannot use
    // (dead space), unless the leftover is tiny (effectively perfect fit).
    if next_item_size > 0 {
        let leftover = post_residual as f64;
        if leftover < next_item_size as f64 {
            // Next item won't fit here -> this residual becomes dead space
            // unless it's small enough to be negligible.
            let waste = if leftover < 5.0 { 0.0 } else { leftover };
            score += 0.35 * waste;
        } else {
            // Next item fits in the leftover -> strong chaining bonus.
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize dumping a small item into a large-residual bin that could
    // host a bigger future item; scale by how much capacity is squandered.
    let squander = (post_residual as f64) - (next_item_size as f64).min(post_residual as f64);
    if item_size < 30 && post_residual > 40 {
        score += 0.25 * squander.max(0.0);
    }

    // Time horizon: early in the stream, be conservative with new bins
    // (many items remain, consolidation matters); late in the stream,
    // residual perfection matters more than bin count.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= 5.0 * progress * tightness;

    // Global pressure: many open bins with high mean residual -> prefer
    // placements that reduce fragmentation (low post_residual).
    if open_bins_count > 3 && mean_residual > 30.0 {
        score += 0.10 * (post_residual as f64 - mean_residual).abs();
        score -= 3.0;
    }

    // New-bin candidate (empty bin): make it mildly attractive only when
    // no open bin offers a good fit, i.e., post_residual is large here
    // equals capacity minus item; keep a fixed offset so tight fits in
    // existing bins win, but poor fits lose to opening a fresh bin.
    if bin_residual == bin_capacity {
        score += 8.0 - 4.0 * tightness;
        // With few bins open early, opening is cheap.
        score -= (open_bins_count.min(5) as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = base;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: tolerate residual waste less (favor tight fits) via stronger
    // quadratic penalty; late stream: residual is more acceptable, so penalty decays.
    let decay = (1.0 - progress) * (1.0 - progress);
    score += 2.0 * base * base * decay;
    score -= 1.5 * base * progress;

    // Cubic interaction: penalize near-full residual tails more sharply as stream advances.
    score += 0.8 * base * base * base * (1.0 + 2.0 * progress);

    // Reward placements that leave room for the lookahead item (smooth coupling).
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (pr - nxt).abs() / cap;
        score -= 0.6 * (1.0 - gap * gap) * (1.0 - 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new one.
    if fitting_bins_count == 1 {
        score -= 1.0 + 0.5 * progress;
    }

    // Mild penalty proportional to deviation from mean residual (prefer balanced fills).
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // Slight preference for bins among many open bins (consolidation pressure).
    score -= 0.01 * open_bins_count as f64 * base;

    // New-bin candidate should score moderately high unless the fit is excellent.
    if bin_residual == bin_capacity {
        score += 0.8 + 0.4 * progress - 0.5 * base;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction slot does it land in?
    // post_residual classes (of 100): 0 perfect, 1-10 great, 11-30 ok, 31+ wasteful
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -60.0 // perfect closure
    } else if pr <= 10 {
        -25.0
    } else if pr <= 30 {
        5.0
    } else {
        20.0
    };
    score += class_penalty;

    // Integer-division harmonic: how many items of the *next* size fit into post_residual?
    // If exactly one next item fits snugly, reward; if it's a dead class, penalize.
    if next_item_size > 0 && pr > 0 {
        let fits_next = pr / next_item_size;
        let leftover_next = pr % next_item_size;
        if fits_next >= 1 && leftover_next == 0 {
            score -= 30.0; // perfect harmonic tiling with lookahead item
        } else if fits_next >= 1 && leftover_next <= 10 {
            score -= 12.0;
        } else if fits_next == 0 {
            // next item cannot use this residual at all -> dead space risk
            score += 15.0;
            // unless this is the last-chance bin, then we must place here anyway
            if fitting_bins_count == 1 {
                score -= 40.0;
            }
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless all else is bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, opening bins is fine (few future items to strand)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * progress;
        // If many open bins exist, spreading is less costly
        score -= (open_bins_count.min(10) as f64) * 1.5;
    }

    // Prefer bins tighter than the mean (best-fit flavor), scaled mildly
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Small tie-breaker: prefer filling larger residual bins slightly
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual that is too small to hold even the smallest plausible item is pure waste.
    let dead_threshold = 10u32; // smallest item size
    if post_residual > 0 && post_residual < dead_threshold {
        score += 100.0; // heavy penalty for creating dead space
    } else if post_residual == 0 {
        score -= 50.0; // perfect fit is strongly rewarded
    }

    // Non-linear penalty on wasted fraction of the bin
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Open-bin pressure: discourage spreading across many bins when few are needed,
    // but favor using existing bins as the open count grows.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Lookahead coupling: reward placements that leave room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // slight penalty for blocking the lookahead item
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // New-bin candidate: make an empty bin mildly unattractive unless open bins are scarce
    // or it would otherwise create dead space in an existing bin.
    if bin_residual == bin_capacity {
        let scarcity_bonus = if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        score = score * 0.5 + 60.0 - scarcity_bonus + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 45.0 - (slack_after_next as f64) * 0.9;
        if slack_after_next == 0 {
            score -= 40.0; // perfect two-item packing
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize proportionally to wasted opportunity.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.35;
    }

    // Penalize tiny dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits relative to the mean residual across open bins.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 25.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins with residuals below the mean (consolidate large spaces).
    score += ((bin_residual as f64) - mean_residual) * 0.2;

    // Discourage opening new bins early in the stream / when many bins already open.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count >= 1 {
            score += 20.0; // only open a new bin if no decent existing option
        }
    }

    // Slight late-stream bias toward closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 35.0 * fill * fill;

    // Penalize tiny dead space that no realistic item can use,
    // but only mildly if it's near zero (perfect fit).
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.12 {
            score += 60.0 * (0.12 - dead); // small penalty near-perfect
        } else {
            score += 8.0 * dead; // larger residuals are mildly bad
        }
    } else {
        score -= 25.0; // perfect fit bonus
    }

    // Lookahead coupling: can the next item use the leftover space?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins whose remainder can host the next item,
            // scaled by how snugly the next item fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 18.0 * snug;
        } else {
            // Leftover can't host next item: penalize proportionally
            // to how much space is wasted relative to next item.
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer fuller bins (less residual).
        score += 4.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: an empty bin has huge residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are
        // crowded (mean residual low) or the item is large and would
        // leave awkward remainders elsewhere.
        let crowded = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 55.0 - 45.0 * crowded - 25.0 * large_item - 10.0 * progress;
        // If the next item is small, a fresh bin is fine to open.
        if next_item_size > 0 && next_item_size <= 25 {
            score -= 12.0;
        }
    }

    // Late in the stream, consolidate: prefer bins with residual close
    // to the mean (avoid fragmenting many half-empty bins).
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = (post_residual as f64 - mean_residual).abs();
    score += prog * 0.08 * dev;

    // Mild pressure against proliferating bins when many are open.
    score += 0.35 * open_bins_count as f64 * (1.0 - prog);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1)

    let mut score = pr as f64;

    // Non-linear polynomial coupling: dead-space penalty grows quadratically/cubically with progress
    let dead = (x * x) * cap * (0.5 + 1.5 * progress) + (x * x * x) * cap * progress * 2.0;
    score += dead;

    // Reward tight fits (small post-residual) more strongly as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (2.0 + 6.0 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize opening new bins when many bins are open with slack
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64 + 10.0 * progress * (1.0 - x);
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += 0.3 * gap;
        if pr >= nx {
            score -= 4.0 * (1.0 - gap / cap) * (1.0 + progress);
        }
    }

    // Mild attraction toward bins whose residual is near the mean (balance load)
    score += 0.2 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic in wasted space
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / cap;

    // Harmonic classes: post_residual divisible by common item-size classes is more reusable
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 3.0; }
        if pr % 25 == 0 { bonus += 3.0; }
        if pr % 50 == 0 { bonus += 4.0; }
        // class of residual in integer division bands of 10
        let band = pr / 10;
        bonus += (band % 3) as f64 * 0.5;
        score -= bonus;
    } else {
        score -= 12.0; // perfect fill
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 3.0; // next item won't fit here, deprioritize
        }
        // harmonic match: next_item_size shares divisor structure with post_residual
        if post_residual % gcd(post_residual, next_item_size) == 0 && gcd(post_residual, next_item_size) > 1 {
            score -= 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Prefer bins with below-mean residual (consolidate emptier bins' usage)
    score += 0.05 * (mean_residual - bin_residual as f64).max(-30.0);

    // New-bin candidate: penalize mildly, but allow when fit is bad
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * (post_residual as f64);
        if open_bins_count == 0 { score -= 25.0; }
    }

    // Late-stream: slightly prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / cap);

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (0 < post_residual < 10)
    // are the worst outcome. Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward placements that leave a gap still usable by typical items (>= 10).
    // The tighter the fit while remaining usable, the better.
    if post_residual >= 10 {
        score -= 15.0;
        // Extra reward when the leftover can also host the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Penalize leaving a gap that is too large relative to mean residual (wasteful).
        if post_residual as f64 > mean_residual * 1.5 {
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage opening a new bin
    // (new-bin candidate has bin_residual == bin_capacity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // Base penalty for a new bin, scaled by number of open bins and progress.
        score += 30.0 + 6.0 * open_bins_count as f64 + 20.0 * progress;
        // But if no open bin leaves a usable gap, a new bin is acceptable:
        // emulate by softening when the best alternative would create dead space.
        if bin_residual >= item_size && item_size < 10 {
            score -= 20.0;
        }
    }

    // Mild preference for bins with lower residual (tighter packing) among ties.
    score += 0.05 * (bin_residual as f64 - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack
    else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 35.0;
    }
    // Next item does NOT fit in the residual: penalize proportionally to wasted space
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.4 * waste;
    }

    // Reward tight fits relative to bin capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Penalize placements leaving residual far from the mean residual of open bins
    // (keeps residuals homogeneous so future items can match many bins)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when good fitting bins exist, more so early on
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 50.0 + 30.0 * (1.0 - progress);
        } else {
            score -= 5.0;
        }
    }

    // Mild penalty for accumulating many open bins late in the stream
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored: reward near-zero post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward residuals that can still host the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 2.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space penalty grows with how much is wasted relative to next item.
            let waste = (post_residual as f64).max(0.0);
            score += 0.8 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when many bins are already open and fitting ones exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 18.0 * pressure + 10.0 * (1.0 - progress);
        // New bin is acceptable when mean residual across open bins is low (all bins full-ish).
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Slight preference for fuller bins overall (lower residual relative to mean).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(-30.0).min(30.0) * 0.1;

    // Mild time decay: early on, be more conservative about fragmenting bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount small post_residual (quadratic coupling).
    let pr = post_residual as f64;
    score -= (1.0 - pr / cap).powi(2) * cap * 0.55;

    // Smooth progress term: later in stream, favor filling bins more aggressively.
    score -= (pr / cap) * (1.0 - pr / cap) * progress * cap * 0.35;

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= fit_quality * fit_quality * cap * 0.8;
    } else if next_item_size > post_residual {
        // Penalize leaving a residual that wastes space against the lookahead.
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * 0.9;
    }

    // New-bin candidate: mild penalty so we only open when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += cap * 0.5 + mean_residual * 0.15 * (1.0 - progress);
    }

    // Deter scattering residual across many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 6.0;

    // Penalize post_residual that is unusably small relative to typical item sizes.
    score += ((pr / 10.0).floor() * 10.0 - pr).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: bins whose residual falls in small-modulo
    // classes (e.g. residual % 10 == 0) are easier to fill later -> reward them.
    let pr = post_residual;
    let class_bonus = match pr % 10 {
        0 => 12.0,
        1 | 2 | 3 | 4 | 5 => 6.0,
        6 | 7 | 8 | 9 => 0.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: penalize residuals that cannot host any
    // plausible future item (below the minimum useful size).
    if pr > 0 && pr < 10 {
        score += 25.0; // dead space class
    }

    // Lookahead coupling: strongly reward exact fit of the next item.
    if next_item_size > 0 && pr >= next_item_size {
        let slack = (pr - next_item_size as u32) as f64;
        score -= 15.0 + 10.0 * (1.0 - slack / cap);
        if pr == next_item_size {
            score -= 20.0; // perfect two-item packing
        }
    } else if next_item_size > 0 && pr > 0 {
        score += 5.0; // next item cannot use this bin's leftover
    }

    // Fractional residual term: prefer tight fills relative to capacity.
    score += 8.0 * (1.0 - (item_size as f64) / cap) * (post / cap);

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mean-residual anchor: pull score toward bins near the fleet mean
    // (preserves a balanced residual distribution across open bins).
    score += 0.3 * (post - mean_residual).abs();

    // Early stream: keep bins openable (mild penalty on very full bins early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post < 10.0 {
        score += 5.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin
    // fits well (large post_residual means we are comparing against empty bin).
    if bin_residual == bin_capacity {
        score = cap as f64 * 0.55 - 8.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && (bin_capacity as u32) >= next_item_size + item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // future items (sizes >= 1) are pure loss; especially gaps below ~10.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0; // barely usable, low utility
    }

    // Reward tight fits (post_residual near zero but not sliver).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    if fill > 0.9 {
        score -= 40.0;
    } else if fill > 0.75 {
        score -= 20.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead coupling: if post_residual exactly matches next item, huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0; // gap that cannot host lookahead item
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize placements into bins when many bins are open
    // and residual is far above mean (encourages consolidation).
    let dev = bin_residual as f64 - mean_residual;
    if open_bins_count > 4 && dev > 0.0 {
        score += 0.15 * dev;
    } else if open_bins_count > 4 && dev < 0.0 {
        score += 0.15 * dev; // favors low-residual (fuller) bins
    }

    // New-bin candidate: make it attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        // New empty bin baseline: post_residual = capacity - item_size.
        // Penalize opening new bins mildly so tight fits into open bins win.
        score -= 10.0;
        if bad_fit > 0.7 {
            // small item into new bin: discourage unless no good open option
            score += 15.0 * bad_fit;
        }
    }

    // Stream progression: late in stream, be more conservative with new bins.
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 20.0 * t;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        // Perfect chain: next item exactly fills this bin.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else {
        // Last item: prefer minimal waste.
        score += 25.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Tight fits are good: penalize large dead space relative to capacity.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Compare against mean residual: filling a bin below average residual tightens the pool.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.3 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
    }

    // Early in stream, consolidation is cheap; late, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward filling bins snugly (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Exact or near-exact fits get a strong bonus.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Dead space penalty: residual too small to fit even the smallest plausible item.
    if post_residual < 5 {
        score += 30.0;
    }

    // Lookahead: penalize wasting space the next item could have used.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // bin remains useful for the lookahead item
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 18.0; // this placement blocks the next item's fit here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only when
    // existing fits are poor or few bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64); // = 0 for empty bin
        let pressure = mean_residual / bin_capacity as f64;
        // Prefer new bin when mean residual is high (bins fragmented) or early stream.
        let new_bin_bonus = 20.0 + 30.0 * (1.0 - pressure) + 25.0 * (1.0 - progress);
        score -= new_bin_bonus * (1.0 - fit_quality);
        // Discard pathological new-bin opening when plenty of tight fits exist.
        if open_bins_count > 0 && pressure < 0.25 {
            score += 15.0;
        }
    } else {
        // Prefer bins with residual below the mean (consolidate fragmentation).
        score += 0.5 * (mean_residual - bin_residual as f64);
        // Slight penalty when many bins are open, encouraging consolidation.
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: quadratic waste in post-residual (dead space grows super-linearly).
    let mut score = post * (1.0 + 0.012 * post / cap);

    // Smooth progress coupling: as the stream advances, waste matters more,
    // so amplify the quadratic term with a cubic-in-progress factor.
    score *= 1.0 + 0.9 * progress * progress * (3.0 - 2.0 * progress);

    // Reward tight fits: subtract a smooth function of fill ratio.
    let fill = (bin_residual as f64 - post) / cap;
    score -= 18.0 * fill * fill * fill;

    // Penalize post-residual that cannot accommodate typical future items:
    // smooth interaction with mean residual of open bins.
    let mean_r = mean_residual.max(0.0);
    score += 0.35 * (post - mean_r).abs();

    // Lookahead: reward leaving room for the next item smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = post - n;
        score -= 6.0 * (gap / cap).tanh();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins fit,
    // with a smoothly decaying penalty as the stream progresses.
    if bin_residual == bin_capacity {
        let decay = (1.0 - progress).powi(2);
        score += 25.0 * decay + 2.0 * open_bins_count as f64;
    }

    // Mild penalty for many open bins, encouraging consolidation early.
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction bands
    let band = post_residual / (bin_capacity / 4).max(1); // 0..4 harmonic class
    score += band as f64 * 6.0;

    // Reward near-perfect fits (post_residual in small harmonic class)
    if post_residual <= bin_capacity / 10 {
        score -= 25.0;
    }
    // Penalize awkward dead space: residual that no typical item (1..=100) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: does post_residual accommodate next item?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64 / cap) * 10.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer fuller bins when many bins are open
    score -= (1.0 - bin_residual as f64 / cap) * 15.0;

    // Mild pressure toward consolidation as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Discard deviation from mean residual (avoid fragmenting)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: penalize opening unless nothing fits well
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small residuals that most future items (10..80) can't use.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Tight fits are excellent: reward heavily.
    score -= (bin_capacity as f64 - post_residual as f64).powi(3) / (bin_capacity as f64).powi(2);

    // Open-bin pressure: prefer reusing bins when many are open.
    if bin_residual != bin_capacity {
        score -= 8.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Opening a new bin is fine only if it yields a perfect or near-perfect fit
        // or no existing bin fits well.
        if post_residual == 0 {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: bins far below mean residual are worse to break.
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev.abs();

    // Early stream: be more conservative, keep bins balanced.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits (small post_residual already does this).

    // Aggressive 2-step lookahead: strongly reward exact or near-exact
    // match between post_residual and the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            // Perfect 2-chain: place here almost certainly.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can follow in this bin; reward closeness of the match.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot follow; penalize dead space proportional to gap.
            score += 0.5 * gap;
        }
    } else {
        // Last item: only tightness matters.
        score -= 10.0;
    }

    // Relative tightness against mean residual across open bins:
    // bins with residual well below the mean are "scarce space" — using
    // them is good; bins far above mean are loose — deprioritize slightly.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a good lookahead chain.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count == 0 { 1.0 } else { mean_residual / bin_capacity as f64 };
        // Opening a new bin is good when open bins are nearly full on average
        // and the current item would leave a large unusable gap elsewhere.
        let gap_elsewhere = post_residual as f64; // = capacity - item for empty bin
        score = gap_elsewhere - 20.0 * open_pressure;
        if next_item_size > 0 && next_item_size <= item_size {
            // A fresh bin can likely host the next item too.
            score -= 15.0;
        }
    }

    // Late-stream consolidation: as the stream ends, prefer filling existing
    // bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: penalize leaving a residual that cannot host the next item
    // (dead space), reward residuals that can chain with the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * post_residual as f64;
        } else {
            score += 6.0 + 0.10 * (next_item_size as f64 - post_residual as f64);
        }
        // If next item fits exactly in post_residual, strongly reward.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit. Penalize the empty-bin candidate, but less
    // when existing residuals are large (poor fits everywhere) or many bins are open.
    if bin_residual == bin_capacity {
        score += 20.0;
        score -= 0.15 * mean_residual;
        score -= 0.5 * open_bins_count as f64;
        // Early in the stream, opening fresh bins is cheap and useful.
        score -= 10.0 * (1.0 - progress);
    }

    // Penalize creating tiny unusable slivers relative to the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Global pressure: many open bins with high mean residual -> encourage
    // consolidating into existing bins (penalize new-bin tendency implicitly,
    // reward filling bins with residual above mean).
    if (bin_residual as f64) > mean_residual && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Time horizon: late in the stream, be greedy about waste; early, keep options open.
    score *= 1.0 + 0.5 * progress;

    // Mild penalty for very loose fits (wasting more than half the bin).
    if post_residual as f64 > 0.5 * bin_capacity as f64 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;

    // Smooth non-linear tight-fit reward: reward small post_residual quadratically,
    // scaled by stream progress (later items pack tighter).
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual: leaving more than average
    // waste is bad, leaving less is good (smooth cubic coupling).
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev * dev.abs().sqrt() * (1.0 + progress);

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 10.0 * (1.0 - gap / cap) * (1.0 + progress);
        } else {
            score += 4.0 * (gap / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a new bin only when post_residual would be
    // large (poor fit elsewhere) or many bins already exist late in the stream.
    if bin_residual == bin_capacity {
        let waste_pressure = fit / cap;
        score = 20.0 + 30.0 * (1.0 - waste_pressure) * (1.0 - progress)
              - 10.0 * (open_bins_count as f64 / (1.0 + progress * 20.0)).min(1.0);
        // Empty-bin post residual equals capacity minus item; keep it competitive
        // only if it leaves a nicely reusable gap.
        score += 5.0 * (1.0 - (post / cap));
    }

    // Mild penalty for very small unusable slivers (< ~10% capacity) late in stream.
    let sliver = (post / cap - 0.1).max(0.0);
    score += 6.0 * (1.0 - progress) * (1.0 - sliver / 0.1).max(0.0) * (post / cap).min(1.0) * 0.0
           + 6.0 * progress * (1.0 - (post / 10.0).min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold: decile class
    let residue = pr % 10;

    // Perfect fit class (post_residual == 0) strongly rewarded.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: residual too small to hold any plausible item.
        let min_item = 1.0;
        if (pr as f64) < min_item + residue as f64 * 0.1 {
            score += 50.0;
        }
        // Reward residuals that can still host the lookahead item exactly-ish.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 400.0;
            } else if next_item_size < pr {
                score -= 30.0 + (pr - next_item_size) as f64 * 0.5;
            } else {
                // Lookahead doesn't fit: penalize proportional to wasted potential.
                score += (next_item_size - pr) as f64 * 0.3;
            }
        }
        // Harmonic decay: prefer bins whose class leaves divisible-friendly space.
        score -= (class as f64) * 2.0;
        score += residue as f64 * 0.4;
    }

    // Last-chance bonus: only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin early.
    if bin_residual == bin_capacity {
        score += 60.0 + 10.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 20.0;
        }
    }

    // Stream-phase coupling: tighten packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // Nudge toward mean residual balance.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits relative to bin capacity.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Open-bins pressure: discourage scattering when many bins are open.
    score += 2.5 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (avoid wasting large bins on small items).
    score += 0.2 * (bin_residual as f64 - item_size as f64).abs();

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into the resulting residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Residual too small for the next item: penalize mildly.
        score += 15.0;
    }

    // Mean residual alignment: prefer bins below the mean residual (tighter bins first).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate handling: only attractive early or when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = if fitting_bins_count == 0 { 100.0 } else { 0.0 };
        score = 100.0 + 150.0 * progress + desperation - 30.0 * (1.0 - fit_ratio);
        if fitting_bins_count == 1 {
            score += 80.0; // don't abandon the last-chance bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward post_residual matching next item
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 90.0 * (-gap / 12.0).exp();          // exact chain reward
        score += 0.35 * gap;                          // smooth penalty for mismatch
        // penalize leaving residual that can't fit the next item
        if post_residual < next_item_size {
            score += 25.0 * (next_item_size - post_residual) as f64 / 50.0;
        }
    }

    // Relative to mean residual: avoid dumping into unusually full bins
    let dev = (bin_residual as f64 - mean_residual) / (mean_residual + 1.0);
    score += 20.0 * dev; // bins with residual above mean get penalized

    // Dead-space penalty: very small unusable residue
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let forced = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size);
        if forced {
            score -= 55.0;
        } else {
            score += 70.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Late-stream consolidation: reuse bins more aggressively toward the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 25.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize small dead space that nothing can use (items >= 1, so any
    // residual is technically usable, but tiny residuals are wasteful).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving medium leftovers.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * fill;
    }

    // New-bin candidate handling: opening a fresh bin is attractive when
    // current bins fit poorly, but wasteful early in the stream or when
    // many bins are already open with plenty of room.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_room = mean_residual / bin_capacity as f64;
        score = bin_capacity as f64 * 0.9;
        score += 30.0 * progress;                 // later => prefer new bins less
        score -= 25.0 * avg_room;                 // roomy open bins => new bin is bad
        score -= 12.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count <= 1 {
            score += 15.0;                        // no good alternative => new bin ok
        }
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 10.0;                        // fresh bin can host a pair
        }
    }

    // Mild global pressure: when mean residual is low overall, conserve
    // space by preferring bins that stay compact after placement.
    let global_tightness = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
    score += 10.0 * global_tightness * (post_residual as f64 / bin_capacity as f64);

    // Slight preference to spread load across bins early (keeps options open).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear emphasis on tight fits.
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, dead space matters less; later, squeeze harder.
    let progress_weight = 0.5 + 4.0 * progress * progress;
    score += progress_weight * norm_pr * norm_pr;

    // Perfect-fit reward (smooth quadratic trough near zero residual).
    score -= 3.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * 0.0;

    // Penalize residual that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let unusable = ((nx - pr / cap) / cap).max(0.0);
        score += 2.0 * unusable * (1.0 + progress);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    score += 0.01 * open_bins_count as f64 * mean_residual / cap * progress;

    // New-bin candidate: keep it competitive only when open bins would waste space.
    if bin_residual == bin_capacity {
        score = 1.0 + progress * 2.0 + norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Dead-space penalty: residual that no realistic item (1..=100) can fill well.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 25 {
        score += 18.0; // only tiny items fit
    } else if post_residual < 50 {
        score += 6.0; // half-class: moderately usable
    } else if post_residual < 75 {
        score -= 2.0; // three-quarter class: very reusable
    } else {
        score -= 8.0; // near-empty class: excellent
    }

    // Reward tight fits (small post_residual in absolute terms).
    if post_residual == 0 {
        score -= 100.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Integer-division harmonic classes of post_residual (mod arithmetic flavor).
    let class = post_residual / 10; // decade class
    let class_penalty = (class % 3) as f64 * 3.0; // penalize awkward decades cyclically
    score += class_penalty;

    // Lookahead coupling: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward proportionally to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - slack / cap * 10.0;
        } else {
            // next item won't fit: penalize more if residual is "almost enough"
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 14.0; // teasing near-miss wastes the bin
            } else {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing space rather than opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are underutilized or stream is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 4.0;
        // But if mean residual is small (open bins nearly full), opening is fine.
        score -= (mean_residual / cap) * 25.0;
    } else {
        // Existing bin: mild reward scaled by how full it already is.
        let fill = (bin_capacity - bin_residual) as f64 / cap;
        score -= fill * 5.0;
        // Crowding bonus: with many open bins, filling existing space is valuable.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Fine-grain tie-break: prefer exact quarter/eighth harmonic residuals.
    let diff_q = (pr - (pr / quarter).round() * quarter).abs();
    let diff_e = (pr - (pr / eighth).round() * eighth).abs();
    score -= (8.0 - diff_q / quarter * 4.0).max(0.0);
    score -= (4.0 - diff_e / eighth * 2.0).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be useful.
    // Residuals below the minimum plausible item size are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.6;
    }

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 18.0;

    // If this bin is the last chance to avoid opening a new bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few open bins, new-bin is cheap.
    score += (open_bins_count as f64) * 1.2;

    // New-bin candidate handling: make empty bins moderately attractive only
    // when the fit is poor or many bins are already open.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > mean_residual.max(1.0);
        if poor_fit && open_bins_count > 2 {
            score -= 14.0;
        } else {
            score += 10.0;
        }
    }

    // Lookahead: if next item could exactly fill this bin's post_residual,
    // strongly reward keeping this residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Slight progression bias: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: bin closes perfectly after next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near-matches of the lookahead.
    if next_item_size > 0 && post_residual > next_item_size {
        score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }
    // Penalize leaving large dead space relative to mean residual across bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.5 * (pr - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - pr);
    }

    // Tight-fit reward: item nearly fills the bin now.
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= 20.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent alternatives exist,
    // unless the item fits nothing well (large post_residual on new bin is fine early).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let new_bin_penalty = 35.0 * (1.0 - progress);
        score += new_bin_penalty;
        // If the next item would fit perfectly in the fresh bin anyway, soften penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward near-perfect fills aggressively (non-linear coupling)
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += waste_ratio * waste_ratio * 120.0; // penalize large dead space quadratically
    }

    // Small residual that can still host typical items is more valuable than big residual
    if post_residual > 0 && post_residual < 20 {
        score += 15.0; // tiny slivers are likely dead space
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this placement (sets up a chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 / (1.0 + slack);
        } else {
            // next item won't fit here; penalize less if residual is large enough to matter later
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 80.0 * tightness;
    }

    // New-bin candidate logic: opening a new bin is only attractive early in the
    // stream or when many open bins already exist and mean residual is low.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its residual is maximal, so score is high already.
        // Discount it slightly when open bins are scarce or stream is early.
        let scarcity = 1.0 / (1.0 + open_bins_count as f64);
        score -= 90.0 * scarcity * (1.0 - progress);
        // If mean residual across open bins is small (they're all nearly full),
        // a new bin is genuinely needed.
        if mean_residual < item_size as f64 {
            score -= 70.0;
        }
        // If no open bin fits (fitting_bins_count == 0 among open bins), opening is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Placing into an existing bin: reward more when bins are plentiful.
        score -= 10.0 * (1.0 - 1.0 / (1.0 + open_bins_count as f64));
    }

    // Mild time-horizon drift: later in the stream, consolidate harder into
    // existing bins (avoid spreading), so penalize new bins more over time.
    if bin_residual == bin_capacity {
        score += 50.0 * progress;
    } else {
        score -= 25.0 * progress * (item_size as f64 / bin_capacity as f64);
    }

    // Mean-residual global coupling: prefer bins whose residual deviates
    // favorably from the fleet mean (below mean = tighter bin, good to fill).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.3 * dev; // tighter-than-average bins get rewarded
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: squared normalized post-residual
    let post_norm = post / cap;
    score += 12.0 * post_norm * post_norm * cap;

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 10.0 * (1.0 - post_norm);
    } else if next_item_size > 0 {
        // penalize leaving residual that blocks the next item
        score += 6.0 * (next_item_size as f64 - post) / cap;
    }

    // Stream progress coupling: later in stream, be more frugal with new bins
    let progress_term = progress * progress * (1.0 - progress);
    score -= 15.0 * progress_term * (bin_residual as f64 / cap);

    // Crowd penalty: many open bins -> discourage spreading; few bins -> encourage consolidation
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += crowd * post_norm * 8.0;

    // Mean residual attraction: prefer bins near mean residual (balanced usage)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: make it moderately attractive only when it truly helps
    if bin_residual == bin_capacity {
        score += 14.0 * (1.0 - progress);
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 measure dead-space quality.
    let pr = post_residual as i64;
    let residue = pr % 10;
    // Residue 0 (multiple of 10) is ideal for future items (sizes are multiples of 10 typically)
    score -= match residue {
        0 => 18.0,
        5 => 6.0,
        _ => -(residue as f64) * 0.4, // small residues mildly penalized
    };

    // Integer division thresholds: large post_residual chunks are more reusable.
    let chunk = pr / 20; // how many 20-sized chunks still fit
    score -= chunk as f64 * 4.0;

    // Perfect fit bonus scaled by how tight the fit is (capacity fractions).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 30.0 + 20.0 * fill_ratio;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nres = post_residual - next_item_size;
            // harmonic class of the double placement remainder
            score -= match (nres % 10, nres / 10) {
                (0, 0) => 25.0,
                (0, _) => 12.0,
                (r, _) => (10 - r as i64) as f64 * 0.5,
            };
        } else {
            // next item cannot follow here; penalize slightly unless this is last-chance bin
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a mild handicap so existing good fits win,
    // but becomes attractive when open bins are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 10.0 - fragmentation.min(10.0);
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    } else {
        // prefer bins whose residual is below mean (tighter bins get closed out first)
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= dev.min(20.0) * 0.3;
        }
    }

    // Many open bins: reward placements that finish bins to allow consolidation.
    if open_bins_count > 4 && post_residual < 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable gap penalty
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item can use the residual exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // residual too small for next item: mild extra penalty proportional to waste
            score += 0.3 * post_residual as f64;
        }
    }

    // Last chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate handling: empty bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 60.0; // no real alternative: opening new bin is fine
        }
    }

    // Prefer bins whose residual is close to the mean (balance load).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    // Tightness reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
