pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: residuals too small for any future item (1..100) are wasted.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: reward leaving exactly enough room for the next item,
    // penalize leaving a gap that just barely fails to fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 12.0 * (miss / 100.0).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this is a poor fit elsewhere.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
        let early = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 20.0 * early - 15.0 * pressure.min(3.0);
        if next_item_size > 0 && next_item_size > bin_residual {
            score += 100.0; // never open a new bin that cannot even take next item
        }
    }

    // Mild global fragmentation penalty: prefer bins with residual near the mean
    // to keep residuals balanced and combinable.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for opening fewer bins as the stream progresses.
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Base: quadratic waste penalty on post_residual (dead space is costly).
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Smooth coupling: large post_residual hurts more late in the stream
    // (less opportunity to fill it), reward tight fits slightly more early.
    let progress_coupling = (pr / cap) * (0.5 + 1.5 * progress);
    score += 30.0 * progress_coupling;

    // Cubic saturation term: extreme waste is heavily penalized, smoothly.
    score += 8.0 * (pr / cap).powi(3);

    if is_new_bin {
        // Opening a new bin: penalize smoothly, but relax if the item fits badly
        // everywhere (few fitting bins) and the fit in a fresh bin is decent.
        let scarcity = (fitting_bins_count as f64).recip();
        let fit_quality = 1.0 - (pr / cap);
        score += 25.0 * (1.0 - scarcity * fit_quality);
        // Late in stream, prefer consolidation into open bins more strongly.
        score += 15.0 * progress;
    } else {
        // Reward using an existing bin, scaled by how many alternatives exist.
        let alt = if fitting_bins_count > 1 { 1.0 / (fitting_bins_count - 1) as f64 } else { 1.0 };
        score -= 10.0 * alt;
        // Bonus if this bin's post_residual exactly accommodates the next item
        // (smooth, continuous reward via overlap measure).
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            let overlap = (pr - (pr - nx).abs()) / nx.max(1.0);
            score -= 6.0 * overlap.clamp(0.0, 1.0);
        }
    }

    // Gentle pull toward bins with residuals below the mean (consolidate small gaps).
    score -= 3.0 * ((mean_residual - pr) / cap).clamp(-1.0, 1.0);

    // Slight preference for keeping open-bin count low.
    score += 0.5 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common item sizes) are less penalized.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus = 40.0; // perfect fit: strongly reward
    } else if pr <= 10 {
        class_bonus = 12.0; // small dead space, still bad-ish but compact
    } else {
        // usable leftover classes: 20,25,30,40,50,60,75 etc.
        let usable = pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0;
        if usable {
            class_bonus = 10.0 + (pr as f64) * 0.05;
        } else {
            class_bonus = -6.0; // awkward leftover class: penalize
        }
    }
    score -= class_bonus;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // reward tight fits for the future item, scaled by how structured
            // the double-leftover is
            score -= 25.0 - slack * 0.3;
            if (pr % next_item_size.max(1)) == 0 {
                score -= 8.0; // divisible leftover: harmonic reuse likely
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // badly fragmented or it's early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            0.0
        };
        score = bin_capacity as f64 * (0.9 + 0.4 * fragmentation) - 30.0 * (1.0 - progress);
        // allow new bin when item is huge and would leave tiny residue anyway
        if item_size >= bin_capacity * 9 / 10 {
            score -= 15.0;
        }
    }

    // Prefer filling fuller bins overall (tightness coupling).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Slight preference for bins below mean residual (keeps balance of slack).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild late-stream pressure to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer small post_residual (tight fit)
    score += post_residual as f64;

    // Strict dead-space penalty: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is too small to plausibly fit a future item.
    let min_item = 1.0f64;
    let dead_threshold = (min_item * 2.0).max(6.0);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residuals that still fit the lookahead item (k=2 lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        // post_residual cannot hold next item -> future dead space risk
        score += 6.0;
    }

    // Open bins pressure: discourage proliferating bins when alternatives exist
    score += open_bins_count as f64 * 0.7;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: avoid leaving this bin far below the average residual
    // (keeps residual distribution balanced, avoids many half-empty bins)
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Penalize opening a new bin, but less when open bins are crowded (mean residual low)
    // or when the current item barely fits any open bin.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let crowding_pressure = (1.0 - crowding).clamp(0.0, 1.0);
        score += 30.0 - crowding_pressure * 22.0;
        // If next item won't fit alongside in the new bin either, opening is fine
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 4.0;
        }
    }

    // Slight preference for bins with less residual among equally tight fits
    score += bin_residual as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression factor: be greedier (tighter packing) later in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward exact match between post_residual and next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain match: strong reward.
        if diff == 0.0 {
            score -= 30.0 + 20.0 * progress;
        } else {
            // Penalize leftover space that cannot hold the next item (dead space).
            if (post_residual as i64 - next_item_size as i64) < 0 {
                score += 8.0 + 0.3 * post_residual as f64;
            } else {
                // Leftover can fit next item, but reward tighter couplings.
                score -= (15.0 * (1.0 - diff / bin_capacity as f64)) * (0.5 + progress);
            }
        }
    }

    // Relative to mean residual: prefer bins with residuals near/below mean (fill fuller bins).
    let resid = post_residual as f64;
    let mean_term = resid - mean_residual;
    score += 0.15 * mean_term;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let mut penalty = 12.0 + 5.0 * (fitting_bins_count as f64).ln().max(0.0);
        // If next item chains perfectly with the fresh bin after this item, allow opening.
        if next_item_size > 0 && (next_item_size as i64 - post_residual as i64).abs() <= 2 {
            penalty -= 18.0;
        }
        score += penalty;
    }

    // Slight bonus for very tight fits (small absolute waste).
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powf(3.0);

    // Penalize dead space that cannot be used by the next item
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 + 0.25 * (post_residual as f64);
        } else if post_residual >= next_item_size {
            score -= 6.0; // this bin can likely serve the next item too
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild penalty to break ties toward emptier bins via other terms
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Compare bin residual against mean residual: prefer bins below mean residual
    // (i.e., fuller bins) to keep many loose bins available for future items
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Time horizon: early in stream, favor spreading items (open new bins cheaply);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_bias = 20.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bias;
        // discourage opening new bin when a good fit exists elsewhere
        if post_residual < 20 {
            score += 15.0;
        }
    }

    // Penalize opening too many bins relative to items processed
    if open_bins_count > 0 {
        let ratio = open_bins_count as f64 / (step_index.max(1) as f64 + 1.0);
        if bin_residual == bin_capacity {
            score += 10.0 * ratio;
        }
    }

    // Slight preference for bins with residuals in "useful" modular ranges
    let r = post_residual as f64;
    if r > 0.0 && r <= 10.0 {
        score -= 8.0; // near-perfect fill
    } else if r > 50.0 {
        score += 3.0; // leaving large holes is wasteful
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear progress coupling: penalize large residuals more as stream progresses
    let progress_weight = 0.5 + t * t;
    score += progress_weight * (pr / c) * (pr / c) * 20.0;

    // Cubic interaction of fill fraction with progress
    let fill = 1.0 - pr / c;
    score -= fill * fill * fill * 15.0 * (0.3 + 0.7 * t);

    // Mean residual deviation penalty (smooth)
    let dev = (pr as f64 - mean_residual) / c;
    score += 8.0 * dev * dev * (1.0 + t);

    // Lookahead: reward leaving residual that can host next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 6.0 * (ni / c) * (1.0 - t * 0.5);
        } else {
            score += 4.0 * ((ni - pr) / c) * (1.0 - t);
        }
    }

    // Last-chance bin: strong reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - t * t);
    }

    // Many open bins: mild penalty for tiny residuals (fragmentation)
    let ob = open_bins_count as f64;
    score += (pr / c) * ob * 0.5 * t;

    // New-bin candidate: neutral-ish baseline, discouraged unless residuals are tiny
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * t * (1.0 - fill);
        if next_item_size as f64 >= c * 0.5 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands in
    // "small dead-space" classes are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0; // near-perfect, likely unusable anyway but small
    } else if pr <= 20 {
        score -= 12.0;
    } else if pr <= 30 {
        score += 4.0;
    } else if pr <= 50 {
        score += 10.0;
    } else {
        score += 18.0; // large residual wasted on a big item
    }

    // Modulo harmonic classes: residuals that are multiples of common item
    // sizes (10/20/25/50) tend to be re-usable by future items.
    if pr > 0 && (pr % 10 == 0) {
        score -= 6.0;
        if pr % 50 == 0 { score -= 4.0; }
        else if pr % 25 == 0 { score -= 2.5; }
    } else if pr > 0 && pr % 5 == 0 {
        score -= 2.0;
    } else {
        score += 3.0; // awkward non-harmonic leftover
    }

    // Integer-division threshold: residual in the "half-bin" band is prime
    // real estate for medium items.
    let half = bin_capacity / 2;
    if pr == half {
        score -= 8.0;
    } else if pr > half {
        score += 6.0;
    }

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            score -= 10.0 + (slack as f64).min(20.0) * 0.3;
            if pr == next_item_size { score -= 6.0; }
        } else {
            // residual too small for next item: penalize less if it's tiny
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the final fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // residuals are poor fits (large leftover would be created).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64;
        // Base penalty keeps new bins from winning trivially.
        score += 30.0 + 8.0 * crowded.min(10.0);
        // Late in the stream, or when mean residual is small, opening up
        // is less attractive.
        score += 20.0 * (1.0 - progress);
        if mean_residual < item_size as f64 + 5.0 {
            score -= 35.0; // existing bins are nearly full -> prefer them
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0; // fresh bin guarantees next-item room
        }
    } else {
        // Slight preference for bins whose residual deviates from the mean
        // in the "more full" direction.
        let dev = mean_residual - bin_residual as f64;
        score += dev.clamp(-30.0, 30.0) * 0.15;
    }

    // Tie-break noise-free deterministic micro-adjustment on item class.
    match item_size / 10 {
        0 => score -= 1.0,
        1 => score -= 0.5,
        6 | 7 => score += 1.0,
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward residuals that can still host a plausible future item (>= ~10).
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead: if next item fits the post-residual, this placement is valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if bin_residual >= next_item_size {
            // keeping next item's option open in this bin is mildly good
            score -= 3.0;
        } else {
            score += 5.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer reusing rather than spreading.
    let pressure = (open_bins_count as f64).ln() * 6.0;
    score -= pressure * (1.0 - fill_ratio);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Mean-residual coupling: bins far below mean residual are less attractive
    // (save the roomier bins for larger future needs).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.3 * dev;
    } else {
        score -= 0.15 * (-dev);
    }

    // New-bin candidate: opening a new bin should only win when open-bin fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0 + pressure + 20.0 * progress;
        if post_residual >= 50 {
            score += 10.0; // fresh bin with lots of room is worse early on
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match: strong reward proportional to next item size.
        if diff == 0.0 {
            score -= 60.0 + nxt;
        } else if post_residual as f64 >= nxt {
            // Next item still fits after this placement: mild reward scaled by tightness.
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to shortfall.
            score += 10.0 + diff * 0.5;
        }
    }

    // Tightness reward: small post_residual relative to bin capacity is good (unless wasted).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * tightness;

    // Penalize creating dead space far from mean residual (fragmentation risk).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score -= 1.5 * open_bins_count as f64 * tightness;

    // Progression: as stream advances, prefer filling bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Base penalty so opening new bins is not preferred when decent fits exist.
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if next_item_size > 0 && post_residual >= bin_residual {
            // Keep near-neutral so a very poor existing fit can still lose.
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
