            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; penalize more if we waste a lot of space.
            score += 4.0 * (pr / cap);
        }
    } else {
        // Last item: just minimize post residual aggressively.
        score -= 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mean-residual divergence: prefer bins whose residual is below average
    // (close them out), penalize draining already-empty bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 8.0;

    // Time horizon: early in stream, be more willing to open/spread bins;
    // late in stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0 * (pr / cap);
    score += progress * 2.0 * (pr / cap);

    // Penalize opening a new bin when open bins can fit and pressure is low.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let pressure = fitting_bins_count as f64;
        score += 5.0 + 3.0 * (1.0 - progress) - pressure.min(3.0);
        // But allow a new bin if the fit in existing bins would be terrible.
        if item_size as f64 / cap > 0.7 {
            score -= 6.0;
        }
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth non-linear waste penalty: dead space becomes costlier as it grows.
    let waste_frac = post / cap;
    score += 8.0 * waste_frac * waste_frac * cap;

    // Reward tight fits (small post_residual) more strongly over time.
    score -= (1.0 - waste_frac).powi(3) * (6.0 + 10.0 * progress);

    // Penalize residuals that cannot accommodate typical future items,
    // with smooth coupling to stream progress.
    let unusable = ((next_item_size as f64) - post).max(0.0) / cap;
    score += 12.0 * unusable * (0.5 + progress);

    // If next item fits perfectly after this placement, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when open bins are mostly full
    // (high mean residual spread) or few bins are open.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        score += 14.0 * (1.0 - mean_frac) * (1.0 - mean_frac);
        score += 6.0 * (open_bins_count as f64).ln().max(0.0);
        score -= 8.0 * progress;
    } else {
        // Prefer bins whose residual is below the mean (consolidate emptier space).
        score += 3.0 * (post - mean_residual) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: bucket post_residual into capacity-fraction classes.
    // Residuals in "dead" classes (too small for typical items 10..80) are penalized.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    if post == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else if post < eighth {
        // dead space below smallest plausible item
        score += 25.0 * (1.0 - post as f64 / eighth as f64);
    } else if post < quarter {
        score -= 10.0; // reusable small pocket
    } else if post < bin_capacity / 2 {
        score -= 5.0;
    } else {
        // large residual left: item was small relative to bin, mild penalty
        score += 6.0;
    }

    // Lookahead coupling: reward if post_residual can host next_item_size exactly-ish.
    if next_item_size > 0 && post >= next_item_size {
        let slack = post - next_item_size;
        if slack == 0 {
            score -= 45.0; // next item then closes this bin perfectly
        } else if slack < eighth {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size >= post && next_item_size <= bin_capacity {
        // next item cannot use this pocket; if pocket is mid-sized it is stranded
        if post >= eighth && post < quarter {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only good when this bin's
    // post-fit would be poor or when many bins already fit the item poorly.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        let mut new_bin_score = 70.0;
        // early in stream: cheap to open bins; late: expensive
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 60.0 * progress;
        // if few bins fit the item, opening a new one is less wasteful
        new_bin_score -= 10.0 * fitting_bins_count as f64;
        // if mean residual is high, prefer reusing existing bins
        new_bin_score += 0.5 * mean_residual;
        score = score.max(new_bin_score);
    }

    // Modulo-harmonic tiebreaker: prefer post_residual divisible into nice classes
    let m = post % quarter.max(1);
    score += 2.0 * (m as f64 / quarter.max(1) as f64);

    // Slight preference for bins whose residual is below mean (tighter packing)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold even the smallest
    // future item are pure waste — punish them heavily.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Smooth tightness reward: the smaller the gap, the better.
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if post residual is large enough for next item, mild bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += 8.0; // gap likely wasted w.r.t. lookahead
        }
    }

    // Open-bin pressure: discourage spreading across many bins, but relax
    // pressure as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).powf(1.3) * (0.35 - 0.2 * progress);
    score += pressure.max(0.0);

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.1 * post_residual as f64;
    }

    // New-bin candidate handling: an empty bin is attractive only when the
    // current item is large relative to capacity or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 12.0 * large_item;
        score += 0.25 * open_bins_count as f64;
        // Penalize opening new bins early in the stream.
        score += 10.0 * (1.0 - progress);
    }

    // Mild alignment with mean residual: prefer bins whose residual is below
    // average (tighter bins) to consolidate fragmentation.
    score += 0.05 * (mean_residual - bin_residual as f64).abs().signum()
        * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
        // Perfect match bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize residuals too small for the next item (dead space for lookahead)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward residuals close to mean_residual (keeps bin pool balanced)
    score -= 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist, unless fit is very tight
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 && fit_ratio < 0.85 {
            score += 30.0;
        } else if fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    // Mild reward for tight fits overall
    score -= 0.2 * (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual near zero is ideal.
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Penalize leaving dead space the next item cannot use.
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let avg_fit_gap = (mean_residual - item_size as f64).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 0.5 * open_bins_count as f64;
        if avg_fit_gap < 15.0 {
            score += 25.0; // an open bin fits well; don't open a new one
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 15.0 * progress;
    }

    // Mild penalty for bins with residual far from mean (keep pool homogeneous).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Prefer fuller bins generally.
    score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual (tight fit), with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: early on, waste matters less; late, demand tight packing
    let tightness = 0.5 + 1.5 * progress * progress;
    score *= tightness;

    // Smooth interaction between post_residual and progress (non-linear coupling)
    score += 12.0 * norm_pr * progress * (1.0 - progress) * 2.0;

    // Lookahead: reward leaving space for the next item (smooth gaussian-like affinity)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let affinity = (-(gap / 25.0) * (gap / 25.0)).exp();
        score -= 8.0 * affinity;
    }

    // Penalize bins that deviate from mean residual (encourage residual homogenization)
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Mildly discourage spreading across too many open bins
    score += 0.02 * open_bins_count as f64;

    // New-bin candidate: penalize opening a fresh bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 18.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: leftovers divisible into small chunks are reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Class the post_residual into harmonic buckets (integer division thresholds).
    let class = match pr {
        0 => 0.0,                       // perfect fit - strongly reward
        1..=5 => 1.0,                   // near-perfect, dead space tiny
        6..=15 => 2.0,                  // awkward small leftover
        16..=30 => 3.0,                 // mid leftover
        31..=50 => 4.0,                 // half-bin class
        _ => 5.0,                       // large leftover
    };
    score += class * 7.0;

    // Modulo arithmetic: leftovers that are multiples of common item sizes are "harmonic".
    let harmonic_bonus = if pr == 0 {
        -30.0
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // next fits: leftover after next is the real dead space
            let next_pr = pr - next_item_size;
            score += next_pr as f64 * 0.6;
            if next_pr == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize proportional to gap
            score += (next_item_size - pr).min(40) as f64 * 0.35;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes mean_residual potential.
    if bin_residual == bin_capacity {
        // base penalty so a fresh bin is only chosen when open bins leave bad fits
        score += 45.0;
        // early in stream, or many open bins with high residual => keep closing old bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 10.0;
        score += open_bins_count as f64 * 2.0;
        // if item is small, a new bin is wasteful
        if item_size < 40 {
            score += 15.0;
        }
    }

    // Prefer tighter fits generally (residual proximity).
    score += (bin_residual - item_size) as f64 * 0.1;

    // Small tie-breaker toward bins below mean residual (consolidating emptier bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
