    // New-bin candidate handling: brand-new empty bin
    if bin_residual == bin_capacity {
        // default mild penalty so we prefer decent existing fits
        score += 12.0;
        // but if the item is large relative to capacity, a fresh bin is great
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
