        let tightness = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Opening a bin is good when existing bins are tight (small residuals) or many bins open.
        let open_bonus = tightness * 30.0 + (open_bins_count as f64).min(10.0) * 2.0;
        // Early in stream, mildly prefer consolidation; later, allow spreading.
        score = 25.0 + open_bonus - t * 10.0;
    }

    // Mild pressure to keep mean residual low: prefer bins with residual below mean.
    if !is_new_bin {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
