    // Reward tight fits: quadratic bonus shrinking as post_residual grows.
    let tightness = 1.0 - waste;
    score -= 8.0 * tightness * tightness * (1.0 - 0.5 * progress);

    // Lookahead coupling: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
