        }
        // Penalize leaving a residual just barely too small for the next item.
        if pr < next_item_size as f64 && pr > 0.0 {
            score += 4.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
