    // with a smooth sinusoidal coupling over progress.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (0.6 + 0.4 * (progress * std::f64::consts::PI).sin());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Harmonic class of the post residual: dead space in "useful" classes
    let class = post_residual / 10; // coarse harmonic class 0..10
    score += match class {
        0 => -50.0,                 // tiny dead space, fine
        1 => 5.0,
        2 => 12.0,
        3 => 20.0,
        4 => 28.0,
        5 => 34.0,
        6 => 40.0,
        7 => 46.0,
        8 => 52.0,
        9 => 58.0,
        _ => 0.0,                   // fresh/empty bin class
    };

    // Modulo-based dead-space penalty: residual that no typical item (1..100) pairs well with
    let m = post_residual % 10;
    score += m as f64 * 1.5;

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // good chain: reward proportionally to how well next item fills leftover
            let next_post = post_residual - next_item_size;
            score -= 60.0 + (next_post as f64).min(30.0);
        } else {
            // next item cannot follow here: penalize more when leftover is mid-range
            score += (post_residual as f64) * 0.4;
        }
        // exact pairing bonus (harmonic pair)
        if post_residual == next_item_size {
            score -= 150.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Empty new-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        // baseline penalty so it's chosen only when it beats bad fits
        score += 90.0;
        // more open bins -> less eager to open another
        score += open_bins_count as f64 * 8.0;
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
        // big next item makes a fresh bin attractive
        score -= next_item_size as f64 * 0.3;
    }

    // Slight preference for tighter existing bins
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio;

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New bin candidate: penalize so it is only chosen when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 55.0 + mean_residual * 0.3;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 10.0;
        } else if post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: this bin takes the item
    // AND the next item exactly fills what remains.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual >= next_item_size {
            // Partial lookahead credit: closer gaps are better.
            let gap = (post_residual - next_item_size) as f64;
            score -= 200.0 - gap.min(200.0);
            // Gentle penalty for leaving a gap the next item can't fully use,
            // scaled by how large the wasted sliver is.
            score += 0.3 * gap;
        } else {
            // post_residual < next_item_size: dead space the lookahead can't use.
            let dead = (next_item_size - post_residual) as f64;
            score += 2.0 * dead;
        }
    }

    // Penalize residual far below the mean residual (creates fragmented small holes)
    // and reward bins whose residual is already small (tight packing).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.2 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // If this is the last item, opening a bin is inevitable-ish but wasteful
        // if any bin fits; keep the cost high.
        if next_item_size == 0 {
            score += 50.0;
        }
        // When many bins already fit the item, opening a new one is bad.
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If the item is large relative to capacity, a fresh bin is more acceptable.
        score -= (item_size as f64 / bin_capacity as f64) * 80.0;
    }

    // Mild preference for placing into fewer total open bins (keep bin count low).
    score += 0.01 * open_bins_count as f64;

    // Slight time decay: early in the stream, be a bit more conservative
    // about wasting space; later, prioritize closure of bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_capacity as f64 - pr) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a nonlinear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize creating dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // hard to fill
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // If the next item cannot fit here, mildly penalize wasting a good bin now.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score -= 2.0 * pressure.min(10.0);

    // Time horizon: early in stream, prefer keeping residuals flexible (balanced);
    // late in stream, prioritize closing bins tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * t * (post_residual as f64 / 100.0);
    score -= (1.0 - t) * 5.0 * (1.0 - (bin_residual as f64 - post_residual as f64).abs() / 50.0);

    // New-bin candidate: only attractive when current bin fits are poor or none consolidate well.
    if bin_residual == bin_capacity {
        let avg_fit_quality = 1.0 - (mean_residual / bin_capacity as f64);
        // Opening a new bin is penalized mildly, but less when open bins have big residuals
        // that would be badly fragmented by this item.
        let poor_alternatives = if fitting_bins_count == 0 { 1.0 } else {
            (post_residual as f64 / bin_capacity as f64).min(1.0)
        };
        score = 60.0 + 40.0 * (1.0 - poor_alternatives) - 15.0 * avg_fit_quality * t;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0; // new bin can serve the next similar item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual

    // Base: prefer tight fits (small post_residual)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, leave room (penalize small residuals less? actually prefer flexible bins),
    // late in stream, strongly prefer near-zero residuals.
    let flex = pr * (1.0 - pr) * 4.0; // peaks at pr = 0.5, zero at edges
    score += flex * cap * (0.6 - 1.2 * progress).max(-0.6);

    // Quadratic decay of residual value as stream progresses
    score -= (pr * pr) * cap * progress * 0.8;

    // Reward using existing bins vs opening new bins, more strongly later
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new {
        score += cap * (0.35 + 0.5 * progress);
        // opening new bin is better if no bin fits tightly
        if post > 0.0 && pr > 0.35 {
            score -= cap * 0.15 * progress;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && !is_new {
        score -= cap * 0.5;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= (next_item_size as f64) * (0.3 + 0.4 * (1.0 - progress));
    } else if next_item_size > 0 {
        // dead space relative to next item: penalize
        score += (next_item_size as f64 - post).min(cap) * 0.2 * progress;
    }

    // Coupling with mean residual: prefer bins below mean residual (consolidation)
    score += (mean_residual - post) * 0.3;

    // Many open bins: prefer filling existing ones
    score += open_bins_count as f64 * pr * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 5 fractional bands
    let band = post_residual / (bin_capacity / 5).max(1);
    let band_penalty: f64 = match band {
        0 => -30.0, // near-perfect fit
        1 => -10.0,
        2 => 0.0,
        3 => 8.0,
        _ => 18.0, // large unusable remainder
    };
    score += band_penalty;

    // Modular residue: post_residual in a "dead zone" (odd small remainders) is hard to fill
    let r = post_residual % 10;
    if post_residual > 0 && r != 0 && r < 5 {
        score += 12.0; // small awkward slivers
    }
    if post_residual % 20 == 0 {
        score -= 6.0; // nicely divisible leftover
    }

    // Lookahead: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // bonus if next item exactly consumes the remainder (harmonic pairing)
            if next_item_size == post_residual {
                score -= 25.0;
            } else {
                let next_post = post_residual - next_item_size;
                if next_post < 5 && next_post > 0 {
                    score += 8.0; // leaves a sliver for the step after
                }
            }
        } else {
            score += 10.0;
        }
    } else {
        // last item: minimize waste aggressively
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: prefer new bin when open bins are fragmented
    if bin_residual == bin_capacity {
        // baseline competitiveness: new bin score ~ item_size + offset
        score = item_size as f64 + 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        }
        // late in stream or many open bins with high mean residual -> discourage new bin
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        if mean_residual > item_size as f64 {
            score += 15.0; // existing space available elsewhere
        }
    }

    // Tightness coupling: reward filling most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open bin count pressure: fewer bins is better; mild reward for reusing crowded sets
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10 units,
    // the classic dead zone) with a heavy nonlinear term.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Slightly larger but still awkward gaps (10..=15) get a mild penalty.
    if post_residual >= 10 && post_residual <= 15 {
        score += 4.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else {
        let tightness = post_residual as f64 / (item_size as f64 + 1.0);
        score -= 10.0 * (-tightness).exp();
    }

    // Open-bin pressure: penalize placements into bins when many bins are open,
    // encouraging consolidation into fewer bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Make the empty bin expensive unless
    // item is large relative to mean residual.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If item barely fits anywhere, opening new bin is reasonable.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Large items leave big residuals in fresh bins only if unavoidable.
        if item_size > 70 {
            score -= 6.0;
        }
    }

    // Lookahead: if the next item fits in post_residual, reward this placement
    // (chaining placements in one bin).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item almost fits, small penalty to discourage near-miss gaps.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 3.0;
    }

    // Mean-residual coupling: prefer bins whose post_residual moves toward
    // the mean (balanced packing).
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * mean_gap;

    // Early stream: slight preference for filling existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect match: next item still fits tightly after this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack * 0.15);
    }

    // Penalize dead space that next item cannot use
    if next_item_size > 0 && next_item_size > post_residual {
        let dead = (post_residual - 0).max(0) as f64;
        score += 0.5 * dead;
    }

    // Compare against mean residual: prefer bins that tighten the distribution
    let mr = mean_residual;
    if (post_residual as f64) < mr {
        score -= (mr - post_residual as f64) * 0.4;
    } else {
        score += (post_residual as f64 - mr) * 0.4;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New empty bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 15.0 + pressure * 45.0;
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for filling larger fraction of bin
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor placements that leave little waste.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly/comfortably in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or when many bins are already open. Relax slightly late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 60.0 + 4.0 * open_bins_count as f64;
        new_bin_penalty *= 1.0 - 0.3 * progress;
        // If the item leaves a good residual (small waste), opening is less bad.
        new_bin_penalty -= 20.0 * tightness;
        score += new_bin_penalty;
    }

    // Prefer bins whose residual is close to the item size (best-fit flavor),
    // and mildly prefer bins below the mean residual (consolidating fuller bins).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap;
    if bin_residual as f64 > mean_residual {
        score += 2.0 * (bin_residual as f64 - mean_residual).sqrt();
    }

    // Early stream: be a bit more conservative with existing bins to keep
    // flexibility; late stream: pack aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: tight fits favored via smooth polynomial in post_residual
    let mut score = norm_pr * norm_pr * cap;

    // Smooth coupling with stream progress: waste tolerance shrinks late in stream
    let progress_coupling = norm_pr * (1.0 + 2.0 * progress * progress);
    score += progress_coupling * cap * 0.5;

    // Reward bins whose residual matches the lookahead item (smooth Gaussian-like term)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score -= (-diff * diff * 40.0) * cap * 0.1;
    }

    // Penalize when this is one of many fitting bins but fit is loose
    if fitting_bins_count > 1 {
        score += norm_pr * (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild preference to fill already-open bins vs opening new ones,
    // modulated smoothly by how far this bin is from the mean residual
    let mean_gap = (pr - mean_residual) / cap;
    score += mean_gap * mean_gap * 4.0;
    score -= (open_bins_count as f64).ln() * 0.5;

    // New-bin candidate: keep it unattractive unless residual is unusably small
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a small remainder
    // (post_residual % 10 == 0..2) is more reusable than awkward remainders.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 6.0,
        1 | 2 => score -= 3.0,
        3 | 4 | 5 | 6 | 7 => score += 2.0,
        _ => {}
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 40.0;
    }

    // If the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = post_residual - next_item_size;
        score -= 12.0 + (chain_fit % 10) as f64 * 0.3;
        if chain_fit == 0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize proportionally to the gap.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.25;
    }

    // Last-chance bin before opening a new one: reward using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: penalize unless current bin is badly fragmented
    // or the item is large relative to residual.
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity as f64);
        score += 30.0 - 25.0 * tight;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
        // Open a fresh bin late in the stream when residuals are fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < (item_size as f64) * 0.5 {
            score -= 15.0 * progress;
        }
    }

    // Prefer bins whose residual is already small (tight packing) via
    // harmonic fraction of capacity.
    let frac = (bin_residual as f64) / (bin_capacity as f64);
    score += frac * 8.0;

    // Integer-division threshold: post_residual in [1..9] is nearly dead space.
    if pr > 0 && pr < 10 {
        score += 10.0;
    }

    // Reward bins that can absorb item plus a harmonic chunk of the next item.
    if next_item_size > 0 {
        let chunk = next_item_size / 2;
        if post_residual >= item_size.max(1) + chunk {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        // A residual is "dead" if the next item cannot fit into it.
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            // Dead space penalty: stronger the smaller the gap relative to capacity.
            let dead_frac = post_residual as f64 / bin_capacity as f64;
            score += 40.0 * (1.0 - dead_frac) * (1.0 - dead_frac);
        } else {
            // Usable residual: mild reward for keeping room for the next item.
            score -= 5.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Tightness of current fit: reward filling the bin well.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Open-bin pressure: when many bins are open, discourage spreading; when few
    // bins are open and this is a last-chance bin, encourage using it.
    if fitting_bins_count == 1 {
        score -= 12.0; // last chance before opening a new bin
    } else {
        score += 0.05 * open_bins_count as f64;
    }

    // New-bin candidate handling: only prefer a fresh bin if every open bin
    // would create severe dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 30.0 + 0.1 * open_bins_count as f64;
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size >= bin_capacity / 2 {
            new_bin_score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score -= 5.0 * (1.0 - progress);
        score = new_bin_score;
    }

    // Mean-residual coupling: if this bin's residual deviates favorably
    // (smaller than mean), slightly prefer it.
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: item + next item fill the bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Residual can still host the next item: scale reward by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 - slack.min(50.0);
        } else {
            // Next item cannot fit in the leftover: penalize dead space.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.0;
    }

    // Prefer bins whose residual deviates favorably from the mean residual.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well,
    // i.e. when the best achievable post_residual is poor relative to next item.
    if bin_residual == bin_capacity {
        let base = 60.0;
        if next_item_size > 0 && post_residual == 0 {
            score -= 500.0; // perfect fit case for fresh bin
        }
        score += base;
        // More open bins already -> less eager to open another.
        score += open_bins_count as f64 * 2.0;
    }

    // Mild preference for compacting into bins with small residual overall.
    score += (bin_capacity as f64 - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic discount for small leftover space.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 18.0 * tight * tight;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.35 * (next_item_size as f64);
    }
    // Penalize near-miss lookahead (wasted potential pairing).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.25 * (next_item_size - post_residual) as f64;
    }

    // Exact fit jackpot.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only option.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global state coupling: if mean residual is high, prefer reusing crowded bins.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score -= 6.0 * dev;
    }

    // New-bin candidate: open a fresh bin only when item is large and fit is poor elsewhere.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 22.0 + 30.0 * frac;
        if next_item_size > 0 && next_item_size <= bin_residual {
            penalty -= 10.0; // fresh bin pairs well with next item
        }
        penalty -= 8.0 * progress; // late in stream, consolidation matters more
        if open_bins_count > 6 {
            penalty += 4.0; // too many open bins already
        }
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let post_norm = post / cap;
    let mut score = post;

    // Non-linear polynomial coupling: quadratic/cubic in normalized post residual,
    // weighted by stream progress (later in stream -> penalize slack more).
    let poly = post_norm * post_norm * (1.0 - post_norm);
    score -= poly * cap * (0.5 + progress) * 2.0;

    // Perfect-fit reward (smooth exponential of squared residual).
    score -= cap * (-(post_norm * post_norm) * 12.0).exp() * (0.4 + 0.6 * progress);

    // Penalize residuals that are too small to be useful later (dead space),
    // but only if next item cannot use it.
    let next_fits = (next_item_size as f64) <= post && next_item_size > 0;
    if !next_fits {
        let dead = 1.0 - (post_norm * 4.0).min(1.0);
        score += dead * dead * cap * 0.6;
    } else {
        score -= 8.0; // reward bins that accommodate the lookahead item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= cap * (0.8 + 0.4 * progress);
    }

    // Mild penalty proportional to number of open bins to discourage sprawl.
    score += open_bins_count as f64 * 0.5;

    // Mean-residual coupling: prefer bins whose residual deviates from the mean
    // in a way that leaves large usable chunks (harmonic coupling).
    score += (post - mean_residual).abs() * 0.1;

    // New-bin candidate: opening a new bin should be costly unless current fit is bad.
    if bin_residual == bin_capacity {
        score += cap * (1.0 + progress) + (fitting_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 0.5;

    // Harmonic class analysis: classify post_residual by integer division thresholds
    // Residuals that can host common item sizes are "useful" dead space.
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let tenth = bin_capacity / 10;

    // Reward residuals that are multiples of common divisor classes (harmonic bins)
    let harmonic_bonus: f64 = if post_residual == 0 {
        40.0 // perfect fit is ideal
    } else if post_residual % tenth == 0 && post_residual >= tenth {
        6.0 // residual aligns with 10-unit harmonic class
    } else if post_residual % fifth == 0 {
        4.0
    } else if post_residual % quarter == 0 {
        3.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize residuals too small to ever be useful (dead space)
    if post_residual > 0 && post_residual < tenth {
        score += 15.0 + (tenth - post_residual) as f64;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: next item can land here; scale by how well it matches
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 + 5.0 * (1.0 - gap / bin_capacity as f64);
        } else if next_item_size > bin_residual && post_residual > 0 {
            // Next item won't fit this bin anyway; residual quality matters less
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit, or stream is early with few bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 * 0.85;
        // Early in the stream, having few open bins makes new bins cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
        // If next item is large and this item is small, a fresh bin preserves space
        if next_item_size > item_size && item_size <= quarter {
            score -= 8.0;
        }
    }

    // Mild penalty for spreading across many open bins (encourage consolidation)
    score += 0.05 * open_bins_count as f64;

    // Slight preference for bins with residual below mean (tighter bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.5;
    }

    // Penalize very loose fits (large post_residual) superlinearly
    if post_residual > bin_capacity / 2 {
        score += 0.3 * (post_residual - bin_capacity / 2) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
    }

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mild preference for bins below mean residual (fills emptier bins first).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // Perfect-fit bonus: strongly reward exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, huge reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 0.5 {
            score -= 500.0;
        } else if nxt <= post_residual as f64 {
            // Next item fits: mild reward proportional to how well it nests.
            score -= 50.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize residual that is too small
            // to be useful relative to next item (dead space risk).
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 80.0 * dead * dead;
        }
    }

    // Reward leaving residuals close to mean (keeps bin portfolio balanced),
    // but only when several bins are open.
    if open_bins_count > 1 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.3 * dev;
    }

    // Last-chance bin: if this is the only bin that fits, penalize opening
    // a new bin unless this fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate: penalize slightly so we only open when nothing fits well.
    if bin_residual == bin_capacity {
        score += 150.0 + 0.5 * item_size as f64;
        // But if next item is large and would pair well with a fresh bin, soften.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 60.0;
        }
    }

    // Early stream: be more willing to open bins (spread items); late stream: consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * (1.0 - progress) * (bin_residual == bin_capacity) as i32 as f64;

    // Mild reward for using bins with larger residuals first (best-fit-ish tiebreak).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize large leftover chunks that only very small items could use later.
    if post_residual > 0 {
        let usable = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
        score += 6.0 * (1.0 - usable);
    }

    // Lookahead coupling: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.08 * gap;
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 8.0; // perfect two-item chain
        }
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation, discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is late.
        score += 10.0 + 0.3 * open_bins_count as f64 + 10.0 * progress;
        // But allow a new bin when no open bin fits well (high mean residual mismatch).
        let mismatch = (mean_residual - item_size as f64).abs();
        if mismatch > 25.0 && fitting_bins_count == 0 {
            score -= 18.0;
        }
    } else {
        // Prefer bins with residual above the running mean (keeps balanced capacity).
        score += 0.05 * (mean_residual - bin_residual as f64);
        // Mild preference for bins that stay flexible early in the stream.
        score -= 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Core: prefer tight fits, with smooth polynomial coupling to stream progress.
    let mut score = pr / cap;

    // Non-linear polynomial coupling: wasted space matters more as stream progresses.
    let waste_norm = pr / cap;
    let coupling = waste_norm * waste_norm * (0.5 + 2.0 * progress);
    score += coupling;

    // Penalize opening a new bin, more so when other bins fit the item.
    if is_new_bin {
        let open_factor = (open_bins_count as f64 + 1.0).ln();
        score += 1.5 + 0.3 * open_factor + 0.5 * progress;
        // Allow new bin if existing residuals are all poor fits (large dead space elsewhere)
        let mean_gap = (mean_residual - item_size as f64) / cap;
        if mean_gap > 0.3 {
            score -= 0.6 * mean_gap;
        }
    } else {
        // Reward using an existing bin, especially the last-chance bin.
        if fitting_bins_count == 1 {
            score -= 0.8;
        }
        // Reward bins whose residual is already below mean (consolidating tightness).
        let tightness = (mean_residual - pr) / cap;
        score -= 0.25 * tightness;
    }

    // Lookahead: strongly favor leaving space for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 0.4 * (1.0 - slack * slack);
        } else {
            score += 0.3 * ((nxt - pr) / cap);
        }
    }

    // Smooth progress-based tightening: late in the stream, squeeze harder.
    score += 0.2 * progress * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division thresholds on capacity fractions.
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction remaining after placement
    let class = (post_residual / (bin_capacity / 5).max(1)) as f64; // 5 harmonic classes 0..5

    // Reward tight fits strongly: lower post_residual classes are better.
    score -= (5.0 - class) * 4.0;
    score -= (1.0 - frac) * 10.0;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of small
    // harmonic units (10/20/25) are more likely reusable by future items.
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0);
    if reusable { score -= 6.0; } else { score += 3.0; }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic pairing: exact/near-exact pairing is excellent.
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 - gap.min(15.0) * 0.5;
            // Perfect closure (post_residual == next_item_size) is ideal.
            if gap == 0.0 { score -= 12.0; }
        } else {
            // Next item won't fit here; slight penalty for leaving large awkward gap.
            score += (next_item_size as f64 - pr).min(20.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only prefer opening a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: large, so it's chosen only when open-bin fits are bad.
        score = cap * 0.75 + item_size as f64 * 0.2;
        // Late in the stream, opening new bins is less attractive (wasted capacity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If many bins are open, prefer consolidating into them.
        score += open_bins_count as f64 * 1.5;
        // If the mean residual of open bins is large, an open bin likely fits well.
        score += mean_residual * 0.4;
    } else {
        // Mild preference for filling bins with less residual already (best-fit flavor),
        // scaled by how many alternatives exist.
        score += mean_residual * 0.1;
        // Coupling: when many bins fit the item, competition is high; tighten scoring
        // to discriminate via post_residual (already dominant term).
        let _ = fitting_bins_count;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A small post_residual that can never host a typical future item is dead space.
    // Penalize it super-linearly: gaps in (0, 10] are pure waste, gaps just above
    // common item sizes are semi-usable.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) <= dead_threshold {
        score += (dead_threshold - post_residual as f64 + 1.0) * 40.0; // unusable gap penalty
    }

    // Tight fit reward: the closer post_residual is to 0 (but usable), the better.
    score -= (bin_capacity - post_residual) as f64 * 0.3;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // --- Usability shaping ---
    // Prefer leaving residuals that are "round" usable amounts (>= next item or >= 10).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the lookahead item: reward chaining.
            score -= 25.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // Leaves a gap the next item cannot use: penalize proportionally to waste.
            score += (next_item_size as f64 - post_residual as f64) * 1.5;
        }
    }

    // --- Open-bin pressure ---
    // Discourage scattering across many open bins; but when this is the ONLY bin
    // that fits, strongly favor using it to avoid opening a new bin.
    score += open_bins_count as f64 * 1.2;
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // --- New-bin candidate handling ---
    // Brand-new empty bin: neutral baseline; only prefer it when current bins are
    // crowded (low mean residual) or item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score = 55.0 + crowding * 30.0;
        if item_size > 70 {
            score -= 20.0; // large items start fresh bins more readily
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score += 5.0; // slight penalty for fresh bin when item could chain elsewhere
        }
    }

    // --- Stream progression: late in stream, consolidate aggressively ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
