pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fills.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing can use (min item ~1..100 unknown, assume >=1).
    if post_residual > 0 {
        let unusable = (post_residual as f64 / bin_capacity as f64).powf(1.5);
        score += 40.0 * unusable;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 20.0 * (1.0 - (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64);
        }
        // Chain fit: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Global state: penalize spreading when many bins are open and residuals are high.
    let spread = if mean_residual > 0.0 {
        (bin_residual as f64 - mean_residual).abs() / mean_residual
    } else {
        0.0
    };
    score += 10.0 * spread;

    // Prefer filling bins with low residual relative to mean (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fit win.
        score += 30.0;
        // But if the item barely fits anywhere (large item, few fitting bins), opening is fine.
        if fit_ratio > 0.7 || fitting_bins_count <= 1 {
            score -= 60.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Time horizon: early stream, keep bins flexible; late stream, fill greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for opening too many bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let fit_ratio = if open_bins_count > 0 { fitting_bins_count as f64 / open_bins_count as f64 } else { 1.0 };

    // Smooth non-linear coupling: post_residual penalized more as stream progresses
    let t = progress;
    let poly = norm_post * norm_post * (0.5 + t) + norm_post * (1.0 - t);
    score += 12.0 * poly;

    // Reward tight fits (small post_residual) with non-linear bonus
    score -= 8.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post);

    // Lookahead coupling: penalize leaving residual that mismatches next item
    if next_item_size > 0 {
        let gap = (norm_post - norm_next).abs();
        score += 6.0 * gap * gap * (0.5 + t);
        // Reward residual exactly matching next item
        score -= 5.0 * (1.0 - gap) * (1.0 - gap);
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + t);
    }

    // Scarcity of fitting bins: reward bins in scarce situations
    score -= 4.0 / (1.0 + fit_ratio);

    // Mean residual coupling: prefer bins deviating favorably from mean residual
    let mean_norm = mean_residual / cap;
    score += 3.0 * (norm_post - mean_norm) * (1.0 - t);

    // Penalize opening new bins early; allow later when many bins open
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - t) - 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Perfect fit heavily rewarded
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // Integer-division thresholds on post_residual: dead space zones
    // Leftovers that no typical item (1..100) can use well are penalized
    if post_residual > 0 && post_residual < 10 {
        score += 80.0; // unusable sliver
    }

    // Modulo arithmetic: post_residual in harmonic bands of 25 (quarter capacity)
    let quarter = post_residual % 25;
    match quarter {
        0 => score -= 60.0,               // exact quarter multiples: reusable
        1..=4 => score += 25.0,           // near-miss slivers
        _ => {}
    }

    // Half-capacity harmonic bonus
    if post_residual == 50 { score -= 90.0; }
    if post_residual == 33 || post_residual == 34 { score -= 40.0; }
    if post_residual == 66 || post_residual == 67 { score -= 40.0; }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 - slack * 1.5; // good chain, decay with slack
        } else {
            // next item won't fit here; penalize less if residual is large enough to be useful later
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: prefer existing bins unless fit is terrible
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty for opening a new bin, scaled by stream progress and open bins
        score += 150.0 + 0.5 * open_bins_count as f64;
        // but if current item leaves a bad residual in any existing bin, new bin is fine
        if post_residual == bin_capacity - item_size.min(bin_capacity) {
            // empty-bin post residual = capacity - item; reward if it's a harmonic value
            let r = bin_capacity - item_size;
            if r % 25 == 0 { score -= 50.0; }
        }
        // late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
    }

    // Mean residual context: if this bin's residual is far below mean, it's a good filler
    let mean_r = mean_residual;
    let dev = mean_r - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.8; // tighter-than-average bins preferred
    } else {
        score += (-dev) * 0.3; // looser bins mildly penalized
    }

    // Prefer bins among many fitting candidates by post residual rank pressure
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 5.0;
    }

    // Small tie-break noise via deterministic mixing of inputs
    let mix = ((item_size as f64 * 7.0 + post_residual as f64 * 13.0 + step_index as f64 * 0.01) % 3.0) - 1.5;
    score += mix * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 {
        // A residual gap is "dead" if no plausible future item (min size 1..=10)
        // can use it well. Penalize gaps that are small but nonzero.
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64);
        }
        // Very tight fit (post_residual == 0) is ideal.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Reward fitting into bins that are already partially filled (waste-minimization).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bins pressure: when many bins are open, prefer consolidation
    // into existing bins; discourage opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin count.
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But if no existing bin fits well (item nearly fills a fresh bin),
        // a new bin is fine.
        if item_size as f64 >= 0.85 * bin_capacity as f64 {
            score -= 30.0;
        }
    } else {
        // Reward using existing bins more strongly when many are open.
        score -= 1.5 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        }
        // If post_residual is just below next item size, it's stranded dead space.
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (future flexibility);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Mild deviation from mean residual: prefer bins whose residual is near the mean
    // to keep a balanced portfolio of gaps.
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Slack after the lookahead item; penalize proportionally to leftover.
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - 0.35 * slack;
    }

    // Dead space that no plausible item (min size 1..) can use well.
    if post_residual < 10 {
        score += 25.0;
    }

    // Compare residual against mean residual across open bins.
    score -= 0.4 * (mean_residual - bin_residual as f64);

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += 30.0;
        }
    }

    // Early in stream: be slightly greedy to consolidate.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving little waste.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Lookahead: penalize leftover space that cannot host the next item,
    // reward leftovers that can (chain future placements into this bin).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to the next item: the smaller the gap, the worse.
            let gap = (next_item_size - post_residual) as f64;
            score += 1.5 * gap * gap / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate logic: an empty bin is a long-term resource; only prefer it
    // when existing bins would be badly fragmented by this item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as the stream progresses
        // (early on, opening bins is cheap since many items remain to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 25.0 * progress;

        // If many bins are open with plenty of residual, don't add another.
        score += 2.0 * open_bins_count as f64 * (mean_residual / bin_capacity as f64).max(0.0);
    } else {
        // Reward using already-open bins, scaled by how "wasted" they are relative to mean.
        let residual_frac = bin_residual as f64 / bin_capacity as f64;
        if residual_frac > mean_residual / bin_capacity as f64 {
            // This bin is emptier than average: using it reduces fragmentation.
            score -= 3.0 * (residual_frac - mean_residual / bin_capacity as f64);
        } else {
            // This bin is tighter than average: using it preserves big residuals elsewhere.
            score += 2.0 * (mean_residual / bin_capacity as f64 - residual_frac);
        }
    }

    // Late-stream pressure: as the stream nears its end, prefer filling existing bins
    // completely rather than spreading residual space.
    let horizon = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * horizon * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Exact-fill jackpot.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Small penalty per open bin to consolidate when scores are otherwise close.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: reward tight fits, but non-linearly — small residuals are super-rewarded.
    let mut score = pr_norm.powf(1.7) * cap;

    // Stream-progress coupling: early on, waste tolerance is low (tight packing matters),
    // later on, prefer consolidating into existing bins (penalize opening spread).
    let tightness = 0.6 + 0.8 * (1.0 - progress);
    score += tightness * (pr_norm * pr_norm) * cap;

    // Smooth interaction between post_residual and mean residual across open bins:
    // penalize placements that leave this bin far below the fleet's mean residual
    // (wasted dead space relative to peers).
    let mean_norm = mean_residual / cap;
    score += 12.0 * (pr_norm - mean_norm).abs() * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr_norm);
    }

    // Lookahead coupling: reward if next item could fit the post residual smoothly.
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let fit_gap = pr_norm - next_norm;
        if fit_gap >= 0.0 {
            score -= 8.0 * (fit_gap * (1.0 - fit_gap)).max(0.0);
        } else {
            score += 6.0 * (-fit_gap);
        }
    }

    // New-bin candidate handling: brand-new empty bin has pr_norm == 1.0.
    // Penalize it increasingly as the stream progresses so consolidation wins,
    // unless it is genuinely the best option (its base score is already high).
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Mild penalty for many open bins to discourage bin proliferation.
    score += 0.5 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: residues that are "usable"
    // for typical item sizes are rewarded, awkward dead-space residues penalized.
    let r = post_residual;
    if r == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if r < 10 {
        // Tiny dead space: nearly perfect, mild reward.
        score -= 25.0;
    } else {
        // Harmonic class via integer division thresholds on r.
        let cls = r / 10; // 1..=10 harmonic band
        match cls {
            1 => score -= 8.0,   // 10..19: fits small items well
            2 => score += 2.0,   // 20..29: decent
            3 => score -= 4.0,   // 30..39: good for mid items
            4 => score += 6.0,   // 40..49: awkward half-bin
            5 => score -= 2.0,   // 50..59: half bin, reusable
            6 => score += 5.0,   // 60..69: large dead space risk
            7 => score -= 1.0,   // 70..79: still flexible
            8 => score += 8.0,   // 80..89: mostly empty, wasteful use
            9 => score += 12.0,  // 90..99: nearly untouched bin
            _ => {}
        }
        // Modulo-4 coupling: residuals divisible by 4 align with common sizes.
        if r % 4 == 0 { score -= 3.0; }
        if r % 10 == 0 { score -= 4.0; } // round residuals are versatile
        if r % 7 == 0 { score += 1.5; }  // odd residue: slight penalty
    }

    // --- Lookahead coupling: if the next item fits exactly in post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 45.0;
        } else if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / 100.0);
            if slack < 10.0 { score -= 8.0; } // near-perfect chain
        } else {
            // Next item cannot follow into this bin: slight penalty scaled by gap.
            score += ((next_item_size - r) as f64) * 0.15;
        }
    }

    // --- Last-chance logic: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave terrible residuals or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Fresh bin baseline: mid-range score so good fits beat it.
        score = 55.0 + 20.0 * (1.0 - progress);
        if open_bins_count == 0 { score -= 100.0; } // must use a bin
        if next_item_size > 0 && next_item_size >= item_size {
            // Opening fresh when item sizes are growing keeps flexibility.
            score -= 15.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            // All open bins nearly full: fresh bin is attractive.
            score -= 25.0;
        }
    }

    // --- Congestion: many open bins -> prefer tightening existing ones.
    let congestion = (open_bins_count as f64 / (1.0 + mean_residual / 25.0)).min(10.0);
    score += congestion * 0.5;

    // --- Mean residual alignment: placing into bins below mean residual
    // balances the pool.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // --- Progress phase: late in stream, squeeze bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space is worse if it cannot host the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
        // Reward leaving exactly enough room for the next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when pressure is high.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.8 * pressure;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin early in the stream
    // when there are open bins; allow it more freely late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - 0.5 * progress);
        // If the new bin would be nearly filled by this item, it's attractive.
        if fill > 0.6 {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit (small post_residual) wins.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: strongly reward bins where the next item
    // exactly fills the post_residual, mildly reward if it fits.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: this bin will be exactly closed
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize proportionally
            // to how much usable space is wasted relative to next item size.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving this bin below average concentrates dead space; leaving it
    // near/above average keeps flexibility.
    score += 0.15 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a poor reason.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits
    // well. Penalize opening new bins while existing ones can host the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 55.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            new_bin_score -= 80.0; // forced: no open bin fits
        } else if fitting_bins_count == 1 {
            new_bin_score += 5.0; // slightly discourage stealing the last-chance bin
        }
        // If the next item is large, having a fresh bin is valuable.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            new_bin_score -= 10.0;
        }
        score += new_bin_score;
    }

    // Mild penalty for very small unusable remnants (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (waste minimization is primary).
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 2.0 * tight * tight;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize placements that leave a residual too small for the
    // next item (dead space), reward residuals that could host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
        } else if post_residual > 0 {
            score += 0.05 * post_residual as f64;
        }
    }

    // New-bin candidate handling: opening a bin is penalized, but the penalty
    // shrinks when open bins have poor average residual (fragmented state).
    if bin_residual == bin_capacity {
        let mut penalty = 30.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Late in stream, prefer closing out bins over opening new ones.
        penalty *= 1.0 + 0.5 * progress;
        // If mean residual of open bins is large, opening is more wasteful.
        penalty += 0.1 * mean_residual;
        // If item is large relative to typical residual, opening is justified.
        penalty -= 0.2 * item_size as f64;
        score += penalty.max(2.0);
    }

    // Mild preference for filling bins with lower residual first (compact bins).
    score += 0.02 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);
    score += 20.0 * poly;

    // Reward tight fits (small post residual), stronger late in stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 30.0 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (1.0 + progress);
        } else {
            score -= (pr - nx).min(20.0) * 0.3;
        }
    }

    // Last-chance bin bonus: avoid opening new bins when only one fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across many open bins vs mean residual alignment
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;

    // New-bin candidate: make it slightly less attractive than a decent fit
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into capacity fractions
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Dead space classes: post_residual in (0,10) is unusable for items >=10 in classic
    // but items 1..100 => tiny residuals < smallest plausible next item are dead.
    if post_residual > 0 && post_residual < 4 {
        score += 60.0; // nearly-dead sliver
    }

    // Harmonic tiers: reward residuals that are "friendly" fractions of capacity
    // (1/2, 1/3, 1/4 of capacity) since they invite complementary items.
    let friendly = |r: f64| -> f64 {
        let mut best = f64::INFINITY;
        for k in 2..=6 {
            let target = cap / k as f64;
            let d = (r - target).abs();
            best = best.min(d);
        }
        best
    };
    score += 0.8 * friendly(pr);

    // Modulo arithmetic on post_residual: residuals divisible by common item sizes
    // (10-step streams) are more likely to be exactly filled later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }
    // Odd, awkward residuals get a penalty
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 0.9 * (next_item_size as f64);
        } else {
            // next item cannot use this residual at all -> residual likely wasted
            score += 0.3 * (next_item_size as f64 - pr).min(50.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate logic: empty bin should score moderately high (post_residual = cap)
    // but become attractive when open bins have poor fits.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 40.0;
        // more open bins with bad mean residual -> opening new bin less costly relative
        score -= 0.5 * open_bins_count as f64;
        // if mean residual across open bins is small (bins nearly full), new bin is fine
        score -= 0.4 * (cap - mean_residual).max(0.0);
        // early in stream, prefer consolidating; late, allow spreading
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * progress;
    }

    // Tightness coupling: prefer bins where item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio;

    // Penalize leaving residual just below a harmonic class boundary (awkward zone)
    for k in 2..=5 {
        let t = cap / k as f64;
        if pr < t && pr > t - 5.0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (10)
    // are permanently unusable -> heavy penalty, ramping as gap shrinks.
    if post_residual < 10 {
        score += 60.0 + (10.0 - post_residual as f64) * 8.0;
    } else if post_residual < 20 {
        // Near-dead zone: only very large future items could use it.
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: bonus if the next item fits the post-residual gap.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + next_item_size as f64 * 0.1;
        } else {
            // Gap won't serve the next item: mild penalty scaled by gap size.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when
    // alternatives exist; encourage using existing bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins
    // would create dead space, otherwise keep existing bins preferred.
    if bin_residual == bin_capacity {
        score = 35.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: fresh bin may be wise
        }
    }

    // Mean residual coupling: if the fleet of open bins is already loose
    // (high mean residual), prefer consolidating into this bin.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight early-stream bias toward opening bins (better structure later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // reward closeness of the lookahead fit
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here: penalize large dead space proportionally
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual to mean residual across open bins: leaving residuals
    // far below mean creates fragmented unusable space
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.3 * (mean_residual - pr);
    } else {
        score -= 0.1 * (pr - mean_residual);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Prefer fuller bins overall (low post_residual relative to capacity)
    score += 0.5 * (bin_capacity as f64 - bin_residual as f64).recip() * 10.0;

    // Slight preference for reusing open bins over opening new ones
    if bin_residual == bin_capacity {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are rewarded nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space only if it cannot plausibly host the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.35 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            score -= 25.0; // perfect lookahead fit
        } else {
            score -= 6.0; // next item still fits, mild reward
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.2 * item_size as f64;
    }

    // Many open bins: prefer consolidating into fuller bins (small residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Relative to mean residual: bins emptier than average are less attractive.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Late in the stream, minimize waste aggressively.
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let escape_cost = if fitting_bins_count == 0 { -1000.0 } else {
            let worst = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 20.0 };
            15.0 + worst + 0.1 * open_bins_count as f64
        };
        score = bin_capacity as f64 - escape_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with progress:
    // early in the stream, larger residuals are acceptable; later, penalize them super-linearly.
    let progress_poly = 0.5 + 1.5 * progress * progress; // smooth ramp 0.5 -> 2.0
    score += progress_poly * (pr * pr) / cap;

    // Reward tight fits: small post_residual relative to capacity, stronger late in stream
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Lookahead: reward residual that can host the next item (smooth coupling)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let snug = (pr - ni) / cap;
            score -= 8.0 * (1.0 - snug * snug);
        } else {
            // residual cannot host next item: penalize more as progress advances
            score += 5.0 * (ni / cap) * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + progress);
    }

    // Penalize bins whose residual deviates far from the mean residual (imbalance)
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * (0.5 + progress);

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * progress;

    // New-bin candidate: neutral baseline so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity quartiles
    let q = bin_capacity / 4;
    let class = post_residual / q; // 0..=4 harmonic class
    match class {
        0 => score -= 30.0, // near-perfect fill
        1 => score -= 10.0, // good fill
        2 => score += 0.0,  // middle
        3 => score += 8.0,  // poor
        _ => {}             // empty-ish
    }

    // Dead-space penalty: post_residual too small for any future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward bins whose residual can host the lookahead item exactly-ish
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect lookahead pairing
        } else if post_residual >= next_item_size {
            score -= 12.0; // lookahead still fits
        } else {
            score += 6.0; // lookahead would spill to another bin
        }
        // modulo harmonic coupling between post_residual and next size
        let m = (post_residual % bin_capacity.max(1)).min(bin_capacity);
        if m >= next_item_size && (m - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless nothing fits well
    if bin_residual == bin_capacity {
        let tight_exists = fitting_bins_count > 0 && (bin_residual as f64 - item_size as f64) <= mean_residual;
        let mut penalty = 55.0;
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            penalty -= 20.0; // current item leaves big residual anyway
        }
        if tight_exists {
            penalty += 15.0;
        }
        // early in stream, allow spreading bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty -= 20.0 * (1.0 - progress);
        score += penalty;
    }

    // Mild preference to fill bins below mean residual (balance avoidance of fragmentation)
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Open-bin pressure: discourage spreading across many bins lightly.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New bin candidate: penalize slightly so existing good fits win,
    // but allow opening when existing residuals are poor.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.1;
    }

    // Progress-based mild adaptation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size well
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            // Perfect lookahead fit: next item exactly fills this bin afterwards
            let diff = (pr - next).abs();
            score -= (bin_capacity as f64) * (1.0 - diff / (bin_capacity as f64)) * 0.8;
            // Extra bonus if next item consumes residual entirely
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted potential
            score += (next - pr) * 0.5;
        }
    }

    // Penalize dead space relative to mean residual across open bins
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += (mean_residual - pr) * 0.3;
    } else {
        score -= (pr - mean_residual) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Tight fits are good: small post_residual relative to capacity
    score -= (1.0 - pr / (bin_capacity as f64)) * 10.0;

    // Late in stream, prefer tighter packing (fewer bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.1 * progress;

    // Prefer reusing existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;
    let fit_norm = pr_norm * pr_norm;

    let mut score = pr * (1.0 + 0.35 * progress);

    // non-linear penalty for awkward residual sizes (mid-range dead space)
    let awkward = 4.0 * fit_norm * (1.0 - pr_norm);
    score += 18.0 * awkward;

    // reward tight fits, scaled by how scarce fitting bins are
    let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
    score -= 25.0 * (1.0 - pr_norm).powi(3) * scarcity;

    // lookahead coupling: residual that fits the next item is valuable
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        let size_match = 1.0 - (pr - nx).abs() / cap;
        score -= 12.0 * fits_next * size_match * size_match;
        score += 6.0 * (1.0 - fits_next) * (1.0 - progress);
    }

    // prefer consolidating into bins deviating from mean residual (balance pressure)
    let dev = (br - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // late stream: penalize opening new bins more strongly
    if br >= cap - 0.5 {
        score += 40.0 + 60.0 * progress;
    }

    // mild reward for using crowded bin sets
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "denomination" of dead space remains.
    // Classes: 0 (perfect fit), <=10 (tiny waste), <=20 (half-slot), <=50 (usable), else large.
    let cls: u32 = if post_residual == 0 { 0 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 20 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };

    // Reward tight fits strongly.
    score -= match cls {
        0 => 60.0,
        1 => 25.0,
        2 => 10.0,
        3 => 0.0,
        _ => 0.0,
    };

    // Penalize leaving dead space that no plausible item (1..=100) can use efficiently:
    // residual in (0,10) is nearly dead; residual in (50,100) wastes half a bin.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.5;
    }

    // Lookahead coupling: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // harmonic compatibility: next item leaves a small remainder too
            let rem = post_residual - next_item_size;
            score -= if rem <= 10 { 20.0 } else if rem <= 20 { 8.0 } else { 0.0 };
            // modulo-class resonance: next item divides post residual nicely
            if post_residual % next_item_size.max(1) == 0 {
                score -= 12.0;
            }
        } else {
            // next item won't fit here anyway: mild penalty for wasting the slot
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer fuller bins relative to current mean residual (pack tight bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless remaining open bins are all bad.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin, discounted when many items remain to allow lookahead room
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 40.0 + 20.0 * (1.0 - progress);
        // if the item is small, a new bin wastes capacity; if huge, new bin is natural
        if item_size <= 30 {
            score += 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Slight preference for bins whose residual is an exact multiple class of item size
    if bin_residual % item_size.max(1) == 0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += 2.5 * (open_bins_count as f64).sqrt();

    // Last-chance bin: strongly favor using it instead of opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral baseline, penalized mildly so it is
    // only chosen when fits into open bins are poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in stream, opening new bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If the next item could pair with this item in a fresh bin, encourage opening.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space if next item can't use the gap.
        score += 4.0;
    }

    // Prefer bins whose residual is close to mean residual (keeps bin states uniform).
    score += 0.15 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item also fits here: strong reward for chain placement
            score -= 12.0 + 0.25 * (post_residual as f64 - next_item_size as f64);
        } else {
            // Next item won't fit after this placement: penalize
            score += 4.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: prefer tightest fit
        score -= 3.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.10 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: penalize unless open bins are hopeless
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Waste penalty: dead space below minimum item size is unusable
    if post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual shrinks (non-linear).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 60.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post-residual, strong bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_waste = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - lookahead_waste / cap);
    } else if next_item_size > post_residual {
        // Next item won't chain here; penalize large leftover chunks that become dead space.
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // When many bins fit the item, prefer the one with the smallest residual beyond the fit.
    if fitting_bins_count > 1 {
        score += 3.0;
    }

    // New-bin candidate handling: opening a bin is penalized, but becomes attractive
    // when the item would otherwise leave a very fragmented residual in an existing bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 - 20.0 * progress; // cheaper to open bins early in the stream
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Global pressure: when mean residual across open bins is small, conserve space aggressively.
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    let pressure = (mr / cap).clamp(0.0, 1.0);
    score += 10.0 * pressure * (post_residual as f64 / cap);

    // Mild preference to fill bins with many open bins (consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Coupling of residual with stream progress: later in stream, dead space matters more
    let progress_coupling = progress * (pr * pr) / (cap * cap);
    score += 8.0 * progress_coupling;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 6.0 * (1.0 - norm_item) * (1.0 - norm_pr) * (0.5 + progress);

    // Lookahead: if next item fits into post_residual, reward this bin smoothly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 10.0 * fit_quality * fit_quality * (1.0 + progress);
    } else if next_item_size > 0 {
        // Penalize leaving residual that cannot host the next item, scaled by residual size
        score += 4.0 * norm_pr * (1.0 + progress);
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: prefer opening a new bin early or when mean residual is fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = pr + 3.0 - 12.0 * fragmentation * fragmentation * (1.0 - progress)
            - 5.0 * progress;
        // discourage new bins when a decent fit exists in open bins
        if fitting_bins_count > 0 && norm_item < 0.5 {
            score += 6.0 * (1.0 - norm_item);
        }
    }

    // Mild penalty for proliferation of open bins
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residuals divisible by small classes are
    // more reusable. Class = post_residual mod 10 (harmonic base).
    let post_mod = post_residual % 10;
    // Reward residuals that fall into "friendly" classes (0, 5, 2, 8) which
    // commonly match item sizes in [1,100].
    let friendly = matches!(post_mod, 0 | 2 | 4 | 5 | 6 | 8);
    if friendly {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: tiny unusable leftovers (1..=5) waste the bin.
    if post_residual > 0 && post_residual <= 5 {
        score += 8.0;
    }

    // Coupling with next item: if the next item exactly matches post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Next item fits here: good, scale by how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
        // Harmonic compatibility: next item size mod class match.
        if next_item_size % 10 == post_mod && post_residual > 0 {
            score -= 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new one unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: neutral-ish score anchored at half capacity so it only
    // wins when all open bins have poor fits. Penalize slightly when many bins
    // are already open (consolidation pressure) unless item is large.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.5 + item_size as f64 * 0.1;
        if item_size >= 60 {
            score += 5.0; // large items prefer existing snug fits
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Tightness reward: snug fit (post_residual small but usable) preferred.
    if post_residual > 5 {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 4.0 * tightness * tightness;
    }

    // Stream progression: later in the stream, be more conservative about
    // opening new bins; reward filling existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 3.0 * progress;
    }

    // Mean residual coupling: when mean residual is high, prefer bins well
    // below the mean (keeps a spread of residual sizes for future items).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (1..100) are pure waste. Penalize unusable gaps hard.
    if post_residual > 0 {
        // Gap smaller than the minimum conceivable item is dead space.
        if post_residual < 10 {
            score += 200.0;
        } else if post_residual < 25 {
            score += 60.0 + (25 - post_residual) as f64 * 4.0;
        } else if post_residual < 40 {
            score += 15.0;
        }
        // Perfect or near-perfect fits are heavily rewarded.
        if post_residual == 0 {
            score -= 120.0;
        } else if post_residual <= 5 {
            score -= 40.0;
        }
    }

    // Reward using bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; penalize placements that leave mid-range gaps.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * (post_residual as f64 - mean_residual).max(0.0) * 0.5;
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin — reward unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit,
    // i.e., when this call is the fresh bin. Judge via lookahead.
    if bin_residual == bin_capacity {
        let lookahead_penalty = if next_item_size > 0 {
            // A fresh bin is good if the next item could pair with the
            // post_residual of the current placement elsewhere; here the
            // fresh bin keeps flexibility, so reward slightly when the
            // current item is large relative to capacity.
            (item_size as f64 / bin_capacity as f64) * 30.0
        } else {
            10.0
        };
        // Base cost of opening a new bin, offset by flexibility bonus.
        score += 35.0 - lookahead_penalty;
    }

    // Lookahead: if the next item exactly fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Mild stream-progression term: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual matches next_item_size exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 500.0;
        } else {
            score += slack * 0.5;
        }
    } else if next_item_size > 0 {
        // next item can't fit here afterwards: penalize proportionally
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Penalize small dead space (unusable fragments)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 150.0 - 100.0 * progress;
        // opening a new bin is fine if no open bin gives a good fit
        let best_alt = if fitting_bins_count == 0 { -100.0 } else { 0.0 };
        score += base + best_alt;
        // a fresh bin is attractive if the next item is large
        if next_item_size > 50 {
            score -= 80.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits strongly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Penalize dead space that cannot fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are bad
    }

    // Lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 {
        score += 5.0; // next item won't chain here
    }

    // Last fitting bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate handling: only attractive when open bins have small residuals
    // (i.e., item would waste space) or many bins are effectively full.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global state.
        let mut new_bin_cost = 40.0;
        if mean_residual < item_size as f64 * 1.2 {
            new_bin_cost -= 30.0; // open bins are nearly full; new bin is fine
        }
        if open_bins_count == 0 {
            new_bin_cost = -100.0; // nothing open, must open
        }
        // Late in the stream, avoid opening bins that will stay mostly empty.
        new_bin_cost += progress * 20.0 * (1.0 - mean_residual / bin_capacity as f64);
        score += new_bin_cost;
    } else {
        // Mild bonus for filling existing bins proportionally.
        score -= (1.0 - (bin_residual as f64 / bin_capacity as f64)) * 5.0;
    }

    // Slight preference for bins already below mean residual (balance spread).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear waste penalty: dead space below next item is quadratic
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * gap / cap;
    }

    // Smooth polynomial coupling of post_residual with stream progress
    let x = pr / cap;
    let t = progress;
    score -= 12.0 * x * x * (1.0 - t) * (1.0 - x);
    score += 8.0 * x * t * t;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - (pr / cap);
    score -= tightness * tightness * (1.0 + 6.0 * t) * (item_size as f64 / cap);

    // Last-chance bin bonus (smooth, not piecewise)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - t) + 5.0;
    }

    // Mild penalty for spreading too many open bins early
    score += (open_bins_count as f64).ln() * t * 2.0;

    // Prefer bins near mean residual (balance) with smooth kernel
    let dev = pr - mean_residual;
    score += dev * dev / (cap * cap) * 4.0;

    // New-bin candidate: penalize opening new bins unless residual is large
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - t) + 6.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64) / cap_f;
    score -= 12.0 * tight * tight;

    // Harmonic class of post_residual: mod-10 buckets.
    let class = post_residual % 10;
    match class {
        0 => score -= 6.0,             // perfect decade residual, reusable
        1 | 2 => score -= 2.0,
        8 | 9 => score += 3.0,         // awkward sliver
        _ => {}
    }

    // Integer-division thresholds on post_residual.
    if post_residual == 0 {
        score -= 25.0;                 // perfect closure
    } else if post_residual < 10 {
        score += 8.0;                 // dead space below min item size
    }

    // Pairing lookahead: residual exactly matches next item, or next item fits comfortably.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 5.0;             // next item can't use this residual
        }
        // modulo coupling between residual class and next item class
        if next_item_size % 10 == class {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when current bin fits are scarce
    // or the item is huge and fits would leave fragmented slivers.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big = item_size as f64 / cap_f;
        score = 55.0 - 40.0 * pressure - 15.0 * big
            - (fitting_bins_count as f64).recip() * 5.0;
        if next_item_size > 0 && next_item_size > post_residual.min(bin_residual) && post_residual == bin_capacity {
            // nothing to fragment in an empty bin; slight pull toward new bin
            score -= 5.0;
        }
    }

    // Mild stream-phase modulation: late in stream, prefer closing bins.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * phase * tight;

    // Residual diversity penalty: avoid scattering residual space when mean residual is low.
    if (post_residual as f64 - mean_residual).abs() > 20.0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += (open_bins_count as f64) * 0.5;

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Prefer bins with below-mean residual (fill the emptier-fitting bins first keeps tight bins tight).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    // New-bin candidate: only attractive when current item leaves large residual and few bins open.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but compare against mean residual.
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff < 0.5 {
            score -= 40.0; // perfect two-step chain: next item fills this bin exactly
        } else if post_residual as f64 >= next {
            // next item fits: penalize leftover waste after the hypothetical second placement
            let second_leftover = post_residual as f64 - next;
            score -= 20.0 - second_leftover * 0.6;
        } else {
            // next item won't fit here: penalize proportionally to the shortfall
            score += (next - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers (dead space nothing can fill).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early in stream: keep bins flexible, mildly discourage fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.1;

    // Empty new-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero is best).
    score -= 30.0 * (-post_residual as f64 / 12.0).exp();

    // Penalize large dead space quadratically.
    score += 0.05 * (post_residual as f64).powi(2) / 100.0;

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, unless the item is huge
    // relative to capacity or many bins exist and residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 20.0
            - 10.0 * (item_size as f64 / bin_capacity as f64)
            - 5.0 * fragmentation / bin_capacity as f64
            - 4.0 * progress;
    } else {
        // Slight preference for bins below mean residual (use up emptier bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.5;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for proliferation of open bins.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pnorm = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic) coupling
    let mut score = pr * (1.0 + 0.6 * pnorm * pnorm);

    // Stream-progress modulation: as stream advances, tighten packing more aggressively
    let prog_coupling = 1.0 + 0.8 * progress * pnorm * (1.0 - pnorm);
    score *= prog_coupling;

    // Dead-space penalty: cubic in normalized residual
    let dead = pnorm * pnorm * pnorm * cap;
    score += 0.5 * dead * (0.5 + 0.5 * progress);

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - pnorm);
    }

    // Crowding pressure: many open bins -> favor filling existing ones
    score -= 0.4 * (open_bins_count as f64).sqrt() * (1.0 - pnorm);

    // Mean residual coupling: if this bin's residual is below mean, it's a good tight fit
    score += 0.3 * (mean_residual - pr);

    // Lookahead: penalize if next item could have used this exact post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let waste = (pr - nxt) / cap;
            score += 8.0 * waste * waste * cap;
        } else {
            // post residual too small for next item: slight penalty for stranding space
            score += 3.0 * pnorm;
        }
    }

    // New-bin candidate: keep it moderately attractive only when fit is poor elsewhere
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo classes against common item sizes
    let classes: [u32; 8] = [10, 20, 25, 33, 50, 40, 60, 80];
    let mut harm_bonus = 0.0f64;
    for &c in &classes {
        if post_residual >= c && post_residual % c == 0 {
            harm_bonus += 8.0;
        }
        if post_residual > 0 && c % post_residual.max(1) == 0 {
            harm_bonus += 2.0;
        }
    }
    score -= harm_bonus;

    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space penalty: small unusable residues (below minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Harmonic thresholds via integer division on post_residual
    let tier = post_residual / 10;
    match tier {
        0 => score -= 5.0,          // near-perfect
        1 | 2 => score += 3.0,      // awkward small gap
        3 | 4 | 5 => score -= 2.0,  // fits mid items (30-50)
        6 | 7 | 8 | 9 => score -= 4.0, // roomy
        _ => {}
    }

    // Lookahead: reward if next item exactly fills post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // harmonic match: next item divides residual
            if post_residual % next_item_size == 0 {
                score -= 30.0;
            } else {
                score -= (post_residual - next_item_size) as f64 * 0.2;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: avoid opening new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer only when current residuals are well-used or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = mean_residual / bin_capacity as f64;
        let bias = 55.0 + 120.0 * (1.0 - progress) - 80.0 * waste;
        score += bias;
    }

    // Mild pressure to consolidate into fewer bins
    score -= (open_bins_count.min(20)) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Gap is "dead" if no plausible future item (>= 1, but typical min ~10)
        // can use it. Penalize gaps below the minimum item size harshly.
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual <= 15 {
            score += 12.0;
        }
        // Squared penalty on very tight leftovers to prefer exact fits.
        score += (post_residual as f64).powi(2) * 0.01;
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Near-miss lookahead: partial credit if next item almost fits.
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.1;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: penalize selecting bins when many bins are open,
    // encouraging consolidation into already-strained bins.
    score += open_bins_count as f64 * 0.05;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins),
    // which concentrates filling.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.2;

    // New-bin candidate: only attractive when the item leaves a large,
    // well-shaped residual or current fits are poor.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: modest; becomes attractive when existing
        // bins would leave tiny dead space.
        score = (bin_capacity - item_size) as f64 * 0.9;
        if post_residual < 10 && item_size < bin_capacity {
            score -= 5.0; // fresh bin with tiny remainder is fine early
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward when next item exactly matches the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.9 * gap;
        // Perfect chaining bonus: next item fills this bin exactly.
        if post_residual == next_item_size {
            score -= 45.0;
        }
        // Penalize leaving a residual that no plausible item (1..=100) can use well.
        if post_residual > 0 && post_residual < 10 {
            score += 12.0; // tiny dead space
        }
    } else {
        // Last item: prefer tightest fit, slight bonus for emptying a bin.
        score -= 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tighter"
    // and should absorb the item to consolidate space.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so open bins usually win; relax slightly as stream progresses.
        score += 30.0 - 10.0 * progress;
        // If next item is huge, a fresh bin has room for it after this item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Many open bins with slack: discourage opening yet another bin.
        score += 0.6 * open_bins_count as f64;
    }

    // Small penalty scaled by item size: large items prefer tightest absolute fit.
    score += 0.05 * item_size as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual (dead-space penalty).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_frac * waste_frac * (bin_capacity as f64);

    // Perfect fit gets a strong discount.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a gap that the next item cannot use.
            score += 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild penalty on opening new bins late in the stream when many bins are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few items remain or many bins open.
        score += 6.0 + 10.0 * progress + 0.3 * open_bins_count as f64;
        // But if item is large and would leave tiny unusable residue elsewhere, allow it.
        if item_size >= bin_capacity / 2 {
            score -= 4.0;
        }
    } else {
        // Slight preference for using already-open bins as stream progresses.
        score -= 2.0 * progress;
    }

    // Fragmentation guard: penalize leaving residuals that are too small for the
    // minimum plausible item size (1..100 unknown, use 10 as conservative anchor
    // derived from observed stream structure via mean_residual scaling).
    let anchor = (mean_residual.max(1.0)).sqrt() * 2.0;
    if post_residual as f64 > 0.0 && (post_residual as f64) < anchor {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual (tight fit)
    let mut score = pr as f64;

    // Non-linear coupling: quadratic reward for very tight fits, weighted by stream progress
    let tight = (1.0 - norm_pr).powi(3);
    score -= 60.0 * tight * (0.4 + 0.6 * progress);

    // Penalize small-but-not-zero dead space (unusable slivers), smoothly
    let sliver = norm_pr * (1.0 - norm_pr);
    score += 25.0 * sliver * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 45.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: reward leaving room for the next item
    let next = next_item_size as f64;
    if next > 0.0 {
        let room = (pr - next).max(0.0) / cap;
        let perfect_next = ((pr - next) as f64).abs();
        score -= 18.0 * (1.0 - (perfect_next / cap).min(1.0)) * (1.0 - progress);
        score += 10.0 * room * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 6.0;

    // Mean residual alignment: prefer bins near the mean residual to balance loads
    score += ((pr - mean_residual) / cap).abs() * 12.0;

    // New-bin candidate: penalize slightly so it only wins when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
