        if post_residual < 10 {
            score += 40.0;
        }
        // Modulo-10 harmonic class: residuals divisible by 10 pair well with
        // common item sizes; reward them slightly.
        let class = post_residual % 10;
        score -= (10 - class as f64) * 0.5;

        // Integer-division thresholds on post_residual (quarters of capacity).
        let quarter = post_residual / (bin_capacity / 4);
        match quarter {
            0 => score += 15.0,          // < 25: poor leftover
            1 => score += 5.0,           // 25..49
            2 => score -= 3.0,           // 50..74: good zone
            _ => score -= 6.0,           // >= 75: very reusable
        }
    }

    // Coupling with next item (lookahead): if the next item fits exactly in
    // the post-residual, big reward; if it nearly fits, small penalty for waste.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            let slack = post - next;
            if slack == 0.0 {
                score -= 45.0; // exact chained fit
            } else if slack < 10.0 {
                score -= 20.0;
            } else {
                score += slack * 0.2;
            }
        } else {
            score += 8.0; // next item cannot use this bin
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_residual {
        score -= 12.0;
    }

    // Mild penalty for spreading across many open bins: prefer consolidation
    // when mean residual is low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let _ = progress;
    if (bin_residual as f64) < mean_residual {
        score -= 4.0; // tighter-than-average bin preferred
    } else {
        score += 2.0;
    }

    // New-bin candidate tie-break: keep it slightly unattractive unless
    // remaining open bins would create heavy dead space (handled above).
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<= 10) are nearly unusable
    // for future items (min size 1..100 stream, but typical small items are rare).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0; // heavy penalty for creating a dead sliver
    } else if post_residual > 10 && post_residual <= 20 {
        score += 25.0;
    } else if post_residual > 20 && post_residual <= 35 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to residual).
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 30.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bins pressure: penalize bins when many bins are open,
    // encouraging consolidation into existing bins.
    score += 2.5 * open_bins_count as f64;

    // Prefer bins with residual close to the mean (avoid fragmenting outliers).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: it becomes dead space.
        score += 15.0;
    }

    // New-bin candidate: only attractive when no existing bin offers a decent fit
    // (i.e., this bin would otherwise be a poor choice). An empty bin starts with
    // full residual; make it moderately costly so it's chosen only when it wins.
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
        // If the item is large, opening a fresh bin is more acceptable.
        if item_size >= 60 {
            score -= 30.0;
        }
    }

    // Slight progression term: later in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect 2-step match: post_residual exactly equals next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect lookahead match
        } else if post_residual >= next_item_size {
            // next item fits, penalize proportional to leftover waste after both placements
            let two_step_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.35 * two_step_waste;
        } else {
            // next item does not fit here; penalize small unusable post_residual
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(60.0);
        }
    }

    // Penalize dead space: very small post_residual that likely can't host future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer bins whose residual is already below mean (tight bins get filled first).
    score += 0.4 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mild pressure to close out bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight bias against opening new bins when decent fits exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let usable = if next_item_size > 0 {
            (post_residual >= next_item_size) as i32 as f64
        } else {
            0.5
        };
        if usable == 0.0 {
            score += 25.0 * (1.0 - (post_residual as f64) / 50.0);
        } else {
            score -= 10.0;
        }
    }

    // Lookahead: bonus if the next item also fits in this bin after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins with residual below the mean (consolidate emptier space).
    score += 0.15 * ((bin_residual as f64) - mean_residual).max(-50.0).min(50.0);

    // Mild preference for reusing bins vs opening new ones as stream grows.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as the stream progresses.
        score += 15.0 + 25.0 * progress + 2.0 * (open_bins_count as f64);
    } else {
        score -= 5.0;
    }

    // Perfect fit gets a big discount.
    if post_residual == 0 {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: quadratic dead-space penalty (smooth, non-linear)
    let mut score = prn * prn * cap;

    // Smooth polynomial coupling of residual with stream progress:
    // later in the stream, larger residuals become more costly (waste compounds)
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - 0.5 * progress);
    score *= progress_coupling;

    // Cubic interaction: penalize residuals that neither fit the lookahead item well
    // nor are near zero, weighted by how far along we are
    let nr = next_item_size as f64;
    if nr > 0.0 {
        let fit_gap = (pr - nr).abs() / cap;
        score += 20.0 * fit_gap * fit_gap * (1.0 + progress);
        // reward exact-ish fit for the lookahead item
        let lookahead_fits = if pr >= nr { 1.0 } else { 0.0 };
        score -= 8.0 * lookahead_fits * (1.0 - fit_gap) * (1.0 + progress);
    }

    // Smooth penalty for bin scarcity: if few fitting bins, favor using this one
    let fbn = fitting_bins_count as f64;
    let scarcity = 1.0 / (1.0 + fbn * fbn * 0.25);
    score -= 15.0 * scarcity * (1.0 + progress);

    // Mean-residual deviation term (cubic smooth): placing into bins far from
    // the mean residual spreads capacity unevenly; penalize mildly
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * dev.abs() * cap;

    // New-bin candidate handling: smooth discouragement of opening new bins
    // unless current residual is nearly exhausted (post_residual would be tiny)
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        let tightness = 1.0 - prn; // how "wasteful" leaving this item alone is
        score += 25.0 * (1.0 - progress * 0.5) - 30.0 * tightness * tightness * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (C/8 grid)
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (post_residual % (bin_capacity / 8)) as f64 / (bin_capacity / 8) as f64;
    score += 6.0 * class * (1.0 - class); // penalize mid-class residuals (awkward dead space)

    // Reward exact harmonic residuals (0 mod small divisors are reusable)
    if post_residual == 0 { score -= 40.0; }
    else if post_residual % 10 == 0 { score -= 12.0; }
    else if post_residual % 5 == 0 { score -= 6.0; }
    else if post_residual < 10 { score += 25.0; } // near-dead space

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // integer-division threshold: how snugly next item fits
            let k = post_residual / next_item_size.max(1);
            score -= 5.0 * (k.min(4) as f64);
        } else {
            score += 10.0 + 0.2 * next_item_size as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - frac * bin_capacity as f64).abs();
        let pressure = 0.5 * open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        score = 55.0 + fragmentation * 0.5 + pressure * 10.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 18.0; // nothing open fits the future well; fresh bin OK
        }
    }

    // Mild preference to fill fuller bins (small post_residual) early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 8.0 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A post_residual that is too small for typical items is "dead space".
    if post_residual > 0 {
        let dead_threshold = 10.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
    } else {
        // Perfect fit is highly desirable.
        score -= 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 6.0;

    // Open-bin pressure: penalize selecting bins when many bins are open,
    // encouraging consolidation into fewer bins.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating a gap that the next item cannot use: penalize.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., filling up the emptier-relative bins less aggressively keeps
    // larger residuals available; actually prefer filling bins with SMALL
    // residual to consolidate).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit (i.e., when this call is the empty-bin
    // candidate, apply a moderate penalty so it's chosen only for poor fits
    // elsewhere, but less penalty when many bins are open and mean residual
    // is fragmented).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let new_bin_penalty = 20.0 - fragmentation * 10.0;
        score += new_bin_penalty.max(5.0);
    }

    // Slight progression term: as the stream advances, be slightly more
    // willing to use existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot reuse this residual: penalize proportional waste.
        let waste = next_item_size.min(post_residual) as f64;
        score += 0.5 * waste;
    }

    // Reward tight fits relative to current bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Penalize creating dead space far below the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer bins below mean residual (consolidate space).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // New-bin candidate: only attractive when no good reuse exists.
    if bin_residual == bin_capacity {
        let reuse_quality = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += 30.0 - 20.0 * (1.0 - progress) - 25.0 * (1.0 - reuse_quality);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good; penalize awkward dead space.
    let dead_zone = if post_residual > 0 && post_residual < 10 { 25.0 } else { 0.0 };
    score += dead_zone;

    // Exact fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            // next item cannot use the leftover: mild penalty proportional to leftover
            score += 0.3 * post_residual as f64;
        }
    }

    // Last chance bin: strongly favor using the only bin that fits, to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Progress-based time horizon: early in the stream, prefer consolidating into open bins
    // (keep scores for existing bins lower); late in the stream, allow new bins more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_flag = (bin_residual == bin_capacity) as i32 as f64;

    // Penalize opening a new bin early; relax later.
    score += new_bin_flag * (30.0 - 25.0 * progress);

    // Favor bins with residuals below the mean (tighter bins first), keeping looser bins
    // available for larger future items.
    score += 0.5 * (mean_residual - bin_residual as f64).abs()
        * if (bin_residual as f64) < mean_residual { 1.0 } else { -1.0 };

    // Mild penalty for spreading across many open bins when this bin is already tight.
    if open_bins_count > 4 && post_residual < 20 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: penalize post_residual non-linearly,
    // weighted by stream progress (later in stream -> dead space matters more).
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * norm_item * 2.0;
    score += poly * cap * 0.5;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - norm_pr) * (1.0 + 2.0 * progress) * 10.0;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly unless post_residual of this bin would be
    // large dead space compared to mean residual.
    if bin_residual == bin_capacity {
        score += 5.0 + progress * 10.0;
        if norm_pr < 0.15 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits the post residual exactly-ish, reward.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= (1.0 - diff / cap) * 8.0 * (1.0 + progress);
    }

    // Mean residual coupling: prefer bins near mean residual (smooth quadratic).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 6.0;

    // Many open bins: slight preference to fill existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that land in
    // "reusable" classes (large enough to accept common item sizes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional capacity position of the post-residual.
    let frac = pr / cap;

    // Class bonus: post-residuals that are multiples of small divisors
    // (e.g. divisible by 10 or 20) are more likely to be exactly filled later.
    let pr_u = post_residual;
    if pr_u > 0 {
        if pr_u % 10 == 0 { score -= 4.0; }
        if pr_u % 20 == 0 { score -= 3.0; }
        if pr_u % 25 == 0 { score -= 2.0; }
    } else {
        // Perfect fit: strongest reward.
        score -= 25.0;
    }

    // Dead-space penalty: residuals too small to hold any plausible item
    // (below the minimum item size) are wasted.
    if pr_u > 0 && pr_u < 10 {
        score += 15.0 * (10.0 - pr) / 10.0;
    }

    // Harmonic threshold classes on post_residual via integer division.
    let class = pr_u / 25; // 0..4
    score -= match class {
        0 => 6.0,       // 0..24: tight but risky
        1 => 8.0,       // 25..49: still useful for medium items
        2 => 6.0,       // 50..74: very reusable
        3 => 4.0,       // 75..99: half-empty, less urgent
        _ => 0.0,
    };

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well the next item fills the leftover.
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 8.0 * fill;
        } else {
            // Next item won't fit here; slight penalty for leaving a large gap.
            score += 2.0 * frac;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless current
    // open bins are quite full (harmonic fill threshold).
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count > 0 { mean_residual / cap } else { 1.0 };
        // If mean residual across open bins is small (bins nearly full),
        // opening a new bin is reasonable: reduce the penalty.
        let base = 12.0;
        score += base - 10.0 * (1.0 - pressure.min(1.0));
        // Early in stream, slightly favor consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 3.0 * (1.0 - progress);
    }

    // Mild preference for bins tighter than the mean residual (best-fit flavor
    // with harmonic coupling to mean).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    let min_gap = 1u32;
    if post_residual > 0 && post_residual < min_gap {
        score += 1000.0;
    }
    // Penalize gaps that cannot fit the lookahead item (creates unusable space for k=2 horizon).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let fit_ratio = post_residual as f64 / bin_capacity as f64;
        score += fit_ratio * 20.0;
    }

    // Tightness of current fit: prefer bins where item fills a large share of residual.
    if bin_residual > 0 {
        let fill = item_size as f64 / bin_residual as f64;
        score -= fill * 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    // and make the new-bin candidate less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more when many bins already open.
        score += 10.0 + pressure * 2.0;
    } else {
        score -= pressure.min(10.0);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    // when the item fits well, above mean otherwise.
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small leftover
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / 50.0);
    }

    // Penalize dead space that cannot fit the next item (wasted gap)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins tighter than the mean residual (best-fit bias)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New empty bin candidate: make it unattractive unless residual is very tight
    if bin_residual == bin_capacity {
        score += 10.0 + 0.2 * open_bins_count as f64;
        // But attractive if item perfectly splits capacity with next item
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 70.0;
        }
    }

    // Late in stream: consolidate, avoid spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize relative waste of residual space.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize large dead space (hard-to-fill leftovers), worse late in stream.
    if post_residual < item_size {
        score += 6.0 + 4.0 * progress;
    }
    if post_residual == 0 {
        score -= 8.0; // perfect closure
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: bonus if leftover can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 4.0; // this placement blocks next item in this bin
        }
    }

    // New-bin candidate: open a new bin only when fits are poor or item is huge.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.7 || (fitting_bins_count > 0 && fill_ratio < 0.5) {
            score -= 5.0 + 3.0 * progress;
        } else {
            score += 10.0; // discourage proliferation of open bins
        }
    }

    // Global pressure: many open bins with big mean residual -> reuse bins.
    if mean_residual > item_size as f64 * 1.5 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, mildly non-linearly scaled
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth polynomial coupling with stream progress:
    // late in the stream, tighten more (favor fuller fills)
    let late_factor = progress * progress;
    score += 12.0 * late_factor * pr_norm;

    // Penalize dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 8.0 * gap * (1.0 - progress);
        // Reward if next item fits this bin's post residual
        let fits = (pr - nxt).max(0.0) / cap;
        score -= 6.0 * fits * (1.0 - progress);
    }

    // Last-chance bonus: smooth exponential-ish reward
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - late_factor);
    }

    // Mild penalty for spreading across many open bins
    score += 0.4 * open_bins_count as f64 * pr_norm;

    // Smooth divergence penalty near-zero residual (wasted tight fits when misused)
    score += 3.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does it fall in?
    let q = post_residual / 10; // 0..10 decile classes
    let class_penalty: f64 = match q {
        0 => -6.0,            // perfect fill
        1 => 4.0,             // 1-9 dead space: worst class
        2 | 3 => 1.5,         // 10-39: usable by small items
        4 | 5 => 0.0,         // 40-59: mid class
        6 | 7 => -1.0,        // 60-79: plenty of room
        _ => -2.5,            // 80-100: near-empty
    };
    score += class_penalty;

    // Dead-space danger: post_residual too small for the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item lands exactly in this bin's residue class
            let diff = post_residual - next_item_size;
            let bonus = if diff == 0 { 10.0 } else if diff <= 10 { 5.0 } else { 2.0 };
            score -= bonus;
        } else {
            // Next item won't fit here; penalize residues that can't absorb it
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 7.0;
        if post_residual <= 15 { score -= 3.0; } // and it fills nearly perfectly
    } else if fitting_bins_count > 1 {
        // With many options, prefer tight fits (lower post residual)
        score += (fitting_bins_count as f64 - 1.0) * 0.4;
    }

    // Integer-division threshold on bin_residual: high-residue bins are flexible
    let half = bin_capacity / 2;
    if bin_residual >= half {
        score -= 1.5;
    }

    // Mean-residual coupling: if this bin's residual deviates from mean, nudge toward consolidation
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    // Late stream: consolidate harder, avoid opening bins near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.05;

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 5.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 4.0; // pairing potential makes a fresh bin attractive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 40 {
        score += 5.0;
    } else {
        // Larger usable residuals get a mild reward relative to baseline.
        score -= 3.0;
    }

    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: penalize spreading across many open bins mildly,
    // scaled by stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.15 * (0.5 + progress);

    // Mean residual coupling: if this bin is much tighter than average,
    // placing here reduces fragmentation of the loose bins.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would
    // be left with unusable dead space.
    if bin_residual == bin_capacity {
        score += 25.0;
        if post_residual < 10 && post_residual > 0 {
            score -= 55.0; // allow new bin when it avoids tiny-gap creation elsewhere
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward bins whose residual after placement
    // matches the next item exactly or closely.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as u32 == next_item_size {
            score -= 150.0; // chain: this bin will be exactly filled by next item
        } else if next_item_size <= post_residual {
            score -= 60.0 - gap.min(60.0); // next item fits here afterwards
        } else {
            score += gap * 0.5; // next item won't fit -> dead space risk
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 35.0;
        // but if next item is huge and nothing fits well, new bin is reasonable
        if next_item_size > item_size && post_residual < next_item_size {
            score -= 20.0;
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Lookahead: penalize if the next item cannot fit the leftover space,
    // reward if it fits snugly (post_residual >= next_item_size).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 25.0 + (next_item_size - post_residual) as f64;
        }
    }

    // Last chance: this is the only open bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer bins with residual above item size already tight relative to mean.
    score += 0.5 * (mean_residual - bin_residual as f64).abs();

    // Early stream: mild preference for spreading load; late stream: pack tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.2 * progress;

    // New-bin candidate: make it unattractive unless existing bins are very fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - bin_capacity as f64).abs();
        let base_penalty = 500.0;
        // If few fitting bins and residuals are small, opening a new bin is reasonable.
        let relief = if fitting_bins_count == 0 { 800.0 } else { 0.0 };
        score = base_penalty + fragmentation * 0.3 - relief;
        if post_residual == 0 { score -= 1000.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space, with non-linear shaping.
    let mut score = pr as f64;

    // Non-linear polynomial coupling with stream progress:
    // early on, prefer tight fills (small post_residual); later, value flexibility.
    let tightness = 1.0 - x;
    let poly = progress * (2.0 * x - 1.0) * (1.0 - x * x);
    score -= 30.0 * poly;

    // Reward near-perfect fits super-linearly.
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small for typical items (smooth quadratic).
    let dead = if x < 0.1 { (0.1 - x) * (0.1 - x) } else { 0.0 };
    score += 60.0 * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        let fits_next = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        let gap = ((post_residual as i64 - next_item_size as i64).abs()) as f64 / cap;
        score -= 15.0 * fits_next * (1.0 - gap * gap);
        score += 8.0 * (1.0 - fits_next) * (x * x);
    }

    // Prefer reusing bins when many are open (encourage consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * x;

    // Deviation from mean residual: prefer bins close to mean (balance).
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate handling: empty bin gets moderate baseline penalty
    // so it only wins when open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 12.0 + 18.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 define "usable" slots.
    // Residuals that are multiples of 10 (or small multiples) pair well with
    // common item sizes; highly fragmented residuals (post_residual % 10 in 1..3)
    // are near-dead space and should be penalized.
    let post = post_residual;
    let residue_class = (post % 10) as f64;
    let dead_penalty = match post % 10 {
        0 => -6.0,           // perfect slot, reusable by many item sizes
        1 | 2 | 3 => 8.0,    // near-dead fragment
        4 | 5 | 6 => 3.0,    // moderate fragment
        _ => 0.0,
    };
    score += dead_penalty;

    // Integer-division threshold: small absolute residuals are dead space.
    let small_space = post / 10; // number of "decades" of free space left
    if small_space == 0 {
        score += 25.0; // bin is essentially closed after placement
    } else if small_space == 1 {
        score += 10.0;
    } else if small_space <= 3 {
        score += 3.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // Reward bins that remain useful for the lookahead item,
            // scaled by how tightly the next item will fit (harmonic fit quality).
            let tightness = 1.0 - (next_item_size as f64 / post as f64);
            score -= 4.0 + 6.0 * tightness;
            // Extra reward if the pair leaves a residue on a good class (multiple of 5/10).
            let pair_res = post - next_item_size;
            if pair_res % 10 == 0 {
                score -= 5.0;
            } else if pair_res % 5 == 0 {
                score -= 2.5;
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted lookahead.
            score += 2.0 + (next_item_size - post) as f64 * 0.15;
        }
    } else {
        // Last item in stream: just minimize leftover; exact fit is best.
        if post == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has no fragmentation history;
    // make it attractive only when the item is large relative to capacity
    // (big items deserve fresh bins) or no existing bin fits well.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.6 {
            score -= 5.0; // large item: fresh bin is fine
        } else {
            score += 8.0; // small item: prefer an existing bin
        }
    }

    // Mild pressure against hoarding many open bins with scattered residuals:
    // when mean residual is high and bins are many, prefer consolidation.
    if open_bins_count > 3 && mean_residual > (bin_capacity as f64) * 0.4 {
        score -= 1.5;
    }

    // Stream progression: early on, be slightly conservative (prefer tight fits),
    // later, allow more aggressive packing into partially-filled bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (min size 1..10)
    // are wasted; small gaps are worse than moderate gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: many open bins -> discourage new bins.
    if bin_residual == bin_capacity {
        score += 25.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than average.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Late in the stream, be conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize wasted residual proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 40.0 * (waste / 100.0).min(1.0);
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Penalize leaving dead space in large-residual bins lightly.
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it unattractive unless open bins are nearly full.
    if bin_residual == bin_capacity {
        let avg_fullness = bin_capacity as f64 - mean_residual;
        let pressure = (avg_fullness / bin_capacity as f64).clamp(0.0, 1.0);
        score = 250.0 - 200.0 * pressure;
        // If the next item fits perfectly in the fresh bin, allow opening.
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 400.0;
        }
        // Late in the stream, opening fresh bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash post_residual so small leftovers dominate.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * (1.0 - tightness).powi(3);

    // Penalize dead space: residuals that are too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this residual: penalize proportionally wasted space.
            score += 10.0 * (post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: strongly prefer tightest fit anywhere.
        score -= 40.0 * (1.0 - tightness);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: slightly penalize to let tightness dominate.
        score += 5.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    // (mean residual low) or many bins are open and none fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / (bin_capacity as f64);
        // Opening a new bin penalized by default; discounted as stream progresses
        // or when existing residuals are small (poor future fit potential).
        score += 30.0 * (1.0 - progress) - 50.0 * (1.0 - crowded);
        // If item is large, a fresh bin wastes less capacity overall.
        score -= (item_size as f64) * 0.15;
    } else {
        // Mild bonus for filling existing bins as stream matures.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * progress;
    }

    // Global consolidation: when many bins are open, discourage spreading.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear coupling: post_residual normalized, shaped by stream progress
    let pr_norm = post_residual as f64 / bin_capacity as f64;
    let shape = (pr_norm * std::f64::consts::PI).sin();
    score += 12.0 * shape * (0.5 + progress);

    // Penalize large dead space more aggressively as stream progresses
    score += 8.0 * pr_norm * pr_norm * (1.0 + 2.0 * progress);

    // Reward tight fits: small post_residual gets a bonus
    score -= 10.0 * (-pr_norm * 6.0).exp();

    // Last-chance bin bonus: avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (nx - post_residual as f64).abs() < 1.0 {
            score -= 6.0;
        } else if nx > post_residual as f64 {
            score += 3.0 * ((nx - post_residual as f64) / bin_capacity as f64);
        } else {
            score -= 2.0 * (post_residual as f64 - nx) / bin_capacity as f64;
        }
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.15 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Deviation from mean residual: prefer bins near mean (balanced usage)
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 5.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit strongly rewarded
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover space by divisibility
    // into common item-friendly chunk sizes (mod arithmetic).
    let pr = post_residual as i64;
    let mut harmonic_bonus: f64 = 0.0;
    for &chunk in &[10i64, 20, 25, 50] {
        if pr % chunk == 0 && pr > 0 {
            harmonic_bonus += 15.0; // leftover divisible into likely future items
        }
    }
    score -= harmonic_bonus;

    // Penalize dead space that cannot fit the next item (lookahead waste)
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += 40.0; // unusable for lookahead item => dead space
        } else {
            // reward residual that tightly matches next item
            let slack = (post_residual as u32 - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize very small leftovers that waste capacity (modulo threshold)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Mild penalty for spreading across many open bins when residual is large
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Progress-aware: later in stream, prefer tighter fits more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below the minimum item size (1) are impossible, but tiny gaps
    // relative to typical item sizes are wasteful. Penalize gaps that are
    // nonzero but very small.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - pr) * 3.0; // dead-space penalty for tiny gaps
    }

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tight fit reward: residual close to zero relative to capacity.
    score -= (bin_capacity as f64 - pr) * 0.5;

    // Last chance: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Open-bins pressure: fewer open bins is better; penalize spreading.
    score += open_bins_count as f64 * 2.0;

    // Reward bins whose residual is below mean (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item could use this bin's post residual,
    // reward keeping this bin; otherwise penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // offers a good fit (residual much larger than item) and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so new bins are used only for poor fits elsewhere.
        score += 120.0 + progress * 80.0;
        // If item nearly fills a fresh bin, allow it.
        if item_size * 4 >= bin_capacity * 3 {
            score -= 150.0;
        }
        // If many open bins can fit the item, discourage opening new bin.
        if fitting_bins_count > 2 {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.18;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 20.0;

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }
    if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
        // Lookahead: this bin's leftover cannot host the next item.
        score += (post_residual as f64).max(0.0) * 0.3;
    } else if next_item_size > 0 {
        // Lookahead bonus: leftover can host next item.
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins with residuals far from the mean (fragmentation control).
    let dev = bin_residual as f64 - mean_residual;
    score += dev.abs() * 0.15;

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64) * 0.1;

    // Many open bins: favor filling existing ones over opening new.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 12.0 + (item_size as f64) * 0.2;
        if fitting_bins_count > 0 && post_residual as f64 >= item_size as f64 * 0.5 {
            score += 20.0; // discourage new bin when a decent fit exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer bins that leave small post_residual (tight packing).
    // Later, value residual retention more (flexibility for the tail).
    let tightness = (pr / cap) * (pr / cap);
    let early_weight = (1.0 - progress).powi(2);
    let late_weight = progress * progress;
    score += 18.0 * tightness * early_weight;
    score -= 10.0 * tightness * late_weight;

    // Smooth cubic shaping of post_residual: penalize mid-range dead space,
    // reward near-full placements.
    let x = pr / cap;
    score += 6.0 * (x - x * x * x);

    // Lookahead coupling: reward post_residual that still fits next item,
    // penalize residual just below next item size (unusable sliver).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = ((pr - nx) / cap).powi(2);
            score -= 9.0 * (1.0 - slack) * (0.5 + 0.5 * progress);
        } else {
            let gap = (nx - pr) / cap;
            score += 7.0 * gap * gap * (1.0 - progress);
        }
    }

    // Last-chance bin: penalize abandonment when few bins can fit the item.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate: smooth sigmoid-like penalty, relaxed late in stream
    // and when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 14.0 * (1.0 - progress) * (1.0 - fill);
        score -= 6.0 * progress * fill;
    }

    // Mild preference for bins below mean residual (balance residual spread).
    score += 2.5 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    } else if post_residual == 0 {
        // Perfect fill is strongly rewarded.
        score -= 100.0;
    }

    // Reward tight fits relative to item size (low waste ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; with few, opening is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.8;

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // Dead space that the known next item cannot use.
        score += 15.0;
    }

    // Deviation from mean residual: prefer bins whose residual is near/above average usage.
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: make it attractive only when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * 2.0;
        let poor_fit = if fit_ratio < 0.9 { 40.0 } else { 0.0 };
        score = 20.0 + crowded - poor_fit;
        if post_residual == 0 { score = 1e9; } // unreachable, new bin has post_residual = capacity - item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);

        // Extra bonus for exact match (item + next item perfectly fill the bin).
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: reward tight fits even more since no future coupling matters.
        score -= 20.0;
    }

    // Penalize tiny dead space that nothing can use (dead space < 10 is unusable given min size 1,
    // but small residuals relative to mean residual are harder to fill later).
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.35 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Discard the new-bin candidate unless current bins would leave large waste.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If lookahead pairs perfectly with a fresh bin, allow opening it.
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 40.0;
        }
    }

    // Prefer spreading load across bins when many bins are open (balance residuals).
    score += 0.15 * ((post_residual as f64) - mean_residual);

    // Mild time pressure: as the stream progresses, tighten fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (1..100 unknown dist):
    // residual in (0, 10) is nearly useless; in (10, 30) partially usable.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr);
    } else if pr >= 10.0 && pr < 30.0 {
        score += 6.0 * (30.0 - pr) / 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // (high mean residual spread) or late in the stream with many open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - pr).abs();
        score += 18.0; // base penalty: prefer existing bins by default
        score -= 30.0 * progress; // late stream: consolidating into fresh bins can help
        if mean_residual < 15.0 {
            score -= 12.0; // open bins nearly full anyway -> fresh capacity is fine
        }
        if fragmentation > 40.0 {
            score -= 10.0;
        }
        if open_bins_count > 8 {
            score -= 5.0;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 0.5 * (next_item_size as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 0.15 * (next_item_size as f64 - pr).min(60.0);
        }
    } else {
        // Last item: minimize leftover aggressively.
        score += 0.3 * pr;
    }

    // Mild pressure to fill fuller bins when many bins are open.
    score -= 0.2 * open_bins_count as f64 * (1.0 - (bin_residual as f64) / (bin_capacity as f64));

    // Small time-coupled jitter-free drift: earlier steps tolerate waste less
    // (long horizon amortizes), later steps prioritize closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Normalized post-residual
    let x = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    let coupling = poly * (1.0 + 4.0 * progress * (1.0 - progress));

    let mut score = pr;

    // Reward tight fits more strongly as the stream progresses
    score -= coupling * cap * (0.5 + progress);

    // Penalize dead space that is too small to be useful later
    let min_future = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
    let waste = (min_future - pr).max(0.0) / cap;
    score += waste * waste * cap * 2.0;

    // Penalize creating residual far below the mean residual (fragmentation)
    let frag = (mean_residual - pr).max(0.0) / cap;
    score += frag * frag * 30.0;

    // Reward using the last fitting bin to avoid opening a new one
    if fitting_bins_count == 1 {
        score -= 10.0 + 10.0 * progress;
    }

    // Mild penalty for opening a new bin early in the stream
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    // Encourage consolidation when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * x * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-fit leftover (mod-10 capacity fractions) ----
    let class = post_residual % 10;
    // Residuals in "harmonic" classes {0, 50} are reusable by mid-size items;
    // awkward leftovers (1..9, 41..49, 51..59, 91..99) are dead-space prone.
    match class {
        0 => score -= 6.0,                       // perfect decimal alignment
        5 => score -= 4.0,                       // half-class, still flexible
        1 | 9 => score += 5.0,                   // sliver leftovers
        2 | 8 => score += 3.0,
        3 | 7 => score += 1.5,
        4 | 6 => score -= 1.0,                   // near-half, decent
        _ => {}
    }

    // ---- Integer-division thresholds on post_residual ----
    let q = post_residual / 10;
    if q == 0 {
        score += 8.0;                            // <10 left: bin effectively closed
    } else if q >= 3 && q <= 5 {
        score -= 3.0;                            // 30..59: prime re-fill zone
    } else if q > 7 {
        score -= 2.0;                            // huge leftover: bin barely used
    }

    // ---- Lookahead coupling: does next item fit the post residual? ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward proportionally to how snugly the next item nests
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 4.0 + 6.0 * snug;
        } else {
            // next item cannot use this leftover: penalize dead space
            let waste = (post_residual - (post_residual % next_item_size.max(1))) as f64;
            score += 0.02 * waste;
        }
    }

    // ---- Last-chance bonus: sole fitting bin before opening a new one ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // ---- Crowding pressure: many open bins => consolidate ----
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64) * (0.05 + 0.10 * progress);
    score += crowding;

    // ---- Mean-residual anchoring: prefer bins near the mean (balanced packing) ----
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large and would
        // leave a clean harmonic residual elsewhere, or no open bin fits well.
        let clean = (bin_capacity - item_size) % 10 == 0;
        let mut new_score = bin_capacity as f64 * 0.55 + crowding;
        if clean { new_score -= 3.0; }
        if fitting_bins_count == 0 { new_score -= 20.0; }   // must open anyway
        if next_item_size > 0 && next_item_size <= post_residual { new_score -= 2.0; }
        score = score.max(new_score) + 12.0 - if fitting_bins_count == 0 { 0.0 } else { 0.0 };
        if fitting_bins_count == 0 {
            score = new_score;                              // forced new bin
        } else {
            score = new_score + 8.0;                        // discourage wasting open capacity
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable gaps (dead space < smallest item size)
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Penalize gaps too small for the lookahead item (k=2 lookahead dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.3 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open,
    // encourage using existing bins rather than opening new ones.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): make it unattractive unless
    // the item fits poorly everywhere (handled by tightness/dead-space terms).
    if bin_residual == bin_capacity {
        score += 12.0 + 0.4 * open_bins_count as f64;
    }

    // Mild stream-progression damping of open-bin pressure early on
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress;

    // Prefer bins whose residual deviates favorably from mean residual
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (small post_residual) already favored.

    // --- 2-step lookahead: reward post_residual that exactly matches next item ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect pairing: next item will exactly fill this bin.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here: reward proportionally to how snug the pair is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space left behind.
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }

        // If the next item fits and this is the ONLY bin that can fit the current item,
        // strongly prefer using it (avoid opening a bin for a lonely item).
        if post_residual >= next_item_size && fitting_bins_count == 1 {
            score -= 15.0;
        }
    } else {
        // Last item: just minimize residual, slight bonus for exact fill.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // --- Last-chance pressure: if this is the only fitting bin, discourage opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are all poor fits,
        // i.e. the item barely fits anywhere or open bins are too full.
        let tightness = (item_size as f64) / (bin_capacity as f64);
        let mean_tightness = mean_residual / (bin_capacity as f64);
        // Penalize new bin when open bins have healthy residual relative to item.
        score += 30.0 * (1.0 - mean_tightness) + 10.0;
        // But if the item is large and mean residual can't hold it comfortably, ease penalty.
        if (mean_residual as u32) < item_size {
            score -= 25.0 * tightness;
        }
        // Early in stream, slightly prefer reusing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * (1.0 - progress);
    }

    // --- Coupling with mean residual: prefer bins tighter than average (consolidate) ---
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Small penalty for leaving awkward small residuals (dead space zones).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Slight preference for filling bins earlier in the stream.
    score -= 0.02 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 40.0;

    // Penalize dead space: small unusable post-residuals that can't fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin, unless the item
    // fits poorly everywhere (large residual waste elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0 + 8.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty *= (1.0 - 0.5 * progress);
        // If the best alternative would leave big waste, soften the penalty.
        if bin_residual - item_size <= 10 {
            new_bin_penalty *= 0.3;
        }
        score += new_bin_penalty;
    }

    // Lookahead: favor bins whose post-residual can host the next item (k=2 chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 5.0;
        }
        // If next item is large, avoid squandering residual space on a small item.
        if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Global state coupling: when mean residual is high, prefer consolidating
    // into bins with residual near mean (keep a balanced pool).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Prefer bins with moderate residual when many bins are open (reduce bin count).
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Smooth non-linear coupling: waste penalty grows quadratically as stream progresses
    score += 12.0 * progress * norm_post * norm_post;

    // Perfect fit reward (post_residual near zero), stronger late in stream
    let fit_quality = 1.0 - norm_post;
    score -= 20.0 * fit_quality * fit_quality * (0.5 + progress);

    // Penalize leaving residual that just misses next item (near-fit dead space)
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap > 0.0 {
            score += 6.0 * (gap / cap) * (gap / cap);
        } else {
            score -= 8.0; // next item fits exactly here: reward
        }
    }

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty when this bin is much tighter than average (fragmentation avoidance)
    let rel = post - mean_residual;
    score += 2.0 * (rel / cap) * (rel / cap) * (1.0 - progress);

    // New-bin candidate bias: make empty bin slightly less attractive unless residuals are fragmented
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress * (open_bins_count as f64).sqrt().ln_1p();
    }

    // Reward filling bins deeply when many bins are open
    score -= 3.0 * (item_size as f64 / cap) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 5 bands.
    let band = post_residual / (bin_capacity / 5).max(1);
    score += band as f64 * 6.0;

    // Perfect (or near-perfect) fit reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Lookahead: does the next item fit exactly in the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            // Harmonic residue class of leftover after hypothetically placing next item.
            let r2 = post_residual - next_item_size;
            let band2 = r2 / (bin_capacity / 5).max(1);
            score += band2 as f64 * 4.0;
            if r2 <= 10 {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here: penalize leaving large dead space.
            score += (post_residual as f64) * 0.8;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless residual
    // space in open bins is critically small.
    if bin_residual == bin_capacity {
        score += 80.0
            + mean_residual * 0.5
            + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 50.0; // big next item: fresh bin is valuable
        }
    }

    // Prefer filling bins that are already mostly consumed (harmonic fill fraction).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 25.0;

    // Late in the stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are nearly worthless dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual < 20 {
        score += 12.0; // only fits tiny items
    } else if post_residual < 35 {
        score += 4.0; // marginal usefulness
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading into new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin count.
        score += 15.0 + 4.0 * open_bins_count as f64;
        // But if no existing bin fits well (post_residual would be dead space),
        // opening a fresh bin is attractive.
        if post_residual < 10 && bin_residual != bin_capacity {
            score -= 30.0;
        }
        // Lookahead: if the next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // Existing bin: slight reward when open-bin pressure is high.
        score -= 0.5 * open_bins_count as f64;
        // Lookahead synergy: placing here is better if next item still fits after.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score += 3.0; // this bin becomes dead after placement
        }
    }

    // Mild phase adjustment: later in the stream, be more conservative
    // (favor filling existing bins over opening new ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is an outlier; using it normalizes the pool.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact match with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 / (1.0 + diff / 10.0));
        // Perfect chain: next item exactly fills the bin after this placement
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item leaves a tiny unusable gap -> penalize
        if post_residual > next_item_size && post_residual - next_item_size < 5 {
            score += 8.0;
        }
        // Next item cannot fit at all -> this placement wastes the residual
        if post_residual < next_item_size && post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize creating dead space (small post_residual that nothing can use)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // Mild preference to consolidate into fewer bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fills (small post_residual).
    score = post_residual as f64;

    // Reward when the lookahead item can also fit into the leftover space (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 8.0 * (1.0 - progress);
    }

    // Penalize dead space that is too small for typical items (unusable waste).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is generally expensive;
    // penalize it, more so early in the stream when consolidation is valuable.
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (1.0 - progress);
        // But if no existing bin fits well (large dead space would result),
        // opening a fresh bin becomes attractive: soften the penalty.
        if fitting_bins_count == 0 || post_residual < item_size as f64 / 2.0 {
            score -= 25.0;
        }
    } else {
        // Slight reward for using bins that are already partially filled
        // relative to the mean residual (balance-aware consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Mild pressure to close out nearly-full bins.
        if bin_residual <= item_size * 2 {
            score -= 4.0;
        }
    }

    // Late in the stream, avoid spreading items across many open bins.
    if progress > 0.7 && open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) shaping
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress:
    // early on, dead space matters less; later, penalize it more strongly
    let progress_coupling = norm_pr * (2.0 + 6.0 * progress * progress);
    score += progress_coupling * cap * 0.1;

    // Reward tight fits via smooth sigmoid-like term on fit ratio
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Lookahead: reward bins whose post-residual can fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 3.0 * (nx / cap) * (1.0 - progress);
        } else {
            score += 2.0 * (nx / cap) * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Mean-residual deviation: prefer bins close to the mean residual (smooth)
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // Slight penalty for spreading across many bins late in the stream
    score += (open_bins_count as f64 / (1.0 + total_items as f64)) * 2.0 * progress;

    // New-bin candidate: smooth adaptive threshold based on mean residual
    if bin_residual == bin_capacity {
        let open_threshold = 0.35 * cap * (1.0 - 0.5 * progress) + mean_residual * 0.3;
        if item_size as f64 > open_threshold {
            score -= 6.0;
        } else {
            score += 4.0 + 8.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), but reward exact fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class of post_residual: dead space in low residue classes is worse
    // because small items (1..=10) are common and can fill them.
    let pr = post_residual as i64;
    let small_fillable = pr <= 10 && pr > 0;
    if small_fillable {
        score -= 12.0; // residual small enough that a tiny item likely plugs it
    } else {
        // penalize "awkward" residual classes via modulo arithmetic
        let awkward = match pr % 10 {
            1 | 2 | 3 => 8.0,   // hard-to-fill slivers
            4 | 6 | 7 => 4.0,
            5 => -2.0,          // half-class residual is flexible
            _ => 0.0,
        };
        score += awkward;
    }

    // Integer-division threshold: residuals that are exact multiples of common sizes
    if pr > 0 && (pr % 25 == 0 || pr % 20 == 0) {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; this bin becomes dead space
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    // or stream is early and we expect many future items to need fresh bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.5;
        if poor_fit || open_bins_count == 0 {
            score -= 25.0 + 20.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
    }

    // Mild preference for bins below mean residual (keep residuals balanced).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space zone: gap too small for the smallest plausible item (1..100 range).
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits generally: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Dead space relative measure: penalize residual waste weighted by item size.
    score += (post_residual as f64) * (1.0 - fill_ratio) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening another.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 3.0 * (open_bins_count as f64).sqrt() + 5.0 * progress;
        // But if existing fit would leave bad dead space, new bin becomes attractive.
        if post_residual > 0 && post_residual < 10 && item_size < bin_capacity {
            score -= 45.0;
        }
    }

    // Lookahead: if next item fits in the post-residual, reward leaving this gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if the leftover gap is useless for the known next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (below-mean residual bins are "nearly full" -> good to fill).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    } else {
        score += (-dev) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the
    // next item size exactly (chains the stream without opening new bins).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits here afterward: reward closeness of chain match.
            score -= 300.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item would NOT fit after placing here: penalize by gap size,
            // especially when the gap is small-but-unusable dead space.
            score += 50.0 + 2.0 * diff;
        }

        // Two-item chain: does next item leave room for a third typical item?
        if post_residual as f64 >= nxt + 10.0 {
            score -= 20.0;
        }
    }

    // Relative to mean residual: prefer bins that are already partially filled
    // (below-mean residual means well-used bin).
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: make it unattractive unless all open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 120.0;
        // If few fitting bins exist, opening a new bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early on, be conservative about opening bins; late, pack tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate handling: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score = 200.0
            - 180.0 * pressure
            - 60.0 * (1.0 - fit_ratio)
            + 40.0 * poor_fit
            + (open_bins_count as f64).sqrt() * 5.0;
        if next_item_size > 0 && (bin_capacity as u64) >= (next_item_size as u64) {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual (balance residuals)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (0.5 + progress) + pr_norm * progress * 2.0;
    score += coupling * 10.0;

    // Penalize dead space relative to next item lookahead (smooth)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap > 0.0 {
            score += (gap / 100.0) * (1.0 + progress) * 5.0;
        } else {
            score += (gap / 100.0) * 3.0; // next item won't fit here: mild reward
        }
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    let fit = fitting_bins_count as f64;
    let scarcity = 1.0 / (fit * fit + 1.0);
    score -= scarcity * 15.0;

    // Encourage filling bins tighter than the mean residual (smooth)
    score += (mean_residual - pr) * 0.3;

    // New-bin candidate: prefer it only when post_residual is large (poor fits elsewhere)
    if bin_residual == bin_capacity {
        score += 5.0 - pr_norm * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (harmonic residue classes of post_residual)
    let pr = post_residual as i64;
    let tight = (pr % 10 == 0) as f64 * 12.0
        + (pr % 20 == 0) as f64 * 8.0
        + (pr % 25 == 0) as f64 * 6.0;
    score -= tight;

    // Penalize small dead space that is hard to fill (residual in (0,10))
    if pr > 0 && pr < 10 {
        score += 15.0;
    } else if pr < 20 {
        score += 5.0;
    }

    // Reward near-perfect fits
    if pr == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if (pr as u32) >= next_item_size {
            score -= 6.0;
            // harmonic bonus if post_residual / next_item_size leaves a class-0 remainder
            if pr % (next_item_size.max(1) as i64) == 0 {
                score -= 6.0;
            }
        } else {
            score += 8.0; // bin becomes dead for the next item
        }
    }

    // New-bin candidate logic: only open a new bin when current fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty so open bins are preferred; scale with item size and open count
        let mut new_bin_score = 30.0
            + 0.15 * open_bins_count as f64
            + 0.2 * item_size as f64
            + 10.0 * (1.0 - progress);
        // If item is huge relative to mean residual, opening may be wise
        if item_size as f64 > mean_residual + 20.0 {
            new_bin_score -= 20.0;
        }
        // Very tight post fit in a new bin (item nearly fills it) is attractive
        if (bin_capacity - item_size) <= 5 {
            new_bin_score -= 15.0;
        }
        score = score.min(new_bin_score) + new_bin_score * 0.0;
        // For the new-bin call, override score with the new-bin evaluation
        return new_bin_score;
    }

    // Mild pressure toward consolidating bins when many are open
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Pressure from many open bins: discourage spreading when bins are plentiful,
    // encourage consolidation when few bins are open.
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += bin_pressure * 0.5;

    // Prefer bins whose residual is below average (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would be blocked by this placement, penalize slightly.
    else if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 6.0;
    }

    // New empty bin candidate: only attractive when current bins leave bad fits.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
    }

    // Progress-based tightening: later in stream, avoid waste more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits comfortably in the resulting residual (with slack).
    else if next_item_size > 0 && post_residual >= next_item_size + 10 {
        score -= 20.0;
    }
    // Next item cannot fit here: penalize mildly, scaled by wasted potential.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize unusable dead space (residual below minimum item size 1..100 -> below 10 typical).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Compare against mean residual: prefer bins tighter than average (good fits).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // Slight preference for opening new bins early in the stream (keep options open),
    // and for reusing bins late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress) - 10.0 * progress;
    }

    // Discourage many open bins with large residuals (fragmentation control).
    if open_bins_count > 5 && bin_residual > bin_capacity / 2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exponential bonus as post_residual approaches zero.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item (10..80 range, or 1..100 here) can plausibly fill.
    if post_residual > 0 {
        let unusable = if post_residual < 1 { 0.0 } else { 1.0 };
        score += 6.0 * unusable * (post_residual as f64 / bin_capacity as f64).sqrt();
    }

    // Perfect closure reward: bin fully consumed.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if the next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let pair_eff = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 * pair_eff;
        } else {
            // Next item won't fit here; slight penalty for leaving awkward remainder.
            score += 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested or residual is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        // Penalize opening new bins mildly; escalate penalty late in stream.
        score += 15.0 + 20.0 * progress;
        // But if mean residual is small (open bins nearly full), new bin becomes attractive.
        score -= 0.15 * (bin_capacity as f64 - mean_residual).max(0.0);
        // Early stream: keep some exploration incentive low.
        score -= 5.0 * (1.0 - progress) * congestion.max(0.0).min(3.0);
    } else {
        // Prefer reusing bins with larger residuals when many bins are open (bin consolidation).
        score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);
    }

    // Global balance: nudge toward bins whose residual is near the mean residual (avoid fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Time-horizon scaling: as stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with a non-linear penalty for awkward mid-range residuals.
    let mut score = pr
        + 18.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr)
        - 14.0 * norm_pr * norm_pr * (1.0 - norm_pr);

    // Smooth polynomial coupling of residual waste with stream progress:
    // early on, tolerate loose fits; later, punish dead space harder.
    let waste_coupling = progress * progress * (3.0 - 2.0 * progress);
    score += waste_coupling * (pr * pr / cap) * 0.35;

    // Reward tight fits (small post residual) with a smooth saturating bonus.
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 8.0 + 6.0 * snug;
    } else if next_item_size > 0 {
        // Penalize if next item likely won't fit into remaining space.
        score += 4.0 * waste_coupling;
    }

    // Mild preference toward consolidating into fewer bins when many are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 1.5 * (1.0 - waste_coupling);

    // Small pull toward bins with residuals close to this bin's residual (homogeneity).
    let dr = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 3.0 * dr * dr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base: prefer minimal post_residual (tight fit), with superlinear penalty.
    score += (post / cap).powi(3) * 40.0;

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    }

    // Harmonic class logic: post_residual divisible by common item granularities
    // (5, 10) is more likely reusable by future items; odd/tiny dead space is bad.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // small dead space (<10) is nearly unusable given min item size class
        score += 25.0;
    } else {
        if pr % 10 == 0 && pr > 0 {
            score -= 12.0; // residue matches decade class
        }
        if pr % 5 == 0 && pr > 0 {
            score -= 6.0;  // matches half-decade class
        }
        if pr % 2 == 1 {
            score += 3.0;  // odd residues fit fewer integer-size patterns
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            score -= (next_item_size as f64 / cap) * 20.0;
        } else {
            // next item won't fit here; residual likely becomes dead space
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish baseline so it only wins when
    // all open bins would create bad fits.
    if bin_residual == bin_capacity {
        score = 55.0 + (post / cap) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin is attractive if item sizes are large relative to capacity
            score -= (item_size as f64 / cap) * 10.0;
        }
    }

    // Late in the stream, prefer consolidating into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (open_bins_count as f64 / 20.0).min(1.0);

    // Slight preference for bins below mean residual (spreads load evenly).
    score += ((bin_residual as f64 - mean_residual) / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space: gaps too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 25 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual) more aggressively than linear
    if post_residual == 0 {
        score -= 25.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * tightness * tightness;
    }

    // Open bins pressure: discourage spreading across many bins unless it's a new bin
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        score += (open_bins_count as f64) * 1.5;
    } else {
        // New bin: mildly attractive when existing bins are crowded or poor fits
        score += 5.0;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if mean_residual < (item_size as f64) * 0.9 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 18.0;
    }

    // Lookahead: if next item could use the post_residual, reward leaving a usable gap
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Late in stream: prefer consolidation into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual is already favored; amplify it).
    if post_residual <= 3 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 20.0 - slack * 2.0;
            } else {
                score += slack * 0.15; // wasteful leftover after serving next item
            }
        } else {
            // next item cannot fit here: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating tiny unusable slivers (dead space) unless exact fit.
    if post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 12.0;
    }

    // New-bin candidate: only attractive when no good fit exists (late stream or
    // large item with few alternatives). Make empty bin less tempting early on.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
            score -= 10.0; // fresh bin can serve the next item too
        }
        if fitting_bins_count > 2 {
            score += 15.0; // plenty of alternatives; opening a bin is wasteful
        }
    }

    // Slight preference for fuller bins as stream progresses.
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let base = pr as f64;
    let poly = x * x * (1.0 - progress) - x * x * x * progress;
    let mut score = base - 12.0 * poly * cap * 0.1;

    // Dead-space penalty grows with progress: tiny post-residuals are bad late.
    let dead = (1.0 - x).powi(3);
    score += dead * 8.0 * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) more strongly over time.
    score -= (1.0 - x) * (1.0 - x) * 6.0 * (1.0 + progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: penalize blocking the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += ((nx - pr) / cap) * 6.0 * (1.0 + progress);
        } else {
            score -= (1.0 - (pr - nx) / cap) * 3.0;
        }
    }

    // Mild preference for fuller bins relative to mean residual.
    score += (mean_residual - pr) * 0.05;

    // New-bin candidate: neutral-ish, slightly penalized early, competitive late.
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.4 * progress) + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize into capacity/10 buckets.
    let class = post_residual / (bin_capacity / 10);
    // Dead-space penalty grows super-linearly for small, awkward residuals.
    if post_residual > 0 {
        score += 40.0 / (post_residual as f64);
    }

    // Reward placements that leave residuals in "usable" harmonic classes
    // (multiples of 10 are easy to fill with typical item sizes).
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Penalize very small dead space that no item (min size 1) is guaranteed to use,
    // but tiny residuals are worse than moderate ones.
    if post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 15.0 / (1.0 + gap as f64 / 20.0);
        } else {
            // next item cannot use this bin's remainder; penalize large leftovers
            score += (next_item_size as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins with high mean residual: discourage fragmenting further.
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual {
        score -= 4.0;
    } else if (bin_residual as f64) < mean_residual - 10.0 {
        // this bin is already tight; slight penalty for overfilling classes
        score += 3.0;
    }

    // Late in the stream, prefer closing bins tightly (compactness matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // New-bin candidate: neutral-ish baseline, only chosen when it beats poor fits.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.6 + 15.0;
        // Prefer new bin late in stream if existing fits are all bad is handled
        // implicitly by the above baseline vs. penalized fits.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual sizes that are "reusable" for typical items (>= 25, multiples of 10).
    if post_residual >= 25 {
        score -= 8.0;
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // dead space relative to lookahead
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Deviation from mean residual: prefer bins that are already partially filled
    // (below-mean residual means tighter bin -> better consolidation).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: only attractive when no open bin fits well
    // (large item, few fitting bins, high mean residual).
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).min(1.0);
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score = bin_capacity as f64 * 0.35 + pressure * 30.0 * scarcity
            + if item_size > 60 { -15.0 } else { 0.0 }
            + if fitting_bins_count == 0 { -40.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize leaving a large awkward gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    } else {
        // Last item: maximize fill.
        score -= 50.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, use it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Penalize opening new bins when the stream is early and open bins are few,
    // but allow new bins when existing residuals are all poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > 40.0;
        if poor_fit {
            score -= 10.0 + 20.0 * progress;
        } else {
            score += 25.0 - 10.0 * progress;
        }
        // Fewer open bins -> mild penalty for spreading out.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild preference for filling fuller bins overall.
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residual waste, especially when it can't fit the next item.
    if next_item_size > 0 && next_item_size <= bin_capacity {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            // Reward bins whose leftover can host the lookahead item.
            score -= 0.5 * (post_residual as f64 - next_item_size as f64).min(20.0);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Small residual waste that is dead space (below min item size) is heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Prefer tightest existing fit: closeness of item to residual.
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += fit_gap * 12.0;

    // Time horizon: early in stream, keep bins flexible (penalize near-full bins less later).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fullness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= fullness * (6.0 + 14.0 * t);

    // Global state: many open bins with high mean residual -> favor filling existing bins.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual.max(1.0);
        score += (rel - 1.0) * 4.0;
        if open_bins_count > 4 {
            score -= 3.0 * (1.0 - rel.min(2.0));
        }
    }

    // New-bin candidate: penalize opening a new bin unless current item is large and
    // existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let open_penalty = 20.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        let poor_fit_bonus = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += open_penalty + poor_fit_bonus;
        // If item is big and next item is also big, fresh bin is more attractive.
        if item_size >= 60 && next_item_size >= 50 {
            score -= 22.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual and its smooth polynomial shaping
    let x = pr / cap;
    let base = pr as f64 - 8.0 * x * (1.0 - x);

    // Non-linear coupling: penalize large residual more as stream progresses
    let progress_coupling = progress * x * x * cap * 0.6;

    // Reward tight fits (small post_residual) with a smooth bump
    let tight_fit_reward = -12.0 * (1.0 - x) * (1.0 - x);

    // Lookahead: penalize if post_residual cannot fit next item (dead space risk)
    let dead_space = if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap < 0.0 { -gap * 0.35 } else { -gap * 0.05 }
    } else { 0.0 };

    // Last-chance bin bonus: strongly favor using the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Mild penalty for spreading across many open bins
    let spread_penalty = open_bins_count as f64 * 0.05;

    // Deviation from mean residual: prefer bins with residual close to item need
    let mean_dev = (mean_residual - br).abs() * 0.02;

    base + progress_coupling + tight_fit_reward + dead_space + last_chance + spread_penalty + mean_dev
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" it falls into.
    // Bands of 10 (min item size) -> residual class determines future usability.
    let post_class = post_residual / 10;
    let next_class = if next_item_size > 0 { next_item_size / 10 } else { 0 };

    // Reward when post_residual class can host the next item's class.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact or near-exact match with next item: strong reward.
            let gap = (post_residual as i64 - next_item_size as i64) as f64;
            score -= 40.0 * (1.0 - gap / cap);
            if post_residual == next_item_size {
                score -= 60.0; // perfect chaining
            }
        } else {
            // Post residual too small for next item: penalize dead space, but
            // mildly forgive tiny residuals (class 0..1) that are near-full bins.
            if post_class >= 2 {
                score += 15.0;
            } else {
                score -= 10.0; // bin nearly closed, that's fine
            }
        }
    }

    // Modulo-arithmetic coupling: residuals divisible by common item granularities
    // (10, 20, 25) are more likely reusable in future packings.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 5.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 6.0; }
    }

    // Penalize residuals in the "dead zone" classes: too small for most items
    // (class 1..3, i.e. 10..30) but not near-zero.
    if post_class >= 1 && post_class <= 2 && post_residual % 10 != 0 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a bin should only win if the item is large
    // relative to capacity or existing bins are very fragmented.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        // Penalize opening a new bin for small items.
        score += 55.0 * (1.0 - fill_frac);
        // But if current bin leaves a bad class and next item is big, allow it.
        if next_item_size > 0 && post_residual < next_item_size && item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        // If many bins are open and mean residual is low, opening fresh is ok.
        if open_bins_count > 4 && mean_residual < 0.2 * cap {
            score -= 20.0;
        }
    }

    // Slight preference for tighter bins early in the stream (keep big residual
    // bins flexible for later large items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let flexibility_penalty = (bin_residual as f64 / cap) * (1.0 - progress) * 6.0;
    score += flexibility_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Medium dead space (10..25) also mildly wasteful.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Reward tight fits (post_residual small relative to bin).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 15.0;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of open bins,
    // making existing bins more attractive as count grows.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64) * 2.0;
    } else {
        // New-bin candidate: only attractive when no bin fits well.
        score += 20.0 + (open_bins_count as f64) * 0.5;
        // If a future item could use this fresh bin's full space, slightly better.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0;
    }
    // If next item leaves a tiny dead gap after this placement, penalize.
    if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        score += 5.0;
    }

    // Prefer filling bins that deviate below mean residual (consolidation).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Late in the stream, tighten up: avoid opening bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for leaving large dead space: waste grows quadratically
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    }

    // Perfect fit bonus: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // next item fits here too; mild reward scaled by how snugly
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit in the leftover; penalize proportionally to wasted potential
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Compare residual against mean residual across open bins:
    // bins with residual far below mean are "tight" — placing here is valuable
    let mean_diff = mean_residual - bin_residual as f64;
    score -= mean_diff * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation to avoid bin proliferation
    if open_bins_count > 3 {
        score -= 0.5 * open_bins_count as f64;
    }

    // Early stream: be more conservative, prefer tight fits; late stream: fill greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.2;

    // New-bin candidate handling: empty bin is a fallback; penalize unless
    // current open bins would leave very bad residuals
    if bin_residual == bin_capacity {
        score += 30.0 + post_residual as f64;
        // If no good fit exists elsewhere (high mean residual mismatch), allow new bin
        if mean_residual < item_size as f64 * 0.5 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear bonus.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 40.0;

    // Penalize leaving dead space that the next item could not use anyway.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward leaving exactly enough room for the next item.
            let gap = post_residual - next_item_size;
            score -= 8.0 * (1.0 - (gap as f64 / bin_capacity as f64));
        }
    } else {
        // Last item: strongly prefer filling existing bins.
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in stream, prefer opening new bins to keep flexibility;
    // late in stream, consolidate into existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 10.0 - t * 5.0;

    // Prefer bins with residuals close to the item (avoid fragmenting large residuals).
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += waste * 0.3;

    // Global pressure: many open bins -> favor filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean residual coupling: if mean residual is small, cherish bins with big residual.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 12.0 * poly;

    // Penalize dead space more as stream advances (fewer chances to fill gaps)
    score += 8.0 * (norm_pr * norm_pr) * (0.5 + progress);

    // Reward tight fits (small post residual) especially when few alternatives exist
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - norm_pr);
    }

    // Lookahead: bonus if next item fits into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - (pr / next_item_size as f64).min(1.0));
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * progress;

    // New-bin candidate: prefer it only when residual is large and progress is early
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress) - 4.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band it falls into.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of bin empty after placement

    // Integer-division thresholds: post_residual buckets via capacity / k.
    let class = post_residual / (bin_capacity / 10).max(1); // 0..=10 harmonic class
    let class_f = class as f64;

    // Reward small post_residual (tight fits), especially in low harmonic classes.
    score -= (10.0 - class_f) * (10.0 - class_f) * 1.5;

    // Dead-space penalty: residuals that are unusable (very small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Modulo arithmetic on post_residual: penalize odd/awkward residuals,
    // reward residuals that are multiples of small harmonics (2,4,5,10).
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    } else if post_residual % 2 == 0 {
        score -= 1.0;
    } else {
        score += 2.0;
    }

    // Lookahead coupling: if the next item fits the post_residual exactly or well,
    // reward heavily (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0; // perfect chain
        } else if slack < 10 {
            score -= 12.0;
        } else {
            score -= (10.0 - (slack / (bin_capacity / 10).max(1)) as f64).max(0.0) * 2.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this residual: penalize leaving large leftover.
        score += pr * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: score it relative to mean residual of open bins.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when open bins have small residuals
        // (poor fragmentation) or when item is large.
        score = 100.0 - item_size as f64 * 0.5;
        if mean_residual < 15.0 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 15.0; // next item won't fit open bins either
        }
        // Never open a new bin when a tight fit exists elsewhere.
        if frac > 0.0 && item_size <= 50 && mean_residual >= item_size as f64 {
            score += 25.0;
        }
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that are too small to be useful are heavily penalized.
    // A residual gap below the minimum item size (1) is impossible, but gaps below
    // a "usable threshold" are likely dead space. Estimate usable threshold from
    // the lookahead item and a fraction of capacity.
    let usable_threshold = if next_item_size > 0 {
        (next_item_size as f64).max(bin_capacity as f64 * 0.15)
    } else {
        bin_capacity as f64 * 0.15
    };
    if (post_residual as f64) < usable_threshold && post_residual > 0 {
        // Proportion of dead space relative to the threshold
        let dead_frac = 1.0 - (post_residual as f64) / usable_threshold;
        score += dead_frac * 40.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into new bins
    // and encourage filling existing ones (lower post_residual is already favored).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Encourage bins whose residual is close to the mean (keeps residuals uniform,
    // preserving future placement options).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement strongly (chains two good placements).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit in post_residual but this bin could have held more,
    // mild penalty for wasting space the next item might need.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate: opening a new bin wastes the residual of existing bins.
    // Only attractive when existing residuals are large (mean_residual high) or
    // item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin, discounted by how poorly current bins fit.
        let avg_waste = mean_residual.max(0.0);
        score = 100.0 - avg_waste * 0.3 + (item_size as f64) * 0.2;
        // Late in the stream, prefer consolidation into open bins.
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect (or near-perfect) fills
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 300.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 500.0; // perfect two-item chain fill
        } else if (post_residual as u32) >= next_item_size {
            let slack = (post_residual as f64 - next) / bin_capacity as f64;
            score -= 200.0 * (1.0 - slack); // tighter lookahead fit is better
        } else {
            // next item cannot fit here; penalize leaving medium dead space
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 150.0 * dead * (1.0 - dead); // worst around mid residuals
        }
    }

    // Compare post_residual relative to mean residual of open bins
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.5 * (pr - mean_residual); // leaving more than average waste
    } else {
        score -= 0.3 * (mean_residual - pr); // tighter than average is good
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 40.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bins moderately unattractive unless
    // item is large and no good fit exists (handled by lookahead penalty above)
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor bins whose post_residual is small.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating tiny dead space that nothing can reuse (dead zone < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward leaving residuals that are likely reusable sizes.
    if post_residual >= 10 && post_residual <= 40 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly or well into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect pairing
        } else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 3.0;
        }
    }

    // Last-chance bin: only one open bin can fit this item -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling: empty bin gets baseline cost, modulated by global state.
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap early or when open bins are fragmented (high mean residual),
        // expensive late in the stream when bins are scarce.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 45.0 - 20.0 * fragmentation - 10.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 30.0;
        }
        // Never open a new bin when an existing bin gives a perfect fit.
        if item_size == bin_residual && fitting_bins_count >= 1 {
            score += 100.0;
        }
    }

    // Mild time-horizon shaping: later in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Small penalty per open bin to discourage bin proliferation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear coupling: quadratic in normalized post_residual, modulated by progress.
    let prn = pr / cap;
    score += 8.0 * prn * prn * cap * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= 6.0 * (1.0 - prn).powi(3) * (0.4 + 0.6 * progress);

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (1.0 - (next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // Dead space: next item cannot use the residual.
        score += 4.0 * prn * (1.0 - (next_item_size as f64) / cap);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: penalize mildly early, more late (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * progress + 0.05 * open_bins_count as f64;
    }

    // Slight preference for bins below mean residual (balance spreading).
    score += 0.5 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // --- Tight-fit rewards (staircase thresholds on post_residual) ---
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 32.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // --- Harmonic class logic: reward residuals near multiples of 10 ---
    let m = (post_residual % 10) as f64;
    score -= (10.0 - m) * 0.9; // residual 0 mod 10 is most reusable

    // --- Lookahead coupling (k=2): harmonic match with next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size as u32 == post_residual {
            score -= 28.0; // next item fills this bin exactly
        } else if (nxt % 10.0) == m && nxt <= post {
            score -= 10.0; // same harmonic class, likely reusable
        } else if nxt > post {
            // next item won't fit here: dead-space penalty scaled by overshoot
            score += (nxt - post) * 0.35;
        }
    }

    // --- Last-chance bonus: only this bin can take the item ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- Crowding pressure: many open bins -> prefer consolidation ---
    score += (open_bins_count as f64).sqrt() * 1.2;

    // --- Mean residual alignment: prefer bins near the fleet mean residual ---
    score += (mean_residual - post).abs() * 0.15;

    // --- Stream phase: late in stream, be greedier about tight fits ---
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 3.0;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Baseline score for a fresh bin: proportional to committed space (item size)
        score = 18.0 + item * 0.25;
        // No open bin fits at all -> new bin is mandatory
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Large items anchor new bins well (less future fragmentation risk)
        if item >= cap * 0.5 {
            score -= 12.0;
        }
        // Early in stream, opening bins is cheap and builds diversity
        if t < 0.2 {
            score -= 6.0;
        }
        // Late in stream with many open bins, avoid sprawl
        if t > 0.7 && open_bins_count > 8 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are nearly unusable
    // (min item size 1 is rare); penalize them hard, scaled by gap smallness.
    if post_residual >= 1 && post_residual <= 9 {
        score += (10 - post_residual) as f64 * 6.0;
    } else if post_residual > 9 && post_residual <= 15 {
        // Moderately risky zone: small penalty to prefer leaving >15 slack.
        score += (15 - post_residual) as f64 * 1.5;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits relative to bin_residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading; encourage
    // consolidation into existing bins, make new-bin option more expensive.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and mean slack.
        score += open_bins_count as f64 * 2.5 + mean_residual * 0.05 + progress * 5.0;
        // But allow opening when existing bins would leave bad dead space.
        if post_residual >= 1 && post_residual <= 9 {
            score -= 30.0;
        }
    } else {
        // Placing into an open bin reduces bin count pressure slightly.
        score -= open_bins_count as f64 * 0.3;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0;
    } else if next_item_size > post_residual && post_residual <= 9 {
        // Next item can't use this dead space: extra penalty.
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect match: next item can fit into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + slack * 0.08);
    }

    // Penalize dead space: post_residual too small for typical next items.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Prefer bins whose residual deviates from the mean (tighten tight bins,
    // keep loose bins loose for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    // Slight preference to fill already-open bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the item into the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items
    // (non-linear: residuals below ~20 are likely unusable).
    if post_residual > 0 && post_residual < 20 {
        score += 15.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; if it barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 8.0 * next_fit;
        } else {
            score += 4.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let openness = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(2.0);
    score -= 3.0 * openness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global residual state: if this bin's residual is far below the mean,
    // it is already tight — using it up is good.
    let dev = mean_residual - post_residual as f64;
    score += 0.05 * dev;

    // Mild time decay: early in the stream, be slightly conservative about
    // filling bins deeply (keep flexibility); later, pack aggressively.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * t * fit_ratio;

    // Slight penalty for opening a new bin when open bins exist and fit is loose.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 * fit_ratio.reciprocal().min(8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let t = t.clamp(0.0, 1.0);

    // Non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - t) + pr_norm * t * (1.0 - pr_norm);
    score += 12.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 18.0 * tightness * tightness * (0.5 + 0.5 * t);

    // Penalize dead space relative to mean residual of open bins
    let mean_pr = if mean_residual.is_finite() { mean_residual } else { cap };
    let dead = (pr - mean_pr / open_bins_count.max(1) as f64).abs();
    score += 0.35 * dead;

    // Lookahead coupling: favor leaving space usable by next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = (next_item_size as f64 / pr).min(1.0);
        score -= 8.0 * fit_quality * (1.0 - fit_quality + 0.5);
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize proportionally to waste
        score += 4.0 * (1.0 - t) * (pr / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive early or when residuals are all poor
    if bin_residual == bin_capacity {
        let avg_open = if open_bins_count > 0 { mean_residual } else { cap };
        let pressure = 1.0 - (avg_open / cap).clamp(0.0, 1.0);
        score += 20.0 * (1.0 - t) * pressure + 6.0 * (pr_norm);
        score -= 10.0 * t * pressure;
    }

    // Mild penalty for proliferating open bins late in the stream
    score += 0.15 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: which capacity-fraction bucket does the leftover fall in?
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Integer division thresholds on post_residual (capacity 100 => classes of 12/13)
    let class = (post_residual / 13) as f64; // 0..7
    score -= class * 2.0; // reward bins whose leftover lands in a "high" class (large residual => still reusable)

    // Dead-space penalty: leftover too small to fit anything useful (below min item size ~ small)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Modulo arithmetic on post_residual: harmonics of 25 (quarter-capacity)
    let m25 = post_residual % 25;
    if m25 == 0 && post_residual > 0 {
        score -= 6.0; // leftover aligns with quarter-capacity: excellent for future items
    } else if m25 <= 5 {
        score += 3.0; // awkward sliver
    }

    // Coupling with lookahead item: perfect next-fit bonus
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // leftover can host the next item: mild reward proportional to tightness
        let tight = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - tight / cap);
        // harmonic check: does post_residual % next_item_size leave a clean class?
        if post_residual % next_item_size == 0 {
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this leftover: penalize proportionally wasted space
        score += 0.25 * post;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it neutral-slightly-high so we prefer existing bins,
    // unless existing bins would create heavy dead space (frac small but nonzero)
    if bin_residual == bin_capacity {
        score = cap * 0.62 + (open_bins_count as f64) * 0.15;
        // late in stream with many bins, prefer packing into open bins even more
        if step_index as f64 / total_items.max(1) as f64 > 0.7 {
            score += 5.0;
        }
        // if best possible use of an open bin would be a near-perfect fit, new bin loses
        if post_residual == 0 {
            score += 50.0;
        }
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight-fit reward: residual barely fit the item
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness;

    // Mild pressure to consolidate when many bins are open relative to mean residual
    if (open_bins_count as f64) > 6.0 && frac > mean_residual / cap {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be useful.
    // Gaps below the minimum plausible item size (1..~12) are "dead" — hard penalty.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 + (12 - post_residual) as f64 * 3.0;
    }
    // Moderately small gaps (12..25) are risky: soft penalty growing as gap shrinks.
    else if post_residual >= 12 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 0.8;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Exact match with lookahead item: strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Lookahead fits comfortably in the post residual: mild reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 12 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // (avoid opening new bins); when few are open, new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; discount slightly at stream start.
        score += 15.0 + pressure;
        // If the item leaves a large useful residual in a fresh bin, soften the cost.
        if post_residual >= 25 {
            score -= 5.0;
        }
    }

    // Tie-break toward bins below the mean residual (filling emptier bins first
    // keeps tight bins available for small items).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // If next item fits into post_residual, this bin stays useful: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 - slack * 0.4;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot use the leftover.
        let waste = post_residual.min(next_item_size - 1) as f64;
        score += waste * 1.5;
    }

    // Prefer bins whose residual is already below mean (tight bins get filled first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize the new-bin candidate mildly when decent fits exist; allow it when
    // post_residual would be large and clean (keeps future flexibility).
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Early in stream: keep bins flexible, favor larger post_residual slightly less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize awkward residuals: small leftovers that most items (>=10) can't use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit gets a strong discount.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 35.0;
        } else if next_item_size as u32 <= post_residual {
            // reward proportional to how much of the leftover the next item consumes
            let use_frac = nx / post_residual as f64;
            score -= 10.0 * use_frac;
        } else {
            // next item won't fit here; mild penalty scaled by overflow amount
            let over = (next_item_size as u32 - post_residual) as f64;
            score += 0.05 * over;
        }
    }

    // Time horizon: early in the stream, be more conservative about opening new bins
    // (favor packing into existing bins); late in the stream, tightness matters more.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * t * tightness;

    // Global state: many open bins with high mean residual -> discourage spreading;
    // prefer bins whose residual is below the mean (compact bins).
    let res = bin_residual as f64;
    let diff = mean_residual - res;
    score += 0.10 * diff; // lower residual than mean -> lower score -> favored

    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: empty bin starts at post_residual == capacity - item.
    // Make it attractive only when no open bin fits well; otherwise keep it penalized.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // forced new bin anyway
        } else {
            score += 15.0; // discourage opening new bin when alternatives exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: quadratic reward for tight fits, scaled by stream progress.
    let tight = 1.0 - (pr / cap);
    score -= 60.0 * tight * tight * (0.5 + progress);

    // Penalize dead space that the lookahead item cannot use (smooth cubic coupling).
    let usable = if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        gap
    } else {
        0.0
    };
    score += 25.0 * usable * usable * usable * (1.0 - progress);

    // Reward exact/near-exact fills strongly with smooth saturating term.
    score -= 40.0 * (1.0 - (pr / cap).powi(4));

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when bin residual is far below mean residual (fragmentation signal).
    score += 8.0 * ((mean_residual - bin_residual as f64) / cap).max(0.0);

    // New-bin candidate: make it attractive only when progress is low or fits are poor;
    // otherwise a fresh empty bin should lose to good existing fits.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress) - 15.0 * (fitting_bins_count as f64).recip();
    }

    // Small smooth regularization coupling open bins with progress.
    score += (open_bins_count as f64).ln() * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic class of post_residual: which "modular band" the leftover falls into.
    // Class 0: near-perfect fit (0..=4), Class 1: small usable gap (5..=15),
    // Class 2: medium gap (16..=35), Class 3: large gap (36..=60), Class 4: dead zone (>60).
    let harmonic_class = if post_residual <= 4 { 0u32 }
        else if post_residual <= 15 { 1 }
        else if post_residual <= 35 { 2 }
        else if post_residual <= 60 { 3 }
        else { 4 };

    // Base score: tightness of the fit, scaled by harmonic class penalty.
    let mut score = post_residual as f64
        + harmonic_class as f64 * 12.0;

    // Dead-space penalty: leftover too small for the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.9 + 8.0;
        } else {
            // Reward bins whose residue can still host the next item.
            score -= 6.0;
            // Extra harmonic coupling: residue mod capacity-quarter alignment.
            let q = bin_capacity / 4;
            if post_residual % q == 0 {
                score -= 3.0;
            }
        }
        // If the next item would fit this residue exactly, strong bonus.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can host the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when item is large
    // (residue in a "clean" harmonic class) and open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer keeping few open bins early; allow new bins when crowded.
        let crowding = (open_bins_count as f64) / 8.0;
        // Large items leave large residues anyway; penalize mildly unless
        // the item is big enough that no open bin likely has a good class.
        score += 20.0
            + crowding * -6.0
            + progress * 4.0
            - (item_size as f64) * 0.25;
        if harmonic_class <= 1 {
            score -= 10.0; // item nearly fills a fresh bin: good opening move
        }
    } else {
        // Reward using existing bins when many fit (spread load on good classes).
        if fitting_bins_count > 1 && harmonic_class <= 2 {
            score -= 4.0;
        }
    }

    // Mild preference toward bins whose residual is below the mean
    // (consolidating waste into few bins).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0 * (1.0 - (post_residual - 10) as f64 / 10.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Open bins pressure: discourage opening new bins when few bins open,
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open-bin pressure and mean residual context.
        score += 12.0 + pressure * 0.8;
        if fitting_bins_count <= 1 {
            score -= 20.0; // last chance: avoid stranding this bin
        }
    } else {
        score -= 4.0 + pressure * 0.05;
        // Last-chance bin bonus.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Slight preference toward bins tighter than average (good fits).
    score += 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Penalize small dead space (waste) more than proportionally.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 8.0;
        }

        // 2-step lookahead: reward if next item fits exactly or well into post_residual.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 120.0; // exact 2-step match
            } else if post_residual >= next_item_size {
                let slack = post_residual - next_item_size;
                // Reward closeness of next item fit; penalize leftover slack after next item.
                score -= 40.0;
                if slack == 0 {
                    score -= 60.0;
                } else if slack < 10 {
                    score -= (10 - slack) as f64 * 3.0;
                } else {
                    score += slack as f64 * 0.3;
                }
            } else {
                // Next item won't fit here; penalize proportional to gap.
                let gap = (next_item_size - post_residual) as f64;
                score += gap * 0.5;
            }
        }
    }

    // Compare against mean residual: placing here shouldn't strand above-average space.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: neutral baseline; only attractive when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        // Prefer new bin when existing bins have small scattered residuals and item is large.
        let frag = mean_residual / bin_capacity as f64;
        score -= 30.0 * frag;
        if item_size > 70 {
            score -= 20.0;
        }
    } else {
        // Slight preference to fill existing bins as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // Prefer bins with less residual overall (tighter packing).
        score += bin_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, normalized
    let cap = bin_capacity as f64;
    let frac_post = post_residual as f64 / cap;
    let frac_item = item_size as f64 / cap;

    // Strong penalty proportional to wasted space squared (dead space aversion)
    score += 40.0 * frac_post * frac_post;

    // Reward tight fits (post residual near 0)
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Lookahead: reward if next item can fit into post_residual (chained placement)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // next item fits exactly-ish: reward proportionally to how well it fills leftover
            let fill = nxt / post_residual as f64;
            score -= 10.0 + 10.0 * fill;
        } else if next_item_size <= post_residual + 10 {
            // near miss: mild penalty since leftover becomes mostly useless
            score += 3.0;
        }
        // If next item won't fit anywhere else well, keeping flexible residual matters more
        if nxt > 0.5 * cap && frac_post < nxt / cap {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer filling existing ones, discourage proliferation
    let open_f = open_bins_count as f64;
    score += 0.15 * open_f * frac_post;

    // Progress-based time horizon: late in stream, consolidate aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // Mean residual coupling: if this bin's residual deviates from mean, nudge toward balance
    let resid = bin_residual as f64;
    let dev = (resid - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate handling: only open a new bin if item is large relative to
    // average open-bin slack or no good fit exists
    if bin_residual == bin_capacity {
        // Default mild penalty so open bins with decent fits win
        score += 8.0;
        // But if item is huge and residuals are small, new bin is attractive
        if frac_item > 0.6 && mean_residual < frac_item * cap {
            score -= 15.0;
        }
        // Early stream with few bins: opening fresh bins is cheap
        if progress < 0.2 && open_bins_count < 4 {
            score -= 6.0;
        }
        // If the only fitting bin would leave terrible dead space, prefer new bin
        if frac_post > 0.5 && frac_item > 0.4 {
            score -= 10.0;
        }
    }

    // Small deterministic tie-breaker based on residual to stabilize choices
    score += (post_residual % 3) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = norm_pr;
    let poly = p * p * (1.0 - p) * 4.0; // peaks at p=0.5, vanishes at 0 and 1
    let mut score = pr * (1.0 + 0.6 * progress) + 30.0 * poly * (0.5 + progress);

    // Reward tight fits (low post residual) more as stream progresses
    score -= 40.0 * progress * (1.0 - norm_pr).powi(3);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0);
        score += 0.35 * waste * (1.0 + 0.5 * progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New bin candidate: mildly penalize opening new bins early, allow late
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 5.0 * progress;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Coupling with mean residual: prefer bins near the mean (balance)
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Dead-space penalty: leftovers in awkward classes (just over quarter/half marks).
    let mut dead = 0.0;
    if post_residual > 0 {
        let class = post_residual % 25; // modulo classes on C=100-like capacity
        if class > 0 && class <= 10 {
            dead += (10 - class) as f64 * 2.0; // tiny slivers are near-useless
        }
        if post_residual < next_item_size && next_item_size > 0 {
            dead += 15.0; // next item cannot use this leftover
        }
    }
    score += dead;

    // Reward perfect or near-perfect fits (post_residual in low harmonic classes).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let rem_after_next = post_residual - next_item_size;
            if rem_after_next <= 10 {
                score -= 25.0; // leaves clean small class
            } else if rem_after_next > quarter {
                score -= 8.0; // still generous leftover
            }
        } else {
            score += 10.0; // next item won't fit here; bin effectively closed
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        let avg_frag = mean_residual / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // prefer new bin when existing residuals are small (fragmented) or early stream
        score = cap * 0.35 + avg_frag * 40.0 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild pressure toward tighter bins when many bins open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste, but residuals below the typical item floor are the worst.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0; // risky small gap
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Fit ratio: penalize proportionally wasted capacity.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Open-bin pressure: with many bins open, prefer filling existing ones
    // rather than spreading out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if the next item is bigger than post-residual, the leftover is dead weight.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 25.0; // dead space relative to lookahead
        }
    }

    // Mean residual coupling: prefer bins below the mean residual (tighter bins)
    // to consolidate space.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: only attractive when nothing fits well. Make the empty
    // bin moderately expensive so it's chosen only when open bins are bad fits.
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64 - fit_ratio * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin can serve the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // lookahead still fits: mild reward proportional to how tight it is
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 / (1.0 + slack / 10.0);
        } else {
            // dead space smaller than next item: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.8;
        }
    }

    // Compare post_residual against mean residual: avoid creating tiny unusable gaps
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.35 {
        score += 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 5.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 100.0; // fresh bin perfectly prepping next item
        }
    }

    // Late in stream: prefer closing bins tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Nonlinear penalty for small but nonzero dead space
        let pr = post_residual as f64;
        score += 8.0 * (1.0 - (-pr / 15.0).exp());
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual of this bin
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // extra reward for tight chain fit
            let chain_gap = post_residual - next_item_size;
            score -= 6.0 * (1.0 - (chain_gap as f64 / 20.0).exp());
        } else {
            // penalize leaving residual that next item cannot use
            score += 4.0;
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let is_last_chance = fitting_bins_count == 1;
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open new bin late in stream (salvage value lower)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        // if many open bins with large mean residual, prefer reusing them
        score += 0.05 * mean_residual;
        score += 1.5 * open_bins_count as f64;
        if is_last_chance {
            // the only fitting open bin should beat a new bin unless it's a terrible fit
            score += 20.0;
        }
        // new bin is attractive when item is large (poor fits likely elsewhere)
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference for bins with residual close to item size (tight fits)
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += 5.0 * tightness * tightness;

    // Time-horizon modulation: early in stream, be slightly conservative with dead space
    let early = 1.0 - (step_index as f64 / total_items.max(1) as f64);
    score += 3.0 * early * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: tolerate residual spread (mildly reward small residual only).
    // Late in the stream: aggressively penalize residual waste via cubic term.
    let progress_poly = 0.5 + 2.0 * progress * progress;
    let mut score = base + 0.35 * (pr * pr * pr) / (cap * cap) * progress_poly;

    // Dead-space penalty: residual that no plausible future item (min size 1..cap)
    // can use well — quadratic in normalized post_residual.
    let pr_norm = pr / cap;
    score += 6.0 * pr_norm * pr_norm * (0.3 + progress);

    // Reward tight fits (small post_residual relative to item size).
    let tight = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tight * tight;

    // Last-chance bonus: only fitting bin — strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let fit_quality = (next_item_size as f64) / pr.max(1.0);
        score -= 10.0 * fit_quality;
    } else if next_item_size > 0 {
        // Next item cannot use leftover: penalize proportional to leftover size.
        score += 3.0 * pr_norm * (1.0 + progress);
    }

    // Mean-residual coupling: placing into a bin whose residual is near the mean
    // keeps balance; deviating bins get a small quadratic penalty.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate: prefer opening a new bin early (when few bins open),
    // but late in the stream prefer filling existing bins.
    if bin_residual == bin_capacity {
        let open_factor = (open_bins_count as f64).ln().max(1.0);
        score = 8.0 + 20.0 * (1.0 - progress) + 2.0 * open_factor + pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: residues mod 10 ---
    let residue = post_residual % 10;
    // Residuals that are "harmonically compatible" with typical item sizes
    // (multiples of 10 align with the 10..80 grid) are less dead.
    let dead_penalty: f64 = match residue {
        0 => 0.0,
        1 | 9 => 2.5,
        2 | 8 => 4.0,
        3 | 7 => 5.0,
        4 | 6 => 6.0,
        _ => 6.5, // residue 5
    };
    score += dead_penalty;

    // Integer-division threshold classes on post_residual:
    // classify how "usable" the leftover space is for future items (1..100).
    let usable_class = post_residual / 10; // 0..=10
    // Reward larger usable classes mildly (sub-linear, diminishing returns)
    score -= 3.0 * (usable_class as f64).sqrt();

    // Perfect fit: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward small residuals super-linearly (tight packing)
        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64).powi(2) * 20.0;
    }

    // --- Lookahead coupling: can next_item_size fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: leftover space remains harvestable by the next item.
            // Reward proportionally to how snugly the next item nests.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 + 6.0 * snug;
        } else {
            // Leftover dead space w.r.t. the lookahead item: penalize by the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(30.0) * 0.4;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only bin that fits; opening a new bin is costly.
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new empty bin: it always "fits" but wastes existing capacity.
        // Base cost: high unless few bins are open or the fit elsewhere is bad.
        score = bin_capacity as f64 * 1.2; // strong default penalty
        if open_bins_count == 0 {
            score = 0.0; // nothing else exists; new bin is fine
        }
        // Early in the stream, opening bins is cheaper (more future to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // If mean residual across open bins is large, prefer using them
        score += mean_residual.clamp(0.0, bin_capacity as f64) * 0.6;
        // If this is the only fitting bin (i.e., no open bin fits), allow new bin
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    // --- Modulo coupling between item_size and bin_residual ---
    // If item divides residual evenly (harmonic), placement is extra clean.
    if item_size > 0 && bin_residual % item_size == 0 {
        score -= 4.0;
    }

    // Mild pressure to close nearly-full bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score -= 6.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // fit a realistic item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // "Awkward gap" zone: 10..=25 residual is usable only by tiny items;
    // penalize proportionally to how deep in the dead zone we are.
    if post_residual >= 10 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward residuals that can exactly fit the next item (perfect pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual still useful for the lookahead item -> mild reward.
        score -= 5.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual cannot host the next item -> penalty scaled by gap.
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate and tight fits less).
    let pressure = open_bins_count as f64 * 0.8;
    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate: penalize more when many bins open.
        score += 15.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Slight preference for bins whose residual deviates from the mean
    // (consolidate space): low-residual bins get a nudge.
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Late-stream tightening: as the stream progresses, prioritize tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (item_size as f64 / bin_capacity as f64) * 20.0 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    score = post_residual as f64 * 1.0;

    // Strong reward for perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual,
    // penalize if next item cannot fit (dead space for the next step).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item still fits: mild reward proportional to closeness
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize wasted residual
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative-to-mean-residual coupling: bins with residual far from mean
    // are more valuable to fill down toward the mean.
    let mean = if mean_residual.is_finite() { mean_residual } else { bin_residual as f64 };
    let dev = bin_residual as f64 - mean;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // the item is large relative to capacity (poor fit anywhere) or when
    // many bins are open and spreading load is beneficial.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            // Large item: a fresh bin is fine, even attractive.
            score -= 150.0 * (fill_ratio - 0.7) / 0.3;
        } else {
            // Small/medium item: penalize opening a new bin unless no real alternative.
            score += 120.0 * (1.0 - fill_ratio);
            if fitting_bins_count > 0 {
                score += 150.0;
            }
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 12.0;

    // Penalize dead space: post_residual too small to fit anything useful later.
    let min_useful = 10u32;
    if post_residual < min_useful && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // reward proportional closeness of next item to remaining space
            let closeness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 * closeness;
        } else {
            // next item won't fit here; mild penalty for wasting large residual
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 6.0 * waste;
        }
    }

    // Prefer bins with below-mean residual (consolidate emptiness into few bins).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // When many bins are open, encourage filling existing ones rather than
    // opening more; the empty-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: quadratic waste penalty on post-residual
    let mut score = pr * pr / cap;

    // Smooth progress coupling: later in the stream, tighter packing preferred
    let tightness = (pr / cap).powi(2);
    score += tightness * (1.0 + 3.0 * progress) * 20.0;

    // Reward exact-ish fits smoothly via sine of post residual fraction
    score -= 15.0 * (std::f64::consts::PI * pr / cap).sin().abs();

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (pr - nx).max(0.0) / cap;
        score -= 10.0 * usable * (1.0 - progress);
        if nx > pr {
            score += 8.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly early, more when many open bins have residual
    if bin_residual == bin_capacity {
        score += 12.0 + 5.0 * (mean_residual / cap) * (open_bins_count as f64).ln().max(1.0);
    }

    // Deviation from mean residual: prefer bins with less residual (fill fuller bins)
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo capacity fractions
    let pr = post_residual as u32;
    let class = pr % 10;
    // Penalize awkward residuals (dead space classes), reward "composable" ones
    let class_penalty: [f64; 10] = [0.0, 6.0, 3.0, 1.0, 2.0, 4.0, 2.0, 1.0, 3.0, 5.0];
    score += class_penalty[class as usize];

    // Reward tight fits (small post_residual)
    if pr <= 5 {
        score -= 15.0;
    } else if pr <= 10 {
        score -= 8.0;
    }

    // Perfect-fit harmonic: post_residual divides into capacity quarters
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Next-item lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0 + (pr - next_item_size) as f64 * 0.2;
    } else if next_item_size > 0 && next_item_size > pr {
        // post_residual too small for next item: penalize proportionally to waste
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive only when current fit is bad
    if bin_residual == bin_capacity {
        // Empty bin baseline: prefer it over creating tiny unusable residuals
        score = 25.0 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Early stream: be slightly conservative, prefer compacting into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item are pure waste — penalize heavily.
    if post_residual < 10 && bin_residual != bin_capacity {
        score += 60.0;
    }
    // Small-but-usable gaps are also risky dead space; grade by tightness.
    if post_residual > 0 && post_residual < 25 && bin_residual != bin_capacity {
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (low post_residual) with a super-linear bonus.
    let tightness = (bin_capacity - post_residual.min(bin_capacity)) as f64 / bin_capacity as f64;
    score -= tightness * tightness * 20.0;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead (k=2): if the next item fits exactly into the post_residual,
    // this placement is excellent; if it nearly fits, keep that option alive.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            // next item would be blocked by this dead space
            score += 8.0;
        }
    }

    // New-bin candidate: only attractive early in the stream or when mean
    // residual across open bins is too small to be useful.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 * 3.0) * (1.0 - progress);
        score += 40.0 + open_pressure;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 15.0; // existing bins are nearly full; fresh bin is fine
        }
    }

    // Mild bonus for bins below mean residual (balancing waste across bins).
    if bin_residual != bin_capacity {
        let diff = mean_residual - post_residual as f64;
        score += diff * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear penalty
    score = post_residual as f64 * (1.0 + (post_residual as f64 / bin_capacity as f64).powi(2));

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap); // perfect match => big bonus
        // Exact next-item fit is gold
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize residuals that are slightly above next item (dead space)
        if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 15.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Reward bins tighter than the mean residual (well-filled bins)
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.5;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Early in the stream: allow new bins more readily; late: consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // New empty bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress);
        // If no open bin fits well, opening new bin is fine
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed, non-linearly.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill * fill;

    // Penalize dead space that cannot fit the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // residual remains useful
        } else {
            // dead space penalty grows with how far the residual falls short
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.15 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless all open bins fit badly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 35.0 * (1.0 - progress);
        // If next item is huge and nothing else fits well, new bin is fine.
        if next_item_size >= 80 && post_residual >= 20 {
            score -= 20.0;
        }
    }

    // Prefer placing into bins whose residual is far below the mean
    // (consolidate fragmentation into low-residual bins).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    // Slight preference to fill larger residuals when late in the stream
    // (close out bins rather than leaving many near-empty ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly weighted by stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Polynomial coupling: penalize mid-range residuals (awkward dead space),
    // reward both near-zero residuals (perfect fit) and large residuals (flexibility).
    let q = norm_pr - 0.5;
    score += 30.0 * q * q - 10.0 * q * q * q * q;

    // Tight fit reward, stronger early in the stream.
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (1.0 - progress);

    // Lookahead: reward residual that can still hold the next item (smoothly).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let fits_next = (pr / ni).min(1.0);
        score -= 8.0 * fits_next * fits_next;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild pressure from many open bins: prefer filling existing bins.
    score += 1.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Alignment of residual with mean residual (harmonize bin states).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "dead" classes
    // (large, hard-to-fill gaps) get penalized more than linearly.
    let pr = post_residual;
    if pr > 0 {
        let class = match pr {
            0..=10 => 0.0,        // nearly perfect fit
            11..=30 => 1.0,       // small gap, likely fillable by small items
            31..=50 => 3.0,       // awkward mid gap
            _ => 6.0,             // large dead space
        };
        score += class * (pr as f64).sqrt();
    }

    // Reward tight fits: if next item fits into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // next item cannot chain here; penalize proportionally to how much
        // of the next item is "wasted" relative to this bin.
        let miss = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 0.08 * miss;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer fuller bins: closeness to capacity.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill * fill;

    // Modulo/harmonic threshold on residual: residuals near multiples of
    // common small item sizes (10, 20, 25, 50) are more reusable.
    let reusable = (pr % 10 == 0) || (pr % 25 == 0) || (pr % 50 == 0);
    if reusable && pr > 0 {
        score -= 5.0;
    } else if pr > 0 && pr < 10 {
        // tiny scraps are effectively dead space
        score += 4.0;
    }

    // Early in the stream, keep bins open flexibly (penalize fragmentation);
    // later, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.05 * open_bins_count as f64;
    score -= progress * 3.0 * fill;

    // New-bin candidate: only attractive when open bins have poor fit potential.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).max(0.0);
        // Opening a new bin is good when existing residuals are small/tight
        // and there are already many bins; otherwise discourage.
        score = 30.0 + 40.0 * (1.0 - pressure) - 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable (min item = 1, but
    // practically gaps < 10 are near-dead given typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // heavy penalty for creating a sliver
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward perfect / very tight fits (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // unless the current item is large and leaves a healthy residual.
    if bin_residual == bin_capacity {
        let base = 45.0 + 3.0 * open_bins_count as f64;
        let healthy = if post_residual >= 20 { 35.0 } else { 0.0 };
        score = base - healthy + 0.5 * item_size as f64;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.15 * open_bins_count as f64;

    // Lookahead: if next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else {
            score += 10.0; // dead space for the known next item
        }
    }

    // Prefer filling bins whose residual is already below average (consolidation).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Strong reward for exact match, decaying with distance.
        score -= 30.0 * (-diff / 12.0).exp();
        // Bonus if this bin's residual becomes exactly usable by the next item
        // while few bins can fit the current item (last-chance pressure).
        if diff < 1.0 && fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Penalize post_residual that is slightly below next item size
        // (dead space that cannot serve the lookahead item).
        if pr < nxt && nxt - pr > 0.0 {
            score += 8.0 * (nxt - pr) / bin_capacity as f64;
        }
    }

    // Reward tight fits relative to mean residual of open bins.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score -= 10.0 * (mean_residual - pr) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless current bin is very tight.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Penalize creating large unusable residuals (> half capacity) as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if pr > bin_capacity as f64 * 0.5 {
        score += 10.0 * pr / bin_capacity as f64 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only when open bins would leave bad dead space
    if bin_residual == bin_capacity {
        // Prefer new bin when existing residuals are large but fragmented relative to next item
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 10.0;
        // Penalize opening new bins late in the stream when many bins are open
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += progress * 20.0;
        score += open_bins_count as f64 * 2.0;
        // If next item fits well in the post-residual of a fresh bin, slight bonus
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 5.0;
        }
        let _ = fragmentation;
    }

    // Dead space penalty: post_residual that cannot fit the next item is wasted
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u64) < next_item_size as u64 {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        } else {
            // reward leaving space exactly usable by next item
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 8.0 * (-gap / 20.0).exp();
        }
    }

    // Prefer bins whose residual is close to item (best-fit style) with non-linear sharpening
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness * tightness / bin_capacity as f64;

    // Mild bonus for using bins with large residuals (keep small-residual bins for small items)
    score -= 0.05 * bin_residual as f64;

    // Global state coupling: when mean residual is high, be pickier (penalize loose fits)
    score += 0.1 * mean_residual * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let p = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let res = bin_residual as f64;

    // Base: wasted space after placement, slightly more expensive as stream progresses.
    let mut score = post * (1.0 + 0.35 * p * p);

    // Tightness of the fit (0..1): how much of the bin's current residual the item consumes.
    let tightness = if res > 0.0 { (item / res).clamp(0.0, 1.0) } else { 1.0 };

    // Reward tight fits with a smooth non-linear bonus (quadratic coupling with progress).
    score -= 18.0 * tightness * tightness * (1.0 + 0.5 * p);

    // Penalize leaving a residual that is small but unusable (dead space in (0,10) range)
    // via a smooth bump: sin-like coupling instead of piecewise constants.
    let dead = (post / 10.0 - 0.5).clamp(0.0, 1.0);
    score += 6.0 * (dead * (1.0 - dead) * 4.0) * (1.0 - post / cap.max(1.0));

    // Lookahead: reward if the next item can still use the post residual (pairing bonus),
    // penalize if next item is large and this placement strands it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - (post - nxt) / cap.max(1.0));
        } else {
            score += 5.0 * (nxt - post) / cap.max(1.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): make it mildly attractive so it
    // wins only when existing bins give poor fits; its base post residual is already high.
    if bin_residual == bin_capacity {
        score -= 12.0 + 10.0 * p;
        // Discard new-bin option when many bins are already open and one fits well.
        score += 0.5 * open_bins_count as f64;
    }

    // Mild regularization toward the mean residual state (encourages balanced bin pool).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that form "nice" fractions of capacity
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect closure
    } else if pr % 25 == 0 {
        -25.0
    } else if pr % 10 == 0 {
        -15.0
    } else if pr % 5 == 0 {
        -8.0
    } else if pr < 10 {
        20.0 // tiny dead space penalty
    } else {
        0.0
    };
    score += class_bonus;

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 6.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * (open_bins_count.min(20) as f64);
        // but allow new bin if mean residual is very fragmented
        if mean_residual < cap * 0.15 && open_bins_count > 3 {
            score -= 30.0;
        }
    }

    // Mild phase coupling: early stream, prefer tight packing into few bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (bin_residual - post_residual) as f64 * 0.15;

    // Prefer bins whose residual is close to mean (balance)
    score += 0.08 * ((post_residual as f64 - mean_residual).abs());

    // Integer division threshold: residuals in [1,9] are near-useless
    if pr > 0 && pr / 10 == 0 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let usable = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        if usable == 0.0 {
            // Gap too small for the lookahead item: penalize proportionally to how "dead" it is.
            let deadness = 1.0 - (post_residual as f64 / bin_capacity as f64);
            score += 25.0 * deadness + 15.0;
        } else {
            // Usable gap: mild reward scaled by how much of next item it absorbs.
            let fill = (post_residual as f64) / (next_item_size.max(1) as f64);
            score -= 5.0 * fill.min(1.0);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (small item relative to residual).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage scattering across many bins when a new bin
    // would consolidate; encourage filling existing bins when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins already exist and mean residual
        // is large enough to be useful; slight bonus early when nothing is open.
        score += pressure * 2.0 + (mean_residual / 10.0).min(20.0);
        if open_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Existing bin: reward keeping open_bins_count low.
        score -= pressure * 0.3;
        // If mean residual across bins is low (bins nearly full), prefer packing here.
        if (mean_residual as u32 as f64) < item_size as f64 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if post_residual exactly matches next item, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0; // perfect chain
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills post_residual
            let chain_fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 50.0 * chain_fill;
        } else {
            // next item won't fit: penalize large dead space left behind
            let waste = post_residual as f64;
            score += 0.25 * waste;
        }
    }

    // Penalize leaving residuals that are "awkward" (small but nonzero)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only open a new bin if this bin's fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // new bin baseline: post_residual = C - item; prefer it only when existing fits waste a lot
        score += 15.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // fresh bin can chain with next item
        }
        // late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        score += 2.0 * open_bins_count as f64;
    } else {
        // prefer bins below mean residual (larger holes) for big items
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // mild preference to fill nearly-full bins early
    if post_residual == 0 {
        score -= 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Penalize dead space relative to smallest plausible item (1..100 unknown dist).
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 120.0;

    // Lookahead: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 + next_item_size as f64 * 0.5;
    }
    // If next item would leave the bin nearly empty after, small bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 <= 10 { score -= 30.0; }
    }
    // If next item cannot use this residual, penalize large leftover.
    if next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64).sqrt() * 8.0;
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Many open bins: prefer filling existing ones over opening new.
    let crowding = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by open bins.
        score += 25.0 + crowding * 4.0;
        // Early stream: opening bins is cheaper (build diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If mean residual is large, existing bins are roomy: new bin less needed.
        score += mean_residual * 0.3;
    } else {
        // Existing bin: slight preference when its residual is close to mean (balance).
        score += (bin_residual as f64 - mean_residual).abs() * 0.15;
        // Late stream: consolidate aggressively.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear reward for tight fits: cubic suppression of small residuals.
    let tightness = 1.0 - (pr / cap);
    score -= 30.0 * tightness.powi(3);

    // Dead-space penalty: quadratic in post_residual relative to mean residual.
    let dead = (pr - mean_residual).max(0.0);
    score += 0.15 * (dead / cap).powi(2) * cap;

    // Exact fit bonus (post_residual zero).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: penalize leaving a residual that can't fit the next item,
    // but reward residuals that exactly fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            score -= 12.0 * (1.0 - (gap / cap)).powi(2);
        } else {
            score += 8.0 * (1.0 - pr / nxt.min(cap)).powi(2);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits, to avoid new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Stream progress: as stream advances, prefer consolidating into existing bins
    // (penalize new-bin candidate more over time via smooth coupling).
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (10.0 + 40.0 * progress) * (1.0 + (open_bins_count as f64 / (open_bins_count as f64 + 5.0)));

    // Slight penalty for creating very small residuals (<~10) that become dead space.
    let small_threshold = cap * 0.1;
    if pr > 0.0 && pr < small_threshold {
        score += 6.0 * (1.0 - pr / small_threshold);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals divisible by small sizes (harmonic with common item sizes) are valuable.
    let pr = post_residual as i64;
    let mut harmony = 0.0f64;
    for d in [5u32, 10, 20, 25, 50] {
        if pr > 0 && pr % d as i64 == 0 {
            harmony += 3.0;
        }
    }
    score -= harmony;

    // Dead-space penalty: tiny unusable leftovers (below smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fill fraction via capacity quarters
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let quarter = (fill * 4.0).floor(); // 0..4
    score -= quarter * 4.0;

    // Lookahead coupling: if next item fits in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + (next_item_size as f64) * 0.3;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        score += 8.0; // this bin would block next item
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is nearly full
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.15 - (post_residual as f64) * 0.1;
    }

    // Late in stream: prefer consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 3 {
        score += (open_bins_count as f64 - 3.0) * 0.5 * progress;
    }

    // Prefer bins with residual close to item (snug fit) via integer division threshold
    let slack_ratio = post_residual as f64 / (bin_capacity as f64);
    if post_residual as f64 / 25.0 < 1.0 && post_residual > 0 {
        score -= 10.0; // post_residual < 25: small but plausibly fillable
    } else if slack_ratio > 0.75 {
        score += 5.0; // leaving more than 3/4 empty is wasteful
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 15 {
        score += 25.0;
    } else if post_residual <= 25 {
        score += 10.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward this placement (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial credit when next item still fits after this placement.
        score -= 10.0;
    } else if next_item_size > post_residual {
        // Next item won't fit here afterwards; mild penalty.
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading out; reward placements into crowded bin sets.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 2.0 * (0.5 + progress);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean-residual coupling: bins far below mean residual are "underused";
    // prefer placing into bins whose residual is close to or below the mean.
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.3;

    // New-bin candidate handling: a fresh empty bin should only win when the
    // item fits poorly everywhere else. Give it a moderate baseline score so
    // that only genuinely bad fits in open bins lose to it.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 1.5;
        // Late in the stream, opening new bins is less useful.
        score += 30.0 * progress;
        // If next item is large and would need a big residual, opening a
        // fresh bin preserves flexibility.
        if next_item_size > 60 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Aggressive 2-step lookahead matching ----
    if next_item_size > 0 {
        // Perfect match: post_residual exactly equals next item size -> huge reward.
        let exact_match = (post_residual as i64 - next_item_size as i64).abs();
        score -= 60.0 * (1.0 - exact_match as f64 / 100.0).max(0.0);

        // Next item fits exactly into post_residual after this placement.
        if post_residual >= next_item_size {
            let two_step_residual = post_residual - next_item_size;
            // Reward tight two-step packing (small leftover after both items).
            score -= 25.0 * (1.0 - two_step_residual as f64 / bin_capacity as f64);
            // Extra reward if the two-step leftover is near zero.
            if two_step_residual <= 5 {
                score -= 20.0;
            }
        } else {
            // Next item cannot follow in this bin: penalize proportionally to the miss.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.35 * miss.min(60.0);
        }

        // Coupling with mean residual: bins whose post_residual deviates badly
        // from the fleet mean create fragmented space.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    } else {
        // Last item: just prefer the tightest fit, no lookahead concerns.
        score -= 10.0;
    }

    // ---- Tight fit reward relative to capacity ----
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio; // reward placing item into a nearly-full bin
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if post_residual < 10 {
        score -= 15.0; // near-closure: tiny dead space
    }

    // ---- Dead-space penalty for unusable gaps ----
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // Gap too small for the known next item and likely too small for future ones.
        score += 0.5 * (post_residual as f64).min(40.0);
    }

    // ---- Last-chance bin pressure ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // This is the only open bin that fits: strongly prefer using it
        // over opening a new bin, especially early/mid stream.
        score -= 35.0 * (1.0 - 0.5 * progress);
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large and
        // nothing fits well elsewhere; otherwise make it unattractive.
        let big_item = item_size as f64 / bin_capacity as f64;
        score = 90.0 + 40.0 * (1.0 - big_item);
        if fitting_bins_count == 0 {
            // No open bin fits: new bin is mandatory.
            score = 0.0;
        } else if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Pairing with next item in a fresh bin is a strong strategy.
            score -= 45.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 20.0 * progress;
    }

    // ---- Fleet-size pressure: many open bins -> discourage spreading ----
    score += 1.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize blocking the next item when it could fit better elsewhere
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 0.10 * (next_item_size - post_residual) as f64;
        } else {
            // next item fits exactly in this bin's leftover -> reward
            let leftover_use = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 * leftover_use;
        }
    }

    // Prefer filling bins with large residual when many bins are open
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be conservative (favor new bins less);
    // late in the stream, squeeze everything into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin candidate: penalize more as stream progresses
        score += 5.0 + 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty for opening bins when many are already open
    if bin_residual == bin_capacity {
        score += 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr;

    // Smooth polynomial coupling: reward low post_residual increasingly at later stages
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) * cap * 0.5;
    score += poly;

    // Cubic term: heavily penalize mid-range dead space as stream progresses
    score += norm_pr * norm_pr * norm_pr * cap * (0.5 + 2.0 * progress);

    // Perfect fit bonus (smooth via tightness)
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness * (1.0 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        if next_item_size as f64 > pr {
            score += 6.0 + 10.0 * progress * (next_item_size as f64 - pr) / cap;
        } else {
            // reward leaving space exactly usable by next item
            let gap = pr - next_item_size as f64;
            score -= 4.0 * (1.0 - gap / cap).max(0.0);
        }
    }

    // Mean residual context: prefer bins below mean residual (tighter bins)
    score += (mean_residual - pr) * 0.3;

    // Many open bins: encourage consolidation
    score += open_bins_count as f64 * norm_pr * 0.5;

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score += 20.0 * (1.0 - fill_ratio) * (1.0 + 2.0 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and tiny residuals are golden
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Modulo classes: residuals divisible by common item sizes (10, 20, 25, 50) are reusable
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 60.0; }
        if pr % 25 == 0 { score -= 40.0; }
        if pr % 20 == 0 { score -= 25.0; }
        if pr >= 50 { score -= 30.0; }
    }

    // Penalize awkward mid-range dead space (harmonic "bad" bands)
    if pr > 5 && pr < 10 { score += 80.0; }
    if pr > 30 && pr < 40 { score += 25.0; }

    // Lookahead harmony: residual that exactly fits next item is excellent
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot fit here: dead-end risk
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let tightness = if next_item_size > 0 && next_item_size <= bin_capacity {
            (bin_capacity - next_item_size) as f64
        } else { 0.0 };
        score += 120.0 - tightness * 0.3;
        if fitting_bins_count > 0 { score += 100.0; }
    }

    // Prefer filling bins with large residual (waste reduction) as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual as f64 / bin_capacity as f64) * 20.0 * (0.5 + progress);
    score -= mean_residual * 0.1;

    // Slight preference for bins with residuals in harmonic multiples of 5
    if bin_residual % 5 == 0 { score -= 5.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure loss.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that the lookahead item can still use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // gap blocks the next item
        }
        // If this bin cannot take the next item but another placement could, mild penalty
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 + 0.5 * progress);

    // Prefer bins with residuals close to the mean (keeps bin states uniform).
    score -= (mean_residual - post_residual as f64).abs() * 0.2;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / 20.0).min(1.0);
        score += 15.0 + 25.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if post_residual as f64 > mean_residual && mean_residual > 0.0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nx = next_item_size as f64;
    let mut score = pr;

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Next item fits with modest slack left (good chain)
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = pr - nx;
        // reward closeness of next item to post_residual
        score -= 25.0 * (1.0 - slack / cap.max(1.0));
        // penalize leaving large unusable slack
        score += 0.15 * slack;
    }
    // Next item does NOT fit: post_residual becomes dead space unless tiny
    else if next_item_size > 0 {
        score += 10.0 + 0.25 * pr;
    }

    // Penalize very tight leftovers (< 10, likely dead space since items >= 1 but small fragments waste)
    if post_residual < 10 {
        score -= 8.0; // nearly perfect fill is great
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Deviation from mean residual: prefer bins with residual close to mean (balance)
    score += 0.10 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize so it's only chosen when no open bin is attractive
    if bin_residual == bin_capacity {
        score += 45.0;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual), with non-linear emphasis.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize large dead space that no future item (min size 1..) can use.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.4) * 0.15;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Lookahead: reward if next item fits in post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving space that the next item just barely misses.
            let miss = (next_item_size - post_residual) as f64;
            if miss < 10.0 {
                score += 3.0 * (10.0 - miss) / 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate logic: only attractive when current open bins are crowded
    // or this is a fresh stream with few bins.
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 {
            mean_residual / (bin_capacity as f64)
        } else {
            0.0
        };
        let t = step_index as f64 / (total_items.max(1) as f64);
        // New bin attractive when mean residual is low (bins full) or early stream.
        score = 45.0 - 40.0 * crowding - 10.0 * (1.0 - t);
        // If no bin fits at all, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for wasting a nearly-empty bin when many bins are open.
    if bin_residual >= 90 && open_bins_count > 3 {
        score += 5.0;
    }

    // Prefer bins whose residual is close to item size (best-fit flavor).
    let gap = (bin_residual - item_size) as f64;
    score += 0.3 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual in [0,1)

    // Non-linear polynomial coupling of post-residual with stream progress
    let mut score = pr as f64;
    score -= 30.0 * x * (1.0 - x) * (1.0 + progress);
    score += 20.0 * x * x * (1.0 - progress);
    score -= 15.0 * x * x * x * progress;

    // Penalize dead space relative to mean residual of open bins
    score += 0.5 * (pr as f64 - mean_residual).abs();

    // Reward tight fits (small post residual)
    score -= 25.0 * (-x * 10.0).exp();

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / cap);
        } else {
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // New-bin candidate: prefer opening new bins early, penalize late
    if bin_residual == bin_capacity {
        score += 60.0 * progress - 20.0 * (1.0 - progress);
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: class 0 (perfect fit) strongly favored.
    let class = post_residual % 10;
    score -= match class {
        0 => 60.0,
        1 => 45.0,
        2 => 30.0,
        3 => 20.0,
        4 => 12.0,
        5 => 8.0,
        _ => 0.0,
    };

    // Dead-space penalty: tiny leftovers that nothing (min size 1..10) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Integer-division thresholds: reward leaving space divisible into likely chunks.
    if post_residual >= 20 && post_residual % 20 == 0 {
        score -= 15.0;
    }
    if post_residual >= 50 && post_residual % 25 == 0 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        if post_residual - next_item_size <= 5 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; mildly penalize wasting this bin's space.
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave bad residue.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if all open bins would leave tiny residues, opening fresh is fine.
        if fitting_bins_count >= 1 {
            let best_alt = (bin_residual - item_size) % 10;
            if best_alt >= 6 && best_alt <= 9 {
                score -= 55.0;
            }
        }
    }

    // Late in stream: consolidate harder, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Prefer filling bins below mean residual (i.e., tighter bins).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f).min(20.0) * 0.5;
    }

    // Fraction-of-capacity harmonics: reward filling past half capacity.
    let fill = item_size as f64 / bin_capacity as f64;
    if fill > 0.5 {
        score -= 10.0 * (fill - 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 6.0;

    // Open-bin pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., close bins) when mean residual is high.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 5.0;
    }
    // Penalize if next item almost fits but not quite (wasted potential).
    if next_item_size > post_residual && next_item_size - post_residual <= 10 && next_item_size > 0 {
        score += 4.0;
    }

    // New-bin candidate: empty bin gets a moderate default score; only chosen
    // when no open bin offers a good fit (its raw post_residual = capacity is
    // already large, so it naturally loses unless penalties push others up).
    if bin_residual == bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // exact chaining fit
        } else if post_residual >= next_item_size {
            // reward closeness of next fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Relative-to-mean residual shaping: prefer bins tighter than average
    let dev = mean_residual - post_residual as f64;
    score -= 0.3 * dev;

    // Penalize large dead space that nothing (10..80 range) can use
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // existing fits are poor (post_residual too small for next item)
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 300.0; // an existing bin chains well; don't open new
        } else {
            score -= 50.0; // poor fits elsewhere -> new bin is fine
        }
    }

    // Late-stream consolidation: prefer reusing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress;

    // Mild penalty for spreading across many open bins
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item (min size 1..~20) can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // nearly unusable sliver
    }

    // Lookahead: strongly reward bins whose post residual fits the next item well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here; mild penalty scaled by how far off it is.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap.min(50.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Progress-based horizon: early in the stream, be frugal with open bins;
    // late in the stream, packing density matters more than bin count.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening bins early/often, reward late
        // only when open bins are very full on average.
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score += 20.0 - 25.0 * progress - 10.0 * avg_fullness;
        if open_bins_count > 0 && fitting_bins_count == 0 {
            score -= 30.0; // nothing fits, must open new bin
        }
    } else {
        // Existing bin: prefer bins whose residual deviates favorably from mean.
        let dev = bin_residual as f64 - mean_residual;
        score -= 0.03 * dev;
        // Slight preference for consolidating into fewer bins when many are open.
        score += 0.02 * open_bins_count as f64 * (1.0 - progress);
    }

    // Coupling: large items prefer very full bins to avoid fragmentation.
    if item_size > 60 {
        score -= 0.1 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // Normalized post residual
    let x = pr / cap;
    // Smooth polynomial coupling: reward small post_residual, more strongly as stream progresses
    let base = pr;
    let coupling = 40.0 * x * x * (1.0 + 2.0 * progress); // quadratic dead-space penalty grows over stream
    // Reward tight fits (small post residual) super-linearly
    let tight = -60.0 * (1.0 - x) * (1.0 - x) * (0.5 + progress);
    // Last-chance bonus: strongly prefer using the only fitting bin
    let last_chance = if fitting_bins_count <= 1 { -25.0 } else { 0.0 };
    // Lookahead: if next item fits into post_residual, reward this placement
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -15.0 * (1.0 - (next_item_size as f64) / cap)
    } else if next_item_size > 0 {
        10.0 * (next_item_size as f64) / cap
    } else {
        0.0
    };
    // Slight preference to keep mean residual balanced
    let balance = 0.3 * (pr - mean_residual);
    base + coupling + tight + last_chance + lookahead + balance
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fill is perfect, small dead space is bad.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic buckets: residual in 1..=100; low-value residual classes penalized
    let cls = post_residual / 10; // 0..10 harmonic class
    score += cls as f64 * 3.0;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves residue; reward proportional to leftover smallness
            let nxt_res = post_residual - next_item_size;
            if nxt_res <= 10 {
                score -= 120.0 - (nxt_res as f64) * 8.0;
            } else {
                score -= 20.0;
            }
        } else {
            // next item won't fit here: penalize leaving large residual
            if post_residual > 40 {
                score += 15.0;
            }
        }
    }

    // Empty new-bin candidate: prefer it only when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fits win
        score += 40.0;
        if post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
            score -= 30.0; // current bin can't chain, new bin more attractive
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, prefer closing out with new bins less
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    } else {
        // prefer bins tighter than mean residual (good fit)
        let mr = mean_residual;
        if (bin_residual as f64) < mr {
            score -= 10.0;
        } else {
            score += 5.0;
        }
        // many open bins: encourage filling existing ones
        score -= (open_bins_count as f64).ln() * 4.0;
    }

    // modulo tie-breakers on residual harmony
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0; // class-aligned residual likely reusable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are pure waste; residuals that cannot fit the next item are risky.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 45.0; // tiny unusable gap -> heavy penalty
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 18.0; // gap too small for lookahead item
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0; // gap exactly fits next item
    } else {
        // reward good utilization of the remaining space
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Tight fit reward relative to bin residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins and
    // prefer filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins open or late in stream
        score += 10.0 + 3.0 * open_bins_count as f64 + 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 25.0; // an open bin fits; opening new bin is wasteful
        }
    } else {
        score -= 2.0 * open_bins_count.min(10) as f64;
    }

    // Prefer bins with residuals close to item size (low fragmentation)
    let frag = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * frag;

    // Mild alignment with mean residual: keep residuals balanced
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
