    }

    // Penalize large leftover residual relative to mean residual across bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Discourage opening a new bin when a decent fit exists
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in the stream: prefer tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: penalize small post-residuals more aggressively.
    if post_residual <= 10 {
        score -= 8.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    } else if post_residual <= 40 {
        score -= 1.0;
    }

    // Dead-space penalty: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 3.0;
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 0.02 * (next_item_size as f64 - post_residual as f64).min(60.0);
        }
    }

    // Last chance: this is the only bin that fits; strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score -= 10.0; // nearly perfect fill, take it regardless
        }
    }

    // New-bin candidate handling: make empty bins less attractive when
    // any reasonable fit exists, but attractive when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 12.0;
        // More attractive early (few bins open) and when stream is long.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - progress);
        // Attractive if this bin is the only fitting one (avoid fragmentation).
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Discourage opening bins when many are already open with slack.
        score += 0.3 * open_bins_count as f64;
        // If mean residual across open bins is large, prefer reusing them.
        score += 0.15 * mean_residual;
    }

    // Prefer bins with residual close to item size (best-fit coupling).
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * tightness;

    // Mild time-horizon coupling: late in stream, favor filling bins fully.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / cap);

    // Diversification: if many bins fit, prefer the fullest one implicitly
    // via post_residual; add small noise-free tie-break via open_bins_count.
    score -= 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress.
    // Early on, prefer tight packing (penalize large residuals more); later,
    // residual waste is less recoverable so penalize it progressively more.
    let pr_norm = pr / cap;
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += 12.0 * progress_weight * pr_norm * pr_norm;

    // Reward near-perfect fits via smooth polynomial bump: (1 - pr/cap)^k
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward; if it almost fits but not quite, penalize dead space creation.
    if next_item_size > 0 {
        let gap = pr - next_ratio * cap;
        let gap_norm = gap / cap;
        if gap >= 0.0 {
            score -= 4.0 * (1.0 - gap_norm * gap_norm);
        } else {
            let miss = -gap_norm;
            score += 6.0 * miss * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 8.0 * progress;
    }

    // Scarcity coupling: many open bins -> favor consolidating into residual-rich
    // bins; reward placing into bins below mean residual (larger than average).
    let mean_norm = mean_residual / cap;
    let bin_norm = bin_residual as f64 / cap;
    let scarcity = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * scarcity * (pr_norm - mean_norm).abs() * (1.0 - progress);

    // New-bin candidate: penalize mildly, more so early when bins are sparse,
    // unless it enables a perfect future pairing.
    if bin_residual == bin_capacity {
        let mut penalty = 6.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && (cap - item_size as f64 - next_item_size as f64).abs() < 1.0 {
            penalty -= 14.0;
        }
        score += penalty;
    }

    // Smooth fill-entropy term: reward bins whose residual after placement
    // is close to a "harmonic" usable size (multiples pattern) via sin coupling.
    score -= 2.0 * (std::f64::consts::PI * pr_norm).abs().sin() * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity quarters
    let q = cap / 4.0;
    let post = post_residual as f64;
    let class = (post % q) / q; // 0..1 within quarter

    // Penalize residuals that are dead space (too small for the smallest plausible item)
    if post < 10.0 {
        score += 12.0 * (1.0 - post / 10.0);
    }

    // Reward exact harmonic fits: post_residual divisible into clean classes
    if post_residual % 10 == 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 {
        score -= 2.5;
    }

    // Lookahead: if next item fits perfectly into post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack % 10 == 0 || slack == 0.0 {
            score -= 8.0;
        } else {
            score -= 3.0 * (1.0 - slack / cap);
        }
    } else if next_item_size > post_residual {
        // next item cannot fit here; penalize proportionally to wasted class space
        score += 2.0 + class * 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we prefer
    // reusing open bins unless the fit is poor
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 5.0;
        // late in stream, allow new bins more readily if open bins are fragmented
        if mean_residual < 20.0 && open_bins_count > 2 {
            score -= 6.0;
        }
    }

    // Mild preference for filling bins tighter than the mean residual
    score -= (mean_residual - post).clamp(-cap, cap) * 0.05;

    // Progression: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * (0.1 + 0.15 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual tightly matches the item (small slack ratio).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio;

    // Penalize leaving a gap that just barely misses the next item's size:
    // the lookahead item could have used this bin otherwise.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward leaving a gap that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing bins; few open bins -> new bins are cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // A new empty bin should only win when the fit here is terrible:
    // make the fresh-bin candidate (post_residual == capacity - item) look
    // mediocre unless this bin's post-residual is unusably small.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.2;
    }

    // Mean-residual coupling: bins far below the mean residual are the
    // "emptiest" -> deprioritize them slightly to keep filling tight bins.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits snugly into the residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 40.0 - 3.0 * slack;
        } else {
            score -= (20.0 / slack).min(15.0);
        }
    }

    // Penalize dead space: residuals too small for the minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Penalize leaving residual that neither fits next item nor is usable
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 8.0;
    }

    // Compare against mean residual across open bins: prefer bins that
    // keep the fleet balanced (post_residual near mean_residual)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 35.0;
        // If next item is large and post_residual tiny, allow new bin more readily
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
    }

    // Slight preference for tighter fits as stream progresses
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (post_residual as f64 / bin_capacity as f64) * 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward residuals that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Perfect closure bonus: bin exactly filled.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win.
        score += 45.0;
        // If no existing bin fits well (large post_residual everywhere), open a new bin.
        let poor_fit_elsewhere = post_residual as f64 > mean_residual.max(0.0);
        // For a new bin post_residual == capacity - item_size; large means small item,
        // suggesting the item is small and existing bins may be fragmented.
        if post_residual as f64 >= 0.5 * bin_capacity as f64 {
            score -= 55.0;
        }
        if poor_fit_elsewhere {
            score -= 20.0;
        }
        // Late in the stream, prefer closing out existing bins over opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // Many open bins: discourage opening yet another.
        score += 3.0 * open_bins_count as f64;
    } else {
        // Prefer bins with residuals close to the mean (keep residuals balanced),
        // but only mildly, so tight fits still dominate.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
        // Slight preference for fewer open bins (consolidation).
        score -= 0.5 * open_bins_count as f64;
        // Early stream: be a bit greedy on tight fits; late stream: avoid stranding space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress) * tight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-like
    score += 8.0 * poly * norm_pr * (1.0 - norm_pr) * 4.0;

    // Penalize large dead space more as stream progresses (less time to fill it)
    score += 10.0 * t * norm_pr * norm_pr;

    // Reward tight fits: small post_residual gets discount
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 + 6.0 * (1.0 - (next_item_size as f64 / pr).min(1.0));
    } else if next_item_size > 0 {
        score += 3.0 * t;
    }

    // Mean residual coupling: prefer bins deviating from mean to consolidate
    score += 0.5 * (pr - mean_residual).abs() * (1.0 - t);

    // Many open bins: prefer filling existing over opening new
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        score += 5.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "usable" classes.
    // Residuals divisible by 10 are ideal (future items of size 10/20/... can tile them).
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.6;

    // Integer-division thresholds: large quotients mean big usable blocks.
    let block = post_residual / 20; // 0..5 blocks of 20
    score -= block as f64 * 2.5;

    // Exact-fit reward: post_residual zero is perfect.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Next-item lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Harmonic compatibility: next item's residue matches post residue class
            let compat = ((next_item_size % 10) == (post_residual % 10)) as f64;
            score -= 8.0 * compat + 3.0;
        } else {
            // Next item cannot use this bin: penalize dead space proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.15;
        }
    }

    // Capacity fraction coupling: small relative post-residual is fine, big is waste.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 10.0;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: empty bin gets neutral baseline, slightly high so we
    // prefer filling existing bins unless fit is terrible.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.85 - block as f64;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0; // large next item: fresh bin useful
        }
    }

    // Stream progression: late in stream, consolidate harder into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0 * (bin_residual == bin_capacity) as i32 as f64;

    // Mean residual context: if this bin is far below mean residual, it's a good donor.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: small unusable gaps (below min item size 1 is trivial,
    // but gaps too small to be useful relative to typical items are penalized hard).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Moderately small gaps: mild penalty scaled by how far below the next item they fall.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 + 0.3 * (next_item_size - post_residual) as f64;
    }
    // Reward when residual exactly accommodates the next item (chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this bin would leave a bad gap.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score = 150.0 + pressure * 20.0;
        if fitting_bins_count == 0 {
            score = -500.0; // no open bin fits: must open
        }
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 30.0; // new bin can host a pair
        }
        return score;
    }

    // Open-bin pressure: penalize spreading across many bins mildly.
    score += 0.15 * open_bins_count as f64;

    // Tightness reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Prefer bins whose residual was already small (consolidation).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Late-stream conservatism: as stream progresses, favor filling existing bins harder.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is good (already base score),
    // give extra reward for exact/near-exact fills.
    if post_residual == 0 {
        score -= 1000.0; // perfect close
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: strongly reward when next item exactly
    // consumes the post_residual, or fits tightly into it.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 500.0; // next item perfectly fills leftover
        } else if (post_residual as i64) >= (next_item_size as i64) {
            // next item fits in leftover: reward tightness of that match
            score -= 120.0 - diff as f64 * 1.5;
        } else {
            // leftover too small for next item: penalize proportionally
            score += diff as f64 * 0.8;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // "wasted" bins; placing here to consolidate is good, so reward
    // choosing a bin whose residual is close to item_size (tight fit
    // relative to average state).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 40 {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual by
    // construction; make it attractive only when no open bin offers a
    // decent fit (its raw score is naturally high, add mild damping so
    // good fits in open bins still win).
    if bin_residual == bin_capacity {
        score -= 30.0;
        // early in stream, opening bins is cheap and useful
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 40.0;
    }

    // Mild penalty for spreading across many open bins when mean residual
    // is already low (fragmentation control).
    if open_bins_count > 3 && mean_residual < 25.0 && post_residual > 30 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: perfect or near-perfect fill is highly desirable.
    let tight = (post_residual as f64) / cap;
    score -= 30.0 * (-tight * 12.0).exp(); // strong bonus when post_residual ~ 0
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize creating small dead space that nothing can use later
    // (dead space threshold: residual < 10, the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack = (post_residual as f64 - nxt) / cap;
            score -= 18.0 * (-slack * 10.0).exp();
        } else {
            // Next item won't fit here; slight penalty for wasting good residual now.
            score += 6.0 * (1.0 - (post_residual as f64) / cap);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and open bins are already crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) * (mean_residual / cap);
        let item_big = item_size as f64 / cap;
        score += 35.0
            - 20.0 * item_big
            - 8.0 * crowded
            - 10.0 * progress;
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor).
        let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
        score += 10.0 * fit_gap;
        // Prefer bins with below-mean residual (use up crowded space first).
        score += 4.0 * ((bin_residual as f64 - mean_residual) / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post-residual with stream progress:
    // early on tolerate larger residuals; later, penalize waste more sharply.
    let waste_weight = 0.5 + 1.5 * progress * progress;
    score += waste_weight * (pr / cap) * (pr / cap) * 20.0;

    // Reward tight fits: smooth exponential of normalized fill.
    let fill = 1.0 - pr / cap;
    score -= 15.0 * fill * fill * (1.0 + progress);

    // Exact-fit bonus (smooth, non-piecewise): strong reward near pr == 0.
    score -= 30.0 * (-pr / 8.0).exp();

    // Lookahead coupling: if next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 12.0 * (-gap / 15.0).exp() * (0.5 + 0.5 * progress);
        } else {
            score += 6.0 * ((-gap) / 25.0).exp();
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - progress * 0.3);
    }

    // New-bin candidate: penalize mildly so open bins with decent fit win,
    // but allow it when the item is large relative to capacity or stream is early.
    if bin_residual == bin_capacity {
        let size_ratio = it / cap;
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 18.0 - 14.0 * size_ratio - 2.0 * openness - 6.0 * (1.0 - progress);
        // If no open bin fits well, mean_residual signals fragmentation; ease new-bin penalty.
        score -= (mean_residual / cap).max(0.0) * 5.0;
    }

    // Mild penalty for leaving residuals near awkward mid-range values (smooth bump).
    let mid = (pr / cap - 0.5).abs();
    score += 4.0 * (-(mid * mid) / 0.02).exp() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class logic on post_residual: classify residual into
    // capacity-fraction buckets. Residuals that fall into "usable" harmonic
    // classes (multiples of common item sizes / capacity fractions) are good.
    let frac_quarter = bin_capacity / 4;
    let frac_eighth = bin_capacity / 8;
    let mut harmonic_bonus = 0.0;

    // post_residual divisible by 10 (common item granularity) => reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        harmonic_bonus -= 12.0;
    }
    // post_residual matches quarter/eighth capacity fractions => reusable
    if post_residual == frac_quarter || post_residual == 2 * frac_quarter || post_residual == 3 * frac_quarter {
        harmonic_bonus -= 10.0;
    }
    if post_residual == frac_eighth || post_residual == 3 * frac_eighth || post_residual == 5 * frac_eighth || post_residual == 7 * frac_eighth {
        harmonic_bonus -= 6.0;
    }
    // Integer division thresholds: tiny dead space is penalized per class
    let dead_class = post_residual / frac_eighth; // 0..=7
    score += dead_class as f64 * 1.5;

    // Lookahead: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            harmonic_bonus -= 40.0; // chain a perfect fit
        } else if next_item_size <= post_residual {
            harmonic_bonus -= 8.0;
            // modulo coupling: next item divides the post residual nicely
            if post_residual % next_item_size.max(1) == 0 {
                harmonic_bonus -= 10.0;
            }
        } else {
            // next item cannot use this residual; penalize small residuals less
            harmonic_bonus += (post_residual as f64) * 0.05;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        harmonic_bonus -= 25.0;
        if post_residual < frac_eighth {
            harmonic_bonus -= 15.0; // near-perfect fill on last chance
        }
    }

    // New-bin candidate: opening a new bin should only win when current bins
    // are nearly full or the fit is bad. Penalize the empty-bin candidate
    // moderately, scaled by how full the average open bin is.
    if bin_residual == bin_capacity {
        let fullness = 1.0 - mean_residual / bin_capacity as f64;
        harmonic_bonus += 18.0 + fullness * 10.0;
        // early in stream, new bins are cheaper to open
        let progress = step_index as f64 / total_items.max(1) as f64;
        harmonic_bonus -= progress * 8.0;
        // if item is large and nothing fits well elsewhere, new bin ok
        if item_size > 3 * frac_quarter {
            harmonic_bonus -= 10.0;
        }
    }

    // Spread-awareness: prefer bins below mean residual slightly (balance)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Modulo class on item_size: items in awkward classes (prime-ish sizes)
    // favor tighter bins
    if item_size % 10 != 0 {
        score += 2.0;
    }

    score += harmonic_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for even the smallest
    // item (size 1) are already usable, but residuals below a practical
    // threshold are likely to become dead space. Penalize them hard.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Lookahead (k=2): if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves further residual: mild reward scaled by fit quality.
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // This bin cannot serve the next item; penalize slightly to prefer
        // bins whose remainder remains useful.
        score += 8.0;
    }

    // Open bins pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Deviation from mean residual: prefer bins that are either much fuller
    // or much emptier than average (consolidation effect).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev - 5.0;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no existing bin fits well (large item, all residuals small).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            0.0
        } else {
            // Existing bins can fit: penalize new bin unless they'd waste space.
            let min_waste_pressure = if (bin_capacity - item_size) < dead_threshold { -30.0 } else { 40.0 };
            min_waste_pressure
        };
        score = 40.0 + pressure + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual)
    score = post_residual as f64;

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space penalty scaled by how much next item misses
        let miss = (next_item_size - post_residual) as f64;
        score += 0.5 * miss;
    }

    // Reward matching residual relative to mean residual (keep diversity of residual sizes)
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow new bin if no good fit exists (post residual of others would be tiny)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward if next item nearly fills the bin after this one.
        let nxt_left = post_residual - next_item_size;
        if nxt_left < 10 {
            score -= 12.0;
        }
    }
    // Penalize if next item could have fit current residual but not post-residual (we blocked it).
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 10.0;
    }

    // Penalize leaving large dead space relative to the smallest plausible item (1..100 unknown; use 10 as soft floor).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small slivers are fine (near-full)
    }
    if post_residual >= 10 && post_residual < item_size.min(80) {
        score -= 5.0; // dead space too small for typical items is acceptable
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // moderately awkward gap
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.15 * consolidation;
        // When many bins are open, discourage spreading into low-fill bins.
        if open_bins_count > 4 && post_residual as f64 > mean_residual {
            score += 0.1 * open_bins_count as f64;
        }
    }

    // New-bin candidate handling: only attractive when no good existing option or early stream.
    if bin_residual == bin_capacity {
        let early_bonus = (1.0 - progress) * 15.0;
        score += 30.0 - early_bonus; // base penalty so existing bins usually win
        if fitting_bins_count <= 1 {
            score -= 55.0; // forced/last chance -> opening new bin is fine
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, opening fresh bins for big items can be better.
        if item_size > 60 && progress > 0.6 {
            score -= 10.0;
        }
    }

    // Mild time-horizon scaling: tighten packing as stream progresses.
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap; // 0..1
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let pr2 = pr_norm * pr_norm;
    let pr3 = pr2 * pr_norm;

    // Polynomial interaction: tight fits (small pr) rewarded more as stream progresses
    score -= 14.0 * progress * pr_norm;
    score -= 22.0 * p2 * pr_norm;
    score -= 18.0 * p3 * pr2;
    score += 10.0 * progress * pr3; // penalize large dead space late

    // Reward exact/near-exact fits with smooth falloff
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness * tightness;

    // Last-chance bin bonus (smooth, scaled by progress)
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - progress) + 6.0;
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty proportional to wasted potential
        score += 4.0 * pr_norm * (0.5 + progress);
    }

    // Mean residual coupling: prefer bins whose residual deviates smoothly from mean
    let dev = pr - mean_residual;
    score += 0.08 * dev * dev / cap;

    // Open bins pressure: many open bins -> prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: bucket post_residual into capacity-fraction classes.
    // Residuals that are large enough to hold common item sizes are "usable";
    // small dead space is penalized quadratically.
    let usable_threshold = bin_capacity / 5; // 20
    if post_residual < usable_threshold && post_residual > 0 {
        score += (usable_threshold - post_residual) as f64 * 3.0;
    }

    // Classify residual by integer division into harmonic bands
    let band = post_residual / 10;
    score += match band {
        0 => 40.0,          // dead space 0-9
        1 => 15.0,          // 10-19
        2 => 5.0,           // 20-29
        3 => 0.0,           // 30-39 sweet spot
        4 => -2.0,          // 40-49
        _ => -5.0,          // large residual, flexible
    };

    // Lookahead: reward if next item fits the post-residual (keeps chain alive)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + (next_item_size as f64) * 0.2;
            // extra reward for exact harmonic pairing
            if post_residual - next_item_size < 10 {
                score -= 15.0;
            }
        } else if next_item_size > post_residual && post_residual < 10 {
            // bin will be nearly dead; mild penalty
            score += 10.0;
        }
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive if no good open option exists
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score += 120.0;
        // but if open bins are fragmented (high mean residual spread), new bin ok
        if open_bins_count > 0 && mean_residual < 25.0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0;
        }
    }

    // Prefer filling bins as stream progresses (close out bins early)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.5;

    // Prefer bins with residual close to item (tight fits) among open bins
    score += ((bin_residual - item_size) as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: very small post_residual is excellent packing.
    if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score -= 6.0;
    }

    // Dead-space avoidance: if the leftover gap cannot host the lookahead item,
    // it risks becoming unusable dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize the brand-new empty bin candidate when existing bins can fit the item.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 12.0 + 0.25 * open_bins_count as f64;
    }

    // Mild pressure to keep the number of open bins in check.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-chain: this bin becomes exactly full after next item.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to tightness of the pair.
            let pair_tightness = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - pair_tightness / bin_capacity as f64);
        } else {
            // Next item does NOT fit here: penalize large dead space that will strand.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.0;
    }

    // Relative to mean residual: bins below-mean residual are precious; placing here
    // in a tight bin is good (best-fit behavior), bins above mean are looser.
    let dev = mean_residual - post_residual as f64;
    score += 0.25 * dev;

    // Penalize leaving small unusable slivers (dead space 1..=9).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Early in stream: keep bins tight (best-fit), allow more spreading later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only open a new bin if the item fits badly
    // everywhere else (large post_residual waste in existing bins).
    if bin_residual == bin_capacity {
        // Base attractiveness of a fresh bin: moderate.
        score += 45.0;
        // Attractive when open bins are all quite full (mean residual small).
        score -= 1.2 * mean_residual;
        // Attractive when few fitting bins exist (crowded state).
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // Lookahead: opening a new bin reserves space for the next item too.
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the leftover relative to capacity, the better.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 20.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize dead space that no future item (min size 1) can realistically use well:
    // small residuals are fine (near-full), large residuals mean wasted space.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // awkward sliver is acceptable if bin nearly full
    }
    if post_residual >= 50 {
        score += (post_residual as f64 - 50.0) * 0.4; // half-empty bin penalty
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits, but how well?
            let next_left = post_residual - next_item_size;
            score -= 10.0 - (next_left as f64) * 0.15;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.08;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer filling existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score -= open_pressure * 2.0;
        // Late in the stream, consolidation matters more.
        score -= progress * 8.0;
        // If this bin's residual is below the mean residual, it's a good filler target.
        let res_diff = mean_residual - bin_residual as f64;
        score += res_diff * 0.1;
    } else {
        // New-bin candidate: penalize opening a new bin, more so when many bins
        // are open or the item would leave a large residual anyway.
        score += 25.0 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // a fresh bin is useful if the next item is bigger
        }
        score += progress * 10.0; // late-stream: avoid opening new bins
    }

    // Mild preference for bins whose residual is close to item size (best-fit core).
    let slack = (bin_residual - item_size) as f64;
    score += (slack / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, with non-linear (quadratic/cubic) coupling
    let mut score = pr
        + 30.0 * norm_pr * norm_pr * cap
        + 15.0 * norm_pr * norm_pr * norm_pr * cap * progress;

    // Penalize dead space that is too small for typical future items,
    // scaled smoothly by stream progress (late stream: tighter packing matters)
    let dead_zone = (pr / cap).powf(1.5) * cap * (0.5 + 1.5 * progress);
    score += dead_zone;

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 20.0 * (1.0 - slack / cap) * (0.5 + progress);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate handling: prefer opening a new bin when fit is poor
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new {
        // Slight opening cost, decaying with progress; but if this is the only
        // fitting bin among open ones, opening a fresh bin is cheap
        score += 8.0 * (1.0 - progress);
        if fitting_bins_count == 1 && open_bins_count > 0 {
            // existing bin is last chance: make new bin less attractive only
            // if the existing fit is decent (post_residual small)
            score += (pr / cap) * 40.0;
        }
    } else {
        // Last-chance bonus: strongly favor using the only bin that fits
        if fitting_bins_count == 1 {
            score -= 25.0 * (1.0 - norm_pr);
        }
        // Prefer bins tighter than the mean residual (best-fit flavor)
        let dev = (mean_residual - pr) / cap;
        score -= 10.0 * dev.tanh();
    }

    // Mild pressure to consolidate when many bins are open
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via non-linear post_residual penalty.
    let pr = post_residual as f64;
    score += 0.6 * (pr / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Harmonic class: reward residuals that fall into "usable" residue classes
    // (small post_residual, or post_residual that is a clean fraction of capacity).
    let cap = bin_capacity;
    let harmonic_bonus = match post_residual {
        0 => 60.0,                                  // perfect fill
        x if x <= 10 => 35.0,                       // near-perfect
        x if cap as u64 % (x.max(1) as u64) == 0 => 20.0, // exact divisor of capacity
        x if x % 10 == 0 => 10.0,                   // decade class
        x if x % 25 == 0 => 12.0,                   // quarter class
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Lookahead: strongly reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // partial credit scaled by how much slack would remain after next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap as f64);
        } else {
            // next item cannot use this bin's residual: penalize dead space proportionally
            score += 0.25 * (pr - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing bins unless fit is poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // but if current item is large relative to mean residual, new bin is attractive
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 40.0;
        }
    }

    // Stream progression: late in the stream, be more aggressive at filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * harmonic_bonus * 0.1;

    // Coupling with mean residual: bins far below mean residual are less attractive targets
    score += 0.15 * (mean_residual - bin_residual as f64).abs().powi(2) / (cap as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10] is unusable for
    // any future item (min size 1..100 stream, but small slivers rarely help).
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual <= 20 && post_residual > 0 {
        score += 12.0;
    }

    // Reward very tight fits (post_residual near zero but still usable).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than spreading; mild per-bin penalty.
    score += open_bins_count as f64 * 0.6;

    // Lookahead: if the next item fits exactly in the post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use the leftover anyway: dead space less costly.
        score -= (post_residual as f64).min(10.0) * 0.5;
    }

    // Early in the stream, opening bins is cheaper; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 8.0;

    // Prefer bins whose residual deviates favorably from the mean residual
    // (fill down the bins with most space to balance fragmentation).
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: neutral baseline; only chosen if open bins score poorly.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
