pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small post-residuals that can't fit typical items are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Reward tight fits relative to bin size.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fill_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 5.0;
        } else {
            score += 3.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        }
    }

    // Time horizon: early in the stream, be conservative (favor new bins less);
    // late in the stream, pack tighter into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * fill_ratio;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins below average residual to balance load.
    if open_bins_count > 0 {
        let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 2.0 * diff;
    }

    // New-bin candidate: penalize slightly so we only open new bins when existing
    // bins give a poor fit; but allow it early when few bins are open.
    if bin_residual == bin_capacity {
        score += 6.0;
        if open_bins_count < 3 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Non-linear penalty on post residual: dead space grows quadratically
    score += 40.0 * pr_norm * pr_norm * cap;

    // Interaction: post residual coupled with stream progress (late stream -> penalize waste more)
    score += 30.0 * pr_norm * pr_norm * progress * cap;

    // Reward tight fits: subtract when post residual is small relative to capacity
    score -= 25.0 * (1.0 - pr_norm).powi(3);

    // Lookahead coupling: penalize if post residual can't fit next item
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let fits_next = (pr >= nx) as f64;
        score -= 12.0 * fits_next * (1.0 - pr_norm);
        score += 15.0 * (1.0 - fits_next) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins below mean residual (denser bins)
    score += 8.0 * (pr_norm - mean_residual / cap).abs();

    // Mild penalty for many open bins (encourage consolidation)
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // Smooth new-bin candidate handling: empty bin gets a moderate baseline
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress * (1.0 - it / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual divisible by common small sizes is reusable
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 30, 40, 50, 60, 80] {
            if pr % d == 0 && pr / d >= 1 {
                harmony += 8.0;
            }
        }
        // integer division threshold: post_residual in a "useful slot" class
        let slot = pr / 10; // 0..10 harmonic decile
        harmony += (slot as f64) * 0.5;
        score -= harmony;
    } else if pr == 0 {
        // handled above
    }

    // Penalize awkward residuals: 1..9 are near-dead space
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item still fits after this placement
            let slack_after_next = post_residual - next_item_size;
            score -= 30.0 - (slack_after_next as f64) * 0.2;
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: only prefer fresh bin when open bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 150.0;
        // early in stream, opening bins is cheaper; late stream, reuse
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 60.0;
        // if many open bins already, discourage one more
        score += open_bins_count as f64 * 4.0;
        // if next item is large, a fresh bin is more attractive
        if next_item_size > 50 {
            score -= 40.0;
        }
        // perfect-fit style bonus: fresh bin has "harmonic" residual
        score -= 10.0;
    } else {
        // reward filling existing bins deeper when mean residual is high
        score -= (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Mild preference for bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals too small to fit the smallest plausible item (1..100 range, min 1)
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 25.0;
    }

    // Reward tight fits (low post residual relative to item size).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tightness * 20.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual < next_item_size {
        score += 10.0;
    }

    // Mean residual alignment: prefer bins whose residual stays near mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // New-bin candidate: baseline attractiveness, only beaten when fit is poor.
    if bin_residual == bin_capacity && bin_capacity > 0 {
