pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact 2-step match
        if post_residual == next_item_size {
            score -= 500.0;
        } else {
            // Penalize residuals that don't chain well with the next item
            score += gap * 0.5;
        }
        // If next item cannot fit in the post residual, penalize dead space
        if post_residual < next_item_size && post_residual > 0 {
            score += 30.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    let resid = post_residual as f64;
    if mean_residual > 0.0 {
        score += (resid - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 60.0;
        // If next item is large, a fresh bin is more attractive
        if next_item_size >= 60 {
            score -= 40.0;
        }
    }

    // Late in the stream, tighten packing (waste matters more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += resid * (0.05 + 0.15 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful for future items.
    if post_residual > 0 {
        let dead_threshold = 12.0;
        if (post_residual as f64) < dead_threshold {
            score += 8.0 * (dead_threshold - post_residual as f64);
        }
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            score -= 10.0 + 0.5 * nxt;
        } else {
            // Waste potential: leftover can't host the known next item.
            let gap = nxt - post_residual as f64;
            score += 0.35 * gap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // More competing fitting bins => less urgency to use this one.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in the stream, be conservative with open bins;
    // later, consolidate to avoid bin proliferation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress;

    // Bin-count pressure: many open bins -> favor filling existing ones.
    score += 0.8 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins whose residual differs
    // favorably from the fleet average (below-mean residual = tighter bin).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 5.0 * dev;

    // New-bin candidate: only attractive when current item is large relative
    // to capacity or no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 15.0;
        } else if large_item > 0.6 {
            score -= 3.0 * (large_item - 0.6) * 10.0;
        } else {
            score += 10.0 * (0.6 - large_item) * 10.0;
        }
    }

    // Small item into a large-residual bin: mild penalty to preserve big space.
    if (item_size as f64) < 0.3 * (bin_capacity as f64) && (bin_residual as f64) > 0.7 * (bin_capacity as f64) {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 + 3.0 * progress) + pr_norm * progress * 2.0;
    score += 10.0 * poly;

    // Reward tight fits, scaled non-linearly by progress.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 6.0 * tightness * (1.0 + progress);

    // Penalize creating residual close to but below the next item size (dead space),
    // with smooth interaction.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 4.0 * (1.0 - gap / bin_capacity as f64) * (1.0 + progress);
        }
        // Reward leaving room for the next item.
        if gap == 0.0 {
            score -= 8.0 * (1.0 + progress);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and residual is large.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // Deviation from mean residual: smooth quadratic coupling.
    let dev = pr - mean_residual;
    score += 0.3 * dev * dev / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot" of capacity fractions it falls into
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class the residual into harmonic bands (1/2, 1/3, 1/4, ...)
    // Residuals just below a harmonic threshold are highly reusable.
    let harmonic_bonus = if pr == 0 {
        60.0 // perfect fit, strongly favored
    } else if pr <= cap / 4.0 {
        30.0
    } else if pr <= cap / 3.0 {
        18.0
    } else if pr <= cap / 2.0 {
        8.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Modulo classes: residuals that are multiples of common item sizes are more reusable
    let common_mods: [u32; 6] = [10, 20, 25, 50, 5, 100];
    let mut mod_bonus = 0.0;
    for (i, &m) in common_mods.iter().enumerate() {
        if post_residual % m == 0 && post_residual > 0 {
            mod_bonus += 6.0 / (i as f64 + 1.0);
        }
    }
    score -= mod_bonus;

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual: partial reward scaled by fit quality
            let nxt = next_item_size as f64;
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - fill_after / cap);
        } else {
            // next item cannot fit here: penalize slightly, more if residual is in a dead zone
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins moderately unattractive unless
    // the item is large relative to capacity or nothing fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap; // 0..1
        // Base penalty for opening a new bin
        score += 35.0;
        // If item is large, opening a fresh bin is more reasonable
        score -= 40.0 * large_item;
        // If many bins are open with high mean residual, prefer spreading into them
        score += 0.15 * open_bins_count as f64 + 0.3 * mean_residual.max(0.0);
        // If no other bin fits, this call is the only option anyway (fitting_bins_count includes it)
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    // Dead-space penalty: residuals below the minimum item size (1) can't happen,
    // but tiny residuals relative to typical item sizes are wasted.
    // Estimate minimum useful residual as a fraction of mean item size proxy.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let tiny_threshold = 0.05 * cap * (1.0 - 0.5 * progress);
    if pr > 0.0 && pr < tiny_threshold {
        score += 12.0;
    }

    // Tightness reward: prefer bins where the item fills a large share of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Mild preference for keeping mean residual balanced (avoid one huge + many tiny bins)
    let deviation = (mean_residual - pr).abs();
    score += 0.05 * deviation;

    // Early stream: slightly favor consolidating into fewer bins
    if progress < 0.3 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit the smallest
    // plausible item are dead space — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, this placement
    // chains nicely — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; a near-empty leftover is wasted.
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new
    // bins; the empty-bin candidate gets a penalty proportional to load.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 8.0 * open_bins_count as f64 + 15.0 * progress;

        // But if all open bins would leave big dead space, new bin is OK:
        // compare against mean residual — if item fits poorly everywhere,
        // soften the penalty.
        if fitting_bins_count > 0 && (mean_residual - item_size as f64) < 5.0 {
            score -= 18.0;
        }
    } else {
        // Mild pressure to consolidate into fewer bins when open count is high.
        score += 0.4 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the item (best-fit core).
    score += 0.3 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by base term.

    // 2-step lookahead: strongly reward if next item fits the post_residual exactly or nearly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.6 * gap;
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: item + next item fill bin
        } else if post_residual > next_item_size {
            // next item fits but leaves more waste; mild penalty proportional to leftover
            score += 0.25 * (post_residual - next_item_size) as f64;
        } else {
            // next item does NOT fit: this residual becomes dead space until later
            score += 8.0;
        }
    } else {
        // last item: maximize fill
        score -= 20.0;
    }

    // Reward bins that are already well-filled (keep few large-residual bins as anchors).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Compare residual against mean residual: prefer placing into below-average-residual
    // (tighter) bins to consolidate emptiness into fewer bins.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize the brand-new empty bin candidate unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // A new bin is attractive late in the stream when open bins are crowded
        // and next item is large (avoid fragmenting).
        if next_item_size > 0 && next_item_size > post_residual.min(bin_capacity / 2) {
            score -= 10.0;
        }
        if open_bins_count > 0 && mean_residual < item_size as f64 * 0.5 {
            score -= 15.0;
        }
    }

    // Mild progression term: slightly prefer consolidating early, tightening late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tight * tight;

    // Penalize creating dead space that nothing small could use
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // nearly-full bin is a good outcome
    } else if post_residual >= 10 && post_residual < 30 {
        // moderately usable leftover: mild penalty relative to post_residual itself
        score += 3.0;
    } else if post_residual >= 30 {
        score += 7.0; // large waste is bad
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slightly penalize leaving a residual
            // that is just barely too small (classic bad leftover)
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 5.0;
            }
        }
    }

    // New-bin candidate handling: penalize opening a new bin, more so
    // when open bins are underutilized or stream is late
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 12.0 + 18.0 * progress;
        // if mean residual is high, existing bins are roomy -> prefer them
        new_bin_penalty += (mean_residual / 10.0).min(15.0);
        // with many open bins, prefer consolidating into one of them
        new_bin_penalty += (open_bins_count as f64).sqrt() * 2.0;
        // exception: large items late in stream may justify fresh bins
        if item_size >= 70 && progress > 0.5 {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference for fuller bins (small bin_residual) among open bins
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early stream: tolerate larger residuals; late stream: pack tight
    let coupling = 1.0 - 0.9 * progress * (3.0 - 2.0 * progress);
    score *= (0.5 + 0.5 * coupling) + 0.5 * norm_pr * (1.0 - coupling);

    // Dead-space penalty: residuals too small for any plausible item (min size 1)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (10 - post_residual) as f64 / 10.0;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (pr - nx) / cap).min(1.0);
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins exist, more so early on
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (0.5 + progress);
        score += 8.0 + pressure;
        // but if mean residual of open bins is small, new bin less bad
        score -= (mean_residual / cap).min(1.0) * 4.0;
    }

    // Mild penalty for bins far from mean residual (balance residual distribution)
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 as dead-space classes
    let r = post_residual % 10;
    let harmonic_penalty = match r {
        0 => -6.0,          // perfectly aligned residual, highly reusable
        1 | 9 => 3.0,
        2 | 8 => 1.5,
        3 | 7 => 0.5,
        4 | 6 => -1.0,
        _ => 0.0,           // 5: half-capacity class, neutral
    };
    score += harmonic_penalty;

    // Integer-division threshold: tiny residuals are dead space
    if post_residual < 10 {
        score += 25.0;      // unusable sliver
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Large residual is valuable; reward keeping big residual bins
    if post_residual >= 50 {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless it yields a
    // harmonically clean post_residual (multiple of 10) or item is huge
    if bin_residual == bin_capacity {
        let base_new = 12.0 + (open_bins_count as f64) * 0.3;
        let clean = if post_residual % 10 == 0 { 10.0 } else { 0.0 };
        let big_item = if item_size >= 70 { 8.0 } else { 0.0 };
        let lookahead_waste = if next_item_size > 0 && next_item_size > post_residual { 6.0 } else { 0.0 };
        score += base_new - clean - big_item + lookahead_waste;
    }

    // Lookahead synergy: if next item fits exactly into post_residual, reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 0.05;
    }

    // Progress-based mild pressure: late in stream, prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 3.0;
    }

    // Deviation from mean residual: prefer bins near the mean to keep balance
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item size
    // are pure waste; penalize them super-linearly.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 25.0;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0;
        } else if gap < 25 {
            score -= 12.0;
        }
    }
    // Penalize leaving a gap the next item cannot use at all.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 20.0;
    }

    // Open-bin pressure: fewer bins is better; discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Mild preference for placing into bins with smaller mean residual (fill fuller bins first),
    // but only when this bin is actually fuller than average.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // Early in the stream, slightly prefer consolidating; late, be more flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 4.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 15.0 + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: post_residual consumed by next item
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 40.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize large dead space
            score += 0.25 * post_residual as f64;
        }
    }

    // Compare post_residual against mean residual: keep residuals homogeneous.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize wasteful near-empty fills when item is small relative to residual.
    if (item_size as f64) < 0.35 * bin_residual as f64 {
        score += 10.0;
    }

    // Late in stream: consolidate, discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress); // early: new bins okay
        score -= 15.0 * progress;         // late: prefer existing bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Exact / near-exact fill gets a big bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Penalize dead space that no plausible future item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are bad
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += 10.0;
        }
        // If next item exactly matches post-residual, strong reward
        if post_residual == next_item_size {
            score -= 45.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer bins with residual close to mean (avoid fragmenting outliers)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // When many bins are open, prefer filling existing ones over opening new
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + progress);
    score += 0.05 * crowding;

    // New-bin candidate handling: empty bin should only win for large items
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score += 15.0 + 60.0 * (1.0 - large);
        // Late in the stream, opening new bins is cheaper than wasting space
        if progress > 0.7 {
            score -= 20.0 * progress;
        }
    }

    // Mild preference for bins whose residual is a multiple-ish of common item sizes
    let r = bin_residual as f64;
    for s in [10.0f64, 20.0, 25.0, 30.0, 40.0, 50.0] {
        if r > s && r - s < 10.0 {
            score += 8.0; // residual just above a common size wastes space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual, with non-linear penalty on mid-range waste
    let mut score = pr;

    // Polynomial coupling with stream progress:
    // late in the stream, tight fits matter more -> weight x^2 and x^3 terms by progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += (1.0 - progress) * (x * x * cap * 0.5) + p3 * (x * x * x * cap * 2.0);

    // Reward near-perfect fits smoothly (small post residual => subtract)
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 30.0 * p2);

    // Lookahead: if next item fits exactly into post residual, strongly favor
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_gap = (pr - nx) / cap;
            score -= (1.0 - fit_gap) * (1.0 - fit_gap) * 25.0 * (1.0 - progress * 0.5);
        } else {
            // next item won't fit here: penalize proportionally to overflow tightness
            score += ((nx - pr) / cap) * 8.0;
        }
    }

    // Last chance: only fitting bin -> strong bonus to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * p2;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Mildly discourage opening new bins early; encourage consolidation late
    score += open_bins_count as f64 * (0.5 + progress);

    // Prefer bins below mean residual (fill emptier bins less) — smooth pull
    score += (mean_residual - pr) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" classes (large enough to likely host future items) are favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction-of-capacity class of the post residual (harmonic bands).
    let frac = post / cap;
    if frac <= 0.05 {
        // Perfect / near-perfect fit: huge reward.
        score -= 60.0;
    } else if frac <= 0.15 {
        score -= 25.0;
    } else if frac <= 0.30 {
        score -= 8.0;
    } else if frac <= 0.50 {
        // Mid-band: mildly penalize leaving half-capacity dead space.
        score += 6.0;
    } else {
        // Large leftover is fine only if item was small; penalize waste.
        score += 12.0 * frac;
    }

    // Modulo-style classes on post_residual (mod 10 granularity).
    let m = post_residual % 10;
    if m == 0 {
        score -= 5.0; // round residuals pair well with decade-sized items
    } else if m <= 3 {
        score += 4.0; // tiny slivers are dead space
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact-ish match with lookahead item is excellent.
            let diff = post_residual - next_item_size;
            if diff == 0 {
                score -= 40.0;
            } else {
                score -= 15.0 * (1.0 - diff as f64 / cap);
            }
        } else {
            // Next item won't fit here; leftover becomes temporary dead space.
            score += 10.0;
            // But if the leftover is small enough to be near-closed, that's ok.
            if post_residual < 10 {
                score -= 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // fit poorly (large post residual) or the item perfectly fills a new bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 30.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If item nearly fills a fresh bin, opening is attractive.
        if post_residual <= 5 {
            score -= 45.0;
        }
        // As the stream progresses, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If many bins are open and mean residual is high, discourage new bins.
        score += 0.5 * (open_bins_count as f64).min(20.0);
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Slight preference for tighter bins overall (best-fit character).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps that no plausible item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits: residual just above item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 8.0 * open_bins_count as f64;
        // Late in the stream, extra pressure to consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If next item could use the leftover of an existing bin, avoid new bin.
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 20.0;
        }
    } else {
        // Reward leaving space usable by the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // Penalize residuals slightly below the next item (near-miss waste).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Mild preference for bins with residuals close to the mean (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item, or can host it after this placement.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 400.0; // chained perfect fit
        } else if post_residual >= next_item_size {
            // next item fits here afterwards: mild reward, stronger when snug.
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 - slack.min(120.0);
        } else {
            // dead space below next item size: penalize proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.5;
        }
    }

    // Reward tight fits relative to the residual before placement.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 50.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer bins with residuals below the mean (consolidate emptier space usage),
    // i.e. penalize picking bins that are unusually full relative to fleet.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.3;

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or few bins fit it.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        // Score for a fresh bin: base cost reduced when item is big or options scarce.
        score = 200.0 - large * 150.0 - pressure * 100.0 + (post_residual as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0; // fresh bin also serves lookahead well
        }
        // Late in the stream, avoid spawning bins with tiny leftovers.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 22.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small but nonzero post-residual).
    if post_residual > 0 {
        let pr = post_residual as f64;
        let awkward = if pr < 10.0 { (10.0 - pr) * 1.8 } else { 0.0 };
        score += awkward;
    }

    // Lookahead: reward if the next item fits in the post residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Penalize blocking a large next item only slightly if waste is small.
            score += 4.0 * (next_item_size as f64 - post_residual as f64).min(30.0) / 30.0;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more conservative (favor new bins
    // for very poor fits); later, squeeze everything in.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * progress * fill;

    // Deviation from mean residual: prefer bins whose residual is below average
    // (i.e., already well-filled bins) to keep large residuals available.
    let dev = mean_residual - post_residual as f64;
    score += 0.08 * dev;

    // New-bin candidate calibration: empty bin gets post_residual = capacity,
    // which is naturally high; add a mild extra penalty unless the item is large.
    if bin_residual == bin_capacity {
        score += 6.0 - 5.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pre = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual (tight fit), normalized
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space matters more (harder to fill later),
    // modeled as a smooth quadratic amplification of post residual.
    let amp = 1.0 + 2.0 * progress * progress;
    score += amp * (post / cap) * (post / cap);

    // Reward tightness: small post residual relative to item size (smooth ratio term)
    let tightness = 1.0 - (post / pre.max(1.0));
    score -= 0.5 * tightness * tightness;

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt) / cap;
        // quadratic penalty for mismatch (either too big a gap or no fit)
        let fit_quality = if gap >= 0.0 {
            -gap * gap
        } else {
            2.0 * gap * gap
        };
        score += 0.4 * fit_quality * (1.0 - 0.5 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * progress;
    }

    // Penalize opening a new bin when decent alternatives exist
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        let mean = mean_residual.max(0.0);
        // new bin is more attractive only if mean residual is very low relative to item
        let urgency = (item - mean) / cap;
        score += 1.5 + 0.05 * open - 1.0 * urgency.max(0.0) * (1.0 - progress);
        // late-stream: discourage new bins even more
        score += 2.0 * progress;
    }

    // Mild diversity term: prefer bins whose residual differs from mean (balance spread)
    let dev = (pre - mean_residual) / cap;
    score += 0.1 * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it falls
    // into "small unusable" residue classes (mod small integers).
    let pr = post_residual;
    // Class bonus: residues that are common item sizes (multiples of 5/10)
    // are more reusable than odd residues.
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0; // highly reusable residue class
        } else if pr % 5 == 0 {
            score -= 6.0;
        } else if pr % 2 == 1 {
            score += 8.0; // odd residues rarely match integer item sizes
        }
        // Integer-division thresholds: tiny leftovers are dead space.
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 10.0;
        }
    } else {
        score -= 20.0; // perfect closure
    }

    // Capacity-fraction coupling: reward bins whose residual after placement
    // is a usable fraction of capacity (>= 1/4).
    let frac = post_residual as f64 / cap;
    if frac >= 0.25 {
        score -= 10.0 * frac;
    } else if frac > 0.0 {
        score += 15.0 * (0.25 - frac);
    }

    // Lookahead harmonic class: if next item fits harmonically into the
    // post residual (same residue family), strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        if diff % 10 == 0 {
            score -= 18.0;
        } else if diff % 5 == 0 {
            score -= 9.0;
        }
        score -= 4.0; // general lookahead fit bonus
    } else if next_item_size > 0 {
        // next item cannot follow here: mild penalty scaled by overflow
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer filling already-open bins when many are open; new-bin candidate
    // (full residual) gets pushed up unless it enables a clean harmonic start.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * (open_bins_count as f64).ln() - 10.0 * progress;
        // new bin pairs well if item is large (harmonic split of capacity)
        if item_size % 50 == 0 || item_size % 25 == 0 {
            score -= 12.0;
        }
    }

    // Tie-break toward bins below mean residual (consolidate slack).
    score += 0.5 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead space avoidance ---
    // Unusable micro-gaps (< 10) are wasted space forever: hard penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Lookahead coupling: if the next item can't use the leftover gap,
    // the gap becomes permanent dead space -> penalize proportionally.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fills (high fill ratio lowers score further).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // --- Open bins pressure ---
    // Prefer reusing existing bins: penalize the brand-new empty bin candidate,
    // especially when other bins already fit the item.
    if bin_residual == bin_capacity {
        score += 20.0 + 6.0 * fitting_bins_count as f64 + 0.05 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mild alignment with mean residual: bins below mean residual are
    // "more filled" and should be prioritized to consolidate open bins.
    score -= 0.1 * (mean_residual - post_residual as f64);

    // Slight late-stream consolidation pressure: as the stream progresses,
    // avoid leaving many half-empty bins around.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.02 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin, but allow it when the
    // current item would leave a large unusable gap in every existing bin.
    if bin_residual == bin_capacity {
        score += 25.0;
        if post_residual as f64 > mean_residual.max(0.0) {
            score += 10.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        return score;
    }

    // Aggressive 2-step lookahead: reward perfect match of post_residual
    // with next_item_size (next item exactly fills the leftover space).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying quadratically with mismatch.
        score -= 40.0 * (-diff / 12.0).exp();
        score += 0.15 * diff;

        // If next item would fit the post_residual exactly, big bonus.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // If next item cannot fit in post_residual anyway, leftover space is dead;
        // penalize proportionally to how dead it is.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    } else {
        // Last item: just minimize post_residual.
        score += 0.5 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins with less residual (tighter fit).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize creating very small unusable residuals (dead space < 10).
    if post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.92;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_post = pr / cap;

    // Base: tight fit reward (quadratic in normalized post residual)
    let mut score = norm_post * norm_post * 140.0 + pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early stream -> prefer filling bins loosely (keep flexibility),
    // late stream -> strongly prefer minimal post residual.
    let coupling = (1.0 - progress) * norm_post * 30.0 + progress * norm_post * norm_post * 120.0;
    score += coupling;

    // Exact fit bonus (smooth bump near zero residual)
    score -= (1.0 - norm_post).powi(6) * 25.0;

    // Lookahead: reward if next item fits in post residual (smooth kernel)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        let fit_kernel = (-gap / 12.0).exp();
        score -= fit_kernel * 22.0 * (0.5 + 0.5 * progress);
        // penalize leaving space just above next item (awkward gap)
        if pr > next_item_size as f64 {
            score += (pr - next_item_size as f64) * 0.25;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 * (1.0 - fit_ratio);
    }

    // New-bin candidate: penalize opening new bins mildly early, more when
    // open bins are already sparse-fitting; scale with open_bins_count.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 18.0 + 6.0 * (open_bins_count as f64).sqrt() - 20.0 * scarcity * progress;
        // avoid opening bins for tiny items
        score += (1.0 - fit_ratio) * 15.0;
    }

    // Mean residual context: prefer bins deviating below mean residual
    // (filling emptier bins keeps a pool of tight bins for small items).
    score += (mean_residual - pr) * 0.12;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (likely dead space) are penalized; classes that
    // can absorb a typical next item are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divisible into nice capacity fractions (25/50)
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 6.0; // perfectly re-usable half-capacity class
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0; // quarter-class, decent reusability
    }

    // Class B: integer division thresholds on post_residual
    let div_class = post_residual / 10;
    match div_class {
        0 => score += 8.0,          // 0..9: nearly full bin, but tiny dead space
        1 => score -= 1.0,          // 10..19: small gap class
        2 | 3 => score -= 2.0,      // 20..39: mid gap class
        4 | 5 | 6 => score -= 0.5,  // 40..69: flexible class
        _ => score += 0.0,
    }

    // Coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward proportional to how snugly the next item nests
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 4.0 + 4.0 * snug;
        } else {
            // post residual cannot host next item: penalize large dead gaps
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / cap) * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins with high mean residual: discourage hoarding capacity in
    // already-spread bins; prefer tight fits (low post_residual).
    if open_bins_count > 0 {
        let spread = (mean_residual - pr).abs();
        score += spread / cap * 3.0;
    }

    // Progress factor: late in the stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (cap - pr) * 0.02;

    // Modulo-7 harmonic class of item size vs residual: alignment bonus
    if (post_residual % 7) == (item_size % 7) {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver -> heavy penalty
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tightness bonus: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Penalize creating residuals that are small but just above usable minimum
    // (they are hard to fill later).
    if post_residual >= 10 && post_residual <= 20 {
        score += 20.0;
    }

    // Favor bins whose residual matches the item closely (best-fit sharpening).
    let gap = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.3 * gap;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open,
    // unless the fit is exceptionally tight (handled via fill_ratio above).
    if bin_residual == bin_capacity {
        // New-bin candidate score: baseline slightly above a decent fit.
        score = bin_capacity as f64 - 0.5 * item_size as f64;
        score += 8.0 * (open_bins_count as f64).ln().max(0.0);
        // If only this bin can fit the item, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Avoid new bin if lookahead item could pair with the residual left behind.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0;
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving space exactly usable by the next item.
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // residual blocks the lookahead item
    }

    // Late-stream consolidation: as the stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    // Mild preference for bins with below-average residual (they fill up faster).
    if bin_residual != bin_capacity {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / tight fits aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness relative to capacity: penalize large dead space.
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * tightness * tightness;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in the post-residual,
    // this placement is ideal (chained perfect fit).
    if next_item_size > 0 {
        let next_fits = (next_item_size as u32) <= post_residual;
        if next_fits {
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 500.0;
            } else {
                // Reward chains that leave small combined waste.
                let chain_waste = next_post as f64 / bin_capacity as f64;
                score -= 120.0 * (1.0 - chain_waste);
            }
        } else {
            // Penalize when next item cannot use the leftover space at all.
            let gap = (next_item_size as u32 - post_residual) as f64;
            score += 0.6 * gap.min(60.0);
        }
    }

    // Compare post_residual against mean residual of open bins:
    // favor bins whose residual we reduce toward/below the mean (balancing).
    let diff = post_residual as f64 - mean_residual;
    score += 0.5 * diff;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: keep it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 { 0.0 } else { 0.0 };
        let _ = best_possible;
        // Opening a new bin wastes capacity = item_size unused elsewhere;
        // make it costly unless open bins are very full (small mean residual).
        score = 100.0 + item_size as f64 * 0.5 - mean_residual * 0.8;
        // Late in the stream, be more willing to open new bins (less compaction risk).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * progress;
        // If many bins are open and mean residual is large, prefer existing bins.
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 25.0;
        }
    }

    // Mild preference for bins that are already partially filled (consolidation).
    score += 0.1 * (bin_capacity - bin_residual) as f64 * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual relative to item size is good,
    // but avoid leaving tiny unusable slivers (< 10) which are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead-space penalty
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Fit ratio coupling: prefer bins where the item fills a large fraction
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Lookahead: if next item fits exactly in the post residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for fragmenting
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing bins
    let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.5);
    score += 3.0 / pressure.max(1.0);

    // Time horizon: early in the stream, keep bins flexible (mild penalty for
    // very low post_residual); late in the stream, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 {
        score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else {
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: an empty bin is valuable; only prefer it
    // when existing bins would leave bad residuals.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; discourage early-opening when a
        // decent fit exists elsewhere.
        score = bin_capacity as f64 * 0.55;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // opening a bin is fine if nothing else fits well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fit_norm = (item_size as f64 / cap).clamp(0.0, 1.0);
    let mean_n = (mean_residual / cap).clamp(0.0, 1.0);

    // Base: post residual, slightly discounted so tight fits win
    let mut score = pr * (1.0 - 0.35 * fit_norm);

    // Smooth polynomial coupling of residual with stream progress:
    // early on, tolerate larger residuals; late, demand tight packing.
    let tight_bias = pr * pr / cap * (0.5 + 1.5 * progress);
    score += tight_bias;

    // Reward filling bins whose residual matches the mean (keeps bin pool homogeneous)
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let perfect = ((next_item_size as f64 - pr).abs() < 1e-9) as f64;
        score -= 6.0 * perfect + 3.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Slight preference for reusing bins when many are open
    score -= (open_bins_count as f64).ln() * 0.5;

    // New-bin candidate (empty bin): make it unattractive unless residuals are hopeless
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress) - 5.0 * mean_n;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals divisible by common item sizes (10,20,25,50) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for &d in &[10u32, 20, 25, 50] {
            if pr % d == 0 { harmony += 6.0; }
        }
        if pr % 5 == 0 { harmony += 2.0; }
        score -= harmony;
    }

    // Exact fit is perfect.
    if pr == 0 {
        score -= 60.0;
    }

    // Dead space: leftover too small for the minimum plausible item.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead: reward residuals that can host the next item (harmonic pairing).
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 12.0;
            // Bonus if next item exactly fills the resulting residual.
            if pr == next_item_size {
                score -= 20.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize wasted slack.
            score += 8.0;
            // Extra penalty when the waste is in an awkward modulo class.
            if pr % 10 != 0 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin when existing bins fit,
    // unless the current open bins are crowded (tight packing endgame).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        let mut nb = 15.0 + 0.3 * crowding;
        // Late in the stream, opening fresh bins can enable better pairing.
        if progress > 0.7 { nb -= 8.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { nb -= 5.0; }
        score += nb;
    }

    // Prefer filling bins whose residual is far from the mean (balance classes).
    score -= ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    // Integer-division thresholds: bins with residual in [1..=item_size/2) are traps.
    if pr > 0 && pr < item_size / 2 && item_size > 0 {
        score += 6.0;
    }

    // Mild preference for tighter bins (smaller residual before placement).
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 15.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits relative to residual.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // Lookahead: if next item fits into this bin's post-residual, reward.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && (post_residual as i64) < (next_item_size as i64) {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive when open bins are crowded,
    // unattractive when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        score -= 10.0 + 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild stream-progression tilt: later in stream, prefer packing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space that can never be reused by typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny useless slivers
    } else if post_residual >= 10 && post_residual <= 80 {
        // usable residual: reward proportionally to reusability
        score -= 4.0;
    } else if post_residual > 80 {
        score += 3.0; // large residual is fine but not a reward
    }

    // 2-step lookahead: reward if next item exactly fills the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize wasted lookahead potential
            score += 6.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare residual against mean residual: prefer bins that are already
    // more filled than average (consolidation strategy)
    if bin_residual < mean_residual {
        score -= (mean_residual - bin_residual as f64).min(20.0) * 0.8;
    } else {
        score += (bin_residual as f64 - mean_residual).min(20.0) * 0.3;
    }

    // Early in stream: be picky (avoid fragmenting bins); late: fill greedily
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fit_ratio;

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        // default penalty so open bins win unless they fit poorly
        score += 18.0;
        // a new bin is good for huge items that leave awkward residuals elsewhere
        if fit_ratio > 0.85 {
            score -= 20.0;
        }
        // many open bins with high mean residual: better to open fresh bin
        if open_bins_count > 3 && mean_residual > 40.0 {
            score -= 12.0;
        }
        // early stream: opening a bin is cheap
        if progress < 0.2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exact or near-exact fills are excellent.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Penalize dead space that no plausible item can use.
    // Items are between 1 and 100; leftover smaller than next item is risky only
    // if it is also small in absolute terms.
    let dead = post_residual as f64;
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if dead > 0.0 && dead < nx {
            // This bin's leftover cannot host the next item: penalize proportionally.
            score += 0.5 * (nx - dead);
        } else if dead >= nx {
            // Reward leftovers that can still host the lookahead item.
            score -= 0.25 * (nx - (dead - nx).min(nx));
        }
        // Small leftovers (below typical minimum item size) are wasted space.
        if dead < 10.0 {
            score += 20.0 * (10.0 - dead);
        }
    } else {
        // Last item: just close out as full as possible.
        score += 0.1 * dead;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing open bins are crowded or the fit there would be terrible.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin (fragmentation of capacity).
        let mut nb = 45.0 + post_residual as f64;
        // If no open bin can even fit the item, the new-bin call is the only option.
        if fitting_bins_count == 0 {
            nb -= 500.0;
        }
        // If the only fitting open bin would leave a very bad residual, allow opening.
        if fitting_bins_count == 1 && (bin_capacity - item_size) < post_residual {
            nb -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        nb += 25.0 * progress;
        // Many open bins with large mean residual: reuse is cheap, penalize new bin more.
        if mean_residual > (item_size as f64) {
            nb += 15.0;
        }
        score = score.max(nb) + (nb - score).abs() * 0.0; // keep structure simple
        score = score + nb * 0.0 + (nb - score).max(0.0) * 0.0;
        score = score.min(score) ; // no-op guard
        score = score;
        // Final: choose between placement score and new-bin score by taking the
        // new-bin score as this candidate's score.
        score = nb;
    } else {
        // Mild preference for filling fuller bins first (best-fit bias).
        score -= 0.05 * (bin_capacity - bin_residual) as f64;
        // Slight penalty if this bin is far below the mean residual (avoid
        // spreading across many half-empty bins).
        if (bin_residual as f64) > mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post-residual with stream progress
    let poly = norm_pr * (1.0 + 0.6 * progress * norm_pr - 0.4 * (1.0 - progress) * norm_pr * norm_pr);

    let mut score = poly * cap;

    // Penalize dead space more late in the stream
    score += 8.0 * progress * norm_pr * norm_pr * cap;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - nx / cap);
        } else {
            score += 4.0 * (nx - pr) / cap * 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins tighter than the mean residual
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class on post_residual: residues that pair well with typical
    // item sizes (1..100) are more reusable. Reward small usable residues.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 12.0,
        1 | 2 | 3 => score -= 8.0,
        4 | 5 | 6 => score -= 4.0,
        _ => {}
    }

    // Dead-space penalty: residues too small for the smallest plausible item
    // (unless exactly 0) are wasted.
    if pr > 0 && pr < 4 {
        score += 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if next item cannot fit, penalize.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            score -= 15.0 + (pr - next_item_size) as f64 * 0.5;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin
    // unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are mostly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = mean_residual / bin_capacity as f64;
        score += 40.0 + 60.0 * openness - 30.0 * progress;
        // penalize opening new bins when many are open with room
        score += open_bins_count as f64 * 2.0;
    }

    // Mild preference for fuller bins overall
    score += (bin_capacity as f64 - bin_residual as f64) * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness;

    // Exact or near-exact fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // next item still fits after this placement: mild reward scaled by leftover
            let leftover_after_next = post_residual - next_item_size;
            score -= 20.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here after placement: penalize wasted space next item can't use
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.3 * unusable;
        }
    }

    // Compare against mean residual: bins below mean residual are more "committed"
    let dev = mean_residual - post_residual as f64;
    score += 0.2 * dev;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // if the current bin would leave a large dead zone, new bin becomes attractive
        if post_residual > 0 && (post_residual as f64) < 0.25 * bin_capacity as f64 {
            // poor fit into existing bin -> make new bin cheaper
            score -= 70.0;
        }
        // early in the stream, opening bins is cheaper (more future items to fill)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // if next item is large, a fresh bin is more flexible
        if next_item_size > item_size {
            score -= 15.0;
        }
    }

    // Slight penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fits are gold: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // Penalize dead space that no plausible item can fill.
    // Items are 1..100, but small residuals (<10) are hard to fill unless exact.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.5 * next_item_size as f64;
        } else {
            // leftover too small for the next item: mild penalty scaled by waste
            score += 0.3 * post_residual as f64;
        }
        // If this bin can host both current and next item perfectly, big bonus.
        if post_residual == next_item_size {
            score -= 150.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // Cheaper to open a bin when many items remain (amortization) and few bins open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 60.0 * progress;
        score -= 0.5 * open_bins_count as f64;
        // If no open bin can fit at all, opening is inevitable: reduce cost.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If the only alternative is a bad fit (large post_residual elsewhere),
        // the empty bin's raw score (100 - item) may already be competitive.
        // Slightly favor opening when the item is large (poor future stacking).
        score -= 0.2 * item_size as f64;
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer to pack into existing bins to consolidate.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Prefer bins with small residual relative to mean (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 10.0;
    }

    // Time horizon: early in stream, be more selective (penalize waste more),
    // late in stream, just close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Base: quadratic waste penalty (dead space hurts superlinearly)
    let mut score = post * post / cap;

    // Smooth progress coupling: late in the stream, waste matters more
    score *= 1.0 + 0.8 * progress * progress;

    // Reward tight fits: normalized fill ratio bonus
    let fill = 1.0 - post / cap;
    score -= 12.0 * fill * fill * fill;

    // Perfect-fit style reward for very small post_residual
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Lookahead: if next item could exactly fill post_residual, big bonus
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let gap = (post - nx).abs();
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            // penalize leaving space that next item cannot use anyway
            score += 2.0 * (nx - post).min(nx) / cap;
        }
    }

    // Coupling with mean residual: prefer bins near the mean (keeps distribution balanced)
    let dev = (post - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: prefer opening a new bin only when no open bin gives a decent fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // new bin starts with full residual; make it attractive only for bad fits elsewhere
        let fit_quality = 1.0 - item / cap;
        score = 40.0 + 30.0 * fit_quality - 5.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity
    let post = post_residual;
    let cap = bin_capacity;
    let class = post % 10; // residue class of dead space
    let harmonic = (post as f64 / cap as f64);

    // Penalize residuals in "awkward" classes (small but unusable)
    if post > 0 && post < 10 {
        score += 40.0; // tiny dead space is worst outcome
    } else if post == 0 {
        score -= 25.0; // perfect closure
    } else {
        // favor residuals likely to host future items: quantized buckets
        let bucket = post / 10; // integer division threshold
        score -= (bucket as f64) * 2.5;
        // odd residue classes are slightly less reusable
        if class % 2 == 1 {
            score += 3.0;
        }
        if class == 5 {
            score += 1.5;
        }
    }

    // Lookahead coupling: harmonic match between post residual and next item
    if next_item_size > 0 {
        if next_item_size <= post {
            // next item fits here: reward proportional to tightness
            let tight = (post - next_item_size) as f64;
            score -= 12.0 + 10.0 * (1.0 - tight / cap as f64);
            if post % next_item_size.max(1) == 0 {
                score -= 6.0; // exact divisor: future perfect fill
            }
        } else {
            // next item won't fit: penalize if we consumed too much
            let gap = (next_item_size - post) as f64;
            score += gap * 0.15;
        }
    } else {
        // last item: prefer closing bins
        score += harmonic * 5.0;
    }

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual < cap {
        score -= 18.0;
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    if bin_residual == cap {
        let crowded = mean_residual / cap as f64;
        let pressure = open_bins_count as f64 / (step_index.max(1) as f64 + 1.0);
        score = 35.0 + 50.0 * (1.0 - crowded) - 20.0 * pressure.min(1.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // big next item: fresh capacity valuable
        }
    }

    // Fraction-of-capacity harmonic term on current fit quality
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_frac * fit_frac; // reward tight fits quadratically

    // Mild phase modulation via stream progression
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (phase * std::f64::consts::PI).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are wasted forever.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0; // unusable dead space penalty
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    } else if post_residual <= 20 {
        score += 12.0;
    }

    // Reward bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 25.0 * (1.0 - tightness);

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use the leftover gap -> residual likely dead
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer existing bins when any fit decently; new bin baseline is its post_residual
        // (large for small items), plus pressure scaled by how many bins already fit.
        score += 10.0 + (fitting_bins_count as f64) * 8.0;
        // Early stream: allow opening bins more freely to build a portfolio.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post-residual exactly matches next item (perfect 2-step chain)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial reward: next item fits in the post-residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + 20.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize dead space that cannot host the next item
        score += 15.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
    }

    // Penalize tiny unusable residuals (< 10) unless it's a near-perfect fill
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with below-mean residual (tighter packing targets)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Slight pressure to consolidate into fewer bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    } else {
        // New-bin candidate: penalize unless post-residual is small (item nearly fills it)
        score += 10.0 - 40.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Prefer bins that become exactly full
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized fill achieved by placing this item here.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Reward tight fits: strongly discount bins where post_residual is small.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that is too small for the typical smallest item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is excellent; if next item cannot fit but could fit
    // elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Global state: prefer bins with residuals below the mean (consolidate
    // space into few bins, keep large residuals available).
    if bin_residual < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (long future amortizes bins); late, squeeze into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + t * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by how many
        // existing bins could also fit the item.
        score += 55.0 + open_pressure * 3.0 + 12.0 * fitting_bins_count as f64;
        // Early stream: opening a fresh bin is cheaper.
        score -= 30.0 * (1.0 - t);
        // If the item is large relative to capacity, a new bin wastes less.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Mild preference for bins that are already fairly full (best-fit flavor)
    // grows as the stream progresses.
    score -= 12.0 * fill * (0.5 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_next = next_item_size as f64 / cap;
    let mean_n = mean_residual / cap;

    // Base: prefer small leftover space (tight fit), scaled by stream progress.
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear penalty for awkward residuals: small but nonzero leftovers
    // are dead space; smooth polynomial bump around residual ~ next item size.
    let gap = norm_pr - norm_next;
    let bump = -(gap * gap) * cap * 0.8 * (1.0 - progress);
    score += bump;

    // Reward residuals that can still hold the lookahead item (smooth coupling).
    let usable = (norm_pr - norm_next).max(0.0);
    score -= 12.0 * usable * (1.0 + norm_next);

    // Mild attraction toward bins whose residual is near the mean (balanced packing),
    // with a quadratic coupling to progress.
    score += 3.0 * (norm_pr - mean_n) * (norm_pr - mean_n) * (0.5 + progress);

    // Penalize spreading across many open bins; encourage consolidation.
    score += (open_bins_count as f64).ln() * 2.0 * norm_pr;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly worse early, better late
    // when open bins have poor fits. Smooth sigmoid-like progress coupling.
    if bin_residual == bin_capacity {
        let openness = 1.0 / (1.0 + (-6.0 * (progress - 0.5)).exp());
        score = cap * (0.35 + 0.3 * openness) - 20.0 * (1.0 - (norm_next - norm_pr).abs());
        score += (open_bins_count as f64) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 arithmetic captures
    // "usable chunk" structure for typical integer item sizes.
    let post = post_residual;
    let cls = (post % 10) as f64;
    let div = (post / 10) as f64;

    // Reward residuals that are harmonic multiples of 10 (clean classes).
    if post % 10 == 0 {
        score -= 6.0 + 0.5 * div;
    } else {
        // Penalize awkward remainders, worse for small remainders (dead space).
        score += (10.0 - cls) * 0.4;
    }

    // Perfect fit is ideal.
    if post == 0 {
        score -= 50.0;
    }

    // Small unusable dead space (1..=9) is bad.
    if post > 0 && post < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0;
        } else if next_item_size < post {
            let nxt_post = post - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 10.0 + (nxt_post / 10) as f64;
            }
            if nxt_post > 0 && nxt_post < 10 {
                score += 6.0;
            }
        } else {
            // Next item cannot fit here: slight penalty if this bin would
            // be left as the only option for a large future need.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual;
    // keep it attractive only when open bins are mostly full / fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Penalize opening new bins early or when existing bins are roomy.
        score += 20.0 * (1.0 - progress) + 25.0 * fragmentation;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Favor tighter fits: closer residual to item size.
        let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score -= 8.0 * tightness;
    }

    // Prefer bins below mean residual slightly (balance load, keep big
    // residuals available for large future items).
    score += 0.05 * (mean_residual - bin_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band (1..=9)
    // are pure waste once the stream passes; penalize them super-linearly.
    if post_residual >= 1 && post_residual <= 9 {
        score += 24.0 * (10.0 - post_residual as f64);
    }

    // Reward near-perfect fills (post_residual close to 0 but not tiny-dead).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (which would waste this bin's residual forever).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here would leave a large awkward gap.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with open-bin pressure.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if placing in this bin would leave a big dead gap in an existing
        // bin, opening fresh is fine: offset by the gap we would create.
        let gap = post_residual as f64;
        if gap > 40.0 {
            score -= 10.0;
        }
        // Lookahead: if next item would fit comfortably in the fresh residual,
        // opening a new bin becomes more attractive.
        if next_item_size > 0 && (next_item_size as f64) <= gap as f64 {
            score -= 8.0;
        }
    } else {
        // Placing into an existing bin: mild preference when its residual is
        // far below the mean (consolidate waste into already-low bins).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
        // Lookahead synergy: if the next item exactly matches the post
        // residual, this is a perfect chain — reward heavily.
        if next_item_size > 0 && next_item_size as f64 == post_residual as f64 {
            score -= 25.0;
        } else if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 6.0;
        }
    }

    // Mild global pressure: as the stream progresses, avoid proliferating bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly fills remaining space
        if post_residual == next_item_size {
            score -= 1000.0;
        } else {
            // penalize proportional to mismatch, weighted by how close we are
            score -= 50.0 / (1.0 + gap);
            // if next item fits in post residual, mild bonus scaled by tightness
            if next_item_size <= post_residual {
                score -= (next_item_size as f64 / post_residual as f64) * 30.0;
            } else {
                // next item won't fit: penalize dead space, worse when post_residual is small
                score += (post_residual as f64 / bin_capacity as f64) * 40.0;
            }
        }
        // extra penalty if post residual is a tiny unusable sliver
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    }

    // Favor bins tighter than the mean residual (good fits)
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer opening new bins early in the stream when the fit is loose
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual as f64 > mean_residual * 1.5 && progress < 0.5 {
        score += 30.0;
    }

    // Avoid wasting a nearly full bin context: exact-fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual.
    score -= 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(2) * 10.0;

    // Exact or near-exact fill gets a large bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that is too small for typical future items
    // (residuals below the minimum item size are pure waste).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score += 15.0 * (1.0 - t); // early waste is worse, late waste is fine
    } else if post_residual < 30 {
        score += 5.0 * (1.0 - t);
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here after this placement; slight penalty
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // the fit into existing bins is poor. Penalize the fresh bin mildly,
    // more so early in the stream when consolidation matters.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - t);
        // but if existing bins would leave very awkward residuals, opening
        // a new bin becomes attractive: reduce penalty when mean residual
        // is large and fragmented.
        if mean_residual > 40.0 {
            score -= 20.0;
        }
        // If next item is large and current item is small, new bin helps
        // preserve large residual slots for the big next item.
        if next_item_size > 50 && item_size < 30 {
            score -= 25.0;
        }
    }

    // Slight preference to fill bins that are already relatively full
    // (keeps many medium-residual bins available).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 6.0 * fill_ratio;

    // Mild penalty for accumulating too many open bins.
    score += 0.3 * open_bins_count as f64 * (1.0 - t);

    // Deviation from mean residual: prefer bins close to the mean to keep
    // the residual profile homogeneous, except for very tight fits.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mild quadratic in normalized residual; later: stronger cubic penalty
    // for leaving medium-sized dead space (hard to fill near the end).
    let x = pr / cap; // normalized post residual in [0,1]
    let mid = x * (1.0 - x); // peaks at x=0.5 (worst dead space)
    let poly = x * x + 2.0 * x * x * x;
    score += poly * (0.5 + 3.0 * progress) * 12.0;
    score += mid * mid * (1.0 - progress) * 8.0;

    // Reward tight fits: subtract proportional to item fraction consumed.
    let fill = item_size as f64 / cap;
    score -= fill * fill * 15.0 * (0.5 + progress);

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let nx = next_item_size as f64 / cap;
        score -= 6.0 + nx * 10.0 * (1.0 - progress);
    }
    // Penalize if next item would NOT fit (bin becomes a dead-end).
    if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 3.0 + x * 6.0 * progress;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate (empty bin): penalize mildly early, more later,
    // unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap;
        score += 10.0 + 25.0 * progress - big * 12.0;
        // If many bins are open, spreading load is cheaper.
        score -= (open_bins_count.min(50) as f64) * 0.15;
    }

    // Slight preference toward bins with residuals close to item (best-fit flavor),
    // expressed smoothly via mean residual coupling.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * 4.0 * (0.3 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot size" class it falls into.
    // Residuals in low classes (small leftovers) are good; large leftover classes waste space.
    let pr = post_residual as u32;
    let class = match pr {
        0 => 0,
        1..=9 => 1,
        10..=19 => 2,
        20..=34 => 3,
        35..=49 => 4,
        50..=69 => 5,
        _ => 6,
    };
    score += class as f64 * 3.0;

    // Reward exact / near-exact fits strongly.
    if pr == 0 { score -= 30.0; }
    else if pr <= 4 { score -= 12.0; }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            // next item fits: penalize proportionally to how much slack remains after it
            score += (pr - next_item_size) as f64 * 0.3;
            // harmonic pairing: next item divides residual cleanly
            if pr % next_item_size == 0 { score -= 6.0; }
        } else {
            // next item cannot use this residual: small bonus for keeping residual usable later
            score -= 2.0;
        }
        // penalize if residual falls between harmonic fractions (dead zone around half capacity)
        let frac = pr as f64 / cap;
        if (0.45..0.55).contains(&frac) { score += 4.0; }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a new bin unless current fit is bad
    // and many bins are open with scattered residuals.
    if bin_residual == bin_capacity {
        let perfect_fit = pr == 0 || (next_item_size > 0 && next_item_size == pr);
        if perfect_fit {
            score -= 10.0; // fresh bin fine if item is huge
        } else {
            score += 20.0 + 0.5 * open_bins_count as f64;
            // open a new bin when mean residual is small (bins nearly full)
            score -= (cap - mean_residual).max(0.0) * 0.2;
        }
    }

    // Mild preference for tighter bins relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Late in stream: consolidate, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (bin_residual < bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful later
    // are heavy dead weight. Items 1..100, so a residual < ~10 is nearly unusable.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable gap -> severe penalty
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    } else {
        // Perfect fill: reward strongly.
        score -= 100.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Reward residuals that can exactly fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual as f64 == next_item_size as f64 {
        score -= 40.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual >= 10 {
        score += 10.0; // residual too small for next item but not dead-small
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // penalize opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score = bin_capacity as f64 + 15.0 + 3.0 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += 0.5 * mean_residual;
        // But if no existing bin fits well (post_residual of new bin equals item gap),
        // opening is fine: neutralize when item is large relative to capacity.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 40.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Slight preference for bins with residual close to mean (balance spreading).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item still fits here: mild reward proportional to how snugly it fits
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot fit in the leftover: penalize wasted residual relative to next item
            score += 0.5 * (post_residual as f64 - (post_residual as f64 % next_item_size as f64)).min(post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize bins far below mean residual (avoid fragmenting many bins) unless it's a great fit
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Prefer keeping tight (small) residuals among open bins: small residual => lower score
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);

    // Slight preference to fill older bins when many bins are open
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when the item is large and no good fit exists
    if bin_residual == bin_capacity {
        if item_size >= bin_capacity / 2 || (next_item_size > 0 && next_item_size > post_residual) {
            score -= 20.0;
        } else {
            score += 400.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize post_residual and apply superlinear penalty.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let crowded = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins by default; discount penalty when open bins are nearly full.
        score += 35.0 * (1.0 - crowded) * (1.0 - 0.3 * progress);
        // If no open bin truly fits well, opening a new bin becomes competitive.
        if post_residual == bin_capacity && item_size > 0 {
            // new-bin post_residual equals capacity - item_size handled naturally
        }
    }

    // Mild pressure to consolidate: prefer bins below mean residual (emptier bins get filled).
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Slight preference for fewer open bins being filled early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Small tie-break noise-free deterministic perturbation.
    score += 0.01 * ((bin_residual as f64).sqrt());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post-residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 25.0 * poly;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 18.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Prefer bins whose post-residual matches the next item size (smooth coupling)
    if next_item_size > 0 {
        let match_term = (norm_pr - norm_next).abs();
        score -= 12.0 * (1.0 - match_term.min(1.0)) * (1.0 - norm_pr);
    }

    // Penalize deviation from mean residual (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: mild penalty unless post-residual is large (useful fresh bin)
    if bin_residual == bin_capacity {
        score += 6.0 - 20.0 * norm_pr * (1.0 - progress);
    }

    // Slight preference for fewer open bins early
    score += 0.15 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals near multiples of small
    // item sizes (10..=20) are reusable, so reward them (subtract).
    for s in 10..=20u32 {
        if post_residual >= s {
            let r = post_residual % s;
            let closeness = 1.0 - (r as f64 / s as f64).min(1.0);
            score -= 3.0 * closeness * (s as f64 / 10.0);
        }
    }

    // Dead-space penalty: tiny unusable post_residual (not zero) is waste.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.5;
    }
    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (two-item harmonic match).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            let rem2 = post_residual - next_item_size;
            if rem2 < 10 {
                score -= 5.0; // next item leaves near-perfect fill
            } else {
                // reward if post_residual is a harmonic multiple of next size
                if rem2 % next_item_size.max(1) == 0 {
                    score -= 4.0;
                }
            }
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current bin is very full and mean residual is low (stream dense).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
        score -= 6.0 + 8.0 * progress - pressure.min(10.0);
        // If item is large relative to capacity, new bin keeps big residual
        // for future items; slight extra reward.
        if item_size > bin_capacity / 2 {
            score -= 3.0;
        }
    } else {
        // Prefer bins whose residual is already small (tight packing).
        let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 4.0 * tightness;
        // Prefer bins with residual below the mean (more committed bins).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Modulo threshold on capacity fraction: residuals in [25,50] or [75,99]
    // of 100 are awkward; penalize mildly.
    let q = post_residual / (bin_capacity / 4).max(1);
    if q == 1 || q == 3 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // ---- Strict dead-space avoidance ----
    // A leftover gap that the NEXT item cannot use is wasted capacity.
    if !is_new_bin && post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // Gap is unusable for the lookahead item: penalize proportionally
            // to how much space is stranded (small gaps = pure loss).
            score += 40.0 + 0.6 * post_residual as f64;
        }
        // Absolutely tiny gaps (<10) are almost certainly dead space regardless
        // of the unknown distribution's lower bound.
        if post_residual < 10 {
            score += 25.0;
        }
        // Perfect fit: reward strongly.
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // ---- Last-chance pressure ----
    // If this is the only open bin that can fit the item, using it avoids
    // opening a fresh bin; reward it (but not for the new-bin candidate).
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 20.0;
    }

    // ---- open_bins_count pressure ----
    // Prefer consolidating into already-open bins: subtract a mild bonus so
    // existing bins beat the empty-bin candidate when fits are comparable.
    if !is_new_bin {
        score -= 0.15 * open_bins_count as f64;
    }

    // ---- New-bin candidate calibration ----
    if is_new_bin {
        // Opening a bin costs more early in the stream (many items still to come
        // could use existing space) and when existing bins still hold room.
        score += 10.0 + 30.0 * (1.0 - progress) + 0.25 * mean_residual;
        // But if all open residuals are tiny (mean_residual near 0), existing
        // bins are nearly dead: make the new bin attractive.
        if mean_residual < 15.0 {
            score -= 25.0;
        }
        // If the item would leave a large, reusable residual in a fresh bin,
        // that's a reasonable investment: soften the penalty.
        score -= 0.1 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fills (dead space minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this bin becomes perfectly packed after two steps.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize larger post residuals relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Compare post_residual against mean residual: prefer bins whose residual
    // becomes close to the average (keeps flexibility), but reward shrinking
    // large residuals.
    if post_residual as f64 > mean_residual {
        score += 0.2 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.1 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive late in the stream or when
    // current bin would leave a very poor fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 > 40.0 && post_residual < bin_capacity as f64) as i32;
        score += 80.0 - 60.0 * progress + 30.0 * poor_fit as f64;
        // If next item is small and would waste a fresh bin, discourage new bin
        if next_item_size > 0 && next_item_size < post_residual {
            score += 20.0;
        }
    }

    // Mild penalty for very tight fits that leave awkward small residuals
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Slight preference for fuller bins as stream progresses
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: penalize if post-residual can't fit the next item but could
    // have if we chose differently; reward if next item fits snugly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when all
    // open bins are crowded (low mean residual) or few bins are open.
    if bin_residual == bin_capacity {
        let crowding = 1.0 - mean_residual / bin_capacity as f64;
        let scarcity = 1.0 / (1.0 + open_bins_count as f64);
        score -= 10.0 * crowding + 6.0 * scarcity;
        // Late in the stream, avoid spreading items into fresh bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * progress;
        // If the next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 5.0;
        }
    } else {
        // Prefer bins whose residual is below average (well-utilized bins).
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    // Slight preference to fill earlier-opened bins (reduce bin count).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 40.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (1.0 + progress);

    // Penalize dead space below smallest plausible item, smoothly
    let dead = ((10.0 - pr).max(0.0)) / 10.0;
    score += 60.0 * dead * dead;

    // Lookahead coupling: favor residuals that fit next item
    if next > 0.0 && pr >= next {
        score -= 15.0 * (1.0 - (pr - next) / cap) * (0.3 + 0.7 * progress);
    } else if next > 0.0 {
        score += 8.0 * (next - pr) / cap;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mildly penalize early, allow late when residuals are poor
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let open_f = open_bins_count as f64;
    let residual_pressure = (mean_residual - norm_pr * cap).abs() / cap;
    score += new_bin * (10.0 + 30.0 * (1.0 - progress) + 5.0 * residual_pressure - 2.0 * open_f * progress);

    // Mild dispersion penalty: avoid bins far from mean residual
    score += 6.0 * residual_pressure * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality by residue class.
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let frac = pr as f64 / cap; // residual fraction of capacity

    // Base: minimize waste, with slight superlinear penalty on mid-size dead space.
    score += 8.0 * frac * frac;

    // Modulo classes: residuals that are "usable" (>= 10 typical small item,
    // or exactly matching next item) are rewarded.
    if pr > 0 {
        if pr >= next_item_size && next_item_size > 0 {
            score -= 6.0; // next item can still land here
        }
        // Harmonic buckets: pr divisible by small integers => flexible
        if pr % 10 == 0 {
            score -= 3.0;
        } else if pr % 5 == 0 {
            score -= 1.5;
        }
        // Very small unusable residue is fine (near-perfect fit)
        if pr < 10 {
            score -= 12.0;
        }
        // Mid-range unusable dead zone: penalize
        if pr >= 10 && pr < 20 {
            score += 5.0;
        }
    } else {
        score -= 15.0; // perfect fit
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well; make the empty bin moderately unattractive by default.
    if bin_residual == bin_capacity {
        // Attraction grows with item size and with scarcity of fitting bins.
        score -= 4.0 + 0.05 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 3.0; // big next item: keep fresh bin clean
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Prefer fuller bins relative to fleet average.
    score -= 0.3 * (mean_residual - (bin_residual as f64));

    // Slight preference to spread across few bins when many open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items are "dead" — penalize them quadratically.
    if post_residual > 0 {
        let dead_threshold = 20.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 1.5;
        } else {
            // Smooth waste pressure on larger residuals.
            score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    if item_size > 0 {
        score -= 40.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Open bins pressure: with many open bins, prefer filling existing ones;
    // penalize opening a new bin more strongly as open_bins_count grows.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 18.0 + 6.0 * (open_bins_count as f64).sqrt() + 10.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    } else {
        score -= new_bin_penalty * 0.5;
    }

    // Last chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward; if post_residual
    // is dead space relative to next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Mild mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.15 * ((post_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack * 0.15);
    }

    // Penalize dead space: post_residual too small for any future item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual > 0 && post_residual < 25 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Prefer bins tighter than the mean residual (good fits).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight preference to fill bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    // Discard new-bin option unless nothing fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 && post_residual >= 10 {
            score += 80.0;
        } else {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual approaches 0
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Dead-space penalty: small post_residual that cannot fit even the smallest
    // plausible item is wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item exactly fills the post_residual,
    // penalize if next item barely doesn't fit (chain break risk).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bins are expensive when many bins are
    // already open; slightly attractive when the stream is early or open bins
    // are all poorly fitting.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + 0.5 * (open_bins_count as f64) - 20.0 * progress;
    }

    // Global fragmentation pressure: if the mean residual across open bins is
    // low (bins nearly full), conserve remaining capacity by preferring bins
    // where this item wastes proportionally less.
    let waste_frac = (post_residual as f64) / (bin_capacity as f64);
    score += 10.0 * waste_frac * (1.0 - mean_residual / (bin_capacity as f64));

    // Mild penalty for spreading across too many bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    // Base: prefer tight fits (small post residual), scaled non-linearly.
    let mut score = pr;

    // Non-linear coupling: post residual penalized more as stream progresses
    // (waste compounds over the remaining stream).
    score += (pr_norm * pr_norm) * cap * (0.5 + 1.5 * progress);

    // Dead-space term: residuals too small for typical future items are worthless.
    let next = next_item_size as f64;
    if next > 0.0 {
        let unusable = (next - pr).max(0.0);
        score += unusable * (1.0 + progress);
        // Reward bins that can also fit the next item (chaining fits).
        if pr >= next && is_new_bin < 0.5 {
            score -= 6.0 * (1.0 - pr_norm) * (1.0 - pr_norm);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 12.0 + 8.0 * progress;
    }

    // New-bin candidate: penalize mildly early (consolidate), allow late when
    // open bins are already fragmented (mean residual high).
    let fragmentation = (mean_residual / cap - pr_norm).abs();
    score += is_new_bin * (18.0 - 14.0 * progress * fragmentation.min(1.0));

    // Slight preference for fuller bins among equals (non-linear in fill).
    let fill = 1.0 - pr_norm;
    score -= fill * fill * 4.0;

    // Mild crowding pressure: many open bins -> prefer existing bins over new.
    score += is_new_bin * (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by integer division
    let post_class = post_residual / 10;
    let post_mod = post_residual % 10;

    // Perfect fit reward: strong subtraction for zero or tiny residue
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // Harmonic coupling: residual class vs next item size class
    if next_item_size > 0 {
        let next_class = next_item_size / 10;
        let next_mod = next_item_size % 10;
        // Exact harmonic match: next item fits perfectly into the leftover class
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Fractional fill: how much of the leftover the next item consumes
            let fill_frac = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fill_frac;
            // modulo arithmetic: residues sharing a common divisor class pair well
            if next_mod == post_mod && post_mod != 0 {
                score -= 40.0;
            }
            // integer division threshold: leftover after next placement
            let post2 = post_residual - next_item_size;
            if post2 <= 10 {
                score -= 80.0;
            }
            if post2 % 10 == 0 && post2 > 0 {
                score -= 30.0; // round leftover class is reusable
            }
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += 60.0 + 2.0 * (post_residual as f64 % 10.0);
        }
        // large next items: prefer keeping big residuals around
        if next_class >= 6 && post_residual < next_item_size {
            score += 25.0;
        }
    } else {
        // last item: any placement is fine, prefer tight fit
        score -= 50.0;
    }

    // Dead-space penalty for mid-range useless residues (11..=19 class band)
    if post_residual > 10 && post_residual < 20 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin fit is bad
    if bin_residual == bin_capacity {
        score += 120.0;
        // but if no open bin fits well, opening is acceptable
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Fraction-of-capacity coupling: reward filling large fractions of the bin
    let used_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 50.0 * used_frac;

    // Stream progression: early on, be conservative with tight fits; later, pack greedily
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 30.0 * (100.0 - post_residual.min(100)) as f64 / 100.0;

    // Mean residual context: if this bin's residual is far below mean, it's scarce space — use it
    if (post_residual as f64) < mean_residual {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // Many open bins: slight penalty for adding fragmentation
    score += 0.5 * open_bins_count as f64;

    // Modulo tie-breaker on post_residual for deterministic diversity
    score += (post_residual % 7) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead gap: nearly worthless leftover
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0; // marginal gap: only fits the smallest items
    } else if post_residual >= 20 && post_residual < 35 {
        score += 6.0; // moderately reusable gap
    }

    // Reward tight fits (exact and near-exact placements).
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 22.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; if the gap cannot host the next item, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing space rather than opening yet another bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt() * (1.0 + progress);
    if bin_residual != bin_capacity {
        score -= pressure * 2.0;
    } else {
        // New-bin candidate: base penalty so it only wins when open fits are bad.
        score += 12.0 + pressure;
        // A fresh bin is acceptable late in the stream when mean residual is low.
        if mean_residual < 8.0 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is already small (fill the tightest bin).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Reward near-perfect fills strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0 + (10 - post_residual) as f64 * 20.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // slack after both items: smaller is better
            let slack2 = (post - nxt).max(0.0);
            score -= 50.0 + slack2 * 0.5;
            if slack2 == 0.0 {
                score -= 300.0; // perfect 2-item packing
            }
        } else {
            // next item won't fit here: penalize proportionally to mismatch
            score += (nxt - post) * 0.8;
        }
    }

    // Compare against mean residual: prefer bins that are tighter than average
    score += (post - mean_residual) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize leaving dead space that nothing typical can use
    if post_residual > 0 && post_residual < 10 {
        score += 0.0; // already rewarded above
    } else if post_residual >= 10 && post_residual < 30 {
        score += 5.0; // mildly awkward zone
    }

    // New-bin candidate: only attractive when current bins are poor fits
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so we prefer existing bins with decent fits
        score += 150.0;
        // but if many open bins and mean residual is small (fragmented), a fresh bin is fine
        score -= mean_residual * 0.5;
        // late in the stream, opening new bins is cheaper than forcing bad fits
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 40.0;
        // if the item is large relative to residual elsewhere, new bin helps
        score -= item * 0.3;
    }

    // Prefer consolidating into fewer bins when few are open
    if open_bins_count > 0 {
        score -= 10.0 / open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score when post_residual is a small fraction of capacity.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that no plausible item can fill (items <= 80).
    if post_residual > 0 {
        let dead = if post_residual > 80 { post_residual - 80 } else { 0 } as f64;
        score += 3.0 * dead;
        // Residuals below 10 are essentially unusable waste.
        if post_residual < 10 {
            score -= 8.0; // perfect sealing is great
        } else if post_residual < 20 {
            score += 2.0; // risky sliver
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post_residual pairs well with the next item.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 6.0 * (1.0 - diff / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 10.0; // perfect chaining
        }
    }

    // New-bin candidate: only attractive when open bins have poor fits on average
    // or the item fits nothing well. Penalize opening new bins early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_pressure = (mean_residual - item_size as f64).abs();
        score += 25.0
            + 0.5 * open_bins_count as f64
            - 10.0 * fit_pressure / bin_capacity as f64
            - 8.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 20.0; // nothing else fits well: open a bin
        }
    }

    // Mild preference for fuller bins among ties (mean residual coupling).
    score -= 2.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer small post_residual (tight fits)
    let mut score = post;

    // Smooth non-linear penalty on large residual dead space, amplified by progress
    let dead = norm_post * norm_post;
    score += 30.0 * dead * (0.5 + progress);

    // Coupling: post_residual vs mean residual across open bins
    let mr = mean_residual / cap;
    score -= 12.0 * (norm_post - mr) * (1.0 - progress);

    // Reward near-exact fills smoothly (quadratic trough at post = 0)
    score -= 20.0 * (1.0 - norm_post) * (1.0 - norm_post) * 0.25;

    // Last-chance bin bonus (only fitting bin)
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if post >= nxt { 1.0 } else { 0.0 };
        let gap = ((post - nxt).abs()) / cap;
        score -= 10.0 * fit_next * (1.0 - gap * gap);
    }

    // Mild penalty for opening new bins when many bins are open with slack
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
        score -= 6.0 * (1.0 - norm_post);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    let c = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / c; // 0..1

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space classes: leftover below the minimum item size (1) never matters,
    // but tiny leftovers (1..=5) are nearly dead -> penalize mildly.
    if post_residual <= 5 {
        score -= 60.0; // actually reward tiny waste slightly (nearly perfect fit)
    }

    // Harmonic band rewards: leftovers that match "nice" fractions of capacity
    // (1/2, 1/3, 1/4) are reusable by common item sizes.
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;
    if post_residual == half { score -= 40.0; }
    else if post_residual == third { score -= 30.0; }
    else if post_residual == quarter { score -= 20.0; }

    // Modulo-class coupling: does post_residual's class match next_item_size?
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits here afterwards -> strong reward, scaled by tightness
        let tight = 1.0 - ((post_residual - next_item_size) as f64) / c;
        score -= 80.0 + 60.0 * tight;
    } else if next_item_size > 0 {
        // next item won't fit here -> this bin becomes dead-ish for lookahead
        score += 25.0;
    }

    // Residual-vs-mean alignment: prefer bins whose residual is close to what item consumes.
    let waste = (post as f64 - mean_residual).abs();
    score += 0.15 * waste;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0 + 0.5 * (item_size as f64);
    }

    // New-bin candidate (empty bin): make it attractive only when fit in open bins is bad.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 55.0;
        // cheaper to open a new bin late in the stream? no: early stream amortizes more,
        // so penalize opening new bins early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * progress;
        // if many open bins already, prefer consolidation
        score += 1.5 * open_bins_count as f64;
        // if lookahead item is small, new bin can host both
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Nonlinear penalty on very large leftover (harmonic tail): big leftovers are flexible,
    // but huge waste means poor packing; use quadratic above 3/4 capacity.
    if frac > 0.75 {
        score += 40.0 * (frac - 0.75) * (frac - 0.75) * 16.0;
    }

    // Prefer tighter fits generally: reward small post_residual via sqrt shaping.
    score -= 10.0 * (1.0 - frac).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly useless.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // dead space: gap too small for any item
        } else if post_residual < 25 {
            score += 25.0; // hard-to-fill small gap
        } else if post_residual < 50 {
            score += 8.0;
        } else {
            score -= 12.0; // large residual retains flexibility
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 80.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage proliferation of bins when many are open.
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate: only attractive when no open bin fits well,
    // or when open bins are nearly full and the item is small.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 70.0; // must open a bin
        } else {
            // Penalize opening new bins when decent fits exist.
            score += 55.0 * (1.0 - pressure);
            if post_residual >= 50 {
                score -= 10.0; // fresh bin keeps flexibility for future items
            }
        }
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // next item won't fit here; leftover likely wasted
    }

    // Late in the stream: avoid leaving scattered small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 25 {
        score += 20.0 * progress;
    }

    // Mild preference toward bins already below-average residual (consolidation).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward if the next item exactly fills the post residual (perfect 2-chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills leftover space.
            let after_two = post_residual - next_item_size;
            score -= 40.0 * (1.0 - after_two as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving awkward gaps.
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 0.5 * gap;
            }
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter-than-average bin).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last chance: strongly prefer using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Dead-space penalty: small unusable remnants are bad unless next item uses them.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / 50.0);
    }

    // New-bin candidate: only attractive when open bins are quite full or item fits poorly.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Default modest penalty so existing bins win unless they're nearly full.
        score += 30.0;
        score -= 80.0 * pressure;
        // If the item is large relative to mean residual, opening fresh is fine.
        if item_size as f64 > mean_residual {
            score -= 40.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Slight preference to fill bins earlier in the stream (consolidation).
    score += 0.01 * (step_index as f64 / (total_items.max(1) as f64)) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: strongly favor small post-residual (non-linear).
    let tightness = (post / cap).powi(3);
    score += tightness * 120.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 300.0;
    }

    // Lookahead: penalize leaving residual that cannot fit the next item
    // (dead space), reward residuals that exactly or nearly fit it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual > 0 && post_residual < next_item_size {
            score += 60.0; // dead space for the known next item
        }
        if next_item_size <= post_residual {
            // next item can still fit here: good chaining potential
            score -= 25.0 * (1.0 - ((post_residual as f64) - nxt) / cap);
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, use it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: a fresh bin should only win when no open
    // bin offers a decent fit. Give it a mild penalty proportional to the
    // number of alternatives, plus its own residual cost.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        score += 40.0 + 10.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper (more future items
        // to fill them); later, prefer consolidating.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 60.0;
    }

    // Global state coupling: if open bins already carry lots of residual
    // (mean_residual high), encourage filling them rather than opening more.
    score -= (mean_residual / cap).max(0.0).min(2.0) * 15.0;

    // Penalize opening bins when many are already open and underfilled.
    if open_bins_count > 0 && bin_residual == bin_capacity {
        score += 5.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x;

    // Smooth progress-weighted penalty: dead space matters more later in the stream
    score += 2.0 * x * x * (0.5 + progress);
    score -= 1.5 * x * x * x * progress;

    // Reward tight fits (small post_residual), smoothly
    score -= 3.0 * (1.0 - x) * (1.0 - x) * (0.5 + 0.5 * progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Coupling with mean residual: penalize bins far from the fleet mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 0.8 * dev * dev;

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 2.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 1.5 * (n - pr) / cap;
        }
    }

    // Mild penalty on opening many bins early
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: keep neutral-ish, slightly favored when residuals are fragmented
    if bin_residual == bin_capacity {
        score = cap - pr + 25.0 * progress + 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in the low band is worst.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        // class by integer division thresholds
        let class = pr / 10; // 0..10 harmonic classes
        // penalize small unusable residues (class 0..2), reward mid residues
        score += (8 - class.min(8)) as f64 * 3.0;
        if pr < 10 {
            score += 25.0; // dead space below min item size
        }
    }

    // Lookahead: reward if next item fits exactly into post residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            score -= 20.0 - (slack as f64).min(20.0);
            // harmonic coupling: next item residue class
            let nres = slack % 10;
            if nres < 3 { score -= 6.0; }
        } else {
            score += 12.0; // next item cannot use this bin's residue
        }
    }

    // Last chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless current fit is terrible
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        score += 40.0 - waste * 0.2 - progress * 10.0;
        if fitting_bins_count == 0 { score -= 100.0; }
    }

    // Prefer tighter bins relative to mean residual
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f).min(30.0) * 0.5;
    } else {
        score += (res_f - mean_residual).min(30.0) * 0.3;
    }

    // Many open bins: mild pressure to consolidate
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a small NONZERO gap is the worst outcome,
    // because it likely cannot host any future item (sizes 1..100).
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead-space severity peaks for tiny gaps; decays as gap grows.
        let dead = 60.0 / (gap + 2.0);
        score += dead;
        // Extra penalty if the gap is smaller than the lookahead item
        // (it is provably unusable for the very next arrival).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 40.0;
    }

    // Tight fit reward: fraction of residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead synergy: reward when the post-residual exactly accommodates
    // the next item (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, tolerate slight spreading by discounting new-bin attractiveness.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += 1.5 * pressure;

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (a "lonely small hole" bin), prefer filling it to consolidate state.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate (empty bin): make it unattractive unless the fit into
    // open bins would be terrible (handled by dead-space penalties above).
    if bin_residual == bin_capacity {
        score += 10.0 + pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when leftover exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            // leftover too small for next item: penalize dead space more if very small
            let waste = post_residual as f64;
            score += (1.0 - waste / 50.0).max(0.0) * 40.0;
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it unattractive unless all open bins are poor fits
    if bin_residual == bin_capacity {
        score += 80.0;
        if fitting_bins_count > 0 {
            score += 120.0;
        }
    }

    // Progress: as stream advances, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that likely cannot host a future item.
    if post > 0.0 && post < 10.0 {
        score += 25.0;
    } else if post >= 10.0 && post < 20.0 {
        score += 8.0;
    }

    // Exact-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: penalize if post residual cannot fit the next item but bin_residual could.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 10.0; // this bin stays useful for the next item
        } else if bin_residual as f64 >= nx && post < nx {
            score += 6.0; // placement blocks a good follow-up fit
        }
        // Reward if post residual exactly matches next item size.
        if (post_residual as u32) == next_item_size {
            score -= 12.0;
        }
    }

    // New-bin candidate handling: neutral baseline, opened only if no decent fit exists.
    if bin_residual == bin_capacity {
        score = cap * 0.55
            + open_bins_count as f64 * 0.8
            - (fitting_bins_count as f64) * 6.0
            + mean_residual * 0.2;
        if next_item_size > 0 && (bin_capacity as u32) >= next_item_size {
            score -= 5.0;
        }
    }

    // Time-horizon modulation: late in the stream, prefer consolidating into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Global pressure: many open bins with large mean residual -> favor using existing space.
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual;
        score += 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer small post_residual, with non-linear (quadratic) sharpening
    let mut score = post + 40.0 * norm_post * norm_post;

    // Smooth stream-progress coupling: later in stream, punish wasted space harder
    score += 60.0 * progress * norm_post * norm_post;

    // Dead-space penalty: residuals too small to be useful (below min item size 1..100, use smooth sigmoid-like term)
    let tiny = (norm_post - 0.05) / 0.05;
    let dead = 1.0 / (1.0 + (-tiny * tiny).exp());
    score += 50.0 * dead;

    // Reward near-perfect fills smoothly
    score -= 30.0 * (-norm_post * norm_post / 0.005).exp();

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 15.0 + 10.0 * (1.0 - (next_item_size as f64 / post).min(1.0));
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty proportional to overshoot
        score += 8.0 * ((next_item_size as f64 - post) / cap);
    }

    // Crowding: many open bins -> prefer consolidation onto tighter fits
    score += (open_bins_count as f64).ln() * 2.0 * norm_post;

    // Mean residual coupling: if this bin is far below mean residual, it is a good tight fit
    score -= 5.0 * ((mean_residual - post) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "harmonically useful"
    // (divisible into common small item sizes) deserve a bonus.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact-fit reward: zero post residual is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: small unusable post-residuals (below min item size 1..10 band)
    // are wasted capacity; penalize tiny-but-nonzero leftovers harder than mid ones.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic divisibility classes: residual that can host common sizes (multiples of 10, 25, 50)
    let harmonic_bonus = if post_residual % 50 == 0 {
        25.0
    } else if post_residual % 25 == 0 {
        15.0
    } else if post_residual % 10 == 0 {
        10.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead coupling: if next item fits exactly in the post-residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits: residual left after that placement
            let after_next = post_residual - next_item_size;
            score -= 10.0 + (after_next as f64).min(20.0);
        } else {
            // next item will NOT fit here: this bin becomes dead for the next step;
            // penalize proportionally to how much of the next item is blocked.
            let blocked = (next_item_size - post_residual) as f64;
            score += blocked.min(30.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it attractive only
    // when open bins are congested or mean residual is low (fragmented).
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64).ln().max(0.0);
        let fragmentation = (mean_residual / cap - 0.3).max(0.0);
        // base cost of opening a new bin, discounted by congestion/fragmentation
        score += 55.0 - 6.0 * congestion - 80.0 * fragmentation;
        // if the current item is large relative to capacity, opening fresh is fine
        if (item_size as f64) / cap > 0.6 {
            score -= 20.0;
        }
    } else {
        // Prefer fuller bins: tighter fit (small relative post residual) is better.
        let tightness = 1.0 - pr / cap;
        score -= 8.0 * tightness * tightness;
    }

    // Stream progression: late in the stream, avoid opening new bins (amortization matters).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 25.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty for spreading across many bins when mean residual is already high.
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1, but
    // realistically >= 10 in classic streams) can use are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: with many open bins, discourage spreading; favor
    // filling existing bins instead of opening new ones.
    score += 1.5 * open_bins_count as f64;

    // Mean residual coupling: bins whose residual is far below the mean are
    // "almost full" -> prefer them (subtract). Bins far above mean keep score high.
    let dev = mean_residual - post_residual as f64;
    score -= 0.8 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement (chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this gap -> dead space likely.
        score += 8.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual, which
    // already scores high; add a mild fixed penalty so it only wins when all
    // open bins fit poorly (their scores raised by dead-space penalties).
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small leftover.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 40.0 - slack * 2.5;
        } else {
            score -= 15.0 / slack.sqrt();
        }
    }
    // Next item does NOT fit: penalize proportionally (wasted pairing potential).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Tightness reward: leaving very little residual is excellent.
    if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Compare against mean residual: bins already tighter than average get priority.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity as f64;
        score -= item_ratio * 20.0;
        if fitting_bins_count > 0 {
            score += 30.0; // discourage opening new bin when fits exist
            if next_item_size > 0 && post_residual >= next_item_size {
                score += 15.0; // even more if a fit could chain with next item
            }
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference for fuller bins among equals.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual relative to capacity)
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Perfect fit gets a big bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space that is too small for typical items but nonzero
    if post_residual > 0 && post_residual < item_size.min(60) {
        let dead = post_residual as f64;
        score += 0.6 * (60.0 - dead).max(0.0);
    }

    // Lookahead: if next item fits in the post residual, reward; otherwise penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when good alternatives exist
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let scarcity = if fitting_bins_count > 0 { 0.0 } else { 20.0 };
        score += 35.0 + 25.0 * (1.0 - progress) - scarcity;
        // late in stream, prefer packing into open bins even more
        score += 10.0 * progress;
    }

    // Prefer fuller bins relative to the current mean residual
    score -= 2.0 * ((bin_capacity as f64 - bin_residual as f64) - mean_residual).max(0.0) / 10.0;

    // Mild penalty for many open bins (consolidation pressure)
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 - progress) - norm_post * progress;
    score += 12.0 * poly;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - norm_post) * (1.0 + progress) * 4.0;

    // Penalize creating dead space relative to the mean residual across open bins.
    score += 0.5 * (post - mean_residual) * (1.0 - progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Lookahead: reward leaving space that can still host the next item.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 3.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Slight penalty for spreading across many open bins late in the stream.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: coarse residue classes (integer division).
    // Residuals in the "useful band" (small, likely fillable by future items) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = post_residual / 10; // harmonic class width 10

    match class {
        0 => score -= 25.0,                 // near-perfect fit (0-9 dead space)
        1 => score -= 15.0,                 // 10-19: still very fillable
        2 => score -= 5.0,                  // 20-29: decent
        3 => { score += 3.0; }              // 30-39: mediocre
        4 => { score += 8.0; }              // 40-49: half-empty bin
        5 => { score += 12.0; }             // 50-59
        _ => { score += 18.0; }             // 60+: mostly empty, wasteful placement
    }

    // Exact modulo harmonics: residuals divisible by common item sizes pair well.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 5 == 0 && post_residual % 10 != 0 { score -= 2.0; }

    // Lookahead coupling: if the next item exactly fills the post-residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how much of the residual it consumes
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 20.0 * fill;
            // harmonic class of the double residual
            let post2 = post_residual - next_item_size;
            if post2 <= 5 { score -= 12.0; }
            else if post2 <= 15 { score -= 5.0; }
        } else {
            // next item cannot use this residual: penalize large leftover classes
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when current fit is bad
    // and we are early/mid stream with few open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let badness = (pr / cap).clamp(0.0, 1.0);
        score = cap * 0.45 + 30.0 * badness - 20.0 * (1.0 - progress) * (open_bins_count as f64 / 10.0).min(1.0);
        // perfect-fit bonus override: never open a new bin when this bin gives a tight fit
        if post_residual <= 5 { score += 100.0; }
    }

    // Tight-fit refinement: reward filling most of the bin.
    let used_frac = 1.0 - pr / cap;
    score -= 10.0 * used_frac * used_frac;

    // Mild penalty for scattering across too many open bins.
    score += 0.15 * open_bins_count as f64;

    // Mean-residual alignment: prefer bins whose residual is close to the fleet mean
    // (keeps a balanced pool of fillable bins).
    let dev = (pr - mean_residual).abs();
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 {
        let min_item = 1u32;
        // A residual that cannot fit even the smallest possible next item is pure dead space.
        if post_residual < min_item.max(1) {
            score += 1000.0;
        }
        // Non-linear penalty: dead space grows quadratically as residual shrinks.
        let r = post_residual as f64;
        let unusability = ((bin_capacity as f64) - r) / (bin_capacity as f64);
        score += (1.0 - unusability) * (1.0 - unusability) * 10.0;
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Exact fit of the lookahead item: big reward for leaving exactly next_item_size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // If the next item cannot fit in the post residual, mild penalty unless post_residual is 0.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 0.5;

    // Prefer bins whose residual is below the current mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: make it costly unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + pressure;
        // But if this bin is the only fitting option is irrelevant for new bin; instead:
        // allow opening a new bin when all fits would create dead space below next item.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            // neutral: handled by per-bin penalties above
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post-residual
    // can host the next item exactly or well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 500.0; // perfect chain: fill now, fill next exactly
        } else if (post_residual as u32) >= next_item_size {
            let slack = post_residual as f64 - next;
            // Prefer bins where next item leaves minimal slack again.
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to wasted
            // potential, but less harshly if residual is already tiny.
            let waste = next - post_residual as f64;
            score += 0.3 * waste;
        }

        // Coupling with mean residual: if this bin is tighter than average,
        // filling it is good (keeps roomy bins flexible for future items).
        let tightness = (mean_residual - post_residual as f64) / bin_capacity as f64;
        score -= 80.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when all open bins fit badly
    // (large post_residual relative to typical item sizes) or bins are crowded.
    if bin_residual == bin_capacity {
        // Base penalty: reusing open bins is generally better.
        score += 60.0;
        // But if existing bins would leave big dead space, new bin becomes good.
        let dead = post_residual as f64;
        score -= 1.5 * dead;
        // More open bins -> slightly favor consolidation into new bin? No:
        // favor reusing when many bins already open.
        score += 2.0 * open_bins_count as f64;
        // Early in stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Prefer bins with small pre-residual (tighter fit overall).
    score += 0.2 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space that can only host tiny future items
    if post_residual > 0 {
        let pr = post_residual as f64;
        let small = (post_residual < 10) as i32 as f64;
        score += small * 40.0;
        // dead-space curvature: waste grows superlinearly as residual shrinks
        score += 25.0 / pr;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // exact chain fit bonus
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: prefer opening a new bin when open bins
    // have large residuals but the item fits poorly, or when many bins are open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of a fresh bin: slightly worse than a good existing fit
        score += 10.0;
        // if item is large relative to capacity, a fresh bin is attractive
        let frac = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * frac * frac;
        // early stream: building diverse bins is fine
        let t = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - t);
        // many open bins with small mean residual -> reuse instead of opening
        if mean_residual < item_size as f64 * 1.5 {
            score += 25.0;
        }
        if open_bins_count > 4 && mean_residual < 20.0 {
            score += 30.0;
        }
    } else {
        // reward tightness of fit relative to bin residual
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 30.0 * fit_ratio * fit_ratio;
        // slight preference for bins below mean residual (tighter bins)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 5.0;
        }
    }

    // global pressure: with many open bins, encourage consolidation into existing bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: tight fits preferred (small post_residual), with non-linear sharpening.
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Dead-space penalty grows super-linearly for residuals that fit nothing typical.
    let unusable = (norm_post).powi(3) * cap * 0.5;
    score += unusable;

    // Smooth stream-progress coupling: early on, tolerate loose fits (post_residual
    // matters less); late in the stream, tighten aggressively via polynomial coupling.
    let tighten = 1.0 + 2.5 * progress * progress * norm_post;
    score *= tighten;

    // Lookahead: reward leaving post_residual that still fits the next item,
    // penalize when the leftover is just barely too small (wasted near-miss).
    if next > 0.0 {
        if next <= post {
            score -= 6.0 * (1.0 - (post - next) / cap) * (0.5 + 0.5 * progress);
        } else {
            let miss = (next - post) / cap;
            score += 4.0 * miss * (1.0 - miss) * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (smooth reward, no hard branch).
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 8.0 + 4.0 * progress;
    }

    // New-bin candidate handling: empty bin gets a smooth opening cost that
    // shrinks with progress and with how poor existing fits are.
    if bin_residual == bin_capacity {
        let open_cost = 10.0 * (1.0 - 0.5 * progress)
            + 0.15 * mean_residual * (1.0 - progress)
            + 0.5 * open_bins_count as f64;
        score += open_cost;
    } else {
        // Prefer bins with residual below the mean (consolidating space).
        score += 0.1 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: residual class harmonic logic. Small post_residual is good.
    let pr = post_residual;
    if pr <= 10 {
        score -= 40.0;
    } else if pr <= 20 {
        score -= 20.0;
    } else if pr <= 30 {
        score -= 8.0;
    }

    // Dead-space penalty: unusable residual for typical item range (1..=100)
    // residual smaller than the smallest conceivable follow-up is wasted.
    if pr > 0 && pr < 5 {
        score += 60.0;
    }

    // Modulo harmonic classes on post_residual: multiples of 10 (capacity fractions)
    // leave room for standard-size items; reward them.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next item fits: residual remains usable
            let next_post = pr - next_item_size;
            score -= (next_post as f64).min(30.0) * 0.5;
        } else {
            // next item cannot use the leftover residual -> dead space risk
            score += (pr as f64) * 0.15;
        }
    }

    // Integer-division threshold on bin_residual: nearly-full bins are precious.
    let fill = bin_capacity - bin_residual;
    if fill >= bin_capacity * 3 / 4 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and
    // the item fits reasonably somewhere.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            let waste = bin_capacity as f64 - item_size as f64;
            score += 30.0 + waste * 0.5;
            // If no open bin fits tightly, opening a new bin may be fine:
            if fitting_bins_count == 0 {
                score -= 45.0;
            }
        } else {
            score -= 100.0; // first bin must be opened
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + 0.5 * progress);

    // Tie-break toward bins with residual close to mean (keeps distribution balanced)
    score -= 1.0 / (1.0 + ((post_residual as f64) - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: penalize if the next item cannot use the leftover gap.
    if next_item_size > 0 {
        if post_residual > 0 && next_item_size > post_residual {
            score += 12.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately expensive so we prefer packing
    // into open bins unless the fit is genuinely poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But under heavy bin-count pressure with a tight stream, opening
        // fresh bins can be preferable to fragmenting many bins.
        if open_bins_count as f64 > 8.0 + mean_residual * 0.15 {
            score -= 30.0;
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += (open_bins_count as f64).sqrt() * 1.5;

    // Prefer using bins whose residual is close to the item (tight fit).
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight nonlinearity
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // 2-step lookahead: strongly reward a perfect match for the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Relative to mean residual: bins with residual near mean are "normal";
    // favor bins whose post_residual deviates low relative to mean_residual
    if mean_residual > 0.0 {
        score += (post_residual as f64 - mean_residual) * 0.35;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is
    // very large (poor fit elsewhere) or many bins are already open
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size > bin_capacity * 7 / 10 {
            score -= 40.0;
        }
        if open_bins_count > 6 {
            score -= 10.0;
        }
        // early in stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: perfect fits are heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Fractional fill quality: reward high utilization of this placement.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill_ratio * fill_ratio;

        // Penalize small awkward residuals that likely become dead space.
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual < 20 {
            score += 10.0;
        }

        // Lookahead: if the next item fits exactly or well into post_residual, reward.
        if next_item_size > 0 && next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * next_fit;
            if next_item_size == post_residual {
                score -= 40.0;
            }
        } else if next_item_size > post_residual {
            // Next item won't fit here; slight penalty for stranding capacity.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by how well the
    // item would fill it and how many open bins already exist.
    if bin_residual == bin_capacity {
        let base_penalty = 80.0 + 2.0 * open_bins_count as f64;
        let fill = item_size as f64 / bin_capacity as f64;
        score += base_penalty * (1.5 - fill);
        // Late in the stream, be even more reluctant to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
    }

    // Global state coupling: if mean residual is large, prefer bins that
    // reduce fragmentation (i.e., bins with small residual before placement).
    let res_ratio = bin_residual as f64 / bin_capacity as f64;
    score += 10.0 * res_ratio * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post residual)
    let mut score = pr;

    // Smooth non-linear coupling: post residual interacts with stream progress.
    // Late in the stream, waste is penalized super-linearly; early, mild.
    let progress_coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress);
    score += 30.0 * progress_coupling;

    // Cubic dead-space penalty: residuals that are hard to reuse (small but nonzero)
    let dead = pr_norm * (1.0 - pr_norm);
    score += 10.0 * dead * dead;

    // Lookahead: if next item fits the post residual, reward this bin strongly
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let fit_quality = (next_item_size as f64) / (pr + 1.0);
        score -= 15.0 + 20.0 * fit_quality * (1.0 - progress);
    }

    // Penalize bins whose residual deviates from the mean (fragmentation avoidance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // New-bin candidate: neutral baseline with slight progress-dependent pull
    if bin_residual == bin_capacity {
        score = cap * (1.0 - 0.15 * progress) + 10.0 * progress_coupling;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: residues modulo small divisors.
    // Perfect-fill classes are heavily rewarded (dead space eliminated).
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // exact fill
    } else {
        // Reward residuals that are "harmonic" with common item sizes (divisible classes)
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 {
                score -= (m as f64) * 1.5;
            }
        }
        // Penalize awkward dead-space classes (prime-ish small leftovers)
        if pr < 10 {
            score += 60.0 * (10 - pr) as f64;
        }
    }

    // Lookahead: does the next item fit exactly / at all into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0; // perfect chained fill
        } else if next_item_size <= pr {
            score -= 40.0 * (next_item_size as f64 / cap);
        } else {
            score += 25.0; // next item won't fit here; wasted capacity
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin is crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 - 30.0 * progress;
        if open_bins_count == 0 {
            score -= 200.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 20.0;
        }
    }

    // Prefer packing into bins tighter than the mean residual (best-fit flavor)
    score -= (mean_residual - post_residual as f64).clamp(-cap, cap) * 0.5;

    // Slight preference for fuller bins overall
    score -= (1.0 - (post_residual as f64 / cap)) * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harsh penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to bin).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 10.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when few bins are open,
    // but relax pressure as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, scaled by open bins count and progress.
        score += 20.0 + 8.0 * open_bins_count as f64 * (1.0 - 0.5 * progress);
    } else {
        score -= 5.0;
    }

    // Prefer bins with residuals below the mean (consolidate large gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Tightness: reward small post_residual relative to capacity
    score -= 0.5 * (1.0 - post_residual as f64 / bin_capacity as f64) * 50.0;

    // 2-step lookahead: if the next item fits the post-residual exactly, strongly favor
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 300.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        // Next item fits inside remaining space: mild reward proportional to how well it fills
        let fill_after = next_item_size as f64 / post_residual as f64;
        score -= 60.0 * fill_after;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: penalize dead space a bit
        score += 30.0;
    }

    // Compare residual to mean residual across open bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it attractive only when existing fits are poor
    if bin_residual == bin_capacity {
        // Baseline: a fresh bin has full residual, but penalize opening extra bins
        // unless current open bins are crowded or fit is bad.
        let crowded = open_bins_count as f64 > 0.0 && mean_residual < item_size as f64;
        if !crowded {
            score += 80.0; // discourage opening when open bins are roomy
        } else {
            score -= 40.0; // encourage fresh bin when others are tight
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // fresh bin can absorb big follow-up items
        }
    }

    // Late in the stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fill: strong reward
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        // Creates dead space that no future item (>=1... realistically >=10 historically,
        // but sizes 1..100 here) can use; penalize moderately so usable alternatives win.
        score += 6.0;
    }

    // Lookahead chaining: reward bins whose leftover can host the next item,
    // tighter chains rewarded more.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 6.0 + 5.0 * (1.0 - slack);
    }

    // Last-chance bin: if this is the only open bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: add an opening premium so existing bins are preferred,
    // but relax it for large items (which leave a useful large residual anyway)
    // and when the next item cannot fit anywhere current.
    if bin_residual == bin_capacity {
        score += 12.0 - 0.06 * item_size as f64;
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            score += 5.0;
        }
        if open_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild coupling to global state: prefer bins whose residual is close to the
    // open-bin mean (keeps the residual profile homogeneous and packable).
    score += 0.03 * (mean_residual - post_residual as f64).abs();

    // Time horizon drift: late in the stream, closing bins out tightly matters more.
    score -= 3.0 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap; // normalized post residual
    let mrn = mean_residual / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post residual with stream progress:
    // early on, prefer tight fits less strongly; later, dead space hurts more.
    score += (prn * prn) * cap * (0.35 + 0.9 * t * t);

    // Interaction: post residual vs mean residual — avoid wasting space when
    // the bin is already below average utilization.
    score -= 12.0 * (prn - mrn) * (1.0 + t);

    // Lookahead: reward leaving space that can serve the next item smoothly.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let fit = (pr - nxt).abs();
        let fitn = fit / cap;
        score -= 20.0 * (-fitn * 8.0).exp();
        score += 6.0 * fitn * (1.0 - t);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * t;
    } else if fitting_bins_count > 1 {
        // slight penalty proportional to alternatives to keep tight fits preferred
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: mild penalty so it's chosen only when open
    // bins would create large dead space.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - t) + 10.0;
    }

    // Congestion term: many open bins -> encourage filling existing ones.
    score += 3.0 * (open_bins_count as f64).ln() * (1.0 - prn);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact fit: perfect placement, huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: residuals divisible by common
    // item classes (mod 10) are more likely reusable.
    let class = post_residual % 10;
    if post_residual > 0 {
        match class {
            0 => score -= 25.0,          // round residual, highly reusable
            5 => score -= 12.0,          // half-class still useful
            _ => score += (10 - class) as f64 * 0.8, // awkward remainder penalty
        }
    }

    // Dead space: residual too small for the minimum item (1..100 unknown,
    // use item_size as proxy for smallest useful chunk).
    if post_residual > 0 && post_residual < item_size {
        score += 40.0 + 0.5 * pr; // unusable sliver penalty
    }

    // Lookahead: reward residuals that exactly fit the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            // prefer leaving slack that itself lands in a good class
            if slack % 10 == 0 { score -= 30.0; }
            score += slack as f64 * 0.15;
        } else {
            // next item cannot follow here: mild penalty scaled by gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Fill-rate coupling: bins that are already mostly full get preference
    // (best-fit flavor beyond raw residual).
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill * fill * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Many open bins: encourage consolidation onto existing bins.
    if open_bins_count > 0 {
        score -= (open_bins_count as f64).ln() * 5.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // no open bin offers a decent fit (post_residual near capacity means
    // this is the fresh bin).
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 400.0 }
                      else if mean_residual < item_size as f64 * 1.2 { 200.0 }
                      else { 0.0 };
        // early in stream: opening fresh bins is cheap; late: consolidate
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap as f64 + 50.0 - urgency + progress * 120.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable -> heavy penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny sliver: nearly dead space
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 40 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward gaps that can still hold a typical item (usable residual).
    if post_residual >= next_item_size && next_item_size > 0 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure from many open bins: favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.4 + 0.6 * progress);

    // Prefer bins tighter than the average residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 40.0 };
        score += desperation + 10.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly (non-linear).
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Penalize small dead space quadratically relative to capacity.
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * tightness * 150.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next <= pr {
            let gap = pr - next;
            // Exact match is ideal: next item fills bin completely.
            if gap == 0.0 {
                score -= 120.0;
            } else {
                // Closer gap -> bigger reward, scaled by lookahead size.
                let gap_frac = gap / pr.max(1.0);
                score -= (1.0 - gap_frac) * 60.0 * (next / 100.0);
            }
        } else {
            // Next item won't fit here; penalize proportionally to overflow.
            let overflow = (next - pr) as f64;
            score += overflow * 0.4;
        }
    }

    // Compare against mean residual: prefer bins deviating favorably.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(50.0) * 0.5;
    } else {
        score += (pr - mean_residual) * 0.25;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Early stream: be more conservative, keep bins balanced.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * mean_residual * 0.05;

    // New-bin candidate: only open when existing bins are badly fragmented.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible future item can use.
    // Items are in [1, 100]; residual smaller than ~10 is nearly dead.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: reward if next item exactly fills the post_residual,
    // penalize if post_residual is just barely too small for next item.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap == 0.0 {
            score -= 25.0; // perfect chaining
        } else if gap > 0.0 && gap <= 5.0 {
            score -= 8.0; // good chance of chaining
        } else if gap < 0.0 && gap >= -5.0 {
            score += 10.0; // next item barely doesn't fit -> dead space risk
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        if post_residual <= 5 {
            score -= 15.0; // near-perfect last-chance fit
        }
    }

    // New-bin candidate handling: opening a new bin should generally be discouraged,
    // but attractive when all open fits are poor (high post_residual) or few bins fit.
    if bin_residual == bin_capacity {
        score += 35.0; // base cost of opening a new bin
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        } else if fitting_bins_count == 1 && post_residual_proxy(item_size, bin_capacity) > 30 {
            // existing best fit is poor; new bin is fine
            score -= 25.0;
        }
        // Late in the stream, avoid opening bins that will be nearly empty.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.85 {
            score += 30.0 * progress;
        }
    }

    // Mild preference for bins below mean residual (balance the pool),
    // keeping large-residual bins flexible.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Slight preference for using more-open-bins states to consolidate early.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

#[inline]
fn post_residual_proxy(item_size: u32, bin_capacity: u32) -> f64 {
    (bin_capacity.saturating_sub(item_size)) as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: wasted space after placement
    let mut score = pr;

    // Smooth non-linear reward for tight fits: cubic decay of residual weight
    let tightness = 1.0 - (pr / cap).powi(3);
    score -= 18.0 * tightness * item_size as f64 / cap;

    // Progress-coupled residual penalty: later in stream, dead space costs more
    score += (pr / cap) * (0.5 + 2.5 * progress * progress) * 10.0;

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item can use the post-residual exactly or well
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = pr - next_item_size as f64;
        score -= 12.0 * (1.0 - gap / cap) * (0.4 + 0.6 * progress);
    } else if next_item_size > 0 {
        // penalize residuals too small for the next item
        score += 6.0 * (1.0 - pr / cap) * (0.5 + 0.5 * progress);
    }

    // New-bin candidate handling: prefer opening a bin early (exploration),
    // penalize it later when consolidation matters; also if other bins fit well
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score = pr - 20.0 * (1.0 - progress) + 30.0 * progress * (1.0 + open_f / 50.0);
        if fitting_bins_count > 1 {
            score += 15.0 * (mean_residual / cap).max(0.0);
        }
    }

    // Mild preference for bins below mean residual (keep residuals balanced)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "usable" space classes.
    // Small residuals that are multiples of common item sizes (10,20,25,50) are fine;
    // awkward residues (1..9, 11..19 gaps) are dead space -> penalize.
    let r = post_residual;
    if r > 0 {
        let dead = if r % 10 == 0 { 0.0 }
            else if r % 25 == 0 { 2.0 }
            else if r % 5 == 0 { 6.0 }
            else { 14.0 };
        score += dead * (r as f64 / bin_capacity as f64).sqrt();
    }

    // Perfect fit reward
    if r == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 55.0;
        } else if next_item_size <= r {
            // next item fits: residual after that placement, harmonic class again
            let r2 = r - next_item_size;
            let bonus = if r2 % 10 == 0 { 18.0 } else if r2 % 5 == 0 { 9.0 } else { 2.0 };
            score -= bonus;
        } else {
            // next item does NOT fit here: this bin will be closed anyway,
            // penalize less if residual is small (well-filled)
            score += (r as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base handicap so existing bins with decent fits win.
        score += 30.0;
        // But if many bins are open and mean residual is small (fragmented), new bin attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0
            + (mean_residual / bin_capacity as f64) * 10.0
            + progress * 5.0;
        // If item is large and would leave awkward residual in a fresh bin, discourage more.
        let pr = bin_capacity - item_size;
        if pr > 0 && pr % 10 != 0 {
            score += 8.0;
        }
    }

    // Mild preference for tighter existing bins (best-fit amplification)
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Coupling: dead space is worse when many bins are already open.
    score += post_residual as f64 * (open_bins_count as f64 * 0.03);

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && (post_residual as u32) > 0 && (next_item_size as u32) > post_residual {
        score += 8.0; // next item won't fit here; dead space likely
    }

    // Pressure against opening new bins when few are open relative to stream length.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress + open_bins_count as f64 * 2.0;
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits into the post residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // exact chain fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
