    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Prefer tighter bins relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slightly discourage opening new bins late in the stream when fits exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize dead space that can't fit typical small items (<= 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // tiny dead space is wasted capacity
    } else {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty scaled by how close it was.
        score += 8.0;
    }

    // Global state: prefer filling existing bins when many are open.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    if bin_residual < bin_capacity {
        score -= pressure * 3.0;
    }

    // Time horizon: early in the stream, be conservative (favor new bins less);
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus early-stream discount, late-stream penalty.
        score = 70.0 - 35.0 * progress;
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 10.0; // fresh bin is good for the next item too
        }
    } else {
        // Existing bin: more attractive as stream progresses.
        score -= 10.0 * progress;
    }

    // Discourage leaving residuals just below common item sizes (unusable gaps).
    for gap in [11u32, 26, 51, 76] {
        if post_residual + 1 == gap {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.8 * progress * post_norm) + 45.0 * progress * post_norm * post_norm;

    // Penalize residuals that cannot fit typical future items, smoothly
    let dead = (post - next_item_size as f64).max(0.0) / cap;
    score += 30.0 * dead * dead * (1.0 + progress);

    // Reward tight fits (small post_residual relative to capacity)
    score -= 25.0 * (1.0 - post_norm) * (1.0 - post_norm) * (1.0 - 0.5 * progress);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: prefer it only when open bins are congested
    if bin_residual == bin_capacity {
        let congestion = if open_bins_count > 0 { open_bins_count as f64 / (1.0 + open_bins_count as f64) } else { 0.0 };
        score += 70.0 - 40.0 * congestion - 20.0 * progress;
    }

    // Mild preference for balancing residuals across open bins
    score += 0.3 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // residue classes (multiples of 10, or large enough for mid-size items)
    // are rewarded; awkward dead-space classes are penalized.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // Dead-space penalty grows for small, awkward leftovers.
        if pr < 10 {
            score += (10 - pr) as f64 * 2.0;
        } else {
            // Reward exact decade alignment (harmonic with typical sizes).
            if class == 0 {
                score -= 6.0;
            } else if class <= 2 {
                score += 3.0;
            }
        }
        // Large residuals are flexible: reward proportionally.
        if pr >= 50 {
            score -= (pr - 50) as f64 * 0.05;
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack <= 5 {
                score -= 12.0;
            } else {
                score -= (slack as f64).sqrt() * 0.5;
            }
        } else {
            // Next item won't fit here; penalize slightly less if post_residual
            // is tiny anyway (bin is effectively closed).
            if pr >= next_item_size - 10 && pr > 0 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin wastes current residual mass.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing bins are highly fragmented or
        // this is early in the stream (building a diverse pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - bin_residual as f64).abs();
        let waste = mean_residual * open_bins_count as f64 / cap;
        // New bin cost decreases if open bins are nearly full (low mean residual).
        score = cap - item_size as f64 * 0.5 + waste * 4.0 - fragmentation * 0.3
              - (1.0 - progress) * 5.0;
        // Exact-fit pressure: if item is large, new bin is natural.
        if item_size >= bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Mild fullness gradient: tighter fits (small post_residual) always better.
    score += (post_residual as f64 / cap) * 8.0;

    // Harmonic threshold on item_size: items in "hard" classes (prime-ish,
    // awkward sizes) should be packed more aggressively into existing space.
    let hard = (item_size % 7 == 1) || (item_size % 13 == 3);
    if hard && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Strict dead-space avoidance ---
    // A post_residual that is too small to hold even the smallest plausible
    // item is pure dead space: penalize it quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Moderate small gaps (10..25) are half-dead: mild quadratic penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 0.8;
    }

    // --- Reward exact / near-exact fits ---
    if post_residual == 0 {
        score -= 50.0; // perfect fit: bin closed, zero waste
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // --- Reward leaving a gap that the lookahead item can use ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if the gap then becomes near-perfect for the next item.
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the known next item: dead-space risk.
        score += 10.0;
    }

    // --- Open-bin pressure ---
    // With many open bins, prefer consolidating into existing ones rather
    // than opening new bins; scale pressure with progress.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 6.0 * progress);
    score += bin_pressure;

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item fits nowhere
        // well: it's the last chance, or all fits are terrible.
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: must open
        } else if fitting_bins_count == 1 && post_residual >= 0 {
            // Only one fitting bin: opening a fresh bin is reasonable unless
            // that bin gives a near-perfect fit.
            if post_residual == bin_capacity - item_size && (bin_capacity - item_size) > 30 {
                score += 5.0; // the existing bin fit is loose, prefer new bin
            } else {
                score += 15.0;
            }
        } else {
            // Plenty of alternatives: new bin should lose.
            score += 35.0 + 5.0 * fitting_bins_count as f64;
        }
        // Late in the stream, slightly discourage opening bins that will
        // barely be used.
        if progress > 0.9 {
            score += 10.0 * progress;
        }
    }

    // --- Mean-residual coupling ---
    // If this bin's residual is far below the mean, it is a "junk drawer";
    // filling junk drawers with big items is good, but leaving them is bad.
    let dev = mean_residual - bin_residual as f64;
    if dev > 15.0 {
        // This bin is tighter than average: filling it consolidates waste.
        score -= 6.0;
    } else if dev < -15.0 {
        // This bin is looser than average: prefer saving it for large items.
        if item_size < 40 {
            score += 5.0;
        }
    }

    // --- Last-chance bonus ---
    // If this is the only bin that fits the item, using it avoids opening
    // a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact fill of both items
        } else if post_residual > next_item_size {
            let two_step_residual = post_residual - next_item_size;
            // prefer small leftover after the pair
            score -= 25.0 * (1.0 - two_step_residual as f64 / bin_capacity as f64);
            if two_step_residual < 10 {
                score -= 15.0; // near-perfect packing pair
            }
        } else {
            // next item won't fit here; penalize leaving large unusable gaps
            let gap = next_item_size - post_residual;
            score += 8.0 + 0.25 * gap as f64;
        }
    }

    // Tight fit reward relative to current residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Penalize residuals far from mean (avoid fragmenting well-balanced bins)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer compacting into existing bins when many are open
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        score += 40.0 + 0.4 * mean_residual;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // fresh bin can host a clean pair
        }
    }

    // Late-stream compaction: tighten up as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits strongly (non-linearly).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Reward near-perfect packing (post_residual <= 10 is mostly dead space otherwise).
    if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Lookahead: bonus if the next item fits in the post-residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            // Penalize leaving a gap just bigger than useful sizes.
            let waste_ratio = post_residual as f64 / bin_capacity as f64;
            if waste_ratio > 0.05 && waste_ratio < 0.30 {
                score += 6.0 * waste_ratio;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is expensive early, cheaper late.
    if is_new_bin {
        let open_cost = 25.0 - 12.0 * progress;
        // If many bins can fit the item, discourage opening a new one.
        let crowding = if fitting_bins_count > 1 { 10.0 + 3.0 * (fitting_bins_count as f64) } else { 0.0 };
        score += open_cost + crowding;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += 0.15 * mean_residual;
    } else {
        // Favor bins whose residual deviates below the mean (consolidate fullness).
        let dev = mean_residual - bin_residual as f64;
        score -= 0.10 * dev;
        // Mild penalty for spreading across too many open bins early on.
        score += 0.02 * open_bins_count as f64 * (1.0 - progress);
    }

    // Time horizon: late in the stream, prioritize minimizing dead space aggressively.
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Normalized post residual and fill ratio
    let pr_norm = pr / cap;
    let fill = 1.0 - pr_norm;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, avoid creating tiny dead space; later, tighten more aggressively.
    let dead_space_penalty = (pr_norm * (1.0 - pr_norm)).powi(2) * 40.0 * (1.0 - progress);
    score += dead_space_penalty;

    // Reward high fill ratio, amplified smoothly as stream progresses
    score -= fill * fill * 10.0 * (0.5 + progress);

    // Perfect fit bonus (smooth, no hard cutoff)
    let perfect = (1.0 - pr_norm).powi(8);
    score -= perfect * 25.0;

    // Last-chance bin: strongly favor using it if it fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    // Penalize opening a new bin when many open bins could take the item.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * (open_bins_count as f64).ln().max(0.0);
        // But if the item is large relative to mean residual of open bins,
        // a fresh bin may be better: soften the penalty.
        let spread = (mean_residual - it).abs();
        score -= (spread / cap).powi(2) * 20.0;
    } else {
        // Mild penalty when this bin's residual deviates strongly from the mean,
        // encouraging balanced residual distribution across bins.
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += dev * dev * 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        let gap_norm = gap / cap;
        score -= (1.0 - gap_norm).powi(3) * 20.0;
    } else if next_item_size > post_residual as u32 && next_item_size > 0 {
        // Next item won't fit here anyway; slightly penalize leaving a mid-range residual
        let prn = pr / cap;
        score += prn * (1.0 - prn) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic-class logic: classify post_residual into residue classes mod 10
    // (a proxy for "which size classes could still fill this gap").
    let post = post_residual as u32;
    let residue = post % 10;
    let class = post / 10;

    // Dead space penalty: residuals in awkward classes (1..9 mod 10 with small class)
    // are hard to fill when sizes are 1..100; reward residuals divisible by common sizes.
    if post > 0 {
        let mut fill_bonus = 0.0;
        // reward residuals divisible by small harmonic sizes (2,4,5,10,20,25,50)
        if post % 2 == 0 { fill_bonus -= 1.5; }
        if post % 4 == 0 { fill_bonus -= 1.0; }
        if post % 5 == 0 { fill_bonus -= 1.5; }
        if post % 10 == 0 { fill_bonus -= 2.0; }
        if post % 20 == 0 { fill_bonus -= 1.5; }
        if post % 25 == 0 { fill_bonus -= 2.0; }
        if post % 50 == 0 { fill_bonus -= 2.5; }
        // residue class penalty: residues 1,3,7,9 (coprime to 10) are worst
        let bad_residue = matches!(residue, 1 | 3 | 7 | 9);
        if bad_residue { fill_bonus += (residue as f64) * 0.8; }
        // very small unusable gaps (class 0, i.e. post < 10)
        if class == 0 { fill_bonus += 3.0; }
        score += fill_bonus;
    }

    // Perfect fit reward
    if post == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0;
        } else if next_item_size <= post {
            // next item fits: penalize proportionally to leftover slack after next
            let slack2 = post - next_item_size;
            score -= 6.0;
            score += (slack2 as f64) * 0.15;
        } else {
            // next item won't fit here: mild penalty scaled by overshoot
            score += ((next_item_size - post) as f64).min(40.0) * 0.12;
        }
    }

    // Prefer tight bins over loose bins when many bins are open (keep mean residual low).
    let tightness = (bin_residual as f64) / (bin_capacity as f64);
    if open_bins_count > 2 {
        score += (tightness - (mean_residual / bin_capacity as f64)).max(0.0) * 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to capacity or existing fits are poor.
    if bin_residual == bin_capacity {
        let load_factor = (item_size as f64) / (bin_capacity as f64);
        // opening a fresh bin is expensive early; cheaper later in the stream
        let stream_pos = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 14.0 - 6.0 * stream_pos;
        // if item is large, a fresh bin is reasonable
        if load_factor > 0.6 { new_bin_penalty -= 8.0; }
        if load_factor > 0.8 { new_bin_penalty -= 6.0; }
        // if no open bin can fit, this call is forced anyway; neutralize
        if fitting_bins_count == 0 { new_bin_penalty = 0.0; }
        score += new_bin_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        let dead = post / cap; // fraction wasted
        // Penalize disproportionately when gap is too small for typical items (1..100 unknown, assume >=10-ish useful threshold ~ but stay grounded in observed stream)
        let min_useful = if next_item_size > 0 { next_item_size.min(80).max(10) as f64 } else { 10.0 };
        if post < min_useful {
            score += dead * 40.0 + (min_useful - post) * 1.5; // unusable sliver penalty
        } else {
            score -= dead * 6.0; // larger useful residual is fine
        }
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Reward tight fits relative to residual (small waste ratio)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are underutilized
        score += pressure * 8.0 + mean_residual * 0.3;
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead: prefer leaving a gap that fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0; // gap blocks the lookahead item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post-residual matches the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 80.0; // exact 2-step chain
        }
    } else if next_item_size > 0 {
        // penalize residuals that dead-end relative to lookahead
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Tightness relative to mean residual: prefer tighter-than-average bins
    score -= 1.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin, unless existing residuals are large/fragmented
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / bin_capacity as f64 - 0.5).max(0.0);
        score = bin_capacity as f64 * 0.6
            + open_f * 2.0
            + progress * 20.0
            - fragmentation * 40.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 25.0; // fresh bin pairs well with upcoming large item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Exact or near-exact fit is extremely desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    }

    // Dead space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward heavily.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 14.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize more if the leftover becomes dead space.
            score += 6.0 + 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins; encourage consolidation when bins are plentiful.
    let bin_pressure = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 10.0 * bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // Relative fullness compared to mean residual: prefer bins below mean residual (fuller bins).
    score += 0.25 * (post_residual as f64 - mean_residual);

    // New-bin candidate handling: prefer a fresh bin only when no open bin offers a decent fit
    // (i.e., when the item would leave a large awkward residual) or late in the stream is irrelevant.
    if bin_residual == bin_capacity {
        // Baseline attractiveness of a fresh bin: its residual is full capacity.
        // Make it less attractive than a decent fit but better than a terrible one.
        score = 0.55 * bin_capacity as f64
            - 8.0 * tight
            + 10.0 * bin_pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Fresh bin can always take the next item alongside.
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative anyway (shouldn't happen, but safe)
        }
    }

    // Time horizon: early in the stream, be slightly more willing to open new bins
    // (long future benefits flexibility); late, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress); // fresh bins cheaper early
    } else {
        score -= 10.0 * progress * tight; // late: prefer fullest bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let mean_norm = mean_residual / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let poly = norm_pr * norm_pr * (1.0 - p) + norm_pr * p * (1.0 - norm_pr);
    score += 25.0 * poly;

    // Reward tight fits, stronger as the stream progresses
    let tight = 1.0 - norm_pr;
    score -= 40.0 * tight * tight * (0.5 + p);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let waste = (next_item_size as f64 - pr) / cap;
        score += 30.0 * waste * (1.0 - norm_pr) * (1.0 + p);
    }

    // Reward when this residual can still host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 15.0 * slack * (1.0 - slack) * (1.0 - p);
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + p);
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).ln_1p() * (1.0 - p);
    }

    // Nudge toward bins deviating from mean residual (avoid uniform thinning)
    score += 10.0 * (norm_pr - mean_norm).abs() * (1.0 - p);

    // Mild penalty for opening new bins late in the stream
    score += 8.0 * p * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Classify post_residual into harmonic bands via integer division thresholds
        // Bands: (0,10] tiny, (10,30] small, (30,50] medium, (50,100] large
        let band = post_residual / 10; // 0..10 harmonic class
        let band_penalty = match band {
            0 => -50.0,          // almost perfect fit
            1 => -10.0,          // good
            2 | 3 => 0.0,        // neutral
            4 => 15.0,           // medium dead space
            _ => 30.0,           // large leftover, wasteful
        };
        score += band_penalty;

        // Modulo coupling: residuals divisible by common item sizes are reusable
        let mut reusable = false;
        for m in [10u32, 20, 25, 40, 50] {
            if post_residual >= m && post_residual % m == 0 {
                reusable = true;
                break;
            }
        }
        if reusable {
            score -= 12.0;
        }

        // Lookahead: does next item fit into post_residual?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // exactness of lookahead fit
                let gap = post_residual - next_item_size;
                score -= (20.0 - (gap as f64).min(20.0)) * 0.8;
            } else {
                // next item won't fit here: penalize more if this bin is last chance
                score += 8.0;
            }
        }

        // Last-chance bin: strongly prefer using it over opening a new bin
        if fitting_bins_count == 1 {
            score -= 35.0;
        }

        // New-bin candidate handling: empty bin gets high base cost unless few bins open
        if bin_residual == bin_capacity {
            score += 25.0 + 5.0 * (open_bins_count as f64).max(1.0).log2();
        }

        // Prefer bins with residuals close to the item (tight packing)
        let tightness = (bin_residual - item_size) as f64;
        score += 0.05 * tightness;

        // Mean residual coupling: avoid degrading bins far below the mean
        score += 0.1 * (mean_residual - pr).abs();

        // Early stream: encourage consolidation into few bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.3 && bin_residual != bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps (below min item size 1..~15) are worthless.
    if post_residual > 0 && post_residual < 12 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: many open bins -> discourage spreading, prefer tight fills.
    let pressure = (open_bins_count as f64) / (1.0 + total_items as f64 / 20.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 10.0;
    }
    // If next item is bigger than post residual but would fit a fresh bin, mild penalty for wasting space.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 && post_residual < 25 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.1;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 40.0 } else { 10.0 + 20.0 * (1.0 - fit_ratio) };
        score += desperation.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward perfect chaining with the next item ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;

        // Exact match: post_residual == next_item_size is ideal.
        let match_gap = (post - next).abs();
        if match_gap < 0.5 {
            score -= 60.0; // perfect chain bonus
        } else if next <= post {
            // Next item fits exactly in what's left: reward proportionally.
            score -= 40.0 * (next / post) * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize leaving dead space relative to next size.
            score += 0.25 * (next - post).min(80.0) as f64;
        }

        // Small post residual that neither current nor next item can use = dead space.
        if post > 0.0 && post < next.min(item_size as f64) {
            score += 15.0 * (1.0 - post / 100.0);
        }
    }

    // --- Relative to mean residual: prefer bins whose post_residual tracks the mean ---
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (post_f - mean_residual).abs() / mean_residual;
        score += 8.0 * dev.min(2.0);
    }

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing fit is terrible
        // (large dead space would be created) or many bins already open with slack.
        let dead_space = (bin_residual - item_size) as f64;
        let poor_fit_penalty = if post_f > 0.0 && post_f < 10.0 { 0.0 } else { 0.0 };
        // Base cost of a fresh bin; relax late in the stream / when open bins are slack.
        let mut new_bin_cost = 30.0;
        if next_item_size > 0 && (next_item_size as f64) >= dead_space {
            // Fresh bin can chain with next item: discount.
            new_bin_cost -= 20.0;
        }
        if mean_residual > 50.0 {
            // Open bins are quite full already; new bin more acceptable.
            new_bin_cost -= 10.0;
        }
        score += new_bin_cost + 0.1 * open_bins_count as f64 + poor_fit_penalty;
    } else {
        // Existing bin: mild preference for tighter bins (smaller residual already).
        score -= 0.05 * (bin_capacity - bin_residual) as f64;
    }

    // Slight global tightening pressure as stream progresses.
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Dead-space penalty for small, awkward leftovers (unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: reward leaving a residual that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item cannot fit here; mild penalty proportional to wasted potential.
            score += 3.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is large
    // or current open bins are crowded (high mean residual / many bins).
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = crowding * (open_bins_count as f64).ln().max(1.0);
        // Prefer new bin when item is big and pressure is high; otherwise discourage.
        score += 45.0 - 20.0 * (item_size as f64 / bin_capacity as f64) - 25.0 * pressure.min(2.0) - 10.0 * progress;
        // Empty bin leaves full flexibility for the future; slight reward early on.
        score -= 5.0 * (1.0 - progress);
    } else {
        // Slight preference for filling bins that are already partially loaded.
        score -= 0.05 * (bin_capacity - bin_residual) as f64;
    }

    // Global state: when many bins are open, prefer consolidation into existing bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Mean-residual alignment: favor bins whose residual is close to the mean
    // (balanced packing) but avoid bins far above mean residual (hoarding space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth polynomial coupling: reward small post_residual more as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (40.0 + 60.0 * progress);
    // Penalize dead space that can't fit the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += (ns - pr) * (1.0 + 2.0 * progress);
        } else {
            score -= 8.0 * (1.0 - (pr - ns) / cap);
        }
    }
    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Mild penalty for proliferating bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (1.0 - mean_residual / cap).abs();
    // Smooth non-linear waste penalty
    score += 10.0 * norm_pr * norm_pr * norm_pr;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 quantizes "dead space quality"
    let post_class = post_residual % 10;
    // Residues that pair well with small items (multiples of 10, 20, 25, 50) are rewarded
    let harmonic_bonus: f64 = match post_class {
        0 => -18.0,
        5 => -6.0,
        2 | 8 => -3.0,
        _ => 2.0,
    };
    score += harmonic_bonus;

    // Integer-division thresholds: post_residual bucketed by capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        score -= 30.0; // near-perfect, unusable sliver but tight fit
    } else if post_residual <= quarter {
        score -= 8.0;
    } else if post_residual <= half {
        score += 0.0;
    } else if post_residual <= three_quarter {
        score += 10.0;
    } else {
        score += 22.0; // large leftover: wasteful placement
    }

    // Lookahead coupling: reward when post_residual can host next item exactly / closely
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 35.0;
            } else if gap <= 10 {
                score -= 15.0;
            } else if gap <= 25 {
                score -= 5.0;
            }
            // next item's own harmonic class matches post class
            if (post_residual % 10) == (next_item_size % 10) && post_residual >= next_item_size {
                score -= 4.0;
            }
        } else {
            // next item cannot use this bin's remainder: penalize proportional to shortfall
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // last item: prefer tightest possible packing
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // more alternatives: mild penalty to encourage discrimination
        score += (fitting_bins_count.min(8) as f64) * 1.5;
    }

    // New-bin candidate logic: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let poor_fit = mean_residual < item_size as f64 * 0.5;
        if poor_fit || open_bins_count == 0 {
            score -= 40.0; // fresh bin justified
        } else if crowded > 4.0 && progress > 0.25 {
            score -= 12.0; // many nearly-full bins: spread out
        } else {
            score += 30.0; // prefer existing bins early on
        }
    }

    // Mean-residual drift: prefer bins deviating from the mean toward fullness
    let deviation = mean_residual - bin_residual as f64;
    score += deviation * 0.15;

    // Progress-scaled tightness pressure: as stream advances, demand tighter fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.25 * progress;

    // Tie-breaker: slight preference for larger item into this bin (high fill ratio)
    score -= (item_size as f64 / bin_capacity as f64) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no plausible item (>=1, but
    // practically small unusable slivers) can fill are heavily penalized.
    if post_residual > 0 {
        // Dead space = gap too small for the lookahead item or tiny slivers.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Slivers below the minimum realistic item size are pure waste.
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual <= 20 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: discourage proliferating bins when few are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // in the "useful" direction (larger residual absorbs big items better).
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        } else if post_residual as f64 > mean_residual {
            score += 15.0; // existing bins fit fine; don't open a new one
        } else {
            score += 5.0;
        }
        // Early in the stream, opening bins is cheaper.
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead synergy: if the next item exactly fits the post-residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly prefer bins where the item fills them exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post_residual, this placement sets up a perfect chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves a 2-step remainder: mild reward,
            // scaled by how tight the 2-step fit is.
            let two_step_remainder = post_residual - next_item_size;
            score -= 150.0 * (1.0 - two_step_remainder as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize proportional
            // to how much dead space is created relative to mean residual.
            score += 40.0 + 0.5 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Tightness reward: prefer bins where the item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 80.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < item_size {
        score -= 120.0;
    }

    // Penalize placing small items into large-residual bins early in the
    // stream when many bins are open (preserve big space for big items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if item_size < 30 && bin_residual > 60 {
        score += 60.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize dead space: residuals too small for likely future items
    // (items are >= 1, but typical useful chunks are larger).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves a gap: mild reward scaled by fit quality
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            let overflow = (next_item_size - post_residual) as f64;
            score += 6.0 * (overflow / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: an empty bin is attractive when existing
    // residuals are fragmented or the fit here is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, opening bins is cheap; later, prefer reusing.
        let open_bias = 20.0 * (1.0 - progress) - 10.0 * progress;
        // If current fit is bad (large post_residual), new bin looks better.
        let poor_fit = (post_residual as f64 / bin_capacity as f64) * 30.0;
        // If many bins are open with big mean residual, discourage new bins.
        let glut = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).min(10.0);
        score = score - open_bias - poor_fit + glut;
    } else {
        // Slight preference for fuller bins (smaller residual) among open bins.
        score += (bin_residual as f64 / bin_capacity as f64) * 8.0;
        // Spread load when many bins are open: prefer bins below mean residual
        // to balance, unless tight fit dominates.
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        }
    }

    // Time-horizon modulation: late in the stream, consolidation matters more,
    // so tighten the reward for small post_residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: waste after placement, softly squashed to keep competition smooth.
    let mut score = norm_pr * (1.0 + 0.35 * norm_pr) * cap;

    // Smooth polynomial coupling of waste with stream progress:
    // later in the stream, larger dead space is punished more aggressively.
    let coupling = 1.0 + 1.2 * progress * (1.0 - progress) + 0.8 * progress * progress;
    score *= coupling;

    // Non-linear interaction: post residual vs. how well the next item would reuse it.
    if next_item_size > 0 {
        let fit_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let reuse = norm_next * (1.0 - (norm_pr - norm_next).abs());
        // Reward bins whose residual is near the next item's size (smooth basin).
        score -= 8.0 * reuse * (0.5 + 0.5 * progress);
        // Penalize leaving residual that fits nothing next (smooth via exp).
        score += 6.0 * (1.0 - fit_next) * (norm_pr * (1.0 + norm_pr));
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + 0.5 * progress);
    }

    // Scarcity pressure: few fitting bins -> favor this one proportionally.
    let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
    score -= 5.0 * scarcity * norm_item;

    // Deviation from mean residual: prefer bins that keep residual distribution tight,
    // with a non-linear (quadratic) penalty scaled by progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * (0.5 + progress);

    // Mild preference for tighter bins overall (waste minimization pressure).
    score += 2.0 * (1.0 - norm_item) * (norm_pr - 0.5 * norm_item);

    // New-bin candidate: make it attractive only when it truly beats a bad fit —
    // empty bin has huge post_residual, so its base is already high; add a
    // progress-scaled bonus so late in the stream consolidation is preferred.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (multiples of 25 / 20) are more reusable -> reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact capacity-fraction classes: 0, cap/4, cap/2, 3cap/4, cap
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == 0 {
        score -= 30.0; // perfect fit, no dead space
    } else if post_residual == quarter || post_residual == half || post_residual == 3 * quarter {
        score -= 12.0;
    } else if post_residual % 10 == 0 {
        score -= 5.0; // multiple of 10: still fairly reusable
    } else {
        score += 8.0; // awkward residual
    }

    // Modulo coupling: does next_item_size divide into post_residual nicely?
    if next_item_size > 0 && next_item_size <= post_residual {
        let fits_next = (post_residual % next_item_size) as f64;
        score -= 6.0 * (1.0 - fits_next / cap);
        // Harmonic divisibility: next item divides post_residual exactly
        if post_residual % next_item_size == 0 {
            score -= 10.0;
        }
        // Integer-division threshold: how many copies of next item fit after
        let copies = post_residual / next_item_size.max(1);
        score -= 2.0 * copies as f64;
    } else if next_item_size > 0 {
        // Next item cannot use this residual at all -> residual is dead weight
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has large residual; penalize
    // opening a new bin unless the current item is large relative to residual
    // or all open bins would leave terrible residuals.
    if bin_residual == bin_capacity {
        // empty candidate: baseline penalty so it's only chosen when good
        score += 20.0;
        // large items pack better in fresh bins
        if item_size >= half {
            score -= 18.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // many open bins with high mean residual -> don't add more
        if mean_residual > 0.4 * cap && open_bins_count > 2 {
            score += 15.0;
        }
    } else {
        // Existing-bin tightness reward: prefer bins whose residual is close
        // to the item (low waste ratio).
        let waste = (bin_residual - item_size) as f64;
        score += 5.0 * (waste / cap);
        // Harmonic class of item: items in the (cap/3, cap/2) band are hard
        // to pair; give them tighter packing priority.
        if item_size > bin_capacity / 3 && item_size < half {
            score -= 4.0;
        }
    }

    // Mild exploration term via modulo classes of step index (deterministic).
    let phase = (step_index % 7) as f64;
    score += 0.5 * phase.sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual can still host the next item (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap that cannot fit the next item: mild extra penalty scaled by gap size.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over spreading out; makes new-bin candidate less attractive.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate adjustment: an empty bin has large post_residual which
    // is naturally high-scoring; add fixed penalty so it only wins when all
    // open bins are truly bad (their scores inflated by dead-space terms).
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening fresh bins is cheaper (fewer future regrets).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    } else {
        // Prefer tighter existing fits: closeness of item to residual.
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 10.0;
        // Bins below mean residual (already loose) are slightly deprioritized.
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base reward for tight fits (small post_residual).
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: reward exact match of next_item_size into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: bin becomes exactly full
        } else if post_residual > next_item_size {
            let rem = post_residual - next_item_size;
            // penalize leftover dead space after the lookahead placement
            score += rem as f64 * 0.8;
            if rem <= 10 {
                score -= 15.0; // near-perfect chain
            }
        } else {
            // next item cannot follow into this bin's remainder
            score += 12.0;
            // but if remainder is very small, it's still fine (usable dead space minimized)
            if post_residual <= 5 {
                score -= 20.0;
            }
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new empty bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual as f64 > mean_residual {
            score += 15.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // new bin can chain with next item
        }
    }

    // Late in stream, consolidate more aggressively (fewer wasted bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize dead space that nothing can ever use (min item size 1)
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.4) * 0.15;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty scaled by how badly it misses
            score += 5.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance bonus: this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer fuller bins when many bins are open (reduce bin count pressure)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Global state coupling: if mean residual is high, prefer bins below mean (consolidate)
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Time horizon: early in the stream, be more willing to open new bins / spread;
    // later, be conservative and pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * (1.0 - progress);

    // New-bin candidate handling: neutral-ish baseline, but avoid opening new bins
    // when a decent fit exists (post_residual small means good fit in an open bin).
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64 * 0.5 - 20.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    // Normalized stream progress
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Smooth polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Quadratic dead-space penalty, stronger late in the stream
    let quad = x * x * (0.5 + 1.5 * progress);
    score += quad * cap;

    // Cubic interaction: reward very small residuals (tight fits) more as stream advances
    let tight = (1.0 - x) * (1.0 - x) * (1.0 - x);
    score -= tight * (2.0 + 3.0 * progress) * cap * 0.1;

    // Smooth coupling with mean residual: prefer bins whose residual deviates favorably
    let dev = (pr - mean_residual) / cap;
    score += dev * (1.0 + progress) * 2.0;

    // Lookahead: penalize residual that cannot fit next item, smoothly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            let gap = (ni - pr) / cap;
            score += gap * gap * cap * (1.0 + 2.0 * progress);
        } else {
            let room = (pr - ni) / cap;
            score -= room * 0.5 * (0.5 + progress);
        }
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 4.0 * progress;
    }

    // Mild penalty for proliferating bins as stream progresses
    score += (open_bins_count as f64).ln().max(0.0) * (0.5 * progress);

    // New-bin candidate handling: neutral baseline, slightly penalized early, competitive late
    if bin_residual == bin_capacity {
        let new_bin_bias = 1.5 - 2.5 * progress;
        score += new_bin_bias;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    // Small post_residuals that are "wasted" get penalized via class weight.
    let class = (post_residual % 10) as f64;
    score += class * 0.35;

    // Reward near-perfect fits: post_residual in small classes (0..=3) are prime targets.
    if post_residual <= 3 {
        score -= 12.0;
    } else if post_residual <= 7 {
        score -= 6.0;
    }

    // Integer-division threshold: residual that can hold common medium sizes
    // (>= 25) is more valuable; penalize leaving such usable space when a
    // poor fit would otherwise occur.
    if post_residual / 25 >= 1 && post_residual < 25 {
        // unreachable guard, kept for harmonic clarity
        score += 0.0;
    }
    let usable_quarters = post_residual / 25;
    score -= usable_quarters as f64 * 4.0;

    // Next-item coupling: if the next item would fit into the post_residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // extra reward for exact harmonic match (post_residual == next_item_size)
        if post_residual == next_item_size {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to wasted chain potential.
        score += (next_item_size as f64 - post_residual as f64) * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bins should only win when the fit here
    // is bad (large post_residual dead space). Penalize opening a new bin.
    if bin_residual == bin_capacity {
        score += 20.0 + post_residual as f64 * 0.5;
        // If current fit is genuinely bad (post_residual small but nonzero,
        // creating dead space), soften the new-bin penalty.
        if post_residual > 0 && post_residual <= 5 {
            score -= 18.0;
        }
    }

    // Stream progression: late in the stream, prefer tighter packing (lower post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: when open bins are already loose, discourage
    // adding more loose space (fragmentation control).
    if mean_residual > 40.0 && post_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste; penalize them heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Tight fits are excellent: reward low post_residual non-linearly.
    score -= (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(4) * 25.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins gets relatively more attractive
    // only when few bins are open.
    score += (open_bins_count as f64).sqrt() * 3.0;

    // If the next item fits exactly into this bin's post_residual,
    // reward the chain fit.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // Penalize leaving a gap the next item barely doesn't fit into.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Early stream: mild preference to spread items; late stream: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Brand-new empty bin candidate: neutral baseline with slight penalty
    // so it's chosen only when open bins offer poor fits.
    if bin_residual == bin_capacity {
        score += 12.0 + (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 - slack * 0.3;
    } else if next_item_size > 0 {
        // penalize dead space the next item can't use
        score += (post_residual as f64).min(next_item_size as f64) * 0.2;
    }

    // Relative to mean residual: prefer bins tighter/worse than average? Prefer using bins with larger residual
    score -= (bin_residual as f64 - mean_residual) * 0.1;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor
    if bin_residual == bin_capacity {
        // new bin only attractive if no open bin fits well
        if fitting_bins_count == 0 || (post_residual as f64) < mean_residual * 0.5 {
            score -= 10.0;
        } else {
            score += 300.0;
        }
    }

    // Late in stream: consolidate, avoid waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score -= 1.5 * (bin_capacity as f64 - waste) / bin_capacity as f64 * (100.0 - waste);

    // Strong reward for near-perfect fits.
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // Penalize dead space that no future item (min size 1, typical >=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: penalize if this placement leaves residual that barely fits next item,
    // blocking it; reward if leftover is either 0 or comfortably large.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 >= nr && (post_residual as f64 - nr) < 8.0 {
            score += 20.0; // would strand next item's fit
        }
        if post_residual == 0 {
            score -= 10.0; // perfect closure helps next item use other bins
        }
        if (post_residual as f64) < nr && post_residual > 0 && post_residual < 10 {
            score += 15.0; // tiny unusable sliver given known next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * mean_residual.max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 - 0.3 * crowded - 20.0 * (1.0 - progress);
        // If item fits poorly nowhere else (many bins but none fit well), allow new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for fuller bins early (best-fit consolidation).
    let fill_ratio = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Global state coupling: if mean residual is large, prefer bins below mean (balance).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let prn = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 - progress) - prn * prn * prn * progress;
    score += 40.0 * poly;

    // Penalize dead space late in the stream
    score += 30.0 * prn * prn * progress;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - prn) * (1.0 - prn) * (10.0 + 20.0 * progress);

    // Last-chance bonus: strong reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 15.0 * (1.0 - nx / cap) * (0.5 + progress);
        } else {
            score += 10.0 * (nx - pr) / cap;
        }
    }

    // Mild preference for bins below mean residual (keeps larger gaps available)
    score += 5.0 * ((pr - mean_residual) / cap);

    // Discourage opening new bins when many bins are open and progress is high
    score += (open_bins_count as f64) * (0.5 + 1.5 * progress);

    // Base new-bin candidate adjustment: empty bin gets natural post_residual = cap
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

