    } else {
        // Residual class penalty: residuals that are small (< 10) are dead space.
        if post_residual < 10 {
            score += 60.0;
        }
        // Modulo-class logic: residuals congruent to 0 mod common item sizes
        // (10, 20, 25, 50) are reusable by future items.
        if post_residual % 10 == 0 { score -= 12.0; }
        if post_residual % 20 == 0 { score -= 8.0; }
        if post_residual % 25 == 0 { score -= 6.0; }
        if post_residual % 50 == 0 { score -= 10.0; }

        // Lookahead coupling: if the next item fits exactly into post_residual,
        // strongly reward this bin (chain fit).
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 90.0;
            } else if next_item_size <= post_residual {
                // next item fits but leaves unknown remainder: mild reward
                // proportional to how well the chained residual classes align.
                let chain = post_residual - next_item_size;
                if chain % 10 == 0 { score -= 15.0; }
                score -= 10.0;
            } else {
                // next item will NOT fit here: penalize tight residuals that
                // block the lookahead item.
                let gap = (next_item_size - post_residual) as f64;
                score += 0.4 * gap;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the item
    // is large or all existing residuals are poor fits.
    if bin_residual == bin_capacity {
        // Base threshold: new bin costs roughly a full capacity of wasted space.
        score += 0.9 * cap;
        // If the item is large, filling a fresh bin is natural (large items
        // pair poorly with leftovers anyway).
        if item_size > bin_capacity / 2 {
            score -= 0.5 * cap;
        }
        // If many bins fit the item, keep using them; opening new bins
        // proliferates fragmentation.
        if fitting_bins_count > 2 {
            score += 30.0 * (fitting_bins_count as f64 - 2.0);
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If mean residual across open bins is large, use them instead.
        if mean_residual > item_size as f64 {
            score += 20.0;
        }
    }

    // Mild preference for tighter existing bins (low residual) to compact load.
    score += 0.05 * (bin_residual as f64 - pr);

    // Prefer bins whose residual deviates favorably from the mean (below-mean
    // residual bins get closed out first).
    score += 0.1 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize leaving tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Medium-small gaps are also somewhat wasteful.
    if post_residual >= 10 && post_residual < 20 {
        score += 5.0;
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Penalize proportionally to how far the next item misses this bin.
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless it's the new-bin candidate itself).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: penalize the new-bin candidate, escalating with the
    // number of already-open bins, to consolidate packing.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    }

    // Mild tiebreak: prefer bins whose residual is above the current mean
    // (keeps a healthy spread of usable space across bins).
    score -= 0.01 * mean_residual;

    // Stream progression: slightly more open to new bins early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 500.0; // chain perfect fit
        } else {
            score -= 0.5 * next_item_size as f64; // next item fits reasonably
        }
    } else if next_item_size > post_residual {
        // next item cannot use this residual: penalize dead space, more when residual is small
        score += 0.3 * post_residual as f64;
    }

    // Compare residual against mean residual across open bins
    if (post_residual as f64) < mean_residual - 10.0 {
        score += 5.0; // creating a small outlier residual is wasteful
    } else if (post_residual as f64) > mean_residual + 10.0 {
        score -= 5.0; // keeping large residual is flexible
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening a new bin early in the stream
    if bin_residual == bin_capacity {
        score += 50.0 + 100.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference for tighter fits overall
    score += 0.2 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the closer post_residual is to 0, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { (post_residual as f64).powf(1.35) };
        score += 0.05 * dead;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot go here; slight penalty proportional to leftover waste.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is expensive; make the empty bin
    // attractive only when existing bins would leave large unusable remnants.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let existing_waste = mean_residual - item_size as f64;
        let poor_alternatives = (fitting_bins_count == 0) as i32 as f64
            + (existing_waste > 30.0) as i32 as f64
            + ((next_item_size > 0 && existing_waste > 0.0 && (existing_waste as u32) < next_item_size)) as i32 as f64;
        let open_cost = 30.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        score = open_cost - 35.0 * poor_alternatives;
    }

    // Mild preference to fill bins that are already low-residual (compactness pressure).
    score += 0.02 * (mean_residual - bin_residual as f64);

    // Slight time-decay urgency: later in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, scaled by progress
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear coupling: quadratic in normalized post residual, modulated by progress
    score += 30.0 * norm_pr * norm_pr * (1.0 - progress);

    // Penalize large dead space late in stream (cubic coupling)
    score += 20.0 * norm_pr * norm_pr * norm_pr * progress;

    // Prefer tight fits: reward small post residual relative to mean residual
    let mean_r = if mean_residual > 0.0 { mean_residual } else { cap };
    score -= 10.0 * (1.0 - norm_pr).min(1.0) * (cap / mean_r).min(2.0).ln().max(0.0);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits into post residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - progress);
    }

    // Discourage spreading across too many open bins early
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: penalize mildly unless current bin is a poor fit
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo arithmetic on capacity fractions.
    // Residuals that are "harmonically useful" (divisible into common small sizes)
    // are rewarded; awkward residuals are penalized.
    let cap: u32 = bin_capacity;
    let pr = post_residual;

    // Integer-division threshold classes on post_residual
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else if pr > cap / 2 {
        // dead space larger than half a bin: strongly penalize
        score += (pr - cap / 2) as f64 * 0.8;
    }

    // Modulo classes: residuals matching common item sizes (10..=80 in steps)
    // are more likely to be filled later.
    let useful_mods: [u32; 8] = [10, 20, 25, 30, 40, 50, 60, 80];
    let mut mod_bonus = 0.0;
    for &m in useful_mods.iter() {
        if pr >= m && pr % m == 0 {
            mod_bonus += 6.0;
        }
        if pr != 0 && pr % m == 0 {
            mod_bonus += 2.0;
        }
    }
    score -= mod_bonus;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 70.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 / (1.0 + slack / 10.0);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += ((next_item_size - pr) as f64).min(40.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != cap {
        score -= 15.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate handling: neutral base, adjusted by stream phase and
    // how bad the best existing fit would be.
    if bin_residual == cap {
        // Opening a new bin is attractive early in the stream or when many
        // bins are already open and residuals are fragmented.
        let phase = step_index as f64 / (total_items.max(1) as f64);
        score = (cap as f64) * 0.9 - phase * 20.0;
        if open_bins_count > 0 {
            // penalize new bins when mean residual could still absorb the item
            score += (mean_residual - item_size as f64).max(0.0) * 0.6;
        }
        // if many bins fit the item, opening new bin is wasteful
        if fitting_bins_count > 2 {
            score += fitting_bins_count as f64 * 5.0;
        }
    }

    // Mild preference for tighter existing bins relative to mean residual.
    if bin_residual != cap {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Moderately bad gaps (10..20) get a graded penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // Next item can't use this residual anyway; mild reward for tight fit here.
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so this term
    // applies mostly to it via mean_residual comparison).
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 2.0;
        // A new bin is acceptable if the current bin would leave a large dead gap.
        let waste_here = post_residual as f64;
        if waste_here > 30.0 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is already below mean (consolidating small bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Slight pressure to fill existing bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild reward scaled by how snugly it fits.
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item does NOT fit into this bin's remainder: penalize leaving
            // dead space that is too small for the next item.
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += 0.6 * dead;
            }
        }
    }

    // Penalize small unusable dead space (waste) with a convex penalty.
    if post_residual > 0 {
        let r = post_residual as f64;
        score += 20.0 / r; // small remainders get large penalties
    }

    // Compare against mean residual: bins already below mean residual are
    // "tighter" than average; prefer them slightly.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it unattractive unless few bins fit and the
    // item is large relative to capacity.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        // Base penalty keeps new bins closed when open bins fit reasonably.
        score += 150.0;
        // But allow opening a new bin for large items with no good alternatives.
        score -= 200.0 * item_frac * scarcity;
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 80.0 * progress;
    }

    // Mild preference for filling already-open bins when many are open.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead-space avoidance).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize leaving a residual too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead space trap
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / bin_capacity as f64) * 12.0;
        } else {
            // next item cannot follow here: mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += (over / bin_capacity as f64) * 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let bad_fits = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        // base cost of opening a new bin
        score += 55.0;
        // discount when open bins have large, unusable residuals or no fitting bin exists
        score -= pressure * 40.0;
        score -= bad_fits * 45.0;
        // early in stream, be more willing to open bins (build diversity)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer fuller bins generally: penalize bins with large residual relative to mean.
    let res_gap = bin_residual as f64 - mean_residual;
    score += res_gap * 0.05;

    // Late in stream, consolidate: penalize spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: quadratic penalty on wasted space (dead space grows quadratically)
    let mut score = norm_post * norm_post * cap;

    // Non-linear coupling: small residuals become more valuable as stream progresses
    // (tight packing matters more later), reward small post_residual increasingly.
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * cap * (0.5 + 2.0 * progress * (1.0 - progress) * 4.0).min(2.5);

    // Smooth interaction: post_residual vs next item fit — reward leaving space
    // that the next item can use (smooth logistic-like term).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_quality = 1.0 - ((post - nxt).abs() / cap).min(1.0);
        score -= fit_quality * fit_quality * 8.0 * (1.0 + progress);
    }

    // Last-chance bonus: penalize opening new bins when few fitting bins remain
    if fitting_bins_count <= 1 {
        score -= 12.0 * (1.0 + progress);
    } else {
        // mild crowding penalty when many bins compete
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // Mean residual coupling: prefer bins deviating below mean residual
    // (keep balanced slack distribution, smooth cubic term).
    let dev = (mean_residual - post) / cap;
    score += dev * dev * dev * 10.0;

    // New-bin candidate handling: empty bin gets moderate penalty unless item is huge
    if bin_residual == bin_capacity {
        let huge = item_size as f64 / cap;
        score += 15.0 * (1.0 - huge * huge);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are
    // "friendly" to typical item sizes (multiples of small divisors).
    let pr = post_residual;
    let friendly_bonus = if pr == 0 {
        -30.0 // perfect fit is always best
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -8.0
    } else if pr % 2 == 0 {
        -4.0
    } else {
        3.0 // odd residuals are harder to fill
    };
    score += friendly_bonus;

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead: strongly prefer bins whose post residual can host the next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 15.0;
            // Harmonic class match: post residual exactly a multiple of next size class
            if pr % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot fit here; slight penalty proportional to gap
            score += (next_item_size - pr) as f64 * 0.3;
        }
    } else {
        // last item: prefer tightest fit only
        score = post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that can fit, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin when many bins are open
    // (fragmentation risk), scaled by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 10.0 * (1.0 - progress);
        if open_bins_count > 0 && item_size <= bin_capacity / 2 {
            score += 6.0; // small items should almost never open new bins
        }
    }

    // Mild preference toward filling bins below the mean residual (balance avoidance
    // of stranded capacity): bins with residual far above mean get slight priority.
    score -= 0.05 * ((bin_residual as f64) - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal.
        score -= 100.0;
    }

    // Reward tight fits generally: relative fill ratio bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness;

    // If the next item fits exactly into the post-residual, this placement is great.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the known next item: dead space risk.
        score += 20.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when open bins with slack exist (bin-count pressure).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of consuming fresh capacity.
        score += 30.0 + 4.0 * open_bins_count as f64;
        // Acceptable if current bins are fragmented (mean residual low relative to item).
        if mean_residual >= item_size as f64 * 1.5 {
            score += 40.0;
        }
    }

    // Mild preference for bins whose residual is close to item (avoid overfilling big bins early).
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * residual_gap;

    // Stream progression: later in the stream, be slightly more conservative about new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: strongly favor small post_residual.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score -= (cap - pr) / cap * 15.0 * (1.0 - pr / cap);

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 20.0 * snug;
    } else if next_item_size > 0 {
        // Penalize creating residual that cannot host next item (dead space).
        score += (next_item_size as f64 - pr).min(30.0);
    }

    // Relative to mean residual: prefer bins more filled than average.
    score += (mean_residual - pr) * 0.3;

    // Last chance bin: strong incentive to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins as stream progresses / many bins open.
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64).sqrt() * 2.0
            + (step_index as f64 / total_items.max(1) as f64) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Reward exact fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Dead-space penalty: small post_residual that cannot fit typical future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
        // Penalize leaving residual just below next item (awkward gap).
        if post_residual > 0 && next_item_size > post_residual && (next_item_size - post_residual) <= 10 {
            score += 5.0;
        }
    }

    // Last-chance bonus: only one fitting bin; using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is good only if current bin
    // would be left with a large awkward residual or fit is very loose.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer existing bins with decent fits.
        score += 25.0;
        // Reward opening a new bin when existing bins are nearly full (mean residual low)
        // or when item is large relative to capacity.
        score -= 20.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
        // If item is huge, a fresh bin is attractive.
        if item_size >= 70 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        score += 10.0 * progress;
    } else {
        // Reward spreading load when many bins are open with high mean residual.
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        }
    }

    // Mild preference for filling emptier bins when bin count is high.
    if open_bins_count > 8 && !is_new_bin {
        score -= (bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let tightness = 1.0 - pr / cap;

    // Smooth polynomial coupling of post-residual with stream progress
    let p = progress * progress;
    let mut score = pr * (1.0 + 0.35 * p) - 12.0 * tightness * (0.5 + p);

    // Reward near-perfect fits more strongly as the stream advances
    score -= 20.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Lookahead: favor bins whose leftover still fits the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 6.0 * (1.0 - pr / cap) * (n / cap);
        } else {
            score += 4.0 * (n - pr) / cap;
        }
    }

    // Penalize dead space relative to population mean residual
    score += 0.10 * (pr as f64 - mean_residual).abs();

    // Last-chance bin discount (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Mild penalty on excessive open bins to discourage fragmentation
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: neutral-ish baseline that loses only to good fits
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - fit);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "clean" fractions
    // of capacity (dead space that is a multiple of small item sizes is reusable).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Modulo-class reward: residual divisible by common small sizes is reusable.
        let mut class_bonus = 0.0;
        for m in [1u32, 2, 5, 10, 20, 25, 50].iter() {
            if post_residual % m == 0 {
                class_bonus += 6.0;
            }
        }
        score -= class_bonus;

        // Integer-division threshold: penalize residuals in awkward mid bands
        // (too small for typical items 10..80 => dead space).
        let q = post_residual / 10; // harmonic decile class
        if q >= 1 && q <= 7 {
            score += 15.0; // residual 10..79 is a "trap zone" if next item is bigger
        }

        // Lookahead coupling: if next item fits exactly in post_residual, big reward.
        if next_item_size > 0 && next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 400.0;
            } else {
                score -= 30.0 * (1.0 - slack as f64 / cap);
            }
        } else if next_item_size > post_residual && next_item_size > 0 {
            // next item cannot use this residual -> residual likely wasted
            score += 0.5 * pr;
        }

        // Fraction-of-capacity shaping: prefer filling bins to high fraction.
        let fill_frac = (bin_capacity - post_residual) as f64 / cap;
        score -= 40.0 * fill_frac * fill_frac;

        // Last-chance bin: strong reward to avoid opening a new bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 120.0;
        }

        // New-bin candidate: neutral-ish baseline, slightly above tight fits.
        if bin_residual == bin_capacity {
            score += 25.0 + 0.3 * it;
            // Early in stream with few bins, opening new bins is cheap.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= 40.0 * (1.0 - progress) * (1.0 - open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        }

        // Spread penalty: if this bin's residual deviates far from mean, mild penalty
        // (prefer balanced residuals for future packing flexibility).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 12) are nearly useless -> heavy penalty.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    let tightness = item_size as f64 / bin_residual as f64;
    if tightness > 0.95 {
        score -= 45.0;
    } else if tightness > 0.8 {
        score -= 20.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 12 {
            score -= 30.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // dead space that next item cannot use at all
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 8.0;

    // New-bin candidate handling: an empty bin has large residual;
    // penalize it mildly so it is chosen only when fits elsewhere are bad,
    // but less when few bins are open.
    if bin_residual == bin_capacity {
        score += 50.0 - pressure * 10.0;
        // If next item is large and no bins look promising, new bin is fine.
        if next_item_size > 70 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // slightly discouraging extreme outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Early in the stream, be more willing to open bins for good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.1 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills this bin's post-residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        // Perfect two-item chain match: big bonus.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize leaving a gap slightly smaller than the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Reward bins tighter than the average residual (good packing).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting a nearly-empty bin's flexibility on small items.
    if item_size < bin_capacity / 4 && bin_residual > bin_capacity * 3 / 4 {
        score += 10.0;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual already helps; amplify it)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Penalize leaving dead space that the next item cannot use
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // gap reusable by lookahead item
        } else if post_residual > 0 {
            score += (post_residual as f64) * 0.5; // small unusable gap
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Discourage opening new bins when plenty of bins fit the item
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many alternatives exist
        score += 10.0 + 4.0 * (fitting_bins_count as f64);
        // Early in the stream, opening bins is fine (build a portfolio)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 12.0 * (1.0 - progress);
    }

    // Prefer bins whose residual deviates favorably from the mean (balance-seeking)
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.3 * dev;

    // Slight preference for fuller bins when many bins are open
    score += 0.2 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 0.5 * t * t + 0.25 * t * t * t;
    score += 12.0 * poly * (1.0 - norm_pr);

    // Penalize large dead space quadratically, more so early in stream
    score += 0.02 * pr * pr * (1.0 - 0.5 * t);

    // Reward tight fits (small post_residual) with smooth exponential-ish term
    score -= 8.0 * (-norm_pr * 4.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: reward leaving space for next item smoothly
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let diff = pr - ni;
        let match_term = (-((diff / cap).abs() * 6.0)).exp();
        score -= 6.0 * match_term;
        // Penalize if post_residual is just barely below next item (near-miss waste)
        if diff < 0.0 {
            score += 4.0 * (-((-diff) / cap) * 3.0).exp();
        }
    }

    // Prefer filling bins with small residuals relative to mean
    let mr = mean_residual;
    if mr > 0.0 {
        score += 3.0 * (pr / mr - 1.0).tanh();
    }

    // Mild penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64).ln();
        // But late in the stream, new bins are cheaper
        score -= 8.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lands on "useful"
    // residue classes (multiples of common item-size bands) are preferred.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward small post_residual (tight fit) with a convex push.
    score -= (cap - pr) / cap * 8.0;

    // Penalize dead space: residuals too small to fit the smallest item (1..10)
    // are pure waste; residuals in mid bands (11..30) are semi-waste.
    if post_residual == 0 {
        score -= 25.0; // perfect packing
    } else if post_residual < 10 {
        score += 20.0; // dead space below min item size
    } else if post_residual < 25 {
        score += 6.0;
    }

    // Modulo-class logic: residuals divisible by 25 or 50 are "harmonic"
    // anchors that future items (drawn from typical size lattices) re-fit well.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 10 == 0 {
        score -= 2.0;
    }

    // Integer-division threshold on post_residual vs next item: if the next
    // item fits exactly in the post residual, big reward (lookahead chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Reward proportional closeness of fit for the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this residual: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 5.0 * (waste / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin fits well (many fitting bins -> keep consolidation).
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 30.0;
        // But if the item is large and current bins would leave big scraps,
        // opening a new bin becomes relatively cheaper.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream, avoid spawning bins unnecessarily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Fragmentation guard: avoid placing into bins whose residual deviates
    // wildly from the mean residual (keeps residual distribution uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins with larger residual when many bins open.
    score -= 0.01 * (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers that almost nothing can use
    // (items are >= 1, but tiny gaps below a typical minimum are hard to fill).
    if post_residual > 0 {
        let dead_threshold = 15.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 2.5;
        }
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect-fit lookahead: if the next item exactly fills the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // If next item fits into the post residual, mild bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item would NOT fit in the residual, penalize creating a gap
    // that blocks the lookahead item (dead space coupling).
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer consolidating when many bins are open.
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 1.5;
    }

    // New-bin candidate handling: only attractive when open bins have poor fit
    // quality (large mean residual spread) or this is a large item.
    if bin_residual == bin_capacity {
        // Base handicap so new bins are used only when justified.
        score += 30.0;
        // Large items deserve fresh bins more often.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // If the best existing fit is poor (post residual would be small),
        // the comparison already favors a new bin; but if mean residual is low
        // (bins are well filled), discourage opening more.
        score += mean_residual * 0.3;
        // Late in the stream, avoid spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Slight preference for bins whose residual is close to item size overall.
    score -= (bin_residual as f64 - item_size as f64).abs() * -0.1 * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 50.0 + (gap as f64).min(30.0);
            if gap == 0 {
                score -= 300.0;
            }
        } else {
            // next item can't follow here: penalize small dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 60.0 - item_size as f64 * 0.4;
    }

    // Late-stream preference for compacting into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better,
    // but give a super-linear penalty for large dead space.
    let waste_ratio = post_residual as f64 / cap;
    score += 40.0 * waste_ratio * waste_ratio;

    // Perfect-fit bonus: leaving nothing behind is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize bins whose post_residual can't host the next item
    // (creates stranded capacity), reward bins that still remain useful.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 8.0 + 0.15 * nxt;
        } else {
            score -= 6.0;
            // extra reward if post-residual is close to next item (chain fit)
            let chain_gap = post_residual as f64 - nxt;
            if chain_gap < 10.0 {
                score -= 5.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.2 * (item_size as f64);
    }

    // New-bin candidate handling: make an empty bin moderately attractive only
    // when the current fit is bad or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = (bin_residual - item_size) as f64 / cap;
        // baseline cost of opening a new bin
        score += 12.0;
        // discount new bins later in the stream when open bins are fragmented
        score -= 6.0 * progress;
        // if placing here would leave a big hole, new bin becomes competitive
        score -= 15.0 * (fit_quality - 0.5).max(0.0);
        // if many open bins already, avoid spreading too thin
        score += 0.4 * open_bins_count as f64;
    }

    // Global fragmentation pressure: if mean residual is small (bins nearly full),
    // favor consolidating into existing bins.
    let mr = mean_residual / cap;
    score -= 10.0 * (1.0 - mr).max(0.0);

    // Mild time-horizon modulation: early in the stream, be pickier about waste;
    // late in the stream, just close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear penalty on dead space
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Smooth coupling of residual quality with stream progress:
    // later in the stream, tighter fits matter more (waste compounds)
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize residuals that are too small to be useful for typical items,
    // scaled smoothly by progress
    let unusable = (1.0 - pr_norm * 10.0).max(0.0).min(1.0);
    score += 30.0 * unusable * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress * 0.5);
    } else {
        // mild penalty when many bins compete (spread items to keep options)
        score += 5.0 * (fitting_bins_count as f64).ln().max(0.0) * progress;
    }

    // Lookahead: reward if next item fits into resulting post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - ((pr - nxt) / cap).abs();
            score -= 20.0 * snug * snug;
        } else {
            // penalize if post-residual just misses the next item
            let miss = (nxt - pr) / cap;
            score += 12.0 * miss * (1.0 - progress);
        }
    }

    // Encourage balance against mean residual: avoid outliers
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // Slight preference for filling larger fraction with the item
    score -= 10.0 * fit * (0.5 + 0.5 * progress);

    // New-bin candidate: make empty bin attractive only when it's genuinely better
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress - 10.0 * fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: zero residual is the ideal outcome, reward massively.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual (decimal digit classes): residual modulo 10
    // distinguishes "clean" leftover classes from awkward ones.
    score += (post_residual % 10) as f64 * 0.35;

    // Small nonzero residuals are near-dead space; penalize the 1..=9 band.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Lookahead coupling with next item (k=2).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // This bin will be exactly filled by the next item: huge reward.
            score -= 600.0;
        } else if post_residual >= next_item_size {
            // Next item fits; reward proportional to leftover after it.
            let after_next = post_residual - next_item_size;
            score -= 30.0 + 0.4 * after_next as f64;
            if after_next == 0 {
                score -= 200.0; // two-item exact closure
            }
        } else {
            // Next item cannot fit here: penalize leaving a bin that strands the lookahead.
            score += 25.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, using it avoids
    // opening a new bin. Reward strongly (but not above a perfect fit elsewhere).
    if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // Brand-new empty bin candidate: it should only win when open bins offer
    // poor fits. Penalize it by an amount that beats mediocre residuals but
    // loses to exact/near-exact fits in existing bins.
    if bin_residual == bin_capacity {
        score += 120.0 + 0.6 * item_size as f64;
        // If the next item pairs perfectly with what remains here, opening
        // the new bin is more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score -= 90.0;
            }
        }
    }

    // Slight preference for consolidating into bins below the mean residual
    // (keeps a few bins very full and others free for large items).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.15 * (mean_residual - pr);
    } else {
        score += 0.15 * (pr - mean_residual);
    }

    // Late in the stream, prefer tighter closure since fewer items remain
    // to fill leftover gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual % 7) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Reward leaving a gap that can still fit the (smaller) next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize gaps that can fit neither the next item nor the minimum item size.
    if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size) && post_residual < 10 {
        score += 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: penalize slightly so it's chosen only when
    // open bins are truly poor fits (their dead-space penalties dominate).
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, be even more reluctant to open new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild bonus for bins tighter than the mean residual (good fill density).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward (subtract).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack exactly matched to next item is ideal.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0);
        } else {
            // Dead space that cannot host the next item: penalize small leftovers.
            let dead = post_residual as f64;
            if dead > 0.0 && dead < 10.0 {
                score += 60.0 - dead * 3.0;
            }
        }
    }

    // Penalize residuals far below the mean residual (wasting a versatile bin).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: prefer it only when item is large and no tight fits exist.
    if bin_residual == bin_capacity {
        score += 30.0 + item_size as f64 * 0.2;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // Mild preference to fill bins early in the stream.
    score += (step_index as f64 / total_items.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    if post_residual > 0 {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fit_ratio;
    } else {
        // Perfect fill is ideal.
        score -= 40.0;
    }

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let lookahead_waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - lookahead_waste as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty if we strand large dead space.
            if post_residual > 0 && post_residual < next_item_size {
                score += 4.0;
            }
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than spreading.
    let mean_res_gap = mean_residual - post_residual as f64;
    if open_bins_count > 3 && mean_res_gap > 0.0 {
        score -= 0.5 * mean_res_gap.sqrt();
    } else if open_bins_count > 3 && mean_res_gap < 0.0 {
        score += 0.3 * (-mean_res_gap).sqrt();
    }

    // Time horizon: early in the stream, be slightly more willing to open fresh
    // bins (flexibility later); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress;

    // New-bin candidate handling: empty bin has large post_residual; make it
    // attractive only when no good existing option exists is handled by the
    // above; add a mild dynamic penalty that shrinks as bins accumulate.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, dead space matters more.
    score += 12.0 * progress * norm_pr * norm_pr;

    // Penalize post-residuals that no plausible future item can use.
    let dead = norm_pr * (1.0 - norm_pr) * 4.0; // peaks mid-range (unusable zone)
    score += 20.0 * dead;

    // Lookahead: reward if next item fits exactly or well in post_residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > 0 {
        score += 6.0; // next item cannot use this bin's leftover
    }

    // Last-chance bonus: only one bin fits the item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Mean-residual coupling: prefer bins whose residual is close to mean (balanced use),
    // penalize outliers smoothly.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Many open bins: favor filling existing ones rather than spreading.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - norm_pr);

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let post_frac = post_residual as f64 / cap;
    let harmonic_class = (post_frac * 10.0).floor() as i64; // 0..10 integer division band

    // Penalize residual bands that are historically hard to fill (small dead space 1..10).
    let band_penalty = match harmonic_class {
        0 => 0.0,                      // perfect fit
        1 => 25.0,                     // tiny unusable sliver
        2 => 12.0,
        3 => 8.0,
        4 => 5.0,
        5 => 3.0,                      // half-full residual is reusable
        6 => 4.0,
        7 => 6.0,
        8 => 9.0,
        9 => 14.0,
        _ => 0.0,                      // near-full residual (new bin case)
    };
    score += band_penalty;

    // Modulo coupling: if next item would fit exactly into post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_frac = next_item_size as f64 / cap;
        let next_class = (next_frac * 10.0).floor() as i64;
        let harmony = if post_residual % bin_capacity.max(1) == 0 {
            30.0
        } else if (post_residual - next_item_size) < 10 {
            20.0 // next item nearly fills bin -> chain fit
        } else {
            8.0 + next_class as f64 // larger next items prefer roomier bins
        };
        score -= harmony;
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize proportionally.
        score += 6.0 + (next_item_size as f64) * 0.1;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter fits (post residual already does this).
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when stream is early or no open bin fits well.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        // Base score for a fresh bin: slightly above a good existing fit.
        score = cap * 0.95
            - if fitting_bins_count == 0 { 60.0 } else { 0.0 }
            - progress * 10.0
            + open_pressure * 1.5
            - if item_size as f64 / cap > 0.5 { 15.0 } else { 0.0 };
    }

    // Mild global pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 && mean_residual > cap * 0.3 {
        score -= (mean_residual - cap * 0.3) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=9) are nearly unusable
    // for future items (sizes >= 1 but typically larger), so penalize them hard.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0) + 15.0;
    }
    // Medium gaps (10..=19) are partially usable; mild penalty.
    if post_residual >= 10 && post_residual <= 19 {
        score += 6.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual (fill fraction).
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_frac;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (which would strand this bin's residual).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is large
    // or no open bin fits well. Penalize opening new bins by default.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if the item nearly fills a fresh bin, opening is reasonable.
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 55.0;
        }
        // With lookahead: if next item is large, avoid wasting a fresh bin now.
        if next_item_size > item_size {
            score += 10.0;
        }
    }

    // Lookahead synergy: if next item fits exactly in the post residual,
    // reward this placement (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item cannot fit the post residual anywhere else, mildly prefer
    // leaving usable space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins),
    // penalize dumping into loose bins.
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Early stream: slightly favor new bins to build a good pool; late stream:
    // consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small post_residual is good, but a post_residual
    // that cannot fit the next item is wasted space unless it's near zero.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can also host the next item,
            // scaled by how snugly the next item fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - snug / bin_capacity as f64);
        } else {
            // Dead space for the lookahead: penalize proportionally
            // to how much of the residual is unusable.
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // a tighter-than-average bin absorbs the item well.
    score += 0.4 * ((bin_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Slight preference for using existing bins over opening new ones:
    // the empty-bin candidate gets a baseline handicap that grows with
    // stream progression.
    if bin_residual == bin_capacity {
        score += 10.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild reward for high occupancy of this bin by the current item.
    score -= 0.15 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the item into the bin.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 8.0; // perfect closure
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward; if post residual is just barely too small for the next item, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Global state: with many open bins, discourage opening new bins implicitly
    // by slightly favoring reuse when mean residual is high.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open and mean residual
        // is large enough to accommodate the item.
        score += 10.0 + 2.0 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            score += 8.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
    } else {
        // Mild preference for bins whose residual deviates from the mean
        // (consolidate fragmentation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.02 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post-residual, with smooth non-linear decay
    let mut score = post.powf(0.85 + 0.3 * progress);

    // Penalize dead space: residuals too small to be useful are wasted
    let dead_threshold = 0.15 * cap;
    if post < dead_threshold {
        let deadness = (dead_threshold - post) / dead_threshold;
        score += 12.0 * deadness * deadness;
    }

    // Smooth coupling: post_residual scaled by stream progress
    score += 6.0 * (post / cap) * (1.0 - progress);

    // Reward tight fits (post_residual small relative to item)
    let tightness = 1.0 - post / (item_size as f64 + post);
    score -= 10.0 * tightness * tightness;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins mildly
    score += 0.4 * open_bins_count as f64 * (post / cap);

    // New-bin candidate: make it less attractive unless residuals of open bins are poor
    if bin_residual == bin_capacity {
        let open_pressure = mean_residual / cap;
        score += 8.0 + 10.0 * (1.0 - open_pressure);
        // Late in stream, prefer packing into existing bins
        score += 15.0 * progress;
    }

    // Lookahead: if next item fits well in post-residual, reward this placement
    if next_item_size > 0 {
        if (next_item_size as f64) <= post {
            score -= 4.0 * (1.0 - (post - next_item_size as f64) / cap);
        } else {
            score += 3.0 * ((next_item_size as f64 - post) / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Harmonic class logic: dead space quantized by capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals that fall in "unusable" harmonic bands
    // e.g. residual in (0,10] is nearly dead, (10,20] hard to reuse for large items
    let harmonic_penalty = if post_residual == 0 { 0.0 }
        else if post_residual <= 10 { 15.0 }
        else if post_residual <= 20 { 8.0 }
        else if post_residual <= 30 { 4.0 }
        else { 0.0 };
    score += harmonic_penalty;

    // Modulo arithmetic on post_residual: multiples of 10 are "clean" residual classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    // Odd small residuals are likely dead space
    if post_residual % 2 == 1 && post_residual < 15 {
        score += 5.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            // reward leaving a harmonic residual for next item
            if next_post % 10 == 0 { score -= 8.0; }
            score -= 5.0 * (1.0 - next_post as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow in this bin: mild penalty if post_residual small
            if post_residual < next_item_size && post_residual < 20 {
                score += 6.0;
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins unless current fit is poor
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 60.0;
        // but if item is large and no tight fit available, new bin is fine
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        }
    }

    // Stream progression: later in stream, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    // Mean residual coupling: if mean residual is high, prefer bins below mean (balancing)
    if post_residual as f64 > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    // Prefer bins with small residual relative to item (best-fit flavor)
    score += 0.1 * (post_residual as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fits that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leaves a gap that cannot host the next item: mild penalty.
        score += 5.0;
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins lightly.
    score += open_bins_count as f64 * 0.3;

    // Discourage placing into bins with already-large residuals when many bins exist
    // (keeps big gaps consolidated for large future items).
    if bin_residual as f64 > mean_residual && post_residual > 0 {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e., penalize opening a new bin unless current bin is empty and item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0
            - (item_size as f64 - 50.0) * 0.3   // large items justify a fresh bin
            - fitting_bins_count as f64 * 8.0    // if few bins fit, new bin is more reasonable
            - progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits (low post_residual) extra aggressively.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: if the NEXT item exactly fills the post_residual,
    // this placement is ideal — strongly reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item still fits here after this placement: mild reward,
            // scaled by how snugly it fits (small leftover after next item).
            let after_next = post_residual - next_item_size;
            score -= 10.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover space: penalize dead space,
            // especially if the leftover is small (unusable).
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Compare against mean residual across open bins: placing in a bin whose
    // post-residual deviates favorably (smaller) from the mean is rewarded.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that can fit the item, use it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to residual pattern (encourage packing into existing bins),
    // but relax slightly late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 10.0 * progress;
        // If item is huge, opening a fresh bin is more acceptable.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Slight penalty for very tight residual that wastes capacity on tiny items.
    if item_size <= 10 && post_residual > 80 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual already does this; amplify).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 25.0 * dead * (1.0 - 0.5 * progress);
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't chain here: mild penalty scaled by how badly it misses.
        let miss = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 0.05 * miss;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with below-mean residual (keep large residuals available).
    score += 0.08 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Many open bins: encourage closing small-residual bins out.
    score += 0.03 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or the lookahead chain justifies it.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.5;
        let chain = next_item_size > 0 && post_residual >= next_item_size;
        if !poor_fit && !chain && fitting_bins_count > 0 {
            score += 40.0;
        } else {
            score += 10.0 * (1.0 - progress);
        }
    }

    // Small bonus for exactly filling a bin.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * (1.0 - progress);
    score += 40.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * progress;

    // Penalize large dead space, quadratically, scaled by progress
    score += 25.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_margin = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - fit_margin * fit_margin);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Slight preference for consolidating into fewer bins late in stream
    score += (open_bins_count as f64).ln() * 2.0 * progress;

    // Deviation from mean residual: prefer bins near the mean to keep balance
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size buckets via integer division.
    let item_class = item_size / 10;
    let next_class = if next_item_size > 0 { next_item_size / 10 } else { 0 };

    // Perfect fit reward: dead space zero is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize post-residuals that are too small for any plausible item
        // (dead space): residuals < 10 are unusable since min item is 1..100,
        // but tiny residuals waste capacity. Penalize super-harmonic gaps.
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += dead * 150.0;

        // Harmonic-class pairing: reward when next item fits exactly or well
        // into the post residual (chained packing).
        if next_item_size > 0 && next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 40.0 + (10 - slack.min(10)) as f64 * 2.0;
        } else if next_item_size > 0 {
            // Next item won't fit here; slight penalty proportional to gap.
            score += ((next_item_size - post_residual) as f64).min(30.0);
        }

        // Modulo / capacity-fraction structure: residuals near multiples of
        // common item classes (10..=100 by 10s) are more reusable.
        let rem = post_residual % 10;
        let harmonicity = 1.0 - (rem as f64) / 10.0;
        score -= harmonicity * 8.0;

        // Integer-division thresholds on post_residual: large residuals are
        // flexible; mid residuals (30..60) are the sweet spot to fill.
        let pr = post_residual;
        if pr >= 30 && pr <= 60 {
            score -= 12.0;
        } else if pr > 80 {
            score += 6.0; // leaving huge residual wastes a bin slot
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: only open a new bin when current open bins
    // are nearly full (mean residual small) or item is large relative to them.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // High pressure (little room left overall) -> new bin attractive.
        let new_bin_score = 60.0 - pressure * 50.0
            + (open_bins_count as f64) * 1.5
            + (item_size as f64) * 0.3;
        // If next item is small, keep new bin fresh for it.
        if next_item_size > 0 && next_item_size <= 20 {
            new_bin_score -= 15.0;
        }
        score = new_bin_score;
    } else {
        // Existing bin: reward tightness of fit (item fills most of residual).
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill_ratio * 25.0;
        // Prefer bins below mean residual (tighter bins first).
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Mild stream-progression term: later in stream, be greedier (fill tight).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // conceivable follow-up item are pure waste; penalize them hard.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // exact fill: perfect
    } else if post_residual <= 10 {
        // small unusable gap -> strong penalty proportional to tightness
        score += (11 - post_residual) as f64 * 8.0;
    } else if post_residual > 50 {
        // very large leftover is fine (still usable), slight reward
        score -= 5.0;
    }

    // Reward tight fits: small relative slack
    let slack_ratio = post_residual as f64 / bin_capacity as f64;
    score += slack_ratio * 20.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use the leftover -> dead space likely
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when
    // plenty of alternatives fit.
    if fitting_bins_count > 1 {
        score += open_bins_count as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin has large residual; only
    // prefer it when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // if open bins are fragmented (mean residual low relative to item),
        // opening a fresh bin becomes attractive
        if (mean_residual < item_size as f64 * 1.2) && fitting_bins_count > 0 {
            score -= 45.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mean residual alignment: prefer bins whose residual is close to the mean
    // (keeps the bin set homogeneous and predictable).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin's post-residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits with small slack: good chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Dead space: post-residual too small for next item -> penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * post_residual as f64;
    }

    // Compare post-residual to mean residual: prefer bins that become tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Favor fuller bins overall (tight fit reward).
    score -= 0.4 * item_size as f64;

    // New-bin candidate: penalize unless it's early or the fit in open bins is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin can chain next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but penalize dead space
    // that is too small to ever be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // nearly unusable sliver -> strong penalty
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 + 0.3 * slack as f64;
        } else {
            score += 8.0;
        }
    }

    // Prefer filling fuller bins relative to mean residual of open bins.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residual space flexible); late in the stream, squeeze existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (60.0 - 50.0 * progress);

    // Discourage spreading across many open bins when a good fit exists:
    // mild penalty for new bins proportional to open bin count.
    score += new_bin * 0.5 * open_bins_count as f64;

    // Exact fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * (1.0 - progress + progress * norm_post * norm_post);

    let mut score = pr * (0.6 + 0.8 * progress * (1.0 - norm_post));

    // Reward tight fits more strongly as the stream progresses
    score -= 30.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + progress);

    // Penalize wasted dead space relative to mean residual
    score += 0.3 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Lookahead: favor bins whose leftover can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / cap) * (1.0 - norm_post);
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - norm_post);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // New-bin candidate: smooth sigmoid-like gate on residual scarcity
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 25.0 * (1.0 - poly) * (0.3 + 0.7 * progress);
    }

    // Mild dispersion pressure across open bins
    score += 0.05 * (open_bins_count as f64) * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover lands in
    // "usable" classes (multiples of common item sizes) deserve reward.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fit is always best
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 10 == 0 {
        -5.0
    } else if pr % 5 == 0 {
        -2.5
    } else {
        4.0 // awkward dead space
    };
    score += harmonic_bonus;

    // Dead-space penalty grows non-linearly for tiny unusable leftovers.
    if pr > 0 && pr < 10 {
        score += 15.0 * (1.0 - pr as f64 / 10.0);
    }

    // Tight fit reward: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / cap;
    score -= 10.0 * fill_frac;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is doubly good (harmonic chain).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            score -= 5.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // next item won't fit here; mildly penalize large leftovers
            score += 0.05 * pr as f64;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // are crowded or the current residual would be badly fragmented.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap < 0.15;
        let many_open = open_bins_count as f64 > 4.0 + 0.05 * total_items as f64;
        if crowded || many_open {
            score -= 5.0;
        } else {
            score += 8.0; // keep filling existing bins early on
        }
        // Empty bin raw residual is 100, so baseline already penalizes it;
        // scale that baseline by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
    }

    // Prefer consolidating into fewer bins when open-bin count is high.
    score += 0.3 * open_bins_count as f64 * (1.0 - fill_frac);

    // Mild dispersion penalty: bins far from mean residual are less attractive.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let item = item_size as f64;
    let open_pressure = (open_bins_count as f64).min(32.0);
    let fitting_pressure = (fitting_bins_count as f64).min(12.0);
    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };
    let mean = if mean_residual.is_finite() {
        mean_residual.clamp(0.0, capacity)
    } else {
        0.0
    };
    let is_new_bin = bin_residual == bin_capacity;

    if post_residual == 0 {
        let closure_reward = 85.0 + 5.0 * open_pressure + 0.30 * capacity;
        let existing_bonus = if is_new_bin { 0.0 } else { 45.0 };
        return -(closure_reward + existing_bonus);
    }

    if next_item_size == 0 {
        if is_new_bin {
            return post + 180.0 + 8.0 * open_pressure + 0.10 * item;
        }
        return post - 18.0 - 0.45 * open_pressure
            - if fitting_bins_count == 1 { 6.0 } else { 0.0 };
    }

    let mut score = post;

    if post >= next {
        score -= 16.0 + 0.22 * next;
    } else {
        let deficit = next - post;
        let mut dead_penalty = 38.0 + 0.50 * next + 2.05 * deficit + 0.055 * deficit * deficit;

        if post < 8.0 {
            dead_penalty += 1.35 * (8.0 - post);
        }

        if mean > 0.0 && post < 0.25 * mean {
            dead_penalty += 0.30 * (0.25 * mean - post);
        }

        score += dead_penalty;
    }

    if post > 0.0 && post < 5.0 {
        score += 0.75 * (5.0 - post);
    }

    if is_new_bin {
        let mut new_penalty = 14.0
            + 1.05 * open_pressure
            + 2.20 * fitting_pressure
            + 5.00 * progress
            + 0.10 * item;

        let mean_anchor = 0.55 * capacity;
        if mean > mean_anchor {
            new_penalty += 0.08 * (mean - mean_anchor).min(40.0);
        } else if mean > 0.0 {
            new_penalty -= 0.04 * (mean_anchor - mean).min(35.0);
        }

        if fitting_bins_count == 0 {
            new_penalty -= 130.0;
        }

        if fitting_bins_count == 1 {
            new_penalty += 4.0;
        }

        score += new_penalty;
    } else if fitting_bins_count == 1 {
        score -= 5.0 + 0.05 * item + 0.30 * open_pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can accommodate the next item (chained packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills the remaining space.
            let chain = next_item_size as f64;
            let tightness = (post_residual - next_item_size) as f64;
            score -= chain * 1.5;
            score -= 20.0 / (1.0 + tightness); // extra bonus for near-perfect chains
        } else {
            // Next item won't fit here: penalize dead space relative to next item.
            let gap = next_item_size as f64 - post_residual as f64;
            score += gap * 0.3;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += 0.0;
    }

    // Penalize leaving small unusable slivers (dead space < min plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward tight fits overall: small post_residual is good (already base),
    // amplify relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.25;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if no open bin
    // offers a good fit (i.e., when residual-based score would otherwise dominate).
    if bin_residual == bin_capacity {
        // Opening a new bin is wasteful early when many bins are open and usable;
        // penalize so it only wins when all open bins score badly.
        score += 30.0 + (open_bins_count as f64).sqrt() * 5.0;
        // Slightly cheaper to open new bins late in the stream (fewer future
        // items to consolidate into it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
    }

    // Mild penalty for very full bins late in stream? No—full bins are good.
    // Small tie-break noise-free scaling by item size: bigger items prefer
    // being placed so post_residual stays useful (already covered above).

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space penalized superlinearly).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 120.0 - (post_residual as f64) * 8.0;
    } else {
        score += (post_residual as f64).powf(1.35) * 0.35;
    }

    // Tight-fill ratio: prefer bins where item occupies most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Lookahead coupling: reward keeping room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 30.0 * (nxt / 100.0);
        } else {
            score += 15.0 + nxt * 0.2;
        }
        // Chain fit: post_residual exactly matches next item -> great packing.
        if post_residual as u32 == next_item_size {
            score -= 90.0;
        }
    }

    // New-bin candidate logic: penalize opening a new bin unless the item is
    // large relative to capacity or open bins are mostly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64 / 10.0;
        let avg_fullness = 1.0 - (mean_residual / bin_capacity as f64);
        let new_bin_penalty = 60.0 + 120.0 * avg_fullness.recip().min(1.0) * (1.0 - progress) + openness * 10.0;
        score += new_bin_penalty;
        // Large items justify opening fresh bins.
        if item_size > bin_capacity * 3 / 5 {
            score -= 80.0;
        }
    } else {
        // Prefer bins below mean residual (fill emptier bins first keeps options).
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.4;
    }

    // Time-horizon modulation: early stream -> be conservative with dead space;
    // late stream -> prioritize exact fits harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (100.0 - post_residual.min(100) as f64) * 0.5;

    // Slight preference for bins with fewer competitors when many bins open.
    if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap; // 0..1
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 12.0 * poly * (1.0 + progress);

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 0.5 * (nx - pr).min(cap);
        } else {
            score -= 0.4 * (pr - nx).min(cap);
        }
    }

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.1 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes over capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual % 10) as f64;

    // Reward residuals that are "perfect" multiples of common item sizes
    if post_residual % 10 == 0 { score -= 8.0; }
    if post_residual % 5 == 0 { score -= 3.0; }
    if post_residual % 25 == 0 { score -= 4.0; }

    // Penalize dead-space classes (small awkward residuals)
    if post_residual > 0 && post_residual < 10 { score += 12.0; }
    if post_residual >= 10 && post_residual < 15 { score += 6.0; }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            score -= 6.0 * (nxt / pr).min(1.0);
            // harmonic bonus: next item divides post residual nicely
            if post_residual % next_item_size == 0 { score -= 5.0; }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by stream position
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 4.0 * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is bad
    if bin_residual == bin_capacity {
        let tight = (item_size as f64 / cap).min(1.0);
        // prefer new bin for large items or when residuals are messy
        score = cap - 30.0 * tight;
        if fitting_bins_count == 0 { score -= 10.0; }
        if post_residual % 10 == 0 { score -= 2.0; }
    }

    // Mean residual alignment: prefer bins near the mean (balanced packing)
    score += 0.15 * (pr - mean_residual).abs();

    // Integer-division threshold on post_residual thirds
    let third = post_residual / (bin_capacity / 3);
    score += third as f64 * 1.5;

    // Slight preference for tighter fits as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (item_size as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Mid-range dead space (unlikely to fit future items 10..80) also penalized.
    if post_residual >= 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual exactly accommodates the item (tight fit).
    if bin_residual == item_size {
        score -= 60.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 5 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (raise the new-bin candidate's score implicitly by lowering fitting bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 3.0 + open_bins_count as f64 * 1.5 + progress * 5.0;
    } else {
        // New-bin candidate: penalize more when many bins are already open,
        // unless mean residual is large (existing bins are fragmented).
        score += open_bins_count as f64 * 2.0;
        if mean_residual > item_size as f64 * 1.5 {
            score += 20.0;
        }
    }

    // Slight preference for bins below mean residual (consolidate space).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward an exact match: the next item perfectly fills this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Next item also fits here: mild bonus proportional to leftover after two placements.
            let two_step_left = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - two_step_left / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: penalize dead space,
            // worse when the dead space is large relative to mean residual.
            let dead = post_residual as f64;
            let small_gap = (next_item_size - post_residual) as f64;
            score += 0.5 * small_gap + 0.3 * (dead - mean_residual).max(0.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating very small unusable fragments (below typical min item size 1..=10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Prefer tighter bins overall: compare residual to mean residual of open bins.
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Mild bonus for consolidating into already-open bins vs opening new ones
    // early in the stream; later, allow opening new bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);
    }

    // Favor bins with less residual (best-fit bias) nonlinearly.
    score += 0.05 * (bin_residual as f64) * (bin_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but avoid useless slivers.
    if post_residual < 5 {
        score -= 6.0;
    } else if post_residual <= 15 {
        score -= 3.0;
    }

    // Penalize dead space relative to capacity fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 4.0 * fill * fill;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 6.0 - (slack as f64).min(10.0) * 0.4;
        } else {
            // next item won't fit here; slight penalty for wasting large residual
            let wasted = post_residual as f64;
            score += wasted * 0.05;
        }
    } else {
        // Last item: prefer filling as tightly as possible.
        score -= 8.0 * fill;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate scoring.
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 10.0 + pressure * 2.0;
        // If no existing bin fits well (few fitting bins), new bin is more attractive.
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else if fitting_bins_count == 1 {
            score -= 5.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
    } else {
        // Existing bin: penalize relative to mean residual deviation.
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.05;
        // Prefer bins with larger residual when many bins are open (consolidation).
        score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).min(10.0);
    }

    // Mild time-horizon modulation: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - fill) * progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, tight fits matter slightly less (keep bins flexible);
    // late in the stream, aggressively prefer minimal post_residual.
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * (post / cap) * (post / cap) * cap;

    // Penalize dead space that is too small for typical future items (smooth term).
    let dead = post / cap;
    score += 8.0 * dead * dead * dead * cap;

    // Reward this bin if it is the last chance to fit the item.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Penalize opening a brand-new bin, more strongly mid/late stream.
    if bin_residual as f64 == cap {
        let openness = 1.0 - progress;
        score += 15.0 + 35.0 * progress * progress;
        // Slightly favor new bins when mean residual of open bins is large (fragmented).
        score -= 0.05 * mean_residual * openness;
    } else {
        // Reward using existing bins whose residual is close to the mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let gap = post - next_item_size as f64;
        score -= 12.0 * (1.0 - gap / cap);
    }

    // Mild penalty for spreading across many open bins late in stream.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it land in?
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Dead-space penalty via integer-division thresholds.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score -= 35.0; // near-perfect, unusable sliver is fine
    } else if post_residual <= quarter {
        // small leftover: still potentially useful, mild reward
        score -= 12.0;
    } else if post_residual <= half {
        score += 5.0;
    } else {
        score += 20.0; // large leftover: wasteful placement
    }

    // Modulo harmonic: post_residual in classes of 10 (typical item granularity).
    let class = post_residual % 10;
    if class == 0 {
        score -= 8.0; // residue divisible by 10 is reusable by many item sizes
    } else if class >= 7 {
        score += 6.0; // awkward residue class
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item's residue class aligns
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 18.0;
            } else {
                score -= 8.0;
            }
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    } else {
        // last item: prefer zero waste
        score -= post_residual as f64 * 0.5;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // brand-new bin: neutral residual cost, but discourage if decent fits exist
        score += 30.0 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean residual (good packing).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;
    score -= (bin_residual as f64 - mean_residual).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

