    let min_item = 1.0f64;
    let dead = (min_item - post_residual as f64).max(0.0);
    score -= 40.0 * dead; // reward bins that become "perfectly full" (post_residual < min_item)

    // Penalize small but nonzero dead gaps (unusable slivers) more than linearly.
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Tight fit reward: fraction of capacity consumed by this placement.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Open-bin pressure: with many open bins, prefer reusing existing ones
    // (penalize the new-bin candidate and spread items across open bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins already active.
        score += 8.0 + 2.0 * pressure;
    } else {
        score -= 1.5 * pressure.min(20.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if (post_residual as f64 - next_item_size as f64).abs() < 0.5 {
            score -= 20.0;
        } else if post_residual as u32 >= next_item_size {
            score -= 5.0;
        } else {
            // Next item cannot fit here; mildly penalize leaving an awkward gap.
            score += 3.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (balanced usage), penalize outliers.
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
