            score -= 10.0 + 10.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize more when the leftover is small
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
