        // Fragmentation pressure: mean residual low relative to typical item size
        let frag = 1.0 - (mean_residual / 100.0).clamp(0.0, 1.0);
        // Base cost of opening a bin
        score += 30.0;
        // Reward opening when existing residuals are fragmented or few fit
        score -= 35.0 * frag;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // Early stream: keep flexibility, slightly favor new bins; late: consolidate
        score += 10.0 * progress;
        if next_item_size > 0 && bin_residual as f64 >= next_item_size as f64 + item_size as f64 {
            score -= 12.0; // fresh bin can host the pair
        }
    }

    // Prefer bins whose residual is close to item size (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * gap;

    // Mild load balancing: prefer bins with residual above mean (keeps small bins for small items)
    score += 3.0 * ((bin_residual as f64 - mean_residual) / 100.0).clamp(-1.0, 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual_norm = post / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits strongly; late, weight residual more evenly.
    let tightness = 1.0 - residual_norm;
    let poly = tightness * tightness * (1.0 + 3.0 * progress) - residual_norm * residual_norm * (1.0 - progress);
    score -= 25.0 * poly;

    // Reward near-perfect fits with a smooth cubic term.
    score -= 30.0 * (1.0 - residual_norm).powi(3);

    // Last-chance bonus: penalize other bins implicitly by rewarding scarcity.
    if fitting_bins_count == 1 {
        score -= 18.0 + 12.0 * progress;
    }

    // Lookahead: penalize if post_residual cannot fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = nxt - post;
        if gap > 0.0 {
            score += 0.35 * gap * (0.5 + progress);
        } else {
            score -= 0.2 * (-gap) * (1.0 - progress);
        }
    }

    // Penalize bins far from the mean residual (smooth quadratic deviation).
    let dev = post - mean_residual;
    score += 0.04 * dev * dev * (0.5 + 0.5 * progress);

    // Mild penalty for opening new bins when many bins exist.
    score += 6.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    // Slight global pressure toward compactness as stream progresses.
    score += 8.0 * progress * residual_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bin capacity 100 splits into
    // natural "harmonics" of 50, 33/34, 25, 20 ... Residuals that align with
    // common item sizes (multiples of 5/10) are more reusable.
    let residual = post_residual;
    let harmonic_div = residual / 10; // integer division threshold class
    match harmonic_div {
        0 => score += 60.0,               // dead space < 10: nearly useless
        1 => score += 25.0,               // 10..19: only tiny items fit
        2 => score += 8.0,               // 20..29
        3 => score += 0.0,               // 30..39: sweet spot
        4 => score -= 5.0,               // 40..49
        _ => score -= 10.0,               // >= 50: very reusable
    }

    // Modulo bonus: residual exactly divisible by 5 or 10 matches typical item
    // granularity, so it packs more cleanly.
    if residual % 10 == 0 && residual > 0 {
        score -= 12.0;
    } else if residual % 5 == 0 && residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this is a perfect harmonic pair — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let pair_post = post_residual - next_item_size;
            score -= 15.0;
            score += pair_post as f64 * 0.3; // still penalize leftover waste
            if pair_post % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot follow here; slight penalty if residual is small
            if post_residual < 20 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin (unless residual would be tiny).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual < 10 {
            score += 20.0; // but avoid near-dead placement
        }
    }

    // New-bin candidate: prefer it only when it would preserve large room and
    // open bins are numerous/cluttered. Otherwise discourage.
    if bin_residual == bin_capacity {
        score -= 5.0; // base mild preference for fresh capacity
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let clutter = (open_bins_count as f64) / (mean_residual / bin_capacity as f64 + 1.0);
        if mean_residual < 30.0 && open_bins_count > 2 {
            score -= 25.0 * (1.0 - progress); // early stream: fresh bins cheap
        }
        if post_residual == bin_capacity && next_item_size >= 50 {
            score -= 10.0; // big next item benefits from fresh bin
        }
        let _ = clutter;
    }

    // Tight fit reward: item fills bin almost exactly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
