            if *m > 0 && r % m == 0 && r > 0 {
                h += 6.0;
            }
        }
        h
    };
    score -= harmonic_bonus(pr);

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement is perfect — reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            // next item fits: reward proportionally to how well it fills
            let fill = next_item_size as f64 / pr.max(1) as f64;
            score -= 15.0 * fill;
            // harmonic class of residual after the lookahead placement
            let pr2 = pr - next_item_size;
            score -= harmonic_bonus(pr2);
        } else {
            // next item cannot fit here: penalize small dead residuals more
            if pr < 10 {
                score += 25.0;
            } else {
                score += (10.0 * (1.0 - (pr as f64) / 100.0)).min(15.0);
            }
        }
    }

    // Dead-space penalty: very small post-residuals are wasted capacity.
    if pr < 10 && pr > 0 {
        score += 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: prefer reusing open bins with good fits;
    // opening a new bin should only win when all open bins would leave bad fits.
    if bin_residual == bin_capacity {
        // empty bin: neutral-ish baseline; add mild penalty so tight fits in
        // existing bins win, but subtract lookahead harmony if next item is large.
        score += 8.0;
        if next_item_size >= 50 {
            score -= 5.0;
        }
        // late in the stream, consolidating is more valuable
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    } else {
        // tightness reward: prefer bins whose residual is nearly consumed
        let tightness = 1.0 - (pr as f64) / (bin_capacity as f64);
        score -= 10.0 * tightness;
        // prefer bins already below mean residual (denser bins)
        score -= 3.0 * (mean_residual - bin_residual as f64).max(-10.0).min(10.0) / 10.0;
    }

    // Integer-division threshold on post_residual: residuals >= half capacity
    // are quite reusable; residuals in the awkward 30..50 band slightly penalized
    // if next item is medium-sized (won't fit twice).
    if pr >= 50 {
        score -= 5.0;
    } else if pr >= 30 && next_item_size > 25 && next_item_size <= 50 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Non-linear coupling: penalize small-but-not-tiny residuals quadratically,
    // since mid-size dead space blocks future mid-size items.
    if post_residual > 0 && post_residual <= 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Perfect fit: strongly reward zero post-residual.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid forcing a
    // new bin unless the fit is good.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // across bins; prefer consolidating into tighter fits.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins whose residual is already below the mean (tighter bins),
    // coupling with mean_residual.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // New-bin candidate: neutral-ish baseline; only open a new bin when the
    // item is large and would leave an awkward gap elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Early stream: be slightly more willing to open bins (more future items
    // to fill them); late stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 10.0;
    } else {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chain fits (next item fills post_residual exactly).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // Strong reward for exact two-item completion (gap == 0), decaying with gap.
        score -= 30.0 * (1.0 - gap / (bin_capacity as f64));
        if gap == 0.0 {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize proportionally to wasted space.
        score += 8.0 + (next_item_size as f64) * 0.1;
    }

    // Penalize dead space that nothing in the plausible size range (1..100) can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably from mean.
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if lookahead says next item pairs well with a fresh bin, soften penalty.
        if next_item_size > 0 && (bin_capacity - next_item_size) >= item_size {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate into existing bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (open_bins_count as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, bonus.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space that cannot host next item: penalize more when small residual
        score += 0.25 * (post_residual as f64);
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * (open_bins_count as f64).ln().max(0.0) * 5.0;

    // Time horizon: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * fill_ratio;

    // Compare against mean residual: bins far below mean residual are attractive targets.
    score += 0.1 * (mean_residual - bin_residual as f64);

    // New-bin candidate: mild penalty so it's only chosen when open bins fit poorly,
    // but relax penalty early in stream when few bins exist.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 18.0 - 10.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 4.0)));
        score += new_bin_penalty + 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;
        // If next item is large and this fresh bin keeps flexibility, slight bonus.
        if next_item_size >= 50 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth non-linear penalty on post_residual relative to capacity
    let r = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * r * r;

    // Progress-coupled term: later in stream, penalize large residuals more
    score += 15.0 * r * r * r * (0.5 + progress);

    // Reward tight fits (small post_residual) especially when few alternatives
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - r);
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 {
            score += 8.0 * (-gap / bin_capacity as f64);
        } else {
            score -= 4.0 * (gap / bin_capacity as f64);
        }
    }

    // Coupling with mean residual: avoid bins far from the mean
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev * dev;

    // Mild preference for consolidating into fewer bins as stream progresses
    score += 0.15 * open_bins_count as f64 * progress;

    // Slight penalty for opening a new bin early
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward "clean" residuals that pair well
    // with common item sizes (multiples of 5 and 10), penalize awkward ones.
    let pr = post_residual;
    let pr_mod10 = (pr % 10) as f64;
    score -= (10.0 - pr_mod10) * 0.35; // residual divisible by 10 is most reusable
    if pr % 5 == 0 {
        score -= 2.0;
    } else {
        score += 3.0;
    }

    // Perfect fit bonus (harmonic class 0).
    if pr == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 18.0;
    }

    // Lookahead coupling: does post_residual admit the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: reward, scaled by how snug the pairing is.
            let snug = (pr - next_item_size) as f64;
            score -= 8.0 - snug * 0.15;
            if (pr % next_item_size.max(1)) == 0 {
                score -= 4.0; // exact divisor: harmonically compatible
            }
        } else {
            // Next item won't fit: penalize unless post_residual is tiny/waste-like.
            score += 4.0;
            if pr >= next_item_size + 10 {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no good harmonic fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins mildly early, more when many bins are open.
        score += 6.0 + 0.4 * open_bins_count as f64 + 5.0 * (1.0 - progress);
        // But if item is large and current residuals are fragmented, allow it.
        if item_size as f64 > mean_residual + 15.0 {
            score -= 10.0;
        }
        if post_residual == 0 {
            score -= 30.0; // large item exactly filling a fresh bin
        }
    }

    // Mild preference for tighter bins overall (low residual = well-packed).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything useful (below the minimum plausible item size) are pure waste.
    let min_item = 1.0f64;
    let dead_threshold = 10.0f64; // items can be as small as 1..10; gaps below ~10 are near-dead
    if (post_residual as f64) < dead_threshold {
        // Hard penalty scaled by how deep into the dead zone we are.
        score += (dead_threshold - post_residual as f64) * 6.0;
    } else {
        // Soft penalty for small-but-usable gaps: prefer leaving gaps that
        // can still accommodate a meaningful chunk.
        let usable = post_residual as f64 / bin_capacity as f64;
        if usable < 0.25 {
            score += (0.25 - usable) * 30.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64 / item_size as f64);
        score -= tightness * 12.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // and encourage consolidating into existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + (open_bins_count as f64) * 2.5;
        // If this bin is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Late in the stream, avoid opening new bins even more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= (open_bins_count as f64).min(20.0) * 0.8;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Leaving room for the next item is mildly good.
            score -= 5.0;
        } else {
            // Post-residual cannot hold next item: slight penalty, worse if gap is wasted.
            score += 3.0;
        }
    }

    // Compare against mean residual: bins with residual far below mean are
    // already tight; prefer them (they absorb the item with less waste).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let diff = (bin_res_f - mean_residual) / mean_residual;
        score += diff * 8.0; // residual above mean -> higher score -> less preferred
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains nicely; reward proportional to tightness
            score -= 50.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // next item cannot use remaining space -> dead space penalty
            score += 20.0 + 0.3 * post_residual as f64;
        }
    }

    // Compare post_residual to mean residual: penalize creating outliers
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins exist with reasonable fit
    if bin_residual == bin_capacity {
        score += 30.0 + 0.1 * open_bins_count as f64;
    }

    // Late in stream: prefer consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let t = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - t) * (1.0 - t) * (item_size as f64 / bin_capacity as f64);

    // Penalize dead space that no future item (min size 1) could plausibly use:
    // harsher when post_residual is tiny-but-nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item (exact or near fit).
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 20.0; // perfect chain fit
        } else if gap > 0 && (gap as u32) < 10 {
            score -= 8.0;  // near chain fit
        } else if gap < 0 {
            score += (gap.unsigned_abs() as f64) * 0.15; // next item won't fit here
        }
    }

    // Global state coupling: when mean residual is high, prefer consolidating
    // into already-loose bins; when low, be more greedy about tight fits.
    let mr = mean_residual / bin_capacity as f64;
    score -= mr * (post_residual as f64) * 0.3;

    // Time horizon: early in stream, be more willing to open/loosely fill bins
    // (discount tightness); late in stream, squeeze hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - t);

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.5 * open_bins_count as f64 * t;

    // New-bin candidate: penalize slightly so we only open when open bins are poor fits,
    // but discount the penalty when the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let base = 18.0 - 12.0 * (item_size as f64 / bin_capacity as f64);
        // If no open bin fits, opening is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            score += base;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); later, dead space matters more.
    let mut score = post * (1.0 + 1.5 * progress * progress);

    // Cubic smoothing term: penalize large residuals super-linearly.
    score += 0.02 * post * post * post / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            // penalize residual just barely below the next item size (dead space)
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Interaction with mean residual: bins far below mean residual are "tighter",
    // prefer them mildly; normalize to keep scale stable.
    let dev = (post - mean_residual) / cap;
    score += 10.0 * dev * (1.0 + progress);

    // Mild penalty for many open bins to encourage consolidation early.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate handling: an empty bin has post == cap; make it
    // attractive only when it would be nearly perfectly filled.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = (1.0 - fill) * (40.0 + 30.0 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post_residual)
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity fractions
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let cls = post_residual / eighth; // 0..=8 class
    // Dead-space penalty: residuals in awkward middle classes are less reusable
    score += match cls {
        0 => -30.0,                       // perfect fit
        1 => -10.0,                       // tiny leftover, likely unusable -> good
        2 | 3 => 12.0,                    // awkward dead space
        4 => 6.0,                         // half-full leftover: reusable
        5 | 6 => 10.0,
        _ => 0.0,
    };

    // Modulo-10 harmonic: exact multiples of 10 leave clean residuals
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead synergy: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize leaving large residual it can't use
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.3;
        }
    }

    // New-bin candidate handling: empty bin gets neutral-ish score;
    // prefer opening new bin only when all fits would leave large dead space
    if bin_residual == bin_capacity {
        // base cost of a new bin, discounted when few bins open early in stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0 - 20.0 * (1.0 - progress);
        if open_bins_count == 0 {
            new_bin_score = -100.0; // must open
        }
        // if next item is large and current item small, fresh bin helps pairing
        if next_item_size >= item_size.saturating_mul(2) {
            new_bin_score -= 10.0;
        }
        return new_bin_score;
    }

    // Slight preference to fill bins with larger residuals when many open
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual that can't fit even the smallest plausible item (<= 10)
    // is pure waste; a residual below the lookahead item is also suspect.
    if post_residual < 10 {
        score += 60.0; // completely dead gap
    } else if next_item_size > 0 && post_residual < next_item_size as f64 {
        score += 25.0; // gap can't host the known next item
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Open-bins pressure: with many open bins, prefer reusing existing bins
    // (subtract) to consolidate; with few bins, tolerate spreading.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score -= 5.0 * pressure.min(4.0);

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make the empty bin moderately unattractive so it
    // only wins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if the item leaves a large usable residual in a fresh bin
        // (large item), a new bin can be reasonable.
        if post_residual >= 20 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: if this bin is far above average residual,
    // it is a good consolidation target.
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: strongly discourage opening a new bin unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 40.0;
        }
        return score;
    }

    // Reward tight fits (small dead space).
    score -= 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(4) * 10.0;

    // Perfect 2-step lookahead match: next item exactly fills post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional closeness of the follow-up fit.
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item does NOT fit the post residual: penalize dead space relative to mean residual.
            score += 0.6 * (post_residual as f64 - mean_residual).abs();
            if post_residual < next_item_size {
                score += 8.0;
            }
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Slight preference for bins with residuals near the mean (balanced packing).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Prefer filling bins that are already fairly full.
    score -= 0.2 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powf(4.0) * 30.0;

    // Penalize dead space that can likely never be used again.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 20.0 + 0.3 * next_item_size as f64;
        } else if (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) {
            // this bin plus current placement leaves no room but exact pair fits
            score -= 8.0;
        } else {
            // leftover likely wasted relative to next item
            let waste = post_residual as f64 - next_item_size as f64;
            if waste > 0.0 {
                score += waste * 0.15;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer opening a new bin when current fit is poor
    // and there is slack elsewhere; penalize new bins early when open bins fit well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // new bin baseline: mediocre score, adjusted by global congestion
        score = bin_capacity as f64 * 0.9
            - mean_residual * 0.4
            - progress * 10.0
            + open_bins_count as f64 * 1.5;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0; // new bin can absorb follow-up items
        }
    }

    // Prefer filling bins with above-average residuals less when global mean is high.
    if !is_new_bin {
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.05;
    }

    // Mild time-horizon shaping: encourage consolidation early, flexibility later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * post_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let post = post_residual as f64;

    // Reward tight fits: squared fill fraction of the bin
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 30.0 * fill * fill;

    // Penalize post-residual relative to mean residual (dead space vs. fleet average)
    let mean = if mean_residual.is_finite() { mean_residual } else { cap };
    score += 0.5 * (post - mean) * (1.0 - progress);

    // Smooth non-linear coupling: tightness bonus modulated by stream progress
    let tightness = 1.0 - post / cap;
    score -= 20.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Lookahead: reward if next item can use post_residual, penalize otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 10.0 * (nxt / cap);
        } else {
            score += 5.0 * (1.0 - nxt / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: prefer it early or when it enables a perfect future fit
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // Penalize opening new bins when many open bins already fit the item
        score += 3.0 * (fitting_bins_count as f64);
    }

    // Mild preference to consolidate into fewer bins
    score -= 1.0 / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (capacity/10).
    let class = (post_residual % 10) as f64;
    score += class * 0.35; // penalize residues that are hard to fill exactly

    // Dead-space penalty: tiny unusable leftovers (1..=5) are worst.
    if post_residual > 0 && post_residual <= 5 {
        score += 25.0;
    } else if post_residual > 0 && post_residual <= 10 {
        score += 8.0;
    }

    // Perfect fit reward via integer division thresholds.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does next item fit the post-residual exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chained perfect fit
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            let nxt_class = (nxt_post % 10) as f64;
            score -= 6.0 + nxt_class * 0.3;
            if nxt_post <= 5 && nxt_post > 0 {
                score += 10.0; // creates future dead space
            }
        } else {
            score += 5.0; // next item cannot use this bin anyway
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64) / 20.0;
        score = bin_capacity as f64 - 12.0 + mean_residual * 0.25 - crowded - progress * 5.0;
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 8.0; // stream is trending large; fresh capacity helps
        }
    }

    // Mild normalization toward mean residual pressure.
    score -= mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
