    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 20.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Prefer bins with residual below mean residual (consolidating small gaps).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well or stream is early.
    if bin_residual == bin_capacity {
        let poor_options = fitting_bins_count == 0
            || (post_residual as f64 - mean_residual) < 0.0;
        if poor_options {
