        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for large dead space relative to bin capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead_frac * dead_frac;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // or nearly matches the next item size (chain-fill bonus).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if gap == 0.0 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if gap <= 10.0 {
            score -= 35.0 - 2.5 * gap;
        } else {
            // penalize residuals the next item cannot use at all
            if (post_residual as f64) < next_item_size as f64 {
                score += 10.0;
            } else {
                score += 5.0 + 0.1 * (gap - 10.0);
            }
        }
        // Reward bins that could fit both current and next item (keeps chains alive)
        if bin_residual >= item_size + next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: prefer minimal waste
        score += 5.0 * dead_frac;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean
    // (compact bins first), penalize above-mean bins.
    score += 0.8 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins
    // would leave very tight/awkward fits, otherwise discourage opening.
    if bin_residual == bin_capacity {
        let tight = item_size as f64 / bin_capacity as f64;
        // big items open bins easily; small items should reuse space
        score = 30.0 + 50.0 * (1.0 - tight);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin can chain next item
        }
    }

    // Mild late-stream pressure to consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (open_bins_count as f64).ln().max(0.0) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
