            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with lower residual relative to mean (compact bins first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Slight preference for existing bins over opening new ones as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with progress and with number of open bins.
        score += 5.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        score -= 3.0;
    }

    // Late stream: be more conservative, prefer exact residual minimization.
    if progress > 0.8 {
