    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post-residual (prefer tight fits)
    let mut score = post;

    // Non-linear polynomial coupling of post residual with stream progress:
    // early on, tolerate slack; late, penalize it quadratically.
    let p2 = progress * progress;
    score += cap * (norm_post * norm_post) * (0.4 + 1.6 * p2);

    // Dead-space penalty: post residual too small for typical future items
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 3.0 * (1.0 - p2);
    }

    // Last-chance bonus: smooth reward when few fitting bins
    let fit_term = 1.0 / (fitting_bins_count as f64);
    score -= 12.0 * fit_term * (0.5 + p2);

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 * (1.0 - nxt / cap) * (0.5 + p2);
        } else {
            score += (nxt - post) * 0.15 * (1.0 - p2);
        }
