    // Mean-residual deviation: prefer bins close to mean (smooth coupling)
    let dev = (post - mean_residual).abs();
    score += 0.25 * dev * (1.0 - p2);

    // Mild penalty for opening new bins when many already open, eased early
    if bin_residual as f64 == cap {
        score += 8.0 * (1.0 + 0.02 * open_bins_count as f64) * (0.3 + p2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual bucketed by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as f64;
    let eighth = (bin_capacity / 8) as f64;

    // Perfect fit: zero waste is best possible.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty for tiny leftovers (unusable slivers).
    if post_residual > 0 && post_residual <= bin_capacity / 20 {
        score += 60.0;
    }

    // Harmonic classes: reward leftovers that are "fillable" by common item sizes.
    // Class the post_residual by integer division into capacity eighths.
    let class = post_residual / (bin_capacity / 8).max(1);
    match class {
        0 => score += 25.0,          // tiny leftover, hard to fill
        1 => score -= 10.0,          // 12-25: fillable by small items
        2 => score -= 15.0,          // 25-37
        3 => score -= 20.0,          // 37-50: sweet spot
        4 => score -= 25.0,          // 50-62
        5 => score -= 15.0,
        6 => score -= 5.0,
        _ => {}
    }

    // Lookahead coupling: does the leftover accommodate the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional to how well next item fills the residual
            score -= 40.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; mildly penalize large residuals that trap space
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only open a new bin if residuals are all tight
    // or this is a large item early in the stream (future packing potential).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Empty bin baseline: attractive when open bins are fragmented or item is large.
        let fragmentation = (mean_residual - pr).abs();
        score -= 20.0 + 30.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
        if item_size >= bin_capacity / 2 {
            score -= 15.0; // large items start fresh bins well
        }
        if fragmentation < quarter {
            score += 25.0; // open bins already uniform; don't fragment more
        }
    }

    // Modulo harmonic: leftover divisible by common item sizes (10, 20, 25, 50) is reusable.
    if post_residual % 10 == 0 { score -= 8.0; }
    if post_residual % 25 == 0 { score -= 6.0; }
    if post_residual % 50 == 0 && post_residual > 0 { score -= 10.0; }

    // Prefer tighter existing bins (best-fit flavor) scaled by mean residual.
    score += (mean_residual - pr) * 0.4;

    // Mild preference to keep bin count low when many bins are open.
    if bin_residual != bin_capacity {
        score -= 0.15 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

