    score += open_bins_count as f64 * 0.3;

    // Prefer bins whose residual deviates below the mean (consolidate fullness).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate: only attractive when the item is huge relative to capacity
    // and mean residual across open bins is small (nothing fits well anyway).
    if bin_residual == bin_capacity {
