        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        if post_residual == next_item_size {
            score -= 120.0; // exact two-item completion of the bin
        }
        // penalize leaving residual that neither fits next item nor is useful
        if post_residual > 0 && (next_item_size as u32) > post_residual {
            score += 15.0;
        }
    }

    // Penalize creating unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        let bad_fits = if fitting_bins_count <= 1 { 0.0 } else { 1.0 };
        score += 70.0 - bad_fits * 0.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0; // opening a bin for a big item then medium next is okay-ish
        }
    }

    // Slight preference for fuller bins late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - item_size) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity, nonlinearly.
    let dead = post_residual as f64 / bin_capacity as f64;
    if dead > 0.0 {
        score += 6.0 * dead * dead;
    }

    // Lookahead coupling: reward if next item fits the post-residual (chain packing).
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a gap the next item cannot use.
            let gap_waste = (post_residual as f64 - next_item_size as f64).abs();
            score += 2.0 * gap_waste / bin_capacity as f64;
        }
    } else {
        // Last item: prefer tightest closure.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but less when
    // alternatives are poor (large mean residual spread / high open count).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 20.0;
        // If open bins are fragmented (mean residual low), opening a fresh bin is cheaper.
        if mean_residual < item_size as f64 * 1.5 {
            new_bin_penalty -= 10.0;
        }
        // Late in the stream, avoid leaving many near-empty open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += 5.0 * (1.0 - progress);
        score += new_bin_penalty;
    }

    // Mild preference to consolidate into existing bins as bin count grows.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time-horizon adaptation: early on, be exploratory (favor diverse residual profiles);
    // later, be greedy about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (mean_residual / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with quadratic dead-space penalty.
    let mut score = post + 60.0 * norm_post * norm_post;

    // Smooth stream-progress coupling: as stream advances, tighten tolerance.
    score *= 1.0 + 0.35 * progress * (1.0 - norm_post);

    // Reward when the lookahead item exactly consumes the post-residual.
    if next_item_size > 0 && (next_item_size as f64 - post).abs() < 1e-9 {
        score -= 25.0;
    } else if next_item_size > 0 {
        // Penalize post-residual that wastes space relative to next item.
        let waste = (post - next_item_size as f64).max(0.0) / cap;
        score += 20.0 * waste * waste;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild preference for bins tighter than the open-bin average.
    score -= 5.0 * ((mean_residual - post) / cap).clamp(-1.0, 1.0);

    // New-bin candidate: keep it attractive only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_possible = (cap - item_size as f64) / cap;
        score = 30.0 + 40.0 * best_possible * best_possible + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is "usable" (small, fillable
    // by the 1..100 item range) is less costly than mid-range unusable space.
    let pr = post_residual;
    let class = pr % 10; // decade remainder class
    // Penalize mid-range dead space (11..=50) hardest: hard to fill by anything.
    if pr > 0 && pr <= 10 {
        score -= 6.0; // near-perfect fit, tiny dead space
    } else if pr > 50 {
        score -= 2.0; // large residual still broadly usable
    } else if pr > 0 {
        // mid-range dead space: penalize more the "rounder" it is mod 10
        score += (class as f64) * 0.8 + 3.0;
    }

    // Integer-division thresholds: residual divisible into likely item sizes is good.
    if pr > 0 {
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 30, 40, 50] {
            if pr % d == 0 {
                harmony += 2.5;
            }
        }
        score -= harmony;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size <= pr {
            // next fits: reward proportional to tightness of that future fit
            let future_post = pr - next_item_size;
            score -= 4.0 + future_post as f64 * 0.05;
            if future_post % 10 == 0 {
                score -= 2.0;
            }
        } else {
            // next item does NOT fit here: penalize leaving this bin for a stranded item
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        // but if placing here would strand a large unusable gap, new bin becomes better
        if pr > 50 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > pr && pr > 0 {
            score -= 6.0;
        }
    }

    // Stream progression: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Prefer bins already below mean residual (consolidating emptier bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item (<= ~10) are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Penalize gaps that cannot host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also absorb the next item (chained fits).
        score -= 4.0;
    }

    // Reward tight fits (item fills most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (make the new-bin candidate less attractive by penalizing small post
    // residual relative to open count).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a fresh bin.
        score += 15.0;
        score += 0.5 * open_bins_count as f64;
        // A new bin is acceptable only if existing bins would leave large
        // dead space; if the best existing fit is bad, this penalty is small
        // relative to their dead-space penalties.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // New bin is great for the next item too.
            score -= 3.0;
        }
    } else {
        // Existing bins get a mild bonus when few bins are open, to encourage
        // consolidation early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 2.0 * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (balanced packing) and avoid extreme outliers.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: perfect match with next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact two-item fill
        } else if post_residual >= next_item_size {
            let next_leftover = post_residual - next_item_size;
            // reward small leftover after the lookahead item
            score -= 25.0 * (1.0 - (next_leftover as f64) / (bin_capacity as f64));
            if next_leftover == 0 {
                score -= 15.0;
            }
        } else {
            // next item can't fit here: penalize leaving a gap smaller than next item
            score += 12.0 + 0.2 * ((next_item_size - post_residual) as f64);
        }
    }

    // Penalize dead space that is hard to fill (below minimum plausible item size 1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Relative to mean residual: prefer bins that keep residual near the mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 55.0;
        // But if current bin would leave a large dead space, new bin becomes attractive.
        if post_residual > 0 && (post_residual as f64) > mean_residual + 20.0 {
            score -= 45.0;
        }
        // If next item is large and nothing can chain, opening fresh is fine.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 25 {
            score -= 25.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Slight preference to fill bins with more items already (avoid bin sprawl)
    score += 0.05 * open_bins_count as f64 * (is_new_bin as i32 as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward bins where the item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize large unusable leftovers relative to smallest plausible item
    if post_residual > 0 && post_residual < item_size {
        score += 0.25 * post_residual as f64;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the known next item
        score += 10.0 + 0.2 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Mean residual coupling: prefer bins with residual below the mean (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Many open bins: encourage consolidation into existing bins
    score += 0.05 * open_bins_count as f64 * (1.0 - fill_ratio);

    // New-bin candidate handling: penalize opening a new bin early/moderately,
    // allow it late in the stream or when no open bin is a decent fit
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let poor_fits = if fitting_bins_count > 0 {
            let best_other = (bin_capacity as f64).min(fitting_bins_count as f64);
            0.0
        } else { 0.0 };
        // base penalty scaled by stream position and existing bins
        let mut new_bin_score = 70.0 * (1.0 - progress) + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            // No open bin fits: new bin is mandatory-ish, low score
            new_bin_score -= 100.0;
        } else if fitting_bins_count == 1 {
            // One last-chance bin exists: only open new bin if that bin would waste a lot
            let waste = (bin_residual - item_size) as f64;
            if waste > 60.0 {
                new_bin_score -= 20.0;
            } else {
                new_bin_score += 30.0;
            }
        }
        // Slightly favor new bin when mean residual is very low (open bins are nearly full)
        if mean_residual < item_size as f64 {
            new_bin_score -= 15.0;
        }
        let _ = desperation;
        let _ = poor_fits;
        score = score.max(score) + new_bin_score;
        score += new_bin_score - new_bin_score; // keep arithmetic explicit
        score = new_bin_score + 0.0 * score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress:
    // later in the stream, tighter fits (small post_residual) are worth more
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * progress * tightness * tightness * norm_pr;

    // Interaction: post-residual vs mean residual (avoid bins that leave
    // residuals far from the pack's typical residual landscape)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * (0.5 + progress);

    // Last-chance bonus: strongly reward using the only fitting bin,
    // scaled non-linearly by how well the item fills it
    if fitting_bins_count == 1 {
        let fill = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fill * fill;
    }

    // Lookahead: penalize if the next item cannot use the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (pr - nx).max(0.0) as f64;
        score += 0.15 * waste * (1.0 + 0.5 * progress);
        // reward if next item fits exactly-ish
        if nx <= pr {
            let snug = 1.0 - ((pr - nx) / cap).abs();
            score -= 10.0 * snug * snug;
        }
    } else {
        // last item: only the absolute fill matters
        score -= 20.0 * (item_size as f64 / bin_residual as f64);
    }

    // Mild pressure to reuse existing bins as open bin count grows
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: small dead space classes are good.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity wasted after placement (non-linear penalty).
    let waste_frac = pr / cap;
    score += 40.0 * waste_frac * waste_frac;

    // Reward tight fits strongly.
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Harmonic class: leftover divisible into common future item chunks (mod logic).
    if post_residual > 0 {
        let pr_u = post_residual;
        if pr_u % 10 == 0 {
            score -= 8.0; // clean decade leftover, easy to refill
        }
        if pr_u % 5 == 0 {
            score -= 3.0;
        }
        // Dead-space trap: leftover in awkward 1..9 band that few items fit.
        if pr_u < 10 {
            score += 25.0;
        }
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overflow.
            score += 6.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (mean_residual / cap).max(0.1);
        score = cap * 1.5 + 20.0 * progress - 10.0 * pressure.min(3.0);
        // Only attractive if nothing fits well anywhere.
        if mean_residual < 15.0 {
            score -= 40.0;
        }
    }

    // Slight preference for fuller bins (lower residual before placement).
    score += 0.15 * (bin_residual as f64 / cap) * 10.0;

    // Progress-based gentle scaling of tightness reward.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - waste_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exact or near-exact fill.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Dead space penalty: gaps too small to ever be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        // Gap can't fit the lookahead item: penalize more if it also can't fit typical small items.
        score += 60.0 + 3.0 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Open-bins pressure: discourage scattering across many bins when residuals are plentiful.
    if open_bins_count > 2 {
        score += (open_bins_count as f64) * 2.0;
    }

    // New-bin candidate handling: only open a new bin if the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        // Base new-bin cost; cheaper when many bins already open and mean residual is low.
        score = 120.0 + poor_fit * 0.5 - (open_bins_count as f64) * 1.5 - mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= bin_residual as u32 - item_size {
            score -= 40.0; // fresh bin leaves room for lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer bins whose leftover is small but not dead space.
    // Aggressive 2-step lookahead: does the NEXT item fit perfectly here?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: this item leaves exactly room for the next one.
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.35;
        } else {
            // Next item won't fit here; penalize proportional to wasted opportunity,
            // but less harsh if post_residual is tiny (bin is nearly full anyway).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            if post_residual <= 5 {
                score -= 12.0; // near-perfect fill, dead space is negligible
            }
        }
    } else {
        // Last item in stream: just minimize leftover.
        score -= 25.0;
    }

    // Reward tight fits relative to the bin's current state.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Penalize creating unusable slivers (residual too small for the minimum item).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Make the empty bin moderately attractive by default...
    if bin_residual == bin_capacity {
        score -= 10.0 + 0.15 * open_bins_count as f64;
        // ...but push it away when the stream is late and open bins are loose
        // (consolidate before opening more bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        if mean_residual > 40.0 {
            score += 25.0; // plenty of loose space already; don't open a new bin
        }
    }

    // Slight preference for bins tighter than the current mean residual
    // (pack into crowded bins, keep loose bins for awkward future items).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Mild exploration penalty for very many open bins: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use:
    // if post_residual is smaller than the smallest plausible item (1), it's dead;
    // more realistically, penalize residual below ~10 heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // partial reward scaled by how well next item fills the remaining space
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill;
        } else {
            // next item cannot fit here: mild penalty, this bin becomes less useful
            score += 4.0;
        }
    } else {
        // Last item: prefer minimizing leftover waste as much as possible
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has neutral attractiveness.
    // Prefer open bins unless all open bins fit poorly.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 10.0 * progress;
        // if many open bins already have large mean residual, opening new bins is worse
        score += mean_residual * 0.2;
    } else {
        // slight preference for bins whose residual is close to item (best-fit flavor)
        score += (bin_residual as f64 - item_size as f64) * 0.3;
        // prefer using bins with below-average residual (keep big holes free)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Mild penalty for spreading across too many open bins late in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress * norm_pr - 0.4 * progress * progress);

    let mut score = poly * 100.0;

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 + progress) * 15.0;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress) * 2.0;
        } else {
            score -= 3.0;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Penalize opening new bins when open bins have plenty of room
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress) + mean_residual * 0.1;
    }

    // Mild penalty for too many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: waste classes mod 10
    let class = post_residual % 10;
    // Small leftovers (dead space) get penalized non-linearly
    if post_residual > 0 {
        score += (class as f64) * (class as f64) * 0.05;
    }

    // Perfect fit is heavily rewarded
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Reward leftovers that are "harmonic": divisible by common item sizes
        let r = post_residual;
        if r % 10 == 0 { score -= 8.0; }
        else if r % 5 == 0 { score -= 4.0; }
        else if r % 3 == 0 { score -= 2.0; }
        else if r % 7 == 0 { score -= 1.5; }
        // penalize prime-ish / awkward leftovers
        if r < 10 { score += 12.0; }
        else if r < 20 { score += 5.0; }
    }

    // Next-item lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // reward if next item leaves another nice class
            score -= 10.0 - (slack % 10) as f64 * 0.5;
        } else {
            // next item won't fit here; slight penalty for blocking bins
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded && open_bins_count > 0 {
            score -= 5.0 + 10.0 * progress;
        } else {
            score += 20.0 + mean_residual * 0.1;
        }
    }

    // Prefer fuller bins when many are open
    score -= (bin_residual as f64 / bin_capacity as f64) * 2.0;

    // Tie-break toward fewer open bins
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item (size 1..10 range floor; use 10 as conservative dead-gap bound)
    // are wasted space — penalize them harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins, but a
    // slightly weaker pressure so tight fits still win.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward it;
    // if post_residual would strand a known next item, penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // New-bin candidate: keep it mildly attractive only when the fit into
    // existing bins would leave a large dead gap; otherwise slightly
    // penalize so existing tight fits are preferred.
    if bin_residual == bin_capacity {
        score += 3.0;
        if post_residual < 25 {
            score -= 15.0; // fresh bin with a big item = fine
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Next item fits into the post residual with a small gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.5 * (post_residual as f64 - next_item_size as f64).min(20.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the upcoming item.
        score += 0.3 * (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Reward tight fits now.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Last chance: strongly favor using this bin instead of opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize dumping into a large-residual bin when many bins are open
    // (save big residual space for big future items).
    if post_residual as f64 > mean_residual && open_bins_count > 1 {
        score += 0.4 * (post_residual as f64 - mean_residual).min(30.0);
    }

    // Slight bias against opening a new bin as the stream progresses.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (step_index as f64 / (total_items.max(1) as f64));
        // New bin is fine if current bin would leave awkward dead space.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic penalty on post-residual (dead space is superlinear bad).
    let post = post_residual as f64;
    score += 0.35 * post * post / bin_capacity as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    } else if post_residual <= 8 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, this is a great pairing.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let slack = post_residual as f64 - nxt;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use leftover: leftover likely dead space.
            score += 6.0 * post / bin_capacity as f64;
        }
    } else {
        // Last item: closing a bin completely is ideal.
        score -= 40.0 * (1.0 - post / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time-horizon pressure: early in the stream, keep residuals flexible (spread);
    // late in the stream, prefer filling bins tightly to avoid leftover waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.5 * (post_residual as f64 - mean_residual).abs();

    // Prefer using already-open bins over opening new ones, more so when many bins are open.
    if bin_residual == bin_capacity {
        // Candidate for a brand-new bin: penalize, especially when open bins fit well.
        let mut new_bin_score = 55.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            new_bin_score += 25.0;
        }
        // Late in the stream a new bin is more acceptable if nothing fits tightly.
        new_bin_score -= 20.0 * progress;
        score = new_bin_score;
    } else {
        // Small preference for reusing bins that are already quite full.
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 8.0 * fullness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize post residual, with non-linear (quadratic/cubic) coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);
    score += cap * 2.0 * norm_pr * norm_pr * (0.5 + progress);

    // Dead-space penalty grows non-linearly when residual becomes unusably small
    score += cap * 3.0 * (1.0 - norm_pr).powi(3) * norm_item * (1.0 + progress);

    // Tight fit reward (small post residual), stronger early in stream
    score -= cap * 1.5 * (1.0 - norm_pr).powi(2) * (1.2 - progress);

    // Last-chance bonus: only bin that fits -> strong reward, smooth
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= cap * 2.5 * last_chance * (1.0 - norm_pr * 0.5);

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let nx = next_item_size as f64 / cap;
        score -= cap * 1.2 * fits_next * nx * (1.0 + progress);
        // Penalize leaving residual just barely below next item (smooth near-miss penalty)
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += cap * 1.0 * gap * (1.0 - gap) * 4.0 * (1.0 - fits_next);
    }

    // Mean residual context: penalize bins far from mean (fragmentation), smooth coupling
    let dev = (pr - mean_residual) / cap;
    score += cap * 0.6 * dev * dev;

    // New-bin candidate: neutral-ish, penalize slightly more as stream progresses
    // unless open bins would create large dead space
    if bin_residual == bin_capacity {
        score = cap * 0.9 + cap * 0.8 * progress - cap * 2.0 * norm_item * (1.0 - norm_item);
        // prefer new bin if all fits would leave tiny residuals
        score -= cap * 2.0 * norm_item * (1.0 - norm_item) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Penalize unusable dead-space slivers (below minimum plausible item size)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead (k=2): reward if the next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // next item overshoots this bin: mild penalty proportional to overshoot
            let over = next_item_size as f64 - post;
            score += 0.08 * over.min(20.0);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer tighter-than-average bins (coupling with mean residual)
    let diff = mean_residual - post;
    score += 0.1 * diff.max(-30.0).min(30.0);

    // Harmonic class logic: post residuals that are multiples of 10 (decimal-friendly
    // classes) tend to remain usable by future items; reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }
    // Integer-division threshold: post residuals in [20, 40] are a "sweet spot"
    // usable by most mid-size items; slight extra reward.
    if post_residual >= 20 && post_residual <= 40 {
        score -= 1.5;
    }

    // New empty bin candidate: neutral-ish baseline so it only wins when all
    // existing fits are poor, or when this is the only viable option.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.1 * item_size as f64;
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1..=10)
    // are essentially unusable; penalize them super-linearly.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    } else {
        // Mild reward for leaving a gap that likely fits a typical next item.
        score -= 2.0;
    }

    // Reward bins whose residual was already tight (good fragmentation reuse).
    let fill_ratio = 1.0 - (bin_residual as f64) / cap;
    score -= fill_ratio * 6.0;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 8.0 + open_pressure * 5.0;
    } else {
        score -= open_pressure * 1.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 1.5;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins),
    // pushing toward balanced consolidation.
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins since leftover slack matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post residual, this bin is an excellent chain candidate.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits: penalize leftover after the chained placement.
            let chained = post_residual - next_item_size;
            score -= 150.0;
            score += chained as f64 * 0.8;
        } else {
            // Next item does NOT fit here: dead-space risk grows with gap.
            let gap = next_item_size - post_residual;
            score += gap as f64 * 0.6;
        }
    }

    // Compare post_residual relative to mean residual across open bins:
    // leaving less than average residual is good (denser packing).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // this placement would leave a large, awkward residual.
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin; penalize slightly so tight fits
        // in existing bins win, but allow it when fits are terrible.
        score += 40.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Penalize very small unusable residuals (dead space) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Slight preference for keeping fewer open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let fit_frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_frac).powi(3) * 30.0;

    // Penalize dead space that can never be used by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: be pickier about wasting this bin.
        score += fit_frac * 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here; penalize leaving large gap anyway.
            score += fit_frac * 8.0;
        }
    } else {
        // Last item: prefer the tightest possible packing.
        score -= 20.0;
    }

    // Global state coupling: with many open bins, consolidate; few bins, spread.
    let pressure = open_bins_count as f64 / (mean_residual + 1.0);
    score += pressure * 0.5;

    // Time horizon: early in stream, slightly favor opening fresh bins (flexibility);
    // late in stream, strongly favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate score: baseline + adjustments.
        score = bin_capacity as f64 - progress * 30.0;
        if fitting_bins_count == 1 && post_residual < item_size as f64 + 1.0 {
            score += 100.0; // never open new bin when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size >= 60 && progress < 0.5 {
            score -= 10.0; // early large next item: fresh bin may help
        }
    } else {
        score -= progress * 15.0; // late stream: favor existing bins
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's an outlier;
    // filling it down toward the mean is good.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.2;
    } else {
        score += (-dev) * 0.1;
    }

    // Mild penalty proportional to item size consumed from a large residual
    // (prefer placing large items into large-residual bins).
    score -= (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64) * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with quadratic smoothing
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Stream progress coupling: later in the stream, tighten residual tolerance quadratically
    let progress_coupling = 60.0 * progress * norm_pr * norm_pr;
    score += progress_coupling;

    // Dead-space penalty: residuals too small to ever fit typical items
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) * (10.0 - pr) * 0.5 } else { 0.0 };
    score += dead;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0 + 25.0 * progress;
    }

    // Lookahead: reward residual that can still hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 15.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure against proliferating bins when mean residual is large
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (mean_residual / cap);

    // Slight preference for fuller bins relative to the fleet average
    score += (mean_residual - pr) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are nearly perfect fits -> strong reward.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // capacity fraction of leftover

    // Perfect-fit harmonic classes (post_residual in {0} or tiny)
    if post_residual == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Dead-space penalty: leftover that no plausible item (>=1) can be
    // judged against — penalize large leftover relative to capacity.
    if frac > 0.5 {
        score += 8.0 * frac;
    }

    // Lookahead coupling (harmonic pairing): reward if next item exactly
    // or nearly fits into the post residual; penalize wasted pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // exact chained fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot fit here: leftover becomes dead space
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.15 * overshoot.min(50.0);
        }
    } else {
        // last item: prefer exact exhaustion even more
        score -= 10.0 * (1.0 - frac);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: brand-new empty bin should only win when
    // the fit into existing bins is bad. Penalize opening a new bin unless
    // current item is large relative to capacity.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        // opening new bin: baseline score = capacity - item (its post residual)
        // add penalty that shrinks for large items or crowded states
        score += 30.0 - 25.0 * big_item;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits, must open
        }
    }

    // Congestion modulation: many open bins with high mean residual ->
    // prefer consolidating into existing bins (reward this bin more when
    // its residual is below mean, penalize when above).
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.10 * diff; // below-mean residual bins get lower score
    }

    // Stream progression: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - frac);

    // Modulo harmonic class: leftover divisible into common item sizes
    // (10/20/25/50) is reusable -> reward.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 6.0;
    }
    // Odd leftover classes are harder to fill -> mild penalty.
    if pr % 2 == 1 && pr > 15 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: gaps too small for the smallest plausible item are waste.
    let min_item = 1u32;
    if post_residual < min_item + item_size.min(10) {
        // Unusable sliver -> heavy penalty scaled by how close it is to a "wasted" gap.
        score += 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64 / item_size as f64);
        score -= 8.0 * tightness.max(0.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement; mild penalty if we create near-miss.
        score += 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 6.0 + 1.5 * open_bins_count as f64;
        // But if mean residual across open bins is large, opening fresh is less costly.
        score -= 0.05 * mean_residual;
    }

    // Slight preference to fill bins with larger residual early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match of post_residual with next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nr).abs();
        if diff < 0.5 {
            score -= 60.0; // exact match: next item fills this bin perfectly
        } else if pr >= nr {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64); // next item still fits
        } else {
            score += 10.0 + diff; // dead space relative to lookahead
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 40.0;
    }

    // Prefer filling bins below mean residual (tackle cluttered bins first)
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: only bin that can fit the item
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        let tight_fit_exists = (bin_capacity as f64 - item_size as f64 - mean_residual).abs() < 15.0;
        if fitting_bins_count > 0 && !tight_fit_exists {
            score += 25.0;
        }
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs() < 1.0 {
            score -= 20.0; // fresh bin will be perfectly packed by next item
        }
    }

    // Reward high fill ratio
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Mild stream-progression pressure to consolidate late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post residual
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Dead space penalty: residuals too small for the smallest item are wasted
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: penalize if next item cannot fit post residual but could fit elsewhere
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 12.0;
        } else if next_item_size == post_residual {
            score -= 30.0; // perfect lookahead fill
        } else {
            score -= 8.0;
        }
        // reward bins whose leftover matches next item size distribution scale
        let compat = (post_residual as f64 - next_item_size as f64).abs();
        score += compat * 0.15;
    }

    // New-bin candidate handling: empty bin starts from a high baseline
    if bin_residual == bin_capacity {
        // opening a new bin is fine when no good fit exists or bin count is low
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += 35.0 + pressure + (open_bins_count as f64 * 2.0);
        // early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Global state coupling: prefer bins below mean residual (keep large residuals available)
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // Mild preference for consolidating among many open bins
    score += open_bins_count as f64 * 0.5;

    // Reward near-exact fills relative to capacity
    let fill_ratio = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * fill_ratio * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // base: prefer low post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // smooth stream-progress coupling: early on tolerate slack, later tighten
    score += 25.0 * progress * norm_pr * norm_pr;

    // reward tight fits more strongly as stream progresses (smooth interaction)
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // penalize when bin deviates from mean residual (non-linear coupling)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // lookahead: reward leaving room for the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit = (pr - nxt).abs();
        score += 0.15 * fit;
        score -= 12.0 * (-fit / 20.0).exp() * (0.5 + 0.5 * progress);
    }

    // last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space that is a multiple of 10
    // is more likely reusable by future items (sizes 1..=100, common classes).
    let post_class = post_residual % 10;
    let post_div = post_residual / 10;

    // Reward residuals that fall into "harmonic" classes (small remainders).
    score -= (10 - post_class) as f64 * 0.8;
    // Penalize very small unusable remainders (1..=4 dead space).
    if post_class >= 1 && post_class <= 4 {
        score += 6.0;
    }

    // Perfect fit: empty residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Next-item lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let nxt_class = (post_residual - next_item_size) % 10;
            // Reward closeness of next item to remaining space.
            score -= (post_residual - next_item_size) as f64 * 0.3;
            if nxt_class == 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot fit here; slight penalty for leaving big gap.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Integer-division thresholds on post_residual: bins with residual in
    // [10, 30] are prime targets for small items; keep them attractive.
    if post_div >= 1 && post_div <= 3 {
        score -= 8.0;
    } else if post_div >= 7 {
        // Nearly empty bin: little urgency, mild penalty so fuller bins win.
        score += (post_div as f64 - 6.0) * 2.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = open_bins_count as f64 * item_size as f64 / bin_capacity as f64;
        // Prefer new bins early or when open bins are crowded on average.
        score += 12.0 - 10.0 * progress - tight.min(12.0);
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (fuller bins).
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 3.0 * post_residual as f64;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual can still host the lookahead item exactly-ish.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // post_residual cannot fit next item: mild dead-space penalty scaled by gap size.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += 0.15 * open_bins_count as f64 * (1.0 + post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean residual (better consolidation).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // New-bin candidate: neutral baseline; only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // next item still fits after this placement
            let slack_after_next = post_residual - next_item_size;
            score -= 60.0 - (slack_after_next as f64).min(50.0);
        } else {
            // next item would NOT fit here; penalize leaving a small dead zone
            let gap = (next_item_size - post_residual) as f64;
            if post_residual < 10 {
                score += 80.0; // unusable dead space
            } else {
                score += gap * 0.5;
            }
        }
    }

    // Tightness relative to mean residual: prefer bins tighter than average
    let res = bin_residual as f64;
    score += (res - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Prefer opening a new bin only when no open bin fits well
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline score of full capacity
        score = bin_capacity as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 500.0; // next item needs a fresh bin anyway
        }
        if fitting_bins_count == 0 {
            score -= 250.0;
        }
    }

    // Slight preference to keep bin count low late in the stream
    score += (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 40.0;

    // Penalize dead space that no future item (min size 1..~10) could use.
    if post_residual < 10 && post_residual > 0 {
        score -= 25.0; // nearly perfect fill
    } else if post_residual > 0 && post_residual < item_size {
        score += 5.0; // small awkward gap
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 0.3 * (next_item_size as f64);
        } else {
            // next item won't fit here; slight penalty for wasting space
            score += 0.1 * (post_residual as f64);
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > 50.0 && open_bins_count > 3 {
        score += 10.0 * (1.0 - tightness);
    }

    // New-bin candidate: only attractive when no good existing option.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        score += 30.0 + crowding * 2.0 - progress * 20.0;
        if fitting_bins_count <= 1 {
            score -= 70.0; // opening new bin is reasonable when alternatives are bad
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual == bin_capacity {
            score -= 15.0; // fresh bin can host a pair of large items
        }
    }

    // Time horizon: early on, be pickier about tight fits; late, just fill.
    score -= (1.0 - progress) * 5.0 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Non-linear coupling of post-residual with stream progress:
    // late in the stream, tight fits matter more; early, waste is cheaper.
    score += 25.0 * norm_post * progress * (1.0 - progress) * 4.0;

    // Reward near-perfect fits with a smooth polynomial bonus.
    let fit_quality = 1.0 - norm_post;
    score -= 15.0 * fit_quality * fit_quality * fit_quality;

    // Penalize creating dead space that likely cannot host the next item.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).max(0.0);
        let usable = if post >= next_item_size as f64 { 1.0 } else { 0.0 };
        score += (1.0 - usable) * 10.0 * norm_post;
        score += 3.0 * (gap / cap) * (gap / cap);
    }

    // Last-chance bin: smooth bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_post);
    }

    // Slight preference for bins below mean residual (balance residuals smoothly).
    score += 2.0 * ((post - mean_residual) / cap).tanh();

    // Mild pressure against opening new bins when many bins are open late.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress + (open_bins_count as f64).sqrt();
        if fitting_bins_count > 0 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: quantize post_residual into capacity/10 classes.
    let class = (post_residual / (bin_capacity / 10)).min(10);
    score += class as f64 * 0.8;

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here; penalize wasting a scarce bin.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when current bins are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual / bin_capacity as f64;
        score = 100.0 - 80.0 * (1.0 - tight) + 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative, must open
        }
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=9) are essentially unusable
    // for items of size >= 10, so penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual as i32 as f64) * 4.0;
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins slightly,
    // but this also makes new-bin candidate less attractive as bins pile up.
    score += open_bins_count as f64 * 0.35;

    // Prefer bins whose residual is close to the item (relative fit quality).
    if bin_residual > 0 {
        let waste_ratio = (bin_residual - item_size) as f64 / bin_residual as f64;
        score += 10.0 * waste_ratio * waste_ratio;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: mild dead-space penalty.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the fit into open bins would be poor. Compare
    // against mean residual: if mean residual is high, opening new bins is
    // less necessary.
    if bin_residual == bin_capacity {
        // New bin baseline: keep some positive cost so it's chosen only
        // when open bins score worse.
        score += 20.0;
        score -= mean_residual * 0.1;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            score -= 25.0; // next item still fits after placement
            // prefer tighter leftover after the chain
            score -= (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize dead space: small post_residual that cannot host typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Compare residual against mean residual: bins tighter than average are attractive.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize unusable dead space: post_residual too small for typical future items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
            // Extra bonus if next item exactly complements.
            if next_item_size == post_residual {
                score -= 15.0;
            }
        } else {
            // Dead space relative to the lookahead item.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer fuller bins (smaller post residual handled above).
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Global state: penalize contributing to bin sprawl when many bins are open.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins whose residual deviates from the mean (consolidate fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.3 * dev;

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // is large and no good fit exists (fit_ratio low everywhere), or early stream.
    if bin_residual == bin_capacity {
        let urgency = (item_size as f64 / bin_capacity as f64).powf(2.0);
        let new_bin_bonus = 45.0 * urgency - 10.0 * (1.0 - progress);
        score -= new_bin_bonus;
        // But if a last-chance bin exists, opening new is bad.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
    }

    // Mild time coupling: late in the stream, prefer compacting into existing bins.
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress + 0.4 * progress);

    // Reward tight fits via cubic term on normalized post-residual
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space relative to mean residual
    if pr as f64 > mean_residual {
        score += 0.5 * (pr - mean_residual);
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let gap = if pr >= next_item_size as f64 { pr - next_item_size as f64 } else { pr + cap };
        score += 0.3 * gap;
    }

    // Mild pressure to prefer open bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize waste into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i32; // 8 harmonic classes of waste

    // Reward tight fits: heavily discount small waste classes.
    match class {
        0 => score -= 40.0,             // near-perfect fit (waste < 12.5%)
        1 => score -= 25.0,             // good fit
        2 => score -= 12.0,             // moderate fit
        3 => score -= 4.0,              // acceptable
        4 => {},                        // neutral
        _ => score += (class as f64 - 4.0) * 6.0, // penalize large dead space
    }

    // Integer-division threshold: post_residual that can still host common small items
    // (harmonic sizes 10/20/25/50) is valuable; penalize residuals in "dead zones".
    let dead_zone = |r: u32| -> bool {
        (1..10).contains(&r) || (11..20).contains(&r) && r < 12
    };
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }
    if post_residual >= 10 && post_residual < 20 && next_item_size > post_residual {
        score += 5.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - slack.min(18.0) * 0.5;
        if (post_residual - next_item_size) == 0 {
            score -= 20.0; // perfect chaining
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity - item_size {
        score -= 10.0;
    }

    // New-bin candidate: neutral-ish score anchored on mean residual of open bins.
    // Prefer opening a new bin when existing bins would waste a lot.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5 - mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // Early in the stream, opening fresh bins is cheaper (more future items to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Crowd penalty: with many open bins, prefer consolidating into fuller bins.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: fraction of bin filled by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 20.0 + 4.0 * open_bins_count as f64;
        // But allow opening a fresh bin if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Lookahead: if next item could use the post residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mild alignment with mean residual: prefer bins below mean residual (tighter).
    score += 0.05 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 30.0;

    // 2-step lookahead: exact match of post_residual with next item is gold
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot fit here; penalize wasted chain opportunity
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    } else {
        // last item: just minimize post_residual strongly
        score -= 15.0;
    }

    // Penalize dead space far from mean residual (fragmentation)
    score += (post_residual as f64 - mean_residual).abs() * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins are too full
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 40.0 };
        score += 45.0 * pressure + lookahead_bonus;
    }

    // Early stream: allow more bins; late stream: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 - progress * 2.0;

    // Prefer bins with larger residual when post_residuals tie (keep small slivers usable)
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 10.0;
        }
        // Perfect chain fit: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 20.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; make the
    // empty-bin call less attractive unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, discourage opening extra bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins already below mean residual (consolidating waste).
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Mild preference for fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - (bin_residual as f64) / cap);

    // Slight penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress) - pr_norm * (1.0 - progress);
    score += 20.0 * coupling;

    // Penalize tight fits more as stream progresses (dead space matters later)
    score += progress * (pr_norm * pr_norm) * 15.0;

    // Reward last-chance bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 20.0 * progress;
    }

    // Lookahead: favor bins whose post_residual fits next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 5.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Discourage spreading when many open bins
    score += (open_bins_count as f64) * 0.05 * pr_norm;

    // New-bin candidate: prefer opening new bin only for large items / late stream
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = cap - fill * cap * (0.6 + 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // --- Harmonic class of the post residual (mod-10 residue classes) ---
    // Residues that are hard to fill later get penalized.
    let residue = post_residual % 10;
    score += residue as f64 * 0.4;

    // Dead-space band: leftover too small for the minimum plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fill: strongest reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fits (small post residual but nonzero) are still good.
    if post_residual > 0 && post_residual <= 10 {
        score -= 12.0;
    }

    // --- Capacity fraction thresholds ---
    let fill_frac = item / cap;
    if fill_frac > 0.7 {
        score -= 8.0 * (fill_frac - 0.7); // reward large-item placements
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation). ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // --- Lookahead (k=2): reward bins whose post residual can host next item ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 {
            // leftover likely wasted relative to the known future demand
            score += 6.0 + 0.15 * ((next_item_size - post_residual) as f64);
        }
    }

    // --- Brand-new empty bin candidate ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: high enough that decent open-bin fits win,
        // but low enough to beat bins that would create large dead space.
        score = post + 35.0 - 0.2 * item;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // Many open bins with slack: discourage another bin.
        if mean_residual > item {
            score += 5.0;
        }
    }

    // Mild coupling with mean residual: prefer bins tighter than average.
    score += 0.1 * (mean_residual - post).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // If next item fits exactly into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - tightness / 40.0).max(0.0);
    }

    // Last-chance bonus: only one bin can fit the item; keep it usable.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure against opening new bins: brand-new bin gets a penalty
    // scaled by how many bins are already open and stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 3.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        // Mildly prefer bins with lower residual than the mean (consolidation).
        score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 25.0; // perfect two-item packing
        }
        // Penalize leaving residuals the next item cannot ever use well
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer bins whose post state tracks the mean
    score += 0.4 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize tiny dead space (<10) which is hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits or residual is tiny
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 45.0 + 0.5 * mean_residual;
        }
    }

    // Slight preference for tighter bins early in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 0.2 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post-residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // penalize bins that would leave dead space unusable by the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: excellent, especially if next item nearly fills the rest.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Dead space relative to next item size.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0 + 0.2 * (bin_residual - item_size) as f64;
    }

    // Penalize leaving very small unusable fragments (< 10 is dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Time horizon: early in the stream, be pickier (penalize wasteful bins),
    // late in the stream, prioritize consolidation of open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.10 * post_residual as f64;

    // Global state: if many bins are open with large mean residual, opening
    // new bins is wasteful; conversely if residuals are small, prefer new bin.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.05 * mean_gap * (open_bins_count as f64).ln().max(1.0);

    // Mild penalty for using a fresh empty bin when open bins exist that fit.
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 6.0 + 0.05 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, sharpened as stream progresses
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;

    // Smooth non-linear coupling: post_residual vs mean residual deviation
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * (1.0 - progress);

    // Lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = (post_residual - next_item_size) as f64 / cap;
        score -= 20.0 * (1.0 - fit_quality) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Dead space that cannot host the lookahead item
        score += 10.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize the brand-new empty bin candidate smoothly, less so early on
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / cap).powi(2);
        score += (30.0 - 20.0 * progress) * (1.0 - tightness);
        // Reward opening a new bin for large items that leave little waste
        score -= 12.0 * tightness * progress;
    }

    // Mild preference for bins with lower residuals (best-fit flavor, smooth)
    score += 0.05 * (bin_residual as f64 - item_size as f64) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) are gold; small dead space is bad.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows quadratically for tiny residuals.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 8.0;
        }
        // Modulo classes: residuals congruent to 0 mod 10 pair well with typical sizes.
        let pr_mod = post_residual % 10;
        if pr_mod == 0 {
            score -= 12.0;
        } else if pr_mod == 5 {
            score -= 4.0;
        } else {
            score += pr_mod as f64 * 0.5;
        }
    }

    // Integer-division threshold on post_residual: usable leftover buckets.
    let bucket = post_residual / 10; // 0..10
    score += (10 - bucket) as f64 * 2.0;

    // Lookahead: favor bins whose post_residual can host next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            score += 6.0;
        }
        // Perfect two-item chain: post_residual == next_item_size exactly.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize fresh bins unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 60.0
            + mean_residual * 0.3
            + (open_bins_count as f64) * 2.0;
        // Early in stream, new bins are cheaper; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 20.0;
    }

    // Tight-fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Mild pressure toward denser bins (low residual relative to mean).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps that likely cannot fit future items).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins that can also fit the lookahead item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 0.3;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Discourage opening a new bin when a reasonable fit exists in an open bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin attractive only if item is large relative to capacity or few bins fit.
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if !large_item && fitting_bins_count > 0 {
            score += 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        if total_items > 0 && (step_index as f64 / total_items as f64) > 0.7 {
            score += 10.0;
        }
    }

    // Slight preference for bins below mean residual (tighter bins used first).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but penalize leftover dead space after both items.
            let second_leftover = post_residual - next_item_size;
            score += second_leftover as f64 * 0.3;
        } else {
            // Next item won't fit here; penalize bins whose residual is close
            // to but smaller than next_item_size (unusable dead space).
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += gap as f64 * 1.5;
            }
        }
    }

    // Compare residual to mean residual across open bins: prefer bins that
    // are already more filled than average.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a brand-new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0 + mean_residual * 0.1;
    }

    // Early in the stream, be slightly more willing to keep bins balanced;
    // later, prioritize tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead coupling: reward bins whose post_residual fits the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - lookahead_waste / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this residual: mild penalty, stronger late in stream.
        score += 8.0 * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
        if post_residual < 5 {
            score += 15.0; // but not for near-perfectly-full bins
        }
    }

    // Reward using bins with large residuals (consolidate space) early on.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate handling: an empty bin has large post_residual naturally,
    // so it already scores high; add extra damping so it's chosen only when open
    // bins are crowded or fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Mild pressure to keep the number of open bins in check as stream grows.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Base: post_residual, with non-linear polynomial shaping of waste.
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Reward tight fits: quadratic coupling between post_residual and item size.
    let it = item_size as f64;
    let tightness = (it / cap) * (1.0 - x);
    score -= 12.0 * tightness * tightness;

    // Stream-progress coupling: later in the stream, waste is more costly.
    score += 6.0 * progress * x * x;

    // Lookahead: penalize if next item cannot use the post-residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            // Next item won't fit here; dead space penalty, stronger late.
            score += (2.0 + 4.0 * progress) * (nx - pr) * 0.05;
        } else {
            // Next item fits: reward leaving exactly usable space.
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        }
    } else {
        // Last item: strongly prefer minimal final residual.
        score += 2.0 * x;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 6.0 * progress;
    }

    // Many open bins: slight penalty to discourage bin proliferation.
    score += (open_bins_count as f64).sqrt() * 0.15;

    // Mean-residual coupling: prefer bins whose residual deviates from mean
    // in a way that consolidates space (large residual bins are more useful).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Default: opening a new bin is moderately penalized so tight fits win,
        // but it stays competitive when post_residual elsewhere is large.
        score = pr + 10.0 + poor_fit_elsewhere * 20.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 classify dead space
    let class = post_residual % 10;
    // Small unusable residues (1..9 that can't host typical items) are penalized
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space: nothing can ever fit
    } else if class == 0 {
        score -= 8.0; // perfectly divisible residual is highly reusable
    } else if post_residual >= 50 {
        score -= 6.0; // half-full bin: plenty of room left
    }

    // Integer-division threshold classes on post_residual
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        score += 10.0; // very tight bin after placement
    }

    // Lookahead coupling: can next item fit in the post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward exact/near-exact chaining (harmonic match)
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 15.0;
            } else {
                score -= (slack as f64).min(20.0) * 0.3;
            }
        } else {
            score += 12.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // prefer the bin with the least waste among many candidates
        score += (fitting_bins_count as f64) * 0.5;
    }

    // New-bin candidate: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize opening new bins unless mean residual is small and stream is late
        score += 30.0 * (1.0 - pressure) * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if post_residual as f64 > mean_residual + 10.0 && open_bins_count > 0 {
            score += 15.0;
        }
    }

    // Prefer filling bins tighter than the current mean residual
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are never dead, but residuals that are small yet
    // nonzero relative to typical item sizes are wasted capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_threshold = 12.0 + 6.0 * (1.0 - progress); // stricter late in stream
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6) * 20.0;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bins pressure: penalize spreading across many open bins,
    // encouraging consolidation; but relax pressure as stream progresses.
    score += open_bins_count as f64 * (1.0 + 0.5 * (1.0 - progress));

    // Deviation from mean residual: prefer bins whose residual deviates
    // from the mean (large residual bins absorb big items better).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item can exactly fill this bin's post
    // residual, big reward; if next item won't fit post residual,
    // mild penalty for stranding the bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 5.0;
        }
    }

    // New-bin candidate: make empty bins moderately attractive so we open
    // a new bin only when existing fits are poor, but discourage opening
    // new bins when few bins are open or the item fits reasonably well.
    if bin_residual == bin_capacity {
        let base = 45.0;
        let fit_pressure = if fitting_bins_count > 0 { 25.0 } else { 0.0 };
        score = base + fit_pressure + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: reward tight fits (small post_residual) more than linearly.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 0.8 * frac * frac * (bin_capacity as f64);

    // Aggressive 2-step lookahead: exact match of post_residual with next item is gold.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // reward leaving room for next item, penalize gap size
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            // penalize dead space next item cannot use
            score += 0.4 * gap;
        } else {
            // next item can't fit in leftover: dead space penalty
            let dead = (next_item_size - post_residual) as f64;
            score += 0.6 * dead;
        }
    }

    // Compare residual against mean residual across open bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev; // prefer below-average residual (tighter bin)

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is very poor
    // or lookahead demands fresh space.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.45 * (bin_capacity as f64);
        let lookahead_needs = next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 8;
        score += if poor_fit { 5.0 } else { 45.0 };
        if lookahead_needs { score -= 30.0; }
    }

    // Early in stream: be slightly conservative, keep bins balanced.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);

    // Late stream: squeeze remaining space harder.
    score -= 10.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio penalization (dead space).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 12.0;

    // Penalize very small post-residuals that are unusable (< 10% of capacity)
    // unless it's an exact fit.
    if post_residual > 0 {
        let dead = if post_residual < bin_capacity / 10 { 1.0 } else { 0.0 };
        score += dead * 8.0 * (1.0 - tightness);
    } else {
        // Perfect fit strongly rewarded.
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward;
    // if the next item would fit better in a fresh bin, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let pair_eff = (item_size + next_item_size) as f64 / bin_residual as f64;
            score -= 6.0 * pair_eff;
        } else {
            // Next item won't fit here after placement; mild penalty scaled
            // by how close post_residual is to being useless.
            let waste = post_residual as f64 / next_item_size as f64;
            score += 4.0 * (1.0 - waste.min(1.0));
        }
    } else {
        // Last item of the stream: any bin works, prefer tightest.
        score -= 5.0;
    }

    // Time horizon: late in the stream, be more conservative about opening
    // new bins (fewer chances to fill them), so favor existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 6.0 * progress;
        // Only open a new bin if existing fit is poor relative to mean residual.
        if (bin_residual as f64 - item_size as f64) > mean_residual * 1.5 {
            score -= 4.0;
        }
    } else {
        score -= 3.0 * progress;
    }

    // Global state: many open bins with high mean residual -> encourage
    // consolidating into existing bins rather than opening more.
    if open_bins_count > 2 && mean_residual > item_size as f64 * 1.2 && bin_residual < bin_capacity {
        score -= 2.5;
    }

    // Prefer bins whose residual is close to item size (best-fit flavor)
    // with a nonlinear squash.
    let gap = (bin_residual as i64 - item_size as i64) as f64;
    score += (gap / bin_capacity as f64).powi(2) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let nx = next_item_size as f64;

    // Base: prefer small post-residual, with smooth polynomial shaping.
    let x = pr / cap;
    let mut score = 2.0 * x + 3.0 * x * x + 4.0 * x * x * x;

    // Smooth coupling of post-residual with stream progress:
    // late in the stream, dead space matters more (bins won't be reused).
    score += (1.0 + 2.0 * progress) * x * x * cap * 0.05;

    // Perfect-fit reward: quadratic trough near zero post-residual.
    score -= 6.0 * (1.0 - x).powi(8);

    // Penalize post-residual that cannot fit the lookahead item (smooth ramp).
    if nx > 0.0 {
        let gap = (nx - pr).max(0.0) / cap;
        score += 8.0 * gap * gap * cap * 0.1;
        // Reward leaving exactly enough room for the next item (smooth Gaussian).
        let d = (pr - nx) / cap;
        score -= 5.0 * (-d * d * 400.0).exp();
    }

    // Last-chance bin: avoid opening a new bin unless this fit is very poor.
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * (1.0 - x);
    }

    // Mild penalty when this bin's residual is far below the mean (waste elsewhere).
    let mean_x = mean_residual / cap;
    score += 2.0 * (x - mean_x).abs();

    // New-bin candidate (pristine residual): keep it attractive only for large items
    // that would leave open bins badly fragmented; otherwise discourage.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * (item_size as f64 / cap);
        score += 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "clean" the leftover space is.
    // Residuals divisible by 10 or 25 pair well with common item sizes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Penalize small unusable leftovers (dead space) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - pr / 10.0);
    }

    // Reward "harmonic" residuals: multiples of 10 leave room for typical items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does the post-residual accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact harmonic match with next item: strong reward.
            if post_residual == next_item_size {
                score -= 45.0;
            } else {
                score -= 12.0 * (next_item_size as f64 / cap);
            }
        } else {
            // Leftover too small for next item: penalize proportionally to wasted space.
            score += 10.0 * (1.0 - frac);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // or no good fit exists. Penalize opening bins early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        // Prefer new bins for big items; penalize more as stream progresses.
        score += 25.0 + 30.0 * progress - 20.0 * item_frac;
        // If many bins can fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Mild preference for tighter bins overall (low residual = better packing).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space zone: residuals too small for the minimum item (1..=9) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward if post_residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // creates a gap that cannot host next item
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling existing bins when many bins are open.
    score += open_bins_count as f64 * 0.6;

    // Prefer bins with small residual (tight fit) relative to mean.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: make it moderately attractive only when item barely fits
    // existing residual patterns, otherwise keep it penalized.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item fits the post-residual exactly (perfect 2-step match)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits, but reward tighter matches more
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0);
        } else {
            // next item won't fit in this bin's remainder: penalize leftover dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Reward near-perfect fills of the current bin (small post_residual)
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual > 40 {
        // large dead space is wasteful
        score += (post_residual - 40) as f64 * 0.8;
    }

    // Prefer bins whose residual is already below average (tighter bins fill first)
    score += 0.6 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in the stream, encourage opening/filling bins aggressively (less penalty for new bins)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless few bins open or post-residual would fit next item well
        let mut new_bin_penalty = 20.0 + 30.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    // Slight preference for keeping the number of open bins bounded
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small dead space is fine-ish, slight reward
    } else if post_residual >= 10 && post_residual < 40 {
        score += 5.0; // moderate gap moderately wasteful
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large relative to the item (poor fits available)
    // or the item is large and would leave a big gap elsewhere.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bin when open bins are crowded (mean residual small)
        // and late in the stream; penalize early stream bin proliferation.
        score += 10.0 + open_bins_count as f64 * 0.5;
        score -= mean_gap.max(0.0) * 0.6;
        score -= progress * 8.0;
        // If lookahead item is small, a fresh bin can host it later: mild bonus.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 6.0;
        }
    } else {
        // Favor bins whose residual after placement still fits the lookahead item.
        if next_item_size > 0 {
            if (next_item_size as u32) <= post_residual {
                score -= 8.0;
            } else {
                score += 3.0;
            }
        }
        // Slight preference for bins tighter than average (best-fit flavor).
        let resid_dev = bin_residual as f64 - mean_residual;
        score += resid_dev * 0.15;
    }

    // Time-horizon coupling: early on, be conservative with gaps; later,
    // prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual (tight fit), scaled by progress
    let mut score = post * (0.5 + progress);

    // Smooth non-linear coupling: quadratic penalty on large leftover space,
    // weighted by stream progress (dead space matters more late in the stream)
    score += 20.0 * norm_post * norm_post * (0.3 + 0.7 * progress);

    // Cubic interaction between post_residual and mean residual:
    // penalize leaving residual far from the mean (fragmentation)
    let dev = (post - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 + norm_post);

    // Last-chance bonus: if this is the only fitting bin, reward usage strongly
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Lookahead coupling: reward if next item fits smoothly in the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let fit_next = if post >= nxt { 1.0 } else { 0.0 };
        // smooth reward for next-item compatibility, non-linear in gap
        score -= fit_next * 8.0 * (1.0 - gap / cap).max(0.0);
        // penalize residuals that are too small for the next item but not tiny
        if post < nxt && post > 0.0 {
            score += 5.0 * (nxt - post) / cap * (0.5 + progress);
        }
    }

    // Mild penalty on opening many bins: smooth function of open bin count
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * (open_bins_count as f64).sqrt() - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fits are golden.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Classify post_residual by divisibility against common item sizes.
        // A residual divisible by many small sizes is reusable; odd/large primes are dead.
        let mut divis = 0u32;
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 { divis += 1; }
        }
        score -= 8.0 * divis as f64;

        // Dead space: residual too small for the minimum item (assume ~10).
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        }

        // Harmonic match with lookahead: residual exactly fits next item -> excellent.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 300.0;
            } else if post_residual >= next_item_size {
                // Bonus proportional to how snugly next item fits.
                let slack = (post_residual - next_item_size) as f64;
                score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            } else {
                // Residual can't fit next item: penalize by closeness to next item.
                let gap = (next_item_size - post_residual) as f64;
                score += 15.0 * (1.0 - gap / bin_capacity as f64);
            }
            // Modulo harmony: residual is a multiple of next item size.
            if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
                score -= 20.0;
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 120.0;
        } else {
            score += 5.0 * (fitting_bins_count as f64 - 1.0);
        }

        // Tightness reward: fractional fill of the bin.
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= 50.0 * fill * fill;

        // Early in stream: keep bins flexible (prefer balanced residuals).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 4.0 * dev * (1.0 - progress);

        // Many open bins: discourage spreading too thin; favor filling existing ones.
        score += 2.0 * open_bins_count as f64 * (1.0 - fill);

        // New-bin candidate penalty unless residual is tiny (i.e., current bins are fragmented).
        if bin_residual == bin_capacity {
            // Opening a new bin is good only if mean residual is small (existing bins nearly full)
            // or the item is huge and would leave a bad leftover elsewhere.
            let mean_r = mean_residual;
            let would_leave_bad = post_residual < 10 && post_residual > 0;
            if mean_r > 30.0 && !would_leave_bad {
                score += 200.0;
            } else {
                score += 40.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Last chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // New empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 25.0 + mean_residual * 0.3 };
        score += desperation;
    }

    // Mild preference for tighter bins overall.
    score += (mean_residual - bin_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let waste_next = (post_residual - next_item_size) as f64;
        score -= 25.0 + 2.0 * (post_residual as f64 - waste_next) - waste_next;
        // exact fit bonus
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize dead space relative to next item size
        let gap = (next_item_size - post_residual) as f64;
        score += 0.3 * gap;
    }

    // penalize large dead space relative to mean residual
    score += 0.2 * (post_residual as f64 - mean_residual).max(0.0);

    // last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // new-bin candidate: mild penalty so we prefer reusing bins with decent fits
    if bin_residual == bin_capacity {
        score += 10.0;
        // but if item is large relative to mean residual, opening new bin is fine
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    }

    // late in stream: tighten packing, prefer fuller bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more strongly than linear.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable slivers are wasted space
    }

    // Lookahead: if the next item fits the post residual exactly-ish, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - waste / (bin_capacity as f64));
        } else {
            // next item won't fit here; mildly penalize if this bin is the only option
            if fitting_bins_count == 1 {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: prefer filling a bin that would otherwise be left nearly empty.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Global balance: prefer bins with residual below mean (consolidate space).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Prefer denser bin sets early; as stream progresses, favor using existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * 3.0 * (bin_residual as f64 / (bin_capacity as f64));

    // New-bin candidate: make it attractive only when open bins are fragmented or fit is bad.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / (bin_capacity as f64);
        let bad_fit = (item_size as f64) / (bin_capacity as f64) < 0.25;
        if fragmentation > 0.6 && bad_fit {
            score -= 4.0; // open fresh bin for small item when bins are fragmented
        } else {
            score += 15.0 + 10.0 * (1.0 - t); // early on, discourage opening new bins
        }
    }

    // Mild pressure against spreading across many bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth polynomial shaping
    let mut score = pr;

    // Non-linear penalty on tiny-but-nonzero dead space (unusable fragments),
    // strongest when residual is below half capacity, smooth via polynomial.
    let frag = norm_pr * (1.0 - norm_pr); // peaks at 0.5
    score += 12.0 * (1.0 - 4.0 * frag) * norm_pr * norm_pr;

    // Stream-progress coupling: early on, waste matters less; later, tighten packing.
    score += 8.0 * progress * norm_pr * norm_pr;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward bins whose post residual fits the next item (k=2 lookahead).
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 + 4.0 * progress;
    } else if next_item_size > 0 {
        // Penalize leaving a residual just barely below the next item (near-miss waste)
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 10.0 * gap * (1.0 - gap);
    }

    // Perfect fit reward (smooth quadratic around zero residual)
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Mild preference for consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate handling: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score = pr + 20.0 * (1.0 - progress) - 10.0 * (fitting_bins_count as f64).min(3.0) / 3.0;
        if next_item_size > 0 {
            score += 4.0 * (next_item_size as f64 / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that sit in
    // "usable" classes (multiples of 10 / high-divisibility classes).
    let pr = post_residual;
    let class = pr % 10;
    let div_bonus = match class {
        0 => 14.0,
        5 => 7.0,
        2 | 4 | 6 | 8 => 3.0,
        _ => 0.0,
    };
    score -= div_bonus;

    // Integer-division thresholds: residuals <= 20 are near-dead space,
    // penalize proportionally; residuals >= 40 are still flexible.
    if pr <= 20 && pr > 0 {
        score += 18.0 * (21.0 - pr as f64) / 20.0;
    } else if pr >= 40 {
        score -= 6.0;
    }

    // Perfect fit is always best.
    if pr == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item can exactly fill this bin's
    // post-residual, this placement is part of a perfect packing chain.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next item fits: mild reward scaled by tightness
            score -= 10.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here: penalize tight leftover a bit
            score += 8.0;
        }
        // Harmonic check: post_residual % next_item_size small => future fit likely
        if next_item_size > 0 && pr % next_item_size.max(1) <= 3 {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: empty bins should only win when open bins
    // would leave bad dead space or don't exist.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, relaxed when stream is early
        // or many items remain and open bins are already fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 30.0 + 40.0 * progress;
        if mean_residual < item_size as f64 {
            penalty -= 20.0; // open bins are too full anyway
        }
        if open_bins_count == 0 {
            penalty = -100.0; // must open
        }
        score += penalty;
    }

    // Slight preference for fuller bins (best-fit flavor) via mean residual.
    if (bin_residual as f64) > mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than leaving them half-empty.
    let pressure = (open_bins_count as f64) * 0.8;
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: only attractive when it yields a very tight fit
        // or when existing bins would leave large dead space.
        let tight_fit = (bin_capacity as f64 - item_size as f64) <= 5.0;
        if !tight_fit {
            score += 25.0 + pressure;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for wasting gap space.
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.3;
    }

    // Mean-residual coupling: if this bin's post residual is far below the
    // mean residual, it is being packed tighter than average -> reward.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= (mean_residual - post_f) * 0.4;
    } else {
        score += (post_f - mean_residual) * 0.2;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (consolidation matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space non-linearly: small post-residuals are valuable,
    // large ones are increasingly wasteful.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // 2-step lookahead: reward bins whose post_residual closely matches the
    // next item size (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        let match_bonus = 40.0 / (1.0 + gap);
        score -= match_bonus;
        // Exact fit for the next item: strong reward.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item in the stream: prefer filling bins as tightly as possible.
        score -= 10.0;
    }

    // Relative to mean residual: bins tighter than average are precious,
    // looser bins are natural targets.
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: make an empty bin unattractive unless the
    // item fits very poorly everywhere else (large item, tight stream).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // Large items are hard to place later; open a fresh bin for them
        // when few bins fit.
        if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 45.0;
        }
        // Late in the stream, opening new bins is less costly (fewer future
        // items to consolidate), so relax the penalty.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
    }

    // Slight preference for bins that are already heavily loaded
    // (best-fit flavor beyond raw post_residual).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 12.0;

    // Penalize dead space that is too small to be useful (below min item size 1..small).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64) * 0.05;
    } else if next_item_size > post_residual {
        // Next item cannot follow here; mildly penalize leaving a stranded gap.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer filling bins when many bins are open (reduce bin proliferation).
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= open_pressure * (bin_capacity - bin_residual) as f64 * 0.03;

    // Global residual balance: penalize bins whose residual deviates strongly from mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Time horizon: late in the stream, be more aggressive at closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Prefer using emptier bins early (keep tight bins free for small items).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin unless current fits are terrible.
        score += 18.0;
        // Late in the stream, opening new bins is even less attractive.
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear base: quadratic penalty on post_residual,
    // modulated by stream progress.
    let mut score = pr * (1.0 + 0.9 * progress * norm_pr);

    // Dead-space aversion: small post_residuals are good, but if the next
    // item cannot use the leftover, penalize smoothly.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        let usable = (pr / next_item_size as f64).min(1.0);
        score += gap * 0.35 * (1.0 - usable);
        score -= 6.0 * usable * usable;
    } else {
        score -= 4.0; // last item: prefer tight fill
    }

    // Last-chance bonus: only one fitting bin -> reward using it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Penalize bins far from the mean residual (smooth dispersion coupling).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    // Slight preference for consolidating into fewer bins early on.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make empty bins mildly unattractive unless
    // the item fits terribly everywhere (handled by last-chance term).
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals in small classes are "dead space"
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Integer-division thresholds on post_residual: classify leftover space
    // class 0: post <= 10 (likely dead), class 1: post <= 25, class 2: larger
    let dead_zone = if post_residual <= 10 {
        1.0
    } else if post_residual <= 25 {
        0.5
    } else {
        0.0
    };
    score += dead_zone * 60.0;

    // Modulo arithmetic on post_residual: residuals near capacity fractions pair well
    // with common small item sizes (harmonic classes of capacity 100)
    let classes: [u32; 6] = [10, 20, 25, 33, 50, 100];
    let mut harmonic_bonus = 0.0;
    for c in classes.iter() {
        if post_residual % c == 0 && post_residual > 0 {
            harmonic_bonus += 8.0;
        }
    }
    score -= harmonic_bonus;

    // Lookahead coupling: reward residuals that can exactly fit the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual >= next_item_size {
            // reward proportionally, favor tight next fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot fit here; penalize proportionally to wasted potential
            score += 15.0;
        }
    }

    // Last chance bin: if this is the only fitting bin, prefer using it over a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits
    if bin_residual == bin_capacity {
        // base penalty so new bins aren't opened frivolously
        score += 45.0;
        // but if mean residual across open bins is small relative to item, new bin is attractive
        let tight = mean_residual < item_size as f64 * 1.3;
        if tight {
            score -= 90.0;
        }
        // later in the stream, slightly prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.8;

    // Tight fit reward: small relative slack
    score -= (1.0 - post / cap).max(0.0) * 0.0 + (post / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead spaces much more than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 {
        // Reward leaving a gap that can still be useful (>= typical min item size).
        score -= 6.0;
        if post_residual as f64 >= mean_residual {
            score -= 3.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 + 8.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);
    } else {
        // Mild preference for tighter existing bins (best-fit flavor).
        score += (bin_capacity as f64 - bin_residual as f64).max(0.0) * 0.05;
    }

    // Lookahead: if the next item could use the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor perfect or near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // this placement is excellent (chains two items into one bin).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            if chain_waste <= 10 {
                score -= 80.0;
            } else {
                // Penalize leaving space that only partially matches the next item
                score -= 30.0 - (chain_waste as f64).min(30.0);
            }
        } else {
            // Next item cannot use this bin's leftover; leftover is dead space
            // unless it's small enough to be generally unusable anyway.
            if post_residual >= next_item_size {
                // unreachable, but safe
            } else {
                let dead = post_residual as f64;
                score += dead * 0.5;
            }
        }
    } else {
        // Last item: minimize leftover as much as possible.
        score += post_residual as f64 * 2.0;
    }

    // Compare against mean residual: choosing a bin with residual far below
    // mean concentrates waste; choosing one near/above mean preserves spread.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and
    // the item is small relative to capacity; encourage it for huge items.
    if bin_residual == bin_capacity {
        let ratio = item_size as f64 / bin_capacity as f64;
        if open_bins_count > 0 {
            score += 250.0 - 200.0 * ratio;
        } else {
            score -= 500.0; // must open first bin
        }
    }

    // Early in the stream, be slightly more willing to spread items
    // (more future flexibility); later, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 50.0;
    } else {
        score += (1.0 - progress) * 10.0;
    }

    // Tie-break: prefer fuller bins (smaller residual) slightly.
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: subtract proportional to how much of the bin the item consumes.
    score -= (item_size as f64) * 0.45;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate penalty: opening a fresh bin is costly unless the current
    // fit is terrible. Penalize relative to mean residual across open bins.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.25 * mean_residual + 8.0 * progress;
        // If no open bin fits well (large dead space everywhere), soften the penalty.
        if mean_residual > 40.0 {
            score -= 10.0;
        }
    }

    // Lookahead coupling (k=2): reward bins whose post-residual can host next item.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 14.0 * (1.0 - 0.5 * progress);
        } else {
            // Dead space that next item cannot use: penalize more early in the stream.
            score += 6.0 + 6.0 * (1.0 - progress);
        }
        // Perfect chain: item + next item exactly fills the bin.
        if next_item_size as u64 + item_size as u64 == bin_residual as u64 {
            score -= 20.0;
        }
    }

    // Global pressure: many open bins -> prefer placements that reduce mean residual.
    if open_bins_count > 3 {
        if (post_residual as f64) < mean_residual {
            score -= 5.0 + 0.05 * open_bins_count as f64;
        } else {
            score += 3.0;
        }
    }

    // Avoid leaving tiny unusable slivers (dead space < 10 is nearly worthless).
    if post_residual > 0 && post_residual < 10 {
        score -= 4.0; // sliver is fine if it means a near-perfect fit happened
    }
    if post_residual >= 10 && post_residual <= 20 && next_item_size >= 10 {
        score += 2.0; // mid-range leftover that only small items can use
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;
    let post_frac = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let poly = pr * pr / cap;                      // quadratic dead-space penalty
    let coupling = poly * (0.5 + 0.5 * progress);  // dead space hurts more late in stream

    let mut score = pr + 0.35 * coupling;

    // Reward tight fits via smooth cubic of fill fraction.
    let fill = 1.0 - post_frac;
    score -= 8.0 * fill * fill * fill;

    // Penalize bins whose residual becomes awkwardly small but nonzero (smooth bump).
    let awkward = post_frac * (1.0 - post_frac);
    score += 6.0 * awkward * awkward;

    // Lookahead: reward if next item fits the post residual (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0) / cap;
        score -= 4.0 * fits * fits;
        let near = (pr - nxt).abs() / cap;
        score += 3.0 * near * near;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild pressure to prefer existing bins over opening new ones, stronger early.
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * (1.0 - progress);
    }

    // Smooth penalty relative to mean residual: prefer bins below-average residual (tighter).
    score += 0.10 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small dead-space" classes are rewarded (residual well spent).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let ir = item_size as f64;

    // Fraction of capacity consumed by this placement.
    let fill = ir / cap;
    score -= 30.0 * fill;

    // Modulo classes: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are reusable -> reward; odd/prime-ish residuals penalized.
    let p = post_residual;
    if p == 0 {
        score -= 40.0; // perfect fit
    } else {
        let reusable = (p % 10 == 0) as f64 * 8.0
            + (p % 25 == 0) as f64 * 6.0
            + (p % 50 == 0) as f64 * 5.0;
        score -= reusable;
        // Dead-space penalty grows superlinearly for tiny unusable residuals.
        if p < 10 {
            score += (10 - p) as f64 * 1.5;
        }
        // Integer-division threshold: residual in [1, item/4] is likely dead.
        let quarter = (item_size / 4).max(1);
        if p < quarter {
            score += 6.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained harmonic match).
    if next_item_size > 0 {
        if next_item_size == p {
            score -= 35.0;
        } else if next_item_size <= p {
            score -= 12.0 * (next_item_size as f64 / cap);
        } else {
            score += 5.0; // next item won't fit here
        }
        // Class match: next item size shares a divisor class with residual
        if next_item_size > 0 && p % next_item_size == 0 && p > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current open bins are crowded
    // or mean residual is too small to be useful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64;
        let mean_useful = mean_residual / cap;
        score += 30.0 - 8.0 * crowding.min(4.0) - 40.0 * mean_useful - 10.0 * progress;
        // If next item is large and mean residual can't hold it, new bin is good.
        if next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    // Mild preference for tighter bins overall.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs().signum()
        * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1) are worthless; residuals below the typical item threshold are risky.
    if post_residual > 0 && post_residual < 10 {
        score += 250.0; // unusable sliver
    } else if post_residual < 20 {
        score += 60.0;  // likely dead space
    } else if post_residual < 35 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Open-bin pressure: discourage spawning extra bins unless this is the
    // empty-bin candidate being evaluated.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when many bins exist and mean
        // residual is fragmented, or when the item fits poorly everywhere.
        score += 40.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size > post_residual {
            score += 10.0;
        }
        if mean_residual < 25.0 && open_bins_count > 2 {
            score -= 30.0; // fragmentation: fresh bin may consolidate
        }
    } else {
        // Reward packing into bins whose residual is close to the item size.
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score -= 50.0 / (1.0 + tightness);
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Mild late-stream tightening: consolidate more aggressively near the end.
    if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 12.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 40.0; // perfect chaining: item + next fills bin
        } else if post_residual >= next_item_size {
            // next item fits, reward proportional to how much would remain after
            let chained_residual = post_residual - next_item_size;
            score -= 18.0 * (1.0 - chained_residual / (bin_capacity as f64));
        } else {
            // next item cannot fit here: penalize leaving a gap smaller than next item
            let gap = post_residual as f64;
            if gap > 0.0 && gap < nxt {
                score += 10.0 * (nxt - gap) / (bin_capacity as f64);
            }
        }
    }

    // Penalize large post_residual relative to mean residual (wasteful bin choice).
    score += 0.08 * ((post_residual as f64) - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening a new bin when other bins fit, softened late in stream.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - 0.5 * progress);
    }

    // Reward using nearly-full bins.
    score -= 6.0 * (bin_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) nonlinearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever be useful.
    if post_residual > 0 {
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score += 25.0;
        }
    }
    // Penalize residuals that cannot fit any plausible future item (items >= 1),
    // scaled by how "wasted" the space is relative to capacity.
    let waste_ratio = (post_residual as f64) / cap;
    if waste_ratio > 0.0 && waste_ratio < 0.10 {
        score += 18.0 * (0.10 - waste_ratio) / 0.10;
    }

    // Lookahead coupling: if next item fits in the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; slight penalty proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * gap / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }
    // Many fitting bins: encourage choosing the tightest (already via post_residual),
    // but add mild penalty to avoid scattering across many bins.
    if fitting_bins_count > 2 {
        score += 2.0 * ((fitting_bins_count - 2) as f64).min(5.0);
    }

    // Time horizon: early in the stream, prefer consolidating into open bins;
    // late in the stream, exact fits matter more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Global state: if mean residual is high, bins are loose — prefer filling
    // the emptiest-fitting ones; use mean_residual to modulate.
    let mean_res_norm = mean_residual / cap;
    score += 4.0 * mean_res_norm * (1.0 - tightness);

    // If many bins are open, discourage opening new ones: penalize the new-bin
    // candidate (bin_residual == bin_capacity) proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * (open_bins_count as f64).min(10.0);
        // But if no open bin fits well (post_residual near-full bin), allow new bin:
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild penalty for very full bins being "spent" — keep them for tiny future items.
    if post_residual == 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), softened by progress
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - progress));

    // Smooth non-linear coupling of post residual with stream progress
    score += 15.0 * norm_pr * norm_pr * progress * (1.0 - progress) * 4.0;

    // Lookahead: reward leaving space usable by next item (smooth Gaussian-like affinity)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (pr - nxt).max(0.0);
        let affinity = (-((pr - nxt) / 20.0).powi(2)).exp();
        score -= 6.0 * affinity;
        score += 0.05 * fit_next;
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for many open bins relative to mean residual spread
    score += 0.02 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: neutral-ish baseline, penalized early, relaxed late
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 5.0;
    }

    // Smooth tie-breaker favoring tighter bins
    score += 0.1 * (bin_residual as f64 - item_size as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual % (bin_capacity / 10).max(1)) as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that no plausible item can fill: post_residual < 10
        if post_residual < 10 {
            score += 60.0;
        }
        // Reward residuals that fall into "fillable" harmonic classes
        // (residuals matching common item sizes or their sums).
        let harmonic_bonus = match post_residual % 10 {
            0 => 25.0,
            5 => 12.0,
            2 | 8 => 6.0,
            _ => 0.0,
        };
        score -= harmonic_bonus;

        // Lookahead coupling: if next item fits exactly into post_residual, big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 400.0;
            } else if next_item_size <= post_residual {
                // reward proportionally to how well next item fills the gap
                let fill = next_item_size as f64 / pr;
                score -= 80.0 * fill;
            } else {
                // next item cannot use this residual: mild penalty scaled by waste
                score += 0.3 * pr;
            }
        }

        // Last-chance bin: strongly prefer using it before opening a new one.
        if fitting_bins_count == 1 {
            score -= 150.0;
        }

        // Class-based threshold on integer division of post_residual by capacity/10.
        let div_class = post_residual / (bin_capacity / 10).max(1);
        score -= (div_class as f64) * 4.0;

        // Prefer bins tighter than the mean residual (best-fit flavor).
        score += (pr - mean_residual) * 0.5;

        // Late in the stream, consolidate harder: penalize spreading across many bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * open_bins_count as f64 * 0.5;
    }

    // New-bin candidate handling: only attractive when it avoids heavy fragmentation.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, discounted early when few bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 40.0 + 120.0 * progress + 8.0 * open_bins_count as f64;
        // If no open bin fits at all, opening is fine; if others fit, make it costly
        // unless the item is large relative to capacity (big items deserve fresh bins).
        let big_item_bonus = if item_size > bin_capacity / 2 { 60.0 } else { 0.0 };
        score = base - big_item_bonus;
        // A new bin's residual after placement equals capacity - item; compare
        // against mean residual: opening is better if mean residual is tiny (fragmented).
        if mean_residual < 5.0 && fitting_bins_count > 0 {
            score -= 30.0;
        }
        // Harmonic: if item size divides capacity nicely, new bin is harmonious.
        if bin_capacity % item_size.max(1) == 0 {
            score -= 20.0;
        }
    }

    let _ = class;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item (1..100 unknown, assume ~10 threshold with softness).
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual as f64);
    } else if (post_residual as f64) < dead_threshold * 2.0 {
        score += 8.0 * (dead_threshold * 2.0 - post_residual as f64) / dead_threshold;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 2 {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward keeping this bin attractive.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }
    // If next item would leave this bin's post placement residue useless, slight penalty.
    if next_item_size > 0 && next_item_size > post_residual && (post_residual as f64) < dead_threshold {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 2.5 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when no open bin fits well (large item, big residual mismatch).
    if bin_residual == bin_capacity {
        let mismatch = (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
        let base = 25.0 + 40.0 * mismatch;
        // Cheaper to open a new bin when existing bins are nearly full on average.
        score = base - mean_residual * 0.4 + post_residual as f64 * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can exactly (or nearly) accommodate the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-item pairing: this bin is closed out by the next item.
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves a smaller leftover; penalize by the
            // remaining gap so tighter chains are preferred.
            score -= 25.0 - 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item will NOT fit here: penalize proportionally to how
            // much of the next item is wasted relative to this residual.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.3 * miss;
        }
    }

    // Compare against mean residual: bins tighter than average are more
    // valuable to fill; looser bins can wait.
    let diff = mean_residual - bin_residual as f64;
    score += 0.2 * diff;

    // Penalize creating very small unusable dead space (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Early in the stream, be more willing to open fresh bins (favor the
    // empty-bin candidate); late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 12.0 * (1.0 - progress);
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are valuable: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish,
    // this placement is excellent; if next item is large and post_residual
    // becomes stranded, penalize.
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= post_residual as f64;
        if next_fits {
            score -= 8.0 * (next_item_size as f64 / 100.0);
        } else {
            // stranded dead space relative to next item
            let waste = post_residual as f64 - (next_item_size as f64 - post_residual as f64).abs();
            score += 0.15 * waste.max(0.0);
        }
    }

    // Penalize bins whose residual deviates wildly from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in stream, prefer spreading load (keep flexibility);
    // late in stream, prefer filling bins fully and opening fewer new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 6.0 * (1.0 - open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 30.0 - 28.0 * poor_fits - 10.0 * progress;
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly warped by stream progress.
    // Late in the stream, residual space is more valuable -> penalize waste more.
    let warp = 1.0 + 1.5 * progress * progress;
    let mut score = pr * warp;

    // Smooth polynomial coupling: quadratic + cubic terms on normalized residual,
    // scaled by progress so early stream tolerates mid residuals, late stream hates them.
    let coupling = norm_pr * norm_pr * (0.5 + 2.0 * progress) - norm_pr * norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += coupling * cap;

    // Perfect fit reward (smooth, not piecewise): strongly subtract when post_residual tiny.
    let fit_bonus = (-norm_pr * 12.0).exp() * (1.0 + progress) * 6.0;
    score -= fit_bonus;

    // Dead-space penalty: residual too small for smallest plausible future item.
    let dead = (1.0 - (pr / 20.0).min(1.0)) * pr * (0.3 + progress);
    score += dead;

    // Last-chance bin: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count <= 1 {
        score -= 4.0 + 6.0 * progress;
    }

    // Lookahead: reward if next item fits in the post-residual (smooth margin term).
    if next_item_size > 0 {
        let margin = (pr - next_item_size as f64) / cap;
        if margin >= 0.0 {
            score -= (margin * 8.0 + 1.0) * (0.5 + progress);
        } else {
            score += (-margin) * cap * 0.05;
        }
    }

    // New-bin candidate handling: empty bin gets a mild penalty unless current bins are tight.
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / cap).max(0.0).min(1.0);
        score += 3.0 - 4.0 * (1.0 - tightness) * (0.5 + progress);
    }

    // Mild reward for bins below mean residual (consolidating space).
    score -= 0.5 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let rem = post_residual % 10;
    let harmonic_bonus = match rem {
        0 => 8.0,          // perfectly aligned dead space, very reusable
        1 | 9 => 2.0,
        2 | 8 => 0.0,
        3 | 7 => -1.0,
        4 | 6 => -2.5,
        _ => -4.0,         // rem 5: awkward half-slot
    };
    score -= harmonic_bonus;

    // Integer-division thresholds on post_residual: penalize large leftover
    // only mildly if it sits in a "harmonic" band (multiples of 10/20).
    let band = post_residual / 20;
    let band_penalty = match band {
        0 => 0.0,                       // tiny residual, near-full bin: great
        1 => 3.0,
        2 => 7.0,
        3 => 12.0,
        _ => 18.0,
    };
    score += band_penalty * (1.0 - 0.5 * (rem as f64) / 10.0);

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (perfect harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            let overflow = (next_item_size - post_residual) as f64;
            score += 2.0 * (overflow / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits (post_residual already does this)
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin has large residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified when existing residuals are poor fits:
        // compare against mean residual. If mean residual is large (open bins
        // are mostly empty), discourage new bin.
        score += 20.0 - 0.35 * mean_residual;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If item is small relative to capacity, opening a bin wastes capacity.
        score += 0.2 * (cap - item_size as f64);
    }

    // Mean-residual coupling: when open bins are on average full (small mean
    // residual), placing into a roomy bin is less costly; when mean residual
    // is large, avoid spreading items thin.
    score += 0.05 * mean_residual * (pr / cap);

    // Fraction-of-capacity harmonic reward: residual near capacity fractions
    // (25, 50, 75) are natural slots for mid-size items.
    let frac_hits = [(25u32, 3.0), (50, 4.0), (75, 3.0)];
    for (target, rew) in frac_hits.iter() {
        let d = (post_residual as i64 - *target as i64).unsigned_abs() as f64;
        if d <= 5.0 {
            score -= rew * (1.0 - d / 5.0);
        }
    }

    // Slight preference for bins that will end very full (dead space < 10).
    if post_residual < 10 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    let dead_threshold = 10.0; // min item size is 1, but typical small items exist
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, tolerate opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + progress * 10.0);
    score += pressure * (post_residual as f64) * 0.05;

    // New-bin candidate: make it mildly unattractive unless residuals are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    }

    // Prefer bins tighter than average (good fits).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // next item fits here too: penalize leftover after two placements
            let two_step_left = post_residual - next_item_size;
            score += two_step_left as f64 * 1.5;
            if two_step_left == 0 {
                score -= 600.0;
            }
        } else {
            // next item cannot use the leftover: penalize proportionally to dead space
            score += (post_residual as f64) * 0.8 + 25.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 && post_residual < item_size.max(next_item_size) {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 40.0;
        }
    }

    // Early stream: be slightly more willing to open bins (future flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize creating dead space that is too small to be useful
    // (below the minimum plausible item size).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Strongly prefer using existing bins over opening a new one,
    // but allow new-bin opening when the fit is very loose.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post residual,
    // reward this placement (chaining).
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 35.0; // perfect chain
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // next item won't fit here; mild penalty
        }
    }

    // Time horizon: later in the stream, consolidate more aggressively
    // (avoid opening new bins near the end).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual
    // suggests fragmentation; prefer filling bins above the mean.
    let above_mean = bin_residual as f64 - mean_residual;
    score -= 0.05 * above_mean;

    // Mild pressure to keep open bin count low.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: as stream progresses, penalize residual waste more strongly
    let progress_coupling = 1.0 + progress * (1.0 - progress) * 4.0 + progress * progress * 2.0;
    score *= progress_coupling;

    // Reward bins whose residual will pair well with the next item (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 12.0 * (-gap * gap / 300.0);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (0.5 + progress);
    }

    // Penalize opening new bins when many bins are open but residual is high
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).ln();
    } else {
        // Mild preference for filling existing bins relative to mean residual
        score -= 0.05 * (mean_residual - pr);
    }

    // Dead-space penalty: residuals too small for any item (smoothly modeled)
    score += 6.0 * (-pr / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: residues modulo 10 create "dead-space bands".
    let residue_class = post_residual % 10;
    // Waste penalty grows for residues that are hard to fill (1..9 unusable slivers).
    if post_residual > 0 {
        let waste = match residue_class {
            0 => 0.0,
            1 | 2 | 3 => 6.0,
            4 | 5 | 6 => 3.0,
            _ => 1.5,
        };
        score += waste * (post_residual as f64 / cap);
    } else {
        // Perfect closure: strong reward.
        score -= 25.0;
    }

    // Integer-division thresholds: how many "typical" small items (<=10) fit next.
    let small_slots = post_residual / 10;
    score -= small_slots as f64 * 2.0;

    // Lookahead coupling: does post_residual admit the next item exactly?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect two-step chain
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // penalize by harmonic class of the resulting gap
            score += (gap % 10) as f64 * 0.8;
            score -= (gap / 10) as f64 * 1.5;
        } else {
            // next item cannot follow here; residual likely dead
            score += (post_residual as f64) * 0.35;
        }
    } else {
        // last item in stream: prefer tighter fill
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Crowding: when many bins are open, prefer consolidating into tight bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 0.6;
    score -= mean_residual * 0.05 * progress;

    // New-bin candidate: neutral-ish baseline; only attractive when fit is terrible.
    if bin_residual == bin_capacity {
        score += 12.0 + (item_size as f64 * 0.1);
    }

    // Fractional capacity coupling: reward placements whose fill fraction is harmonic (1/4, 1/2, 3/4).
    let fill = (bin_capacity - post_residual) as f64 / cap;
    for h in [0.25f64, 0.5, 0.75, 1.0] {
        if (fill - h).abs() < 0.01 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item are unusable "dead space" -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward good tight fits (small but still usable residual).
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).min(1.0);

    // Last fitting bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins rather than opening more.
    score += 0.8 * open_bins_count as f64;

    // New empty bin candidate: only attractive when the item is large
    // (poor fit anywhere) or no bin leaves a usable residual.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 60 || post_residual < 10;
        if poor_fit {
            score -= 30.0;
        } else {
            score += 45.0;
        }
        // Early in stream, opening bins is cheaper; late, avoid fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement is extra valuable.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item cannot fit in post residual but could fit elsewhere,
    // mildly penalize wasting large residuals.
    if next_item_size > post_residual && post_residual > 40 {
        score += 8.0;
    }

    // Prefer bins whose residual is already below mean (consolidate waste).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: item placed leaves exactly room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Leaves usable space for next item, but not a perfect match.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here; dead space penalty grows with wasted gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 15.0 * (gap / bin_capacity as f64);
    }

    // Perfect single-item fill (bin closed exactly).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Compare against mean residual: placing in a bin whose residual is far
    // below average wastes the big residual bins; prefer tight bins.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when decent existing fits exist,
    // unless the item is huge and a fresh bin is natural.
    if bin_residual == bin_capacity {
        let fresh_penalty = 20.0 + 0.5 * open_bins_count as f64;
        let tightness = (item_size as f64 / bin_capacity as f64).powf(2.0);
        score += fresh_penalty * (1.0 - tightness);
    }

    // Late in the stream, consolidate: favor bins with small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual, but penalize dead space
    let tight_fit = (post_residual as f64) / (bin_capacity as f64);
    score += tight_fit * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that blocks the known next item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Penalize opening new bins when many open bins exist (consolidation pressure)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 50.0 * progress + open_bins_count as f64 * 2.0;
        // But if no existing bin fits well, allow opening
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // If next item is large, prefer fresh bin with room
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 25.0;
        }
    }

    // Prefer bins with residual below mean (fill the emptier bins less, tighten tight ones)
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.15;

    // Slight preference for larger residual bins early (spread load), tighter late
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64) * (0.1 - 0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    let mut score = pr as f64;

    // Non-linear polynomial coupling with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - progress);
    score -= 40.0 * poly;

    // Penalize large dead space more aggressively late in stream
    score += progress * (x * x) * 20.0;

    // Reward tight fits (small post residual) with smooth falloff
    score -= 15.0 * (-x * 8.0).exp();

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Mild penalty when bin residual deviates from mean residual (balance open bins)
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: discourage opening new bins early unless residual is tiny
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Harmonic class of post_residual: residues mod 10 and mod 25.
    let class10 = (post_residual % 10) as f64;
    let class25 = (post_residual % 25) as f64;

    // Penalize awkward residues that are hard to fill later.
    // Small residues (< 10, min item size) are dead space.
    if post_residual < 10 {
        score += 6.0;
    } else {
        // Nonzero mod-10 residue means wasted fraction of capacity quantum.
        score += class10 * 0.15;
        score += (25.0 - class25).abs() * 0.02;
    }

    // Perfect fills (post_residual == 0) are heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Coupling with lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves another residue: mild reward scaled by fit tightness.
        let nxt_left = post_residual - next_item_size;
        score -= 4.0 - (nxt_left as f64) * 0.08;
        if nxt_left < 10 {
            score += 2.5; // would create dead space next step
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize more if this bin's residue is large.
        score += (post_residual as f64) * 0.03;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here is terrible (large post_residual).
    if bin_residual == bin_capacity {
        // New bin starts with post_residual == 100; make it competitive only
        // when open bins are plentiful / mean residual is small.
        let crowding = (open_bins_count as f64) * 0.5 + mean_residual * 0.2;
        score -= crowding.min(15.0);
        // Early in the stream, opening bins is cheap.
        score -= (1.0 - progress) * 5.0;
    }

    // Prefer filling bins with larger residual when many bins are open (consolidation).
    if open_bins_count > 4 {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // Integer-division thresholds: bins whose residual is in a "fillable band"
    // (residual/10 >= 1, i.e., at least one min item) get slight reward.
    if post_residual / 10 >= 1 && post_residual >= item_size {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (below the minimum item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> strong penalty
    }
    // "Awkward gap" zone: small enough to be hard to fill but not zero.
    if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    }

    // Reward near-perfect fits (post_residual close to zero but usable).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 12.0; // tight fit, still fillable by small items
    }

    // Coupling: tight fit is even better when the next item is large
    // (we want big items to consume fresh large residuals).
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 * 1.0 {
            score -= 8.0; // residual can host the lookahead item
        }
        if post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 6.0; // residual too small for lookahead -> dead-ish space
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        // But if the fit would create a large unusable gap, relax the bonus.
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, new bins are cheaper.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure for many open bins.
        score = 100.0 + 8.0 * open_pressure;
        // Late in the stream, opening new bins is more acceptable (less
        // time for residual to matter); early on, discourage strongly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * progress;
        // If no open bin fits well (this call is the comparison), allow it.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Large items favor fresh bins.
        if item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Filling an existing bin reduces open-bin pressure slightly.
        score -= 3.0 * open_pressure;
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps the bin set balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for placing into bins with larger residual when
    // item is large (best-fit would otherwise tie).
    if item_size >= 50 {
        score -= 0.05 * (bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual exactly matches
    // the next item size (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else {
            // Penalize dead space that is too small for the next item.
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.8;
            } else {
                // Reward leaving room for the next item.
                score -= 0.3 * (post_residual as f64 - next_item_size as f64).min(50.0);
            }
        }
    }

    // Compare against mean residual: placing in a bin with residual far below
    // mean (tight bin) is good; far above mean (wasteful bin) is bad.
    let bin_res_f = bin_residual as f64;
    score += 0.5 * (bin_res_f - mean_residual).max(0.0);
    score -= 0.4 * (mean_residual - bin_res_f).max(0.0);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize creating tiny unusable residuals (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (post_residual large means this is the empty bin or a loose fit).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, reduced when many bins are open
        // or late in the stream.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let mut nb = 120.0 - 60.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > item_size {
            nb -= 40.0;
        }
        // If the only fitting bin leaves a bad residual, opening a new bin
        // becomes competitive.
        if next_item_size > 0 && post_residual < next_item_size {
            nb -= 60.0;
        }
        score += nb.max(0.0);
    }

    // Prefer bins with residual close to item size (tight fit) generally.
    score += 0.2 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item leaves little waste.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: post_residual that is small but nonzero is risky.
    if post_residual > 0 {
        let dead = post_residual as f64;
        let dead_norm = dead / bin_capacity as f64;
        // Penalize residuals that are too small to hold typical future items,
        // but reward residuals large enough to be reusable.
        if dead < 10.0 {
            score += 8.0 * (10.0 - dead);
        } else {
            score -= 3.0 * dead_norm;
        }
    } else {
        // Perfect fit: huge reward.
        score -= 25.0;
    }

    // Lookahead (k=2): if the next item fits exactly into the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: the leftover becomes waste.
            score += 0.10 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing bins are crowded or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / bin_capacity as f64;
        // Penalize new bins mildly; the penalty shrinks when open bins are
        // nearly full (low mean residual) or late in the stream.
        score += 10.0 * (1.0 - crowded) * (1.0 - 0.5 * progress);
        // A new bin is great for very large items that barely fit anywhere.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 6.0;
        }
    } else {
        // Slight preference for reusing bins that are already well-filled
        // relative to the fleet average residual.
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    // Fragmentation guard: penalize leaving residuals in the awkward middle
    // band (too big to ignore, too small to be reliable).
    let pr = post_residual as f64;
    if pr > 20.0 && pr < 45.0 {
        score += 2.5 * ((pr - 32.5) / 12.5).abs();
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling: waste penalized more early, less late
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (3.0 - 2.0 * norm_pr); // smoothstep in [0,1]
    score += poly * cap * (1.0 - 0.6 * progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 25.0 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: penalize if post_residual can't fit next item but a tighter residual could
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // residual usable by next item: mild reward scaled by match quality
            let gap = (pr - nx) / cap;
            score -= (1.0 - gap) * (1.0 - gap) * 12.0 * (0.5 + 0.5 * progress);
        } else {
            // dead space relative to next item
            score += (nx - pr) * 0.25 * (1.0 - progress);
        }
    }

    // Deviation from mean residual: prefer bins that reduce dispersion
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 15.0;

    // New-bin candidate: discourage early, allow late when it yields a clean large residual
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity/10 buckets.
    let class = (post_residual / (bin_capacity / 10).max(1)) as f64;

    // Reward small post_residual, especially exact fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else {
        // Dead-space penalty grows superlinearly per class.
        score += class * class * 0.6;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // harmonic match: next item leaves another tiny residual
            let nxt_class = ((post_residual - next_item_size) / (bin_capacity / 10).max(1)) as f64;
            score -= 10.0 + 8.0 * (1.0 - nxt_class / 10.0);
        } else {
            // next item cannot use the residual: penalize proportionally
            score += 4.0 + (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless residuals elsewhere are very tight.
    if bin_residual == bin_capacity {
        score += 20.0;
        if mean_residual < 15.0 {
            score -= 30.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is far from mean (tighten spread control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild pressure against too many open bins.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (<= 10) are pure waste. Penalize hard when post_residual
    // falls in the "unusable gap" zone (1..=9), softly above.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 30.0 * (10.0 - post_residual as f64);
        } else if post_residual < 25 {
            score += 0.6 * (25.0 - post_residual as f64);
        }
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new
    // bins and encourage filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or late in stream.
        score += 8.0 + 2.5 * open_bins_count as f64 + 10.0 * progress;
        // But if no open bin fits well (post_residual small gap everywhere),
        // opening a fresh bin is fine; approximate via mean_residual mismatch.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 12.0;
        }
    } else {
        // Existing bin: slight bonus for filling bins when bin count is high.
        score -= 0.3 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item exactly fits the post_residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual && post_residual > 0 && next_item_size <= bin_residual {
            score += 10.0;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit core),
    // scaled by deviation from mean residual to diversify gap sizes.
    score += 0.2 * ((bin_residual as f64 - item_size as f64) - (mean_residual - item_size as f64)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward when next item fits into the post residual (partial lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > 0 {
        // Penalize creating dead space that cannot host the next item
        let waste = post_residual as f64;
        score += 0.5 * waste;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Penalize bins whose residual is far from any plausible future fit
    let r = post_residual as f64;
    if r > 0.0 && r < 10.0 {
        score += 15.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += 25.0;
        }
        // Early in stream, new bins are cheap; later, discourage fragmentation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference to fill already-open bins when many are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space: residuals too small for the smallest items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead reward: if the next item fits exactly or well into the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * tightness;
        } else {
            // next item cannot use the leftover space at all
            score += 6.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no good
    // fit exists elsewhere (many bins but poor fit) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if open_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).recip() };
        // Baseline cost of a fresh bin ~ its full residual, discounted slightly
        let mut new_bin_score = bin_capacity as f64 * 0.85;
        // If the item leaves a large, reusable residual in a new bin, discount
        new_bin_score -= (post_residual as f64) * 0.3;
        // Opening a bin becomes more acceptable late in the stream
        new_bin_score -= 20.0 * progress;
        // If many bins fit the item, opening a new one is wasteful
        new_bin_score += 15.0 * scarcity * (open_bins_count as f64).min(10.0);
        // Avoid opening new bins when the average residual across open bins is large
        new_bin_score += (mean_residual - post_residual as f64) * 0.4;
        return new_bin_score;
    }

    // Global state coupling: prefer bins whose residual deviates favorably from mean
    let deviation = bin_residual as f64 - mean_residual;
    score += deviation * 0.15;

    // Mild reward for filling tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 10.0 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post-residual (waste), non-linearly shaped by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize small-but-nonzero post-residual (dead space), smoothly
    let norm_dead = pr / cap;
    score += 25.0 * norm_dead * (1.0 - norm_dead) * (1.0 + progress);

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0 + 20.0 * progress;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / cap);
    }
    // Penalize if next item almost fits but not quite (near-miss dead space)
    else if next_item_size > 0 && next_item_size <= item_size.max(next_item_size) && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64)) * (1.0 - progress);
    }

    // Prefer fuller bins relative to mean residual of open bins
    score += 0.3 * (mean_residual - pr);

    // Slight preference to keep few bins open early, consolidate later
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make it moderately attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        score -= 10.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post_residual
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tight * tight;

    // Harmonic class of post_residual: residual mod 10 buckets.
    // Residuals that are small modulo classes (0..=9) are "almost reusable"
    // for the smallest items; class 0 (perfect fit) heavily rewarded.
    let pr_class = post_residual % 10;
    match pr_class {
        0 => score -= 25.0,
        1..=3 => score -= 8.0,
        4..=7 => score += 5.0,
        _ => score += 12.0,
    }

    // Integer-division thresholds: large dead space (>= half capacity) is bad.
    if post_residual >= bin_capacity / 2 {
        score += 20.0;
    }
    if post_residual >= 3 * bin_capacity / 4 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how much remains after both
            let after_next = post_residual - next_item_size;
            score -= 15.0 * (1.0 - after_next as f64 / cap);
        } else {
            // next item cannot use this residual: penalize by gap size
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / cap).min(1.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual < 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: fresh bins are attractive mid-stream when
    // open bins are mostly full, otherwise discouraged.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fullness = 1.0 - mean_residual / cap;
        // early stream or all bins nearly full -> new bin is fine
        score -= 20.0 * fullness * (1.0 - progress);
        // but late in stream with slack available, avoid fragmentation
        score += 15.0 * progress * (1.0 - fullness);
        if fitting_bins_count > 2 {
            score += 25.0; // plenty of alternatives; don't open new bins
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (spread load),
    // keep high-residual bins for future big items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Slight preference to use many bins rather than overfilling few
    score -= 2.0 * (open_bins_count.min(64) as f64).log2();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual below the minimum item size (1) is impossible, but tiny
    // residuals relative to typical item sizes are near-dead space.
    let dead_threshold = 20.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Coupling with next item: if the next item fits the post-residual,
    // this is a great chain placement; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // We destroyed the ability to fit the next item: penalize.
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (avoid sprawl); with few bins, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += pressure * (post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the current item
    // leaves a large, useful residual or bins are few.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        let mut new_bin_score = 60.0;
        // Cheap to open early in the stream or when few bins are open.
        new_bin_score -= 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        new_bin_score -= (open_bins_count as f64).min(10.0) * 1.5;
        // If mean residual across open bins is small, opening fresh space is valuable.
        new_bin_score -= (mean_residual / bin_capacity as f64) * 20.0;
        // If the item would leave a large residual here, a new bin is fine too.
        if post_residual as f64 >= mean_residual {
            new_bin_score -= 10.0;
        }
        score = score.min(new_bin_score);
        // Never let the new-bin candidate win when a perfect fit exists elsewhere.
        if post_residual == 0 {
            score = 1e9;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step pairing: post_residual exactly matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 40.0; // exact 2-step match: place here
        } else {
            score += diff * 0.5; // penalize mismatch between leftover and next item
        }
        // Bonus if next item fits exactly in current residual (one-shot pairing)
        if bin_residual == next_item_size && post_residual == 0 {
            score -= 25.0;
        }
    } else {
        // Last item: prefer minimal waste
        score += 0.0;
    }

    // Reward tight fits (small post residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Penalize creating dead space that no typical item (>=10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 8.0;
        // But if no open bin fits well (post residual leaves big gap vs next item), allow new bin
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 * 0.5 {
            score -= 20.0;
        }
    }

    // Relative to mean residual: bins with residuals near mean are neutral; prefer bins
    // whose residual is close to item_size (efficient use)
    let res_gap = (bin_residual as f64 - item_size as f64).abs();
    score += res_gap * 0.1;

    // Prefer bins with residual below mean (denser bins first) early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (bin_residual as f64) < mean_residual {
        score -= 3.0 * (1.0 - progress);
    }

    // Slight preference to fill already-open bins when many are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is good, with a non-linear bonus.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that nothing could use: residual smaller than min item (1) is fine,
    // but residuals just above small item sizes are valuable; penalize large awkward residuals.
    let pr = post_residual as f64;
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        // Lookahead: if the next item fits in this post-residual, reward strongly.
        score -= 6.0 + 0.15 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to the wasted gap.
        score += 0.05 * (next_item_size as f64 - pr).max(0.0);
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer bins whose residual is already below the mean (avoid fragmenting healthy bins).
    let diff = mean_residual - bin_residual as f64;
    score += 0.04 * diff;

    // Time horizon: early in the stream, be conservative (favor filling existing bins);
    // late in the stream, allow more aggressive packing into tight fits.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * t * tightness;

    // Many open bins: discourage opening yet another bin / spreading items.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing sensible fits elsewhere.
    if bin_residual == bin_capacity {
        let crowded = fitting_bins_count == 0 || (fitting_bins_count == 1 && mean_residual < item_size as f64);
        if crowded {
            score -= 3.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear sharpening over stream progress
    let mut score = pr * (1.0 + 2.0 * progress * norm_pr);

    // Polynomial coupling: post_residual squared term grows in importance as stream progresses
    score += 0.5 * norm_pr * norm_pr * cap * (0.5 + progress);

    // Penalize dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (pr - nxt).max(0.0);
        score += 0.8 * waste * (1.0 - (pr / nxt.min(pr + 1.0)).min(1.0)) * (0.3 + progress);
    }

    // Reward tight fits (small post residual relative to item) with smooth saturation
    let tightness = 1.0 - (pr / cap);
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize mildly so open bins are preferred unless fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    // Slight preference to balance residuals across bins
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band it lands in.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    // Penalize residuals in awkward bands (dead space classes).
    if post == 0 {
        score -= 60.0; // perfect fit
    } else if post < 10 {
        score -= 25.0; // near-perfect, unusable sliver
    } else if post < quarter {
        score += 8.0; // small-but-not-tiny waste
    } else if post == quarter {
        score -= 12.0; // harmonic class boundary: exact quarter
    } else if post < half {
        score += 4.0;
    } else if post == half {
        score -= 10.0; // exact half is reusable by mid-size items
    } else {
        score += 6.0; // large residual means poor packing density
    }

    // Modulo arithmetic: residuals divisible by common item sizes are valuable.
    if post > 0 {
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 40, 50] {
            if post % d == 0 {
                harmony += 6.0;
            }
        }
        score -= harmony;
    }

    // Lookahead: reward residuals that exactly fit the next item.
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 45.0;
        } else if post >= next_item_size && post - next_item_size < 10 {
            score -= 30.0; // next item leaves near-perfect state
        } else if post < next_item_size {
            score += 10.0; // next item can't use this bin's leftover class
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing
    // bins are crowded (low mean residual) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.75
            + mean_residual * 0.6
            + (open_bins_count as f64) * 2.0
            - progress * 15.0;
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin guarantees a home for the next item
        }
    }

    // Mild global pressure: many open bins -> prefer consolidating into existing ones.
    score += (open_bins_count as f64) * 0.3;

    // Slight preference for tighter fits overall.
    score += (post_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item are wasted.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.5;
    }

    // Tight fit reward: prefer bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 8.0;

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate (residual == capacity) gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 6.0 + open_bins_count as f64 * 1.5;
    }

    // Lookahead: if next item fits the post-residual, reward keeping this bin flexible.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 2.0;
    }

    // Mean residual coupling: penalize bins far above mean residual (less flexible),
    // slightly reward bins near/below mean.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Mild stream progression: later in stream, be slightly more conservative about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base: prefer tight fits (small post_residual)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score = post * (1.0 + 0.5 * (post / cap));

    // 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let match_quality = 1.0 - (post - nxt) / cap;
            score -= 25.0 * match_quality * match_quality;
            // perfect chain: post_residual == next_item_size exactly
            if (post_residual as u32) == next_item_size {
                score -= 30.0;
            }
        } else {
            // next item cannot fit here: mild penalty proportional to gap
            score += 5.0 * ((nxt - post) / cap);
        }
    }

    // Relative to mean residual: bins with residuals below mean are precious;
    // penalize wasting them on loose fits.
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / mean_residual;
        if rel < 1.0 {
            score += 8.0 * (1.0 - rel) * (post / cap);
        } else {
            score -= 3.0 * ((rel - 1.0).min(2.0)) * (post / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Early stream: be slightly conservative, prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * (1.0 - progress) * (post / cap);

    // New-bin candidate: only attractive when item is large or fits are terrible
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        // new bin attractive if item is big (leaves useful space) or no good fits exist
        let poor_fits = if next_item_size > 0 {
            (fitting_bins_count == 0) as f64
        } else {
            0.0
        };
        let bonus = 10.0 * tightness * tightness + 15.0 * poor_fits;
        score = score.max(0.0) + cap - item_size as f64 - bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.83;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - progress));

    // Smooth coupling: post-residual penalty grows non-linearly with stream progress.
    score += 25.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits more strongly later in the stream.
    score -= (item_size as f64 / cap) * (10.0 + 15.0 * progress);

    // Last-chance bin bonus (smooth sigmoid-like reward).
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use, more as stream advances.
        score += 6.0 * norm_pr * (0.5 + progress);
    }

    // Deter spreading across many open bins when mean residual is large.
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // Mild preference for keeping bins balanced relative to mean residual.
    score += 0.5 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual modulo capacity quarters
    let q = post_residual / 25; // 0..3
    let r = post_residual % 25;

    // Reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // usable residual: mild reward scaled by tightness
            score -= 0.5 * (next_item_size as f64 / post_residual as f64);
        } else {
            // dead space relative to lookahead: penalize
            score += 0.3 * ((next_item_size - post_residual) as f64);
        }
    }

    // Harmonic classes: residuals in (0,10) are nearly dead (min item size 1)
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual < 25 {
        score += 10.0;
    } else if post_residual >= 50 {
        // large residual is flexible: reward mildly
        score -= 5.0 + q as f64 * 2.0;
    }

    // Fractional remainder penalty within class
    score += r as f64 * 0.05;

    // Last-chance bin: strongly prefer using it over opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost; make it attractive only if
        // item is huge relative to capacity or all fits are terrible.
        score = 100.0
            - 0.5 * (item_size as f64)
            - (if post_residual >= 50 { 20.0 } else { 0.0 });
        // late in stream, prefer closing out open bins
        if step_index as f64 / total_items.max(1) as f64 > 0.8 {
            score += 30.0;
        }
        // many open bins: discourage spreading
        score += open_bins_count as f64 * 2.0;
    }

    // Prefer fuller bins when mean residual is high (fragmentation risk)
    score += 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Slight preference for bins whose residual was already tight
    if bin_residual < 40 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else if post_residual < 20 { 0.5 } else { 0.0 };
        score += dead * 60.0;
    }

    // Reward tight fits (exact or near-exact).
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // If next item can use the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize when post residual is too small for the next item (likely dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (post_residual as f64) * 0.8;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 8.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates from mean
    // toward tighter fits (lower residual = better utilization).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild progression term: later in the stream, be slightly more conservative.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Small slack after next item = good chained packing.
            score -= 80.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // Next item cannot fit: post_residual becomes dead space for lookahead.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Penalize large residuals that are unlikely to be useful (dead space).
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // tiny residual is nearly full usage
    }
    if post_residual > 60 {
        score += 0.3 * (post_residual as f64 - 60.0); // large leftover less attractive than tighter bins
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are
    // nearly full or the item fits nothing well; otherwise keep it costly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_tight = 1.0 - mean_residual / bin_capacity as f64;
        // Base penalty so new bins aren't opened frivolously.
        score += 150.0;
        // If existing bins are quite full on average, opening a new bin is fine.
        score -= 120.0 * avg_tight;
        // Later in the stream, consolidation matters more; keep penalty higher early.
        score += 40.0 * (1.0 - progress);
        // If next item is large and this item is large, a fresh bin gives flexibility.
        if next_item_size >= 60 && item_size >= 60 {
            score -= 60.0;
        }
    }

    // Mild penalty for proliferating bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Penalize awkward dead space: residuals that are too small for the smallest
    // plausible future item (1..100 range) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover; penalize proportionally to waste.
            score += 0.15 * (next_item_size as f64).min(post_residual as f64 + 1.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // bins are crowded (low mean residual) or many bins are already open.
    if bin_residual == bin_capacity {
        let mean_pressure = 1.0 - (mean_residual / bin_capacity as f64);
        let time_horizon = step_index as f64 / (total_items.max(1) as f64);
        // Default: slightly worse than a decent existing fit.
        score += 18.0;
        // If open bins are nearly full, a new bin is fine.
        score -= 25.0 * mean_pressure;
        // Late in the stream, prefer consolidating into open bins less.
        score -= 5.0 * time_horizon;
        // Many open bins: discourage opening yet another.
        score += 0.4 * open_bins_count as f64;
    }

    // Mild preference for bins whose residual deviates from the mean in a useful way:
    // placing into a bin with residual close to the item size is ideal (already captured
    // by post_residual), but also slightly favor bins with larger residuals when many
    // bins are open, to consolidate.
    score -= 0.02 * (bin_residual as f64 - mean_residual) * (open_bins_count as f64).ln().max(1.0);

    // Progress-aware waste penalty: dead space matters more early in a long stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.08 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress * 2.0 - 1.0; // map to [-1, 1]
    let poly = 0.5 * t * t + 0.3 * t - 0.2;
    score += norm_pr * norm_pr * poly * cap * 0.4;

    // Penalize large dead space relative to mean residual
    score += (pr - mean_residual).abs() * 0.15 * (1.0 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 8.0 * (0.5 + progress);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1.0 {
        score -= 6.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // next item won't fit here; mild penalty for wasting residual
        score += norm_pr * 3.0;
    }

    // New-bin candidate: penalize opening new bins early, less late
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
    }

    // Penalize spreading items across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    // Smooth coupling: item size vs residual interaction
    score += norm_item * (cap - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer near-perfect fits: post_residual close to 0 is great.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Harmonic classes: classify post_residual by residue mod capacity quarters.
    let quarter = bin_capacity / 4; // 25
    let residue = post_residual % quarter;
    // Residues near 0 (i.e., post_residual ~ multiple of quarter) are "aligned" slots;
    // mid-range residues are dead-space prone.
    if residue == 0 {
        score -= 15.0; // aligned slot: likely reusable by future 25-class items
    } else if residue >= 10 && residue <= 15 {
        score += 12.0; // awkward dead zone
    }

    // Integer division threshold: post_residual bucket by halving capacity.
    let half = bin_capacity / 2; // 50
    if post_residual > half {
        score -= 8.0; // still roomy bin, flexible
    } else if post_residual < half / 4 {
        score += 5.0; // nearly full, but that's fine only if fit was tight
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize if post_residual is small-ish
            // (dead space that nothing can use)
            if post_residual < next_item_size && post_residual < 20 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive if no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // More attractive when open bins are crowded (low mean residual)
        // or few bins can fit the item.
        score -= mean_residual * 0.4;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    } else {
        // Reward using existing bins, more when many bins are open (contain spread).
        score -= 5.0 * (open_bins_count.min(20) as f64) / 20.0;
    }

    // Prefer bins whose residual is close to the mean (keep residuals uniform,
    // easier to pack future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Tightness reward: filling a bin that is already mostly full.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Modulo-10 harmonic class of item size: items ending in 0 pair well with
    // residuals ending in 0 (capacity 100 arithmetic).
    if post_residual % 10 == 0 && item_size % 10 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item (1..=10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Reward very tight fits (small post_residual relative to item size).
    if post_residual <= 5 {
        score -= 40.0;
    }

    // If the leftover space can exactly host the lookahead item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize leftovers that can't host the lookahead item but are close to it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new empty bin has bin_residual == bin_capacity -> largest post_residual,
    // but add explicit pressure via open_bins_count coupling).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64 + 10.0 * progress;
    }

    // Slight preference for bins below mean residual (consolidating slack).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match with next item is highly desirable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // exact fill on next step
        } else if next_item_size <= post_residual {
            // next item fits; reward tighter remaining slack afterwards
            let after = post_residual - next_item_size;
            score -= 20.0 + 0.5 * after as f64;
        } else {
            // next item cannot fit in this bin's residue: penalize leftover
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Compare residual against mean residual: bins with below-average slack
    // (tight bins) are preferred to consolidate waste.
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Penalize creating large dead space (>20) that likely becomes unusable.
    if post_residual > 20 {
        score += 0.25 * (post_residual - 20) as f64;
    }

    // Slight preference for filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress;

    // New-bin candidate: make empty bin moderately attractive only when it
    // beats very poor fits (its raw post_residual = capacity - item is large,
    // so the base term already penalizes it unless item is huge).
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
