pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1]
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let t = t.clamp(0.0, 1.0);

    let mut score = pr;

    // Smooth non-linear coupling: quadratic/cubic dead-space penalty grows with stream progress.
    let dead = x * x * (1.0 + 2.0 * t) + x * x * x * (1.0 + 3.0 * t);
    score += 30.0 * dead;

    // Reward tight fits (small post_residual) more strongly later in the stream.
    score -= 20.0 * (1.0 - x) * (1.0 - x) * (0.5 + t);

    // Penalize waste relative to mean residual state of open bins (smooth coupling).
    score += 0.15 * (pr - mean_residual) * (1.0 + t);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 + x);
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let tight = 1.0 - ((pr - nx) / cap);
            score -= 15.0 * tight * tight;
        } else {
            // If next item won't fit in the post-residual, mildly penalize leaving a mid-size gap.
            score += 8.0 * x * (1.0 - t);
        }
    }

    // New-bin candidate handling: empty bin has pr = cap - item_size; make it mildly
    // attractive only when the gap left behind is large (poor fits elsewhere) or
    // few fitting bins exist.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new {
        score -= 5.0 * x * (1.0 + t);
        score += 6.0 / (1.0 + open_bins_count as f64);
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    } else {
        // Prefer consolidating into existing bins when many are open.
        score += 0.05 * open_bins_count as f64 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classes: reward small post_residual classes (mod 10 buckets)
    let class = post_residual % 10;
    score -= (10 - class) as f64 * 0.5;

    // Penalize "dead zone" residuals that are too small for the smallest item (1..100 unknown dist)
    // residual < 10 is nearly unusable
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic match on mod classes
            if post_residual % 10 == next_item_size % 10 {
                score -= 5.0;
            }
        } else {
            // next item cannot fit here: mild penalty proportional to overflow
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 20.0;
        // but if all open bins would leave large dead space, allow new bin
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Prefer filling bins that are already well-used (low residual relative to mean)
    if bin_residual < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Integer division thresholds: reward post_residual in "tight" harmonic bands
    let band = post_residual / 25; // 0..4
    score -= match band {
        0 => 6.0,
        1 => 3.0,
        2 => 1.0,
        _ => 0.0,
    };

    // Mild penalty per open bin to encourage consolidation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

