    // Open-bin pressure: many open bins -> discourage spreading, prefer new bin
    // only when fit is poor; encourage filling existing bins otherwise.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // New-bin candidate: baseline competitive score; prefer it only when the
    // item leaves a good chunk of usable space and existing fits are bad.
    if bin_residual == bin_capacity {
        score = 30.0 + (100.0 - item_size as f64) * 0.3;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // new bin can also host the next item
        }
        if fitting_bins_count <= 1 {
            score -= 50.0; // no good alternative -> open new bin
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0; // next item won't fit here; slight penalty
    }

    // Early in stream, be more conservative about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
