        let poor_fit_penalty = (post_residual as f64) / bin_capacity as f64;
        // Base cost of opening a bin grows with progress (fewer future items to fill it)
        score += 120.0 + 250.0 * progress - 40.0 * poor_fit_penalty - 5.0 * pressure;
        // If next item is large, a fresh bin is attractive
        if next_item_size >= 50 {
            score -= 25.0;
        }
    }

    // Global state: many open bins with high mean residual -> consolidate
    if mean_residual > 30.0 && open_bins_count > 2 && bin_residual != bin_capacity {
        score -= 0.3 * mean_residual;
    }

    // Prefer bins with smaller residual overall (best-fit flavor), scaled by progress
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping
    let x = pr / cap;
    let mut score = pr as f64 * (1.0 + 1.5 * x * x) + 40.0 * x * x * x;

    // Tight fits strongly rewarded, smoothly: (1 - x)^3 bonus
    score -= 60.0 * (1.0 - x).powi(3);

    // Stream progress coupling: later in the stream, waste matters more (cubic ramp)
    let urgency = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += urgency * 25.0 * x;

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 35.0 + 30.0 * urgency;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if (ns - pr).abs() < f64::EPSILON {
            score -= 50.0;
        } else if ns <= pr {
            // next item fits: mildly reward leaving usable space
            score -= 12.0 * (1.0 - (pr - ns) / cap);
        } else {
            // next item won't fit here: penalize large post_residual
            score += 10.0 * x * urgency;
        }
    }

    // New-bin candidate: baseline cost that grows with open bins and progress
    score += is_new_bin * (20.0 + 15.0 * urgency + (open_bins_count as f64).sqrt() * 5.0);

    // Prefer bins whose residual is close to item (best-fit smoothness)
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 15.0 * fit_gap * fit_gap;

    // Slight preference for bins below mean residual (fill emptier-of-space bins? no: fill tighter bins)
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "useful" for future items
    let pr = post_residual as i64;
    let nis = next_item_size as i64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward when the next item exactly fills the post-residual (k=2 lookahead)
    if nis > 0 && nis == pr {
        score -= 500.0;
    } else if nis > 0 && nis <= pr {
        // Two-step chain: reward proportional to how well next item nests
        let chain = (pr - nis) as f64;
        score -= 60.0 * (1.0 - chain / cap);
    } else if nis > 0 {
        // Next item won't fit here: penalize dead space mildly
        score += 10.0;
    }

    // Harmonic classes: post_residual divisible by common item sizes (10..80 grid)
    if pr > 0 {
        let mut best_mod = 100i64;
        for d in [10i64, 20, 25, 33, 50] {
            let m = pr % d;
            if m < best_mod {
                best_mod = m;
            }
        }
        // Low residue to a harmonic divisor => residual is reusable
        score -= 8.0 * (1.0 - best_mod as f64 / 33.0);
        // Penalize residuals in awkward dead zone (1..9)
        if pr < 10 {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: prefer reusing bins early; allow new bin
    // only when existing residuals are large and fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / cap) * open_bins_count as f64;
        // Opening a new bin is good if current bins are crowded/fragmented
        score += 200.0 - 150.0 * fragmentation - 100.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 300.0; // no alternative: new bin is fine
        }
    } else {
        // Prefer bins whose residual is closest above item (best-fit core)
        score += 0.5 * (bin_residual as f64 - item_size as f64);
        // Slight preference for bins below mean residual (tighter bins)
        score += 5.0 * ((bin_residual as f64 - mean_residual) / cap);
    }

    // Late-stream tightening: penalize waste more as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual >= 1 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 3 {
        score -= 10.0;
    }

    // If the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 15.0;
        } else {
            score -= 4.0;
        }
    }
    // If next item cannot use the residual, penalize leaving a medium gap it can't fill.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    score += (open_bins_count as f64) * 0.5;

    // Prefer bins whose residual is close to the mean residual (balanced packing),
    // penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else. Base cost of a fresh bin is high.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6 + (open_bins_count as f64) * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        } else {
            // Slightly discourage opening new bins early in the stream.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect match: next item fits with small slack
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Penalize if next item cannot fit in the post residual (dead space risk)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Reward tight fills (small post residual relative to mean residual)
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score -= (mean_residual - pr) * 0.3;
    }

    // Penalize leaving large unusable gaps
    if pr > 0.0 && pr < 10.0 {
        score -= 15.0; // tiny slivers are fine (nearly full bin)
    }
    if pr > 50.0 {
        score += (pr - 50.0) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // open bins are congested (high mean residual usage is low)
    if bin_residual == bin_capacity {
        score = 70.0 - 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 20.0;
        }
    }

    // Slight preference to fill earlier bins as stream progresses
    score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Relative fit quality: fraction of residual consumed by the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize creating dead space that is small but unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            // Wasted residual relative to next item's needs.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream or with many open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        score = 120.0 - 40.0 * progress - 200.0 * pressure;
        // Opening a new bin is good if the item is large (fills it well).
        score -= 0.6 * item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Global state coupling: if mean residual is high, prefer bins above the mean
    // (drain large-residual bins first), penalize bins below the mean.
    if bin_residual < bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score -= 0.3 * diff;
    }

    // Mild time-horizon shaping: early in the stream, be conservative about
    // leaving big residuals; later, exploit tight fits more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 25.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: post-residual with smooth non-linear shaping (favor tight fits).
    let mut score = pr * (1.0 + 0.35 * pr_norm * pr_norm);

    // Stream-progress coupling: late in the stream, residual waste matters more.
    score += 18.0 * progress * pr_norm * pr_norm * cap.sqrt();

    // Mean-residual interaction: penalize bins far above mean residual (avoid fragmentation).
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * cap;

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if pr < 10.0 {
        score += 25.0 * (1.0 - pr / 10.0);
    }

    // Lookahead: reward leaving space for the next item, penalize blocking it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (1.0 - ni / cap) * (1.0 - progress * 0.5);
        } else {
            score += 6.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: open a new bin only when fits are poor.
    if bin_residual == bin_capacity {
        // Empty bin: neutral-ish baseline, penalized so good fits win, but beats terrible fits.
        score = 55.0 + 20.0 * progress;
    } else {
        // Reward filling existing bins, scaled by how full the bin becomes.
        let fill = 1.0 - pr_norm;
        score -= 15.0 * fill * fill;
    }

    // Mild pressure against bin proliferation early on.
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by divisibility
    let pr = post_residual;
    if pr > 0 {
        // Small residual classes that are "usable" (>= 10 typical min item, but sizes 1..100 here)
        let usable_threshold = 10u32;
        if pr < usable_threshold {
            score += 40.0; // dead space penalty
        } else {
            // reward residuals that are harmonic multiples of common item classes
            for m in [10u32, 20, 25, 50] {
                if pr % m == 0 {
                    score -= 8.0 + (m as f64) * 0.2;
                }
            }
            // divisibility by next item size: future fit likelihood
            if next_item_size > 0 && pr % next_item_size == 0 {
                score -= 15.0;
            }
            if next_item_size > 0 && next_item_size <= pr {
                // lookahead fits: reward proportional to tightness
                let slack = (pr - next_item_size) as f64;
                score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            } else if next_item_size > pr {
                score += 10.0; // lookahead cannot reuse this residual
            }
        }
    }

    // Integer-division threshold coupling: post_residual / next_item_size classes
    if next_item_size > 0 {
        let q = pr / next_item_size.max(1);
        match q {
            0 => score += 12.0,
            1 => score -= 20.0, // exactly one more fit: tight harmonic pair
            2 => score -= 10.0,
            _ => score -= 4.0,
        }
    }

    // Capacity fraction classes of residual
    let frac = pr as f64 / bin_capacity as f64;
    if (frac - 0.5).abs() < 0.01 {
        score -= 10.0;
    } else if (frac - 0.25).abs() < 0.01 || (frac - 0.75).abs() < 0.01 {
        score -= 6.0;
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer filling crowded bins when many bins are open
    score -= (open_bins_count as f64) * 0.5 * (1.0 - frac);

    // Early vs late stream: early on, keep bins tight; later, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Mean residual coupling: avoid bins far from mean (outliers)
    score += 0.2 * ((post_residual as f64) - mean_residual).abs();

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 60.0 - 50.0 * desperation - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any
    // plausible item (items >= 1, but practically small slivers < 10-ish
    // are hard to fill) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate penalty for gaps that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }
    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward bins whose residual tightly matches the item (small waste ratio).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Last chance: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; with few open bins, opening is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (1.0 - progress);

    // New-bin candidate: penalize opening a fresh bin unless the item is
    // large relative to residual capacity of existing bins.
    if bin_residual == bin_capacity {
        score += 35.0 + 0.4 * mean_residual;
        if item_size >= 80 {
            score -= 45.0; // big items fit well in fresh bins
        }
    }

    // Lookahead synergy: reward bins that can also host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-exact fits (minimal dead space).
    if post_residual <= 5 {
        score -= 60.0 + (5 - post_residual) as f64 * 8.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // 2-step lookahead: reward if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.5; // next item fits, tighter is better
            if slack <= 5.0 {
                score -= 15.0;
            }
        } else {
            // next item does NOT fit: leftover becomes potential dead space
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.6;
        }
    } else {
        // Last item: prefer minimal post residual strongly.
        score += 10.0;
    }

    // Penalize post_residual that is small but nonzero (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Relative-to-mean coupling: bins with residual far above mean are
    // "fresher" bins; using them for small items wastes capacity.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.15;
    } else {
        score += dev * 0.05; // slight reward for draining low-residual bins
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current fits are poor and the next item is large.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 20 && (next_item_size == 0 || post_residual < next_item_size);
        if poor_fit && fitting_bins_count <= 2 {
            score -= 20.0;
        } else {
            score += 25.0; // default: prefer filling existing bins
        }
        // Early in stream, tolerate new bins slightly more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 5.0;
    }

    // Slight preference to keep many open bins from proliferating:
    // encourage packing into existing bins when many are open.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
