        // If the item is large, a fresh bin is more natural.
        score -= (item_size as f64) * 0.3;
        // If no open bin fits (this call is the only fit), make new bin reasonable.
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
    } else {
        // Prefer tighter existing bins: penalize bins with lots of residual left.
        score += (bin_residual as f64) * 0.15;
        // Reward bins whose residual is close to the item (tight fit).
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.1;
    }

    // Global load balancing: mildly prefer bins below mean residual (keeps slack distributed).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let norm_post = post_residual as f64 / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Smooth non-linear coupling: polynomial in normalized post_residual, modulated by progress
    let poly = norm_post * norm_post * (3.0 - 2.0 * progress) - norm_post * (1.0 - progress);
    score += 8.0 * poly;

    // Penalize dead space relative to mean residual (quadratic coupling)
    let dead = norm_post - mean_residual / cap;
    score += 5.0 * dead * dead;

    // Reward tight fits with lookahead coupling
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * (1.0 - slack) * (1.0 - progress);
    }

    // Last-chance bonus: smooth sigmoid-like term
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - norm_item) * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: mildly penalize early, allow late when fits are poor
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) * (1.0 - progress);
        score += 3.0 * (norm_item - 0.5) * (norm_item - 0.5);
    }

    // Open-bin pressure: nonlinear in count
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residual classes that are "dead": small nonzero leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // worst class: tiny unusable sliver
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 30 {
        score += 6.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual >= 50 {
        score -= 8.0; // large leftover stays useful
    }

    // Modulo-10 harmonic class: residuals that are multiples of common item sizes
    // (10/20/25/50) are more reusable.
    let r = post_residual;
    if r % 10 == 0 && r > 0 {
        score -= 5.0;
    }
    if r % 25 == 0 && r > 0 {
        score -= 3.0;
    }
    if r % 20 == 0 && r > 0 {
        score -= 2.0;
    }

    // Integer-division thresholds: quarter classes of residual.
    let quarter = (r * 4) / bin_capacity.max(1);
    score -= quarter as f64 * 1.5;

    // Lookahead: reward residual that can host next item (harmonic pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0; // next item exactly fills this bin
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 3.0; // next item won't fit here; leftover likely dead
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins overall (tight packing pressure).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = (post_residual as f64 - mean_residual).abs();
        score += 55.0 + 2.0 * open_bins_count as f64 * frac
            - pressure * 0.1;
    }

    // Mild stream-progression regularization.
    score += (step_index as f64 / (total_items as f64).max(1.0)) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100) are pure waste.
    // Penalize unusable gaps super-linearly; zero residual is perfect (tight fit).
    if post_residual > 0 {
        // treat gap as "dead" if smaller than the smallest plausible item (1) -> never dead here,
        // so instead weight by how small the gap is relative to mean residual:
        let gap_ratio = post_residual as f64 / mean_residual.max(1.0);
        if gap_ratio < 0.35 {
            score += (0.35 - gap_ratio) * 60.0; // tiny leftover = wasted capacity
        }
    } else {
        score -= 25.0; // perfect fit reward
    }

    // Reward using a bin whose residual closely matches the item (tight fit)
    let fit_tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += fit_tightness * 15.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open bins pressure: discourage opening new bins when many are open;
    // the new-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + open_bins_count as f64 * 8.0 + progress * 20.0;
    } else {
        score -= 5.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement (chain fit)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // extra reward if post-residual almost exactly matches next item
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // leftover likely dead for the next item
    }

    // Mild preference for filling bins with larger residual (consolidation)
    score -= (bin_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Post residual can still fit the next item (good chaining).
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit: post residual becomes dead space unless small.
    else if next_item_size > 0 {
        score += 15.0;
    }

    // Penalize tiny useless residuals (dead space) more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward closing a bin nearly exactly (post_residual near 0 but not tiny-fragment).
    if post_residual == 0 {
        score -= 200.0;
    }

    // Compare against mean residual: leaving this bin far below mean wastes capacity elsewhere.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Prefer tighter fits: reward bins with small pre-residual margin.
    let margin = (bin_residual - item_size) as f64;
    score += 0.3 * margin;

    // New-bin candidate handling: only attractive early in the stream or when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        let new_bin_bonus = 60.0 * (1.0 - progress) + 25.0 * crowding;
        // A new bin starts with residual = capacity: apply lookahead as if fresh.
        let mut fresh = bin_capacity as f64;
        if next_item_size > 0 && bin_capacity >= next_item_size {
            fresh -= 30.0 * (1.0 - (bin_capacity - next_item_size) as f64 / bin_capacity as f64);
        }
        score = fresh - new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (low post residual, non-linear)
    if post_residual > 0 {
        score -= 30.0 / (post_residual as f64).powf(0.5);
    } else {
        score -= 40.0; // perfect fit bonus
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins that are already crowded relative to mean residual
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Lookahead: penalize leaving a residual that cannot fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Prefer filling bins with small residual relative to capacity (tight packing)
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // When many bins are open, encourage consolidation into existing bins
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: only prefer a fresh bin if this bin's fit is bad
    if bin_residual == bin_capacity {
        score += 20.0 + post_residual as f64 * 0.5;
        if fitting_bins_count <= 1 && item_size >= bin_capacity / 2 {
            score -= 30.0; // large items may justify a new bin anyway
        }
    }

    // Time horizon: slightly more conservative early, aggressive late
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: post residual, normalized and non-linearly warped by stream progress.
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Quadratic dead-space penalty: small post residuals are bad (wasted capacity),
    // but as the stream progresses we tolerate tighter packing less.
    let dead = (1.0 - norm_post).powi(3);
    score += 6.0 * dead * (0.5 + progress);

    // Smooth coupling: post_residual vs mean residual — prefer bins whose leftover
    // tracks the fleet mean (keeps residual distribution balanced).
    score += 0.35 * (post - mean_residual) * (post - mean_residual) / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: reward if the next item fits the post residual (chaining),
    // penalize if post residual is a near-miss for next_item_size.
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            score -= 3.0 * (1.0 - gap / cap);
        } else {
            score += 2.0 + 0.05 * (-gap);
        }
    }

    // New-bin candidate: penalize early (reuse open bins), relax late in stream
    // with a smooth easing so a fresh bin can win when open bins are fragmented.
    let open_f = open_bins_count as f64;
    score += is_new_bin * (20.0 * (1.0 - progress) + 1.5 * open_f.sqrt());

    // Mild penalty for opening bins when many are already open and fit.
    score += is_new_bin * 0.4 * fitting_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: subtract heavily when post_residual is small.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: dead space thresholds.
    // Residuals <= 10 are essentially dead space -> penalize strongly.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score += 25.0; // nearly dead space, wasteful
    } else if post_residual <= 25 {
        score += 8.0;
    } else if post_residual <= 50 {
        score -= 6.0; // still useful half-bin
    }

    // Modulo arithmetic on capacity fractions: residual classes by integer division.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual > half {
        score -= 10.0; // leaves more than half a bin, flexible
    } else if post_residual >= quarter && post_residual <= half {
        score -= 4.0;
    }

    // Lookahead: if next item fits in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // Exact match with next item is ideal chain placement.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        // Next item cannot use the leftover -> dead space penalty.
        score += 12.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual > 0 && post_residual < 10 {
            score += 20.0; // but not if it creates dead space
        }
    }

    // New-bin candidate: only attractive when open bins have poor fit potential.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // Cheaper to open a new bin when many bins are open with low mean residual
        // (fragmentation is high) or when fit here would be very tight/dead-spacey.
        let fragmentation = mean_residual / bin_capacity as f64;
        score -= 25.0 * (1.0 - fragmentation);
        if post_residual <= 10 {
            score -= 30.0; // prefer fresh bin over creating dead space
        }
        // Early in stream, opening bins is fine; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild consolidation pressure: fewer open bins relative to progress is good.
    score += (open_bins_count as f64) * 0.5 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste. Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals that cannot fit the lookahead item are less useful.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }
    // Perfect fit: strongly reward zero post residual.
    if post_residual == 0 {
        score -= 80.0;
    }
    // Reward tight fits relative to bin residual (waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are quite full or crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are not opened casually.
        score += 70.0;
        // Pressure grows with number of open bins (consolidate when many open).
        score += 8.0 * open_bins_count as f64;
        // If mean residual is large, existing bins have room; penalize new bin more.
        score += 1.5 * mean_residual;
        // Late in the stream, prefer using existing bins even more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    } else {
        // Mild reward for keeping bins consolidated when many are open.
        score -= 2.0 * open_bins_count as f64;
        // Favor bins with residual below mean (using up emptier-ish space evenly).
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Slight preference for larger post residuals only when they remain usable.
    if post_residual >= 20 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a mild quadratic penalty
    // on wasted space so large dead zones are punished harder than small ones.
    let waste = post_residual as f64;
    score += 0.35 * (waste * waste) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward if the next item exactly fills the
    // post residual (perfect chaining), penalize if next item cannot fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 >= next_item_size {
            // Next item fits: reward closeness to a perfect second fit.
            score -= 12.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item cannot fit here: penalize leftover space that will strand.
            score += 0.5 * (post_residual as f64);
        }
        // Exact match bonus: post_residual == next_item_size is ideal.
        if diff < 1.0 {
            score -= 8.0;
        }
    }

    // Relative-to-mean coupling: a bin whose residual deviates strongly from the
    // mean is either an outlier filler (good, low residual) or a stranded bin.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += 0.10 * dev; // below-mean residual (tighter than average): slight reward
    } else {
        score += 0.05 * dev; // above-mean residual: mild penalty
    }

    // Last-chance dynamics: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin, but relax the penalty late in
    // the stream or when many bins are open with large mean residual (all poor).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 20.0;
        // If open bins are quite full on average, opening a new bin is fine.
        if mean_residual < 0.25 * bin_capacity as f64 {
            new_bin_penalty -= 10.0;
        }
        new_bin_penalty -= 5.0 * progress;
        score += new_bin_penalty.max(0.0);
    }

    // Slight preference to fill bins with larger residual first when many bins
    // are open (keeps the number of partially-filled bins manageable).
    score += 0.02 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 50.0 * tightness * tightness;

    // Lookahead: penalize post_residual that cannot fit the next item (dead space)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0; // next item can follow here
        } else if post_residual > 0 {
            // dead space penalty scaled by how close it was to fitting
            let miss = (next_item_size - post_residual) as f64;
            score += 20.0 + 0.5 * miss;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Many open bins: prefer filling existing ones rather than spreading
    if open_bins_count > 3 {
        score -= 5.0 * (open_bins_count as f64).ln();
    }

    // Prefer bins with residual below mean (denser bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Time horizon: late in stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 40.0 * progress * tightness;

    // New-bin candidate: only attractive when item is large and no good fit exists
    if bin_residual == bin_capacity {
        score += 60.0 - 0.3 * (item_size as f64);
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mildly penalize large residuals slightly (keep bins flexible).
    // Later (progress ~ 1): strongly reward small residuals (tight packing matters).
    let prn = pr / cap;
    let t = progress;
    let coupling = prn * prn * (1.0 - t) - prn * t * (1.0 - t) * (1.0 - t);
    score += 18.0 * coupling;

    // Reward perfect / near-perfect fits with smooth decay.
    let tightness = 1.0 - prn;
    score -= 12.0 * tightness.powi(3);

    // Penalize dead space that cannot fit the next item (smooth quadratic gap).
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 0.35 * (gap / cap).powi(2) * cap;
        } else {
            score -= 6.0; // next item fits here: bonus
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty for very tight residual that risks wasting (smooth in prn).
    score += 4.0 * prn * (1.0 - prn) * (1.0 - t);

    // Slight preference to fill bins with residuals near the mean (balance).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * t;

    // New-bin candidate: encourage only when residuals are all poor fits.
    if bin_residual == bin_capacity {
        let poor = if next_item_size > 0 { (prn * cap - next_item_size as f64).max(0.0) } else { 0.0 };
        score += 10.0 - 0.5 * poor.min(20.0) as f64;
        score += 8.0 * t; // later in stream, opening new bins is costlier
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into capacity fractions.
    let quarter = (bin_capacity / 4) as u32;
    let class = match post_residual {
        0 => 0.0,                 // perfect fill
        r if r <= quarter / 2 => 1.0,   // tiny dead space
        r if r <= quarter => 2.0,
        r if r <= 2 * quarter => 3.0,
        r if r <= 3 * quarter => 4.0,
        _ => 5.0,                 // nearly empty bin after placement
    };
    score += class * class * 1.7;

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose leftover can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // leftover becomes dead space for the next item
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // or the fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - cap / 2.0).abs();
        // discourage opening new bins early or when open bins are roomy
        score = cap * 0.55 + open_bins_count as f64 * 2.0 + progress * 6.0;
        if mean_residual < cap * 0.35 {
            // open bins are fragmented; a fresh bin is reasonable
            score -= 25.0;
        }
        if fragmentation < 10.0 {
            score += 15.0;
        }
        if fitting_bins_count > 0 {
            score += 12.0; // some open bin fits; new bin must lose ties
        }
    } else {
        // Mild penalty for spreading items thin across many bins.
        if post_residual as f64 > mean_residual {
            score += 3.0;
        }
        // Reward packing into bins that are already partially consumed.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Modulo-based micro-tuning on post residual (harmonic classes refinement).
    let m = post_residual % 7;
    if m == 0 && post_residual > 0 {
        score -= 2.0;
    } else if m <= 2 {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A residual is "dead" if it is too small to hold even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals that cannot fit the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and stream progress.
        score += 15.0 + open_bins_count as f64 * 8.0 + progress * 20.0;
        // But if no open bin fits well (large dead space elsewhere), allow opening.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    }

    // Mild bonus for using bins whose residual is well-matched (tight fit).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Penalize large post_residual when mean residual is already high (fragmentation risk).
    if post_residual as f64 > mean_residual * 1.5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual).
    let pr = post_residual as f64;

    // Perfect match for the lookahead item: strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match for the lookahead item: graded reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + gap * 0.15);
    }
    // If the next item cannot fit in the leftover, penalize proportional to dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.35;
    }

    // Penalize leaving large residual relative to mean residual (wasteful bin usage).
    score += 0.5 * (pr - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins that already hold content (avoid needless new bins).
    if bin_residual < bin_capacity {
        score -= 8.0;
    } else {
        // New-bin candidate: only attractive when item is large and few bins fit.
        score += 10.0 * (item_size as f64 / 100.0) * (fitting_bins_count as f64).sqrt();
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Mild preference for using many open bins efficiently.
    score += 0.02 * open_bins_count as f64 * (pr / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (1.0 + t) * x * x - 2.0 * t * x;
    score += 40.0 * poly;

    // Reward tight fits, more so late in the stream (smooth in t)
    let fit = 1.0 - x;
    score -= (1.0 + 2.0 * t) * 30.0 * fit * fit;

    // Penalize residual that cannot fit the lookahead item (smooth gate)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 25.0 * (1.0 + t) * gap * gap;
        // Reward residual that exactly accommodates the next item
        let match_term = 1.0 - ((pr - next_item_size as f64).abs() / cap).min(1.0);
        score -= 15.0 * match_term * match_term;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - 0.5 * t);
    }

    // Mild pressure against hoarding many open bins with large residuals
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * x;
    score += 2.0 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: best-fit core — reward tight fits.
    score += (post_residual as f64) / cap * 5.0;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic class: dead-space class of the post residual.
    // Residuals in [1..9] are nearly useless for items >=10 (but items can be 1..100 here,
    // so scale thresholds by next item size instead).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as f64) < n {
            // This bin cannot host the next item: its leftover is dead unless tiny.
            let dead = post_residual as f64;
            // Penalize dead space more when it is "almost useful" (wasted potential).
            score += dead * (0.3 + 0.7 * (dead / n.max(1.0)));
        } else {
            // Can host next item: reward, especially if next fits snugly too.
            let next_post = post_residual as i64 - next_item_size as i64;
            if next_post >= 0 {
                score -= 10.0 + (next_post as f64).min(20.0) * 0.2;
            }
        }
    } else {
        // Last item: pure tightness.
        score -= 5.0;
    }

    // Harmonic modulo classes on post_residual: penalize residuals in awkward bands
    // (just above small-item sizes), reward residuals in reusable bands.
    let pr = post_residual;
    if pr > 0 {
        let band = pr % 25; // quarter-capacity harmonic
        match band {
            0 => score -= 6.0,          // exact quarter multiples: clean reusable space
            1..=9 => score += 4.0,      // sliver risk
            _ => {}
        }
        // Integer-division thresholds: residual >= half capacity is very reusable.
        if pr >= bin_capacity / 2 {
            score -= 4.0;
        } else if pr < bin_capacity / 10 {
            score += 6.0; // nearly-empty residual: low utility
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // fits well. Penalize the fresh bin moderately; the empty-bin call has
    // post_residual == capacity and next_item lookahead still applies.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.1;
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Crowd management: many open bins with low mean residual -> favor filling them.
    if open_bins_count > 2 && mean_residual < cap * 0.25 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Small tie-break noise-free deterministic coupling.
    score += (item_size as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize dead space that can't fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward residuals that can host the next item exactly.
    else if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are low.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.5 * (mean_residual / bin_capacity as f64);

    // Mild penalty for very large leftover relative to capacity.
    score += 15.0 * (post_residual as f64 / bin_capacity as f64).powi(2);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * -2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact or near-exact chain match is highly desirable.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 + 0.5 * chain_waste;
        } else {
            // Next item cannot follow: penalize proportionally to overflow gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    } else {
        // Last item: prefer tightest packing.
        score += 2.0;
    }

    // Compare post_residual against mean residual across open bins.
    // Keeping residuals balanced avoids accumulating many small unusable gaps.
    let post = post_residual as f64;
    if post < mean_residual {
        score -= 0.3 * (mean_residual - post);
    } else {
        score += 0.3 * (post - mean_residual);
    }

    // Penalize dead space that is too small to be useful for typical items.
    if post > 0 && post < 10.0 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when many bins are open but few fit, or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 100.0 - 40.0 * scarcity - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
