pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * progress;
    score += 12.0 * poly;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Lookahead: penalize if post_residual cannot fit next item, reward if it can
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 8.0 * (ni - pr) / cap * (1.0 - progress);
        } else {
            score -= 5.0 * (1.0 - (pr - ni) / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Penalize bins far from the mean residual (encourage balanced residuals)
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln() * 2.0 * tightness;

    // Prefer using existing bins over opening new ones, especially early
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer division into coarse "dead space" classes (capacity fractions).
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward tight fits strongly: post_residual in the lowest harmonic class.
    if post_residual < eighth {
        score -= 45.0;
    } else if post_residual < quarter {
        score -= 22.0;
    } else if post_residual < bin_capacity / 2 {
        score -= 8.0;
    } else {
        // Large leftover: penalize proportionally beyond the raw residual.
        score += (post_residual as f64 - cap * 0.5) * 0.35;
    }

    // Lookahead: if the next item exactly or nearly fills the leftover,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 60.0; // exact harmonic pairing
        } else if gap > 0 && (gap as u32) < eighth {
            score -= 30.0; // near pairing
        } else if gap < 0 {
            // Next item cannot use the leftover at all.
            score += (post_residual as f64) * 0.15;
        }
        // Harmonic class match: leftover divisible-ish by next item size.
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): only attractive when open bins are
    // badly fragmented or the fit here is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 55.0;
        // Discount when existing bins are fragmented / crowded.
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score -= fragmentation * 40.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If current fit is terrible (huge leftover), make new bin competitive.
        if post_residual > bin_capacity / 2 {
            score -= (post_residual as f64 - cap * 0.5) * 0.6;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-average residual
    // (i.e., fuller bins) as open_bins_count grows.
    let avg = if mean_residual.is_finite() { mean_residual } else { cap };
    if (post_residual as f64) < avg {
        score -= 6.0;
    } else {
        score += 6.0;
    }

    // Progression: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < eighth {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0; // tiny gaps heavily penalized
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 25.0 / (1.0 + tightness * 4.0);

    // Penalize bins whose residual was already small (fragmented bins).
    if (bin_residual as f64) < mean_residual * 0.6 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: only attractive when item is large relative
    // to capacity or no good fits exist; otherwise make fresh bins costly.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 45.0 - fill_ratio * 40.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternatives: must open
        }
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64
            && post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // leftover won't hold the next item anyway
        }
    }

    // Lookahead: reward leaving exactly the next item's size (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Early in stream, be slightly more conservative about fragmenting bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits too: mild bonus proportional to remaining slack after that
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // dead space penalty: next item cannot use the residual
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer filling below-average-residual bins (tighter bins)
    let dev = mean_residual - post_residual as f64;
    score += 0.2 * dev;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably
    if bin_residual == bin_capacity {
        // new bin candidate: base cost plus penalty scaled by number of usable open bins
        score += 250.0;
        if fitting_bins_count > 0 {
            score += 50.0 * fitting_bins_count as f64;
        }
        // early stream: new bins cheaper to open
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 100.0 * (1.0 - progress);
        }
    }

    // Large dead-space penalty for big residuals left in otherwise tight bins
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward small residuals that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    } else if post_residual < 20 {
        score += 5.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: favor bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Extra reward if next item fits snugly afterward.
            let rem = post_residual - next_item_size;
            if rem < 10 {
                score -= 6.0;
            }
        } else {
            score += 4.0;
        }
    } else {
        // Last item: minimize residual waste purely.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strong preference to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless current
    // residuals are globally poor or many bins already fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let global_quality = mean_residual / bin_capacity as f64;
        // Poor global residual state -> new bin more attractive.
        score += 30.0 * (global_quality - 0.5).max(0.0);
        score -= 12.0 * progress;
        score += 8.0 * (open_bins_count as f64).ln().max(0.0);
        // If item is large relative to capacity, a fresh bin is natural.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // But if this is the only fitting option among open bins, prefer reuse.
        if fitting_bins_count <= 1 {
            score += 20.0;
        }
    }

    // Mild penalty for spreading across many open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Coupling: penalize placements far above mean residual (fragmentation).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Tight fits rewarded more strongly as stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (30.0 + 60.0 * progress);

    // Penalize leaving residual that cannot fit the next item (smooth coupling).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 45.0 * gap * gap * (0.5 + progress);
        // Bonus if post residual still accommodates next item (smooth ramp).
        let fit_next = (pr / nx.max(1.0)).min(1.0);
        score -= 25.0 * fit_next * fit_next * (1.0 - progress);
    }

    // Last-chance bin: strong smooth reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 70.0 * (1.0 - norm_pr * norm_pr);
    }

    // Mild penalty tied to congestion, scaled by wasted-space ratio.
    let waste = (pr as f64 / cap) * (pr as f64 / cap);
    score += waste * (open_bins_count as f64).sqrt() * 8.0 * (0.5 + 0.5 * progress);

    // Smooth interaction: post residual vs mean residual deviation.
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * (0.3 + progress);

    // New-bin candidate handling: empty bin gets neutral-ish score that
    // decreases late in the stream, penalized early to force packing.
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.4 * progress) - 20.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item sizes
    let pr = post_residual;
    if pr > 0 {
        // Penalize residuals that fall into awkward classes (not near multiples of 10..50)
        let mut harmony = 0.0f64;
        for m in [10u32, 20, 25, 30, 40, 50].iter() {
            let r = pr % m;
            let d = (*m as f64 * 0.5 - r.min(*m - r) as f64).abs();
            harmony += d;
        }
        score += harmony * 0.15;

        // Reward residuals that exactly match likely next-item sizes
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 25.0; // perfect follow-up fit
            } else if next_item_size <= pr {
                let slack = (pr - next_item_size) as f64;
                score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            } else {
                score += 8.0; // next item cannot fit here
            }
        }
    } else {
        score -= 20.0; // perfectly closed bin
    }

    // Integer-division threshold classes on post_residual
    let q = pr / 10;
    match q {
        0 => score += 15.0,          // tiny dead space
        1 => score += 5.0,
        2 | 3 => score -= 3.0,       // sweet spot for medium items
        4 | 5 => score -= 6.0,
        _ => {}                       // large residual, neutral
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing bins fit poorly
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.55;
        if poor_fit && fitting_bins_count <= 2 {
            score -= 10.0;
        } else {
            score += 12.0;
        }
    }

    // Progress and congestion coupling
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0 * mean_residual / (bin_capacity as f64);
    score += open_bins_count as f64 * 0.3;

    // Fractional capacity coupling
    let frac = post_residual as f64 / bin_capacity as f64;
    score += (frac - 0.5).abs() * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (<= 10) are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += 120.0 + (10 - post_residual) as f64 * 15.0;
    } else if post_residual <= 20 {
        // Small gap: only useful if next item can use it.
        if next_item_size == 0 || next_item_size > post_residual {
            score += 25.0 + (20 - post_residual) as f64;
        } else {
            score -= 10.0; // gap is reusable by lookahead item
        }
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, prefer
    // filling existing bins; few open bins -> allow new-bin flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Mean residual coupling: penalize bins far below mean residual
    // (they are "odd" bins); prefer bins near the mean to homogenize.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no good fit exists:
        // i.e. this item leaves a large unusable gap in every open bin.
        // Give the empty bin a moderate base score; subtract when the
        // item fits perfectly (post_residual small but usable).
        score = 60.0;
        if post_residual < 10 {
            score -= 30.0; // near-perfect fit in fresh bin
        }
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 20.0;
        // Few fitting bins -> new bin less attractive (last-chance exists).
        if fitting_bins_count <= 1 {
            score += 15.0;
        }
    }

    // Lookahead synergy: if next item exactly fills the post residual,
    // reward this placement strongly.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (dead-space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0 + (10 - post_residual) as f64 * 10.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches
    // the next item's size (perfect chain), penalize wasteful gaps.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let diff = pr - nxt;
            if diff == 0.0 {
                score -= 500.0; // next item fits perfectly here
            } else if diff <= 10.0 {
                score -= 150.0 - diff * 5.0;
            } else {
                // leftover after next item: penalize proportionally to waste
                score += diff * 0.5;
            }
        } else {
            // next item cannot use this residual: residual likely dead space
            score += (nxt - pr) * 0.8;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are tight;
    // prefer filling tight bins (avoid scattering small leftovers).
    let pr = post_residual as f64;
    let mean = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    let rel = pr - mean;
    score += rel * 0.3;
    // non-linear coupling: very large residuals relative to mean are wasteful targets
    if rel > 20.0 {
        score += (rel - 20.0) * 0.7;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual; make it
    // attractive only when no good fit exists (large item, no tight bin helps).
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; becomes competitive when the
        // item is large relative to typical residuals.
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 100.0; // fresh bin can serve the next item too
        }
    }

    // Late in the stream, prefer consolidating (tighter fits weighted more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0 + 0.25 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // Penalize opening a new bin when open bins already fit, scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // But if mean residual is small (bins nearly full), new bin is fine.
        score -= mean_residual.min(30.0);
    }

    // Mildly prefer bins whose residual is below average (keeps big residuals for big items).
    score += 0.08 * ((bin_residual as f64) - mean_residual);

    // Prefer filling bins that are already relatively full (best-fit bias).
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let norm_post = post / cap;
    let norm_item = item / cap;

    // Base: prefer small post_residual (tight fits).
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly -> penalize larger residuals.
    let dead_space_penalty = norm_post.powi(3) * cap * (0.5 + 2.0 * progress * progress);
    score += dead_space_penalty;

    // Reward filling a bin nearly full, stronger as stream progresses.
    let fill_reward = (norm_item * norm_item) * cap * (0.3 + 0.7 * progress);
    score -= fill_reward;

    // Perfect-fit style bonus: post_residual near zero gets extra reward.
    let perfect = (1.0 - norm_post).powi(4);
    score -= 8.0 * perfect * (0.4 + 0.6 * progress);

    // Lookahead coupling: if the next item fits into the resulting residual, reward it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            // smooth reward decaying with leftover slack after next item
            score -= 6.0 * (1.0 - slack).powi(2) * (0.5 + 0.5 * progress);
        } else {
            // next item won't fit: penalize mildly, scaled by wasted potential
            let gap = (nxt - post) / cap;
            score += 4.0 * gap * gap * cap * 0.05;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins exist and could fit,
    // especially early/mid stream; smooth ramp with progress.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 20.0 + 25.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // allow new bin if item is huge relative to capacity (would leave tiny residual anyway)
        let relief = 18.0 * norm_item.powi(3);
        score += new_bin_penalty - relief;
    }

    // Mild coupling with mean residual: placing into a bin below-average residual
    // balances the pool of open bins.
    let mean_norm = mean_residual / cap;
    score += 3.0 * (norm_post - mean_norm) * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how it partitions the capacity.
    let post = post_residual;
    let class = post % 10;
    let div = post / 10;

    // Reward small post-residuals strongly (tight fits).
    if post == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else if post < 10 {
        score -= 60.0 - (post as f64) * 3.0;
    }

    // Dead-space penalty: residuals that no plausible item (1..100) can use well.
    // Residuals in [1,9] are near-dead; residuals that are exact tenths (class 0)
    // align with typical item granularity and are reusable.
    if class == 0 {
        score -= 8.0 + div as f64; // aligned residual is valuable
    } else {
        score += (10 - class) as f64 * 1.5; // misalignment penalty
    }

    // Harmonic coupling with next item: if the lookahead fits exactly in the
    // post-residual, this bin is a great chain candidate.
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt == post {
            score -= 120.0;
        } else if nxt < post {
            let leftover = post - nxt;
            let chain_class = leftover % 10;
            if leftover == 0 {
                score -= 90.0;
            } else if chain_class == 0 {
                score -= 25.0;
            } else {
                score += chain_class as f64 * 0.8;
            }
        } else {
            // Lookahead cannot use this bin's remainder at all.
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless post-residual is tiny/dead).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post >= 10 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // fit poorly. Penalize the fresh bin mildly; extra penalty early in stream
    // when consolidation is cheap, less when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 15.0; // next item pairs perfectly with current in fresh bin
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // already fragmented; discourage dumping large items there.
    let frag = mean_residual - post_residual as f64;
    if frag > 0.0 {
        score += frag * 0.3;
    } else {
        score += frag * 0.1;
    }

    // Item-size harmonic class: large items (divisible by large fractions of
    // capacity) deserve tight placement anywhere; small items are flexible.
    if item_size % 25 == 0 {
        score -= 5.0;
    }
    if item_size > 50 && post < 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=9) are nearly
    // unusable for future items; penalize them heavily.
    if post_residual > 0 && post_residual <= 9 {
        score += 25.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual >= 10 {
        // Usable gap: mild reward proportional to how well it fits next item.
        score -= 3.0;
    }

    // Lookahead: bonus if post_residual exactly accommodates next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 9 {
            score -= 12.0; // chain fit leaving tiny dead space
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space for the known next item.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate implicitly by rewarding open bins).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 2.0 * pressure;
    } else {
        score += 4.0 + 2.0 * pressure; // new-bin candidate penalized more when many bins open
    }

    // Prefer bins tighter than the mean residual (good packing progress).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 - (post_residual as f64) * 20.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // this is a perfect pairing — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward based on how tight the secondary fit is.
            let slack2 = post_residual - next_item_size;
            score -= 150.0 * (1.0 - slack2 as f64 / 100.0);
        } else {
            // Next item does NOT fit after this placement: penalize proportionally
            // to how much the leftover would be wasted relative to the next item.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.8;
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving more than average slack is wasteful; leaving less is efficient.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when existing bins could reasonably fit the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus penalty scaled by how many
        // alternatives exist and how small the item is relative to capacity.
        score += 250.0;
        if fitting_bins_count > 0 {
            score += 80.0 * (fitting_bins_count as f64).min(3.0);
        }
        // Early in the stream, new bins are cheaper (fewer bins to consolidate into).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Mild penalty for leaving very large dead space (> 40) that small items
    // are unlikely to fill later.
    if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize (raise score) large post-residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use: penalize proportionally.
        score += 0.25 * post_residual as f64;
    }

    // Last chance: strongly favor using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global waste pressure: if mean residual is high, prefer consolidating into
    // bins that reduce fragmentation (below-mean residual bins get priority).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score += 2.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // New-bin candidate handling: only attractive when existing bins are fragmented
    // or late in the stream; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / bin_capacity as f64).min(1.0);
        let pressure = fragmentation * (1.0 - 0.5 * progress) + 0.3 * (open_bins_count as f64 / 20.0);
        score = 30.0 + 60.0 * (1.0 - pressure.min(1.5) / 1.5);
    }

    // Mild exploration coupling with stream position: early on, tolerate looser fits
    // to keep options open; later, be stricter about wasted space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = 0.5 * t * t - 0.25 * t * t * t + 0.15 * t * t * t * t;
    score += 6.0 * poly * (pr / cap);

    // Smooth reward for tight fits (low post residual), scaled by progress.
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * tightness * (0.5 + t);

    // Penalize dead space: residuals too small for typical future items.
    let dead = (pr / cap).powi(3);
    score += 20.0 * dead * (1.0 - t * 0.5);

    // Lookahead: reward bins whose post residual still fits the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = 1.0 - ((pr - nx) / cap);
            score -= 8.0 * slack * slack;
        } else {
            let gap = (nx - pr) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 7.0 * (0.5 + t);
    } else if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening fresh bins unless tightness is poor.
    if bin_residual == bin_capacity {
        let waste = pr / cap;
        score += 14.0 - 10.0 * tightness * tightness;
        // Early stream: opening new bins is cheaper; late stream: reuse.
        score += 8.0 * (1.0 - t) - 4.0 * t;
        let _ = waste;
    }

    // Mild dispersion pressure: prefer bins deviating from mean residual.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Open-bin count pressure: many open bins -> prefer consolidation.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (class 0) are ideal.
    let class = (post_residual % (bin_capacity / 4)).min(post_residual); // classes 0..24, capped for tiny residuals
    score -= 30.0 * (1.0 - class as f64 / (bin_capacity as f64 / 4.0));

    // Dead-space penalty: residual in the awkward 1..=9 band is nearly unusable (min item size 10).
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    }

    // Reward bins whose post_residual matches the next item (harmonic pairing, k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 10.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // creates a gap the next item cannot use
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when a decent fit exists among open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Mild preference for bins already below mean residual (consolidating slack).
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Tight-fit bonus: item fills most of the bin.
    score -= 10.0 * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0 * (1.0 - post_residual as f64 / 10.0) + 15.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0; // moderately wasteful gap
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit: strongly reward closing the bin
    }

    // Tight-fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 12.0 * (fill_ratio - 0.8) / 0.2;
    }

    // Last-chance bin: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: penalize if post_residual is too small for the next item,
    // reward if the next item fits the leftover space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are large.
    score += open_bins_count as f64 * 0.3 * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced late in the stream or with pressure.
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits: new bin is necessary
        } else if next_item_size > 0 && next_item_size > bin_residual - item_size {
            // next item can't fit anywhere useful anyway; new bin slightly better
            score -= 5.0;
        }
        // Late in the stream, prefer closing out existing bins over new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild tie-breaker: prefer bins with smaller residuals (denser bins).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leftover after that matters.
            let after = post_residual - next_item_size;
            if after <= 10 {
                score -= 12.0; // near-perfect chain
            } else {
                score -= 4.0; // still useful
            }
        } else {
            // Next item won't fit here: dead space risk proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    } else {
        // Last item: just prefer tightest fit (score already post_residual).
    }

    // Penalize leaving residuals that are hard to fill (< 10 min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Last-chance bin: avoid opening a new bin if this fit is decent.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Compare against mean residual: bins with less residual than average
    // are "tighter" -> reward placing there to consolidate space.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New empty bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score = bin_capacity as f64 - 5.0;
        // If existing bins are fragmented (high mean residual vs item), a new
        // bin becomes more attractive.
        if mean_residual > 2.0 * item_size as f64 {
            score -= 10.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
        // If only this "bin" fits, opening is forced anyway.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal wasted space, but avoid near-zero useless residuals.
    if post_residual > 0 && post_residual < 10 {
        // Tiny sliver = dead space; penalize proportionally.
        score += (10 - post_residual) as f64 * 2.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but measure how well.
            let nxt_fit = (post_residual - next_item_size) as f64;
            score -= 12.0 - nxt_fit * 0.15;
        } else {
            // Next item won't fit here: mild penalty if we leave a large gap.
            score += (post_residual as f64) * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // New-bin candidate logic: opening a fresh bin is attractive when the item
    // fits poorly everywhere or residuals across open bins are already small.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) < 15.0;
        let crowded = open_bins_count as f64 > 0.0;
        let tight_globals = mean_residual < 20.0 && crowded;
        if poor_fit || tight_globals {
            score -= 35.0;
        } else {
            // Prefer reusing existing bins early on.
            score += 15.0 + (step_index as f64 / (total_items.max(1) as f64)) * 10.0;
        }
    }

    // Global residual pressure: when mean residual across open bins is low,
    // reusing bins is precious; penalize placements that waste big residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let residual_gap = (bin_residual as f64 - item_size as f64) - mean_residual;
    if residual_gap > 0.0 {
        score += residual_gap * 0.05 * (1.0 - progress * 0.5);
    }

    // Utilization bonus: reward high fill ratio of this bin.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 20.0;

    // Late in the stream, tighten packing (waste matters more).
    score += progress * (post_residual as f64) * 0.10;

    // Many open bins: discourage fragmentation by mildly penalizing large post-residuals.
    if open_bins_count > 5 {
        score += (post_residual as f64) * 0.03 * ((open_bins_count - 5) as f64).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth non-linear emphasis
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space matters more; early, keep bins flexible
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * coupling;

    // Penalize waste when this is the last fitting bin (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = (pr >= nxt) as i32 as f64;
        let snug = 1.0 - ((pr - nxt).abs() / cap);
        score -= 10.0 * fit_next * snug * snug;
    }

    // Slight preference for tighter bins when many bins are open
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Smooth penalty relative to mean residual (avoid fragmenting average slack)
    score += 0.2 * (pr as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Penalize residuals that fall into "dead zones": too small to fit typical
    // small items (<=10) but too large to be considered well-packed.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 8.0; // perfect fill, excellent
        } else if post_residual < 20 {
            score -= 4.0; // can host a small item later
        } else if post_residual < 30 {
            score -= 1.5;
        } else if post_residual < 50 {
            score += 0.5;
        } else {
            score += 3.0; // large leftover = loose packing
        }
    } else {
        score -= 20.0; // exact fit: always reward strongly
    }

    // Modulo-class coupling: post_residual mod 10 tells whether the leftover
    // aligns with the integer item-size lattice (sizes are multiples of 1..100).
    let align = post_residual % 10;
    if align == 0 {
        score -= 2.0; // residual aligns with common size classes
    } else {
        score += align as f64 * 0.15;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / cap); // tight follow-up fit is good
        } else {
            // next item cannot follow; leftover risks being wasted
            score += 1.0 + frac * 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing residuals are tight (mean residual small) and item is large.
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let large_item = item_size as f64 / cap;
        score += 25.0; // base cost of a new bin
        score -= 30.0 * mean_tightness * large_item; // open when bins are full & item big
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin mandatory
        }
    }

    // Late in the stream, consolidate: prefer filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (1.0 - frac);

    // Mild pressure against scattering across many open bins.
    score += 0.05 * open_bins_count as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible follow-up item are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }

    // Penalize dead space relative to what could still be useful: a residual
    // smaller than the next item's size (but nonzero) is likely wasted.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Reward leaving room exactly for the lookahead item.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small-residual dead space penalty (non-linear in gap size).
    let gap = post_residual as f64;
    if gap > 0.0 {
        score += 40.0 / gap; // tiny gaps are worst
    }

    // Open bins pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Mean-residual coupling: if this bin's residual is far below average,
    // it is a good consolidation target.
    score -= (mean_residual - bin_residual as f64) * 0.05;

    // New-bin candidate: only attractive if no decent fit exists.
    if bin_residual == bin_capacity {
        score += 18.0 + open_bins_count as f64 * -0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when this placement leaves room exactly matching the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff); // perfect match (diff=0) => -60 bonus
        // Gentle penalty if post_residual can't hold the next item at all (dead space risk)
        if (post_residual as u64) < (next_item_size as u64) {
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize very small unusable leftovers relative to mean residual.
    let tiny_threshold = (mean_residual * 0.15).max(6.0);
    if (post_residual as f64) < tiny_threshold {
        score += (tiny_threshold - post_residual as f64) * 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mildly prefer tighter (fuller) bins early; relax as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * (0.3 * (1.0 - progress));

    // Prefer filling bins when many bins are open (consolidation pressure).
    score -= 0.5 * open_bins_count as f64;

    // New-bin candidate: baseline reference; only chosen if no decent fit exists.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
