pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 1 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    // Smooth polynomial coupling of post_residual with progress:
    // early on, prefer tight fits mildly; late in stream, weight residual waste more heavily.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (1.0 + 3.0 * progress) * cap * 0.5;
    score += coupling;

    // Reward filling bins very tightly (small post_residual) with a smooth quadratic bonus
    let tightness = (1.0 - pr_norm).powi(3);
    score -= 12.0 * tightness;

    // Last-chance bin: strong reward to use it, scaled by progress
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // Penalize opening a new bin when decent fits exist; allow it when residuals are large
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_r = mean_residual.max(0.0);
        // New bin attractive only if open bins are mostly full (low mean residual)
        let scarcity = (cap - mean_r) / cap; // high when open bins nearly full
        score += 8.0 * (1.0 - scarcity) * (1.0 + open_bins_count as f64).ln();
        score -= 5.0 * scarcity * progress;
        // Slight late-stream preference to consolidate into fewer bins
        score += 6.0 * progress;
    }

    // Lookahead coupling: reward leaving room for the next item (smooth, non-linear)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_term = 1.0 - ((pr - nxt) / cap).abs();
        if match_term > 0.0 {
            score -= 6.0 * match_term * match_term;
        }
        // Penalize creating residual just below next item size (dead space), smooth ramp
        let dead = (nxt - pr) / cap;
        if dead > 0.0 && dead < 0.3 {
            score += 25.0 * dead * (1.0 - dead / 0.3);
        }
    }

    // Mild penalty when many bins are open and this placement leaves large residual
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * pr_norm * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 40.0;

    // Harmonic class of post_residual: residues divisible by common item
    // sizes (multiples of 10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    let mut bonus = 0.0;
    if pr % 10 == 0 { bonus += 4.0; }
    if pr % 20 == 0 { bonus += 3.0; }
    if pr % 25 == 0 { bonus += 3.0; }
    if pr % 50 == 0 { bonus += 4.0; }
    score -= bonus;

    // Lookahead: reward if next item exactly fits the post residual,
    // penalize if next item is larger than post residual (dead space).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= (next_item_size as f64) / (pr.max(1) as f64) * 8.0;
        } else {
            score += 6.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals of
    // open bins are all large (nothing fits well anywhere).
    if bin_residual == bin_capacity {
        let tight_exists = mean_residual < item_size as f64 + 5.0;
        if tight_exists {
            score += 60.0;
        } else {
            score += 5.0;
        }
    }

    // Prefer filling bins when many bins are open (consolidation).
    if open_bins_count > 2 {
        score -= 2.0;
    }

    // Early stream: be slightly greedy toward compact placements.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals too small to hold the smallest item are waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    } else if post_residual <= 35 {
        score += 8.0;
    } else {
        score -= 6.0; // generous leftover is fine
    }

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; penalize small leftovers more
            if post_residual < next_item_size && post_residual < 25 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins exist and pressure is high,
        // but allow opening when current bins have poor fit (small residual).
        score += pressure + 12.0;
        if bin_residual - item_size == 0 {
            score -= 40.0; // perfect fit in fresh bin
        }
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins with residuals close to item size (tight fit relative measure).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Slight preference for bins below mean residual (consolidate emptier bins).
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // exact chain fit
        } else if next_item_size <= post_residual {
            // reward proportional to how tightly next item fits
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 200.0 * tightness;
        } else {
            // next item cannot use leftover space: penalize large dead space
            score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    // Relative residual vs mean: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when a decent existing fit exists
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty, reduced late in stream or when few bins fit
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 120.0 * (1.0 - 0.3 * progress);
        if fitting_bins_count <= 2 {
            penalty -= 60.0;
        }
        if post_residual > 0 && next_item_size > 0 && next_item_size <= post_residual {
            penalty -= 80.0; // new bin can chain next item too
        }
        score += penalty;
    }

    // Waste penalty: leftover space that is too small for typical items (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize opening a new bin when open bins could fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let crowding = (open_bins_count as f64).ln().max(1.0);
        let new_bin_penalty = 60.0 + 40.0 * progress + 8.0 * crowding;
        // If this bin is the only fitting option, a new bin is less wasteful.
        let relief = if fitting_bins_count == 0 { 55.0 } else { 0.0 };
        // If next item fits perfectly into a fresh bin, allow opening.
        let lookahead_bonus = if next_item_size > 0 && next_item_size == bin_capacity {
            30.0
        } else {
            0.0
        };
        score += new_bin_penalty - relief - lookahead_bonus;
        return score;
    }

    // Reward tight fits: small post_residual is already the base score.
    // Extra reward when the bin becomes exactly full.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
        // Even more if next item won't fit the residual after placement anyway.
        if next_item_size > post_residual {
            score -= 12.0;
        }
    }

    // Lookahead coupling: penalize placements that leave a residual just barely
    // too small for the next item (dead space), reward residuals that fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            let waste_ratio = (next_item_size - post_residual) as f64 / next_item_size as f64;
            score += 10.0 * waste_ratio;
        }
    }

    // Penalize bins far below the mean residual (fragmenting candidates),
    // mildly favor bins near the mean (balanced depletion).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late in the stream, be greedier: prefer minimal post_residual harder.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += progress * (post_residual as f64) * 0.5;

    // Mild penalty for leaving very small unusable slivers (1..=5).
    if post_residual > 0 && post_residual <= 5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, small residuals become more valuable (tight packing).
    let progress_coupling = progress * (pr / cap) * (pr / cap) * cap;
    score += 0.35 * progress_coupling;

    // Reward tight fits (small post_residual) more strongly as stream advances.
    let tightness = 1.0 - (pr / cap);
    score -= (1.0 + 2.0 * progress) * tightness * tightness * 10.0;

    // Penalize waste relative to mean residual across open bins.
    score += 0.15 * (pr - mean_residual).abs();

    // If the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_gap = pr - nxt;
            score -= 8.0 * (1.0 - fit_gap / cap);
        } else {
            // post residual that cannot host next item: mild penalty scaled by progress
            score += 3.0 * progress * (pr / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight penalty when many bins are open and this one is nearly empty of use.
    if open_bins_count > 1 {
        score += 0.05 * (open_bins_count as f64).ln() * (pr / cap) * cap * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize residual space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i64; // 8 harmonic classes of residual space

    // Reward tight fits: penalize by how "wasteful" the leftover class is
    match class {
        0 => score -= 30.0,               // near-perfect fit, dead space < 1/8 capacity
        1 => score -= 18.0,
        2 => score -= 8.0,
        3 => score -= 2.0,
        4 => score += 0.0,
        5 => score += 4.0,
        6 => score += 9.0,
        _ => score += 14.0,               // mostly empty bin, wasteful to dump item here
    }

    // Modulo coupling: residuals that form "nice" sums with common item sizes are valuable.
    // Residuals divisible by small granularity (10/20/25) are reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 5.0; }
    } else {
        score -= 40.0; // bin exactly closed — ideal
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 35.0;
        } else if gap <= 10 {
            score -= 15.0;
        } else {
            score -= (10.0f64).min(gap as f64 / 8.0);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // post_residual cannot host next item: penalize proportionally to dead space
        score += (post_residual as f64).min(20.0) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when fit here is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // A fresh bin has huge residual; make it attractive only for large items
        // or when current stream is early (lots of future items to fill it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 100.0 - item_size as f64 * 0.4 - (1.0 - progress) * 15.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // room for pairing in the new bin
        }
    }

    // Mild preference to consolidate across many open bins
    score += open_bins_count as f64 * 0.3;

    // Small tie-break toward bins with residual close to item size (best-fit flavor)
    score += (bin_residual as f64 - item_size as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps after placement.
    // A residual that is too small to hold even the minimum future item is pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(post_residual).max(min_item)) {
        // gap below next item size and nonzero => likely dead space
        score += (next_item_size as f64 - post_residual as f64).max(0.0) * 2.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0; // hard dead-space penalty
    }

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 90.0;
    }
    // Penalize if next item almost fits but not quite (creates awkward gap).
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins / spreading items).
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open-bin pressure is high.
        score += 30.0 + pressure * 25.0;
        // But allow new bin when existing residuals are fragmented (high mean residual spread)
        if mean_residual < item_size as f64 && next_item_size > 0 {
            score -= 20.0;
        }
    } else {
        // Slight reward for using bins with larger residual (keeps small bins for small items)
        score -= bin_residual as f64 * 0.05;
    }

    // Stream progression: early on, be pickier about fits (more future flexibility matters).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * fit_ratio * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize proportional slack left after that
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            score -= 120.0 - slack_after_next * 2.0;
        } else {
            // next item won't fit: penalize large unusable post residual
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += gap * 6.0; // near-miss dead space is costly
            } else {
                score += 40.0 + post_residual as f64 * 0.5;
            }
        }
    }

    // Compare post_residual to mean residual: prefer bins whose residual
    // shrinks toward/below the mean (tight packing across the fleet)
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when existing bins fit decently,
    // unless the item is large and would leave tiny unusable residue elsewhere
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let early = step_index as f64 / (total_items.max(1) as f64);
        // new bins are cheap early, expensive late
        score += 250.0 + pressure * 4.0 * (1.0 - early);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0; // a fresh bin guarantees room for the next item
        }
    }

    // Mild penalty for leaving residue in the awkward 1..10 band (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit: reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Penalize small post-residuals that are too small to be useful
    // (dead space), but reward exact/near-exact fills.
    if post_residual > 0 {
        let min_useful = 10u32.min(post_residual); // smallest plausible item
        if post_residual < min_useful {
            score += 15.0; // tiny dead space penalty
        }
    } else {
        score -= 30.0; // perfect fill bonus
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit here; slight penalty for wasting residual
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): prefer reusing open bins unless
    // the fit is poor or many bins are already open with slack.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized when good fitting bins exist.
        score += 8.0 + 0.5 * open_bins_count as f64;
        // But if the item is large relative to mean residual, opening
        // a fresh bin may be better; reduce the penalty.
        if item_size as f64 > mean_residual {
            score -= 6.0;
        }
        // Late in the stream, avoid opening bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer filling bins with large residuals (consolidate space).
    score -= 0.05 * bin_residual as f64 * fit_ratio;

    // Slight preference for bins with below-mean residual (pack fuller bins).
    score += 0.03 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = post;

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate larger residuals (favor new bins for big items);
    // later, squeeze tight (penalize waste more aggressively).
    let waste_penalty = 60.0 * (pr * pr) * (0.4 + 1.2 * progress);
    score += waste_penalty;

    // Reward near-perfect fits with a smooth bump: (1-pr)^4 grows as pr -> 0
    score -= 25.0 * (1.0 - pr).powi(4);

    // Dead-space term: residuals too small for typical items are quadratic dead loss
    let dead = if post > 0.0 && post < 10.0 { (10.0 - post) * (10.0 - post) * 0.8 } else { 0.0 };
    score += dead;

    // Lookahead coupling: smooth interaction of post-residual with next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // if post residual can hold next item, reward; else penalize proportionally
        let gap = (nxt - post).abs();
        score += 0.35 * gap * (1.0 - progress);
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        }
    } else {
        // last item: strongly prefer filling bins completely
        score -= 30.0 * (1.0 - pr);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation)
    let frag = mean_residual / cap;
    score += 5.0 * frag * (pr - frag).abs() * (open_bins_count as f64).sqrt();

    // New-bin candidate: make empty bin attractive only when its residual is best used
    if bin_residual == bin_capacity {
        // smooth gate: prefer new bin early or when item is large relative to capacity
        let size_ratio = item_size as f64 / cap;
        score += 10.0 * (1.0 - size_ratio) * (1.0 - progress);
        score -= 12.0 * size_ratio * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: classify post_residual into
    // "dead space" classes via integer division thresholds.
    // Class 0: post_residual == 0 (perfect fit) -> strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Harmonic bucket: post_residual / 10 gives class 0..9.
        let class = (post_residual / 10) as f64;
        // Dead-space penalty grows super-linearly in the class:
        // small residuals (class 0-1) are nearly unusable, larger ones reusable.
        score += class * class * 1.5;

        // Fractional capacity coupling: how close post_residual is to the
        // next harmonic fraction of capacity (25, 50, 75).
        for frac in [25u32, 50u32, 75u32] {
            let d = (post_residual as i64 - frac as i64).abs() as f64;
            if d < 8.0 {
                score -= (8.0 - d) * 2.0; // reward near-harmonic residuals
            }
        }
    }

    // Lookahead: reward if the NEXT item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 25.0 - (slack as f64).min(25.0) * 0.5;
    }
    // Penalize if next item almost fits but not quite (tempting dead space).
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has no scarcity value yet.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decay as stream progresses
        // (early on, opening bins is cheap and builds flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0 - 30.0 * (1.0 - progress);
        // If many open bins already, discourage one more unless item is large.
        score += open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            score += 50.0; // never open when a last-chance bin exists
        }
    }

    // Mild preference for tighter bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Reward tight fits relative to residual.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Penalize wasting a large residual on a small item.
    if item_size < bin_residual / 3 {
        score += 8.0;
    }

    // Open-bin pressure: fewer open bins -> prefer existing bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        score += 6.0;
    }

    // Mean residual coupling: placing into a bin below mean residual is good consolidation.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // New-bin candidate: make it attractive only when item is large relative to mean residual
    // or no good fit exists; otherwise keep it mildly unattractive.
    if bin_residual == bin_capacity {
        let base = 8.0 + 0.35 * open_bins_count as f64;
        score = base
            + (bin_capacity - post_residual) as f64 * 0.5
            - if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 { 10.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: exact/near-exact fill bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 500.0;
        } else {
            score += diff * 2.0;
        }
        // Penalize dead space that next item cannot use
        if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only
    // when current bin would leave large dead space
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score = 60.0 + waste * 0.5 - (next_item_size as f64 * 0.1);
        if fitting_bins_count == 1 {
            score += 400.0; // don't open new bin when it's the only fitting one
        }
    }

    // Late-stream tightening: reduce waste tolerance as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra reward for a tight two-item packing.
        let gap = post_residual - next_item_size;
        score -= (gap == 0) as i32 as f64 * 10.0;
        // Penalize if next item fits nowhere else well (few fitting bins now).
        if fitting_bins_count <= 2 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slightly prefer conserving this bin's residual.
        score += 5.0;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: keep it attractive when open bins would waste space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global state.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 45.0;
        // Early in stream: opening bins is cheap (more future items to fill them).
        new_bin_score -= 25.0 * (1.0 - progress);
        // Many open bins with large mean residual: prefer reusing.
        new_bin_score += (open_bins_count as f64) * 1.5;
        new_bin_score += mean_residual / 10.0;
        // Large items prefer fresh bins.
        if item_size > bin_capacity / 2 {
            new_bin_score -= 12.0;
        }
        return new_bin_score;
    }

    // Penalize leaving residuals in the awkward zone (unfillable by typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Prefer filling bins with lower residual among comparable fits (fragmentation control).
    score += (bin_residual as f64 - item_size as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let prog = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer small post_residual, with smooth polynomial shaping.
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * (0.5 + prog);

    // Penalize post_residual that is too small to hold typical future items
    // (dead space), smoothly via a saturating quadratic.
    let dead = (1.0 - (post / 10.0)).max(0.0);
    score += 6.0 * dead * dead * (1.0 - prog);

    // Lookahead: if the next item fits into the resulting post_residual,
    // reward; if it just barely misses, penalize slightly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 8.0 * (nx / cap) * (0.5 + prog);
        } else {
            score += 4.0 * (1.0 - (post / nx)) * (0.3 + prog);
        }
    }

    // Last chance: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + prog);
    }

    // New-bin candidate: only attractive when open bins are quite full on
    // average or few bins are open; penalize opening bins otherwise.
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 10.0 * (1.0 - mean_norm) * (1.0 - prog) + 4.0 * (1.0 - mean_norm);
        if open_bins_count > 0 {
            score += 3.0;
        }
    }

    // Mild preference to keep many bins' residuals balanced (avoid many
    // half-empty bins lingering), smoothly coupled with progress.
    score += 2.0 * ((post - mean_residual).abs() / cap) * prog;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: mod capacity/4 buckets
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter.max(1);
    let class_rank = (class as f64 / quarter as f64) * 10.0;

    // Penalize post_residuals in "dead zone" classes (too small to fit typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable dead space
    }

    // Reward post_residual classes that match next item size (harmonic resonance)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual >= next_item_size && post_residual < next_item_size * 2 {
            score -= 15.0; // post residual fits next item nicely
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Integer-division threshold: post_residual in third harmonic band gets bonus
    let third = bin_capacity / 3;
    if post_residual / third.max(1) == 1 {
        score -= 8.0;
    } else if post_residual / third.max(1) == 2 {
        score += 5.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening unless residuals are tight
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 10.0;
        }
    }

    // Fractional class penalty scaled by stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += class_rank * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest plausible future item are wasted space.
    if post_residual > 0 {
        let dead_threshold = 10.0_f64.min(next_item_size as f64);
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 12.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if post_residual is smaller than the next item (dead for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins; opening new bins becomes more costly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Last-chance bin: if this is the only bin that fits, avoid wasting it
    // on a loose fit unless the fit is tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if tightness < 0.7 {
            score += 10.0 * (0.7 - tightness);
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // fits are poor or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let base_cost = 25.0 + open_bins_count as f64 * 1.5;
        let relief = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        score += base_cost - relief;
        // Large items start fresh bins more willingly.
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
    }

    // Slight preference for bins below mean residual (keep residual spread balanced).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/tight fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins where next item fits the new residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 60.0;
        } else {
            // next item cannot follow here: penalize proportionally to overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 1.5;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Compare residual against mean residual across open bins
    let mr = mean_residual.max(0.0);
    let pr = post_residual as f64;
    if pr > mr + 20.0 {
        // leaving much more slack than average: wasteful
        score += (pr - mr - 20.0) * 0.5;
    } else if pr < mr {
        score -= (mr - pr) * 0.3;
    }

    // Penalize using a fresh bin when open bins could still absorb the item
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // unless the fit in existing bins would be terrible (large post_residual elsewhere)
        score += 250.0 + 0.5 * mean_residual;
    }

    // Mild preference to fill bins earlier in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post residuals that can't hold even the smallest item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 20.0 * next_fit;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0; // post space likely wasted for the next item
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Time horizon: late in the stream, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Penalize opening new bins when many bins are already open and mean residual is high.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let avg_need = mean_residual.max(0.0);
        score += 25.0 + 0.5 * open_bins_count as f64;
        if avg_need >= item_size as f64 {
            score += 20.0; // existing space exists; don't open a bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    } else {
        // Favor bins whose residual deviates below mean (tighter bins get priority).
        let dev = mean_residual - bin_residual as f64;
        score -= 0.3 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling: base tightness reward, non-linear in x and t
    let mut score = 100.0 * x * x * (1.0 + 0.8 * t) - 60.0 * x * (1.0 - t) * (1.0 - t);

    // Reward exact-ish fits smoothly (peak at x = 0)
    score -= 30.0 * (1.0 - x) * (1.0 - x) * x;

    // Lookahead coupling: penalize residual that can't smoothly accommodate next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit = (x - nx).max(0.0);
        score += 25.0 * nx * (x - fit) * (x - fit) * 4.0;
        score -= 15.0 * (1.0 - (x - nx).abs() * 2.0).max(0.0);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - x);
    }

    // Mild dispersion penalty vs mean residual
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: prefer opening early in the stream, penalize later
    if bin_residual == bin_capacity {
        score += 10.0 * t * t + 5.0 * x;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual gap: small gaps (<10) are dead space -> penalize
    if post_residual < 10 {
        score += 25.0;
    }

    // Integer-division harmonic classes of post_residual (decile bins)
    let decile = post_residual / 10;
    score += match decile {
        0 => 20.0,  // 0-9: nearly unusable
        1 => 8.0,   // 10-19
        2 => 4.0,   // 20-29
        3 => 2.0,   // 30-39
        4 => 0.0,   // 40-49: sweet spot
        5 => -2.0,  // 50-59
        6 => -3.0,  // 60-69
        7 => -4.0,  // 70-79
        _ => -6.0,  // 80-99: plenty of room left
    };

    // Modulo-5 harmonic: residuals divisible by 5 pair well with items on a 5-grid
    if post_residual % 5 == 0 {
        score -= 3.0;
    }
    if post_residual % 10 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            // harmonic class of the follow-up gap
            score -= if gap < 10 { 5.0 } else if gap < 20 { 12.0 } else { 18.0 };
        } else {
            // next item cannot follow here: mild penalty scaled by overflow
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin anyway
        } else if fitting_bins_count == 1 {
            score += 20.0; // resist abandoning the last fitting bin
        }
        // late in the stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Spread-awareness: prefer bins below mean residual (tighter packing)
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Prefer fewer open bins when nearly identical fits
    score += 0.5 * open_bins_count as f64;

    // Exact fit is always best
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 8.0 / (1.0 + fit_ratio);

    // Open-bin pressure: discourage spreading across many bins slightly.
    score += 0.15 * open_bins_count as f64;

    // Lookahead: bonus if the post residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize if post residual is a small gap that cannot host the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // alternatives are scarce or the fit elsewhere would be terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin
        } else {
            // Base penalty for opening a new bin when one could fit.
            score += 18.0 + 2.0 * fitting_bins_count as f64;
            // But allow opening if all fitting bins would leave near-dead space.
            if post_residual >= bin_capacity - item_size && item_size >= bin_capacity / 2 {
                score -= 10.0; // large item: fresh bin keeps flexibility
            }
            // Late in the stream, prefer consolidating into existing bins.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 20.0 * progress;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Prefer bins whose residual deviates favorably from the mean (pack tighter ones).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: strongly reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: item + next item fill the bin
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness of the chain
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item does NOT fit: penalize wasted potential
            score += 15.0 + 0.25 * gap;
        }
    } else {
        // Last item: prefer minimal leftover
        score += 0.1 * post_residual as f64;
    }

    // Penalize creating unusable dead space (post_residual too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: placing into a bin with large residual is good,
    // but avoid draining bins below mean too aggressively.
    let cap = bin_capacity as f64;
    let residual_ratio = bin_residual as f64 / cap;
    score -= 10.0 * (residual_ratio - 0.5);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good open-bin fit exists
    if bin_residual == bin_capacity {
        // base penalty to prefer reusing open bins
        score += 55.0;
        // but if next item is huge and current item is large, a fresh bin chains well
        if next_item_size >= 70 && item_size >= 60 {
            score -= 45.0;
        }
        // fewer fitting bins -> new bin less costly
        score -= 8.0 * (fitting_bins_count as f64).min(3.0);
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference to fill bins that are already quite full
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
