    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely useful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer using open bins when mean residual is large enough.
        if mean_residual >= item_size as f64 + 5.0 {
            score += 50.0;
        }
        // Early in stream, allow new bins more freely for large items.
        score += (1.0 - progress) * 10.0 + item_size as f64 * 0.2;
        score -= open_bins_count as f64 * 2.0;
    }

    // Slight preference for filling fuller bins (small residual before placement).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Global balance: penalize bins far from mean residual to keep residuals uniform.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth in [0,1])
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: dead space penalized more as stream progresses
    let dead_penalty = pr * pr * (1.0 + 2.5 * progress) + 0.8 * pr * pr * pr;
    score += dead_penalty * bin_capacity as f64;

    // Reward tight fits (small post_residual) with smooth exponential decay
    let tightness = (-pr * 8.0).exp();
    score -= 6.0 * tightness;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Avoid fragmenting bins when the next item could use this residual
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= post_residual as f64;
        if next_fits {
            score -= 4.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // residual too small for next item: penalize unusable leftover
            score += 3.0 * pr * (1.0 - progress);
        }
    }

    // Slight preference for bins below mean residual early on (balance), stronger later
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 2.0 * dev * (0.5 + progress);

    // Mild inertia against opening new bins when many are open and fit is decent
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are more likely to be completed later.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Reward tight fits strongly (near-zero post residual).
    if post_residual == 0 {
        score -= 500.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 200.0;
    } else {
        // Penalize residuals that are hard to fill: those below the smallest item.
        if post_residual < 10 {
            // dead space (unreachable, kept for safety)
            score += 300.0;
        }
        // Harmonic class penalty: residuals in awkward bands get punished.
        let class = post_residual % 25; // modulo classes of capacity/4
        score += (class as f64) * 2.0;

        // Residuals that can host the next item are valuable.
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 60.0 + 0.5 * (next_item_size as f64);
                // exact match with next item => excellent chaining
                if next_item_size == post_residual {
                    score -= 120.0;
                }
            } else {
                // leftover too small for next item: penalize proportionally
                score += 20.0 + 0.3 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; relax late in the stream or when
        // open bins are already crowded.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / cap; // low mean residual => bins are full
        let mut new_bin_cost = 180.0 - 60.0 * progress - 80.0 * (1.0 - crowded);
        if fitting_bins_count == 0 {
            new_bin_cost = -50.0; // must open a bin
        }
        score += new_bin_cost;
    }

    // Prefer filling bins with below-average residual (balance + consolidation).
    score += 0.4 * ((bin_residual as f64) - mean_residual);

    // Slight preference for bins with larger residual when many bins are open,
    // to consolidate usage into fewer bins.
    score -= 0.1 * (open_bins_count as f64) * (bin_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Gap too small for any item (min size 1..100 unknown, but small gaps are wasteful)
            score += (10.0 - gap) * 12.0;
        } else if gap < 20.0 {
            score += (20.0 - gap) * 4.0;
        } else if gap < 35.0 {
            score += (35.0 - gap) * 1.5;
        }
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones,
    // making new bins less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0 + progress * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure; only attractive
        // when current bin would leave a bad dead space.
        score += 15.0 + pressure;
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0; // dead space elsewhere justifies a fresh bin
        }
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Slight preference toward bins tighter than average (compactness).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            // Perfect 2-step match: post_residual exactly fits the next item
            score -= 60.0;
        } else if post_residual as u32 >= next_item_size {
            // Next item still fits after this placement: mild reward scaled by tightness
            let tightness = 1.0 - (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 10.0 + 20.0 * tightness;
        } else {
            // Dead space: next item cannot use the leftover
            let waste = nxt - post_residual as f64;
            score += 8.0 + 0.5 * waste;
        }
    } else {
        // Last item: just prefer minimal leftover
        score += 5.0;
    }

    // --- Relative to mean residual across open bins ---
    let pr = post_residual as f64;
    if pr < mean_residual {
        // Tighter than average: good consolidation
        score -= 0.3 * (mean_residual - pr);
    } else {
        // Looser than average: penalize creating outlier large residuals
        score += 0.15 * (pr - mean_residual);
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only open bin that fits; strongly prefer using it over opening a new bin
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new empty bin: penalize slightly so we prefer existing bins with good fits,
        // but allow it when the lookahead match is perfect or few bins fit the item.
        let mut new_bin_penalty = 18.0;
        if next_item_size > 0 && post_residual as u32 >= next_item_size {
            new_bin_penalty -= 10.0;
        }
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 12.0;
        }
        // Late in the stream, closing out bins cleanly matters more
        new_bin_penalty -= 6.0 * progress;
        score += new_bin_penalty.max(0.0);
    }

    // --- Small residual hygiene: avoid leaving tiny unusable slivers ---
    if pr > 0.0 && pr < 10.0 {
        score += 6.0;
    }

    // Mild preference for bins with fewer total open bins (bin-count pressure)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

