    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins below mean residual (fill emptier bins less; keep balanced residuals).
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be more conservative: penalize opening/wasting space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // good pairing in a fresh bin
        }
    }

