}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (0.5 + 1.5 * progress) - norm_pr * norm_pr * norm_pr * (1.0 + progress);
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses (dead space matters later).
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.4 + 0.6 * progress);

    // Penalize post_residual that wastes space relative to the next item's need.
    if next_item_size > 0 {
        let gap = norm_pr - norm_next;
        score += 15.0 * gap * gap * (0.5 + progress);
        // Bonus if post_residual exactly accommodates next item smoothly.
        if gap >= 0.0 && gap <= 0.15 {
            score -= 10.0 * (1.0 - gap / 0.15) * (0.5 + progress);
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (0.6 + 0.4 * progress);
    }

    // Mild penalty for spreading across many open bins; smooth in open count.
    let openness = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 12.0 * openness * norm_pr * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual stays coherent.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: make it attractive only when the fit is poor or stream is early.
    if bin_residual == bin_capacity {
        let poor_fit_bonus = 1.0 - (1.0 - norm_item) * (1.0 - norm_item);
        score += 20.0 * poor_fit_bonus * (1.2 - progress);
        score -= 15.0 * norm_item * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals divisible by common
    // item sizes (10, 20, 25, 50) are "reusable" classes and get rewarded.
    if post_residual > 0 {
        if post_residual % 50 == 0 {
            score -= 12.0;
        } else if post_residual % 25 == 0 {
            score -= 8.0;
        } else if post_residual % 10 == 0 {
            score -= 5.0;
        } else if post_residual % 20 == 0 {
