            } else {
                score += 3.0;
            }
        } else {
            // Next item won't fit here regardless; slight penalty for tight bins.
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Prefer bins below mean residual (fill emptier bins first when equal).
    score += (mean_residual - bin_residual as f64) * 0.02;

    // New-bin candidate: make empty bins attractive only when the item is
    // large (harmonic class of large items) or few bins fit the item.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.5 || fitting_bins_count <= 1 {
            score -= 5.0;
        } else {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
