    let min_future = if next_item_size > 0 { next_item_size } else { 10 } as f64;
    let pr = post_residual as f64;

    if pr > 0.0 {
        if (pr as u32) < next_item_size && next_item_size > 0 {
            // Gap cannot fit the known next item: dead space penalty scaled by tightness.
            score += 25.0 * (1.0 - pr / min_future.max(1.0));
        }
        if pr < 10.0 {
            // Tiny sliver below conservative minimum item size: near-total waste.
            score += 30.0 * (1.0 - pr / 10.0);
        }
    }

    // Reward exact/near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size as u32 <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, allow it.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 3.0 * progress);

    // Prefer bins tighter than the mean (better packing), penalize loose bins.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: neutral-ish baseline; only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // New bin gets moderate score: worse than a good existing fit, better than dead space.
        score += 15.0 + pressure;
        // Early in stream, opening bins is cheap; late, conserve.
        score *= 1.0 - 0.3 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual)
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-chain: strongly favored
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: mild reward scaled by how snugly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.3;
        } else {
            // Next item won't fit: penalize wasted capacity that blocks the chain
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.25;
        }
    } else {
        // Last item: just minimize post_residual (already base)
        score += 0.0;
    }

    // Penalize creating unusable dead space (small post_residual that nothing can use)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Slight preference to fill older/more-full bins as stream progresses,
    // discouraging excessive open bins
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 10.0;

    // Mild penalty for opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        score += 5.0 + (open_bins_count as f64) * 0.5;
        // But if lookahead suggests a perfect future chain in a fresh bin, ease it
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // next item's size is wasted unless it's tiny.
    let tight_fit_bonus = (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;
    score -= tight_fit_bonus;

    // Penalize residual that is too small to ever be useful (>0 but < min item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly favor this bin (chained placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a penalty unless current bin
    // fits are poor (large post_residual) or mean residual is already high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = post_residual as f64; // for empty bin, post_residual == capacity - item
        let threshold = 35.0 + 30.0 * progress;
        score += 15.0 + (poor_fits - threshold).max(0.0) * 0.8
               + (mean_residual - 20.0).max(0.0) * 0.3;
        // Early stream: keep open bin count low by discouraging new bins.
        if open_bins_count < 3 {
            score += 20.0;
        }
    }

    // Mild preference for fuller bins as stream progresses (first-fit-like bias).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (0.5 + progress);

    // Prefer bins below mean residual (balance but bias toward fuller bins late).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 8.0 * poly;

    // Reward tight fits more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + 3.0 * progress);

    // Penalize dead space: post_residual too small to ever fit typical items
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress);
        } else {
            // Reward leaving space exactly usable by the lookahead item
            let fit_gap = (pr - nxt) / cap;
            score -= 4.0 * (1.0 - fit_gap).max(0.0) * (1.0 - progress);
        }
    }

    // Last-chance bonus: only one bin can fit this item
    if fitting_bins_count == 1 {
        score -= 6.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * (open_bins_count as f64).ln();

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: penalize unless residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            mean_residual / cap
        } else {
            0.0
        };
        score += 5.0 - 10.0 * fragmentation * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes on capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: tiny dead space (<= 10) is excellent — reward strongly.
    if post_residual <= 10 {
        score -= 25.0;
    }
    // Class B: unusable dead space (post_residual < min item size) is terrible — penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 0.0; // unreachable given sizes >= 1, keep harmonic structure
    }
    if post_residual >= 10 && post_residual < 20 {
        score -= 8.0;
    }

    // Integer-division thresholds: post_residual in [20,40) mid class.
    let class = post_residual / 20; // 0,1,2,3,4,5 harmonic buckets
    score -= match class {
        0 => 20.0,
        1 => 6.0,
        2 => 0.0,
        3 => 4.0,
        4 => 10.0,
        _ => 14.0,
    } as f64;

    // Modulo coupling with next item: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 30.0;
        } else if gap <= 15 {
            score -= 12.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this residual — mild penalty scaled by wasted fraction.
        score += 5.0 + 10.0 * (pr / c);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: neutral-ish baseline, opened only when fits are bad.
    if bin_residual == bin_capacity {
        score = 0.45 * c + 0.10 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 4.0;
        }
        // If many fitting bins exist, new bin is less attractive.
        if fitting_bins_count > 0 {
            score += 8.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * progress;
    }

    // Prefer tighter (fuller) bins generally.
    score -= 6.0 * (1.0 - pr / c);

    // Spread awareness: if this bin is much tighter than average, reward.
    score -= 3.0 * (mean_residual - pr).max(0.0) / c;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (<=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 4.0 * post_residual as f64;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Penalize wasting a large residual on a small item (poor space utilization).
    let utilization = item_size as f64 / bin_residual.max(1) as f64;
    score += (1.0 - utilization) * 15.0;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += new_bin * (20.0 + 30.0 * open_bins_count as f64 * (0.3 + 0.7 * progress));

    // If next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Penalize if next item would fit better in current residual than post-residual.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 25.0;
    }

    // Mild preference for bins below mean residual (balance residuals).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits perfectly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            // reward tightness of the follow-up fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize dead space relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    }

    // Penalize large post_residual (wasted space) with a convex term.
    let pr = post_residual as f64;
    score += 0.15 * (pr * pr) / bin_capacity as f64;

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    score += 0.8 * (pr - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // no reasonable fit exists (large post_residual otherwise).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) > 0.5 * bin_capacity as f64;
        if poor_fit && progress > 0.2 {
            score -= 12.0; // prefer fresh bin over wasting a big residual
        } else {
            score += 25.0; // discourage opening new bins when fits are decent
        }
    }

    // Mild reward for filling bins completely (post_residual near 0).
    score -= 10.0 * (1.0 - pr / bin_capacity as f64) * (pr as f64 / 10.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to wasted lookahead.
        score += 0.1 * (next_item_size as f64 - post_residual as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Compare against mean residual: bins below mean residual are already tight,
    // prefer using them to consolidate.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Time horizon: early in stream, be more willing to open new bins
    // (new-bin candidate gets a boost early, less later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress) - 5.0 * progress;
    }

    // Too many open bins: discourage opening yet another one.
    if bin_residual == bin_capacity {
        score += 0.5 * open_bins_count as f64;
    }

    // Large items should preferentially go into larger-residual bins.
    score += 0.05 * (item_size as f64 / bin_capacity as f64) * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_post * (1.0 + 0.8 * progress - 0.6 * progress * progress);
    let mut score = poly * (1.0 + 0.5 * norm_post * norm_post);

    // Reward tight fits (small post_residual) more strongly later in the stream.
    score -= (1.0 - norm_post) * (1.0 - norm_post) * 20.0 * (0.5 + progress);

    // Penalize dead space relative to mean residual of open bins.
    score += 0.15 * (post - mean_residual).abs();

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 * (1.0 - post / cap);
    } else if next_item_size > 0 && (next_item_size as f64) > post {
        score += 3.0;
    }

    // New-bin candidate: mildly discourage opening new bins early, allow late.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 2.0 * open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Classes based on integer division of capacity into deciles.
    let post_class = post_residual / 10;
    let item_class = item_size / 10;

    // Penalize residuals that fall into awkward "dead zone" classes (1..9 small scraps)
    match post_class {
        0 => score += 45.0,                      // nearly full: excellent, reward heavily
        1 => score += 12.0,                      // tiny scrap, mostly dead space
        2 => score += 8.0,
        3 => score += 5.0,
        4 => score += 2.0,
        5 => score -= 2.0,                       // half-full leftover: flexible
        6 => score -= 1.0,
        7 => score -= 3.0,
        8 => score -= 4.0,
        9 => score -= 5.0,
        _ => score -= 6.0,                       // empty-ish (new bin case)
    }

    // Reward when leftover class matches the class of the next item (harmonic pairing)
    let next_class = (next_item_size / 10) as f64;
    if next_item_size > 0 {
        let class_gap = ((post_class as f64) - next_class).abs();
        score += 1.5 * class_gap;                // leftover should anticipate next item
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 10.0;                       // perfect slot for the lookahead item
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are all bad.
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / bin_capacity as f64;
        // If mean residual is small, open bins are nearly useless -> new bin is fine.
        score += 55.0 * (1.0 - mean_frac);
        // Early in stream, prefer filling existing bins; later, allow more bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
        // Penalize new bin if item is small (wastes capacity)
        score += 0.6 * item_class as f64;
    } else {
        // Prefer tighter fits among open bins
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fit_ratio;
    }

    // Penalize creating a residual that no plausible item (>=10) can ever use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mild pressure against accumulating many open bins with loose residuals
    if open_bins_count > 4 {
        score += 0.3 * ((open_bins_count - 4) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }
    // Zero waste is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty scaled by how many other bins could fit the item.
    if fitting_bins_count == 1 {
        // Last chance: strongly prefer using this bin over opening a new one.
        score -= 40.0;
    } else if fitting_bins_count > 2 {
        // Plenty of alternatives: be picky about tight fits.
        score += 5.0;
    }

    // Lookahead: if the next item would fit the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item barely misses the post residual, penalize creating a near-dead gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 15.0;
    }

    // Open bins pressure: discourage spreading across too many bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins tighter than average (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Early in the stream, allow new bins more freely; later, conserve.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    // New empty bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // prefer bins where next item leaves little dead space
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to leftover waste
            score += 50.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize so it is chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 120.0;
        // but if lookahead shows current item + next item pack perfectly in a fresh bin, allow it
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 400.0;
        }
    }

    // Late in the stream: consolidate harder, avoid spreading across bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0 * (open_bins_count as f64).max(1.0).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize dead space relative to current item size: small post-residual
    // relative to item is fine; large post-residual is wasted space.
    if post_residual > 0 {
        let dead = post_residual as f64 / item_size.max(1) as f64;
        score += dead * dead * 2.0;
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward;
    // if not, penalize leaving a gap the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 6.0;
            // Extra penalty if the wasted gap is close to but smaller than next item.
            let gap_loss = (next_item_size - post_residual) as f64;
            score += 0.1 * gap_loss;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits poorly everywhere. Make empty-bin score moderately high so
    // only genuinely bad fits in existing bins trigger a new bin.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If many bins are open, prefer consolidating instead of adding more.
        score += 0.5 * open_bins_count as f64;
    }

    // Global state: if mean residual is high, prefer bins below mean (tighter)
    // to balance residuals; if low, mild preference for tighter bins anyway.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Late in the stream, be more conservative: keep bins tight, avoid sprawl.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (open_bins_count as f64 / (fitting_bins_count.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling: as stream progresses, tighten preference for tight fits.
    score += 12.0 * progress * norm_pr * (1.0 - norm_pr);

    // Penalize large dead space more strongly late in the stream.
    score += 20.0 * progress * norm_pr;

    // Reward filling a bin nearly completely (post_residual near 0) with smooth bonus.
    score -= 15.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bin bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Lookahead: penalize if next item cannot use this bin's post-residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if pr >= next {
            score -= 6.0 * (pr - next) / cap;
        } else {
            score += 5.0 * (next - pr) / cap;
        }
    }

    // Slight penalty for spreading across many open bins vs mean residual.
    score += 0.05 * (open_bins_count as f64) * ((pr - mean_residual).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but keep post_residual usable.
    if post_residual == 0 {
        score -= 500.0; // perfect fill
    } else {
        // Dead-space penalty grows superlinearly as residual becomes unusable.
        let small_threshold = 10u32;
        if post_residual < small_threshold {
            score += (small_threshold - post_residual) as f64 * 12.0;
        }
    }

    // Harmonic classes of post_residual relative to capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // Class the leftover falls into: quarters of capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual > 0 {
        if post_residual <= quarter {
            // small leftover: mildly penalize unless it exactly fits common item classes
            score += 8.0;
            if post_residual % 10 == 0 { score -= 15.0; } // divisible by 10 -> likely reusable
        } else if post_residual <= half {
            score -= 5.0; // medium leftover is flexible
            if post_residual % 5 == 0 { score -= 6.0; }
        } else {
            score -= 10.0; // large leftover nearly like a fresh bin
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = next_item_size == post_residual;
        score -= if exact { 120.0 } else { 40.0 + (post_residual - next_item_size) as f64 * 0.3 };
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover too small for next item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= (open_bins_count.min(20)) as f64 * 1.5;
    }

    // Early in stream, be pickier about waste; late, just fill bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0;

    // New-bin candidate: only attractive when current fit is very poor
    // (huge leftover waste or item barely fits nowhere useful).
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin
        } else if waste > cap * 0.7 {
            score -= 30.0; // large item: fresh bin keeps big space elsewhere
        } else {
            score += 25.0 + mean_residual * 0.1; // discourage spreading
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates below mean
    // (fills the emptier bins first, keeping tight bins for small items).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward tight fits (small post_residual that is still usable or zero).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize post_residual that cannot fit the next item (lookahead dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a good fit exists.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.15 + 0.25 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins below mean residual (consolidate space into fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Mild preference for using existing bins vs. opening a new empty one.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches
    // the next item size (perfect chain), penalize mismatched dead space.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 == next_item_size as i64 {
            // Perfect match: strong reward.
            score -= 60.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 25.0;
        } else {
            // Penalize dead space that the next item cannot use.
            score += 0.35 * diff;
        }
        // If next item cannot fit in post_residual, this placement creates waste.
        if post_residual < next_item_size {
            score += 8.0;
        }
    } else {
        // Last item: just minimize residual.
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins tighter than average (good fits), discourage loose bins.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Slight preference for filling bins early in the stream; late in the
    // stream, allow opening new bins more freely by penalizing big residuals less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    // Discourage opening a new bin when a decent fit exists in an open bin.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item nearly fits (within small slack), mild reward.
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(5) && post_residual < next_item_size {
        score -= 4.0;
    }

    // Penalize bins whose residual is far below mean (fragmented bins),
    // unless it's a tight fit.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev.max(0.0);

    // Time horizon: early in stream, prefer opening new bins less (consolidate);
    // late in stream, prefer filling existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Many open bins: discourage spreading; prefer consolidating into existing bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: baseline penalty so it's only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Allow new bin early or when nothing fits well.
        if progress < 0.15 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post residual, with non-linear sharpening over stream progress
    let mut score = pr * (1.0 + progress * norm_pr);

    // Non-linear coupling: quadratic post-residual penalty scaled by item density
    score += 8.0 * norm_pr * norm_pr * (norm_item + 0.1);

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr) * (1.0 + progress);
    }

    // Reward leaving room for the next item (smooth interaction)
    let nxt = next_item_size as f64 / cap;
    let fit_next = if next_item_size > 0 { (pr >= next_item_size as f64) as f64 } else { 1.0 };
    score -= 6.0 * fit_next * nxt * (1.0 - norm_pr);

    // Penalize deviating from mean residual (encourage balanced fills)
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    // Mild penalty for opening new bins when many bins already fit
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (4.0 + 6.0 * fitting_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;
    score -= 60.0 * (1.0 - frac).powi(3);

    // Dead-space penalty: residuals too small for the smallest items are wasted.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Harmonic class: group post_residual into capacity-fraction classes.
    // Residuals in the "half-full" band (25..50) are highly reusable.
    let class = post_residual / 25; // 0,1,2,3
    match class {
        0 => score -= 8.0,                    // near-full: good
        1 => score -= 15.0,                   // 25..49: sweet spot
        2 => score -= 5.0,                    // 50..74
        _ => {}                               // 75..99: mostly empty
    }

    // Lookahead synergy: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Perfect pairing bonus
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here afterwards; mild penalty if post_residual becomes dead.
        if post_residual < 10 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, unless it's early stream
    // or many bins are open with small mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 30.0 * (1.0 - progress);
        if open_bins_count > 2 && mean_residual < 25.0 {
            score += 15.0; // fragmentation: prefer spreading into new bin less
        }
        // If item is large and would leave huge residual in any open bin, new bin ok
        if item_size > 60 {
            score -= 20.0;
        }
    }

    // Modulo-based tie-breaking on post_residual classes (harmonic residue).
    score += ((post_residual % 7) as f64) * 0.3;
    score -= ((post_residual % 10 == 0) as i32 as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // A post_residual below the minimum item size (1..100 unknown, assume ~10)
    // is pure dead space; penalize proportionally to how close it is to zero.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    // Penalize near-full-but-wasted gaps in the 10..25 range (hard to reuse).
    if post_residual >= 1 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 2.0;
    }

    // Reward exact/tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Open-bins pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins whose residual is already small (consolidate fullness).
    score += (bin_residual as f64 / bin_capacity as f64) * 8.0;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        if next_item_size == post_residual {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for blocking.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bin attractive only when no
    // open bin offers a decent fit (post_residual would be tiny/dead).
    if bin_residual == bin_capacity {
        // Baseline neutral score; good placements in existing bins should beat it.
        score = bin_capacity as f64 * 0.5 + open_bins_count as f64 * 0.3;
        // If the current item leaves a large usable gap anyway, opening is fine.
        if post_residual >= 25 {
            score -= 10.0;
        }
        // Early stream: allow opening bins more freely.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
        // If the only fitting bin is this new bin, make it viable.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

