    }

    // Global state coupling: reward packing into bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for many open bins being closed out early
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic penalty on post-residual (dead space), modulated by progress.
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr) * (0.5 + progress);

    // Smooth interaction: post-residual vs next item fit quality.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.8 * (gap / cap) * (1.0 - progress);
        // Reward if next item fits snugly into this bin's post-residual.
        let snug = (pr - next_item_size as f64) / cap;
        if snug >= 0.0 {
            score -= 1.5 * snug * (1.0 - snug) * 4.0 * (1.0 - progress);
        }
    }

    // Polynomial coupling with item size: large items prefer tight fits.
    score -= norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bonus: smooth function of fitting bins count.
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 2.0 * scarcity * (1.0 + progress);

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bin).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.5 * dev * dev - 0.3 * dev;

    // Mild preference for using existing bins over opening new ones,
    // decaying as stream progresses (later: consolidation matters more).
    if bin_residual == bin_capacity {
        score += 1.2 - 0.8 * progress;
    } else {
        score -= 0.4 * (1.0 - progress) / (open_bins_count as f64 + 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // granularities (10, 20, 25, 50) are more "reusable" dead space.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit is ideal
    } else if pr % 50 == 0 {
        -25.0
    } else if pr % 25 == 0 {
        -15.0
    } else if pr % 20 == 0 {
        -12.0
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        5.0 // awkward residue, penalize
    };
    score += class_bonus;

    // Exact-match lookahead: if next item fits perfectly in post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // next item fits but leaves another residue; mild reward scaled by
        // how harmonic the double-post residual is
        let pr2 = post_residual - next_item_size;
        if pr2 % 10 == 0 {
            score -= 10.0;
        }
        score -= (pr2 as f64).min(20.0) * 0.25;
    } else if next_item_size > 0 {
        // next item cannot fit here: this bin becomes dead-ish space
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current item is large relative
    // to residual space or open bins are all tight.
    if bin_residual == bin_capacity {
        let tight = (mean_residual < item_size as f64) as i32 as f64;
        score += 20.0 - 25.0 * tight;
        // opening new bins is fine early on when item is big
        let frac = item_size as f64 / bin_capacity as f64;
        score -= frac * 15.0;
    }

    // Late in the stream, compact aggressively: prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Penalize bins whose residual deviates from mean (fragmentation control)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    // Small tie-breaker favoring fuller bins among many open bins
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0;
    }
    // Penalize "awkward" gaps: small but nonzero residuals that most items can't use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 80.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: prefer it only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        // Opening a new bin is cheap early, expensive when many bins are open.
        let open_cost = 25.0 + 6.0 * pressure.sqrt();
        // If the next item could use this bin's full space after placing current item, discourage new bin.
        let next_usable = if next_item_size > 0 && next_item_size <= post_residual { 30.0 } else { 0.0 };
        score = bin_capacity as f64 - open_cost + next_usable;
        // If current item fits an open bin almost perfectly, strongly discourage new bin.
        if fit_ratio > 0.9 && bin_residual != bin_capacity {
            score += 500.0;
        }
    }

    // Lookahead: if placing item leaves exactly room for the next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 15.0;
    }

    // Slight pressure to consolidate into fewer bins as stream progresses.
    score += 0.15 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits: heavily reward small post_residual.
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Penalize leaving space that neither fits next item well nor is small.
        if post_residual as i64 - next_item_size as i64 > 0 && gap > 0.0 {
            score += 0.3 * gap;
        }
    }

    // Reward bins whose residual is already below mean residual (consolidation).
    score -= 4.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        score += 18.0 - 0.15 * item_size as f64;
        // If many open bins exist, opening another is worse.
        score += 0.5 * open_bins_count as f64;
    }

    // Early in stream, be slightly more willing to open bins (flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as fill ratio increases (non-linear).
    let fill = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fill * fill;

    // Penalize small dead space that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    } else if post_residual < 20 {
        score += 6.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if next item fits exactly-ish in post residual, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            let waste = post_residual as f64 - nx;
            score -= 12.0 * (1.0 - waste / cap);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor or many bins
    // already open with high residual fragmentation.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0; // item was small relative to bin
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut nb = 30.0;
        if poor_fit { nb -= 20.0; }
        if open_bins_count > 8 { nb -= 6.0; }
        if mean_residual < 25.0 { nb += 8.0; }
        nb *= 0.5 + progress;
        score += nb;
    }

    // Slight preference for fuller bins among many open bins.
    score += 0.15 * open_bins_count as f64 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let base = pr as f64;

    // Smooth non-linear coupling of post-residual with stream progress:
    // early on, prefer tight fills (low post_residual); later, tolerate slack.
    let progress_bias = 8.0 * progress * (1.0 - progress) * (1.0 - norm_pr);

    // Penalize dead space non-linearly (quadratic in normalized residual),
    // dampened as the stream progresses (slack matters less near the end).
    let dead_space = 6.0 * norm_pr * norm_pr * (1.0 - 0.5 * progress);

    // Lookahead: reward if next item fits in post_residual (smooth ramp),
    // penalize if next item is large relative to post residual.
    let look = if next_item_size > 0 {
        let fit = (next_item_size as f64) / cap;
        let fits = if (next_item_size as u32) <= post_residual { 1.0 } else { 0.0 };
        -5.0 * fits * fit + 2.0 * fit * (1.0 - fits)
    } else {
        0.0
    };

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    let last_chance = if fitting_bins_count == 1 { -12.0 } else { 0.0 };

    // Slight preference to consolidate into bins tighter than the mean.
    let mean_pull = 1.5 * ((pr - mean_residual) / cap);

    // Mild penalty for proliferating bins.
    let bin_count_penalty = 0.05 * open_bins_count as f64 * norm_pr;

    base + dead_space - progress_bias + look + last_chance + mean_pull + bin_count_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual.
    score -= ((cap - pr) / cap).powi(2) * 40.0;

    // Exact or near-exact fit gets a large reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Harmonic classes: dead-space classes modulo 10.
    // Residuals in [1..9] are hard to reuse; class 0 is ideal.
    let class = post_residual % 10;
    match class {
        0 => score -= 25.0,
        1..=3 => score += 18.0 + (3 - class) as f64 * 4.0,
        4..=6 => score += 10.0,
        _ => score -= 5.0,
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 30.0 * (1.0 - slack as f64 / cap);
        } else {
            // Next item won't fit here regardless; slight penalty for
            // leaving a residual that is just barely below next item.
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += gap as f64 * 2.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when item is large relative to
    // capacity or existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        // Base penalty for opening a new bin.
        score += 45.0;
        // Large items pair well with a fresh bin.
        score -= fill_frac * fill_frac * 90.0;
        // If many bins fit the item, discourage opening another.
        if fitting_bins_count > 2 {
            score += fitting_bins_count as f64 * 6.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Mild preference for bins below mean residual (balance avoidance
    // of many half-empty bins) when open bin count is high.
    if open_bins_count > 4 {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score -= dev * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical small items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Strong penalty for very tight fits that leave near-zero residual (waste of a big residual)
    if post_residual == 0 {
        score -= 15.0; // perfect fit is great
    }

    // Dead-space penalty grows if residual becomes hard-to-fill
    let dead = (post_residual as f64 / bin_capacity as f64).powf(2.0);
    score += 20.0 * dead;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: prefer spreading when many bins open
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // New-bin candidate: make it moderately attractive only when current fits are bad
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect two-item match is highly desirable.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits exactly or near-exactly: reward heavily.
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item would not fit: penalize leftover dead space.
            score += 0.5 * (post_residual as f64).powf(1.2);
        }
    }

    // Prefer bins whose residual is below the mean (tight packing), avoid
    // wasting large residuals on small items when space is abundant.
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.3 * mean_gap;

    // Last-chance bin: strongly discourage opening a new bin when this is
    // the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure to close out bins early in the stream.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive if no open bin gives a decent fit
    // (i.e., this bin is empty and the item is large).
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to current item size.
    score += 0.35 * (post_residual as f64).sqrt();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but imperfectly: mild reward proportional to leftover after next
            let second_left = post_residual - next_item_size;
            score -= 12.0 * (1.0 - second_left as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving residual just below next_item_size
            if post_residual >= next_item_size.saturating_sub(3) {
                score += 15.0;
            }
        }
    }

    // Prefer filling bins with small residuals (consolidation).
    let res_norm = bin_residual as f64 / bin_capacity as f64;
    score += 8.0 * (1.0 - res_norm) * (1.0 - res_norm);

    // Global state coupling: many open bins with high mean residual -> favor using existing bins.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 6.0;
    }

    // Early stream: allow opening new bins more freely; late stream: consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current fits are poor or stream is early.
        score += 20.0 * (1.0 - progress);
        if post_residual < 10 {
            score -= 18.0; // big item into fresh bin is good
        }
        if fitting_bins_count > 0 && progress > 0.5 {
            score += 22.0; // late stream: avoid opening new bins
        }
    } else {
        // Existing bin: small bonus for reuse, scaled by progress.
        score -= 4.0 + 6.0 * progress;
    }

    // Discourage residuals that are likely unusable (very small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;
    let mut score = r;
    // smooth polynomial coupling: penalize large dead space more as stream progresses
    let dead = rn * rn * (1.0 - rn);
    score += 40.0 * progress * dead * cap * 0.1;
    // reward tight fits (small post_residual) with quadratic term
    score -= 12.0 * (1.0 - rn) * (1.0 - rn) * progress;
    // last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }
    // lookahead: reward if next item can use post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= r {
            let slack_fit = (r - nx) / cap;
            score -= 8.0 * (1.0 - slack_fit) * (1.0 - progress);
        } else {
            score += 6.0 * progress * (nx - r) / cap;
        }
    }
    // penalize bins far from mean residual (prefer balanced residuals)
    let dev = (r - mean_residual) / cap;
    score += 5.0 * dev * dev;
    // new-bin candidate: keep neutral-ish, slightly penalize early opening
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity quartiles
    let pr = post_residual;
    let quart = (pr * 4) / bin_capacity; // 0..3 harmonic class
    match quart {
        0 => score -= 12.0,          // near-perfect fit: reward heavily
        1 => score -= 3.0,           // good fit
        2 => { /* neutral */ }
        _ => score += 8.0,           // large dead space: penalize
    }

    // Exact-fill reward
    if pr == 0 { score -= 25.0; }

    // Small dead space that is unusable for typical items (< 10 min size)
    if pr > 0 && pr < 10 { score += 15.0; }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match via integer division: how many next items fit
            let k = pr / next_item_size.max(1);
            score -= 6.0 + 2.0 * k.min(3) as f64;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: penalize so it's only chosen when fits are terrible
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
        // but if current bin would leave huge dead space, opening fresh is fine
        if post_residual > bin_capacity / 2 && item_size <= bin_capacity / 4 {
            score -= 25.0;
        }
    }

    // Stream progression: later in stream, be greedier about tight fits
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * (post_residual as f64 / cap) * 5.0;

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bin)
    score += ((post_residual as f64) - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let cap_safe = cap.max(1.0);
    let item = item_size as f64;
    let residual = (bin_residual as f64).max(1.0);
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;

    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let mean_ratio = (mean_residual / cap_safe).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;
    let fresh_post = (cap - item).max(0.0);

    let next_exists = next > 0.0;
    let next_fits_fresh = next_exists && next <= fresh_post + 1e-9;
    let post_takes_next = next_exists && post + 1e-9 >= next;

    let residual_position = ((residual - mean_residual) / cap_safe).clamp(-0.30, 0.30);
    let tight_fit_bonus = (item / residual) * (cap_safe * 0.05);

    let mut score = post - tight_fit_bonus + residual_position * 4.0;

    if post_residual == 0 {
        score -= cap_safe * (0.28 + 0.008 * open.min(25.0));
    } else {
        if post_takes_next && next_fits_fresh {
            score -= 0.14 * next + 1.0;
        }

        if next_exists && !post_takes_next && next_fits_fresh {
            let gap = next - post;
            let scarcity = if fitting_bins_count <= 1 { 1.25 } else { 0.75 };
            let mean_relief = 1.0 - 0.45 * mean_ratio;
            let below_mean_relief = if residual < mean_residual {
                let deficit = (mean_residual - residual) / cap_safe;
                (1.0 / (1.0 + 2.0 * deficit)).clamp(0.30, 1.0)
            } else {
                1.0
            };

            score += gap * 1.9 * scarcity * mean_relief * below_mean_relief + 2.5;
        }

        if !next_exists && post < item {
            score += (item - post) * 0.02;
        }
    }

    if is_new_bin {
        let mut new_penalty = 8.0
            + open * 0.28
            + mean_ratio * (7.0 + open.min(50.0) * 0.08)
            + progress * 4.0
            + fitting * 0.10;

        if next_exists {
            if post_takes_next && next_fits_fresh {
                new_penalty -= 4.0;
                if fitting_bins_count <= 1 {
                    new_penalty -= 1.0;
                }
            } else if post + 1e-9 < next {
                new_penalty += (next - post) * 0.6 + 2.0;
            }
        } else {
            new_penalty += 8.0;
        }

        if fitting_bins_count == 0 {
            new_penalty *= 0.8;
        }

        score += new_penalty.max(2.0);
    } else if fitting_bins_count == 1 {
        score -= 2.5 + 0.03 * open.min(30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain fill
        } else if post_residual >= next_item_size {
            // next item fits; reward proportionally to how tight that fit is
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large dead space left behind
            let dead = post_residual as f64;
            score += 0.3 * dead;
        }
    } else {
        // Last item: minimize leftover as strongly as possible
        score += 0.5 * post_residual as f64;
    }

    // Penalize bins with residual far below mean (they are nearly full anyway;
    // prefer using them only for tight fits, which is already rewarded).
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or lookahead suggests a better dedicated bin.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.6 * bin_capacity as f64;
        let lookahead_waste = next_item_size > 0 && post_residual < next_item_size;
        if !poor_fit && !lookahead_waste {
            score += 60.0;
        } else {
            score += 10.0;
        }
        // Early in stream, opening bins is cheaper; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference to spread load when many bins are open with high mean residual.
    if open_bins_count > 4 && mean_residual > 50.0 && bin_residual as f64 >= mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize creating tiny, hard-to-use dead space (post_residual in 1..=10 is worst).
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + next_tight);
    } else if next_item_size > post_residual {
        // Dead space for the known next item.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Prefer placing into bins whose residual is below the mean (compact small bins first),
    // keeping large-residual bins available for large future items.
    if bin_residual as f64 > mean_residual {
        score += 6.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Time horizon: as the stream progresses, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 20.0 - 30.0 * progress;
        // Opening a bin is worse when many bins are already open.
        score += (open_bins_count as f64).sqrt() * 2.0;
        // But acceptable if the item is large and leaves a useful residual pattern.
        if item_size >= 50 {
            score -= 12.0;
        }
    } else {
        // Using an existing bin gets better as stream progresses.
        score -= 10.0 * progress;
    }

    // Mild penalty for leaving a residual that no typical item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, but its value depends smoothly on stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Non-linear coupling: residual squared penalizes large dead space,
    // weighted by progress (late in stream, dead space hurts more).
    score += 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: smooth bell around small post-residual.
    let tight = (-norm_pr * 6.0).exp();
    score -= 15.0 * tight * (1.0 - progress * 0.3);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits into post-residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (-slack * 8.0).exp() * (1.0 - progress * 0.5);
        } else {
            let gap = (nxt - pr) / cap;
            score += 8.0 * (-gap * 5.0).exp();
        }
    }

    // New-bin candidate: penalize mildly so it only wins when open bins fit badly,
    // but relax the penalty late in the stream (consolidation phase).
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress * 0.4) + 0.1 * open_bins_count as f64;
    }

    // Mean residual context: prefer bins whose residual deviates below mean
    // (fills the emptier bins first, keeping tight bins for small items).
    score += 3.0 * (norm_pr - mean_residual / cap).max(0.0) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac <= 0.10 {
        score -= 60.0; // tiny dead space is fine
    } else if frac <= 0.25 {
        score -= 20.0;
    } else if frac <= 0.50 {
        score += 15.0;
    } else {
        score += 40.0; // more than half wasted
    }

    // Harmonic class of next item: does it fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item nests perfectly: strong reward, more if exact
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 120.0;
            } else {
                score -= 25.0;
            }
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins exist and item fits reasonably.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if open_bins_count > 0 {
            // new bin cost grows with how well the item would fit elsewhere
            score += 150.0 + 50.0 * (1.0 - tightness);
        } else {
            score -= 200.0; // must open first bin
        }
        // late in stream, avoid spawning bins with big residual
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress * frac;
    }

    // Mild preference for tighter bins overall (best-fit flavor via mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Modulo arithmetic harmonic classes on post_residual (mod 10 bands).
    let m = post_residual % 10;
    score -= match m {
        0 => 12.0,
        1..=3 => 4.0,
        4..=6 => 0.0,
        _ => -3.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post_residual gaps that no future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Mid-size unusable gaps: penalize residuals that are too small for
    // the smallest plausible item (1..100 range, but small items are rare-ish).
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (waste minimization).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Last chance: strongly favor using this bin if it's the only one that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: penalize placements that keep many bins open when
    // residual is already fragmented; encourage consolidating into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.5 * (1.0 - fit_ratio);

    // Lookahead: if the next item fits into the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item is large and would not fit post_residual, slight penalty
    // unless post_residual is near zero (bin essentially full = good).
    if next_item_size > post_residual && post_residual > 15 {
        score += 3.0;
    }

    // Mean-residual coupling: prefer bins with residual below mean (fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate handling: the empty bin has bin_residual == bin_capacity.
    // Prefer opening a new bin only when no open bin offers a decent fit,
    // i.e., when the best-case fit would leave large dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress
        // (early in the stream, opening bins is cheaper / more useful).
        score = 45.0 + 25.0 * progress;
        // If this is the last-chance situation, opening new bin is bad.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus (next item exactly fills the bin)
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item fits with room left: mild reward proportional to closeness
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize dead space left behind
            score += 0.5 * gap;
        }
    } else {
        // Last item: prefer minimal post_residual
        score += 0.2 * post_residual as f64;
    }

    // Compare against mean residual across open bins: prefer tighter-than-average bins
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good fitting options exist
    if bin_residual == bin_capacity {
        score += 25.0;
        // But new bin is attractive if item is large and no tight fit exists
        if item_size >= bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Reward high fill ratio
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small dead space more than proportionally (hard-to-fill slivers).
    if post_residual > 0 {
        let pr = post_residual as f64;
        let tight = (bin_capacity as f64 * 0.10).min(pr);
        score += 6.0 * (bin_capacity as f64 - pr) / bin_capacity as f64 * (tight / pr).max(0.0);
        score += 2.0 * (1.0 - pr / bin_capacity as f64);
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Lookahead: reward if the next item can fit into post_residual.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post_residual as f64 >= ns {
            score -= 8.0 * (ns / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer fuller bins relative to global mean residual.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mild preference for keeping open-bin count low late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: only attractive when current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Core: quadratic waste penalty (dead space grows quadratically worse)
    let mut score = post * post / cap;

    // Smooth tight-fit reward: cubic term favoring near-zero post_residual
    score -= (1.0 - post / cap).powi(3) * cap * 0.5;

    // Stream-progress coupling: later in stream, be more forgiving of residual
    // (bins opened early should be packed tighter; late, accept fits to close bins)
    score *= 1.0 - 0.35 * progress * (post / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= cap * 0.75;
    }

    // Lookahead: penalize if post_residual can't hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += (nxt - post) * 0.6;
        } else {
            // reward leaving room exactly for next item
            score -= (1.0 - (post - nxt) / cap) * 4.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely needed
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += cap * (0.9 + 0.5 * progress) * urgency;
        // new bin is attractive when item is large and mean residual is low
        score -= (item / cap) * mean_residual * 0.3;
    }

    // Mild penalty proportional to open bins count (encourage filling existing bins)
    score += open_bins_count as f64 * 0.05;

    // Mean-residual coupling: when open bins are mostly empty, prefer them
    score += (mean_residual - post).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "dead zone" classes.
    let residue = post_residual % 10;
    // Penalize awkward leftover classes (1..9) that few future items can fill exactly.
    if residue >= 1 && residue <= 9 {
        score += (10 - residue) as f64 * 0.6;
    } else if residue == 0 && post_residual > 0 {
        // Perfect decade fit: strongly reward.
        score -= 12.0;
    }

    // Integer-division thresholds on post_residual: tiny slivers are wasted space.
    let sliver = post_residual / 10; // decade bucket of leftover
    if sliver == 0 && post_residual > 0 {
        score += 25.0; // leftover < 10: almost certainly dead space
    } else if sliver == 1 {
        score += 8.0; // 10..19: only small items fit
    }

    // Reward tight fits: post_residual small relative to item size.
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= tightness * 6.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0; // perfect chaining
        } else if gap <= 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Leftover cannot host the next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Last-chance bin before opening a new one: favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // open bins are fragmented or the item is huge relative to typical residuals.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / (bin_capacity as f64);
        // Prefer new bin when existing mean residual is small (bins nearly full)
        // or when item is large and would leave a bad class.
        let new_bin_penalty = 6.0 + fragmentation * 30.0;
        score += new_bin_penalty;
        // If item leaves a perfect decade in a fresh bin, ease the penalty.
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 5.0;
        }
    }

    // Progress modulation: early in stream, be conservative about fragmentation;
    // late in stream, squeeze into existing bins harder.
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    score -= progress * 4.0;
    score += (1.0 - progress) * 3.0;

    // Mild pressure when many bins are open: consolidate.
    score += (open_bins_count as f64).sqrt() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // plausible future item (min size 1..100, but typical small item ~10)
    // are wasted capacity. Penalize small unusable gaps nonlinearly.
    if post_residual > 0 {
        if post_residual < 10 {
            // gap below the smallest possible item => pure dead space
            score += 40.0 + 3.0 * (10 - post_residual) as f64;
        } else if post_residual < 20 {
            // very likely dead space for most distributions
            score += 18.0 + 0.8 * (20 - post_residual) as f64;
        } else if post_residual < 30 {
            score += 6.0;
        }
    } else {
        // perfect fit: reward strongly
        score -= 30.0;
    }

    // Reward leaving a gap that exactly (or nearly) accommodates the lookahead item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 12.0 - slack as f64;
            }
        } else {
            // lookahead cannot fit here; mild penalty proportional to shortfall
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage using this bin when it is the last fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }
    score += 0.35 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64).max(0.1);

    // Prefer bins whose residual is below average (tighter bins first),
    // keeping looser bins available for larger future items.
    let diff = mean_residual - bin_residual as f64;
    score += 0.5 * diff;

    // Slight preference for filling fuller bins (small bin_residual)
    score += 0.2 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer residual that exactly matches the next item (perfect 2-step chain)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Penalize dead space the next item cannot use (waste creation)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.3 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits relative to mean residual
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * (1.0 - tightness) * (mean_residual / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin enables a good next placement
        }
    }

    // Late in stream: consolidate, avoid sprawl
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64 / (total_items.max(1) as f64).sqrt());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && next_item_size > bin_capacity {
        // unreachable guard, no-op
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize tight leftovers more.
        score += 0.15 * (post_residual as f64);
    }

    // Last-chance bin: strongly prefer filling the only bin that fits,
    // avoids opening a new bin for one item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Fragmentation pressure: prefer bins whose residual is already below average
    // (consolidate waste into few bins).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.10 * dev;

    // Time horizon: early in the stream, be pickier about tight fits;
    // late in the stream, just fill anything to close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 10.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // Many open bins: encourage using existing bins rather than opening more.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are open
        // and how well the item would fill a fresh bin.
        score += 5.0 + 2.0 * (open_bins_count as f64);
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 40.0 * (1.0 - fill_ratio);
        // But if the item is huge and nothing fits well elsewhere, allow it.
        if fill_ratio > 0.8 {
            score -= 30.0;
        }
    }

    // Prefer bins that will end up with residual below the next item size
    // (waste becomes unusable anyway).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (1.0 - progress) * (1.0 - progress);
    score += 20.0 * coupling;
    // Reward tight fits more strongly as stream progresses
    let tightness = (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= (5.0 + 25.0 * progress) * tightness;
    // Last-chance bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }
    // Penalize opening new bins when many open bins exist
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    // Dead-space penalty relative to mean residual
    score += 0.3 * (pr - mean_residual) * (1.0 - pr_norm);
    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (pr >= nx) as i32 as f64;
        score -= 8.0 * fit_next * (1.0 - pr_norm) * (0.5 + 0.5 * progress);
        // Penalize wasting residual just below next item size
        let gap = nx - pr;
        if gap > 0.0 && gap <= 10.0 {
            score += 6.0 * (1.0 - gap / 10.0);
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small residuals are hard to fill later.
    if post_residual > 0 {
        let p = post_residual as f64 / bin_capacity as f64;
        if p < 0.1 {
            score += (0.1 - p) * 120.0;
        } else if p < 0.2 {
            score += (0.2 - p) * 40.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classes: reward bins whose post-residual lies in a "friendly"
    // class (multiples of 10 or 20 are more likely to fit future items).
    let class = post_residual % 10;
    if class == 0 {
        score -= 12.0;
    } else if class == 5 {
        score -= 4.0;
    } else {
        score += (class as f64) * 1.5;
    }

    // Lookahead: strongly reward leaving exactly room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += (slack / bin_capacity as f64) * 25.0;
        } else {
            // next item cannot follow into this bin; mild penalty scaled by how close we were
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Bonus if next item also lands on a harmonic boundary after placement
        if post_residual >= next_item_size && (post_residual - next_item_size) % 20 == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer tightest existing bin when many bins fit (best-fit reinforcement).
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 1.0;
    }

    // Early stream: encourage compacting into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // New-bin candidate bias: opening a fresh bin is penalized unless the
    // current item is large relative to what open bins can absorb.
    if bin_residual == bin_capacity {
        let big = item_size as f64 / bin_capacity as f64;
        score += 30.0 - big * 55.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 10.0; // fresh bin can host next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (below min item size 1..threshold) are worthless.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        // unusable sliver -> heavy penalty for keeping this bin chosen with such a gap
        score += (dead_threshold - post_residual as f64) * 8.0;
    } else {
        // prefer tight fits: reward small (but usable) post residuals
        score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 6.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Next-item lookahead: if the next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item cannot fit in post residual but could fit elsewhere, mild penalty
    if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        // candidate new bin: base cost plus pressure from open bin count
        score += 20.0 + (open_bins_count as f64) * 3.0;
        // but if mean residual is large (fragmented bins), new bin is more attractive
        score -= mean_residual * 0.15;
        // if next item is large and mean residual is small, opening fresh bin is good
        if next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
    } else {
        // mild pressure to consolidate into fewer bins as stream progresses
        score += (open_bins_count as f64) * 0.05;
    }

    // Slight preference early in stream for filling existing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * lookahead_gap;
        // Perfect chain bonus: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item fits with small slack: still good
        if next_item_size <= post_residual && post_residual - next_item_size <= 10 {
            score -= 8.0;
        }
        // Next item cannot fit here: mild penalty so chain-friendly bins win
        if next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Penalize unusable dead space relative to smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 20.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0; // open bins still have room; don't open new one
        }
        if open_bins_count > 0 && progress > 0.9 {
            score -= 5.0; // end of stream: consolidation less valuable
        }
    }

    // Prefer bins tighter than average (best-fit flavor relative to mean residual)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Reward large fill ratio
    score -= 0.2 * (item_size as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty scaled by capacity.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a residual that is just barely too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Global pressure: when many bins are open relative to stream length, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / total_items.max(1) as f64;
    score -= 20.0 * pressure * (0.5 + progress);

    // Prefer bins whose residual is below the mean residual (consolidate fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; it must lose only when fits are bad.
        score += 25.0 + 15.0 * (1.0 - progress);
        // But if current item leaves large dead space in any existing bin, new bin becomes viable:
        // (this is handled implicitly since existing-bin scores rise with tightness penalty).
        if fitting_bins_count == 0 {
            score -= 60.0; // no existing bin fits anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 30.0 * poly;
    // Penalize large post-residual later in the stream (dead space matters more)
    score += 40.0 * norm_pr * norm_pr * progress;
    // Reward tight fits early
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }
    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 - pr).max(0.0) / cap;
    }
    // Mild penalty when many bins open and this placement wastes space
    score += 0.5 * open_bins_count as f64 * norm_pr;
    // Align with mean residual: prefer bins above mean residual (bigger holes)
    score -= 5.0 * (mean_residual - pr) / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which residue class mod 10 it lands in.
    let harmonic_class = post_residual % 10;
    // Residues that are "dead zones" (too small to fit the minimum item of 1..100 unknown range,
    // treat small residues as increasingly wasted).
    let dead_penalty: f64 = if post_residual == 0 {
        -30.0 // perfect fit, best possible outcome
    } else if post_residual <= 5 {
        25.0 // nearly dead space
    } else {
        match harmonic_class {
            0 => -8.0,  // round residual: pairs well with round sizes
            5 => -4.0,  // half-class also composable
            _ => 0.0,
        }
    };
    score += dead_penalty;

    // Integer-division threshold: residual divided into "slots" of the next item's size class.
    if next_item_size > 0 {
        let slots = post_residual / next_item_size.max(1);
        if slots >= 1 {
            score -= 6.0 * slots as f64; // residual reusable by lookahead item
        } else {
            score += 8.0; // lookahead cannot use this bin's leftover
        }
        // Harmonic compatibility: next item fits exactly into post_residual class
        if post_residual % next_item_size.max(1) == 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Last item: strongly prefer zero residual
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: if only one bin fits, penalize opening a new bin instead.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: keep it neutral-slightly-poor unless current bin is badly fragmented.
    if bin_residual == bin_capacity {
        score += 4.0 + mean_residual * 0.05;
    }

    // Capacity fraction coupling: reward filling a large fraction of the bin.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // Late-stream consolidation: prefer tighter bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit is the best outcome.
        score -= 25.0;
    } else {
        // Larger residual space left is mildly good (keeps flexibility).
        score -= 0.15 * post_residual as f64;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    if bin_residual < bin_capacity {
        score -= 2.0 * pressure.min(5.0);
    } else {
        // New-bin candidate: penalize opening bins when pressure is high,
        // but allow it when current bin would leave a bad gap and next item fits.
        score += 3.0 * pressure.min(5.0);
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 8.0; // fresh bin accommodates the lookahead item well
        }
        if post_residual > 0 && post_residual < 10 {
            score += 30.0; // don't open a bin that will immediately get dead space
        }
    }

    // Lookahead: if next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    } else if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item can't use this bin's remainder anyway
    }

    // Mean residual coupling: prefer bins close to the mean (balanced packing),
    // unless it's a new bin.
    if bin_residual < bin_capacity {
        score += 0.1 * ((bin_residual as f64 - mean_residual).abs());
    }

    // Late in stream: tighten up, avoid leaving any residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 1.0;

    // Perfect fit bonus: nearly zero waste is excellent
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 50.0;
    }

    // Dead-space penalty: residual too small for any item (min size 1, but
    // practically small leftovers are wasted). Penalize residuals below 10 hard.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 5.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // perfect chain
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // good chain: next item leaves small gap
            score -= 100.0 - gap as f64 * 2.0;
            if gap < 10 {
                score -= 50.0;
            }
        } else {
            // next item does NOT fit after this placement: penalize proportionally
            let overflow = next_item_size - post_residual;
            score += overflow as f64 * 1.5;
        }
    }

    // Compare against mean residual: bins with residual below mean are scarcer;
    // filling them is good (keeps many bins usable). Filling a high-residual bin
    // toward the mean is also good.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 20.0; // fill the tighter bin first
    } else {
        score += (resid_f - mean_residual) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin — unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: make empty bin attractive only when the item
    // is large relative to capacity or fits poorly everywhere.
    if bin_residual == bin_capacity {
        // neutral baseline; opening a new bin for a big item is fine
        if item_size >= bin_capacity / 2 {
            score -= 30.0;
        } else {
            score += 40.0; // discourage new bins for small items
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is already favored by the base term.
    // Penalize creating tiny, hard-to-use dead space (1..10) more than base implies.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - 0.15 * slack;
        if slack == 0.0 {
            score -= 10.0; // perfect chain fit
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: dead space penalty scaled by tightness.
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is costly unless the item fits poorly
    // everywhere or the stream is early and we want many bins for future flexibility.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (item_size as f64 / bin_capacity as f64) > 0.6;
        // Base cost of a new bin.
        score += 20.0;
        // Early stream: allow more bins (exploration discount).
        score -= 18.0 * (1.0 - progress) * (1.0 - progress);
        // Large item with few alternatives: new bin is fine.
        if poor_fit && fitting_bins_count <= 2 {
            score -= 14.0;
        }
        // Many open bins with slack: discourage opening yet another.
        if mean_residual > 30.0 && open_bins_count > 3 {
            score += 10.0;
        }
    } else {
        // Prefer fuller bins among open bins: reward high fill ratio.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 8.0 * fill;
        // Penalize bins whose residual deviates far below the mean (wasting slack elsewhere).
        let dev = (mean_residual - bin_residual as f64).abs();
        score += 0.05 * dev;
    }

    // Late-stream consolidation: as the stream ends, avoid opening bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling: post_residual weighted by stream progress
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress;
    score += 40.0 * coupling;

    // Tight fit reward, stronger early in the stream
    score -= (1.0 - progress) * 20.0 * (1.0 - norm_pr) * (item_size as f64 / cap);

    // Penalize dead space relative to mean residual
    if pr as f64 > mean_residual {
        score += 5.0 * (pr - mean_residual) / cap;
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: favor bins whose post residual fits the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // New-bin candidate: prefer opening a new bin when residuals are fragmented
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        score -= 15.0 * frag * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by 10 are
    // "harmonic" because typical item sizes are multiples of 10; such dead
    // space is far more likely to be filled by a future item.
    let harmonic = (post_residual % 10 == 0) as f64;
    score -= harmonic * 6.0;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize tiny non-harmonic dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Coupling with lookahead: if the next item fits exactly into the
    // post-residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            // next item would create a sliver here: mild penalty
            score += 4.0;
        }
        // Harmonic class match between post-residual and next item size class
        if next_item_size / 10 == post_residual / 10 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: an empty bin has full residual. Prefer keeping it
    // pristine unless current fits are poor (large post_residual). Penalize
    // opening a new bin for small items; encourage it when the item is large
    // and no open bin offers a good (harmonic) fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64 * 0.05) + progress * 2.0;
        // base reluctance to open a new bin
        score += 15.0 + pressure;
        // but if this item is large, opening a fresh bin is often better
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        // if mean residual of open bins is small (they are nearly full),
        // a new bin is genuinely needed
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
        // if no open bin gives a harmonic fit, allow the new bin
        if post_residual > 0 && post_residual < 10 {
            score -= 10.0;
        }
    }

    // Mild tie-break: prefer bins with larger residual consumed relative to
    // mean residual across open bins (balance preservation).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strict dead-space avoidance with open-bin pressure.
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (< 10) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps too small for the smallest plausible item (1..10 range) softly.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 2.5;
    }

    // Reward tight fits (small post_residual) with a superlinear bonus.
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 8.0;

    // Open-bin pressure: prefer reusing existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 4.0 + open_bins_count as f64 * 0.35 + progress * 3.0;
    } else {
        // New bin: only attractive if it enables a good future fit or nothing fits well.
        if next_item_size > 0 && next_item_size > post_residual.min(bin_residual) {
            score -= 6.0;
        }
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
        score += 2.0 + open_bins_count as f64 * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in the resulting residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slightly penalize creating a stranded residual.
        score += (post_residual as f64) * 0.15;
    }

    // Mean residual coupling: penalize placing into bins far below mean residual
    // when mean residual is small (fragmentation signal).
    if mean_residual < 12.0 && bin_residual != bin_capacity {
        score += (12.0 - mean_residual) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (smaller post_residual) wins.
    // Normalize dead space relative to capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += dead_frac * 40.0;

    // --- 2-step lookahead: does the next item fit into the leftover? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: this bin can host the next item too.
            let chain_slack = (post_residual - next_item_size) as f64;
            // Reward chains, more so when the chain is also tight.
            score -= 30.0 + 25.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leftover that is likely dead space,
            // scaled by how far off the fit is.
            let miss = (next_item_size - post_residual) as f64;
            score += 10.0 + miss * 0.5;
        }
        // If the next item exactly fills the bin after this placement, huge reward.
        if post_residual == next_item_size {
            score -= 45.0;
        }
    } else {
        // Last item: minimize leftover as much as possible.
        score += dead_frac * 60.0;
    }

    // --- Mean-residual context coupling ---
    // Bins far below mean residual are "fresher"; prefer filling bins with
    // residual above the mean (older/more congested bins) to balance load.
    if bin_residual as f64 > mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // --- Last-chance bonus: only this bin can fit the item ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Must use it; strongly prefer regardless of fit quality,
        // but still slightly prefer tighter fits.
        score -= 100.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when:
        //  - item is large relative to capacity, and
        //  - current fit would leave big dead space, or
        //  - few bins fit (fragmentation risk).
        let big_item = item_size as f64 / bin_capacity as f64;
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        let new_bin_score = 60.0
            - 50.0 * big_item
            + 80.0 * poor_fit
            - if fitting_bins_count <= 2 { 25.0 } else { 0.0 };
        // Replace score with calibrated new-bin score.
        score = new_bin_score;
        // Lookahead: a fresh bin can always take the next item.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    // Mild stream-position adaptation: early on, be conservative (prefer
    // spreading), later in the stream, pack aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward;
    // if it would leave a near-unusable remainder, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 12.0 * chain_tight;
        } else if next_item_size <= bin_residual {
            // Next item fits this bin but not after placing current item: mild penalty.
            score += 6.0;
        }
    }

    // New-bin candidate handling: empty bin is attractive only when current
    // fits are poor or the item is large relative to mean residual space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = (post_residual as f64 / bin_capacity as f64).powi(3);
        let pressure = (open_bins_count as f64 * mean_residual) / (item_size as f64 * 10.0);
        score = 60.0 + fit_quality * 20.0 - pressure * 5.0 - progress * 10.0;
        // If a lone fitting bin exists, discourage opening a new one.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    // Mild preference for fuller bins among equals (fragmentation control).
    score -= (bin_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling: residual tightness polynomial
    let tightness = 1.0 - pr / cap;
    score -= 30.0 * tightness * tightness * tightness;

    // Smooth interaction: small post-residuals penalized more as stream progresses
    let small_res = (cap - pr) / cap;
    score += (10.0 + 40.0 * progress) * small_res * small_res * small_res * small_res;

    // Dead-space penalty: post_residual too small for any future item (1..100)
    let dead = ((50.0 - pr) / 50.0).max(0.0);
    score += 25.0 * dead * dead * (0.5 + progress);

    // Lookahead coupling: smooth reward if next item fits post-residual
    if next_item_size > 0 {
        let fits = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 20.0 * (1.0 - (1.0 - fits) * (1.0 - fits));
        // penalize near-miss: next item slightly larger than residual
        let miss = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 15.0 * miss * miss;
    }

    // Last-chance bonus (smooth): only fitting bin gets strong discount
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 35.0 * (1.0 - progress * 0.5);
    }

    // Crowding penalty: many open bins with high mean residual -> prefer consolidation
    let crowd = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (mean_residual / cap);
    score += 20.0 * crowd * crowd;

    // New-bin candidate: penalize mildly, discount late in stream
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - 0.6 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // residual as fraction of capacity

    // Penalize residuals that are "dead" — too small for typical items (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Harmonic bonus: post_residual exactly divisible by common item classes.
    for m in [10u32, 20, 25, 50] {
        if post_residual > 0 && post_residual % m == 0 {
            score -= 4.0 + (m as f64) * 0.05;
        }
    }

    // Non-linear waste curve: quadratic penalty on residual fraction.
    score += 12.0 * frac * frac * cap * 0.01;

    // Reward tight fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else {
            score += 6.0; // next item won't fit here; this bin likely closes
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when current bins fit badly.
    if bin_residual == bin_capacity {
        // Neutral baseline with mild penalty so good fits in open bins win.
        score = 45.0 + 0.1 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 10.0; // next item pairs well with fresh bin
        }
        if fitting_bins_count == 1 {
            score += 60.0; // never open new bin when a last-chance bin exists
        }
    }

    // Stream progression: tighten packing as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    // Mean residual coupling: prefer bins deviating below mean residual (consolidate).
    score -= 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are worthless; heavily penalize tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.5;

    // Last-chance bin pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // fit into existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.8
            + open_bins_count as f64 * 2.0
            - progress * 10.0;
        if next_item_size > 0 && next_item_size > post_residual.max(0) {
            // next item might pair better in a fresh bin; slight discount
            score -= 8.0;
        }
    }

    // Open-bin pressure: mild penalty scaled by number of open bins to
    // encourage consolidation.
    score += open_bins_count as f64 * 0.3;

    // Coupling with mean residual: bins below mean residual are already tight;
    // favor filling them further.
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect chain (post_residual == next_item_size) is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // small slack after also fitting next item is good
            score -= (10.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
            // penalize leaving a hole slightly bigger than next item (unusable wedge)
            if slack < 10.0 {
                score += 8.0 * (10.0 - slack);
            }
        } else {
            // next item cannot follow here; dead space penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * gap.min(30.0);
        }
    } else {
        // last item: prefer tightest fill
        score -= 15.0;
    }

    // Tight fits are inherently good: reward small post_residual non-linearly.
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(2));

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: placing into a below-average-residual bin
    // (i.e., a well-filled bin) preserves spread capacity elsewhere.
    let cap = bin_capacity as f64;
    if mean_residual > post_residual as f64 {
        score -= 3.0 * ((mean_residual - post_residual as f64) / cap).min(1.0);
    } else {
        score += 3.0 * ((post_residual as f64 - mean_residual) / cap).min(1.0);
    }

    // Discourage opening new bins when many bins are already open and item fits well.
    if bin_residual != bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - progress) * (post_residual as f64 / cap);
    } else {
        // New-bin candidate: penalize unless item is large relative to capacity
        // (big items are better placed fresh) and few bins are open.
        score += 20.0;
        if item_size as f64 > 0.6 * cap && open_bins_count > 2 {
            score -= 22.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: prefer bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
        // If next item fits exactly with current item, big reward (perfect pairing).
        if item_size + next_item_size == bin_residual {
            score -= 25.0;
        }
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor
    // and mean residual across open bins is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = (mean_residual / bin_capacity as f64).recip();
        // Base cost of opening a bin; reduced late in the stream or when open bins are full-ish.
        score += 45.0 - 15.0 * desperation - 10.0 * progress;
        // If no open bin can fit at all, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins with above-average residual when many bins are open
    // (keeps a spread of usable space).
    if bin_residual as f64 > mean_residual && open_bins_count > 2 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;
    let mean_r = mean_residual / cap;
    let last_chance = (fitting_bins_count == 1) as i32 as f64;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let t = progress;
    score += 12.0 * pr_norm * pr_norm * (t - 0.5) * 2.0;
    score -= 8.0 * pr_norm * (1.0 - pr_norm) * (1.0 - t);

    // Reward tight fits with a smooth polynomial in fit_ratio
    score -= 10.0 * fit_ratio * fit_ratio * (1.0 - pr_norm);

    // Lookahead: reward bins whose post-residual accommodates the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 6.0 * gap.exp().tanh() * next_ratio;
    }

    // Penalize creating dead space relative to mean residual
    score += 5.0 * (pr_norm - mean_r).abs() * (1.0 - fit_ratio);

    // Last-chance bonus decaying smoothly over the stream
    score -= last_chance * (6.0 + 4.0 * t);

    // Mild crowding penalty, smooth in open_bins_count
    score += (open_bins_count as f64).ln() * pr_norm * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quartiles:
    // residuals that form "usable" classes (>= half of typical small item) are good.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divisible into clean halves/quarters -> usable pockets
    let quarter = bin_capacity / 4;
    if quarter > 0 && (post_residual % quarter == 0) && post_residual > 0 {
        score -= 6.0;
    }
    // Class B: dead space (tiny residual that few items can use)
    if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Integer-division threshold: residual class by (post_residual / 20)
    let class = post_residual / 20;
    score -= class as f64 * 2.0;

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // harmonic bonus: next item fills residual to another clean class
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 15.0;
            } else if next_post < 10 {
                score += 5.0;
            }
        } else {
            // next item won't fit here regardless; penalize wasted lookahead alignment
            score += 3.0;
        }
    } else {
        // last item: prefer tightest fill
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when no open bin is decent
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32;
        if pressure == 1 {
            score -= 40.0;
        } else {
            score += 30.0 + mean_residual * 0.2;
        }
    }

    // Stream progression: later in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - pr).abs() * 0.5;
    score -= progress * 4.0;

    // Prefer bins tighter than the mean residual (good fill)
    if pr < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals that can't fit even the smallest plausible item.
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits (small post_residual relative to item).
    score -= 30.0 * (1.0 - post_residual as f64 / bin_residual.max(1) as f64);

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing residuals are large/wasteful.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
        if post_residual < 20 {
            score -= 20.0; // fresh bin still leaves usable space
        }
    }

    // Lookahead: favor bins whose post_residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Late in stream: consolidate, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item well.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Perfect chain fit: next item exactly fills the leftover space.
        let chain_slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - chain_slack / bin_capacity as f64);
        // Bonus if the pair nearly exhausts the bin.
        if post_residual - next_item_size <= 5 {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize dead space proportionally.
        let dead = (post_residual.min(next_item_size - 1)) as f64;
        score += 0.35 * dead;
    }

    // Tight fit reward for current placement.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Compare against mean residual: prefer filling below-average-residual bins (tighter bins).
    let cap = bin_capacity as f64;
    let residual_bias = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * residual_bias;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Late in the stream: consolidate into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses; slight early-stream allowance.
        score += 8.0 + 30.0 * progress;
        // If no existing bin fits well and item is large, opening a new bin is acceptable.
        if fitting_bins_count == 0 && item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild preference to spread across fewer bins when many are open.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base signal.

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover space; penalize large dead space
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a brand-new bin when decent fits exist:
    // an empty bin has huge residual; scale penalty by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
    }

    // Prefer bins whose residual deviates below the mean (consolidate large holes).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference for fewer open bins when this bin is already mostly full.
    if post_residual <= 10 {
        score -= 4.0;
    }

    // Encourage using existing bins early in the stream, allow spreading later.
    score += (1.0 - progress) * 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual cost, non-linearly warped by stream progress.
    // Early on, waste is cheap (bins get consolidated later); late, waste is costly.
    let waste_weight = 0.5 + 1.5 * progress * progress;
    let mut score = pr * waste_weight;

    // Smooth polynomial coupling: penalize mid-range residuals more than tight fits,
    // with the penalty peak shifting as the stream progresses.
    let bump = norm_pr * (1.0 - norm_pr);
    score += 30.0 * bump * (1.0 - progress);

    // Tight fit reward (smooth, quadratic in item fraction of bin).
    let fill_frac = item_size as f64 / cap;
    score -= 20.0 * fill_frac * fill_frac;

    // Last-chance bin: strongly favor using it (avoid opening new bins).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Crowd penalty: many open bins -> prefer consolidating into fuller bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Lookahead: if next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        let diff = (pr as u32).checked_sub(next_item_size).unwrap_or(u32::MAX);
        if diff != u32::MAX {
            score -= 15.0 * (1.0 - diff as f64 / cap);
        } else {
            // Dead space relative to next item: penalize unusable leftover.
            score += 5.0 * norm_pr;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" residue classes (multiples of common small sizes) are favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Perfect fit bonus: zero residual is ideal.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Dead-space penalty grows super-linearly for tiny unusable leftovers.
        if post_residual < 10 {
            score += 120.0 * (10.0 - post) / 10.0;
        }
        // Harmonic class: reward residuals divisible by small item sizes (2,4,5,10).
        let divisible_bonus = if post_residual % 10 == 0 {
            40.0
        } else if post_residual % 5 == 0 {
            25.0
        } else if post_residual % 4 == 0 {
            18.0
        } else if post_residual % 2 == 0 {
            10.0
        } else {
            0.0
        };
        score -= divisible_bonus;
    }

    // Fraction-of-capacity classes for the item itself: large items (>cap/2)
    // should be packed tightly into tight bins; small items are flexible.
    let frac = item / cap;
    if frac > 0.5 {
        // Big item: strongly prefer the tightest bin.
        score -= 60.0 * frac;
    } else if frac < 0.25 {
        // Tiny item: penalize wasting a nearly-empty bin on it.
        if post > 0.6 * cap {
            score += 30.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a chain placement — reward it strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how well it chains.
            score -= 25.0 * (next_item_size as f64 / post.max(1.0));
        } else {
            // Next item won't fit here: penalize leaving residual that is
            // just barely too small (wasted sliver).
            let gap = next_item_size as f64 - post;
            if gap < 15.0 {
                score += 45.0 * (15.0 - gap) / 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open
    // bin offers a decent fit. Penalize new bins mildly so they lose to any
    // reasonable fit, but let them win over badly fragmented bins.
    if bin_residual == bin_capacity {
        score += 90.0;
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Fragmentation guard: penalize bins far below the mean residual only if
    // placing here would strand a large, awkward residual.
    if post_residual as f64 > mean_residual + 0.35 * cap {
        score += 20.0;
    }

    // Congestion: when many bins are open, favor consolidation (tight fits).
    if open_bins_count > 8 {
        score -= 15.0 * (1.0 - post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit any plausible
    // future item are wasted. Penalize sharply when post_residual falls into
    // the "unusable gap" zone (small but nonzero).
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - pr) / 10.0;
    }

    // Tight-fit reward: the closer the item fills the bin, the better.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage scattering items across many bins when
    // the count grows; mildly favor consolidating into fewer bins.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless post_residual is dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin offers a
    // good fit; make the empty bin slightly unattractive by default so we
    // reuse bins, but keep it competitive if the item is large.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item can use this bin's post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit the leftover, the leftover risks being dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mean residual coupling: penalize placing into bins that deviate from
    // the mean residual (keeps the bin pool homogeneous and packable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Early-stream: be a bit more willing to open bins early to build a
    // diverse pool; late-stream: consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize small dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 30.0 * (waste / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when a decent fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 80.0 + 0.5 * open_bins_count as f64;
    }

    // Mild pressure to close out bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared post-residual penalizes wasted space superlinearly.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize leaving a dead gap that the next item cannot use.
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: prefer it only when open bins are congested or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / 20.0;
        score += 12.0 + 25.0 * (1.0 - progress) - congestion.min(20.0);
    }

    // Favor bins that are tighter than the current average residual.
    score -= 0.25 * (mean_residual - bin_residual as f64);

    // Slight time-horizon bias: late in the stream, pack tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * (1.0 + 0.9 * progress * x + 0.6 * progress * progress * x * x);

    // Lookahead: reward residual that can still hold the next item
    let mut score = pr * (1.0 + 0.5 * progress) + 3.0 * poly;
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64).sqrt() * (1.0 + 1.5 * progress);
    } else if next_item_size > 0 {
        score += 2.0 + 6.0 * progress;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize bins far from mean residual (fragmentation)
    score += 0.15 * (pr - mean_residual).abs();

    // Slight penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residuals into coarse classes
    // via integer division thresholds (class 0 = tight fit, higher = wasteful).
    let class = post_residual / 10; // 0..=10 harmonic class
    score += match class {
        0 => -60.0,           // near-perfect fit: heavily reward
        1 => -30.0,           // small dead space
        2 => -10.0,
        3 => 0.0,
        4 => 10.0,
        5 => 20.0,
        6 => 30.0,
        7 => 40.0,
        8 => 50.0,
        _ => 60.0,            // large dead space: penalize
    };

    // Modulo arithmetic: residuals that are multiples of common item sizes
    // are more reusable. Reward divisibility of post_residual by small units.
    let pr = post_residual;
    let mut div_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { div_bonus += 8.0; }
        if pr % 20 == 0 { div_bonus += 6.0; }
        if pr % 25 == 0 { div_bonus += 6.0; }
        if pr % 50 == 0 { div_bonus += 6.0; }
    }
    score -= div_bonus;

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how well it fills
            let fill = next_item_size as f64 / pr as f64;
            score -= 20.0 * fill;
        } else {
            // next item will NOT fit here: mild penalty if this bin was the
            // only fitting option (we'd strand the bin anyway).
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: brand-new empty bin has residual == capacity.
    // Prefer it only when current placement would leave awkward dead space
    // (mid harmonic classes) and there are many open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 55.0 + 25.0 * (1.0 - progress);
        // penalize opening new bins generally; but if the item would leave a
        // "bad class" residual in existing bins, the class penalty above may
        // dominate and this base keeps new-bin competitive for large items.
        score += base - 0.5 * open_bins_count as f64;
        // large items pack cleanly into fresh bins
        if item_size >= 50 {
            score -= 20.0;
        }
    }

    // Coupling with mean residual: bins far below mean residual are "fresh",
    // keep them flexible; bins above mean are old/fragmented, prefer filling.
    if (bin_residual as f64) > mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it cannot hold even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize gaps too small for the known next item (wasted for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward using a bin whose residual was already tight (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly prefer filling the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones.
    if bin_residual == bin_capacity {
        // Candidate new bin: penalize more when many bins are already open
        // and mean residual suggests existing space could be consolidated.
        score += 30.0 + 2.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // But if no open bin fits well (post_residual on new bin is natural),
        // allow opening when stream is early and bins are few.
        if open_bins_count < 3 {
            score -= 25.0;
        }
    }

    // Mild late-stream bias: consolidate into existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 8.0 * progress;
    }

    // Prefer bins whose residual is close to item size (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual matches the
    // next item's size (perfect chaining), penalize wasted dead space otherwise.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Reward bins that can still host the next item, scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 / (1.0 + slack / 10.0);
        } else {
            // Penalize leaving a gap smaller than the next item (dead space).
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize low-utility residual space relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < mean_residual * 0.5 {
            score += 15.0; // creating below-average residual: fragmentation risk
        } else if pr > mean_residual * 1.5 {
            score -= 5.0; // keeping a large useful residual
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive if all existing fits are poor
    // or the stream is early and consolidation is unlikely.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: wastes the residual of this empty slot.
        score += 200.0;
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative, must open
        } else if fitting_bins_count == 1 {
            // Competing with a single (already boosted) fitting bin; stay discouraged
            // unless the item leaves a very awkward residual there.
            if (bin_residual - item_size) < 10 {
                score -= 250.0;
            }
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 40.0;
    }

    // Mild preference for tighter existing bins among equals.
    score += (bin_residual as f64) * 0.05;

    // Slight load-balancing: fewer open bins is better; discourage spreading.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit reward: strong subtraction so zero-waste placements dominate.
    if post_residual == 0 {
        score -= 2.0 * cap;
    }

    // Dead space penalty: residual too small for the lookahead item (or below
    // the minimum plausible item size when no lookahead) is likely wasted.
    let min_item = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < min_item {
        score += 0.75 * post;
    }

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // reward this bin; if next item barely misses, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = post - nxt;
            score -= 0.4 * (nxt / cap) * (1.0 - gap / cap);
        } else {
            score += 0.3 * nxt * (1.0 - post / cap);
        }
    }

    // Tightness reward: filling a bin deeply is good, scaled by fill fraction.
    let fill = (bin_residual as f64 - post) / cap;
    score -= 1.5 * fill * fill;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.9 * cap;
    }

    // New-bin candidate handling: an empty bin gets a moderate baseline cost so
    // it is only chosen when open bins fit poorly. Cost shrinks late in the
    // stream when consolidation matters less, and grows with many open bins
    // (encourage reuse of scattered bins instead of spawning more).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += cap * (0.55 + 0.25 * progress + 0.15 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)));
    }

    // Mean-residual coupling: when open bins are collectively roomy, nudge
    // toward using them rather than new bins; when they are tight, relax.
    if bin_residual != bin_capacity {
        score -= 0.2 * (mean_residual / cap) * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear penalty on residual scaled by capacity
    let x = pr / cap;
    score += 12.0 * x * x * (1.0 - x);

    // Progress-coupled quadratic term: late stream punishes waste harder
    score += 20.0 * progress * x * x;

    // Reward tight fits (small post residual) non-linearly
    score -= 15.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Last-chance bin bonus (smooth via fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Lookahead coupling: favor bins whose post residual matches next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_gap = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins near mean residual
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: penalize mildly so it wins only when fits are bad
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 define dead-space classes.
    let class = post_residual % 10;
    // Class 0 residues are perfectly reusable; odd/prime-ish residues are less so.
    score += match class {
        0 => -6.0,
        5 => -2.0,
        2 | 4 | 6 | 8 => -1.0,
        _ => 1.0, // odd, hard-to-fill residues
    };

    // If the next item fits exactly into the post-residual, strongly reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Reward partial compatibility, scaled by how tightly it fits.
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize proportionally to wasted space.
        score += 0.05 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): penalize unless current fit wastes a lot
    // relative to what a fresh bin would offer.
    if bin_residual == bin_capacity {
        score += 30.0;
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio > 0.6 {
            score -= 45.0; // item leaves a fresh bin still very usable anyway
        }
    } else {
        // Prefer tighter fits among open bins: reward low post_residual fraction.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Late in the stream, close out bins aggressively (favor filling existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading, reward consolidation into low-residual bins.
    if open_bins_count > 4 {
        score += 0.02 * open_bins_count as f64;
        score -= 0.5 * mean_residual.abs().min(50.0) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Integer-division threshold: post_residual in [0..=10] is near-perfect fill.
    if post_residual / 10 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer the tightest fit (smallest leftover).
    let mut score = post;

    // 1) Perfect fit: overwhelmingly reward closing a bin out completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2) Strict dead-space avoidance: small nonzero leftovers are statistically
    //    near-worthless, so punish them with an exponentially decaying penalty.
    //    The penalty is amplified when residual space elsewhere is scarce
    //    (low mean_residual means few future placement opportunities).
    let dead_penalty = 40.0 * (-post / 6.0).exp();
    let scarcity = 1.0 + mean_residual / cap.max(1.0);
    score += dead_penalty * scarcity;

    // 3) open_bins_count pressure: with many open bins, push harder to empty
    //    existing bins (amplify the preference for small post_residual) instead
    //    of letting fragmentation grow.
    score += post * (open_bins_count as f64) * 0.02;

    // 4) Lookahead (k=2): reward leftovers that can host the next item,
    //    with a tighter upcoming fit earning a larger bonus.
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 * (nxt / post);
        }
    }

    // 5) Late-stream tightening: leftovers left near the end of the stream are
    //    unlikely to ever be filled, so gradually penalize large residuals.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score += post * progress * 0.15;

    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Never open a new bin while any open bin can fit the item: doing so
        // strictly increases the bin count while the fitting bin stays open.
        if fitting_bins_count > 0 {
            score += 150.0;
        }
        // Consolidation pressure: the more bins already open, the costlier a new one.
        score += open_bins_count as f64 * 2.0;
    } else if fitting_bins_count == 1 {
        // Last chance: this is the only open bin that fits; using it avoids
        // opening a new bin regardless of the dead space it creates (sunk bin).
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits relative to mean residual across open bins.
    score -= mean_residual * 0.35;

    // Lookahead: reward leaving exactly the next item's size (perfect chain fit).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Extra bonus for exact match: next item fills bin completely.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving dead space that no plausible next item can use.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Penalize very small unusable fragments (dead space).
    if post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New empty bin candidate: penalize opening a new bin unless current bin
    // would leave a bad fit or there are no fitting bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Opening a new bin is more attractive early (more stream remaining to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
    }

    // Mild reward for bins already partially loaded (consolidation).
    if bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Prefer bins whose residual is close to item size (tight fit ratio).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Slight penalty for too many open bins: encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: if the next item fits into the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            // Penalize leaving a residual that is useless for the next item
            // (dead space between 1 and next_item_size - 1).
            let waste = (post_residual as f64 - (post_residual as f64 / next_item_size as f64).floor() * 0.0);
            score += 0.05 * waste.min(30.0);
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: usually bad unless it avoids extreme fragmentation.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 + 10.0;
        // If no open bin fits, the new bin is the only option anyway.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If open bins have large mean residual, opening new bins is wasteful.
        score += 0.3 * mean_residual;
    } else {
        // Reward using bins whose residual is close to the item (best-fit coupling).
        let fit_gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.10 * fit_gap;
        // Slight penalty for spreading across too many open bins.
        score += 0.02 * open_bins_count as f64;
    }

    // Fragmentation guard: penalize tiny unusable residuals more aggressively.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: post residual, with smooth non-linear shaping (quadratic/cubic waste penalty)
    let mut score = pr * (1.0 + 0.9 * norm_post * norm_post) + 12.0 * norm_post * norm_post * norm_post * cap;

    // Polynomial coupling with stream progress: waste tolerated early, punished late
    score *= 1.0 - 0.35 * progress * (1.0 - norm_post) * (1.0 - norm_post);

    // Reward tight fits: smooth term in item_size / residual fill ratio
    let fill = item_size as f64 / cap;
    score -= 8.0 * fill * (1.0 - norm_post);

    // Last-chance bin: strong smooth reward when few fitting bins
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Lookahead coupling: penalize leaving residual that neither fits next item well nor is near zero
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let mismatch = if pr >= n { (pr - n) / cap } else { pr / cap + n / cap };
        score += 10.0 * mismatch * mismatch * cap / 100.0;
        score -= 5.0 * (1.0 - (pr - n).abs() / cap);
    } else {
        // Last item: strongly prefer filling bins completely
        score -= 20.0 * (1.0 - norm_post);
    }

    // Mild preference for consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64 * (norm_post - mean_residual / cap).abs();

    // New-bin candidate handling: make an empty bin mildly attractive only when residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = pr + 6.0 + 25.0 * fragmentation * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: capacity divided into 10 classes of 10 units
    let post_class = (post_residual / 10) as f64;

    // Perfect-fit reward: exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward small post-residuals (tight fits) with a convex penalty on larger ones
    score += 0.15 * post_class * post_class;

    // Harmonic coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward leaving room for the next item, scaled by how well it uses the leftover
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill_ratio;
            // Bonus if next item nearly fills the post residual (leaves <= 5 dead)
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 5 {
                score -= 15.0;
            }
        } else {
            // Penalize leaving a residual that the next item cannot use
            score += 10.0;
        }
    }

    // Modulo logic: residuals that are multiples of 5/10 are "harmonic" and more reusable
    if post_residual % 10 == 0 {
        score -= 5.0;
    } else if post_residual % 5 == 0 {
        score -= 2.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are very fragmented
    if bin_residual == bin_capacity {
        let avg_gap = mean_residual.max(0.0);
        score += 60.0;
        // If mean residual across open bins is small, opening a new bin is less wasteful
        score -= avg_gap * 0.5;
        // Late in the stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Mild penalty when many bins are open and this one is highly fragmented
    if open_bins_count > 3 && post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Nonlinear dead-space pressure: quadratic growth of wasted fraction.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * waste_frac * waste_frac;

    // Reward tight fits (post_residual close to 0 relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 20.0 * (tightness / (1.0 + tightness));

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones over new bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 3.0;

    // New-bin candidate: penalize unless current bin would leave bad dead space
    // or next item could use this bin's residual better.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // But if this bin's placement would leave an awkward small gap, allow new bin.
        let bad_gap = post_residual > 0 && post_residual < 10;
        let next_fits_gap = next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10;
        if bad_gap && !next_fits_gap {
            score -= 45.0;
        }
        // Early stream with few bins: opening new bins is cheaper.
        if open_bins_count < 3 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual is close to item (best-fit flavor).
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += gap * 0.2;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize if next item is larger than post_residual but would fit elsewhere fine.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Mean residual coupling: prefer placing into bins with residual near mean
    // (keeps bin population homogeneous), avoid outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: tiny post-residual is ideal.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 120.0; // chain of two perfect fits
        } else if next_item_size <= post_residual {
            let slack = post_residual as f64 - next;
            // Reward lookahead fit, stronger when slack is small (tight chain).
            score -= 40.0 * (1.0 - slack / 100.0);
        } else {
            // Next item cannot fit here; penalize proportionally to overflow gap,
            // but less if post_residual is large enough to be generally useful.
            let gap = next - post_residual as f64;
            score += 10.0 * (gap / 100.0).min(1.0);
        }
    } else {
        // Last item: only immediate tightness matters.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual above mean are more valuable to
    // fill tightly; bins already below mean get a mild penalty for wasting space.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel > 1.0 {
            score -= 8.0 * (rel - 1.0).min(2.0);
        } else {
            score += 6.0 * (1.0 - rel);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
        if post_residual > 50 {
            score += 25.0; // bad fit in the only fitting bin -> soften the reward
        }
    }

    // New-bin candidate handling: an empty bin has full residual; make it attractive
    // only when the item is large or the fit into open bins would leave big dead space.
    if bin_residual == bin_capacity {
        if item_size >= 70 {
            score -= 30.0; // big items are fine in fresh bins
        } else {
            score += 20.0 + 0.5 * (100 - item_size.min(100)) as f64 * 0.2;
        }
        // If lookahead item is small, keeping a fresh bin is useful.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 10.0;
        }
    }

    // Stream progression: early on, slightly discourage opening many bins; late,
    // prioritize tight packing even more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    // Crowd factor: with many open bins, favor consolidating into existing ones.
    if open_bins_count > 4 {
        score += 2.0 * ((open_bins_count as f64) - 4.0).min(10.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but zero residual is best.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize leaving dead space that no plausible future item can use.
        let t = step_index as f64 / (total_items.max(1) as f64);
        // Small residuals become more valuable late in the stream (less chance to close bins).
        let dead_weight = 8.0 + 12.0 * t;
        if post_residual < 10 {
            score -= dead_weight; // small gap likely usable by tiny items
        } else {
            score += dead_weight * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 45.0;
        } else {
            score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here after placement; mild penalty for blocking lookahead.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is justified only when open bins
    // have poor residuals and this bin is nearly empty.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_cost = 25.0;
        // If many open bins have large mean residual, discourage opening another.
        new_bin_cost += (mean_residual / bin_capacity as f64) * 40.0;
        // If this bin is the only fitting option, opening may be necessary.
        if fitting_bins_count == 0 {
            new_bin_cost -= 40.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        new_bin_cost += 10.0 * t;
        score += new_bin_cost;
    }

    // Mild preference for filling bins with larger residual when many bins are open
    // (keeps number of active bins down).
    if open_bins_count > 4 {
        score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);

    // Non-linear growth of waste penalty with stream progress
    let pr = post_residual as f64;
    score += 0.35 * pr * t + 0.002 * pr * pr * (1.0 - t);

    // Lookahead-aware dead-space penalty: residual too small for next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 0.6 * gap * (1.0 + t);
    }
    // Reward leaving exactly enough room for the lookahead item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * t;
    }

    // New empty-bin candidate: mild penalty so existing bins are preferred,
    // modulated by mean residual (crowded bins make new bin more attractive)
    if bin_residual == bin_capacity {
        score += 15.0 + 0.15 * mean_residual - 10.0 * (1.0 - t);
    }

    // Smooth coupling: prefer placing larger items into tighter bins
    score -= 0.05 * item_size as f64 * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Penalize residual classes that are hard to fill later (small unusable slivers).
    // Classes: (0,10] terrible, (10,30] bad, (30,50] ok, (50,100] good.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual <= 10 {
        score += 45.0; // dead sliver
    } else if post_residual <= 30 {
        score += 18.0;
    } else if post_residual <= 50 {
        score += 4.0;
    } else {
        score -= 8.0; // roomy residual, still usable
    }

    // Modulo logic: residuals that are multiples of common item sizes are reusable.
    for m in [10u32, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (20.0 * (1.0 - slack / cap)).max(0.0);
        } else {
            // next item won't fit here: penalize wasting a "good" residual
            score += 6.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin; make it competitive with mediocre fits.
        score = 55.0 + 0.25 * mean_residual + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
    }

    // Late-stream tightening: prefer filling existing bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_frac);

    // Prefer bins tighter than average (best-fit flavor).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers (1..=10) are almost unusable
    // given item sizes, so penalize them heavily (non-linearly).
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }
    // Mid-range dead space (11..=19) is also risky: only next items <= that fit.
    if post_residual > 10 && post_residual <= 19 {
        score += 15.0 + 1.5 * (19 - post_residual) as f64;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (post_residual small relative to capacity) smoothly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Open-bin pressure: discourage opening new bins when many bins are open
    // and this bin fits reasonably (post_residual not huge).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin baseline: its post_residual is capacity - item_size, which is
        // naturally large; add pressure proportional to open bins.
        score += 8.0 * (open_bins_count as f64).sqrt();
        // Only allow new bin to win if the fit in existing bins is terrible:
        // i.e. if this call is a last-chance bin, strongly prefer using it.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
        // Lookahead: if next item would fit the residual left here, bonus.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
    } else {
        // Existing bin: last-chance bonus to avoid opening a bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Prefer bins whose residual deviates from mean in a useful way:
        // filling down the mean residual reduces fragmentation.
        score -= 0.3 * (mean_residual - post_residual as f64);
        // Lookahead synergy: if next item exactly fills this bin's post residual.
        if next_item_size == post_residual && post_residual > 0 {
            score -= 30.0;
        }
        // If next item cannot use the leftover, mild penalty for wasting space.
        if next_item_size > post_residual && post_residual > 0 && post_residual <= 19 {
            score += 10.0;
        }
    }

    // Mild stream-progression term: later in the stream, be greedier about
    // tight fits (less room to recover from fragmentation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: bin becomes exactly full after next item
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // small slack after lookahead placement is good
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin; penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize creating tiny unusable dead space (< 10, smallest item).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Mild pressure to prefer fuller bins as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (item_size as f64 / bin_capacity as f64);

    // Slight penalty for proliferating bins when many are open.
    score += 0.05 * open_bins_count as f64;

    // Brand-new empty bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= bin_capacity as f64 {
            score -= 5.0; // fresh bin can host a clean 2-item chain
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: strongly prefer minimal post_residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 55.0 * tight * tight;

    // Lookahead: reward if the next item fits exactly into the post residual,
    // penalize if post residual is too small to ever be useful again.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size < post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // dead space unless tiny
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 0.5 * dead; // small dead space is cheap
            } else {
                score += 6.0;
            }
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, exploit tight fits aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tight;

    // Global pressure: many open bins with high mean residual -> favor filling
    // existing bins rather than opening new ones.
    if open_bins_count > 2 {
        score -= 0.3 * mean_residual.min(100.0);
    }

    // New empty bin candidate: make it attractive only when the fit into
    // existing bins would be very poor (large post_residual).
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 30.0;
        // but if this item would leave big dead space in any existing bin,
        // a fresh bin becomes relatively better (score already reflects that).
        if post_residual == 0 {
            score -= 100.0; // exact fit in a fresh bin is perfect
        }
    }

    // Penalize leaving residuals that are hard to fill (typical awkward zones).
    let r = post_residual;
    if r > 0 && r < 10 {
        score += 3.0; // near-useless sliver
    } else if r >= 40 && r <= 60 {
        score -= 5.0; // versatile residual range
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: reward tight fits (small post_residual) with a convex penalty on waste.
    let mut score = (pr / cap).powi(2) * cap;

    // Smooth interaction: tight fits matter more as the stream progresses.
    score -= (1.0 - pr / cap).powi(2) * (progress * 8.0 + 2.0);

    // Penalize creating dead space that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += (gap / cap).powi(2) * 6.0;
        // Reward residuals that still fit the next item.
        if pr >= next_item_size as f64 {
            score -= 2.0 + progress * 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 + progress * 5.0;
    }

    // New empty bin candidate: penalize opening bins when good fits exist,
    // but allow it late in the stream or when the item is large.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score += 6.0 - progress * 3.0 - large_item * 4.0 + (open_bins_count as f64) * 0.15;
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter bins).
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    // Residuals in the "dead zone" (small unusable remainders) are penalized hard.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= eighth {
        score += 25.0; // tiny dead space, nearly unusable
    } else if post_residual <= quarter {
        score += 8.0;
    } else if post_residual <= 2 * quarter {
        score -= 6.0;
    } else {
        score -= 12.0; // large residual stays useful
    }

    // Modulo harmonic class of post_residual: multiples of common item sizes
    // (10/20/25/50) are re-usable by future items; odd remainders are not.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 5.0;
    }
    if pr > 0 && pr % 10 != 0 && pr < 10 {
        score += 10.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual: leftover likely wasted
            let waste = (next_item_size - post_residual).min(post_residual) as f64;
            score += waste * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer existing bins unless this bin would be badly fragmented.
    if bin_residual == bin_capacity {
        // Base penalty: opening a new bin is expensive when good fits exist.
        score += 30.0 + open_bins_count as f64 * 2.0;
        // But if the item is huge relative to mean residual of open bins,
        // a fresh bin is attractive (avoid fragmenting many bins).
        if item_size as f64 > mean_residual + 0.5 * cap {
            score -= 45.0;
        }
        // Late in the stream, avoid opening bins that will stay nearly empty.
        if next_item_size == 0 {
            score += 100.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit) globally.
    score += (bin_residual as f64 - item_size as f64).abs() * 0.15;

    // Slight preference for bins below mean residual (fill the emptier ones
    // less; keep concentrated residuals for big future items).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    }

    // Stream progression: early on, be conservative about dead space;
    // later, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (post_residual == 0) as u32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size ~1..20) are heavily penalized.
    if post_residual > 0 {
        if post_residual < 20 {
            // Unusable sliver of dead space - strongly penalize.
            score += (20 - post_residual) as f64 * 6.0;
        } else if post_residual < 40 {
            // Marginal gap: mild penalty.
            score += (40 - post_residual) as f64 * 1.5;
        } else {
            // Large usable residual: reward tight fits that leave big gaps.
            score -= (post_residual - 40) as f64 * 0.8;
        }
    } else {
        // Perfect fill: massive reward.
        score -= 150.0;
    }

    // Reward exact match with the lookahead item (k=2 lookahead coupling).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Penalize if the next item cannot fit into the post residual.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: it has bin_residual == bin_capacity. Make it
    // attractive only when open-bin pressure is high or current fit is bad.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a new bin, scaled by open bins pressure.
        score = 60.0 + (open_bins_count as f64) * 4.0;
        // If the stream is early, opening fresh bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score *= 1.0 - 0.3 * progress;
        // If mean residual across open bins is large, prefer existing bins.
        score += mean_residual * 0.5;
    }

    // Open-bins pressure: with many open bins, favor consolidating into
    // existing bins (penalize placements that waste space there less).
    score += (open_bins_count as f64).sqrt() * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual was already tight (efficient packing).
    score -= (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward post_residual that matches next_item_size exactly or closely
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // residual can host next item: mild reward proportional to tightness
            score -= 40.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalty grows with gap
            score += 0.6 * (nxt - post_residual as f64);
        }
    }

    // Penalize small unusable residuals (dead space) non-linearly
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Compare against mean residual: prefer bins that are already tight
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 + 30.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0; // existing bins could chain-fit, keep them
        }
        if fitting_bins_count == 1 {
            score += 120.0; // never open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that nothing else can use (post_residual too small to matter).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; penalize wasting residual that could have held it.
            score += 6.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    } else {
        // Last item: just fill as tightly as possible.
        score -= 20.0 * fill_ratio;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins with high mean residual: encourage consolidating into existing bins.
    if open_bins_count > 4 && mean_residual > 30.0 {
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }

    // Early in stream: mild preference for opening new bins to build flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 3.0;
    }

    // Prefer bins that are already partially filled (avoid scattering).
    if bin_residual < bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), non-linearly.
    let mut score = post * (1.0 + 0.02 * post / cap);

    // Quadratic penalty on dead space, amplified late in the stream.
    let waste_frac = post / cap;
    score += 30.0 * waste_frac * waste_frac * (0.5 + progress);

    // Reward filling the bin well (high fill ratio), smooth cubic reward.
    let fill = item / residual.max(1.0);
    score -= 20.0 * fill * fill * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New empty bin candidate: penalize unless the item would leave big waste elsewhere.
    if bin_residual == bin_capacity {
        // Opening a new bin is costly; penalize mildly, less so if this item is large.
        score += 25.0 - 0.2 * item;
        // Late in the stream, closing out open bins is better than spreading.
        score += 15.0 * progress;
        // If many bins already fit the item, opening new is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        score -= 12.0 * (1.0 - diff / cap).max(0.0) * (1.0 - progress * 0.5);
    }

    // Prefer bins with below-mean residual (consolidate emptier bins? no:
    // prefer filling bins that are already relatively full).
    if open_bins_count > 1 {
        score += 0.15 * (mean_residual - residual);
    }

    // Mild penalty for having many open bins when placing into a fresh-ish bin.
    score += 0.02 * (post as f64).powi(2) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands in a
    // "usable" class (large enough for typical future items) are favored.
    let capacity_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / capacity_f; // fraction of capacity wasted

    // Dead-space penalty grows superlinearly for tiny unusable leftovers.
    if post_residual > 0 {
        // harmonic classes via integer division thresholds on post_residual
        let class = post_residual / 10; // class 0..=10
        match class {
            0 => score += 45.0,                 // 1..9 : almost dead space
            1 => score += 30.0,                 // 10..19: only tiny items fit
            2 => score += 18.0,                 // 20..29
            3 => score += 8.0,                  // 30..39
            4 => score += 2.0,                  // 40..49: good
            5 => score += 0.0,                  // 50..59: ideal half-bin
            6 => score -= 3.0,                  // 60..69: roomy
            7 => score -= 5.0,                  // 70..79
            8 => score -= 6.0,                  // 80..89
            9 => score -= 6.5,                  // 90..99
            _ => score -= 7.0,                  // exactly full
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Pairing bonus: if the NEXT item fits exactly into the post residual,
    // this placement is a perfect two-item chain.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack <= 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot fit here, mildly penalize leaving a mid gap that
    // matches neither small nor large classes.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (post_f * 0.15).min(15.0);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the current
    // bin's post residual would be poorly usable; otherwise keep open bins
    // preferred to avoid bin proliferation.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 10.0;
        // If this bin candidate is evaluated for the empty bin, post_residual
        // equals capacity - item_size; reward keeping big leftovers only when
        // open bins are already fragmented.
        if open_bins_count > 0 {
            let mean_gap = mean_residual - post_f;
            if mean_gap > 0.0 {
                score -= mean_gap * 0.25; // new bin keeps larger residual than average
            }
        }
        // Late in the stream, opening fresh bins is less costly (fewer future
        // items to strand), scale the penalty down.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 8.0;
    } else {
        // Existing bin: slight bonus for bins tighter than the mean residual
        // (concentrating fill), scaled by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let gap = post_f - mean_residual;
        if gap < 0.0 {
            score += gap * 0.05 * (1.0 - progress); // tighter-than-mean bins favored
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1) are pure waste; penalize them quadratically.
    if post_residual < 1 {
        score += 1000.0; // impossible fit, should never happen but guard
    }
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * (10.0 - dead) * 0.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space relative to what's coming next
        score += 5.0;
    }

    // Open-bin pressure: when many bins are open, favor consolidating into
    // existing bins (penalize the new-bin candidate more).
    if bin_residual == bin_capacity {
        // New-bin candidate: its raw post_residual is large; add pressure
        // proportional to number of open bins that could already fit.
        score += (open_bins_count as f64) * 2.0;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    } else {
        // Mild reward for using existing bins as pressure builds.
        score -= (open_bins_count.min(20) as f64) * 0.3;
    }

    // Slight preference for tighter-than-average fits.
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item exactly matches the
    // post-residual, this placement is perfect — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits in leftover: mildly good.
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to wasted space.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(40.0);
        }
    }

    // Compare against mean residual across open bins: prefer bins whose
    // residual is already below average (consolidating waste).
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large relative
    // to capacity (poor fit elsewhere likely) or many bins are open.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
        let attractiveness = 40.0 * fill_ratio * fill_ratio + 20.0 * pressure.min(1.0);
        score += 80.0 - attractiveness;
        // If next item is small, a fresh bin wastes capacity potential.
        if next_item_size > 0 && next_item_size < 20 {
            score += 15.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins for
    // flexibility; late in the stream, squeeze everything shut.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor placements that leave little dead space.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tight * tight;

    // Reward small waste relative to item size (relative fit quality).
    if item_size > 0 {
        score += 10.0 * (post_residual as f64 / item_size as f64).min(3.0);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current fit is poor and the lookahead item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = post_residual as f64 / bin_capacity as f64; // = 1 - item/C for empty bin
        let lookahead_pressure = next_item_size as f64 / bin_capacity as f64;
        // Penalize new bins by default; discount penalty when many open bins
        // already exist and the stream is late (fragmentation risk).
        let mut penalty = 25.0;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty -= 10.0 * progress;
        penalty -= 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        // If lookahead is big and this bin's post-residual would be tiny, new bin
        // may be better; reduce penalty.
        penalty -= 15.0 * lookahead_pressure * poor_fit;
        score += penalty;
    } else {
        // Lookahead coupling: if the next item fits exactly in post_residual,
        // reward this placement strongly (chain packing).
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 25.0;
            } else if post_residual > next_item_size {
                score -= 8.0 * (next_item_size as f64 / post_residual as f64);
            } else {
                // next item won't fit here; mild penalty proportional to waste
                score += 5.0 * (next_item_size as f64 / bin_capacity as f64);
            }
        }
    }

    // Global state coupling: prefer placing into bins whose residual is near
    // the mean residual (keeps bin residuals homogeneous, easier future fits).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * (dev / (mean_residual + 1.0)).min(2.0);

    // Penalize very large open_bins_count slightly to encourage consolidation.
    score += 1.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += poly * cap * 0.5;
    // reward tight fits
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 20.0;
    // last chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }
    // penalize fragmentation vs mean residual
    score += 0.3 * (pr - mean_residual) * (1.0 - progress);
    // lookahead: penalize if next item can't use the leftover
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * 0.8;
        } else {
            score -= 5.0 * (1.0 - (pr - nxt) / cap);
        }
    }
    // mild penalty for too many open bins
    score += open_bins_count as f64 * 0.05 * progress;
    // new-bin candidate normalization
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress) * norm_pr;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: which fifth of the capacity it belongs to.
    let item_class = (item_size * 5 + bin_capacity - 1) / bin_capacity; // 1..=5
    let next_class = if next_item_size == 0 { 0 } else { (next_item_size * 5 + bin_capacity - 1) / bin_capacity };

    // Reward tight fits strongly (post residual small relative to capacity).
    let tight = post_residual as f64 / cap;
    score -= (1.0 - tight) * (1.0 - tight) * 10.0;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: residual that is too small to host common items.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 1 {
        score += 20.0;
    }

    // Harmonic pairing: reward if post_residual can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / cap);
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize if we waste capacity that
        // would have been useful, scaled by how large the next item is.
        let waste = post_residual as f64;
        score += 0.05 * waste * (next_item_size as f64 / cap);
    }

    // Complementary class logic: small items (class 1-2) prefer large-residual bins;
    // large items (class 4-5) prefer bins they nearly fill.
    let residual_class = (bin_residual * 5 + bin_capacity - 1) / bin_capacity;
    let class_gap = (item_class as i32 - residual_class as i32).abs();
    score += class_gap as f64 * 2.0;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly by default, more when open bins are few
    // or mean residual is large (we should reuse capacity first).
    if bin_residual == bin_capacity {
        score += 15.0;
        score += open_bins_count as f64 * 2.0;
        score += mean_residual.max(0.0) * 0.3;
        // But if no existing bin fits (this is the only option), the +15 keeps it
        // competitive only when alternatives are bad; if nothing fits, all new-bin
        // calls still win since fitting bins get waste penalties.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late-stream bias: consolidate more aggressively near the end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0 * (1.0 - tight);

    // Modulo harmonic bonus: post_residual divisible by common item sizes (10/20/25/50)
    // keeps the residual in a "usable class".
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible item (min item size 1, but realistically small gaps under
    // ~12 are hard to reuse) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 + (12 - post_residual) as f64 * 6.0;
    }
    // Perfect fit: maximal reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap that fails the lookahead: mild extra penalty.
        score += 5.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating
    // (penalize spreading into fresh space); with few bins, be lenient.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // Tightness reward: fraction of the bin's residual consumed.
    if bin_residual > 0 {
        score -= 20.0 * (item_size as f64 / bin_residual as f64);
    }

    // Mean residual coupling: bins with residuals well below the mean are
    // "nearly full" — favor packing them further.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize so it's only chosen when all
    // open bins fit poorly (its raw post_residual = capacity - item is large,
    // but ensure a bias against opening bins under normal pressure).
    if bin_residual == bin_capacity {
        score += 12.0 + pressure * 2.0;
        // Early in the stream, opening a bin is fine.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 12.0 * (1.0 - progress);
    }

    // Waste ratio: post_residual relative to capacity as a soft term.
    score += (post_residual as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fills (small post_residual is already the base).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small to ever hold another item (min size 1).
        if post_residual < 1 {
            score += 500.0;
        }
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly or closely matches the next item size.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: chain the next item perfectly.
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // Next item fits: reward proportionally to how tight the fit is.
            let tightness = 1.0 - lookahead_gap / bin_capacity as f64;
            score -= 60.0 * tightness;
        } else {
            // Next item would NOT fit: penalize proportional to the miss.
            score += 40.0 * (lookahead_gap / bin_capacity as f64);
        }

        // Two-step chain: post_residual == item_size + next_item_size means
        // this bin was sized for both, still a decent sign of coordination.
        if post_residual + item_size as u32 == bin_residual
            && bin_residual as f64 > mean_residual {
            score -= 15.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the fleet average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that can fit the item, using it
    // avoids opening a new bin, so reward it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate (pristine empty bin): only attractive when no open bin
    // is a good home. Make the empty bin expensive unless the item is huge
    // relative to typical residuals or the fleet is nearly exhausted.
    if bin_residual == bin_capacity {
        let fleet_pressure = mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        // Discount for new bin when item is large, fleet residuals are small,
        // or we are late in the stream.
        let discount = 20.0 * big_item + 30.0 * (1.0 - fleet_pressure) + 40.0 * progress;
        score = score.max(0.0) + 120.0 - discount;
    }

    // Mild preference for consolidating into fewer bins early on.
    if open_bins_count > 0 && bin_residual != bin_capacity {
        score -= 5.0 / open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in post_residual).
    if post_residual == 0 {
        score -= 200.0;
    } else {
        let pr = post_residual as f64;
        score += pr * pr / bin_capacity as f64 * 0.05;
    }

    // Lookahead: reward if next item fits into post_residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + next_item_size as f64 * 0.3;
        } else {
            // Penalize leaving residual that no plausible item can use
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 10.0; // tiny dead space
            } else {
                score += waste * 0.4;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer fuller bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.5;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    // or this is early in the stream with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64;
        // Penalty shrinks when many bins open / late stream (keep bins tight)
        score += 40.0 + 60.0 * (1.0 - progress) - crowding.min(20.0) * 2.0;
        // If no bin currently fits, new bin is fine
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 15.0;

    // Slight preference for bins that leave residual divisible into
    // common small sizes (heuristic fragmentation shaping).
    if post_residual >= 1 && post_residual <= 9 {
        score += 5.0 * (10 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // Smooth non-linear coupling: post-residual weighted by progress polynomial
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * 40.0 * norm_pr * norm_pr;
    // Tight-fit reward (small post residual), stronger late in stream
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.3 + 0.7 * progress);
    // Penalize residual that cannot fit the lookahead item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 30.0 * (1.0 - pr / ns) * (0.5 + 0.5 * progress);
        } else {
            score -= 10.0 * (ns / cap) * (1.0 - progress);
        }
    }
    // Last-chance bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (0.4 + 0.6 * progress);
    }
    // New-bin candidate penalty scaled by stream progress and open bins
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (open_bins_count as f64).sqrt() * (0.5 + 0.5 * progress);
    }
    // Mean-residual coupling: prefer bins near the mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact half/quarter/third fits are gold.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else if pr % 50 == 0 {
        score -= 25.0;
    } else if pr % 25 == 0 {
        score -= 12.0;
    } else if pr % 20 == 0 {
        score -= 8.0;
    } else if pr % 10 == 0 {
        score -= 4.0;
    }

    // Dead-space penalty: residual below smallest plausible item (harmonic floor).
    if pr > 0 && pr < 10 {
        score += 60.0;
    } else if pr < 25 {
        score += 15.0;
    }

    // Lookahead coupling: does next_item_size fit the post residual exactly?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            // harmonic compatibility: next divides post residual nicely
            if pr % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
            score -= 6.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            // next item won't fit here: penalize leftover more
            score += 5.0 + 0.15 * (pr as f64);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score += 45.0 - 40.0 * crowding;
        // early stream: opening bins is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer tighter bins: relative fill fraction.
    let fill = 1.0 - (post_residual as f64 / cap);
    score -= 20.0 * fill * fill;

    // Mean-residual coupling: if this bin is tighter than average, reward it.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Small modulo threshold on item_size classes (odd sizes waste more).
    if item_size % 2 == 1 && post_residual % 2 == 1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are pure waste.
    // Items can be as small as 1, so "dead" means post_residual == 0 is best,
    // but tiny gaps that likely can't fit future items are penalized nonlinearly.
    if post_residual > 0 {
        // Nonlinear penalty that spikes when the gap is small-but-nonzero:
        // a gap of 1..~9 is nearly useless; a gap of 30+ is still reusable.
        let gap = post_residual as f64;
        let deadness = (1.0 - gap / bin_capacity as f64).powi(3);
        score += 40.0 * deadness * (gap.min(15.0) / 15.0);
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward filling bins tightly relative to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than opening new ones.
    score += (open_bins_count as f64) * 2.0;

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "ragged" bin; prefer placing items there to normalize residuals.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Lookahead: if the next item fits exactly in the post-residual, keep this bin
    // tight now but don't destroy the opportunity — slight penalty for leaving
    // a gap the next item can't use.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Next item won't fit here regardless; tight fit now is fine.
            score -= 5.0;
        } else if next_item_size == post_residual {
            // Leave room for a perfect future fit: mild penalty to discourage
            // consuming the space with a sloppy item.
            score += 20.0;
        }
    }

    // New-bin candidate handling: an empty bin gets a neutral-ish baseline.
    // Only prefer it when all fitting open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score = 55.0
            + (open_bins_count as f64) * 2.0
            - (item_size as f64 / bin_capacity as f64) * 25.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0; // empty bin preserves pairing opportunities
        }
    }

    // Stream progression: late in the stream, avoid opening new bins even harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual is good, but only if usable).
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover waste after the pair
            let after_next = post_residual - next_item_size;
            score -= 20.0 - (after_next as f64).min(20.0);
        } else {
            // next item does NOT fit: dead space risk proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + gap.min(40.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 18.0;
    }

    // Penalize bins far below the mean residual (wasteful use of a full bin)
    // and reward bins near the mean (balanced packing).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Slight preference for filling nearly-full bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (1.0 - progress);

    // New-bin candidate should lose unless all fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if no open bin fits well, opening fresh is fine
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space that is too small for typical future items
    // (small leftovers are waste; medium leftovers stay usable).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // penalize those that cannot (k=2 chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 6.0;
        }
        // Exact two-item chain bonus.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are already fragmented or few bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 20.0;
        // Cheap early in the stream when consolidation is still possible.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * (1.0 - progress);
        // If the mean residual is large and usable, prefer existing bins.
        if mean_residual > item_size as f64 + 15.0 {
            score += 15.0;
        }
        // Many open bins: discourage adding more unless it is a clean split.
        score += (open_bins_count as f64).sqrt() * 3.0;
        // Perfect-fit escape hatch: if this item exactly fills a bin, a new
        // bin is pointless.
        if item_size == bin_capacity {
            score += 100.0;
        }
    } else {
        // Slight preference for fuller bins (lower residual first).
        score += (bin_capacity - bin_residual) as f64 * 0.05;
        // If many bins fit the item, mildly prefer the fullest one.
        if fitting_bins_count > 2 {
            score -= 3.0;
        }
    }

    // Global fragmentation pressure: when mean residual is small, conserve
    // open-bin space more aggressively.
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling of post residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * cap;
    score += 0.35 * coupling;
    // reward tight fits (small post residual) more strongly later in stream
    let tight = (norm_pr - 0.5) * (norm_pr - 0.5);
    score -= (1.0 - progress) * 8.0 * (1.0 - tight * 2.0);
    // penalize dead space that cannot fit lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 10.0 * progress;
    }
    // reward using the last fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }
    // penalize opening a new bin when open bins fit well
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 20.0 * (1.0 - norm_pr) * (1.0 - progress) + 5.0;
        if post_residual >= next_item_size && next_item_size > 0 {
            score += 6.0;
        }
    }
    // interaction with mean residual across open bins
    score += 0.1 * (pr - mean_residual) * (1.0 + progress);
    // mild penalty for many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fraction bands.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left over

    // Dead-space penalty: leftovers that are hard to fill (small, awkward remainders).
    // Harmonic classes via modulo on post_residual (e.g. sizes that pair badly with
    // common item sizes get extra penalty).
    let awkward = if post_residual > 0 && post_residual < 10 {
        8.0 // tiny sliver, nearly unusable
    } else if post_residual < 20 {
        4.0
    } else if post_residual % 10 == 0 {
        -3.0 // round leftover is easy to fill with grid-like items
    } else if post_residual % 5 == 0 {
        -1.0
    } else {
        1.5
    };
    score += awkward;

    // Non-linear dead-space curve: penalize mid-small remainders quadratically.
    if frac > 0.0 && frac < 0.3 {
        score += (0.3 - frac) * (0.3 - frac) * 40.0;
    }

    // Lookahead coupling: reward leftovers that exactly (or nearly) fit the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0; // perfect harmonic match
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 6.0; // near match
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 3.0; // next item cannot use this leftover
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when remaining open
    // bins have poor residuals. Base cost for opening a new bin.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + mean_residual * 0.3;
        // If open bins are mostly full, a new bin is attractive.
        if mean_residual < 25.0 {
            score -= 15.0;
        }
        // Late in the stream, avoid opening bins with lots of usable space around.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 5.0;
    }

    // Tight-fit reward: placing item nearly filling the bin is excellent.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Mild preference for bins with lower residual among comparable fits
    // (best-fit behavior is already the base term; add small mean-residual coupling).
    score -= (mean_residual - post) * 0.05;

    // Integer-division threshold: bins whose residual is in the "one more big item"
    // class get slight priority to keep big-item placement options open.
    if bin_residual >= 60 && item_size >= 40 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward bins whose residual was already small (tight packing).
    if bin_residual <= item_size + 5 {
        score -= 10.0;
    }

    // If this bin is the last chance, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin, scaled by how many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the next item could use the leftover of existing bins poorly, opening is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Lookahead: reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        // Gap slightly larger than next item: mild penalty (near-dead space).
        score += 5.0;
    }

    // Mild pressure from mean residual: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.1;

    // Late in the stream, be more conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more aggressively
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect-fit bonus: residual zero
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // next item fits here later; penalize leaving a gap that matches next item poorly
            let gap_after_next = post_residual as f64 - next_item_size as f64;
            score += 0.15 * gap_after_next;
        } else {
            // next item won't fit after placement: mild penalty for wasting residual
            score += 4.0;
        }
    }

    // Penalize creating small unusable dead space (< 10, minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Compare against mean residual: bins with less residual than mean are more precious
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: only bin that fits the item
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; discourage unless
    // the current bin would leave a large unusable residual or the fit is terrible
    if bin_residual == bin_capacity {
        // empty new bin: base high score so it's only chosen when fits are bad
        score += 45.0;
        // allow new bin when item is large relative to capacity (would leave little room anyway)
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.8 {
            score -= 20.0;
        }
        // early stream: fewer open bins, prefer opening to keep flexibility
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += 8.0 * (bin_residual == bin_capacity) as i32 as f64;
    }

    // Slight preference for bins with larger residual among comparable fits
    score -= 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual that is small but nonzero less than large waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Penalize dead space that is too small for the smallest plausible item.
        if post_residual < 10 {
            score += 40.0;
        }
        // If lookahead item can still fit in post_residual, reward leaving room.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        } else if next_item_size > 0 {
            score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    // and many bins are already open with high mean residual.
    if bin_residual == bin_capacity {
        let bad_fit = fit_ratio < 0.5;
        let crowded = open_bins_count as f64 * mean_residual > bin_capacity as f64 * 1.5;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if bad_fit && crowded {
            score -= 20.0 + 30.0 * progress;
        } else {
            score += 80.0;
        }
    }

    // Mild preference to fill bins with lower residual (consolidate waste).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Time horizon: early in stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        + 60.0 * norm_pr * norm_pr * norm_pr;

    // Progress coupling: early on, tolerate residual; late, punish it harder
    let progress_penalty = progress * (1.0 + 2.0 * progress) * norm_pr * cap * 0.5;
    score += progress_penalty;

    // Reward tight fits (post_residual near zero) via smooth term
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward (smooth)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_factor = 1.0 - ((pr - nx).abs() / cap);
        score -= 25.0 * match_factor.max(0.0) * match_factor.max(0.0);
        // Penalize leaving residual that neither helps nor matches
        score += 8.0 * norm_pr * (1.0 - match_factor.max(0.0));
    }

    // Mean residual context: placing into a bin below-average residual is good
    score -= (mean_residual - pr) * 0.3;

    // Slight penalty for proliferating bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 pair well
    // with a size grid that includes multiples of 10; odd/prime-like residuals
    // are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let harmonic = (post_residual % 10) as f64;
    score += harmonic * 1.7;

    // Integer-division thresholds: reward residuals in "usable" bands.
    let band = post_residual / 25; // 0..=4
    match band {
        0 => score += 25.0,                    // tiny leftover: near-perfect fill
        1 => score -= 6.0,                     // 25..49: good mid band
        2 => score -= 12.0,                    // 50..74: still useful
        3 => score += 4.0,                     // 75..99: wasteful for small items
        _ => {}                                // full empty bin handled below
    }

    // Empty new-bin candidate: penalize opening a new bin unless the item is
    // large or nothing else fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.35 * (open_bins_count as f64);
        if item_size >= 60 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid bin proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead coupling: if next item fits into the post-residual exactly or
    // near-exactly, reward heavily (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 10.0 - 0.4 * (gap as f64);
        if post_residual % next_item_size == 0 {
            score -= 8.0; // harmonic divisibility bonus
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // next item won't chain here
    }

    // Stream progression: early on, be greedy about fill quality; late in the
    // stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (1.0 - pr / cap);

    // Mean-residual coupling: if this bin is far below the mean residual,
    // it is a good "garbage absorber".
    if (mean_residual - pr) > 10.0 {
        score -= 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A post_residual that cannot fit even the smallest plausible item (1..=100)
    // is pure waste; the smaller the gap below the next item, the worse.
    if post_residual < next_item_size && next_item_size > 0 {
        score += 60.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }
    if post_residual < 10 {
        score += 25.0; // tiny dead gap, almost certainly unusable
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to bin).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: discourage scattering across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 1.4 * progress);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: only attractive when it enables a much better future fit
    // (next item exactly fills a fresh bin) or current bin leaves bad dead space.
    if bin_residual == bin_capacity {
        let fresh_bonus = if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64).abs() < 5.0 {
            35.0
        } else {
            0.0
        };
        score += 15.0 * (1.0 - progress) - fresh_bonus;
    }

    // Prefer bins whose residual is already below mean (consolidating waste).
    score += (mean_residual - post_residual as f64).max(-50.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), scaled by capacity.
    score += 0.05 * (bin_capacity as f64 - post_residual as f64).abs() * 0.0; // neutral filler

    // Reward when the next item exactly fills the post residual (perfect 2-step chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to leftover after that (2-step lookahead).
            let second_left = post_residual - next_item_size;
            score -= 40.0 - 0.4 * second_left as f64;
        } else {
            // Next item does not fit: penalize dead space created.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.3 * dead;
        }
    } else {
        // Last item: minimize post residual strongly.
        score += 0.5 * post_residual as f64;
    }

    // Relative to mean residual: bins below mean residual are more "loaded"; prefer filling them.
    let rel = post_residual as f64 - mean_residual;
    score += 0.25 * rel;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists (high dead space elsewhere)
    // or stream is early. Penalize opening a new bin generally.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin supports the lookahead chain
        }
    }

    // Late in the stream, consolidate: discourage spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Small exact-fit bonus relative to item size.
    if post_residual < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, with non-linear penalty on dead space.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes residual space.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, scaled by how much space would be left idle
        // in existing bins and by stream progress (waste less late in the stream).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = mean_residual.max(0.0);
        score += 40.0 + 20.0 * (1.0 - progress) + 0.15 * waste;
        // If next item is large, a fresh bin is somewhat more attractive.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    } else {
        // Reward bins whose residual could still host the next item after this placement.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 8.0;
            } else {
                score += 4.0;
            }
        }
        // Mild preference for bins below mean residual (consolidate emptier bins).
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Global pressure: with many open bins, prefer filling existing ones.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Small exact-fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr_n = pr / cap;

    // Base: prefer tight fits (low post residual), with convex penalty growth
    let mut score = pr * (1.0 + 0.5 * pr_n * pr_n);

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate slack (favor spreading); late, demand tightness
    let early_bias = (1.0 - progress) * (1.0 - progress);
    score += 8.0 * early_bias * pr_n;

    // Dead-space penalty: residuals too small for any plausible item
    let dead = if pr < 10.0 { (10.0 - pr) * (10.0 - pr) } else { 0.0 };
    score += 0.05 * dead;

    // Lookahead: reward leaving space for the next item
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (pr - nxt) / cap;
        if gap >= 0.0 {
            score -= 6.0 * gap * (1.0 - gap);
        } else {
            score += 4.0 * (-gap);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins below mean residual (keeps open bins balanced)
    score += 1.5 * (mean_residual - pr) / cap;

    // Mild pressure to close bins when many are open
    score += (open_bins_count as f64).ln() * pr_n * 0.5;

    // New-bin candidate: penalize opening a fresh bin unless item is large
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Residuals in "useful" classes (large enough to
    // plausibly host future items) get a reward (subtracted); tiny dead-space
    // classes get penalized (added).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Integer-division thresholds on post_residual: quarter classes.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth.max(1); // harmonic class index 0..8

    match class {
        0 => {
            // Post-residual < 1/8 capacity: near-perfect fill.
            score -= 12.0;
            // Extra reward for exact or near-exact fill.
            if post_residual == 0 { score -= 25.0; }
        }
        1 => {
            // 1/8..2/8: small leftover; check if next item fits (modulo-style
            // pairing: does next_item_size divide into post_residual class?).
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 15.0; // chainable: next item slots in
            } else if next_item_size > 0 {
                score += 8.0; // dead space relative to lookahead
            }
        }
        2 | 3 => {
            // 2/8..4/8: mid-range leftover, generally reusable.
            score -= 5.0;
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 10.0;
            }
        }
        4 | 5 => {
            // Half-ish bin still open: fine, mildly prefer.
            score -= 3.0;
        }
        _ => {
            // > 5/8 capacity left: item was small relative to bin; neutral,
            // but new-bin candidate (full residual) should not win when a fit exists.
            score += 0.0;
        }
    }

    // Perfect-fit modulo check: item divides residual evenly (harmonic fit).
    if bin_residual > 0 && (bin_residual % item_size.max(1)) == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post-residual would be unusable dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual == 0 {
            score -= 40.0;
        } else if post_residual < eighth {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // gives a decent fit. Penalize the empty-bin candidate progressively.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with reasonable fits beat it.
        score += 30.0;
        // If many bins are open and mean residual is large, opening new bins is wasteful.
        score += 0.4 * open_bins_count as f64;
        score += (mean_residual / cap).clamp(0.0, 1.0) * 20.0;
        // Late in the stream, avoid opening bins (waste at the end).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
        // Exception: if the item is huge and next item is also huge, a fresh bin
        // may be preferable; relax penalty slightly.
        if item_size >= quarter * 3 && next_item_size >= quarter * 3 {
            score -= 35.0;
        }
        // If no other bin can chain the next item and this bin's post-residual
        // would be dead space, allow new bin to compete more.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < eighth {
            score -= 12.0;
        }
    }

    // Mild preference for keeping bins balanced: bins with residual far above
    // mean residual are good targets (absorb space where there's plenty).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 4.0 * dev.clamp(-1.0, 1.0);

    // Small tie-breaker favoring larger items into fuller bins (best-fit bias).
    score += 0.02 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for anything
    // (below the minimum plausible item size ~10, with margin) are pure waste.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        // Perfect fit region: reward heavily, scaled by how dead the space would be.
        score -= (dead_threshold - post_residual as f64) * 6.0;
    } else {
        // Usable leftover: mild penalty proportional to waste, but reward leaving
        // space exactly matching the next item (lookahead coupling).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 15.0;
        }
        // Penalize leftovers that are dead for the NEXT item too (nonlinear).
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        }
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.15 + 0.35 * progress);

    // Mean-residual coupling: if the fleet average residual is low, conserve
    // remaining space; if high, be more permissive about spreading items.
    score += (mean_residual - post_residual as f64) * 0.25;

    // New-bin candidate: make it attractive only when the fit into open bins is bad.
    if bin_residual == bin_capacity {
        // Base handicap so new bins only win on genuinely poor fits.
        score += 30.0;
        // But if the current item is large relative to mean residual, opening
        // a fresh bin is reasonable.
        if (item_size as f64) > mean_residual * 0.9 {
            score -= 20.0;
        }
        // Late in the stream, avoid spawning extra bins unless necessary.
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: quadratic bonus for small post_residual.
    let pr = post_residual as f64;
    score -= 30.0 * (1.0 - pr / bin_capacity as f64).powi(3);

    // Exact fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Next item fits: good, but leave some residual quality.
            let two_step_post = post_residual - next_item_size;
            score -= 20.0 * (1.0 - two_step_post as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize small dead space that
            // neither this nor the next item can use.
            let waste = pr.min(next_item_size as f64 - pr);
            score += 0.6 * waste;
        }
    }

    // Relative to mean residual: prefer bins that are already partially
    // filled (below-mean residual means tighter bin, good for tight packing).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.3 * diff;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless open bins
    // would create large dead space. Base penalty scaled by stream progress.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = open_bins_count as f64;
        score += 40.0 + 20.0 * (1.0 - progress) + 2.0 * open_pressure;
        // Allow opening a new bin when mean residual is very small (bins nearly full)
        // and this item doesn't fit well anywhere.
        if mean_residual < item_size as f64 * 0.5 && fitting_bins_count <= 1 {
            score -= 70.0;
        }
    }

    // Mild penalty for leaving residuals in the awkward 1..=9 dead zone.
    if post_residual >= 1 && post_residual <= 9 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize high post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness;

    // Reward perfect fill.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: residual too small to fit the smallest plausible item (1..100 unknown, use small threshold).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement wastes space the next item could have used
            score += 6.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are fragmented or the item is large.
    let is_new_bin = bin_residual == bin_capacity && bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize opening new bins mildly when open bins have plenty of room.
        score += 20.0;
        score -= 15.0 * (1.0 - fragmentation);
        // Late in the stream, prefer consolidating into existing bins.
        score += 10.0 * progress;
        // Large items are fine in a fresh bin.
        if item_size >= 50 {
            score -= 10.0;
        }
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight bonus for using already-open bins when many are open (avoid bin explosion).
    score += 0.02 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear coupling: dead space penalized super-linearly as stream progresses
    let prn = pr / cap;
    score += 40.0 * prn * prn * (0.5 + progress);

    // Reward tight fits (post_residual near zero) more strongly later in stream
    score -= 25.0 * (1.0 - prn) * (1.0 - prn) * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            score += 6.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // New-bin candidate: penalize mildly, less so early when few bins are open
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress - (open_bins_count as f64).sqrt();
    }

    // Pull toward mean residual to balance bins
    score += 0.15 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    // Class 0: post_residual is a "nice" residual (multiple of 25 or 10) -> reward
    let pr = post_residual;
    let nice25 = (pr % 25 == 0) as i32;
    let nice10 = (pr % 10 == 0) as i32;
    let class_penalty = match (nice25, nice10) {
        (1, _) => -6.0,
        (_, 1) => -2.0,
        _ => 0.0,
    };
    score += class_penalty as f64;

    // Integer-division thresholds on post_residual: dead space zones
    if post_residual <= 10 {
        score -= 12.0; // near-perfect fill
    } else if post_residual <= 20 {
        score -= 4.0;
    } else if post_residual > 50 {
        score += 8.0 * frac; // large leftover: wasteful
    }

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic class of the leftover gap after next item
            let gap = post_residual - next_item_size;
            let gap_frac = gap as f64 / cap;
            score -= 8.0 * (1.0 - gap_frac);
            if gap == 0 {
                score -= 15.0;
            }
            if gap % 10 == 0 && gap > 0 {
                score -= 3.0;
            }
        } else {
            // next item won't fit: penalize leaving awkward mid-range residual
            score += 4.0 + 6.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate (empty bin): penalize mildly so it's chosen only
    // when all open bins are poor fits (their scores already carry penalties)
    if bin_residual == bin_capacity {
        score += 18.0 + 0.15 * open_bins_count as f64;
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * frac * 3.0;

    // Mean residual coupling: if this bin is far from mean, small correction
    score += 0.05 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for even the smallest item (1..10)
    // are pure waste; penalize extra hard when the gap is tiny but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    }

    // Tight-fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 25.0;

    // Prefer bins whose residual is close to item size (small slack ratio).
    let slack = post_residual as f64 / bin_capacity as f64;
    score += slack * 15.0;

    // Open-bin pressure: with many open bins, discourage opening new ones,
    // favor consolidating into existing bins.
    score += open_bins_count as f64 * 2.5;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else (large residual mismatch) or when
    // the next item is large and this bin's post-residual can't hold it.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 * 0.85 + open_bins_count as f64 * 2.0;
        let mut nb = base;
        // If the next item could use the leftover space of an existing bin,
        // opening a new bin is less attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            nb += 30.0;
        }
        // Late in the stream, be more conservative about new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        nb += progress * 20.0;
        score = score.max(nb);
    }

    // Lookahead: if placing here leaves space exactly (or nearly) matching the
    // next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    // Mean residual coupling: bins far below mean residual are already tight;
    // prefer filling tighter bins to consolidate waste.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: post residual close to 0.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let pr = post_residual as f64;
        // Penalize dead space that is too small for typical future items.
        if pr < 10.0 {
            score += 25.0;
        } else if pr <= 30.0 {
            score -= 10.0;
        }
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this placement is excellent (sets up a perfect follow-up).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 20.0 {
                score -= 20.0 - gap * 0.7;
            } else {
                score += gap * 0.25;
            }
        } else {
            // Next item won't fit after this placement: mild penalty scaled by overflow.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.15;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 40.0;
    }

    // Compare residual against mean residual of open bins: prefer bins that
    // are already partially filled relative to the average (consolidation).
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (resid_f - mean_residual) * 0.35;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Late in the stream, be more conservative: favor filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 12.0;

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed; late items favor tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward near-perfect fits (post residual close to zero).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful:
    // residual below the minimum plausible item size is nearly wasted.
    let min_item = 1.0f64;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < min_item + 9.0 {
        score += 25.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - progress);
        } else {
            // Next item won't fit here; mild penalty grows with progress.
            score += 8.0 * progress;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has a baseline score equal to
    // capacity; bias it slightly upward so only genuinely poor fits open bins.
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
    }

    // Reward using bins whose residual deviates above the mean (balance load),
    // and slightly prefer reducing the number of open bins.
    if open_bins_count > 0 {
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score -= 10.0 * dev;
        score += 2.0 * (open_bins_count as f64).ln();
    }

    // Mild pressure toward consolidation as the stream progresses.
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strong non-linear reward for tight fits: post_residual^2 normalized by capacity
    score -= (post * post) / cap;

    // Cubic coupling: extremely small residuals are gold; smooth, no piecewise constants
    let post_norm = post / cap;
    score -= post_norm * post_norm * post_norm * 30.0;

    // Stream-progress coupling: as the stream progresses, penalize loose fits more
    // (encourage consolidation late, allow slack early)
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += post_norm * (1.0 + progress_coupling) * 20.0;
    score -= progress * progress * 10.0;

    // Lookahead: reward if next item fits into the post residual (chaining)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - ((post - nxt) / cap);
            score -= snug * snug * 12.0;
        } else {
            // next item cannot follow: dead space risk, penalize proportionally
            score += (nxt - post) / cap * 8.0;
        }
    }

    // Last chance: this is the only fitting bin — strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 + progress * 15.0;
    }

    // Crowd effect: many open bins -> prefer consolidation into existing ones
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= open_norm * 6.0;

    // Mean residual context: if this bin's residual is far below mean, it's a good tight fit
    let mean_post = mean_residual - item_size as f64;
    if mean_residual > 0.0 {
        score += (post - mean_post) / cap * 5.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are bad fits
    if bin_residual == bin_capacity {
        // Base penalty so a fresh bin loses to decent fits
        score += 30.0;
        // But relax the penalty late in the stream or when many bins are open
        score -= progress * 10.0 + open_norm * 12.0;
        // If next item is large, a fresh bin has future value
        if next_item_size > 0 {
            score -= (next_item_size as f64 / cap) * 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets — small dead space classes are good.
    let pr = post_residual;
    let class = pr % 10;
    score -= match class {
        0 => 12.0,
        1 | 9 => 2.0,
        2 | 8 => 1.0,
        3 | 7 => -1.0,
        4 | 6 => -2.5,
        _ => -4.0,
    };

    // Integer-division thresholds on post_residual: reward "harmonic" residuals
    // that can host common item sizes (10..=100 in steps of 10).
    let harmonic_fit = (10..=100).step_by(10).filter(|&s| s <= pr).count() as f64;
    score -= harmonic_fit * 3.0;

    // Tight fit reward: post_residual small relative to capacity fraction.
    let frac = pr as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score -= 20.0;
    } else if frac < 0.25 {
        score -= 8.0;
    } else if frac > 0.7 {
        score += 10.0; // leaving a huge mostly-empty bin is wasteful
    }

    // Lookahead: does post_residual still fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // chainability bonus, stronger if next item is small (mod class)
            let nxt_class = next_item_size % 10;
            let bonus = 6.0 + (nxt_class as f64) * 0.3;
            score -= bonus;
            // perfect chain: post_residual exactly matches a harmonic size
            if pr == next_item_size {
                score -= 15.0;
            }
        } else {
            // creating dead space that next item cannot use
            score += 8.0 + (next_item_size - pr) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when all open bins are quite full
    // (low mean residual) or many bins already open (fragmentation).
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        score = 55.0 - mean_r * 0.5 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin useful for upcoming large item
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Progress coupling: late in the stream, be more frugal with open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Tight fit reward relative to capacity
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill;

    // Pressure from number of open bins: discourage spreading when many bins open
    score += 2.0 * open_bins_count as f64;

    // Encourage using bins with above-average residual (reduce fragmentation)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item fits into post_residual, bonus
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
    }

    // Late in the stream, be more conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress); // new bin cheaper early, costlier late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward (small dead space)
    if post_residual > 0 {
        let tightness = 10.0 / (post_residual as f64);
        score -= tightness * (post_residual as f64).min(10.0) * 0.5;
    }

    // 2-step lookahead: reward when next item exactly fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills remaining space
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 100.0 * fill;
        } else {
            // next item cannot use the leftover: penalize large unusable gaps
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    if bin_residual == bin_capacity {
        score += 50.0;
        if item_size >= 70 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 30.0; // fresh bin can host the pair nicely
        }
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual to strongly prefer near-exact fills.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: reward if the next item fits exactly into the post-residual,
    // penalize if post-residual is awkward relative to the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty if we leave a large dead gap
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin for a small item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or open bins are mostly full.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // New bins are more attractive when item is big, bins are nearly full,
        // or late in the stream with few items left.
        score += 30.0 - 25.0 * fill_ratio - 20.0 * (1.0 - pressure.min(1.0)) - 10.0 * progress;
    }

    // Global state: when many bins are open with high mean residual, discourage
    // leaving large gaps in low-residual bins (keep big bins for big items).
    if bin_residual != bin_capacity {
        let gap_vs_mean = mean_residual - bin_residual as f64;
        if gap_vs_mean > 0.0 {
            score += 0.5 * gap_vs_mean;
        } else {
            score += 0.2 * gap_vs_mean; // small reward for using below-average-residual bins
        }
    }

    // Time horizon: early in the stream, be slightly more conservative (favor
    // tight packing); late in the stream, just close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, with non-linear growth
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of residual with stream progress:
    // early on, tight packing matters less; later, waste is more costly
    score += norm_pr * (0.6 + 1.4 * progress * progress) * 2.0;

    // Interaction: post residual vs next item size (lookahead fit bonus)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = pr - nx;
        if fit_gap >= 0.0 {
            // smooth reward for leaving room for the next item
            score -= 3.0 * (fit_gap / cap).exp() * (1.0 - progress * 0.3);
        } else {
            // smooth penalty proportional to mismatch
            score += 0.02 * (-fit_gap) * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Many open bins: mildly favor filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 0.3;

    // Mean residual coupling: prefer bins deviating below mean residual (tighter)
    score += 0.5 * (mean_residual - pr).max(0.0) / cap;

    // New-bin candidate handling: empty bin gets a smooth handicap that
    // shrinks as stream progresses (late stream may prefer fresh bins)
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) + 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity fractions
    let frac = (post_residual as f64) / (bin_capacity as f64);
    // Penalize residuals in "dead" harmonic classes (tiny unusable slivers)
    if post_residual > 0 {
        if post_residual < 10 {
            score += 25.0; // dead space class
        } else if post_residual <= 20 {
            score += 8.0;
        } else if post_residual <= 30 {
            score += 3.0;
        } else if post_residual >= 50 {
            score -= 6.0; // large residual = reusable
        }
    }

    // Modulo-10 harmonic band reward: residuals divisible into coarse classes
    let band = post_residual % 10;
    if band == 0 {
        score -= 4.0;
    } else if band >= 8 {
        score += 2.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact next-item match is a harmonic jackpot
            if post_residual == next_item_size {
                score -= 30.0;
            } else {
                let slack = (post_residual - next_item_size) as f64;
                score -= 10.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            score += 5.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-high so it's
    // chosen only when open bins score badly (bad fits / dead space)
    if bin_residual == bin_capacity {
        score = 45.0
            - 0.5 * open_bins_count as f64
            - 10.0 * (1.0 - frac)
            + if next_item_size > 0 && next_item_size >= 70 { -5.0 } else { 0.0 };
        // Late in stream, prefer consolidating into open bins
        score += 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild pressure to spread load when many bins open
    score += 0.05 * (open_bins_count as f64) * (1.0 - frac);

    // Mean-residual coupling: prefer bins below mean residual (tighter packing)
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest item (1) are fine,
    // but small nonzero gaps that likely can't fit future items are dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if post_residual > 0 {
        // Dead-space penalty grows sharply for tiny unusable gaps.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 8.0;
        } else if post_residual < 20 {
            score += (20 - post_residual) as f64 * 3.0;
        }
        // Perfect fit bonus.
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Reward fitting the next item too (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item exactly consumes the remaining gap.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item: penalize proportionally to how close it is.
        let waste = next_item_size as f64 - post_residual as f64;
        if waste < 10.0 {
            score += waste * 4.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0 + 20.0 * progress;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    // and mean residual is healthy; encourage consolidation early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + open_bins_count as f64 * 2.5;
        // Allow new bin if mean residual across open bins is low (all crowded).
        if mean_residual < item_size as f64 * 0.5 && open_bins_count > 0 {
            score -= 45.0;
        }
        // Late in the stream, prefer tightening existing bins.
        score += progress * 15.0;
    } else {
        // Favor bins whose residual is close to the item (tight fit).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 10.0;
        // Slight preference for bins below mean residual (use up emptier bins? no:
        // keep emptier bins flexible -> penalize picking emptier-than-mean bins less).
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (item exactly fills the bin).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly matches
    // the post-residual (perfect chain match).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let pr = post_residual as f64;
        if next_item_size == post_residual {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to tightness
            let tightness = 1.0 - (pr - ni) / bin_capacity as f64;
            score -= 50.0 * tightness;
        } else {
            // next item cannot fit here: penalize the unusable gap,
            // worse the smaller the gap (dead space).
            let gap = ni - pr;
            score += 30.0 + 2.0 * gap as f64;
        }
    }

    // Penalize leaving residual far below mean residual (fragmented bin).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.5 * dev;
    } else {
        score += 0.1 * dev; // slight reward for above-average residual bins
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New empty bin candidate: base cost high, but cheaper late in the
    // stream and when many bins are already open (amortization).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 400.0 - 150.0 * progress - 5.0 * open_bins_count as f64;
        // If no existing bin fits, opening a new bin is the only option;
        // make it clearly preferable to a bad-fit placement.
        if fitting_bins_count == 0 {
            score -= 600.0;
        }
        // If next item is huge, a fresh bin is attractive.
        if next_item_size > 60 {
            score -= 50.0;
        }
    }

    // Small tie-break toward tighter residual bins.
    score += 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly prefer bins where the item nearly fills the residual.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 35.0 * (1.0 - tightness);
    } else if post_residual <= 20 {
        score -= 12.0 * (1.0 - tightness);
    }

    // Lookahead coupling: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let nxt_waste = (post_residual - next_item_size) as f64;
            score -= 20.0 * (-nxt_waste / 25.0).exp();
        } else {
            // Next item won't fit here; penalize large dead space left behind.
            score += 0.15 * (post_residual as f64);
        }
    }

    // Last-chance pressure: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when existing bins would leave big waste
    // or when few bins fit the item (fragmented state).
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { open_bins_count as f64 } else { 1.0 };
        let waste_if_used = fitting_bins_count as f64;
        score += 25.0; // base cost of consuming a fresh bin
        score -= 18.0 / open_pressure; // slightly cheaper when many bins already open
        score += 8.0 / (1.0 + waste_if_used); // expensive when alternatives are scarce
        // If lookahead item is small, a fresh bin is more flexible.
        if next_item_size > 0 && next_item_size < post_residual {
            score -= 5.0;
        }
    }

    // Dead-space penalty scaled by stream horizon: early on, be greedy about tight fits;
    // later, protect against accumulating many tiny residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.10 * post_residual as f64 * (0.5 + 0.5 * progress);

    // Global fragmentation: when mean residual is low (bins nearly full), reward tight fits more.
    if mean_residual > 0.0 {
        let frag = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
        score -= 10.0 * frag * (1.0 - tightness);
    }

    // Mild preference to balance open bin count: too many open bins with big residuals is bad.
    if open_bins_count > 3 {
        score += 0.02 * (open_bins_count as f64 - 3.0) * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear coupling: post_residual quadratic term modulated by stream progress.
    // Early in the stream, waste is cheap (favor tight packing less aggressively);
    // late in the stream, dead space becomes costly.
    let waste_weight = 0.5 + 2.0 * progress * progress;
    score += waste_weight * norm_pr * norm_pr * cap;

    // Reward near-perfect fits with a smooth cubic bonus.
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead coupling: penalize residuals that can't hold the next item,
    // reward residuals that snugly fit it (smooth kernel instead of hard cutoff).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = pr - ns;
        if gap < 0.0 {
            // next item cannot use this residual: penalize proportionally to miss
            score += 3.0 * (-gap / cap) * (1.0 + progress);
        } else {
            // smooth reward peaking when gap == 0
            score -= 5.0 * (-gap / 25.0) * (-gap / 25.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Prefer bins below mean residual (tighter bins) with smooth interaction.
    score += 0.05 * (pr - mean_residual);

    // Slight preference to spread load across open bins early on.
    score -= (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows super-linearly for tiny residuals.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 12.0;
        }
        // Modulo classes: residuals divisible by common item sizes are reusable.
        let pr = post_residual;
        if pr % 10 == 0 { score -= 25.0; }
        else if pr % 5 == 0 { score -= 10.0; }
        else { score += 8.0; }
        // Harmonic quartile of capacity.
        let quarter = bin_capacity / 4;
        if pr >= 3 * quarter { score -= 15.0; }
        else if pr >= 2 * quarter { score -= 5.0; }
        else if pr >= quarter { score += 5.0; }
        else { score += 20.0; }
    }

    // Lookahead coupling: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            score -= (nxt_post as f64).min(60.0) * 1.5;
            if nxt_post % 10 == 0 { score -= 15.0; }
        } else {
            // Next item won't fit here; mild penalty for stranding space.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 30.0;
        if open_bins_count == 0 { score -= 500.0; }
        if mean_residual < 20.0 { score -= 120.0; }
        if post_residual == bin_capacity { score += 0.0; }
    }

    // Prefer tighter bins overall (below mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Stream progression: near the end, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // A residual is "dead" if it's too small to be useful for typical items.
        let dead_threshold = 10.0;
        if (post_residual as f64) < dead_threshold {
            score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating into fewer bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit in leftover: leftover may become dead space.
        score += 8.0;
    }

    // Mean residual coupling: placing into a bin whose residual is near the mean
    // keeps the bin pool balanced; prefer bins with residual close to item size.
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * residual_gap;

    // Slight preference for new empty bin early vs late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin: penalize more when many bins are open (discourage sprawl),
        // but allow it when progress is late and fits are poor.
        score += 20.0 + 1.5 * open_bins_count as f64 - 10.0 * progress;
    }

    // Penalize leaving residual near the awkward mid-range (e.g. 11..30) which is hard to fill.
    if post_residual >= 11 && post_residual <= 30 {
        score += 10.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Tight 2-chain: next item nearly fills the bin afterwards.
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            // Exact chain match bonus.
            if slack == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot use this bin's remainder: penalize leftover dead space.
            let dead = post_residual as f64;
            score += 0.35 * dead;
            // Extra penalty if next item could have fit BEFORE placing here.
            if bin_residual >= next_item_size {
                score += 8.0;
            }
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare post_residual against mean residual across open bins.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 6.0 * (0.5 - rel); // below-average leftover: good compaction
        } else {
            score += 3.0 * (rel - 0.5); // above-average leftover: fragmenting
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - post_residual as f64; // == item_size
        score += 15.0 + 0.25 * waste;
        // But allow a new bin if it enables a perfect 2-chain and existing fits are poor.
        if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 2 {
            score -= 22.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Mild preference to keep the number of open bins low.
    score += 0.05 * open_bins_count as f64;

    // Small tie-breaker: prefer bins with less residual before placement (tighter history).
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving little waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Dead-space penalty for large post-residuals that few items can use.
    if post_residual > 0 {
        score += 0.15 * (post_residual as f64).powf(1.3);
    }

    // Lookahead: reward if the next item fits exactly / well in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * next_fit;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving residual that next item can't use at all.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded / residuals small.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let crowding = mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 - 30.0 * crowding - 10.0 * (1.0 - progress);
        // Never open a new bin when a perfect-ish fit exists elsewhere.
        if fit_ratio > 0.8 && !is_new {
            score += 100.0;
        }
    }

    // Mild preference for consolidating many bins into fewer.
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0);

    // Slight time-decay on waste tolerance: late in stream, pack tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.96;
