pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction buckets (1/8 granularity)
    let frac = (item_size as f64) / (bin_capacity as f64);
    let hclass = (frac * 8.0).floor() as i64; // 0..8

    // Post-residual harmonic class: integer-division thresholds
    let pr = post_residual;
    let pr_class = pr / 10; // 0..10

    // Reward tight fits strongly
    if pr == 0 {
        score -= 1000.0;
    } else if pr <= 5 {
        score -= 300.0;
    } else if pr <= 10 {
        score -= 150.0;
    } else if pr <= 20 {
        score -= 40.0;
    }

    // Dead-space penalty: post_residual too small for the smallest possible next item
    if pr > 0 && pr < 10 {
        score += 250.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size < pr {
            score -= 30.0 * (1.0 - (pr - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leftover proportionally
            score += 0.5 * pr as f64;
        }
        // Harmonic pairing: next_item_size class complements item class to fill capacity
        let nfrac = (next_item_size as f64) / (bin_capacity as f64);
        let nclass = (nfrac * 8.0).floor() as i64;
        let pair = hclass + nclass;
        if pair == 8 { score -= 120.0; }          // perfect harmonic pair
        else if pair == 7 { score -= 60.0; }      // near pair
        else if pair > 8 { score += 80.0; }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fit: mild dispersion pressure
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin gets neutral baseline unless open bins are congested
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin: capacity worth of potential
        score = 100.0 + 0.3 * mean_residual;
        // early stream: opening bins cheap; late stream: prefer consolidating
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 60.0 * progress;
        // if many open bins with large residuals, discourage new bin
        score += 0.5 * open_bins_count as f64;
        // if item is huge and mean residual small, new bin is fine
        if frac > 0.7 && mean_residual < 40.0 { score -= 80.0; }
    }

    // Mean-residual context: if this bin is far below mean residual, it's a good filler
    score += 0.2 * ((mean_residual - bin_residual as f64).abs());

    // Modulo-based dead-space shaping on post_residual: penalize residuals in awkward bands
    let m = pr % 10;
    if pr > 0 && pr < 25 && m >= 1 && m <= 4 {
        score += 20.0 * (5 - m) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 0.8 * (item_size as f64 / bin_residual.max(1) as f64) * 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: penalize placements that spread across many bins mildly,
    // but reward using existing bins when many are open.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high unless residuals are poor.
    if bin_residual == bin_capacity {
        score += 6.0;
        // Open a new bin if existing residuals are mostly dead space.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 20.0;
        }
    }

    // Lookahead: if next item could use the post_residual, soften the penalty.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Late-stream tightening: prefer consolidation as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: post_residual near zero is best.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Exact-fit bonus (item fills the bin completely).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (-gap / 15.0).exp();
        // Exact chain match: post_residual == next_item_size.
        if post_residual == next_item_size {
            score -= 35.0;
        }
        // Penalize leaving a residual that is too small for the next item
        // (dead space relative to lookahead).
        if post_residual < next_item_size && post_residual > 0 {
            score += 20.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: strongly prefer near-zero post_residual.
        score += 30.0 * tightness;
    }

    // Relative to mean residual: prefer bins that are more filled than average
    // (placing into already-low-residual bins concentrates packing).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // is large relative to capacity (poor fit elsewhere would waste space).
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / bin_capacity as f64;
        // Large items justify a new bin; small items should go into open bins.
        score = 60.0 + 60.0 * (1.0 - size_ratio);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // new bin will serve the next item too
        }
    }

    // Mild stream-progression effect: early on, be slightly more willing
    // to consolidate (fewer open bins preferred later).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;

    // Penalize residuals that are too small to be useful later (dead space),
    // with a non-linear "usability valley": residuals below ~10 are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Lookahead coupling: reward if the next item fits the post-residual,
    // penalize if post-residual is just barely too small for the next item.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 12.0;
        } else if next_item_size <= bin_capacity && post_residual > 0 {
            let miss = (next_item_size as f64 - post_residual as f64).min(bin_capacity as f64);
            score += miss * 0.35;
        }
        // Reward chain fits: this bin + next item both tight
        if next_item_size <= post_residual && post_residual - next_item_size < 10 {
            score -= 8.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Mild penalty for the fresh-bin candidate so we prefer filling existing bins,
    // but relax it as the stream progresses and open bins get fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 55.0 - 25.0 * fragmentation - 10.0 * progress;
    }

    // Prefer bins whose residual deviates below the mean (more filled bins),
    // encouraging consolidation into partially filled bins.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight preference for fewer open bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual, scaled smoothly by stream progress.
    let mut score = post * (1.0 + 0.5 * progress);

    // Smooth polynomial coupling: reward tight fits (post_residual near 0)
    // using a normalized quadratic bowl, stronger later in the stream.
    let tight = 1.0 - (post / cap).min(1.0);
    score -= 30.0 * tight * tight * (0.5 + progress);

    // Penalize leaving residuals that are awkward relative to the next item:
    // if the next item cannot use the leftover space, penalize smoothly.
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (next - post).max(0.0);
        score += 0.4 * gap * (1.0 - tight);
        // Reward when next item fits exactly into the post-residual.
        let fit_next = 1.0 - (post - next).abs() / cap;
        score -= 8.0 * fit_next.max(0.0) * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate (empty bin): penalize mildly so we prefer filling
    // existing bins, but relax the penalty when residuals are fragmented
    // (high mean residual spread / many bins with poor fit).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).max(0.0);
        score += 20.0 - 15.0 * fragmentation * (0.5 + progress);
        if next > 0.0 && next > post {
            score += 0.0; // empty bin trivially fits; handled by base score
        }
    }

    // Mild penalty proportional to open bins to discourage bin sprawl.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by small
    // moduli are more likely to be exactly filled by future items.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Reward "harmonic" residuals (multiples of 10, 5, 4, 2)
        if r % 10 == 0 { score -= 18.0; }
        else if r % 5 == 0 { score -= 9.0; }
        else if r % 4 == 0 { score -= 6.0; }
        else if r % 2 == 0 { score -= 3.0; }

        // Integer-division thresholds: small dead space is bad unless it
        // can pair with a tiny item.
        let q = r / 10; // decade class
        match q {
            0 => score += 22.0,          // 1..9: nearly unusable
            1 => score += 8.0,           // 10..19
            2 => score += 2.0,           // 20..29
            3 => score -= 4.0,           // 30..39
            4 => score -= 6.0,           // 40..49
            _ => score -= 2.0,           // large residuals fine
        }

        // Coupling with lookahead: if next item fits exactly in the
        // post residual, strongly reward.
        if next_item_size > 0 {
            if next_item_size == r { score -= 35.0; }
            else if next_item_size < r {
                let nxt_post = r - next_item_size;
                if nxt_post % 10 == 0 { score -= 12.0; }
                else if nxt_post < 10 { score += 10.0; }
            } else {
                // next item can't use this bin's remainder anyway
                score += 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin for a decent fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins
    // unless their residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.15 * open_bins_count as f64;
    }

    // Waste relative to mean residual: bins with residual far below mean
    // are tighter, prefer them.
    score += 0.10 * (mean_residual - bin_residual as f64);

    // Stream progression: later in the stream, consolidate more eagerly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        let dead = (post / cap).powf(2.0);
        // Small gaps (< ~20% of capacity) are heavily penalized; large gaps mildly so.
        let small_gap_penalty = if post_residual < 20 { 60.0 } else if post_residual < 35 { 25.0 } else { 0.0 };
        score += 30.0 * dead + small_gap_penalty;
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Lookahead: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // Next item cannot use this gap: penalize leftover space further.
        score += 10.0 * post / cap;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: mildly prefer packing into existing bins when many are open.
    score -= (open_bins_count as f64) * 1.5;

    // Prefer bins tighter than the current mean residual (good compactness).
    score += (post - mean_residual) * 0.3;

    // New empty bin candidate: make it unattractive unless nothing else works.
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can still fit the next item: reward proportionally to tightness
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit in leftover: penalize dead space
        let gap = (next_item_size - post_residual) as f64;
        score += 12.0 * (gap / bin_capacity as f64).min(1.0);
    }

    // Reward small post_residual (tight packing) with a nonlinear curve
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4);

    // Penalize post_residual that is small but nonzero (unusable sliver)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Mild preference for keeping the number of open bins low
    score += 0.3 * open_bins_count as f64;

    // Slight progression-aware pressure to consolidate early
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual). Nonlinear waste penalty
    // grows superlinearly for small leftover slivers that are hard to reuse.
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 18.0 / pr.sqrt();
    } else {
        score -= 25.0; // perfect fit is excellent
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.25 * next_item_size as f64;
    }
    // Penalize leaving a sliver just below the next item (dead space trap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
    }

    // Time horizon: late in the stream, consolidate aggressively into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: when many bins are open, discourage opening new ones
    // (the empty-bin candidate has residual == capacity, so its high post_residual
    // plus this term keeps it low-priority unless the fit is truly terrible).
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        // Exception: very large items or near end of stream may justify a new bin.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        if progress > 0.9 {
            score -= 8.0;
        }
    }

    // Mean residual coupling: placing into a bin with residual far from the mean
    // helps rebalance residuals across open bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for filling fuller bins (low residual) overall.
    score += 0.08 * bin_residual as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, larger residuals are more acceptable (bins stay flexible);
    // later, we penalize residuals super-linearly to squeeze into tight fits.
    let t = progress.clamp(0.0, 1.0);
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep
    score += 8.0 * poly * (pr * pr) / cap;

    // Reward tight fits smoothly (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr / cap);
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - slack);
    } else if next_item_size > 0 {
        // next item won't fit here; mildly penalize leaving awkward gaps
        score += 4.0 * pr / cap;
    }

    // Prefer bins below mean residual (filling emptier bins keeps big residuals alive)
    score += 3.0 * (pr - mean_residual) / cap;

    // Many open bins: encourage consolidation into existing bins
    score += (open_bins_count as f64).ln().max(0.0) * pr * 0.05;

    // New empty bin candidate: penalize unless current bins are hopeless
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of capacity consumed by the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Harmonic classes on post_residual: small leftovers are good.
    // Class A: post_residual == 0 -> perfect bin, huge reward.
    if post_residual == 0 {
        score -= 500.0;
    }
    // Class B: post_residual below the minimum item size (<= 10) is dead space;
    // tolerate it only if it is exactly 0 (handled above), else penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    }
    // Class C: post_residual in the "awkward middle" (11..=30) is a classic
    // dead zone; penalize proportionally.
    if post_residual > 10 && post_residual <= 30 {
        score += 25.0 * (31.0 - post_residual as f64) / 20.0;
    }
    // Class D: post_residual in a harmonic-friendly band (multiples of common
    // item sizes 10,20,25,50) is reusable; reward it.
    let reusable = post_residual % 10 == 0 || post_residual % 25 == 0;
    if reusable && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item exactly fills post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual && post_residual - next_item_size <= 10 {
            score -= 80.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here: leftover becomes permanent dead space.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // into existing bins is poor. Give the empty bin a baseline cost that
    // scales with stream progress and existing bin count.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 70.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // If the item would leave a nicely reusable residual in an existing bin,
        // opening a new bin is definitely worse.
        if fit_ratio > 0.6 {
            score += 100.0;
        }
    }

    // Mild normalization against mean residual: prefer bins below average fill
    // gap (larger residual than mean) slightly, to balance load.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead space avoidance ---
    // Residuals that are too small to hold even the next item are "dead"
    // unless they are exactly 0 (perfect fit). Penalize small nonzero gaps.
    if post_residual > 0 {
        let min_useful = next_item_size.max(1) as f64;
        if (post_residual as f64) < min_useful {
            // Gap can never hold the lookahead item: strong dead-space penalty,
            // scaled by how close the gap is to being useless.
            let uselessness = 1.0 - (post_residual as f64) / min_useful;
            score += 40.0 * uselessness;
        }
        // Small gaps (even if next item fits) are fragile: mild penalty that
        // grows quadratically as the gap shrinks toward zero.
        let frag = (1.0 - (post_residual as f64) / bin_capacity as f64).powi(2);
        score += 10.0 * frag;
    } else {
        // Perfect fit: heavily reward closing the bin.
        score -= 60.0;
    }

    // --- Open-bins pressure: prefer reusing existing bins over spreading out ---
    // When many bins are open, discourage opening yet another one.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 6.0 * open_bins_count as f64;
        // Late in the stream, opening bins is even less attractive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // If other bins can fit, new bin is rarely justified.
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    } else {
        // Last-chance bin: if this is the only bin that fits, strongly favor
        // using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // --- Coupling with mean residual ---
    // If this bin's post placement leaves it far below the mean residual,
    // it means we consumed an unusually large chunk: reward consolidation.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.15 * mean_gap.max(0.0);
    // If the bin is far above mean residual after placement (still roomy),
    // slight penalty so roomier bins stay available for big items.
    score += 0.10 * (-mean_gap).max(0.0);

    // --- Lookahead awareness ---
    // If next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // Perfect fit for the next item is heavily rewarded.
        if post_residual == next_item_size {
            score -= 120.0;
        }
        // Penalize if post_residual is small but next item cannot fit anywhere else well.
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: minimize post residual directly (already done).
    }

    // Tight fit reward relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Compare against mean residual: prefer bins below mean residual (tighter bins).
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // Penalize new-bin opening unless current bins are nearly exhausted.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let avg_waste = mean_residual.max(0.0);
        // Open new bin if mean residual is large enough to accommodate future items poorly.
        if avg_waste > 25.0 && next_item_size > 0 && avg_waste < next_item_size as f64 {
            score -= 50.0; // opening new bin attractive when residuals can't fit next item
        } else {
            score += 70.0 + 30.0 * progress; // default: discourage new bins
        }
        // Early stream: keep bins open to pack densely.
        if progress < 0.3 {
            score += 40.0;
        }
    }

    // Dead-space penalty: very small unusable post residual.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: reward small post_residual non-linearly.
    let tightness = (bin_residual - post_residual) as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny slivers are fine only if truly tiny
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // awkward gap zone: hard to fill later
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // New-bin candidate handling: prefer existing bins unless current bin is badly fragmented.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        // Opening a new bin is penalized more when many bins are already open and fit exists.
        if fitting_bins_count > 0 {
            score += 20.0 + 2.0 * open_bins_count as f64;
        } else {
            score += 5.0; // forced open
        }
        // Early in stream, opening bins is cheaper (build diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Global state coupling: when mean residual is high, prefer bins above the mean
    // (drain the fullest usable bins first), keeping small residuals for small items.
    if mean_residual > 0.0 && !is_new_bin {
        let diff = bin_residual as f64 - mean_residual;
        score -= 0.05 * diff;
    }

    // Late-stream consolidation: as stream ends, squeeze remaining items into existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Discourage leaving residuals that exactly match nothing (odd gaps).
    if post_residual % 2 == 1 && post_residual < 30 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 8.0 * norm_pr * norm_pr * (0.5 + 2.0 * p2);
    score += 4.0 * norm_pr * p3 * (1.0 - progress);

    // Reward tight fits: subtract when post_residual is small relative to capacity.
    let tight = 1.0 - norm_pr;
    score -= 12.0 * tight * tight * tight;

    // Lookahead coupling: if next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        let gap = (pr - nx).abs();
        score -= fits_next * 10.0 * (1.0 - gap / cap);
        score += (1.0 - fits_next) * 3.0 * (nx / cap);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowd penalty: many open bins with large mean residual -> prefer filling existing bins.
    let crowd = (open_bins_count as f64).ln1p();
    score -= 2.0 * crowd * (mean_residual / cap) * (1.0 - norm_pr);

    // New-bin candidate: penalize opening a new bin unless current placements are poor.
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Base: strongly reward tight fits (small post_residual), convex penalty.
    score = score.powf(1.25) * 0.9;

    // Harmonic class of post_residual: bins whose leftover falls in "useful"
    // residue classes (multiples of 10/20) are more valuable later.
    let class10 = (post_residual % 10) as f64;
    let class25 = (post_residual % 25) as f64;
    score += class10 * 0.8 + class25 * 0.4;

    // Dead-space penalty: tiny unfillable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item still fits this bin afterwards,
    // reward the placement (keeps chains of items in the same bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 + slack * 0.15;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Bin becomes unusable for the known next item: mild penalty scaled
        // by how much space is wasted relative to the next item.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, use it rather
    // than opening a new one (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin, but less so for
    // large items where splitting waste across bins is cheap.
    if bin_residual == bin_capacity {
        score += 45.0 - item_size as f64 * 0.35 + mean_residual * 0.1;
        // Late in the stream, be more reluctant to open bins.
        score += t * 10.0;
    }

    // Congestion: many open bins -> prefer consolidating into existing ones.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Item size fraction: prefer placing large items into bins with
    // proportionally matching residual (harmonic capacity fraction match).
    let frac = item_size as f64 / bin_capacity as f64;
    let res_frac = bin_residual as f64 / bin_capacity as f64;
    score -= (1.0 - (frac - res_frac).abs()) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item (1) are pure waste, but small-but-usable gaps matter too.
    // Penalize small non-zero post_residuals superlinearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 3.0; // tiny unusable gap
        }
        // non-linear penalty on tight fits that leave awkward gaps
        score += 50.0 / (1.0 + pr);
    } else {
        // perfect fit: strong reward
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor filling
    let obp = open_bins_count as f64;
    score += obp * 1.5 * (post_residual as f64) / bin_capacity as f64;

    // Lookahead: if the next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size <= bin_capacity {
            // next item won't fit here; if post_residual is large enough to be
            // valuable for future items, mild penalty for wasting it now
            if post_residual > 50 {
                score += 10.0;
            }
        }
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier bins)
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Early stream: allow opening new bins more freely; late stream: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: prefer it late in stream or when item is large
        score = 60.0 - progress * 20.0 - (item_size as f64) * 0.2;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 15.0; // room for lookahead in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match of next item into post_residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how tight the leftover would be
            let left2 = post_residual - next_item_size;
            score -= 200.0 * (1.0 - left2 as f64 / bin_capacity as f64);
        } else {
            // next item does not fit here: penalize leftover dead space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer bins with residual below mean (tighter bins get priority)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins exist and item fits reasonably
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        score += 120.0;
        if waste < 20 {
            score -= 200.0; // new bin is fine if item nearly fills it
        }
        if open_bins_count > 0 && next_item_size > 0 && next_item_size <= item_size {
            score += 50.0; // discourage new bin if lookahead could pair with existing bins
        }
    }

    // Mild stream-progression pressure: consolidate more as stream advances
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * tightness * tightness;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: penalize leaving a residual that blocks the next item,
    // reward residuals that can exactly host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 20.0;
            } else {
                score += 0.35 * gap as f64;
            }
        } else {
            // Next item cannot fit here anyway; small residual is still fine.
            score -= 5.0;
        }
    }

    // Crowding: when many bins are open, prefer consolidation into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score -= 4.0 * crowd * (1.0 - progress);

    // Compare against mean residual: bins already loose are better targets.
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: only attractive when item is large relative to a fresh
    // bin or post_residual would be tiny dead space in every open bin.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; overcome it only for big items
        // or late in the stream when fragmentation is high.
        score += 15.0 + 0.5 * (bin_capacity - item_size) as f64;
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        if fitting_bins_count > 0 {
            score += 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: dead space hurts more as it grows
    score += 30.0 * norm_post * norm_post;

    // Tight fits rewarded, amplified by stream progress
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Dead space that could fit the next item is less harmful
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post >= ns {
            score -= 12.0 * (ns / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (ns - post) / cap;
        }
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0 * (0.3 + 0.7 * progress);
    }

    // Crowding pressure: many open bins -> prefer filling existing ones
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * crowd * norm_post;

    // Mean-residual coupling: penalize bins far from the fleet mean residual
    let dev = (mean_residual - post) / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate must be discouraged unless current bin is hopeless
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - 0.5 * progress) + 5.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual (decile buckets): reward near-perfect fills,
    // penalize mid-range residuals that are hard to pack later.
    let cls = post_residual / 10;
    score += match cls {
        0 => -18.0,                    // post_residual 0..9: excellent fit
        1 => -10.0,                    // 10..19: good
        2 => -4.0,                     // 20..29: acceptable
        3 => 2.0,                      // 30..39: mildly wasteful
        4 => 6.0,                      // 40..49
        5 => 9.0,                      // 50..59
        6 => 12.0,                     // 60..69
        7 => 15.0,                     // 70..79
        _ => 18.0,                     // 80..100: mostly empty, bad placement
    };

    // Exact modular harmony: post_residual that is an exact divisor-class match
    // with the lookahead item is gold (next item fills this bin perfectly).
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 20.0;             // perfect two-item harmony
        } else if post_residual % next_item_size.max(1) == 0 {
            score -= 8.0;              // divisible remainder chain
        } else {
            score -= 3.0;              // next item still fits
        }
    } else if next_item_size > 0 {
        // Lookahead item cannot use the leftover: dead space penalty scaled
        // by how much would be stranded.
        score += post_residual as f64 * 0.4;
    }

    // Last-chance bin: if this is the ONLY bin that can fit the item, strongly
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize by default so we keep using open
    // bins; relax the penalty when no open bin fits or the item is large.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 70.0;             // forced open
        }
        if item_size >= 60 {
            score -= 25.0;             // big items start fresh bins cheaply
        }
        if item_size >= 80 {
            score -= 15.0;             // near-full single-item bin is fine
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;             // room for lookahead pairing
        }
    }

    // Coupling with mean residual across open bins: prefer bins whose leftover
    // diverges from the mean (consolidate small leftovers into one bin).
    score += (mean_residual - post_residual as f64) * 0.08;

    // Mild pressure to keep many small leftovers alive when few bins are open.
    if open_bins_count > 4 {
        score += post_residual as f64 * 0.05;
    }

    // Stream progression: later in the stream, tighten tolerance on waste.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are nearly unusable
    // for future items -> heavy penalty proportional to how "trapped" the space is.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual <= 25 {
        // medium-risk gaps: mildly penalized
        score += 0.5 * (post_residual as f64 - 10.0);
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits generally: smaller post_residual relative to capacity is better.
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Pressure from number of open bins: when many bins are open, prefer
    // consolidating into existing bins; opening new bins becomes costly.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open,
        // and when a lookahead item could still use this bin's space.
        score += 25.0 + 3.0 * open_pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 10.0;
        }
    } else {
        // Existing bin: reward using it, scaled by open-bin pressure.
        score -= 2.0 * open_pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 15.0;
        }
    }

    // Late in the stream, avoid leaving many tiny open bins: favor fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Slight preference for bins below mean residual (balance residuals).
    score += 0.1 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact chain fits.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Penalize post-residual that doesn't match next item size.
        score += lookahead_gap * 0.5;

        // Strong reward if next item fits perfectly into the post-residual.
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to tightness.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * tightness;
        } else {
            // Next item won't fit: penalize wasted residual relative to mean.
            score += (post_residual as f64 - mean_residual).abs() * 0.3;
        }
    }

    // Penalize creating dead space far below the minimum plausible item size.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 60.0;
        // Discount slightly when many bins are open (bin proliferation already high)
        // and item is large (hard to place later).
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        if open_bins_count > 4 {
            score -= 5.0;
        }
    } else {
        // Reward filling existing bins tightly relative to mean residual.
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.2;
    }

    // Early in stream: slightly prefer keeping bins open for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fills get a strong discount.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Penalize small dead space nonlinearly (dead space < next item is less useful).
        let dead = post_residual as f64;
        score += (dead / 10.0).powi(2) * 0.6;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Extra reward when the next item exactly fills the remainder.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that blocks the next item: penalize proportionally.
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Global state coupling: many open bins with large mean residual suggests
    // fragmentation; prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= mean_residual * 0.05;
        score -= (open_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // New-bin candidate handling: an empty bin is only attractive when the item
    // fits poorly everywhere else or open bins are nearly full.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // Base penalty for opening a new bin.
        score += 10.0 + progress * 5.0;
        // But if the item is huge relative to capacity, opening fresh may be best.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 14.0;
        }
        // If mean residual across open bins is small, existing bins are crowded;
        // new bin becomes more attractive.
        if mean_residual < item_size as f64 {
            score -= 8.0;
        }
        let _ = fit_quality;
    }

    // Mild time-decay: late in the stream, avoid leaving awkward residuals.
    score += progress * (post_residual as f64 % 7.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tight fits rewarded: penalize large residuals non-linearly
    score += 0.35 * (pr * pr) / cap;

    // Stream progress coupling: early on, tolerate loose fits; later, demand tightness
    let tightness = 1.0 - (pr / cap);
    score -= 18.0 * progress * tightness * tightness;
    score += 6.0 * (1.0 - progress) * tightness;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: mildly discouraged unless it's genuinely better
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    // Lookahead: prefer residuals that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 4.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Mean residual coupling: bins far below mean residual are wasteful
    score += 0.10 * (mean_residual - pr).abs();

    // Many open bins: prefer filling existing ones
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Reward near-perfect fits strongly (waste minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 500.0;
    } else if frac <= 0.05 {
        score -= 200.0;
    } else if frac <= 0.15 {
        score -= 80.0;
    }

    // Penalize leftovers in "dead zones": residues that few item sizes can use
    // Items are 1..100; a residual r is usable if some future item <= r exists.
    // Small residuals (<10) are nearly dead; mid residuals are fine.
    if post_residual < 10 && post_residual > 0 {
        score += 150.0;
    }

    // Modulo arithmetic on post_residual: harmonics with common item sizes
    let r = post_residual;
    if r % 10 == 0 && r > 0 {
        score -= 30.0; // residue divisible by 10 matches many item classes
    }
    if r % 5 == 0 && r > 0 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; slightly penalize large leftovers
            score += 0.2 * (next_item_size as f64 - pr).min(50.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: baseline cost of opening a fresh bin
    if bin_residual == bin_capacity {
        score += 60.0 + 2.0 * open_bins_count as f64;
        // but if item is large and nothing fits well elsewhere, this stays competitive
        if item_size >= 60 {
            score -= 40.0;
        }
    }

    // Prefer bins with below-mean residual (tighter packing bins)
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Early stream: be more conservative about fragmenting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (>=10)
    // can ever use are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small but usable gaps are risky too (hard to fill exactly).
    if post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (perfect fill is ideal).
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 25.0 * tightness * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement is excellent.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // existing fits are poor (high mean residual spread) or few bins fit.
    if bin_residual == bin_capacity {
        let base_new = 55.0;
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            base_new + 20.0 * (mean_residual / bin_capacity as f64) + 15.0 * (fitting_bins_count as f64).ln().max(0.0)
        };
        score = pressure + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (minimize wasted space)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when post_residual can host next item exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - gap / (bin_capacity as f64));
        // Perfect chain: post_residual == next_item_size
        if gap == 0.0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize leaving dead space the next item cannot use
        score += 5.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
    }

    // Compare against mean residual: prefer bins with residual below mean (denser bins)
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 4.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize slightly so we only open when fits are truly bad,
    // but relax as stream progresses / many bins open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = (post_residual as f64) > 40.0 && next_item_size > 0 && post_residual < next_item_size;
        let pressure = (open_bins_count as f64) / (20.0 + 20.0 * progress);
        if bad_fit {
            score -= 15.0 + pressure; // opening new bin is attractive
        } else {
            score += 10.0 + 5.0 * (1.0 - pressure.min(1.0));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount small post-residuals (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead coupling: if the next item can use this bin's post-residual, reward it.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) >= nr {
            // next item fits exactly-ish after this placement -> big reward
            let slack = (post_residual as f64 - nr) / bin_capacity as f64;
            score -= 10.0 * (1.0 - slack);
        } else {
            // next item won't fit here; penalize leaving a gap smaller than next item
            if post_residual > 0 {
                score += 4.0 * (1.0 - (post_residual as f64) / nr);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // competition among fitting bins: mild penalty so scoring differentiates
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer bins with residual below mean residual (smaller holes) when multiple fit.
    let res_f = bin_residual as f64;
    score += 0.08 * (res_f - mean_residual);

    // Time horizon: early in stream, opening new bins is cheap (favor consolidation less);
    // late in stream, avoid leaving large residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress * tightness;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized by number of open bins (fragmentation cost),
        // but becomes attractive if no open bin fits well (post_residual small here = item_size? no, post = capacity - item).
        let new_post = post_residual as f64;
        let waste_penalty = if next_item_size > 0 && new_post < next_item_size as f64 { 6.0 } else { 0.0 };
        score += 15.0 + 1.5 * open_bins_count as f64 + waste_penalty;
        // late in stream, slightly cheaper to open a bin (little to consolidate anyway)
        score -= 4.0 * progress;
    }

    // Small structural bonus for near-perfect fills.
    if post_residual <= 2 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill_ratio = 1.0 - post / cap;

    // Base: prefer small post-residual, with non-linear emphasis
    let mut score = post * (1.0 + 0.8 * fill_ratio * fill_ratio);

    // Smooth stream-progress coupling: later in stream, tighten packing harder
    let tightness = 0.5 + 0.5 * progress * progress;
    score *= tightness;

    // Polynomial interaction between post_residual and progress
    let post_norm = post / cap;
    score += 6.0 * post_norm * post_norm * (1.0 - progress) * (1.0 - progress);

    // Reward near-perfect fits (post_residual small) with smooth bonus
    let perfect = (1.0 - post_norm).powi(6);
    score -= 4.0 * perfect;

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 3.0 * (1.0 - slack * slack);
        } else {
            // penalize post-residuals that are useless for next item, smoothly
            let waste = (nxt - post) / cap;
            score += 2.5 * waste * waste;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize mildly unless current fit is bad
    if bin_residual == bin_capacity {
        let badness = post_norm * post_norm; // post==cap -> 1
        score += 10.0 * (1.0 - badness) * (1.0 + 0.5 * progress);
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
    }

    // Mean-residual coupling: discourage diverging far from average residual
    let dev = (post - mean_residual) / cap;
    score += 1.5 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: reward residuals that are "friendly" sizes (small, reusable)
    let pr = post_residual;
    // Class A: tiny dead space (1..=10) is nearly perfect — heavily reward
    if pr >= 1 && pr <= 10 {
        score -= 60.0 + (10 - pr) as f64 * 4.0;
    }
    // Class B: mid residuals (11..=30) — moderate, still usable for small items
    else if pr <= 30 {
        score -= 25.0;
    }
    // Class C: large residual (>= 50) wastes the bin — penalize mildly
    else if pr >= 50 {
        score += (pr - 50) as f64 * 0.5;
    }

    // Modulo structure: residuals that are multiples of common item sizes are valuable
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.8;
        } else {
            // next item cannot use this residual: penalize proportionally to wasted potential
            score += (next_item_size - pr).min(pr) as f64 * 0.3;
        }
    }

    // Last chance: only one fitting bin — strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 40.0;
        // opening a new bin is better when the stream is early (many items left)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 20.0;
        // and when the item is large relative to capacity (hard to place later)
        score += (item_size as f64 / bin_capacity as f64) * 30.0;
    } else {
        // prefer tighter existing bins: reward closeness of fit
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= tightness * 30.0;
    }

    // Spread pressure: when many bins are open, consolidate into existing ones
    score += open_bins_count as f64 * 1.5;
    // and when mean residual is high, favor bins below the mean (tighter)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest future item are pure waste — penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Usable leftover space is mildly rewarded.
        score -= 3.0;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly
    // or well, strongly favor this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use the leftover: leftover more likely dead space.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Pressure from number of open bins: discourage spreading across many
    // bins; but allow opening a new bin when existing residuals are all poor.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline attractiveness, adjusted by context.
        score = 45.0;
        if open_bins_count > 0 {
            // Prefer new bin only if mean residual is too small for the item
            // or dead-space-heavy.
            if mean_residual < item_size as f64 {
                score -= 15.0;
            }
            if mean_residual < 25.0 {
                score += 10.0; // existing bins are near-full anyway, don't open
            }
            // More open bins => opening yet another bin is costly.
            score += 2.5 * (open_bins_count as f64);
        } else {
            score = -100.0; // no bins open at all: must open one
        }
    } else {
        // Mild reward for consolidating into already-open bins.
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - 2.0 * slack; // perfect follow-up match strongly rewarded
        if slack == 0.0 {
            score -= 30.0; // exact pair completion
        }
    } else if next_item_size > 0 {
        // Next item cannot follow: penalize dead space relative to next item
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Compare post_residual against mean residual across open bins:
    // prefer bins whose residual stays near the mean (balanced packing).
    score += 0.6 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0; // fresh bin enables a clean pair
        }
    }

    // Late-stream consolidation: favor tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space)
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Penalize leaving dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            score -= 5.0; // lookahead item can still fit here
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residuals below mean (consolidate emptier space usage)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, avoid opening new bins; early, allow exploration
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 20.0 + progress * 60.0 + open_bins_count as f64 * 2.0;
        // but allow new bin if item is huge and fit elsewhere would be terrible
        if item_size > bin_capacity * 3 / 4 {
            score -= 30.0;
        }
    }

    // Slight preference for bins whose residual is close to item size (perfect wrap)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let tight = 1.0 - norm_pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = (1.0 - progress) * norm_pr * norm_pr + progress * tight * tight;
    score += 40.0 * poly;

    // Reward near-perfect fits smoothly (quadratic falloff)
    let fit_gap = (pr / cap).powi(2);
    score -= 25.0 * (1.0 - fit_gap) * (item_size as f64 / cap);

    // Last-chance bonus, smoothly scaled by how well the item fills the bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - (bin_residual - item_size).min(bin_capacity) as f64 / cap);
    }

    // Lookahead: penalize wasting space needed by the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let shortfall = (nx - pr).max(0.0) / cap;
        score += 20.0 * shortfall * shortfall;
        // Reward leaving just enough room for the next item
        let room = if pr >= nx { 1.0 - (pr - nx) / cap } else { 0.0 };
        score -= 10.0 * room * room;
    }

    // Mild penalty for spreading across too many bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - norm_pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0 (residual % 10 == 0) leaves room for typical small items.
    let class = post_residual % 10;
    let class_reward: f64 = match class {
        0 => 12.0,
        1 | 9 => 4.0,
        2 | 8 => 6.0,
        3 | 7 => 3.0,
        4 | 6 => 2.0,
        _ => 0.0,
    };
    score -= class_reward;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize tiny dead space that nothing can use (items >= 1).
    if post_residual > 0 && post_residual < 4 {
        score += 15.0;
    }

    // Reward leaving room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.25 * (next_item_size as f64);
            // Exact two-item packing: residual exactly equals next item.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Lookahead won't fit here; mild penalty scaled by waste.
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    if fill > 0.8 {
        score -= 10.0 * (fill - 0.8);
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins, growing with open count.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If the item is large and few bins fit it, a fresh bin is fine.
        if fill > 0.5 && fitting_bins_count <= 2 {
            score -= 20.0;
        }
        // Late in the stream, avoid scattering.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If mean residual across open bins can't hold the item, opening is OK.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    } else {
        // Existing bins: prefer ones whose residual is close to item size (tight fit).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 10.0 * tightness;
        // Prefer bins below mean residual (consolidating emptier space).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Early stream: be slightly greedy about keeping bins balanced.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residuals too small for the smallest possible item (1..100 range,
    // but penalize gaps that are unlikely to be filled by the next item).
    if post_residual > 0 {
        // Gap unusable for the lookahead item: heavy penalty (wasted space).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
        // Very small absolute gap: likely permanent dead space.
        if post_residual < 10 {
            score += 12.0;
        } else if post_residual < 25 {
            score += 5.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open,
    // encourage consolidation when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.4 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty plus pressure, softened if current
        // best fit would leave a terrible gap.
        score += 20.0 + pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.05 * next_item_size as f64;
        }
    } else {
        // Slight reward for filling bins that are already relatively full.
        score -= 0.05 * (bin_capacity - bin_residual) as f64;
        // Reward placing into bins below mean residual (tighter bins).
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    // Lookahead synergy: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
