pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect fit gets a decisive reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item can fill this bin's post-residual exactly, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to how well it packs.
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize leaving medium dead space.
            if post_residual > 0 && post_residual < 10 {
                score += 3.0; // tiny dead space is fine
            } else if post_residual >= 10 && post_residual < 30 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Many open bins: prefer consolidating into existing bins (avoid sprawl).
    score += 0.6 * open_bins_count as f64;

    // Prefer bins with residuals far from the mean (better packing diversity),
    // or rather favor bins close to mean residual to keep bin states uniform.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: only attractive when nothing fits well or item is huge.
    if bin_residual == bin_capacity {
        let desperate = (fitting_bins_count == 0) as i32 as f64;
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.7;
        if desperate > 0.0 || (big_item && fitting_bins_count <= 1) {
            score -= 40.0;
        } else {
            score += 20.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Time horizon: early in stream, be picky (penalize mediocre fits);
    // late in stream, accept placements to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * tightness;

    // Penalize creating residuals that are awkward (just above common small sizes).
    if post_residual >= 1 && post_residual <= 9 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post residual, with non-linear (quadratic) penalty growth.
    let mut score = post + 0.9 * (post / cap) * post;

    // Smooth coupling of dead-space penalty with stream progress:
    // late in the stream, wasted space is costlier.
    score += (0.5 + 1.5 * progress) * (post * post) / (cap * cap) * 20.0;

    // Perfect fit bonus: strongly reward near-zero residual, smoothly.
    let tightness = 1.0 - post / cap;
    score -= 15.0 * tightness * tightness * tightness;

    // Lookahead: if the next item can fit into the post residual, reward this bin;
    // smooth decay as the gap between next item size and post residual grows.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        score -= 8.0 * fits_next * (-gap / cap).exp();
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // over opening a new bin (scaled smoothly by fitting-bin scarcity).
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 + progress);
    } else {
        // Mild scarcity reward: fewer fitting bins -> slightly prefer reuse.
        score -= 3.0 / (fitting_bins_count as f64);
    }

    // Penalize bins whose residual deviates strongly from the mean (keeps a
    // diverse residual portfolio); smooth quadratic coupling with progress.
    let dev = post - mean_residual;
    score += (0.05 + 0.15 * progress) * dev * dev / cap;

    // New-bin candidate: bin_residual == bin_capacity means an empty bin.
    // Make opening a new bin attractive only for large items that would leave
    // huge dead space in existing bins, and only early/mid stream.
    let is_new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let waste_ratio = post / cap;
    score += is_new_bin * (10.0 - 18.0 * waste_ratio) * (1.0 - progress) * (1.0 - progress);

    // Slight preference for consolidating into fewer bins as stream matures.
    score += 0.01 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "perfect" companions
    // for common item-size classes (small items 1..=10, mid 11..=30, large 31..=100).
    let perfect_fit_bonus = match post_residual {
        0 => 60.0,                       // exact fill is best
        1..=10 => 35.0,                  // small item fits later
        11..=30 => 18.0,                 // mid item fits later
        31..=60 => 6.0,                  // large item fits later
        _ => 0.0,                        // dead space above 60
    };
    score -= perfect_fit_bonus;

    // Modulo-10 harmonic class: residuals divisible by 10 align with decimal item grids.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Penalize awkward odd residuals (rarely reusable).
    if post_residual % 2 == 1 {
        score += 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // harmonic pairing: next item leaves a small remainder again
            let r2 = post_residual - next_item_size;
            if r2 <= 10 { score -= 10.0; }
        } else {
            // next item cannot use this residual: penalize large leftover more
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Tightness ratio: prefer bins where item fills a large fraction of residual.
    if bin_residual > 0 {
        let fill = item_size as f64 / bin_residual as f64;
        score -= fill * 20.0;
    }

    // New-bin candidate logic: an empty bin has high base residual; only attractive
    // when existing bins are crowded or the fit is poor.
    if bin_residual == bin_capacity {
        score = 55.0
            - (mean_residual / bin_capacity as f64) * 40.0      // crowded bins -> open new
            + (post_residual as f64) * 0.25                      // large fresh residual is fine
            - if fitting_bins_count <= 1 { 20.0 } else { 0.0 }
            - if next_item_size > 0 && next_item_size <= bin_capacity - item_size { 5.0 } else { 0.0 };
    }

    // Slight preference to keep fewer open bins when residuals are large.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * (mean_residual - post_residual as f64).abs() * 0.05;
    }

    // Progress-based tiebreak: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals in [1, 12] are nearly unusable for future items.
    if post_residual > 0 && post_residual <= 12 {
        score += 30.0 + (12.0 - post_residual as f64) * 2.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room that can still host the next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (post_residual as f64 - next_item_size as f64).min(40.0) * 0.25;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual cannot host next item: mild penalty scaled by gap size.
        score += (next_item_size as f64 - post_residual as f64) * 0.4;
    }

    // Open-bin pressure: discourage spreading across many bins when few fit options exist.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins)
    // so large residuals stay available for large items.
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: opening a fresh bin is attractive only when the item
    // is large (would leave a big residual anyway) or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score = 55.0 - item_size as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin anyway
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/tight fits
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 200.0 / post_residual as f64;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 + 100.0 / (1.0 + slack);
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use
        score += 0.3 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins with below-average residual (denser bins)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 60.0; // pairing consecutive items in a fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize creating dead space that few future items could use
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // small leftover is actually fine (items 1..10 exist)
    }
    if post_residual > 50 {
        score += 8.0; // large leftover wastes the bin
    }

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * (next_item_size as f64);
        } else {
            // penalize blocking the next item
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.08 * overflow;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless
    // open bins are quite full or none fit well
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // open new bin only when existing bins are crowded or many fit poorly
        score = 60.0 - 40.0 * mean_fullness - 2.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size > 70 {
            score -= 10.0; // big item coming; fresh bin useful
        }
    }

    // Time horizon: late in the stream, consolidate aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty on bin count growth pressure
    score += 0.05 * open_bins_count as f64;

    // Nudge toward bins below mean residual (balance load lightly)
    score += 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post-residual with smooth polynomial shaping (penalize small unusable leftovers)
    let mut score = pr * (1.0 + 2.0 * pr_norm * pr_norm);

    // Non-linear coupling of post-residual with stream progress:
    // late in the stream, tight fits (small post_residual) are more valuable
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * progress;

    // Reward bins whose post-residual matches the lookahead item size (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= 25.0 * (-40.0 * diff * diff);
    }

    // Penalize creating dead space relative to mean residual across open bins
    score += 0.5 * (pr - mean_residual).abs();

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Mild penalty for proliferating bins early; smooth in progress
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // Slight preference to keep the emptiest bins for later large items
    score += 0.3 * pr_norm * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" classes
    // (multiples of common item sizes / capacity fractions), penalize dead space.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    let mut class_bonus = 0.0;

    // Residuals that are multiples of small common sizes are reusable.
    if pr % 10 == 0 { class_bonus -= 6.0; }
    else if pr % 5 == 0 { class_bonus -= 3.0; }
    if pr % 25 == 0 { class_bonus -= 4.0; }
    if pr % 20 == 0 { class_bonus -= 3.0; }

    // Fraction-of-capacity classes: quarter / half / three-quarter residuals.
    if pr * 4 == cap { class_bonus -= 8.0; }
    if pr * 2 == cap { class_bonus -= 10.0; }
    if pr * 4 == 3 * cap { class_bonus -= 6.0; }

    // Dead space: tiny residuals (1..5) are almost unusable -> strong penalty.
    if pr > 0 && pr < 5 { class_bonus += 15.0; }

    score += class_bonus;

    // Perfect fit: enormous reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains beautifully.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            // Harmonic check: next item leaves a class-nice residual too.
            if (post_residual as i64 - next_item_size as i64) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled by waste.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin wastes (capacity - item) immediately.
    // Prefer new bin only when item is huge relative to capacity or existing
    // residuals are all poor fits.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // New bin baseline cost: the space left behind.
        score = (bin_capacity - item_size) as f64;
        // Big items deserve fresh bins; small items should never open bins.
        if frac > 0.7 { score -= 20.0 * frac; }
        if frac < 0.35 { score += 25.0; }
        // If many bins already fit the item, discourage new bin.
        if fitting_bins_count > 0 {
            score += 12.0 * (fitting_bins_count as f64).min(4.0);
        }
        // Late in stream, consolidation matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Reward using bins with below-mean residual (tighten loose bins).
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= 3.0 * diff / bin_capacity as f64;
        }
    }

    // Mild penalty for proliferation of open bins when this placement
    // leaves a large residual that nothing may use.
    if open_bins_count > 3 && post_residual > 40 && post_residual < 50 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    } else {
        // Larger leftover space is less harmful; mild quadratic softening.
        score -= 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Tightness reward relative to current fill.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Mean-residual coupling: prefer bins whose residual deviates favorably.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong reward to avoid opening a needless new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            // Next item cannot use the leftover: penalize proportionally.
            score += 0.4 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // New-bin candidate baseline: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 120.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving large dead space
            score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    // Prefer bins with residual below mean (tighter bins absorb items first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New empty bin candidate: penalize unless current fit is bad.
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        score += 150.0 - 0.5 * waste;
        if post_residual > 20 {
            score += 50.0;
        }
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: bonus if the next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 15.0 + (slack_after_next as f64 / bin_capacity as f64) * 10.0;
    }
    // Penalize if next item nearly fits but misses (dead space risk).
    if next_item_size > post_residual && next_item_size > 0 && next_item_size - post_residual <= 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize using a bin when many bins can fit (save flexible bins for later).
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Time horizon: early in the stream, be conservative (keep bins balanced);
    // late in the stream, prioritize closing bins out (tight fits matter more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state: if mean residual is high, tolerate looser fits to consolidate.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let base = 35.0 + mean_residual * 0.1 + (open_bins_count as f64) * 0.5;
        score = base + item_size as f64 * 0.2;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space quadratically (waste grows super-linearly)
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth interaction: tight fits are more valuable as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward residual that can still host the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            // residual too small for next item: penalize dead space
            score += 8.0 * (ni - pr) / cap * (0.5 + progress);
        }
    } else {
        // last item: fill as tightly as possible
        score -= 20.0 * tightness;
    }

    // Penalize bins far from mean residual (prefer balanced fill levels)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Mild pressure to close bins when many are open
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: make empty bin attractive only when it's early
    // or residuals elsewhere are poor
    if bin_residual == bin_capacity {
        let avg_tight = 1.0 - (mean_residual / cap);
        score = cap * (1.0 - progress) * 0.3 + 60.0 * progress * avg_tight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: residues divisible by 10 are more reusable
    let pr = post_residual;
    let class = pr % 10;
    if class == 0 {
        score -= 6.0; // perfectly aligned residual (e.g. 0,10,20...) highly reusable
    } else if class == 5 {
        score -= 2.0;
    } else {
        score += (5 - (class.min(10 - class))) as f64 * 0.8; // penalize odd dead space
    }

    // Zero residual is ideal: bin closed perfectly
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: reward residual that can host the next item exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 4.0 + (slack as f64).sqrt();
        if slack % 10 == 0 {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // next item can't use this residual; penalize proportionally
        score += (next_item_size as f64 - post as f64).min(20.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate penalty: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count >= 1 {
            score += 10.0 * (fitting_bins_count as f64).ln().max(1.0);
        }
        // early stream: opening bins is fine; late stream: prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer tighter bins relative to mean residual of open bins
    score += (mean_residual - post) * 0.5;

    // Mild preference to fill bins deeply when many bins are open
    score -= (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10.0 - post_residual as f64) * 4.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 0.8;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if item_size >= bin_residual {
        // should not happen, but guard
        score += 1000.0;
    }

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (post_residual as f64 - next_item_size as f64).min(30.0) * 0.3;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // New-bin candidate: make opening a new bin costly unless the current bin
    // would be left with dead space or is empty already.
    if bin_residual == bin_capacity {
        // Empty bin candidate: only attractive if no tight fit exists elsewhere.
        score = bin_capacity as f64 + 25.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big item coming: fresh bin is fine
        }
    }

    // Slight preference for bins below mean residual (fill emptier bins first
    // keeps larger residuals available for future items).
    score -= (mean_residual - post_residual as f64).clamp(-20.0, 20.0) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - next).abs();
        if post >= next {
            // next item can chain into this bin: reward tight chaining
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 400.0; // exact two-item perfect fill
            }
        } else {
            // dead space penalty scaled by how badly next item misses
            score += 25.0 * (next - post) / bin_capacity as f64;
        }
    }

    // Penalize bins far below mean residual (wasteful large residual usage)
    let post_f = post_residual as f64;
    score += 0.35 * (post_f - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 90.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= bin_capacity as f64 {
            score -= 40.0; // fresh bin can host a clean pair
        }
    }

    // Late-stream consolidation: tighten packing as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that nearly fill the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize dead space relative to the mean residual of open bins:
    // a bin left far below the fleet mean residual wastes capacity differently.
    let mean_res = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    let post = post_residual as f64;
    if post > mean_res + 0.5 {
        score += 0.35 * (post - mean_res);
    } else {
        score -= 0.15 * (mean_res - post).abs();
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 18.0;
        if post_residual <= 5 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: only attractive when the item fits poorly everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: reusing an open bin is usually better.
        score += 22.0;
        // If no open bin fits well (post_residual would be large in this new bin
        // relative to item), opening a new bin is more reasonable: relax penalty.
        let fit_quality = item_size as f64 / bin_capacity as f64;
        if fit_quality > 0.6 {
            score -= 14.0 * (fit_quality - 0.6) / 0.4;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // Many open bins with high mean residual: avoid spreading too thin.
        if open_bins_count > 4 && mean_res > 30.0 {
            score += 6.0;
        }
    } else {
        // Slight preference for bins with smaller residual before placement (denser bins first).
        score += 0.08 * (bin_residual as f64);
    }

    // Lookahead coupling: if the next item would fit exactly into the post-residual,
    // reward this placement; if the next item barely misses, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            if slack <= 8.0 {
                score -= 12.0 * (1.0 - slack / 8.0);
            } else {
                score += 0.05 * slack;
            }
        } else {
            let miss = nxt - post;
            if miss <= 8.0 {
                score += 8.0 * (1.0 - miss / 8.0);
            }
        }
    }

    // Mild global load balancing: many open bins -> encourage filling existing ones.
    score -= 0.6 * (open_bins_count as f64).ln().max(0.0);

    // Small noise-free tie-break on residual for determinism.
    score += 0.01 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap; // normalized post residual
    let is_new = (bin_residual == bin_capacity) as f64;

    let mut score = r;

    // Non-linear polynomial coupling of post-residual with stream progress.
    // Late in the stream, prefer tight fits (small post_residual) more aggressively.
    let prog_weight = 0.5 + 1.5 * progress * progress;
    score += prog_weight * rn * rn * cap * 0.3;

    // Reward filling a bin nearly perfectly, stronger as stream progresses.
    score -= (1.0 - rn).powi(3) * (10.0 + 20.0 * progress);

    // Penalize dead space that is too small to be useful for typical items,
    // with a smooth (quadratic) activation around small residuals.
    let dead = rn * (1.0 - rn);
    score += dead * dead * cap * 0.6;

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - fit_gap / cap) * (0.6 + 0.4 * progress);
    } else if next_item_size > post_residual {
        // Next item won't fit here; slight penalty, growing with progress.
        score += 2.0 * progress;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && is_new < 0.5 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate: penalize mildly early, more strongly late in the stream
    // (once many bins are open, prefer packing into them).
    score += is_new * (6.0 + 14.0 * progress + 0.2 * open_bins_count as f64);

    // Mild tie-break toward bins with residual close to the mean (balance).
    score += ((r - mean_residual) / cap).powi(2) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful" sizes
    // (multiples of 10 or small enough to be plausibly filled by small items).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr % 10 == 0 && pr <= 50 {
        score -= 25.0; // round, reusable residual
    } else if pr < 10 {
        score += 30.0; // dead space below smallest item
    } else if pr > 50 {
        score += (pr as f64 - 50.0) * 0.8; // large leftover less penalized but scaled
    }

    // Modulo-5 harmonic classes: fine-grained fit quality
    if pr % 5 == 0 {
        score -= 6.0;
    } else {
        score += (5 - (pr % 5)) as f64 * 1.5;
    }

    // Integer-division thresholds: how many items of typical size fit the residual
    let slots = pr / 20;
    score -= slots as f64 * 4.0;

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0;
            // harmonic match: residual class equals next item class
            if pr % 10 == next_item_size % 10 {
                score -= 8.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: only prefer opening a new bin when current
    // bin would leave terrible dead space and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead = (pr < 10) as i32 as f64 + (pr > 60) as i32 as f64;
        if dead > 0.5 && progress < 0.7 {
            score -= 45.0 * dead; // fresh bin better than wasting this one
        } else {
            score += 55.0; // prefer existing bins by default
        }
    }

    // Mean residual alignment: bins far from the fleet mean are penalized
    score += (mean_residual - post_residual as f64).abs() * 0.25;

    // Mild preference to fill bins when many are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Unusable sliver: dead space that no item (min size 1..100) can use well.
            score += (10.0 - gap) * 6.0;
        }
        // Non-linear penalty for gaps in the "awkward" middle range.
        if gap > 0.0 && gap < 20.0 {
            score += (20.0 - gap) * (20.0 - gap) * 0.15;
        }
    }

    // Perfect-fit reward: filling the bin completely is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward if the lookahead item can exactly fill the resulting gap (k=2 chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial lookahead fit: mild reward proportional to how much is consumed.
        let frac = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * frac;
    } else if next_item_size > post_residual {
        // Next item cannot use the gap: penalize proportionally to wasted gap.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of open bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Relative tightness: prefer bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if all existing fits are poor
        // (i.e., the best post_residual among fits would be a large awkward gap).
        // Penalize opening new bins when open bins exist with decent residuals.
        if open_bins_count > 0 {
            // If mean residual suggests existing bins are roomy, prefer them.
            if mean_residual >= item_size as f64 * 1.5 {
                score += 35.0;
            }
            // Late in the stream, consolidating into open bins is cheaper.
            if progress > 0.7 {
                score += 20.0 * progress;
            }
        } else {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tightest fit).
    // Reward if next item can exactly fill the post_residual (2-step lookahead match).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - post_residual as f64).abs() < 0.5 {
            // Perfect 2-step chain: current item + next item fill the bin exactly.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits in the leftover: mild reward proportional to how well it fills.
            let fill = next / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // Next item will NOT fit here: penalize dead space, especially large dead space.
            let dead = post_residual as f64;
            score += 0.35 * dead;
            // Extra penalty if next item is small enough that this dead space is wasteful.
            if next < dead {
                score += 0.15 * (dead - next);
            }
        }
    }

    // Coupling with mean residual: prefer bins whose post_residual diverges from mean
    // in a useful direction (push residual toward 0 or toward capacity-like chunks).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (pr - mean_residual).abs();
        if pr < mean_residual {
            score -= 0.2 * dev; // tightening below average residual is good
        } else {
            score += 0.1 * dev; // leaving more than average is mildly bad
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual;
    // penalize it so it is only chosen when no decent open-bin fit exists.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item is large (hard to place later), opening fresh is less bad.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Early in the stream, having many open bins is costly; opening is cheaper then.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Mild preference to keep number of open bins low: filling existing bins
    // when many are open avoids bin proliferation.
    score += 0.5 * open_bins_count as f64 * (pr / bin_capacity as f64);

    // Slight bonus for larger items going into emptier bins (big items fit anywhere,
    // save tight bins for small items).
    score -= 0.05 * item_size as f64 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space is convexly bad).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Lookahead: reward residuals that the next item can exactly or nearly fill.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 * (-gap / 15.0).exp();
        } else {
            // next item cannot use this residual: mild penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap;
        }
    } else {
        // Last item: fill as much as possible.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Penalize opening new bins when open bins have plenty of room,
    // but allow it late in the stream to avoid overstuffing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early/when mean residual is high.
        let openness = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 8.0 + 14.0 * openness * (1.0 - 0.5 * progress);
        score -= 3.0 * progress; // slightly cheaper to open bins later
        // If no open bin fits at all, opening is necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // If the item fits a residual exactly elsewhere, new bin is bad.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor)
        // and bins with residuals below the mean (consolidate large holes).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.08 * dev;
        if bin_residual as f64 > mean_residual {
            score += 1.5;
        }
        // Slight preference for fewer open bins early on.
        score += 0.02 * (open_bins_count as f64) * (1.0 - progress);
    }

    // Penalize leaving residuals that are too small for the minimum item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 * (10 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = post / cap; // 0 = perfect fit

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = post
        + 40.0 * fit_ratio * fit_ratio
        + 25.0 * fit_ratio * fit_ratio * fit_ratio;

    // Reward tight fits more as the stream progresses (smooth coupling)
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * (20.0 + 60.0 * progress);

    // Penalize leaving residuals that are awkwardly small-but-nonzero (dead space)
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 3.0;
    }

    // Lookahead coupling: reward residual that can host the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = (post - nx).abs();
        score -= 15.0 * (1.0 - slack / cap).max(0.0) * (1.0 - fit_ratio);
        if post >= nx {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * progress;
    }

    // Mean-residual coupling: prefer bins deviating below mean residual (fill laggards)
    score += 0.3 * (post - mean_residual).max(0.0);

    // New-bin candidate: mild penalty so we prefer reuse, but allow opening when
    // existing fits are terrible (large post residual) or few bins fit
    if bin_residual == bin_capacity {
        score = 55.0 + 45.0 * (1.0 - progress) - 8.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into residue classes mod 10
    // Small leftovers (dead space) are heavily penalized unless they are "harmonic"
    // complements of likely future items (multiples of 10 / 25 / 50).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fill_ratio = (bin_capacity - post_residual) as f64 / cap;

    // Reward high fill ratio
    score -= 30.0 * fill_ratio * fill_ratio;

    // Harmonic classes: post_residual in {0, 10, 20, 25, 50} are reusable classes
    let harmonic = match post_residual {
        0 => 2.0,
        10 | 20 | 25 | 50 => 1.0,
        x if x % 10 == 0 => 0.5,
        _ => 0.0,
    };
    score -= 12.0 * harmonic;

    // Penalize tiny non-harmonic dead space strongly
    if post_residual > 0 && harmonic == 0.0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
            if slack < 10.0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; slight penalty proportional to mismatch
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with residual close to item (tight fit)
    let tight = (bin_residual as f64 - item_size as f64) / cap;
    score += 8.0 * tight * tight;

    // Mildly discourage scattering across many open bins when mean residual is high
    if open_bins_count > 3 && pr > mean_residual {
        score += 2.0;
    }

    // Early stream: be slightly more willing to open new bins (score new bin lower)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of a fresh bin
        let mut nb = cap * 0.35 - 18.0 * (1.0 - progress);
        if item_size as f64 > 0.6 * cap {
            nb -= 15.0; // big items prefer fresh bins
        }
        if next_item_size > 0 && next_item_size as f64 + item_size as f64 <= cap {
            nb -= 10.0; // pair next item into this fresh bin
        }
        score = score.min(nb);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: post_residual below the minimum item size (1)
    // is pure dead space; also penalize gaps too small for typical items.
    if post_residual < 10 {
        score += (10 - post_residual as i32) as f64 * 12.0;
    } else if post_residual < 20 {
        score += (20 - post_residual as i32) as f64 * 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize wasting this bin's usefulness.
        score += 5.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation into
    // existing bins rather than opening new ones.
    let pressure = open_bins_count as f64;
    score += pressure * 1.5;

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // already tight; placing here is efficient. If far above mean, penalize
    // slightly to keep bins balanced.
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.3 * diff;

    // Progress-based mild tightening: later in the stream, be greedier about
    // tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless no good alternative.
    // Empty bin has post_residual = capacity - item_size; make it mildly unattractive.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when post_residual is small relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= tightness * 12.0;

    // Strong reward for near-perfect fit.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits into the post-residual, this placement is valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0);
        } else {
            // Dead space that cannot host the next item is penalized.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // bins fit poorly and there's plenty of stream left to justify the extra bin.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit_penalty = if post_residual > 30 { 0.0 } else { 1.0 };
        score += 25.0 + poor_fit_penalty * 20.0 - progress * 15.0;
        // Discard new bins when many bins are already open with slack.
        score += (open_bins_count as f64) * 1.5 + mean_residual * 0.2;
    } else {
        // Slight preference for filling bins that are already more depleted.
        score += (bin_capacity - bin_residual) as f64 * 0.05;
        // Mild penalty proportional to how much this bin's residual deviates
        // above the mean residual (prefer balanced or below-mean usage).
        let dev = post_residual as f64 - mean_residual;
        if dev > 0.0 { score += dev * 0.15; } else { score -= (-dev) * 0.05; }
    }

    // Late-stream consolidation: favor using existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Quadratic penalty on wasted residual, modulated by stream progress
    score += (pr / cap) * (pr / cap) * (0.5 + 1.5 * t) * 40.0;

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tight = 1.0 - pr / cap;
    score -= tight * tight * (10.0 + 20.0 * t);

    // Prefer bins whose residual is close to the item (smooth coupling)
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += diff * diff * 30.0;

    // Lookahead: bonus if post_residual accommodates next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = (pr - nx).abs();
        score -= 15.0 * (1.0 - slack / cap).max(0.0);
        score += (pr < nx) as i32 as f64 * 8.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + t);
    }

    // Penalize scattering across many open bins when mean residual is low
    score += (open_bins_count as f64).ln() * (mean_residual / cap) * 5.0;

    // New-bin candidate: mild baseline so it's chosen only on poor fits
    if bin_residual == bin_capacity {
        score += 12.0 - 6.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class 1: post_residual small (<=10) -> nearly perfect.
    // Class 2: post_residual divisible into common small sizes (mod 10 == 0).
    // Class 3: awkward leftover.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    } else {
        score += 5.0;
    }

    // Integer-division thresholds on post_residual: leftover that can host
    // typical next items is valuable; leftover below the smallest item is dead.
    let can_host_next = next_item_size > 0 && post_residual >= next_item_size;
    if can_host_next {
        score -= 10.0;
        // exact chain fit: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // dead space relative to the lookahead item
        score += (next_item_size as f64 - post_residual as f64).min(25.0) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no tight fits exist. Empty-bin call has post_residual == capacity.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap_f;
        // opening a fresh bin is attractive for big items or late in the stream
        score += 30.0 - 25.0 * frac - 10.0 * (step_index as f64 / total_items.max(1) as f64);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Prefer bins whose residual is below mean (tighter bins get packed first).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Mild pressure against proliferating bins.
    score += open_bins_count as f64 * 0.05;

    // Harmonic modulo coupling: post_residual classes that align with capacity
    // fractions (quarter/half/third) are more reusable.
    if post_residual == bin_capacity / 4 || post_residual == bin_capacity / 2 || post_residual == bin_capacity / 3 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are pure waste — penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Soft penalty for small-but-usable residuals, scaled by how "tight" the fit is.
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 0.8;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        // next item would leave a dead gap too — mild penalty
        score += 8.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading; penalize placements that keep a bin
    // barely used, and penalize opening new bins when pressure is high.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) + progress;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are crowded or
        // this is a last-chance-free situation with a poor fit.
        let tight = mean_residual / bin_capacity as f64;
        score += 45.0 - 30.0 * tight - 6.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Avoid opening a new bin for items that would leave a big residual anyway.
        score += post_residual as f64 * 0.3;
    } else {
        // Favor using bins whose residual deviates from the mean (consume outliers).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.25 * dev;
        // Last-chance bin: strongly prefer filling the only bin that fits.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Prefer bins that keep residual aligned with likely future demand.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (post_residual near 0).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize dead space relative to smallest plausible item.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score -= 25.0; // small unusable sliver is fine
        } else {
            score += dead * 0.15;
        }
    }

    // 2-step lookahead: reward when post_residual matches next item size exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 80.0; // perfect chaining
        } else if post_residual >= next_item_size {
            // residual can host next item: mild bonus scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit in leftover; penalize proportionally
            score += (nxt - post_residual as f64) * 0.3;
        }
    }

    // Compare bin residual to mean residual: prefer bins with less residual (tighter).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: mildly penalize so it's chosen only when fits are poor,
    // but keep it attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Late in stream: prefer closing bins tightly (reduce open bin count pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in fill ratio).
    let fill = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * fill * fill * fill;

    // Penalize small but unusable dead space (post_residual below typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins with residuals above the mean (consume "fat" bins first).
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= (res - mean_residual) * 0.3;
    } else {
        score += (mean_residual - res) * 0.3;
    }

    // Time horizon: early in stream, be conservative about opening new bins;
    // late in stream, prefer closing bins tightly.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * t * fill;

    // Penalize accumulating many open bins slightly, to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: neutral-ish baseline that loses when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But allow opening a new bin late in the stream when open bins are fragmented.
        if post_residual == bin_capacity && t > 0.5 && mean_residual < 20.0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (0.5 + progress);
    score -= 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= 25.0 * fit_ratio * fit_ratio * (0.3 + progress);

    // Penalize dead space relative to mean residual of open bins
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead coupling: reward leaving space usable by next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = (pr - nxt).abs();
        score -= 20.0 * usable * (1.0 - gap / cap);
        score += 10.0 * (1.0 - usable) * pr_norm;
    }

    // Mild penalty for opening new bins late in the stream
    score += 5.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (pr_norm * cap / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic class of post_residual
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual < 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 60.0;
    } else if post_residual <= 30 {
        score -= 20.0;
    } else {
        // penalize large dead space, non-linearly
        score += frac * frac * 50.0;
    }

    // Harmonic class: post_residual divisible into small canonical slots
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0; // residual matches common item-size grid
    }

    // Lookahead: does next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // bonus if next item exactly fills residual
        if next_item_size == post_residual {
            score -= 60.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // residual becomes dead space for the known next item
        score += (post_residual as f64) * 0.5;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Many open bins: prefer consolidation (favor bins below mean residual => emptier bins)
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += dev * 30.0; // prefer emptier bins to consolidate
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0
            || (fitting_bins_count == 1 && bin_residual - item_size > 40);
        if desperate {
            score -= 150.0;
        } else {
            score += 120.0; // discourage opening new bin when fits exist
        }
    }

    // Late stream: slightly more conservative, protect good residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items are unusable "dead space" — penalize them heavily.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: worst possible outcome.
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        } else {
            // Larger residuals remain usable; slight reward scaled by size.
            score -= 0.05 * post_residual as f64;
        }
    } else {
        // Perfect fill — maximum reward.
        score -= 100.0;
    }

    // Tightness coupling: reward when the item nearly fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage scattering across many open bins,
    // but the pressure fades as the stream progresses (endgame consolidation
    // matters less than early compaction).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 - 0.5 * progress) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has no dead space yet, but
    // opening it should only win when the best fit is genuinely poor.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; add a mild opening cost that shrinks
        // if many bins are already open (amortization of fragmentation).
        score += 12.0 + 0.1 * open_bins_count as f64;
        // Lookahead: if the next item is large, a fresh bin preserves room.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0;
        }
    } else {
        // Lookahead synergy: placing here leaves room for the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            // Blocks the next item's fit into this residual — mild penalty.
            score += 4.0;
        }
    }

    // Mean-residual context: prefer bins whose residual is below the mean
    // (concentrating slack into fewer bins keeps other bins flexible).
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 && residual_f < mean_residual {
        score -= 0.10 * (mean_residual - residual_f);
    } else if residual_f > mean_residual {
        score += 0.05 * (residual_f - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chaining: this placement enables a full bin next step.
            score -= 60.0 + 20.0 * (1.0 - progress);
        } else {
            // Penalize dead space the next item cannot use.
            let waste = post_residual as f64 - next_item_size as f64;
            if waste > 0.0 {
                score += 0.35 * waste;
            } else {
                // Next item doesn't fit here anyway; mildly favor compact residuals.
                score += 0.05 * (-waste);
            }
        }
    } else {
        // Last item: minimize residual outright.
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 {
            true
        } else {
            // Compare best possible post-residual quality against mean residual.
            post_residual as f64 > mean_residual + 0.5 * item_size as f64
        };
        if poor_fit {
            score -= 15.0 + 10.0 * (1.0 - progress);
        } else {
            // Prefer reusing existing bins when they fit decently.
            score += 40.0;
        }
    }

    // Coupling with mean residual: penalize bins that are anomalously empty relative to peers.
    score += 0.25 * ((post_residual as f64 - mean_residual).abs());

    // Slight preference for tighter fits scaled by item size.
    score += 0.05 * (item_size as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize wasted space quadratically.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post residual, reward this bin strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 20.0 - gap * 0.5;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins whose residual is close to the item size (best-fit coupling).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Slight preference to fill already-open bins when many are open.
    score += open_bins_count as f64 * 0.05;

    // Time horizon: early on, be conservative (favor filling existing bins);
    // later, allow opening new bins for better long-term packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0;

    // New-bin candidate: make it attractive only when the item is large relative to capacity
    // or the fit in open bins would be very poor.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual as f64 - item_size as f64).abs();
        score -= 5.0 + poor_fit * 0.1;
        // Discourage opening bins for small items.
        score += (100.0 - item_size as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space
    let mut score = pr + 8.0 * norm_pr * norm_pr;

    // Smooth non-linear coupling: wasted space matters less late in the stream
    let progress_weight = 0.5 + 0.5 * (1.0 - progress) * (1.0 - progress);
    score *= progress_weight;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    let tightness = (-norm_pr * 4.0).exp();
    score -= 6.0 * tightness * (1.0 - progress);

    // Penalize bins far from mean residual (fragmentation smoothing)
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Lookahead: bonus if next item fits the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 4.0 * (-slack * 3.0).exp();
        } else {
            score += 2.0 * ((nx - pr) / cap);
        }
    }

    // Mild penalty for opening a new bin when many bins are open
    if bin_residual == bin_capacity {
        score += 2.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals in "reusable" bands
    // (multiples of small denominations likely to be filled by future items).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else {
        // class by integer division thresholds on post_residual
        let class = pr / 10; // 0..10 harmonic decile
        match class {
            0 => score -= 25.0,          // 1..9: nearly full, excellent
            1 | 2 => score -= 12.0,      // 10..29: still very reusable
            3 | 4 => score -= 4.0,       // 30..49: decent
            5 | 6 => score += 6.0,       // 50..69: awkward dead zone
            7 | 8 => score += 0.0,       // 70..89: mediocre
            _ => score -= 3.0,           // 90..99: nearly empty, like new bin
        }
        // modulo-5 arithmetic: residuals divisible by 5 pair well with typical sizes
        if pr % 5 == 0 {
            score -= 3.0;
        }
        if pr % 10 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            score -= 10.0; // chains a second item into this bin
            // exact chain (post_residual == next) is a harmonic match
            if n == pr {
                score -= 15.0;
            } else {
                let chain_left = pr - n;
                if chain_left <= 10 {
                    score -= 6.0; // leaves only tiny waste
                }
            }
        } else {
            score += 5.0; // next item won't fit here; bin will strand residual
            // modulo class conflict: pr and n share no common divisor band
            if pr % 10 != 0 && n % 10 != 0 {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only allow opening a new bin when existing
    // fits are poor (large dead space) and many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline penalty: prefer reusing an open bin
        score += 30.0;
        // but if the best existing placement would waste a lot, opening is OK
        let waste = post_residual as f64;
        if waste > 0.6 * cap {
            score -= 20.0;
        }
        // fewer open bins -> keep consolidation, penalize new bins more
        score += 5.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // reward tight fits relative to capacity fraction
        let fill = item_size as f64 / cap;
        score -= 8.0 * fill;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // placing here tightens the global residual distribution.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 0.15 * (mean_residual - res_f);
    } else {
        score += 0.10 * (res_f - mean_residual);
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits in the resulting post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: avoid bins far below mean residual (fragmentation).
    score += 0.5 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: baseline penalty so it is only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score += 55.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward perfect match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Extra bonus for exact fit consumed by next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize leaving a residual too small for the next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest packing.
        score += 0.0;
    }

    // Relative to mean residual: prefer bins that get closer to the average fill.
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Last chance: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin opening unless item is large relative to capacity or fits badly.
    if bin_residual == bin_capacity {
        let waste_ratio = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 * (1.0 - waste_ratio) - 10.0 * waste_ratio;
        if next_item_size > 0 && next_item_size >= item_size {
            // Next item is bigger; opening a fresh bin may be smart.
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative anyway
        }
    }

    // Mild stream-progression pressure to consolidate early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Penalize residuals that no future item (10..80 typical) can use
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Many fitting bins: mild penalty for wasting choice on a crowded fit
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (next_item_size as f64 / 100.0);
        } else {
            // next item won't fit here; penalize dead space proportionally
            score += 8.0 * (post_residual as f64 / 100.0);
        }
        // chain fit: next item exactly fills post residual
        if post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // New-bin candidate logic: only attractive when existing bins are poor fits
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin
        score += 15.0;
        // cheaper to open a bin early when few bins are open (consolidation phase)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress) * (1.0 - open_bins_count as f64 / (open_bins_count as f64 + 3.0));
        // if current bin would leave big dead space and next item is large, prefer new bin
        if post_residual > 0 && post_residual < next_item_size && next_item_size > 50 {
            score -= 25.0;
        }
    } else {
        // Penalize bins whose residual deviates far from mean (fragmentation)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Prefer filling bins that are already mostly full (reduce bin count pressure)
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill;

    // Late in stream: strongly prioritize closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - norm_pr * progress * 0.5;
    let mut score = pr + 40.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (20.0 + 30.0 * progress);

    // Penalize last-chance bin usage mildly to preserve it unless fit is tight
    if fitting_bins_count == 1 {
        score -= 8.0 * tightness;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - ((pr - nx) / cap).abs());
        } else {
            score += 4.0;
        }
    }

    // Slight preference for filling bins with low mean residual
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residuals are dead space
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap_f;

    // Penalize residuals in "dead zones" (too small for typical items 1..100 min item is 1,
    // but residual below 10 is nearly unusable)
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // Modulo-class logic: residuals that are multiples of common item sizes are reusable
    let reusable = |r: u32| -> bool {
        (r % 10 == 0) || (r % 20 == 0) || (r % 25 == 0) || (r % 50 == 0)
    };
    if reusable(post_residual) {
        score -= 15.0;
    } else {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - fill_after / cap_f);
        } else {
            // next item won't fit here: mild penalty scaled by wasted fraction
            score += 20.0 * (next_item_size as f64 - pr) / cap_f;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Prefer bins with residual close to item (tight fit)
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += 30.0 * tightness;

    // New-bin candidate: only attractive when existing bins would leave bad residuals
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 40.0;
        // but if the item is large relative to capacity, opening fresh is fine
        score -= 50.0 * (item_size as f64 / cap_f);
        // if many open bins already, discourage spreading
        score += 5.0 * open_bins_count as f64;
    }

    // Progress-based mild tightening: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (mean_residual - pr) / cap_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
