    // Lookahead: favor bins whose residual can host the next item too.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Extra reward if the residual exactly matches the next item well.
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 4.0 / (1.0 + chain_fit);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize leaving残 space unusable by the next item.
        score += 3.0 * (post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New empty bin candidate: only attractive when few bins fit or open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = (open_bins_count as f64) / (1.0 + fitting_bins_count as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // Open a new bin if open bins have little usable residual or few alternatives.
        let open_worth = -10.0 + 20.0 * (1.0 - pressure) + crowding;
        score = 45.0 - open_worth.min(20.0);
        // Late in the stream, discourage opening new bins slightly less (stream may be long).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * (1.0 - progress);
    } else {
        // Slight bonus for filling bins that are below the mean residual (balancing).
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        }
        // Mild preference for keeping the number of open bins stable.
        score += 0.2 * (open_bins_count as f64).ln().max(0.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
