            score += 40.0; // tiny sliver, nearly unusable
        } else if next_item_size > 0 && (dead as u32) < next_item_size {
            score += 25.0; // gap too small for the known next item
        } else if next_item_size > 0 && (dead as u32) == next_item_size {
