        score += 20.0 + 3.0 * open_bins_count as f64 + 0.2 * mean_residual;
        // But allow new bins late in the stream when existing bins are crowded.
        score -= 15.0 * progress;
    } else {
        score -= 2.0 * open_bins_count as f64 * fill;
    }

    // Prefer bins whose residual is close to the mean (balanced packing).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

