pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness;

    // Penalize dead space that no future item can plausibly use:
    // dead space is post_residual if smaller than the smallest plausible item.
    if post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 18.0; // cannot host the lookahead item
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead synergy: if the lookahead item exactly fills the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // leave room for the next item: reward moderate leftover
        score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score -= 4.0 * pressure.min(20.0);

    // Deviation from mean residual: prefer bins tighter than average early,
    // but spread load when bins are nearly all tight.
    let dev = bin_residual as f64 - mean_residual;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - 2.0 * t) * 0.35 * dev;

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the empty bin moderately; the tight-fit
    // bonuses of good open bins will overcome this.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // If this empty-bin call is the only fitting option, allow it.
        score += if scarcity > 0.0 { 0.0 } else { 30.0 + 20.0 * (1.0 - t) };
        // Slight bonus late in the stream to avoid leaving many half-empty bins.
        score -= 15.0 * t * (post_residual as f64 / bin_capacity as f64);
    }

    // Small global fill-pressure term: as stream progresses, prefer bins with
    // larger current residual consumed (i.e., lower remaining residual).
    score -= 8.0 * t * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual
    let mut score = post;

    // Non-linear polynomial coupling of residual with stream progress:
    // early on, prefer tight fits (low post_residual) less aggressively;
    // later, penalize large residuals super-linearly.
    let poly = x * x * (0.5 + 2.0 * progress) + x * x * x * (1.0 + 3.0 * progress);
    score += 30.0 * poly;

    // Reward near-perfect fits smoothly (small post residual gets discount).
    score -= 10.0 * (1.0 - x) * (1.0 - x) * (1.0 + progress);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post - nx).abs() / cap;
        score += 15.0 * diff * diff; // penalize when next item doesn't fill nicely
        score -= 12.0 * (1.0 - diff) * (1.0 - diff); // reward good chaining
    }

    // Slight preference for bins with residuals near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild penalty for spreading across too many open bins early.
    score += (open_bins_count as f64).ln() * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    if post_residual == 0 {
        score -= 60.0; // perfect fill is always best
    }

    // Harmonic class of the leftover: classify post_residual into residue bands
    // by integer division against capacity fractions.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let leftover_class = post_residual / eighth; // 0..=8 harmonic slot

    // Dead space penalty grows super-linearly for awkward leftovers
    // (too small for typical items 10..80, i.e. < 10 usable).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // unusable sliver
    }

    // Modulo coupling: leftover that matches common size classes is good.
    // Items in 1..100, so leftovers divisible by common item granularities
    // (10, 20, 25, 50) are more likely reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 25 == 0 { score -= 5.0; }
        if post_residual % 50 == 0 { score -= 6.0; }
    }

    // Lookahead compatibility: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward exact harmonic match between leftover and next item.
            let gap = post_residual - next_item_size;
            score -= 12.0 - (gap as f64).min(12.0) * 0.5;
            if gap == 0 { score -= 20.0; } // chains a perfect fill
        } else {
            // Next item won't fit here anyway; mild penalty for wasting
            // a large-capacity bin on a lone item.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across too many open bins when mean residual is high:
    // prefer consolidating into bins that are already relatively full.
    if open_bins_count > 2 {
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 10.0;
        // Harmonic threshold: bins more than half full get extra consolidation bonus.
        if (bin_capacity - bin_residual) > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // New-bin candidate logic: an empty bin should only win when no open bin
    // is a decent fit. Give the empty bin a moderate handicap that tight fits
    // in existing bins can overcome.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if the item nearly fills a fresh bin (harmonic large-item class),
        // opening a new bin is actually great.
        if post_residual <= quarter {
            score -= 22.0;
        }
        // Early in the stream, opening bins is cheaper.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 8.0;
        }
    }

    // Mild global regularization toward mean residual alignment: prefer bins
    // whose residual is below the mean (i.e. fuller than average).
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.15;

    // Small harmonic jitter on leftover class to break ties deterministically
    // without randomness: alternate preference across residue slots.
    score += (leftover_class as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
