    // Global pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate gets penalized via its large residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and bins accumulate.
        score += 15.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Compare residual to mean residual across open bins: prefer bins with
    // below-average residual (concentrate filling), i.e. larger fill.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.15 * diff;
    }

    // Mild time-varying aggression: early on, prefer consolidating into fewer bins.
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with non-linear shaping.
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more.
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space that is too small to be useful (non-linear in norm_pr).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if pr < next {
            score += 12.0 * (1.0 - pr / next.max(1.0)) * (1.0 - pr / next.max(1.0));
        } else {
            // Reward leaving room exactly sized for the lookahead item.
            score -= 8.0 * (1.0 - ((pr - next) / cap).powi(2));
        }
    }

    // Last-chance bonus: smooth reward when few bins can fit the item.
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - norm_pr * norm_pr);
    }

    // Mild global pressure: many open bins with large mean residual
    // favors consolidating into existing bins.
    let openness = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 10.0 * openness * (mean_residual / cap) * (1.0 - tightness);

    // Smooth penalty for very small post_residual relative to capacity
    // (avoid creating slivers) unless it's a near-perfect fit.
    score += 5.0 * norm_pr * norm_pr * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit: huge reward (subtract).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: residues divisible into capacity fractions.
        let pr = post_residual as f64;
        let frac = pr / cap; // fraction of capacity wasted
        // Penalize small-but-unusable residuals non-linearly.
        if pr < 10 {
            score += 120.0 * (1.0 - pr as f64 / 10.0);
        }
        // Modulo classes: residuals that are "harmonic" with common item sizes
        // (multiples of 5, 10, 20, 25, 50) are more likely fillable later.
        let harmonic = (post_residual % 5 == 0) as f64 * 6.0
            + (post_residual % 10 == 0) as f64 * 8.0
            + (post_residual % 20 == 0 || post_residual % 25 == 0) as f64 * 6.0
            + (post_residual % 50 == 0) as f64 * 4.0;
        score -= harmonic;
        // Fractional dead-space penalty, convex in wasted capacity.
        score += 40.0 * frac * frac;

        // Lookahead: if next item exactly fills the post residual, big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 300.0;
            } else if next_item_size <= post_residual {
                // next item fits here: mild reward proportional to fill quality
                let fill = next_item_size as f64 / post_residual as f64;
                score -= 60.0 * fill;
            } else {
                // next item cannot use this residual: penalize large leftovers
                score += 10.0 * (1.0 - (next_item_size as f64 - pr) / cap).max(0.0);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: make an empty bin moderately attractive by
    // default (baseline), so it wins only when open bins score poorly.
    if bin_residual == bin_capacity {
        score = 75.0 + 0.25 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 200.0; // reserve fresh bin for a full-size item
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Slight stream-position adaptation: later in the stream, prefer tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // future item (items >= 1, but practically small gaps are wasted) get
    // a strong penalty. A tiny gap (1..=10) is almost certainly dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual == 0 {
        // Perfect fill: heavily reward closing a bin exactly.
        score -= 80.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Penalize leaving a gap just below next_item_size (blocks the lookahead item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid forcing
    // a bad placement unless the fit is decent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual as f64 <= mean_residual * 0.5 {
            score -= 20.0;
        } else {
            score += 12.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer existing bins over new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (2.0 + 3.0 * progress);
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: add pressure so it's only chosen when existing
        // placements are genuinely bad, and penalize a fresh bin's full residual.
        score += 10.0 + pressure * 0.8;
    }

    // Slight pull toward bins near the mean residual (balanced packing).
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (small post_residual).
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * 100.0 / 100.0 * (post_residual as f64);

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - diff / (bin_capacity as f64));
        // Perfect lookahead match: post_residual exactly equals next item.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving residuals too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 18.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if item is large and would leave awkward residual in existing bins, opening is fine.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 70.0; // fresh bin perfectly chains to next item
        }
    }

    // Prefer bins below mean residual (keeps balance, avoids fragmenting large-residual bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference for filling older bins as stream progresses.
    score -= 0.05 * (step_index as f64 / total_items.max(1) as f64) * (bin_capacity - bin_residual) as f64;

    // Penalize very small unusable residuals (dead space < typical min item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Many fitting bins: mild penalty to encourage bin consolidation.
    if fitting_bins_count > 1 {
        score += 2.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: opening a fresh bin is attractive only when
    // the item fits poorly in existing bins or the current bin leaves dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 30.0;
        // If this bin is the only option, opening is inevitable-ish: reduce cost.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Lookahead: if next item pairs well with a fresh bin residual
        // (next item fits into post_residual of a fresh bin), encourage opening.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
        // Early in stream: new bins are cheap; late: prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 12.0 * (1.0 - progress);
    } else {
        // Lookahead synergy: reward placing item so that next item fits the
        // remaining residual of this bin.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
        // Penalize leaving residual that is too small for typical items
        // (dead space): residual in (0, 10) is nearly unusable.
        if post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
    }

    // Global state coupling: prefer bins below mean residual (keep bins balanced),
    // penalize dumping into already-empty-ish bins when mean residual is high.
    if !is_new_bin {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Consolidation pressure: with many open bins, favor filling existing ones.
    score += 0.4 * open_bins_count as f64 * (is_new_bin as i32 as f64);

    // Mild time-decay of lookahead value.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (1.0 - progress) * (norm_pr * norm_pr) + progress * (norm_pr * norm_pr * norm_pr);
    score += 12.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space far from mean residual (wasted capacity)
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Mild penalty for spreading across many bins late in the stream
    score += 0.3 * (open_bins_count as f64) * progress;

    // New-bin candidate handling: keep it attractive early, expensive late
    if bin_residual == bin_capacity {
        score = 20.0 * (1.0 - progress) + 60.0 * progress + 0.5 * (item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual) super-linearly
    let fit_frac = post_residual as f64 / cap;
    score += 12.0 * fit_frac * fit_frac;

    // Harmonic class: quantize post_residual into capacity/8 classes
    let class = (post_residual * 8 / bin_capacity.max(1)) as i64;
    score -= 4.0 * (class as f64).sin().abs();

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: reward if next item fits the residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.3 * next_item_size as f64;
        } else {
            // dead space if next item can't use it
            score += 6.0 * (1.0 - (next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins when mean residual is high
    score += 0.15 * (open_bins_count as f64) * (mean_residual / cap - fit_frac).abs();

    // Late in stream: prefer consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - fit_frac);

    // New-bin candidate: penalize unless current bins fit poorly
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (post_residual as f64) > 0.5 * cap && next_item_size > post_residual;
        score += if bad_fit { 5.0 } else { 40.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum item (1) are fine,
    // but residuals that are small relative to typical items are likely wasted.
    // Treat residual < 10 as fully dead; penalize it heavily.
    let dead = if post_residual < 10 { post_residual as f64 } else { 0.0 };
    score += 3.0 * dead;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits: post_residual small but nonzero.
    if post_residual > 0 && post_residual <= 15 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize opening new bins implicitly by rewarding existing bins).
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // New-bin candidate: penalize when decent fits exist elsewhere,
        // reward when open bins are nearly full on average.
        score += 5.0 + 0.5 * open_bins_count as f64;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 15.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; this residual is likely dead.
        score += 0.5 * post_residual as f64;
    }

    // Late in stream: prioritize minimizing bin count, fill existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 8.0 * progress;
    }

    // Slight preference for bins with residual close to item (best-fit core).
    score += 0.1 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; penalize wasted space that could have held it.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.25 * waste;
        }
    }

    // Relative to mean residual: prefer bins tighter than average when many bins are open.
    let mean_gap = (post_residual as f64) - mean_residual;
    score += 0.08 * mean_gap * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // Neutral base; lookahead decides if a fresh bin is better.
        let fresh_look = if next_item_size > 0 && next_item_size <= bin_capacity {
            (bin_capacity - next_item_size) as f64
        } else {
            0.0
        };
        score = 60.0 + fresh_look * 0.3;
        // Late in stream, be more reluctant to open new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If only one fitting bin, opening a new bin is wasteful.
        if fitting_bins_count <= 1 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave minimal waste.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never host a typical item (post_residual too small).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0; // only tiny items fit
    }

    // Lookahead: reward if the next item can fit in the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // If next item won't fit here anyway, prefer perfect packing now.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: opening a new bin wastes (capacity - item_size).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score = (bin_capacity - item_size) as f64 + 15.0;
        // Early in the stream, opening bins is cheap and useful for future flexibility.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If very few bins fit the item, new bin is a real option.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Many open bins with high mean residual: avoid spreading waste.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 25.0;
        }
    } else {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
        // Prefer bins whose residual is close to mean (keep residuals balanced)
        // but only mildly; tight fit reward dominates.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Late in the stream, close out bins aggressively (minimize waste left behind).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual with smooth quadratic sharpening
    let mut score = post * (1.0 + (post / cap).powi(2));

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * (cap * (0.35 + 0.65 * progress));

    // Penalize dead space relative to mean residual of open bins
    let dead = (post - mean_residual).abs();
    score += dead * (0.1 + 0.4 * progress);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= cap * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize early, allow late when waste is justified
    if bin_residual == bin_capacity {
        let waste = cap - item;
        score += cap * (1.2 - progress) + 0.25 * waste;
        // opening a new bin is fine if the item is large relative to capacity
        score -= (item / cap) * cap * 0.5 * progress;
    }

    // Lookahead: bonus if next item fits the resulting residual well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let fit_next = (nxt <= post) as i32 as f64;
        score += gap * 0.3 - fit_next * cap * 0.15 * (1.0 - progress);
    }

    // Mild penalty for bin proliferation
    score += open_bins_count as f64 * (0.5 + 2.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quantization
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / 10.0).floor(); // 0..10 harmonic class
    // Penalize awkward mid-range residuals (11..30 are hard to fill)
    if post_residual >= 11 && post_residual <= 30 {
        score += 8.0;
    } else if post_residual == 0 {
        score -= 15.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 3.0; // small unusable-but-tiny waste
    }
    // Bonus if a harmonic class boundary hit (residual divisible by common item sizes)
    if post_residual % 25 == 0 || post_residual % 20 == 0 || post_residual % 10 == 0 {
        score -= 4.0;
    }

    // Lookahead: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact or near-exact chain fill is great
            if next_item_size == post_residual {
                score -= 20.0;
            } else {
                let after2 = post_residual - next_item_size;
                if after2 <= 10 {
                    score -= 12.0;
                } else {
                    score -= 5.0;
                }
            }
        } else {
            // next item won't chain here; penalize if we leave big gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive if no good fit exists elsewhere
    if bin_residual == bin_capacity {
        // base cost of opening a bin, softened late in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap + 12.0 - 6.0 * progress;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0; // big next item: fresh bin useful
        }
    }

    // Slight preference for tighter existing bins when many are open
    score += (open_bins_count as f64) * 0.05 * (pr / cap);

    // Mean residual coupling: if this bin's residual far below mean, it's a good packer
    score -= (mean_residual - pr).max(-50.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fills relative to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;
    score -= (bin_residual as f64 - mean_residual).max(0.0) * 0.2;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 10.0;
        }
    }

    // New-bin candidate: prefer opening a new bin only when current fit is poor.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: moderate score; penalize slightly with stream progress
        // to encourage consolidation late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 25.0 + progress * 20.0 + open_bins_count as f64 * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward exact/near match between post_residual and next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / 50.0).max(0.0);
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize proportionally to the overshoot.
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Penalize dead space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += 0.25 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer filling tight bins: reward small post residuals nonlinearly.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Slight penalty for opening a brand-new bin when other bins fit.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residual that cannot fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            let waste = post_residual as f64;
            score += 2.0 * waste;
            // extra penalty if residual is small but unusable (true dead space)
            if post_residual < 10 {
                score += 15.0;
            }
        } else if post_residual >= next_item_size {
            // reward leaving room exactly for the next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Lookahead: if next item is large, prefer bins where residual after placement is tiny
    if next_item_size > 50 {
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early
    // in the stream or when many bins already exist with usable space
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 40.0 + 30.0 * progress;
        // if mean residual across open bins is large, opening a new bin is wasteful
        new_bin_penalty += mean_residual * 0.3;
        // if very few bins fit the item, opening new bin is less bad
        if fitting_bins_count == 0 {
            new_bin_penalty -= 50.0;
        } else if fitting_bins_count == 1 {
            new_bin_penalty -= 20.0;
        }
        score += new_bin_penalty;
    }

    // Mild penalty for spreading across too many bins
    score += 0.5 * open_bins_count as f64;

    // Small noise-free time coupling: later in stream, prefer fuller bins even more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    let mut score = post;

    // Smooth non-linear penalty on wasted space, stronger as stream progresses.
    let waste_frac = post / cap;
    score += 2.5 * waste_frac * waste_frac * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 3.0 * tightness * tightness * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: penalize if post_residual cannot fit the next item but could with slack.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > post {
            score += 2.0 * (nx - post) / cap;
        } else {
            // Reward leaving space exactly usable by next item.
            score -= 1.5 * (1.0 - (post - nx) / cap);
        }
    }

    // New-bin candidate: make opening a new bin mildly unattractive unless
    // this bin would leave a very poor residual or bins are few.
    if bin_residual == bin_capacity {
        let pressure = if mean_residual > 0.0 { (mean_residual / cap).min(1.0) } else { 0.0 };
        score = cap + 5.0 - 8.0 * pressure * (0.3 + progress) - (open_bins_count as f64).sqrt();
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Coupling: mean residual alignment — prefer bins whose residual is near mean (balanced).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.2 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward residuals that are "usable" for common item sizes
    // via modulo arithmetic on post_residual.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit is ideal
    } else {
        // Classify residual by divisibility / small-modulo classes
        let class_bonus: f64 = if pr % 10 == 0 {
            6.0
        } else if pr % 5 == 0 {
            3.0
        } else {
            0.0
        };
        score -= class_bonus;

        // Dead-space penalty: residuals too small for the smallest plausible item
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 10.0;
        }

        // Reward if the lookahead item fits the resulting residual exactly or well
        if next_item_size > 0 && next_item_size <= pr {
            if pr == next_item_size {
                score -= 20.0;
            } else {
                let gap = pr - next_item_size;
                if gap < 10 {
                    score -= 8.0;
                }
            }
        } else if next_item_size > pr {
            // lookahead can't use this residual -> mild penalty scaled by overflow
            score += 4.0;
        }

        // Integer-division threshold classes on post_residual
        let q = pr / 25; // quarter classes: 0..4
        score -= match q {
            0 => 5.0,           // 0..24 : nearly dead
            1 => 2.0,           // 25..49
            2 => 0.0,           // 50..74
            _ => -3.0,          // 75..99 : very usable
        };
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 40.0;
        // If no good fit exists among open bins (this is the only fitting option),
        // soften the penalty so a new bin can win.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Prefer fuller bins: relative fill fraction
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Mild penalty proportional to number of open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.2;

    // Mean residual coupling: if this bin's residual is below mean, it's tighter -> favor
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (10 - post_residual as i32) as f64 * 6.0;
    }
    // Mid-range gaps (10..=20) are moderately risky: only large-ish future items fit.
    if post_residual >= 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward bins whose residual tightly matches the item (good packing density).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 25.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 5.0 {
            score -= 20.0;
        } else {
            score -= 8.0 * (1.0 - gap / 100.0);
        }
    }
    // Penalize if next item would be stranded in a tiny leftover gap.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 15.0;
    }

    // New-bin candidate: default moderate score; open a new bin only when open bins
    // would create dead space or pressure is high.
    if bin_residual == bin_capacity {
        score = 25.0 + open_bins_count as f64 * 0.5 - mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild stream-progression adaptation: tighten criteria later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (small post_residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += 40.0 * (gap / 100.0);
        }
    }

    // Penalize bins far below mean residual (fragmented, poorly filled bins)
    score += 0.8 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 250.0 + 0.5 * item_size as f64;
    }

    // Prefer denser packing when many bins are open
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: squared coupling of post_residual
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize leaving dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny slivers are waste
    } else if post_residual >= 10 && post_residual <= 40 {
        score -= 3.0; // usable range for future items
    } else if post_residual > 80 {
        score += 2.0; // near-empty leftover after placement
    }

    // Lookahead: reward bins whose post_residual pairs with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            score -= 5.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 2.0 * (gap / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: prefer consolidation into fuller bins
    let open_f = open_bins_count as f64;
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= open_f * fullness * 1.5;

    // Mean residual context: bins below mean residual are already packed; prefer them
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Time horizon: early on, be conservative about new bins; late, allow spreading
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: empty bin gets a penalty unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 8.0 - 4.0 * progress; // cheaper to open early than late
        if post_residual == 0 {
            score -= 50.0; // perfect fit never open a new bin
        }
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Reward tight fits more strongly as the stream progresses
    if post_residual == 0 {
        score -= 50.0 * (1.0 + progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
