    // Penalize opening new bins when many bins are open and residuals are high
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        score -= 5.0 * (mean_residual / cap) * progress;
    }

    // Lookahead: favor bins whose post_residual can fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / cap);
        } else {
            score += 8.0 * (1.0 - pr / cap.max(1.0));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
