        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            score -= 15.0; // weak alternative exists
        }
        // Fewer open bins relative to progress: prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count as f64 > 4.0 + 10.0 * progress {
            score -= 5.0;
        }
    }

    // Coupling with mean residual: prefer bins far from the mean (extremes first).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // Prefer filling bins with large residual (big holes get used).
    score -= 0.05 * bin_residual as f64;

    // Modulo coupling between item_size and capacity quarter-classes.
    let q = (item_size / 25) as f64;
    score -= 1.5 * q;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 30.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Reward residual that can still host a plausible future item (>=10)
        if post_residual >= 10 {
            score -= 15.0;
        } else {
            score += 40.0;
        }
    }

    // Lookahead coupling: if next item fits the post residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= next_item_size as f64 * 0.8 + 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space relative to the known next item
        score += 25.0;
    }

    // Last chance: only bin that can fit the item -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bins pressure: discourage scattering when many bins are open
    score += open_bins_count as f64 * 1.5;

    // Prefer bins tighter than the mean residual (compactness)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: neutral baseline; only attractive when no open bin is decent
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 1 {
            score -= 30.0; // opening fresh may be better than forcing into sole bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Near-match bonus: next item almost fills the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (-gap / 6.0).exp();
    }

    // Penalize dead space that no plausible item (>=1) can use well:
    // small post_residual that is NOT a match is wasted capacity.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0;
    }

    // Reward tight fits relative to current mean residual across open bins.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * (tightness - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0));

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it competitive only when current bins are crowded.
    if bin_residual == bin_capacity {
        score -= 12.0 * (open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0));
        if mean_residual < item_size as f64 * 0.5 {
            score -= 15.0;
        }
    }

    // Slight preference for balanced bin usage as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 - mean_residual) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = (mean_residual - item_size as f64).abs();
        score += 18.0 + 20.0 * progress - 0.3 * tightness;
        if next_item_size > 0 && next_item_size <= post_residual.max(item_size as u32) {
            score -= 6.0;
        }
    }

    // Mild preference for filling bins below mean residual (keeps large residuals available)
    if (bin_residual as f64) > mean_residual && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Penalize very small unusable leftovers scaled by stream position
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress_sq = progress * progress;
    let progress_cu = progress_sq * progress;

    // Normalize residuals
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let ir = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with progress:
    // late in the stream, tight fits (small post_residual) are worth much more
    let coupling = pr * (1.0 - progress_sq) * 20.0 + pr * pr * progress * 35.0 + pr * pr * pr * progress_cu * 15.0;
    score += coupling;

    // Reward near-perfect fits with smooth quadratic shaping
    let fit_bonus = (1.0 - pr) * (1.0 - pr) * (10.0 + 30.0 * progress);
    score -= fit_bonus;

    // Penalize residual that no plausible future item can use (dead space),
    // smoothly weighted by how far the residual is from typical item sizes
    let dead = if pr > 0.0 { (pr - (pr / 0.8).floor() * 0.8).abs() } else { 0.0 };
    score += dead * dead * 25.0 * (0.5 + progress);

    // Lookahead: if next item fits into post_residual, reward this bin strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= (1.0 - gap) * (1.0 - gap) * (12.0 + 25.0 * progress);
        } else {
            score += (-gap) * 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more when open bins are few,
    // but relax the penalty late in the stream when consolidation matters
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress) - 6.0 * progress_sq;
        // opening new bins is cheap if few are open
        score -= (open_bins_count.min(20) as f64) * 0.3;
    }

    // Prefer bins whose residual deviates from the mean (pack heterogeneously),
    // with a smooth cubic term
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * dev * 5.0 * (0.5 + progress);

    // Mild preference for filling larger items into emptier bins
    score -= ir * (1.0 - (bin_residual as f64 / cap)) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small-item reachable" classes are more valuable to keep tight.
    let pr = post_residual;
    let class = pr / 10; // decade class of leftover space
    score += (class as f64) * 3.0;

    // Perfect fit is heavily rewarded.
    if pr == 0 {
        score -= 500.0;
    } else if pr <= 5 {
        score -= 120.0;
    }

    // Lookahead coupling: reward residual that exactly (or nearly) matches next item.
    if next_item_size > 0 {
        let gap = if pr >= next_item_size { pr - next_item_size } else { next_item_size - pr };
        if pr >= next_item_size {
            score -= (gap as f64).min(40.0) * 4.0;
        } else {
            score += (gap as f64) * 1.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize creating dead space that no small item (min 1..10) can fill well:
    // residual in (0, 10) is nearly dead unless it's 0.
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    // or the fit into open bins is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 / (mean_residual / cap + 1.0);
        score += 150.0; // base cost of opening a new bin
        score -= pressure * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 50.0; // fresh bin helps sequence big items
        }
        if fitting_bins_count <= 1 {
            score -= 220.0; // no good alternative: open new bin
        }
    } else {
        // Prefer bins whose residual is a harmonic fraction of capacity near fullness.
        let fill = (bin_residual as f64) / cap;
        score -= fill * 40.0;
        // Prefer bins whose residual is divisible into useful classes (multiples of 10/20).
        if pr % 10 == 0 && pr > 0 {
            score -= 15.0;
        }
        if pr % 20 == 0 && pr > 0 {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: tighten packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 25.0 * (1.0 - (post_residual as f64) / cap);

    // Slight preference for bins below mean residual (use emptier space first is bad;
    // instead prefer tighter bins to consolidate).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item (min item size 1, but practically tiny gaps) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward if the lookahead item exactly or nearly fits the post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.15;
    }
    // Penalize when post_residual cannot host the next item (dead space for k=2).
    else if next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.10;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we pay for a fresh bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins.
    score -= open_bins_count as f64 * 1.5;

    // Slightly prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that create fragmented space.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    // New-bin candidate: opening a new bin is only attractive when no good fit
    // exists (large item, tight residual) or few bins are open.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / bin_capacity as f64) * 20.0
            + open_bins_count as f64 * 2.0;
        score += 15.0 - pressure;
    }

    // Prefer tighter fits overall: small relative slack is good.
    score += (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Mild late-stream conservatism: as stream progresses, avoid creating
    // new bins / dead space since fewer items remain to fill them.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.20;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: heavily favor bins whose post_residual is small.
    let pr = post_residual as f64;
    if pr == 0.0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly,
    // penalize post_residual that is just barely too small for the next item (dead space).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        if pr >= n {
            // next item fits in the leftover: reward closeness of the chain fit
            score -= 40.0 + 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // leftover unusable by next item: penalize proportional dead space
            score += 25.0 * (1.0 - n / bin_capacity as f64) + 0.5 * gap;
        }
        // chain of exact matches: post_residual == next item size
        if (pr - n).abs() < 0.5 {
            score -= 120.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual
    // (fill the fullest bins first), but avoid ultra-tight bins that strand space.
    score += 0.6 * (mean_residual - pr);
    if pr > 0.0 && pr < 10.0 {
        score += 15.0; // small unusable slivers are wasteful
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make opening a new bin costly unless the item is large
    // and no open bin gives a good fit.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let best_possible = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 300.0 - 200.0 * tightness - 250.0 * best_possible;
        // Late in the stream, prefer closing out open bins rather than spawning new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is valuable.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items
    // (residuals below ~20 are likely wasted).
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs();
        // Penalize opening a new bin when open bins are reasonably empty.
        score += 18.0 + 0.15 * mean_residual;
        // But discount if next item is large and current fit is loose.
        if next_item_size > 0 && fit_ratio < 0.5 && next_item_size as f64 > post_residual as f64 + 10.0 {
            score -= 22.0;
        }
        let _ = spread;
    } else {
        // Prefer bins whose residual is close to the item (best-fit shaping).
        score += 0.08 * (bin_residual as f64 - item_size as f64);
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for over-shrinking.
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Global state: many open bins with high mean residual -> consolidate,
    // favor filling existing bins rather than spreading.
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= 0.1 * mean_residual;
    }

    // Time horizon: early in stream, be conservative about tight fits
    // (keep bins flexible); late in stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;
    // Smooth non-linear coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let wave = (progress * std::f64::consts::PI).sin();
    score += 8.0 * prn * prn * (0.5 + wave) * (1.0 - progress);
    // Penalize large residuals early, reward tight fits late
    score -= (1.0 - prn) * (1.0 + progress) * 3.0;
    // Dead-space penalty: quadratic in post_residual relative to mean residual
    if pr > mean_residual {
        score += 0.5 * (pr - mean_residual) * (pr - mean_residual) / cap;
    }
    // Lookahead coupling: reward leaving space near next item size
    let gap = (pr - next_item_size as f64).abs();
    score += 0.02 * gap * (1.0 - progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }
    // New-bin candidate: mildly penalize unless residuals elsewhere are tight
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (mean_residual / cap);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover into capacity fractions.
    let post = post_residual as f64;
    let frac = post / cap; // 0..1 fraction of capacity left over

    // Penalize leftovers in "dead" harmonic classes (hard to fill later).
    // Classes: (0,10], (10,20], (20,30], (30,50], (50,100]
    let class_penalty = if post == 0 {
        -30.0 // perfect fit: strongly reward
    } else if post <= 10 {
        -12.0 // near-perfect: small items (>=1) can still use it
    } else if post <= 20 {
        -4.0 // usable by small items
    } else if post <= 30 {
        3.0 // risky zone: only tiny items fit
    } else if post <= 50 {
        8.0 // half-dead space
    } else {
        14.0 // mostly empty bin: wasteful placement
    };
    score += class_penalty;

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportional to how tightly the next item would nest.
            let tightness = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 6.0 + 8.0 * tightness;
        } else {
            // Next item cannot use this bin's leftover: penalize leftover more.
            score += 5.0 + 0.05 * post;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so that
    // only genuinely bad fits on open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 0.02 * open_bins_count as f64;
        // If nothing fits well elsewhere this stays competitive; if an open bin
        // scores lower (good fit / last chance), it wins.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 2.0; // slightly favor fresh bin when next item is big
        }
        return score;
    }

    // Prefer bins whose residual is already small relative to the mean
    // (consolidate space, keep big-residual bins flexible for big items).
    score += 0.10 * (mean_residual - post);

    // Late in the stream, tighten packing: reward filling bins nearly full.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - frac);

    // Mild penalty for spreading across too many open bins.
    score += 0.03 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized
    // because no item (min size 1) can be assumed to fill them reliably.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward exact / near-exact fills strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Tightness ratio: favor bins where the item occupies a large fraction of residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Pressure from number of open bins: discourage spreading into many bins,
    // but allow opening a new bin when existing residuals are large and fragmented.
    let open_pressure = open_bins_count as f64 * 2.0;
    score += open_pressure * (1.0 - tightness);

    // Mean residual context: if this bin's residual is far below mean, its remaining
    // space is precious; penalize wasting it on a poor fit.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev * (1.0 - tightness);
    } else {
        score -= 0.10 * (-dev) * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual <= 9 && post_residual > 0 {
            score += 20.0; // but not if it creates dead space
        }
    }

    // New-bin candidate handling: only attractive when open bins would leave bad gaps
    // or when no bins fit well. An empty new bin has residual == capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit_elsewhere = mean_residual < item_size as f64 * 1.2;
        if bad_fit_elsewhere {
            score -= 15.0 + 10.0 * progress; // opening a fresh bin is fine
        } else {
            score += 18.0; // discourage abandoning usable open bins
        }
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    } else {
        // Lookahead synergy: reward placing item so that next item fits this bin too.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
            score += 15.0; // creating a gap too small for the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if the next item fits exactly
    // into the post-residual (chain of perfect matches).
    if next_item_size > 0 {
        if next_item_size == post_residual && post_residual > 0 {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits: reward proportionally to how snug the
            // resulting two-step residual is.
            let two_step = (post_residual - next_item_size) as f64;
            score -= 60.0 - two_step.min(60.0);
        } else {
            // Next item cannot use this residual: penalize wasted space
            // that is smaller than the next item (dead space risk).
            score += (post_residual as f64) * 0.5;
        }
    }

    // Penalize residuals that are too small to ever hold a meaningful
    // item (dead space), scaled by how early we are in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * (2.0 + 2.0 * progress);
    }

    // Last-chance bin: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current
    // item leaves a large usable residual elsewhere. Prefer existing
    // bins mildly; allow new bin only when it creates a clean state.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If no existing bin fits well (post_residual large waste on
        // existing bins), opening a fresh bin becomes attractive.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
            score -= 15.0;
        }
    }

    // Relative-to-mean coupling: favor bins whose post-residual sits
    // below the mean residual (concentrating usage into fuller bins).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Mild reward for consolidating when many bins are open.
    score -= open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let _ = item_size;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Base: best-fit flavor — minimize leftover space.
    let mut score = post;

    // Perfect closure (zero waste) gets a strong bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead (k=2): reward placements whose post-residual still
    // accommodates the next item, with extra reward for a tight follow-up fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let lw = 8.0 * (1.0 - 0.5 * progress); // lookahead strength decays near stream end
        if post >= nxt {
            let tight = 1.0 - (post - nxt) / cap; // 1.0 = perfect follow-up fit
            score -= lw * (nxt / cap) * (0.5 + 0.5 * tight);
        } else {
            // Next item won't fit here: mild penalty proportional to shortfall.
            score += 0.04 * (nxt - post);
        }
    }

    // Last-chance: this is the only open bin that can fit the item.
    // Using it weakly dominates opening a new bin, so reward strongly.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 25.0 + 0.1 * mean_residual.min(cap);
    }

    if is_new_bin {
        if fitting_bins_count == 0 {
            // No open bin can fit the item: opening a new bin is mandatory.
            score -= 1000.0;
        } else {
            // Penalize proliferation, more when many bins are already open
            // or existing residuals are ample. Kept moderate so a strong
            // lookahead advantage (next item fits only in fresh space)
            // can still justify opening a new bin.
            score += 7.0
                + 1.0 * fitting_bins_count as f64
                + 0.2 * open_bins_count as f64
                + 0.02 * mean_residual;
        }
    }

    // Gentle worst-fit tie-breaker: slightly favor bins with above-average
    // residual to preserve small residuals for small future items.
    if !is_new_bin {
        score -= 0.015 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.9 * progress * norm_post);

    // Quadratic dead-space penalty: small post-residuals are wasted space
    score -= 30.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - progress);

    // Cubic coupling term: tight fits rewarded more as stream progresses
    score -= 20.0 * norm_item * norm_post * (0.5 + progress);

    // Lookahead synergy: reward if next item fits into post residual
    if next_item_size > 0 {
        let next = next_item_size as f64 / cap;
        if next_item_size <= post_residual {
            score -= 15.0 * next * (1.0 - next);
        } else {
            score += 10.0 * next * (1.0 - progress);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_post);
    }

    // Mild penalty for spreading across many open bins with high mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap - norm_post).abs();

    // New-bin candidate: neutral baseline with slight progress-aware bias
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by 10 are "usable" slots
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -30.0,
        1 | 9 => 12.0,
        2 | 8 => 6.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Fraction-of-capacity coupling: post_residual / capacity thresholds
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.05 {
        score -= 25.0; // near-perfect packing, reward strongly
    } else if frac > 0.5 {
        score += 8.0 * frac; // half-empty bin kept is wasteful
    }

    // Integer division threshold: post_residual / 20
    let div20 = post_residual / 20;
    score -= (div20 as f64) * 3.0;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 20.0;
            // harmonic match of next item with residual class
            if post_residual % 10 == 0 && next_item_size % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 10.0; // dead space relative to lookahead
        }
    }

    // New-bin candidate handling: penalize opening a bin unless current fit is bad
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > mean_residual.max(1.0) * 0.9;
        let last_chance = fitting_bins_count == 1;
        if bad_fit && !last_chance {
            score -= 15.0; // prefer fresh bin over stuffing
        } else {
            score += 50.0; // keep using open bins when fit is fine
        }
    }

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Stream progression: late in stream, be more conservative (favor tight fits)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    // Many open bins: discourage spreading, favor filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual that is too small for the smallest plausible item (1) is never
    // truly "dead", but gaps too small for typical items waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny sliver: nearly unusable
    } else if post_residual < 20 {
        score += 12.0; // small gap: usable only by very small items
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than fragmenting space; penalize lightly scaled
    // by number of open bins.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin gets opened and this residual is stranded.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when many
    // bins are already open; make the empty bin less attractive as
    // open_bins_count grows, but keep it reasonable early on.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 1.5;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, reward this placement (sets up a future perfect fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 15.0; // next item nearly perfectly fits leftover
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for stranding space
        score += 3.0;
    }

    // Mild mean-residual coupling: prefer bins whose residual is below mean
    // (tighter bins), keeping looser bins available for future items.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (consolidate), so add pressure to new-bin candidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled.
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item fits exactly into the leftover space.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to wasted potential.
            let miss = (next_item_size - post_residual) as f64;
            score += 15.0 * (miss / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving a residual well below the mean suggests a good consolidation.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 10.0 * (rel - 1.0).clamp(-1.0, 1.0);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Cost of opening a new bin, amortized by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host the next item too
        }
        if fitting_bins_count > 0 {
            score += 30.0; // discourage new bin when alternatives exist
        }
    }

    // Slight preference for filling bins that are already mostly full.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill;

    // Mild pressure to close out many open bins as stream matures.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - (step_index as f64 / (total_items.max(1) as f64)));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward placements whose leftover can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize dead space that the next item cannot use.
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(40.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Prefer bins whose leftover is "usable-sized" (>= 10) vs tiny scraps.
        if post_residual < 10 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it, else a new bin opens.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when the item fits reasonably well elsewhere.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            // New bin only attractive for very large items or many open bins.
            score += 20.0 - 25.0 * tightness + 0.5 * open_bins_count as f64;
        } else {
            score -= 5.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    } else {
        // Favor bins whose residual is below the mean (filling fuller bins first).
        score -= 0.1 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;
    let mut score = post;

    // Smooth non-linear coupling: post_residual weighted by stream progress
    score += 12.0 * post_norm * post_norm * (0.5 + progress);
    score -= 10.0 * post_norm * (1.0 - progress) * (1.0 - post_norm);

    // Tight fit reward, stronger as stream progresses
    let tight = 1.0 - post_norm;
    score -= 18.0 * tight * tight * tight * (0.4 + 0.6 * progress);

    // Mean residual alignment: prefer bins near mean residual
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Penalize lone fitting bin only early; late, it's precious
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space that fits next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post >= n {
            score -= 9.0 * (1.0 - ((post - n) / cap).abs());
        } else {
            score += 6.0 * ((n - post) / cap);
        }
    }

    // Mild new-bin penalty that decays with progress
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 5.0;
    }

    // Slight preference to fill fewer bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of small sizes) are more attractive.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: strongly favored
    } else {
        // usable-class reward: residual divisible by common item sizes
        let mut usable = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                usable += 8.0;
            }
        }
        score -= usable;
        // dead-space penalty: residuals too small for typical items
        if pr < 10 {
            score += 40.0;
        } else if pr < 20 {
            score += 15.0;
        }
    }

    // Lookahead: does post_residual still admit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward chainability, more if residual is a tight match
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - (slack / cap).min(1.0) * 6.0;
        } else {
            score += 10.0; // bin becomes dead for the next item
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only good when no
    // decent fit exists; penalize it, scaled by how many bins could fit.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * fitting_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
    } else {
        // Tightness reward: prefer bins where the item fills a large fraction.
        let fill = item_size as f64 / bin_residual as f64;
        score -= fill * 15.0;
    }

    // Stream progression: late in the stream, avoid leaving many loose bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.1 * progress;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 100.0;
    }

    // Reward when the lookahead item exactly fits the resulting gap.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // Lookahead cannot use the gap: penalize proportionally.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when current fit is bad
    // (full residual keeps it neutral against well-fitting open bins).
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    }

    // Mild tightness bonus: bins that end up fuller are preferred.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Stream progression: later in the stream, be slightly more conservative
    // about opening bins (pressure scales with progress).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when this placement leaves exactly the next item's size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 50.0 * (1.0 - gap / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 75.0;
        }
        // Penalize residuals too small for next item (dead space)
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer tight fits relative to mean residual
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Late in stream: consolidate into fewest bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: waste-free placement strongly favored.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: penalize leaving a residual the next item cannot use (dead space),
    // reward residuals that the next item can exactly or nearly fill.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // residual too small for next item: dead space unless tiny
            if post_residual > 5 {
                score += 0.15 * post_residual as f64;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more when many bins
    // are already open and mean residual is large (existing capacity available).
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64 + 0.1 * mean_residual;
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins whose residual is already below the mean (consolidation).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Prefer filling bins with small residuals over large-residual bins
    // when the item is large (large items need large holes).
    let frac = item_size as f64 / bin_capacity as f64;
    score += 5.0 * frac * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);

    let mut score = pr + 20.0 * poly;

    // Penalize near-full bins slightly less as stream progresses (waste less matters early)
    let tight_fit = 1.0 - norm_pr;
    score -= 10.0 * tight_fit * tight_fit * (1.0 - progress);

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack_match = 1.0 - ((pr - nxt) / cap).abs();
            score -= 6.0 * slack_match * slack_match;
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly unless residuals are tight
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score += 8.0 * (1.0 - pressure);
    }

    // Mild penalty for many open bins with large mean residual (fragmentation)
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small, awkward" classes (1..=10) are heavily penalized dead space.
    let cap_frac = post_residual as f64 / bin_capacity as f64;

    // Integer division thresholds: classify post_residual into decade classes.
    let decade = post_residual / 10;
    match decade {
        0 => score += 25.0,          // 0..9: tiny dead space, but if 0 it's perfect
        1 => score -= 2.0,           // 10..19: usable for small items
        2 => score -= 5.0,           // 20..29: sweet spot for medium items
        3 => score -= 4.0,
        4 => score -= 2.0,
        5 => score += 1.0,
        6 => score += 3.0,
        7 => score += 5.0,
        8 => score += 7.0,
        _ => {}                      // 90..100: nearly empty bin
    }

    // Perfect fit reward (exact zero residual is ideal).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic coupling with the next item (lookahead k=2):
    // reward residuals that can exactly accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0; // chain of perfect fits
        } else {
            // modulo arithmetic: how "harmonically" the gap divides by item classes
            let gap_mod = gap % 10;
            let harmony = if gap_mod <= 2 || gap_mod >= 8 { 6.0 } else { 2.0 };
            score -= harmony * (next_item_size as f64 / 20.0);
        }
    } else if next_item_size > 0 {
        // next item won't fit here: penalize more if residual is awkward-small
        if post_residual < 10 {
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing bins
    // are poorly harmonized with the item.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; decreases late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 - 8.0 * progress;
        // but if the item is large and nothing fits well, new bin is attractive
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: prefer bins close to the mean residual
    // (keeps the bin population homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Congestion term: many open bins -> prefer filling existing ones tighter.
    score -= (open_bins_count as f64).ln() * 1.5 * (1.0 - cap_frac);

    // Modulo harmonic class of item itself: items in "harsh" classes (e.g. 51..59)
    // pair poorly with residuals; slightly penalize placing them anywhere loose.
    let item_class = item_size % 10;
    if item_class >= 5 && post_residual > 0 && post_residual < item_class {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Penalize gaps too small to fit the smallest plausible next item.
    if next_item_size > 0 && post_residual < next_item_size as f64 {
        score += (next_item_size as f64 - post_residual as f64) * 0.8;
    }

    // Reward when this bin's post-residual exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 30.0;
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Favor bins tighter than the mean residual (good fit).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current bin leaves large dead space.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count <= 1 {
            score -= 25.0; // no real alternative: allow opening new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item exactly matches post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 45.0 * match_quality * match_quality;
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize leaving dead space relative to next item.
        score += 0.35 * ((next_item_size as f64) - (post_residual as f64)).max(0.0);
    }

    // Penalize deviation from mean residual: prefer bins that are either
    // already well-filled (residual below mean) rather than outliers.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.10 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if lookahead matches a fresh bin perfectly and no tight fit exists, allow it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Slight preference to fill bins as stream progresses (reduce open bin count late).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (open_bins_count as f64) / ((open_bins_count + 2) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor small post_residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize placing a small item into a large-residual bin (waste of flexible space).
    score += 0.25 * (bin_residual as f64 - item_size as f64).max(0.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: if the next item fits the post-residual well, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tightness = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * next_tightness;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; mildly penalize leaving awkward leftover.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // If this bin's residual is far from the mean, adjust: high-residual bins
    // should absorb large items; low-residual bins should take small items.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.1 * dev * (1.0 - fit_ratio);

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && (fit_ratio > 0.7 || post_residual == 0);
        if good_fit_exists {
            score += 60.0; // discourage opening new bin when a tight fit exists
        } else {
            // Opening a new bin is fine if item is large and fits nothing well.
            score += 10.0 * (1.0 - fit_ratio);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by small
    // "harmonic denominators" (5, 10, 20, 25, 50) are more reusable by
    // future items, so reward them; prime-ish dead space is penalized.
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    if pr == 0 {
        harmony_bonus += 60.0; // perfect fit: bin closed, ideal outcome
    } else {
        if pr % 50 == 0 { harmony_bonus += 22.0; }
        else if pr % 25 == 0 { harmony_bonus += 15.0; }
        else if pr % 20 == 0 { harmony_bonus += 14.0; }
        else if pr % 10 == 0 { harmony_bonus += 11.0; }
        else if pr % 5 == 0 { harmony_bonus += 7.0; }
        else { harmony_bonus -= 6.0; } // non-harmonic dead space

        // Tiny unusable slivers (1..5) are nearly dead space.
        if pr < 5 { harmony_bonus -= 12.0; }

        // Mid-band leftovers (20..=50) are the most reusable for typical items.
        if pr >= 20 && pr <= 50 { harmony_bonus += 8.0; }
    }
    score -= harmony_bonus;

    // Lookahead coupling: does the leftover's harmonic class admit next_item_size?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits exactly into the harmonic class -> strong reward.
            if pr % next_item_size.max(1) == 0 && pr == next_item_size {
                score -= 30.0; // chain-terminating exact fit for the next item
            } else if pr.saturating_sub(next_item_size) <= 10 {
                score -= 18.0; // leaves only a tiny sliver after next item: bad chain
            } else {
                score -= 9.0; // next item fits with usable remainder
            }
        } else {
            score += 10.0; // leftover cannot host the lookahead item
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the current item is large and
    // no open bin offers a tight fit (post_residual would be large).
    if bin_residual == bin_capacity {
        // Baseline penalty so new bins are opened only when justified.
        score += 12.0;
        if post_residual <= 20 { score -= 40.0; } // large item: fresh bin is efficient
        if fitting_bins_count == 0 { score -= 60.0; } // no alternative at all
        if (post_residual as f64) > mean_residual + 25.0 { score += 15.0; }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.15;
    score -= progress * 4.0 * (fitting_bins_count as f64).recip().min(1.0);

    // Prefer bins whose residual is below the open-bin mean (tighter bins first),
    // keeping larger residuals for future large items.
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 {
        let dead_zone = 20.0f64;
        let severity = (dead_zone - post_residual as f64).max(0.0) / dead_zone;
        score += 45.0 * severity * severity;
        // Gap is "dead" if no plausible item (min size 1..=10) fits well
        if post_residual < 10 {
            score += 30.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Tightness reward: fraction of bin consumed by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Open-bin pressure: discourage spreading when many bins are open,
    // but encourage using existing bins when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.15 + 0.35 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // baseline penalty: prefer reusing bins
        score += 12.0;
        // reward opening a new bin for big items that would leave a bad gap elsewhere
        if item_size >= 60 {
            score -= 10.0 * (item_size as f64 - 60.0) / 40.0;
        }
        // if the next item could combine with this one in a fresh bin, boost new bin
        if next_item_size > 0 {
            let combined = item_size as f64 + next_item_size as f64;
            if combined >= 95.0 && combined <= 100.0 {
                score -= 35.0;
            }
        }
        // many open bins with high mean residual: opening yet another bin is bad
        score += (mean_residual / 10.0).min(20.0);
    } else {
        // Existing bin: reward if the lookahead item also fits the post_residual
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size > 0 && next_item_size <= post_residual + 10 && post_residual > 0 {
            // near-miss lookahead: mild penalty for blocking the next item
            score += 8.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is close to the item
    // (minimizes leftover dispersion across the fleet).
    let residual_gap = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.05 * residual_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills what remains.
            if post_residual == next_item_size {
                score -= 400.0;
            } else {
                // Reward proportional to how snugly the next item fits.
                let slack = (post_residual - next_item_size) as f64;
                score -= 150.0 - slack * 3.0;
            }
        } else {
            // Next item cannot fit here: penalize leaving a gap that is
            // too small to be useful (dead space trap).
            let gap = (next_item_size - post_residual) as f64;
            if post_residual < 10 {
                score += gap * 2.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += (res - mean_residual) * 0.8;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity (open bins would be fragmented) or no good fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin by default...
        score += 300.0;
        // ...unless the item is huge (poor fit anywhere else).
        if fill_ratio > 0.7 {
            score -= 350.0;
        }
        // Late in the stream, avoid accumulating many half-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 100.0;
        // If many bins are open, discourage yet another one.
        score += open_bins_count as f64 * 15.0;
    }

    // Slight preference for fuller bins among ties (compactness).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
    }
    // Penalize leaving a sliver that the next item cannot use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more when
    // alternatives exist or many bins are already open
    if bin_residual == bin_capacity {
        score += 120.0 + 5.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 150.0; // no alternative: must open
        }
    }

    // Prefer filling bins that are already relatively full (tight packing)
    let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * fullness;

    // Divergence from mean residual: avoid creating outliers
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Time horizon: early on, be conservative about tight fits; later, pack aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * fullness;

    // Small tie-breaker against too many open bins
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: dead space squared, normalized by capacity
    let dead = post / cap;
    score += 18.0 * dead * dead;

    // Tight-fit reward: smooth bell around zero post-residual
    let tight = (1.0 - dead).max(0.0);
    score -= 12.0 * tight * tight * item_size as f64 / cap;

    // Stream progress coupling: late in stream, prefer filling bins tighter
    score -= 10.0 * progress * (item_size as f64 / cap);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins when decent fits exist,
    // but allow it early or when item is large and fits poorly
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);
        if item_size as f64 / cap > 0.5 {
            score += 8.0;
        }
        if fitting_bins_count > 0 && post / cap < 0.15 {
            score += 20.0;
        }
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score += 6.0 * gap / cap;
        if next_item_size as f64 <= post {
            score -= 8.0;
        }
    }

    // Mean residual alignment: prefer bins near average residual
    score += 3.0 * ((post - mean_residual) / cap).abs();

    // Mild pressure against proliferating open bins
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: which "slots" of size classes remain.
    // A residual that can still host a mid-size item (>= 20) is valuable.
    let slot_class = (post_residual / 20).min(4); // 0..4 harmonic buckets
    score -= (slot_class as f64) * 12.0;

    // Perfect or near-perfect fit reward.
    if post_residual == 0 { score -= 60.0; }
    else if post_residual <= 5 { score -= 35.0; }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 70.0; }
        else if next_item_size < post_residual {
            // bonus scaled by how snugly next item fits
            score -= 20.0 * (1.0 - (post - next_item_size as f64) / cap);
        } else {
            // next item won't fit here: penalize leaving a large awkward residual
            let waste = post - (next_item_size as f64 % cap);
            if post > 0.0 && next_item_size as f64 > post {
                score += 0.15 * post;
            }
            let _ = waste;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well
    // (i.e., this call is for the empty bin) or mean residual is very small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_item = item_size as f64;
        // Expected usable residual if item placed in fresh bin
        let fresh_post = cap - avg_item;
        score = fresh_post + 30.0
            - 25.0 * (mean_residual / cap).max(0.0).min(1.0)
            - 10.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        score += (fitting_bins_count as f64) * 20.0;
    } else {
        // Prefer bins whose residual is close to item size (tight packing).
        let tightness = (bin_residual as f64 - item_size as f64) / cap;
        score += 25.0 * tightness;
        // Spread load: slightly favor bins below mean residual (keeps variety).
        if (bin_residual as f64) > mean_residual { score += 6.0; }
        // Modulo harmonic: residuals in [0,10] or [40,50] are "dead zones"
        let m = post_residual % 50;
        if m <= 10 { score -= 8.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 25.0; // hard-to-fill gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: reward strongly
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Coupling with mean residual: prefer bins whose residual is close to
    // the item (best-fit behavior), penalize wasteful large-residual bins.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Open-bins pressure: many open bins -> favor consolidating into
    // existing bins; few open bins -> opening a new bin is less costly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 40.0 * progress);
    score += 8.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item would NOT fit here anyway, mild penalty for leaving
    // a mid-sized gap that neither helps nor hurts.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // New-bin candidate: baseline attractiveness of a fresh empty bin,
    // modulated by how bad existing options look (high pressure => open new).
    if bin_residual == bin_capacity {
        score = 45.0 + 10.0 * pressure - 12.0 * fill_ratio;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no real alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward bins whose post residual is tiny.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it uses leftover space.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
            // Bonus for the chain leaving a small remainder after the next item.
            let post2 = post_residual - next_item_size;
            if post2 <= 10 {
                score -= 15.0;
            }
        } else {
            // Next item will NOT fit in the residual: penalize creating dead space,
            // scaled by how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * miss.min(50.0);
        }
    } else {
        // Last item: only the immediate residual matters.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual near the mean are "typical";
    // prefer using bins that deviate upward (wasteful bins) to consolidate.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of every
    // open bin. Penalize the new bin unless open bins are crowded or this fit is bad.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64).ln().max(0.0);
        score += 35.0 + 5.0 * crowding;
        // If the item would leave a large unusable gap in existing bins, opening
        // a fresh bin becomes more attractive.
        if post_residual == bin_capacity - item_size && post_residual > 40 {
            score -= 20.0;
        }
        // If the next item is large and no current bin could chain, a new bin
        // with room for both is valuable.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // Mild consolidation pressure: with many open bins, favor placements that
    // keep post residual small.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Stream progression: late in the stream, be more conservative about new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: later in the stream, tighten up (avoid spreading).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: penalize residuals that cannot host the next item (locked dead space),
    // reward residuals that can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 + 0.5 * (post_residual as f64 - next_item_size as f64).sqrt();
        } else {
            score += 2.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Prefer bins whose residual is below the mean (denser bins) mildly.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // As stream progresses, penalize leaving large residuals more aggressively.
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: add an opening cost so it's chosen only when open bins
    // would waste more space than the fresh bin's initial residual.
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * (1.0 - progress);
        // If no open bin fits at all, opening is inevitable-ish; soften the cost.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth interaction: post_residual vs stream progress — later in the stream,
    // tight packing matters more (penalize large residuals quadratically)
    let prog_coupling = 1.0 + 1.2 * progress * progress;
    score *= prog_coupling;

    // Reward near-perfect fills with a smooth bump around small residuals
    let tightness = (norm_pr * std::f64::consts::PI).cos();
    score -= 4.0 * tightness * (1.0 - norm_pr) * (1.0 - progress);

    // Penalize bins whose residual deviates from the mean (imbalance penalty, smooth)
    let dev = (br - mean_residual) / cap;
    score += 2.0 * dev * dev * pr / cap;

    // Last-chance bonus: only one fitting bin — smooth sigmoid-like reward
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 6.0 * last_chance * (1.0 - norm_pr);

    // Lookahead: if the next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= 5.0 * (1.0 - fit_gap / cap) * (1.0 - progress);
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 0.5 * norm_pr * (1.0 - progress);
        }
    }

    // Mild pressure to close bins as stream progresses: scale by open bins count
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr * progress;

    // New-bin candidate handling: empty bin has moderate default score;
    // prefer it only when fit into existing bins would leave large dead space
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.35 * progress) + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "usable"
    // for common item sizes (multiples of 10 and small classes).
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // Residuals in harmonic classes {0, 10, 20, ...} are ideal; penalize odd remainders
        score += (class as f64) * 0.8;
        // Dead space: residual too small for the smallest item (<= 9) is wasted
        if pr < 10 {
            score += 25.0;
        }
    } else {
        // Perfect fit is the best outcome
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        if pr >= next_item_size {
            // post-residual can host next item: strong reward scaled by tightness
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 + 8.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic bonus if post_residual exactly matches next item size class
            if pr == next_item_size {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to wasted lookahead
            score += 6.0 + (next_item_size as f64 - pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        // baseline penalty so a fresh bin loses to good fits
        score += 30.0;
        // but if current bin would leave a lot of dead space, new bin becomes attractive
        if pr > 0 && pr < 20 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin accommodates growing items
        }
    }

    // Stream progression: early on, be conservative with bin openings; late, pack tight
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    // Prefer bins tighter than the mean residual (good packing density)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Mild penalty per open bin to discourage bin proliferation
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size
    // (1 here, but tiny gaps like 1..=3 are effectively dead) are pure waste.
    // Penalize non-zero small residuals hard.
    if post_residual > 0 && post_residual < 4 {
        score += 60.0 * (4.0 - post_residual as f64);
    }

    // Perfect fit is gold: subtract heavily.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Tight fit reward: the smaller the post_residual relative to capacity,
        // the better the packing density.
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Dead-space shaping: penalize residuals that no plausible item can use,
    // approximated by distance from mean_residual granularity.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < mean_residual.max(1.0) * 0.25 {
        score += 15.0; // gap much smaller than typical residual: likely unusable
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins.
        score += 20.0 + 5.0 * open_bins_count as f64;
        // If the next item is small, a fresh bin is more attractive (keeps
        // large residual for it) — mild discount.
        if next_item_size > 0 && (next_item_size as f64) <= pr * 0.5 {
            score -= 10.0;
        }
        // Never open a new bin when a perfect fit exists elsewhere is handled
        // by the -40 above; also if only one bin fits, opening is bad.
        if fitting_bins_count <= 1 {
            score += 50.0;
        }
    } else {
        // Using existing bins reduces clutter; mild reward scaled by pressure.
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Residual too small for the upcoming item: dead space risk.
        score += 8.0;
    }

    // Early stream: be slightly more willing to open bins (future flexibility);
    // late stream: consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward perfect 2-step match (post_residual == next_item_size)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;

        // Exact match bonus
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Post-residual large enough to host next item exactly is great;
        // too-large post_residual wastes space
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize huge leftover relative to capacity (dead space)
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * 20.0;

    // Prefer fuller bins: tighter fit relative to mean residual
    if mean_residual > 0.0 {
        score += (mean_residual - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless item is large and no good fit exists
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 30.0 - fill_ratio * 25.0;
        // Opening new bin is fine late in the stream with many bins
        if open_bins_count > 3 {
            score -= 5.0;
        }
    }

    // Slight preference for opening bins early when stream is long
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize dead space that can't fit typical items: small post_residual in awkward band.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only this bin fits -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 + 0.5 * next_item_size as f64;
        } else {
            score += 8.0;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * open_bins_count as f64 * (1.0 - t);

    // Pull toward mean residual: prefer bins with residual above mean (keeps diversity).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Late in stream, be more conservative: penalize opening new bins implicitly.
    if bin_residual == bin_capacity {
        score += 30.0 * t + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let poly = prn * prn * (1.0 + progress) + prn * progress * progress;
    score += 8.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - prn;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: penalize residuals that can't hold the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 4.0 * (nx / cap);
        } else {
            let waste = (nx - pr) / cap;
            score += 10.0 * waste * waste;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64;

    // Penalize bins far from mean residual (encourage uniform packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin, less so late in stream or for large items
    if bin_residual == bin_capacity {
        let base = 12.0 - 6.0 * progress;
        score += base * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small
    // "dead" classes (1..9) are wasted space; penalize via modulo structure.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 12.0 - pr as f64; // tiny residuals are hard to fill: strong penalty
    }

    // Integer-division thresholds: reward residuals that are multiples of common
    // item classes (harmonic bins can host future items cleanly).
    let harmonic_bonus = |r: u32| -> f64 {
        let mut b = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if r % m == 0 && r > 0 {
                b += 3.0;
            }
        }
        b
    };
    score -= harmonic_bonus(pr);

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here: mild penalty proportional to overshoot
            score += 2.0 * ((next_item_size - pr) as f64 / cap).min(1.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is justified only when this bin's
    // fit is terrible (large post_residual relative to capacity) or item is huge.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64; // = capacity - item
        let pressure = mean_residual / cap;
        // Prefer new bin when existing bins have little room (pressure low means
        // open bins are nearly full) or when current fit leaves big dead space.
        let open_penalty = 20.0 * (1.0 - pressure);
        let fit_penalty = waste * (waste / cap);
        // Reward opening when item is large (hard to place later).
        let size_bonus = (item_size as f64 / cap) * 15.0;
        score += open_penalty - fit_penalty * 0.3 - size_bonus - harmonic_bonus(pr);
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        }
    }

    // Tight-fit reward: nearly exact fills are excellent.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 6.0 * tightness * tightness;

    // Slight preference to fill earlier bins as stream progresses (reduce spread).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);

    // Tie-break toward bins close to mean residual (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    // Assume smallest item is ~1; treat gaps below 10 as near-dead.
    if post_residual > 0 {
        let dead = (10u32.saturating_sub(post_residual)) as f64;
        score += dead * 6.0;
    }

    // Perfect or near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item can fit exactly in the post-residual,
    // strongly favor this placement (chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the fit is loose.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64) * (2.0 + progress);

    // New-bin candidate baseline: opening a new bin is only attractive when the
    // current fit would leave a large unusable gap.
    if bin_residual == bin_capacity {
        score = 55.0 - item_size as f64 * 0.2;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: prefer tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain placement
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Reward chaining proportionally to how well next item fits the leftover.
            score -= 40.0 * (1.0 - gap / post_residual as f64);
        } else {
            // Next item cannot fit: leftover is likely dead space unless tiny.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score -= 5.0; // negligible waste is fine
            } else {
                score += 0.6 * dead; // penalize stranded usable space
            }
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 6.0 * (1.0 - rel); // better than average residual
        } else {
            score += 4.0 * (rel - 1.0); // worse than average
        }
    }

    // Last-chance bin: strong reward to use it and avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless current
    // fit is poor (large post_residual) and lookahead cannot use it.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.45 * bin_capacity as f64;
        let lookahead_bad = next_item_size == 0 || next_item_size > post_residual;
        if poor_fit && lookahead_bad {
            score -= 12.0; // fresh bin preferable to wrecking a good bin
        } else {
            score += 20.0; // prefer existing bins for reasonable fits
        }
    }

    // Late in stream: consolidate aggressively, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no future item (min size 1..100 unknown, assume >=10)
    // could reasonably fill: post_residual below 10 is wasted.
    if post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: reward bins whose residual after placement matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty scaled by how much it misses
            score += 4.0 * (next_item_size - post_residual) as f64 / 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a new bin; rises with stream progress
        // (late in stream, prefer consolidating into open bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 + 40.0 * progress;

        // If many open bins with slack, opening yet another is worse.
        score += 2.0 * open_bins_count as f64;
        // If the item fits well somewhere (small post_residual elsewhere),
        // opening a new bin should lose; approximate via mean residual.
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
        // Perfect-fit item into fresh bin is fine (item == capacity).
        if item_size == bin_capacity {
            score -= 100.0;
        }
    } else {
        // Prefer bins with less residual overall (fill fuller bins first),
        // scaled by global mean residual to adapt.
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Mild bonus for keeping open-bin count low late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if !is_new_bin {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: waste after placement, with non-linear (quadratic) growth in dead space.
    let mut score = post + 0.35 * (post * post) / cap;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if it almost fits, mildly reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            let overflow = nxt - post;
            score += 4.0 * (overflow / cap).min(1.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Smooth stream-progress coupling: later in the stream, waste matters more
    // (fewer chances to consolidate), so penalize residual progressively.
    score += 6.0 * progress * (post / cap);

    // Mean-residual interaction: if this bin's residual is far below the mean,
    // it's a good consolidator; reward closing the gap.
    let this_residual = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (this_residual - mean_residual) / cap;
        score += 5.0 * rel; // below-mean residual -> negative rel -> lower score
    }

    // New-bin candidate: opening a new bin wastes the aggregate open space.
    // Penalize proportionally to how well existing bins could still absorb items,
    // but relax the penalty late in the stream or when few bins fit the item.
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        let waste_pressure = (mean_residual / cap).min(1.0);
        let mut new_bin_score = 18.0 + 10.0 * waste_pressure * (1.0 - progress) + 2.0 * open.sqrt();
        if fitting_bins_count <= 2 {
            new_bin_score += 6.0 * (1.0 - progress);
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "usable" classes (multiples of common item sizes), penalize dead zones.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual approaches 0.
    score -= (1.0 - pr / cap).powi(8) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic classes: residuals divisible by small harmonics are more
    // likely to be filled later by items of those sizes.
    let harmonic_bonus = |r: u32| -> f64 {
        let mut b = 0.0;
        for h in [10u32, 20, 25, 50] {
            if r % h == 0 && r > 0 {
                b += 6.0;
            }
        }
        b
    };
    score -= harmonic_bonus(post_residual);

    // Penalize residuals in awkward dead zones (1..10) — hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item won't fit here; penalize wasting large residuals.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing bins
    // fit poorly and there are many open bins with scattered residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 - item_size as f64) / cap; // = 0 for new bin
        let avg_fit = (mean_residual - item_size as f64) / cap;
        // Opening a bin is penalized mildly by default; discount when open
        // bins have low mean residual (they are nearly full anyway).
        let open_penalty = 15.0 + 10.0 * progress;
        let discount = if mean_residual < 25.0 { 30.0 } else if avg_fit < 0.15 { 12.0 } else { 0.0 };
        score += open_penalty - discount + 20.0 * poor_fit.abs().min(1.0);
        // Late in stream, prefer closing out existing bins.
        if progress > 0.8 {
            score += 10.0;
        }
    }

    // Mild penalty for bins whose residual deviates far from mean residual
    // (keeps bin population homogeneous, easier future packing).
    score += 0.05 * (pr - mean_residual).abs();

    // Tie-break by harmonic class of item size vs bin residual.
    if bin_residual % 10 == item_size % 10 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps below min item size 1..10 are dead)
    if post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64; // tiny gap: strongly penalized
    } else if post_residual <= 20 {
        score += 5.0; // risky gap zone
    } else {
        // Reward tight fits: perfect fill
        if post_residual == 0 {
            score -= 200.0;
        } else if post_residual <= 30 {
            score -= 10.0;
        }
    }

    // Reward matching next item into the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }
    // Penalize if next item nearly fills residual but misses (wasted potential)
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 8.0;
    }

    // Open bins pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Last chance bin: strong bonus to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        } else if post_residual > 60 {
            score -= 5.0; // fresh bin ok if current fits are poor
        } else {
            score += 30.0; // discourage opening when decent fits exist
        }
    }

    // Mean residual alignment: prefer bins whose residual is below mean (tighter bins)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Progress-based slight tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        // Perfect two-item fill: post_residual == next_item_size -> huge reward
        if diff == 0 {
            score -= 60.0;
        } else if (post_residual as i64) >= (next_item_size as i64) {
            // next item fits too: mild reward scaled by closeness
            score -= (8.0 - (diff as f64).min(8.0)) * 0.8;
        } else {
            // next item won't fit: penalize proportional to leftover dead space
            score += diff as f64 * 0.3;
        }
    }

    // Zero residual is ideal (perfectly full bin)
    if post_residual == 0 {
        score -= 50.0;
    }

    // Small unusable residuals are dead space: penalize tiny nonzero leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual near the mean keeps flexibility; extreme residuals hurt
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += dev * 0.05;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placements
    // would waste a lot. Scale penalty with stream progression.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste = (bin_capacity as f64 - pr) - item_size as f64; // space wasted if item placed alone here
        let _ = waste;
        score += 30.0 + 20.0 * (1.0 - progress);
        // But if no open bin can fit well (large post_residual elsewhere), allow opening
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Slight preference for filling bins with less residual first (best-fit core)
    score += bin_residual as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linearity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Reward near-perfect fits strongly.
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 8 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits: residual is usable, mild reward proportional to how well it fits
            let waste_after = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - waste_after / bin_capacity as f64);
        } else {
            // next item does NOT fit here: large post residual becomes dead space
            score += 15.0 + 0.2 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Compare against global state: penalize bins whose residual is far above mean
    // (they are "hoarding" space), reward bins below mean.
    if bin_residual as f64 > mean_residual {
        score += 0.5 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - bin_residual as f64);
    }

    // New-bin candidate handling: opening a new bin wastes nothing now, but is
    // penalized when open bins already exist and item fits reasonably; allowed
    // (encouraged) when the item is large relative to capacity and fits are bad.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        } else {
            let fill_ratio = item_size as f64 / bin_capacity as f64;
            // Opening is attractive for large items that leave little room anyway.
            score -= 30.0 * fill_ratio;
            // But penalize opening when several bins can already fit the item.
            score += 12.0 * (fitting_bins_count as f64).min(4.0);
            // Later in the stream, prefer consolidating into open bins.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 25.0 * progress;
        }
    }

    // Slight preference to fill fewer bins when many are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = norm_pr * norm_pr;
    let tight_fit = 1.0 - (pr / (bin_residual as f64 + 0.5));
    score -= 3.0 * tight_fit * tight_fit;
    score += 0.5 * norm_pr * progress;
    let lookahead = next_item_size as f64;
    if lookahead > 0.0 {
        let waste = (pr - lookahead).max(0.0) / cap;
        score += 2.0 * waste * waste;
        let perfect = (pr - lookahead).abs() / cap;
        score -= 1.5 * (1.0 - perfect) * (1.0 - perfect);
    }
    if fitting_bins_count == 1 {
        score -= 2.5 * norm_pr;
    }
    let mean_gap = (mean_residual - pr) / cap;
    score += 0.8 * mean_gap * mean_gap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, with diminishing returns.
    score = 12.0 * (post_residual as f64 / bin_capacity as f64).powf(1.5);

    // Harmonic class of post_residual: residues divisible by common item sizes
    // (10/20/25/50) are more reusable than odd dead space.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -40.0 // perfect fit
    } else if pr % 50 == 0 {
        -14.0
    } else if pr % 25 == 0 {
        -10.0
    } else if pr % 20 == 0 {
        -9.0
    } else if pr % 10 == 0 {
        -7.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        4.0 // awkward odd residue: penalize
    };
    score += harmonic_bonus;

    // Lookahead coupling: reward if next item fits in post_residual,
    // extra reward if it also lands on a harmonic class.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0;
            if pr % next_item_size.max(1) == 0 {
                score -= 6.0;
            } else if next_item_size % 10 == 0 && pr % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: mild penalty scaled by gap
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // else we pay for a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // competition among fitting bins: tighten selection pressure
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize spreading across too many open bins with large mean residual;
    // encourage consolidation when mean residual is small.
    score += 0.08 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate logic: opening a new bin is attractive only when
    // existing fits are poor (large post_residual) or many bins compete.
    if bin_residual == bin_capacity {
        // cost of a fresh bin, discounted if the item is large (hard to place later)
        let fresh_cost = 30.0 - 0.25 * item_size as f64;
        // discount if stream is early (amortize the bin over more items)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = fresh_cost * (1.0 - 0.3 * progress);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0; // new bin leaves room for lookahead
        }
    }

    // Small late-stream tightening: prefer tighter fits as stream nears end.
    score += 2.0 * (step_index as f64 / (total_items.max(1) as f64)) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;

    // --- 1. Perfect fit: a bin left at exactly 0 residual is the ideal outcome.
    if post_residual == 0 {
        score -= 500.0;
    }

    // --- 2. Strict dead-space avoidance.
    if post_residual > 0 {
        // 2a. Tiny unusable gaps: residual below the practical minimum item
        // size is almost certainly wasted space; penalize proportionally.
        if pr < 10.0 {
            score += (10.0 - pr) * 15.0;
        }
        // 2b. Lookahead dead zone: if the next item cannot use this gap,
        // the gap is dead at least for the next step; penalize the shortfall.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.5;
        }
    }

    // --- 3. Last-chance bin: if this is the only existing bin that fits,
    // strongly prefer using it over opening a new bin (a new bin costs +1
    // immediately, dead space only costs probabilistically later).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- 4. New-bin candidate (bin_residual == bin_capacity):
    // apply open-bins pressure and late-stream pressure so that opening a
    // fresh bin only wins when it clearly avoids creating dead space in an
    // existing bin (via the penalties raised in section 2).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 {
            step_index as f64 / total_items as f64
        } else {
            0.0
        };
        score += open_bins_count as f64 * 4.0 + progress * 25.0;
    } else {
        // --- 5. Mild consolidation tie-breaker: slightly favor bins whose
        // residual is below the mean (nearly exhausted bins get closed out),
        // without overriding the best-fit ordering from the base term.
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual)
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 30.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize leaving a residual that awkwardly fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual after placement can host next item: good if snug, bad if wasteful
            let leftover = post_residual - next_item_size;
            score += 0.15 * leftover as f64;
            score -= 8.0; // hosting next item is valuable
        } else {
            // next item cannot fit in the leftover: dead space risk
            score += 0.25 * post_residual as f64;
        }
        // If next item fits this bin exactly now, prefer keeping it for the pair
        if item_size + next_item_size <= bin_residual && post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor fits
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= 100;
    if is_new_bin {
        // base penalty so open bins win on decent fits
        score += 60.0;
        // attractive when few bins can fit or mean residual is small (fragmented bins)
        let fit_pressure = 1.0 / (fitting_bins_count as f64 + 0.5);
        score -= 25.0 * fit_pressure;
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // late in stream, prefer consolidating rather than opening
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // large items into fresh bins are fine
        if item_size > 50 {
            score -= 15.0;
        }
    } else {
        // penalize placing into bins whose residual is much larger than needed (waste)
        let waste = (bin_residual - item_size) as f64;
        if waste > 40.0 {
            score += 0.1 * (waste - 40.0);
        }
        // spread load when many bins are open with large residuals
        if open_bins_count > 3 && mean_residual > 50.0 {
            score -= 5.0;
        }
    }

    // mild global pressure: prefer filling existing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post_residual non-linearly (wasted space), scaled by stream progress.
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress);

    // Non-linear polynomial coupling of post_residual with progress.
    let coupling = norm_pr * norm_pr * (0.5 + 1.5 * progress);
    score += coupling;

    // Reward tight fits (small post_residual) more strongly later in the stream.
    score -= (1.0 - norm_pr).powi(3) * (2.0 + 3.0 * progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: penalize mildly unless current bin leaves bad dead space.
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * progress;
        // Opening a new bin is attractive if item fits poorly in existing bins.
        if post_residual < item_size as f64 * 0.15 {
            score -= 3.0;
        }
    }

    // Lookahead: reward bins whose post_residual accommodates next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 1.5 * (1.0 - progress);
    } else if next_item_size > 0 && next_item_size <= item_size {
        score += 0.5 * progress;
    }

    // Coupling with mean residual: prefer bins deviating favorably from mean.
    let dev = mean_residual - pr;
    score += 0.3 * dev * dev / cap;

    // Slight penalty for spreading across many bins.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via squared post-residual penalty
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Harmonic class of post_residual: which "slots" of size 10 remain usable
    let slot = post_residual / 10;
    // Penalize dead space that cannot host typical items (harmonic class thresholds)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if slot < 2 && post_residual >= 10 {
        score += 8.0; // only micro items fit
    }

    // Lookahead coupling: reward if next item fits post_residual, penalize blocking it
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // extra harmony: next item leaves a further clean class
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // spread across bins: mild penalty when many alternatives fit
        score += fitting_bins_count as f64 * 1.5;
    }

    // Prefer filling bins as they accumulate; discourage opening new bins early
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize, less so later in stream or when open bins are crowded
        let crowd = open_bins_count as f64 / 8.0;
        score += 40.0 - 20.0 * progress - crowd.min(20.0);
    }

    // Mean-residual harmony: prefer bins near the mean residual (balanced packing)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;

    // Modular tie-breakers on item size classes
    let item_class = item_size % 10;
    if item_class == 0 {
        score -= 3.0; // round items pack cleanly
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0; // leaves clean harmonic slot
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but typical items >= 10) are pure waste. Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // awkward small gap zone
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill is ideal
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Reward if this placement leaves room exactly for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // decent fits exist; mildly encourage consolidation.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., a very full bin) is good; into a near-empty bin is wasteful.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // New-bin candidate handling: only attractive when no open bin fits well
    // (few fitting bins) or stream is early and consolidation is cheap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.55
            + fitting_bins_count as f64 * 10.0
            - 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 - item_size {
            score -= 10.0; // next item pairs well in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = post_residual - next_item_size;
        let match_quality = 1.0 - (lookahead_waste as f64) / (bin_capacity as f64);
        score -= 20.0 * match_quality * match_quality;
    } else if next_item_size > 0 {
        // Penalize blocking the next item: post_residual too small for it (dead space).
        let blocked = (next_item_size - post_residual.min(next_item_size)) as f64;
        score += 0.35 * blocked;
    }

    // Relative to mean residual: prefer bins with residuals close to (or below) the mean,
    // i.e. consolidate space in already-tight bins.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.08 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Many open bins: prefer filling existing bins over spreading.
    score += 0.02 * open_bins_count as f64;

    // Early in stream: mild preference for opening fresh bins to keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless the item is large relative
    // to capacity or no good fits exist (post_residual == capacity - item on empty bin).
    if bin_residual == bin_capacity {
        score += 14.0;
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // reward but less if leftover after next item would be a sliver
            let after_next = post_residual as i64 - next_item_size as i64;
            score -= 12.0;
            if after_next > 0 && after_next < 10 {
                score += 6.0;
            }
        } else {
            // next item cannot fit here; mild penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: prefer filling a bin as fully as possible.
        score -= 30.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that can fit, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Prefer bins whose residual is below the mean residual (i.e., fuller bins),
    // keeping high-residual bins available for larger future items.
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.35;
    }

    // New-bin candidate handling: only open a new bin when current fits are poor
    // or many bins are already open with large residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open a new bin early in the stream / when open bins are fragmented.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        score += (open_bins_count as f64) * 1.5;
        score += (mean_residual - 50.0) * 0.4;
        // If item is large, opening a fresh bin is relatively more attractive.
        score -= (item_size as f64 - 50.0) * 0.25;
    } else {
        // Mild reward for keeping bins consolidated when many bins are open.
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Small time-dependent noise-free modulation to diversify exploration.
    let phase = ((step_index as f64 * 0.37).sin()) * 1.5;
    score += phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Fractional fill of the bin by this item
    let fill = item_size as f64 / cap;
    let post_frac = post_residual as f64 / cap;

    // Non-linear tight-fit reward: cubic coupling of fill and progress
    let tight = (fill * fill * fill) * (1.0 + 2.0 * progress);
    score -= 40.0 * tight;

    // Penalize dead space quadratically, amplified late in the stream
    score += 30.0 * post_frac * post_frac * (0.5 + progress);

    // Interaction: post_residual relative to mean residual across open bins
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev * dev / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving residual that can host the next item
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= 10.0 * (1.0 - gap / cap) * (1.0 + progress);
        } else {
            score += 0.05 * (-gap) * (0.5 + progress);
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln() * post_frac * 5.0;

    // Smooth new-bin candidate penalty: prefer existing bins slightly
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strong best-fit preference (small post_residual wins).
    score += post_residual as f64 * 0.01;

    // Harmonic class of post_residual: dead space that cannot hold
    // typical small items (1..=10) is nearly worthless; classify by
    // integer division thresholds.
    let dead = if post_residual == 0 {
        0.0 // perfect fit, ideal
    } else if post_residual < 10 {
        // tiny unusable sliver -> heavily penalize
        12.0
    } else if post_residual < 25 {
        4.0
    } else if post_residual < 50 {
        1.5
    } else {
        0.0
    };
    score += dead;

    // Perfect-fit bonus via modulo harmonic classes.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 3.0; // residual aligns with common item granularity
    } else if post_residual % 5 == 0 {
        score -= 1.0;
    }

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + (next_item_size as f64) * 0.05;
        } else {
            // next item won't fit here; penalize proportionally to waste
            score += (next_item_size as f64 - post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: mildly discourage opening new bins when decent
    // fits exist, but encourage when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            0.0
        };
        // high mean residual among open bins -> bins are roomy, prefer them
        score += 5.0 + fragmentation * 10.0;
        // late in the stream, opening fresh bins is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 3.0;
    }

    // Slight penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * open_bins_count as f64 + 10.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            score += 10.0; // next item can't use the leftover gap
        }
    }

    // Slight preference for bins below mean residual (balancing residuals).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let perfect = if post_residual == next_item_size { 25.0 } else { 0.0 };
        score += diff * 0.6 - perfect;
        // Penalize post-residuals too small to fit the next item (dead space risk)
        if (post_residual as u32) < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    } else {
        // Last item: tightest fit is best
        score *= 1.5;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (denser bins)
    score += (mean_residual - bin_residual as f64) * 0.35;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize wasteful placements leaving large awkward gaps
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // tiny leftover is fine, item nearly fills bin
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // awkward mid-range gap
    }

    // New-bin candidate: only open a new bin when existing fits are poor
    if bin_residual == bin_capacity {
        score += 18.0;
        // More willing to open a new bin early when many bins are already open and fragmented
        if open_bins_count > 3 && mean_residual > 40.0 {
            score -= 10.0;
        }
        // Discourage opening new bin if lookahead item could pair with this item
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 15.0;
        }
    }

    // Mild stream-progression pressure: later in stream, tighten packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only one bin fits this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Perfect pairing: item + next item exactly fills the bin.
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Prefer filling bins when many bins are open (contain bin proliferation).
    score -= (open_bins_count as f64) * (post_residual as f64) * 0.02;

    // Bias toward bins whose residual is close to the mean (keep residuals uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, just close out bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * tightness;
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    // New-bin candidate: only attractive when current item is small and
    // no open bin fits well (post_residual would be large).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score = 60.0 + waste * 0.8 - (fitting_bins_count as f64) * 5.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling: prefer tight fits, stronger late in stream
    let tightness = 1.0 - (pr / cap).powi(2);
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize dead space quadratically, modulated by stream progress
    score += 0.35 * (pr * pr / cap) * (0.4 + 0.6 * progress);

    // Reward using nearly-full bins with smooth saturating term
    score -= 6.0 * fill * fill * (1.0 - fill);

    // Last-chance bin: smooth bonus when few fitting bins
    let scarcity = 1.0 / (fitting_bins_count as f64).powf(0.7);
    score -= 8.0 * scarcity * (1.0 - fill);

    // Lookahead: penalize if next item won't fit the post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns > pr {
            score += 5.0 * ((ns - pr) / cap) * (1.0 - progress);
        } else {
            score -= 3.0 * (pr - ns) / cap;
        }
    }

    // Mean residual context: prefer bins diverging from mean smoothly
    score += 0.15 * (pr as f64 - mean_residual).powi(2) / cap;

    // Mild new-bin pressure late in stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 4.0 * progress * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: dead space in low moduli is harder to fill
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Modulo classes on post_residual (harmonic decomposition of residual)
    let m8 = post_residual % 8;
    let m10 = post_residual % 10;
    let m20 = post_residual % 20;
    score += (m8 as f64) * 0.6 + (m10 as f64) * 0.4 + (m20 as f64) * 0.3;

    // Small post-residuals are excellent: reward tight fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Integer-division thresholds: residual that can still host a mid-size item
    if post_residual >= 50 {
        score -= 6.0; // flexible large leftover is fine
    } else if post_residual >= 30 {
        score += 2.0;
    } else if post_residual > 0 {
        score += 10.0; // awkward dead zone
    }

    // Lookahead coupling: if next item fits the post-residual exactly or well, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let fill = nxt / pr;
            score -= 15.0 * fill;
            // harmonic bonus when leftover after next item lands in a good class
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 { score -= 8.0; }
        } else {
            // next item won't fit here; penalize proportionally to its size
            score += 0.15 * (nxt - pr);
        }
    } else {
        // last item: prefer emptying bins completely
        score -= 30.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current fit is terrible
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 18.0;
        // but if the item is large relative to capacity, a fresh bin is attractive
        score -= 0.25 * item;
        // if existing bins are fragmented (high mean residual spread), new bin less bad
        if mean_residual > 40.0 && item > 60.0 {
            score -= 10.0;
        }
    }

    // Capacity-fraction coupling: items that are exact divisors of capacity pack well
    if bin_capacity % item_size == 0 {
        score -= 5.0;
    }

    // Late in stream: consolidate, avoid proliferation of open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

