    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins mildly.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: baseline cost of opening a fresh bin; only attractive
    // when current fit would create bad dead space.
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64 * 0.2;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no real alternative anyway
        }
    }

