    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if no good fit exists (lookahead mismatch everywhere), opening is fine
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Penalize very small dead residuals that are hard to reuse later
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Late in stream: prefer tighter packing, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio;

    // Strongly reward near-perfect fills.
    if post_residual < 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score -= 4.0; // small gap often becomes unusable anyway; finishing is good
    }
    if post_residual > 30 {
        score += (post_residual as f64 - 30.0) * 0.15;
    }

    // Last-resort bin: if this is the only bin that fits, heavily favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward placements that still allow the next item to fit here.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
            // Bonus if next item exactly pairs with leftover space.
            if post_residual == next_item_size {
                score -= 6.0;
            }
        } else {
            score += 1.5;
        }
        // If next item could pair with current item in a fresh bin, discourage
        // fragmenting this bin unless the fit is already tight.
        let pair = item_size + next_item_size;
        if pair <= bin_capacity && fit_ratio < 0.7 {
            score += 2.0;
        }
    }

    // New-bin candidate logic: opening a bin is attractive only when the item
    // fits poorly everywhere else or open bins are highly fragmented.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / bin_capacity as f64) > 0.6;
        let fragmentation = mean_residual / bin_capacity as f64;
        let mut open_bonus = -2.0;
        if poor_fit {
            open_bonus -= 8.0;
        }
        if fragmentation < 0.25 && open_bins_count > 2 {
            open_bonus -= 4.0; // existing bins are nearly full; fresh capacity helps
        }
        if fitting_bins_count <= 1 {
            open_bonus -= 10.0;
        }
        // Early in the stream, keep bin count low; late, allow more bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        open_bonus -= 3.0 * (1.0 - progress);
        score += open_bonus;
    }

    // Mild preference for balancing residuals toward the mean (avoid extremes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight penalty per open bin to discourage unnecessary bin proliferation
    // when fits are comparable.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

