    // New-bin candidate: penalize opening unless residuals elsewhere are very poor
    if bin_residual == bin_capacity {
        let pressure = if mean_residual > 0.0 { mean_residual } else { 0.0 };
        score = 60.0 + pressure * 0.2 + open_bins_count as f64 * 0.5;
        if fitting_bins_count <= 1 {
            score -= 40.0; // opening is fine if no good existing bin
