            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward closeness of match
            let gap = (post_residual - next_item_size) as f64;
            score -= 100.0 / (1.0 + gap);
        } else {
            // next item would NOT fit in this bin's remainder: penalize wasted space
            let gap = (next_item_size - post_residual) as f64;
            score += 50.0 * (1.0 - (gap / bin_capacity as f64).min(1.0));
        }
    }

    // Penalize bins far from mean residual (avoid fragmenting outlier bins)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded/fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 80.0 + 120.0 * crowded - 50.0 * progress;
        // discourage opening new bin if lookahead fits nicely in an existing bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 60.0;
        }
    }

    // Mild preference to keep many bins tight rather than one loose
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tight = (item_size as f64) / (bin_residual as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space: residuals too small for any future item (min size 1, but typical >10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: open a new bin only when existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fill = item_size as f64 / bin_capacity as f64;
        // Big items justify new bins; poor existing fit (large post_residual elsewhere) too.
        score = 45.0 + 55.0 * (1.0 - fill) + 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 18.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity - item_size {
            score -= 15.0;
        }
    }

    // Mild pressure to consolidate when many bins are open with scattered residuals.
    score += 0.15 * open_bins_count as f64;
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, small residuals are acceptable; late in the stream, waste is penalized harder.
    let waste_weight = 1.0 + 2.0 * progress * progress;
    score += waste_weight * (pr / cap) * (pr / cap) * cap * 0.5;

    // Reward tight fits: normalized fill ratio of the current item.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill;

    // If the next item exactly matches the post residual, strongly favor this bin.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = (-diff / 20.0).exp() * 25.0;
        score -= match_bonus;
        // Penalize leaving a residual that is too small for typical next items.
        if (post_residual as i64) < (next_item_size as i64) {
            score += 8.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate handling: penalize opening a fresh bin when open bins fit well,
    // but allow it when residuals across open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
        if fitting_bins_count > 0 && mean_residual > item_size as f64 * 1.2 {
            score += 15.0;
        }
    }

    // Mild penalty proportional to residual deviation from the mean (fragmentation).
    score += 0.15 * (pr - mean_residual).abs();

    // Slight preference for bins with more remaining space when few bins are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fit and near-fit classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space class: residual below minimum item size is pure waste
        if post_residual < 10 {
            score += 200.0;
        }
        // Harmonic classes on capacity fractions: residuals that pair well
        // with common item sizes (multiples of 5/10) are more reusable.
        let pr_mod10 = post_residual % 10;
        let pr_mod5 = post_residual % 5;
        if pr_mod10 == 0 {
            score -= 30.0;
        } else if pr_mod5 == 0 {
            score -= 15.0;
        } else {
            score += 10.0;
        }

        // Integer-division thresholds: classify residual into harmonic bands
        let band = post_residual / 10; // 0..=9 bands
        score += band as f64 * 3.0;    // prefer tighter bins slightly

        // Lookahead coupling: if next item fits exactly into the post residual,
        // strongly reward; if next item is blocked, penalize small residuals.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 120.0;
            } else if next_item_size < post_residual {
                let next_fit_gap = post_residual - next_item_size;
                if next_fit_gap < 10 {
                    score -= 60.0; // near-perfect chaining
                } else {
                    score -= (20.0 * next_item_size as f64) / (next_fit_gap as f64 + 10.0);
                }
            } else {
                // next item cannot use this residual: penalize proportionally
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }

        // Last-chance bin: if this is the only fitting bin, avoid opening a new one
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 80.0;
        }

        // New-bin candidate: penalize opening a fresh bin unless the item is
        // huge and no open bin offers a good harmonic fit.
        if bin_residual == bin_capacity {
            let progress = step_index as f64 / (total_items.max(1) as f64);
            let item_frac = item_size as f64 / cap;
            let open_pressure = open_bins_count as f64 / (mean_residual / cap).max(0.01);
            score += 150.0
                - item_frac * 100.0
                - progress * 20.0
                - (open_pressure.ln().max(0.0)) * 10.0;
            if item_size > 70 && fitting_bins_count == 0 {
                score -= 200.0;
            }
        }

        // Tightness reward: small post residual generally good, but not if
        // it falls in an awkward modulo class for future small items.
        if pr <= 20.0 && pr_mod5 != 0 && pr >= 10.0 {
            score += 25.0;
        }
    }

    // Mild preference for filling bins with larger mean residual (cleanup)
    score -= mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gap that likely becomes dead space for typical items (10..80).
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // If the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here -> this residual is likely dead space.
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's clearly better.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if no existing bin fits well, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += 0.5 * open_bins_count as f64;

    // Progress-aware: late in the stream, prefer consolidating (tight fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Mild attraction toward bins with residuals close to the item (best fit).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) relative to item size.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * (bin_capacity as f64 - post_residual as f64);

    // Aggressive 2-step lookahead: strongly reward when next item fits the post residual exactly or nearly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize when next item cannot follow into this bin.
        score += 0.3 * next_item_size as f64;
    }

    // Penalize post_residual that is far below mean residual (creates unusable dead space).
    if (post_residual as f64) < mean_residual {
        score += 0.4 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.2 * open_bins_count as f64;
    }

    // Slight late-stream tightening: prefer fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bins whose post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Partial reward proportional to how well next item fills leftover space.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * fill;
        } else {
            // Next item can't use the leftover: penalize dead space a bit more.
            score += 3.0;
        }
    }

    // Penalize dead space that can never be used by any future item (min size 1, so mild),
    // but heavily penalize residuals too small for typical items (below 10).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: bin_residual == bin_capacity means a fresh bin.
    if bin_residual == bin_capacity {
        // Default penalty for opening a new bin (fragmentation cost).
        score += 30.0;
        // But if no existing bin fits well (this call would only win when others are bad),
        // and the item is large, opening a new bin is fine: reduce penalty for large items.
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * large_item;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If many bins are already open with high mean residual, prefer consolidation instead.
        score += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    } else {
        // Mild reward for using already-open bins, scaled by how full the bin already is.
        let used = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 5.0 * used;
        // Prefer bins with below-mean residual (fill the emptiest relative bins first
        // keeps a spread of usable residuals for future items).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64 / bin_capacity as f64;
    let lookahead_fit = if next_item_size > 0 && next_item_size <= post_residual { 1.0 } else { 0.0 };
    let tight = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    // quadratic coupling of post_residual with stream progress
    score -= 12.0 * (1.0 - pr).powi(2) * (1.0 - progress) * tight;
    score -= 8.0 * pr * pr * progress;
    // lookahead reward
    score -= 6.0 * lookahead_fit * (1.0 - pr);
    // last-chance bonus
    if fitting_bins_count == 1 { score -= 10.0 * (1.0 - pr); }
    // penalize diverging from mean residual
    score += 0.05 * (post_residual as f64 - mean_residual).abs();
    // penalize too many open bins
    score += 0.1 * open_bins_count as f64 * pr;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post-residual: residues near 0 are "dead" zones
    let post = post_residual;
    let class = post % 10;
    let class_penalty = match class {
        0 => 18.0,          // exact multiple: large unusable chunk unless perfectly filled
        1..=3 => 10.0,      // tiny sliver: nearly dead
        4..=6 => 2.0,       // mid zone
        7..=9 => -4.0,      // leaves room for small items
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual: how many size-10 slots remain
    let slots = (post / 10) as f64;
    score += (slots * slots) * 0.6; // superlinear penalty on wasted slots

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post as f64 / cap);
    score -= 25.0 * tightness * tightness;

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // next item fits: harmonic match reward, stronger if it nearly fills
            let slack = (post - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
            if post % next_item_size.max(1) == 0 {
                score -= 6.0; // exact harmonic division: excellent pairing
            }
        } else {
            // next item won't fit here: penalize based on how far off
            let gap = (next_item_size - post) as f64;
            score += 4.0 + 0.08 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            60.0
        } else {
            // penalize opening new bin when alternatives exist,
            // scaled by how much residual the open bins collectively waste
            40.0 + mean_residual * 0.3 + (open_bins_count as f64) * 2.0
        };
        score += desperation;
        // early stream: opening bins is cheaper to build a portfolio
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below the mean (fill the emptier ones first)
    score += 3.0 * (bin_residual as f64 - mean_residual).max(0.0) * 0.05;

    // Modulo-3 harmonic tiebreak on item size vs residual class
    if bin_residual % 3 == item_size % 3 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many are open; tolerate new bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // New-bin candidate: baseline cost of opening a bin, modulated by how poorly
    // the item would fit existing bins (large mean residual = existing bins are roomy).
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * mean_residual;
        // If next item is large and current item is small, opening a fresh bin
        // may be preferable (keeps big item pairable with current small one).
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 12.0;
        }
        // Early stream: allow more bins.
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead: if the post_residual exactly matches the next item, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual is already the base score).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: if the next item exactly matches post_residual,
    // this is a perfect chain placement -> strong reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 * (-gap / 12.0).exp();
        // Penalize leaving a residual that is too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Penalize bins whose residual deviates upward from the mean (fragmented bins),
    // but only mildly so we don't discourage using tight bins.
    score += 0.08 * (post_residual as f64 - mean_residual).max(0.0);

    // Slight pressure to keep the number of open bins bounded early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only if it beats placing in an open bin.
        score = post_residual as f64 + 3.0 - 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post residual, reward; else penalize
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            score += 6.0;
        }
    }

    // Prefer bins below mean residual (fill emptier bins less when many open)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 15.0 * progress;
    } else {
        // New-bin candidate: penalize when many bins open or early fit exists
        score += 20.0 * progress + 0.5 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Slight preference for larger residual bins to keep flexibility
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Tight fit reward: strong when post_residual small, damped late in stream
    let tight = 1.0 - (pr / cap).powf(2.0);
    score -= 30.0 * tight * (1.0 - progress);

    // Perfect fit bonus
    if pr == 0 { score -= 50.0; }

    // Penalize large dead space, especially if next item can't use it
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr > 0.0 && ni > pr {
            score += 12.0 * (pr / cap) * (ni / cap);
        } else if ni <= pr && pr > 0.0 {
            score -= 8.0 * (ni / pr).min(1.0) * tight;
        }
    }

    // Last-chance bin: reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate handling: prefer reusing open bins early, allow new bin when residuals are fragmented
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress);
        score += 0.5 * mean_residual.min(100.0) * (open_bins_count as f64).ln() / (1.0 + open_bins_count as f64);
    }

    // Non-linear coupling of post_residual with progress: late stream tolerates residual spread less
    score += 10.0 * (pr / cap).powf(1.5) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes
    let cap = bin_capacity as f64;
    let pr = post_residual as i64;
    let nis = next_item_size as i64;

    // Reward tight fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // Modulo-10 harmonic class: residuals divisible by 10 are more reusable
    let pr_mod = pr % 10;
    if pr_mod == 0 {
        score -= 30.0;
    } else {
        score += pr_mod as f64 * 3.0;
    }

    // Lookahead coupling: does next item fit in post_residual?
    if nis > 0 {
        if nis <= pr {
            // good: chain placement possible
            let leftover = pr - nis;
            score -= 40.0 + leftover as f64 * 0.5;
            // harmonic class of leftover after chain
            if leftover % 10 == 0 { score -= 15.0; }
        } else {
            // dead space for next item
            score += 25.0;
            // extra penalty if next item is small (wasteful)
            if nis <= 30 { score += 15.0; }
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 3 {
        score += 5.0 * (fitting_bins_count as f64 - 3.0).min(10.0);
    }

    // New-bin candidate logic: penalize opening new bin unless current fits are bad
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score = cap * 0.35;
        // if few fitting bins, opening new is reasonable
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
        // late in stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // many open bins -> discourage another
        score += open_bins_count as f64 * 4.0;
    }

    // Mean residual coupling: if this bin is far from mean, slight penalty
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Prefer filling fuller bins (harmonic fraction of capacity used)
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    score -= fill_frac * fill_frac * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Small gaps (< 10) are pure dead space; large gaps are still usable.
        if dead < 10.0 {
            score += 40.0 * (10.0 - dead) / 10.0;
        }
        // Nonlinear penalty on leaving less than half the smallest item class.
        if dead < 5.0 {
            score += 25.0;
        }
        // Reward tight fits: exact fill is ideal.
        if dead == 0.0 {
            score -= 30.0;
        }
    }

    // Prefer bins where the post-residual cannot serve the next item,
    // unless it is genuinely dead space anyway.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            // This bin can also host the next item: good chain, reward.
            score -= 12.0 * (nxt / 100.0);
        } else if pr > 0.0 && pr >= 1.0 && pr < nxt {
            // Leftover cannot fit next item; penalize proportionally to waste.
            score += 6.0 * (pr / nxt);
        }
    }

    // Open-bin pressure: discourage opening/using many bins when avoidable.
    // Applied as a mild penalty scaled by how full this bin already is.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is costly; make the empty
    // bin candidate only win when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin; tight fits in existing bins (low
        // post_residual) should beat this.
        score += 55.0 + 0.05 * open_bins_count as f64;
    }

    // Late-stream consolidation: as the stream progresses, prefer packing
    // into already-open bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    // Mean-residual coupling: if the average open residual is large, we can
    // afford loose fits; if small, be pickier about dead space.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this is a perfect chain placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 {
        // Penalize mismatch: wasted space relative to what the next item needs.
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * diff;
        // If next item fits into post_residual, mild reward (chain-friendly).
        if next_item_size < post_residual {
            score -= 20.0;
        }
    }

    // Compare against mean residual of open bins: bins tighter than average
    // should be preferred to consume scarce space.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when all existing fits are poor
    // (post_residual after using an open bin would be tiny/dead) — make the
    // fresh bin mildly expensive so it is chosen only when it wins anyway.
    if bin_residual == bin_capacity {
        score += 150.0 + 10.0 * (open_bins_count as f64).sqrt();
    }

    // Late in the stream, consolidate: prefer filling nearly-full bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space normalized by capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty if post_residual becomes dead space.
            let progress = step_index as f64 / total_items.max(1) as f64;
            if post_residual < 10 {
                score += 10.0 * (1.0 - progress);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins whose residual deviates far above the mean residual (fragmented bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev.abs();

    // New-bin candidate logic: opening a new bin is attractive only when no open bin
    // fits well (large item relative to typical residuals) or many bins already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = item_size as f64 / bin_capacity as f64;
        // Early stream with few bins: prefer filling existing bins.
        let new_bin_bias = 20.0
            + 30.0 * (1.0 - progress)
            - 15.0 * tightness
            + 0.5 * open_bins_count as f64;
        score += new_bin_bias;
        // If item nearly fills a fresh bin, opening one is cheap.
        if item_size >= 90 {
            score -= 40.0;
        }
    }

    // Prefer bins with smaller residual overall (best-fit flavor), scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (amplified penalty on residual);
    // later, tolerate residual spread more smoothly.
    let progress_coupling = 1.0 + 2.0 * (1.0 - progress) * (1.0 - progress);
    score += progress_coupling * (norm_pr * norm_pr) * 20.0;

    // Reward near-perfect fits (post_residual close to 0) with smooth saturating term.
    score -= 15.0 * (-pr / (0.15 * cap)).exp();

    // Penalize residuals that are too small for the typical next item (dead space),
    // but only when the lookahead item cannot use this bin.
    if next_item_size > 0 && next_item_size > post_residual {
        let gap = (next_item_size - post_residual) as f64 / cap;
        score += 12.0 * gap * (1.0 + gap);
    } else if next_item_size > 0 {
        // Reward bins whose residual accommodates the lookahead item smoothly.
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * (-slack * 5.0).exp() * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smooth in fitting_bins_count).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Mild penalty relative to mean residual: avoid leaving this bin far above average.
    score += 2.0 * (pr - mean_residual).abs() / cap;

    // Discard new-bin opening unless the item is large or fits are poor:
    // penalize the empty-bin candidate (bin_residual == bin_capacity) smoothly.
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - norm_item) * (1.0 + progress);
    }

    // Smooth interaction: tightness relative to item size.
    score -= 4.0 * norm_item * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (integer division thresholds).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_class = post_residual / (bin_capacity / 8).max(1); // 8 harmonic classes
    match post_class {
        0 => score -= 12.0,          // near-perfect fit, dead space < 12.5%
        1 => score -= 4.0,           // small but reusable sliver
        2 | 3 => score += 2.0,       // awkward mid-range leftovers
        4 | 5 => score += 6.0,       // half-ish bin: decent but wasteful now
        _ => score += 1.0,           // large residual, still flexible
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward when next item exactly harmonically divides the leftover
            let slack = post_residual - next_item_size;
            if slack < bin_capacity / 8 {
                score -= 4.0;
            }
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement destroys the only fit for the lookahead item: penalize
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the sole fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large (would leave a coherent harmonic class) or nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        // penalize opening new bins mildly; discount late in the stream
        score += 10.0 - 6.0 * progress;
        // a fresh bin with a big item keeps a clean residual class
        if item_frac > 0.5 {
            score -= 4.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Mean-residual alignment: prefer bins whose leftover is close to the fleet mean
    // (keeps residuals harmonized for future items).
    let dev = (post - mean_residual).abs();
    score += 0.08 * dev;

    // Mild preference to fill already-open bins when many are open.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item size (1) are pure waste; residuals below a "usable gap"
    // threshold are heavily penalized non-linearly.
    if post_residual > 0 {
        let dead = (12u32).saturating_sub(post_residual) as f64;
        score += 3.0 * dead * dead / 12.0;
    }

    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 3 {
        score -= 12.0;
    }

    // Reward leaving a gap that can host the lookahead item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 - 0.5 * slack.min(12.0);
    } else if next_item_size > 0 {
        // Lookahead cannot fit in the leftover gap: penalize proportionally.
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // New-bin candidate: opening a bin should lose unless the current fit is bad.
    if bin_residual == bin_capacity {
        score += 14.0;
        // If many bins can fit, opening a new one is rarely wise.
        if fitting_bins_count >= 2 {
            score += 10.0;
        }
        // Last-chance bin exists: strongly discourage opening a new bin.
        if fitting_bins_count == 1 {
            score += 20.0;
        }
        // Early in the stream, allow opening bins more freely.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    } else {
        // Reward using existing bins, more so when they are tightly filled.
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 5.0 * fill_ratio;
        // Last-chance bonus: if this is the only bin that fits, use it.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing ones.
    score += 0.15 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    // Slight preference for bins whose residual is close to the mean
    // (keeps residuals balanced across bins for future flexibility).
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // perfect chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space relative to lookahead: penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 1.5 * gap;
        }
    }

    // Penalize residual far below the mean residual (creating unusable slivers).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.8 * (mean_residual - pr);
    } else {
        score -= 0.2 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: discourage opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // fresh bin chains well with next item
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open new bin
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small post_residual).
    let tightness = post_residual as f64 / cap;
    score -= 40.0 * (1.0 - tightness).powi(6);

    // Penalize residual that is too small to ever be useful again (dead space).
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < next_item_size as u32 && next_item_size > 0 {
        // Residual cannot fit the lookahead item: dead-ish space.
        score += 8.0 + 0.15 * post_residual as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Residual accommodates the next item: reward chaining.
        let chain_left = (post_residual - next_item_size as u32) as f64;
        score -= 12.0 * (1.0 - chain_left / cap);
    }

    // Penalize wasting a large residual on a small item.
    let waste = bin_residual as f64 - item_size as f64;
    score += 0.10 * waste * (waste / cap);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Many alternatives: mild penalty to prefer the best fit among them.
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate logic: open a fresh bin only when the fit here is poor
    // and the item is large (likely to pair well with a fresh bin).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = 1.0 - item_size as f64 / cap;
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else { (waste / cap).max(0.0) };
        let open_bonus = (open_bins_count as f64 * 0.3).min(6.0);
        score = 55.0 - 20.0 * fit_quality - 15.0 * poor_fit - 10.0 * progress + open_bonus;
        // Fresh bin is attractive if item is big and few bins fit it.
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Global state coupling: when mean residual across bins is high, prefer
    // consolidating into bins (avoid spreading), i.e., penalize bins far from mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild time-dependent pressure to keep bin count low later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post_residual), with a smooth polynomial
    // that penalizes both large leftovers and near-zero leftovers that waste space.
    let mut score = 3.0 * x * x + 1.0 * x;

    // Non-linear coupling with stream progress: early on, tolerate leftovers
    // (bins can absorb future items); late in the stream, squeeze harder.
    let progress_coupling = (1.0 - progress) * (x - x * x) * 4.0;
    score += progress_coupling;

    // Penalize residuals that cannot plausibly fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = if pr >= nx { (pr - nx) / cap } else { 0.0 };
        score -= 2.0 * usable * (1.0 + progress);
        // Smooth penalty when post_residual is just barely below next item size.
        let gap = (nx - pr).max(0.0) / cap;
        score += 1.5 * gap * gap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // Slight reward for bins that are already more filled than average.
    let mean_x = (mean_residual / cap).clamp(0.0, 1.0);
    score += 0.5 * (x - mean_x);

    // New-bin candidate: penalize opening a new bin mildly, more when many bins
    // are open and the stream is late.
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * progress + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else {
        // Harmonic class penalty: dead space bucketed by integer division of capacity.
        let class = post_residual / 10; // 0..=9 dead-space class
        score += (class as f64) * (class as f64) * 1.5;
    }

    // Modulo classes on post_residual: values that pair with common small items
    // (residuals in {0, 50, 25, 20, 10} mod 50) are more reusable.
    let m50 = post_residual % 50;
    if m50 == 0 && post_residual > 0 {
        score -= 25.0; // exactly half-full, very reusable
    } else if m50 == 25 || m50 == 20 || m50 == 10 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score -= 40.0;
            }
        } else {
            // next item cannot follow here; penalize slightly more if this bin
            // would be left with awkward residual.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 120.0;
        // If many open bins and item is small, opening new bins is wasteful.
        score += (open_bins_count as f64) * 2.0;
        // But early in the stream, having spare bins is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 40.0;
    }

    // Prefer filling bins that are already relatively full (small residual).
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Mild bonus for keeping mean residual low (balanced packing).
    score -= mean_residual * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever host a future
    // item (below the minimum plausible size) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 2.0 * (10 - post_residual) as f64;
    }

    // Residual that cannot fit the lookahead item is semi-dead if small.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Exact-fit of the lookahead item is highly desirable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Perfect bin match (item exactly fills the current residual).
    if item_size == bin_residual {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation
    // (penalize opening/spreading); the new-bin candidate has max residual.
    if bin_residual == bin_capacity {
        score += 25.0 + 6.0 * open_bins_count as f64;
        // Opening a new bin is acceptable only if no open bin fits well.
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    } else {
        // Slight reward for using existing bins, stronger when few bins fit.
        score -= 3.0 * fitting_bins_count as f64;
        if fitting_bins_count == 1 {
            score -= 10.0; // last-chance bin: strongly prefer using it
        }
    }

    // Prefer bins tighter than average residual (better packing density).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild early-stream bonus for keeping residual balanced for the future.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 30.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow in this bin; penalize leaving awkward gaps
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Compare post_residual relative to mean residual across open bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when good open bins exist
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64;
    }

    // Early in stream: be slightly conservative with tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness ratio: strongly reward near-perfect fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space proportionally, especially tiny leftovers that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // post-residual can't host next item: mild penalty scaled by wasted potential
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full / poor fits.
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count == 0 { 0.0 } else { mean_residual / bin_capacity as f64 };
        // Low mean residual => bins are full => opening new bin is fine.
        score += 55.0 * pressure;
        // Early in the stream, be more willing to open bins (spread items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Prefer filling bins whose residual is close to the item (best-fit core), with mild
    // tie-breaking toward bins that are already well-utilized.
    let utilization = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 4.0 * utilization;

    // Slight penalty when many bins are open and this placement leaves a large residual.
    if open_bins_count > 3 {
        score += 0.02 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: dead space is quadratically worse when small-but-unusable.
    let waste_ratio = post / cap;
    score += 40.0 * waste_ratio * waste_ratio;

    // Reward tight fits with smooth exponential term.
    score -= 30.0 * (-(post / cap * 4.0)).exp();

    // Stream progress coupling: as stream advances, tolerate less residual waste.
    score *= 0.5 + 1.5 * progress;

    // Lookahead: reward residuals that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * fit_tightness;
    } else if next_item_size > 0 {
        score += 8.0; // residual cannot host lookahead item
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize early, relax late when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score += 20.0 * (1.0 - progress) + 15.0 * (1.0 - fragmentation);
    } else {
        // Prefer bins with residual close to (but above) mean: balanced consolidation.
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 6.0 * dev * dev.abs();
    }

    // Mild penalty for proliferating open bins.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" slots
    // (multiples of 10 or small enough to be dead space anyway).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual == 0 -> perfect fit, strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Class B: tiny residual (<= 5) is nearly dead -> mild reward.
    else if post_residual <= 5 {
        score -= 25.0;
    }
    // Class C: residual in harmonic band 6..=15 is awkward -> penalize.
    else if post_residual <= 15 {
        score += 15.0;
    }
    // Class D: multiples of 10 are reusable by typical items -> reward.
    else if post_residual % 10 == 0 {
        score -= 12.0;
    }

    // Lookahead coupling: does the residual still fit the next item?
    if next_item_size > 0 {
        if next_item_size as f64 <= pr {
            score -= 8.0;
        } else {
            // residual becomes dead space relative to lookahead
            score += (pr - (next_item_size as f64)) * 0.3 + 10.0;
        }
        // If next item fits exactly after this placement, big reward.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when nothing decent is open.
    if bin_residual == bin_capacity {
        score = cap * 0.75 + mean_residual * 0.5;
        if open_bins_count == 0 {
            score -= 40.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Prefer fuller bins: scale by fraction used.
        let used_frac = (bin_capacity - bin_residual) as f64 / cap;
        score -= used_frac * 20.0;
    }

    // Stream progression: late in stream, tighten up (waste less).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest possible item (1)
    // are perfect, but small-but-unusable gaps (1..=10) are heavily penalized.
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 4.0; // unusable dead space
    } else if post_residual <= 20 {
        score += 5.0; // awkward zone
    }

    // Tightness reward: filling a bin well relative to its residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and penalize opening/spreading into new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        score += pressure * 6.0 + 10.0; // new-bin candidate penalty
    } else {
        score -= pressure * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item would leave an even worse gap, mildly penalize.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual
        && post_residual < 10 {
        score += 3.0;
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean (balanced use),
    // penalize outliers creating fragmentation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: perfect fill is heavily favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual == next_item_size && next_item_size > 0 {
        // Post residual exactly matches lookahead item: chain placement.
        score -= 300.0;
    }

    // Penalize dead space relative to what could still arrive.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let horizon = 1.0 - t;
    // Late in the stream, leftover space is less likely to be usable.
    score += post * (0.5 + 0.5 * horizon);

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: neutral baseline so it only wins when all
    // open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 0.0; // base = cap - item, already large
        // Slight discount late in stream? No: opening bins is fine anytime.
        // But if item is small relative to capacity, opening a bin wastes space.
        score += (item_size as f64 / cap) * -50.0;
    } else {
        // Reward using already-open bins to consolidate.
        score -= 20.0;
    }

    // Prefer filling bins below mean residual (balancing), avoid spreading.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += dev * 30.0; // bins with more residual than mean are less attractive
    }

    // Lookahead: if next item cannot fit in post_residual and next item is large,
    // the dead space is more costly.
    if next_item_size > post_residual && next_item_size > 0 {
        score += (next_item_size as f64 - post) * 0.5;
    }

    // Mild preference to keep few open bins when many bins exist.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let tightness = 1.0 - fit_ratio;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer filling bins fully (low post_residual). Late: tolerate residual waste.
    let poly = pr * pr / (cap * cap); // normalized quadratic dead-space term
    score += 30.0 * poly * (1.0 - progress);

    // Reward near-perfect fits with a smooth cubic decay on post_residual.
    let fit_bonus = (1.0 - pr / cap).powi(3);
    score -= 25.0 * fit_bonus * (0.5 + 0.5 * progress);

    // Penalize leaving residual that no typical next item can use (fragmentation risk),
    // coupled smoothly with mean residual across open bins.
    let frag = (pr / cap) * (1.0 - (mean_residual / cap).min(1.0));
    score += 15.0 * frag;

    // Lookahead: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - ((pr - next_item_size as f64) / cap);
        score -= 12.0 * snug * snug;
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: smooth urgency term to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins (encourage consolidation),
    // damped non-linearly as the stream progresses.
    score += (open_bins_count as f64).ln() * 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near multiples of a
    // "typical small item" band are more reusable than mid-band dead space.
    let band: u32 = 20;
    let residue = post_residual % band;
    let harmonic = residue as f64 / band as f64; // 0 = perfectly on-class
    // Penalize mid-band dead space (U-shaped penalty, worst at half-band).
    score += 6.0 * (2.0 * harmonic - 1.0).abs();

    // Small post_residual that is a multiple of 10 is highly reusable.
    if post_residual <= 30 && post_residual % 10 == 0 {
        score -= 8.0;
    }

    // Perfect fit: zero waste is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, penalize dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let nxt_res = post_residual - next_item_size;
            if nxt_res % 10 == 0 {
                score -= 10.0;
            } else {
                score += 2.0 * ((nxt_res % 10) as f64);
            }
        } else {
            // Dead space the next item cannot use.
            score += (post_residual as f64) * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual;
    // only prefer it when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        if post_residual as f64 > mean_residual + (item_size as f64) * 0.5 {
            score += 30.0; // discourage opening new bin when decent fits exist
        } else {
            score -= 5.0;
        }
    }

    // Late in the stream, waste matters more; tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // Mild tie-break toward consolidating into fewer bins.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum plausible item
    // are wasted capacity. Penalize them quadratically.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 + 3.0 * (20 - post_residual) as f64;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item if it would fit exactly-ish.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // Penalize if the lookahead item just barely misses the post residual
    // (near-miss dead space for the future).
    if next_item_size > post_residual && (next_item_size - post_residual) <= 10 && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the current
    // item is large and would leave a big, awkward residual elsewhere.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin, offset by its full 100 residual.
        score += 15.0;
        // Large items justify fresh bins; small items should reuse space.
        if item_size > 60 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Open-bin pressure: mildly discourage scattering across many open bins.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins whose residual is close to the mean (keep residuals uniform),
    // penalize deviating from the pool average.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Tight-fit reward: the smaller the waste relative to item, the better.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fits post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item still fits: mild reward proportional to tightness
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space that blocks lookahead
            score += 80.0 * (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64;
        }
    }

    // Tightness relative to capacity: favor bins where item fills a large fraction
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 200.0 * fill_ratio;

    // Relative to mean residual: prefer tighter-than-average bins
    score -= (mean_residual - post_residual as f64) * 2.0;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // New empty bin candidate: penalize unless it's genuinely better
    if bin_residual == bin_capacity {
        score += 250.0;
        // If item is large and few bins fit it, allow opening a new bin
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 200.0;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 100.0 * progress;
    }

    // Slight penalty for many open bins to encourage closing them out
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Favor tight fits: reward small post_residual nonlinearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever fit anything.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly prefer filling it to avoid waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; mild penalty for leaving awkward gap
            score += 5.0 * (post_residual as f64) / cap;
        }
    }

    // Time horizon: early in stream, be conservative (prefer existing bins less,
    // allow new bins to spread); later, pack tightly into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> prefer using them.
    if open_bins_count > 2 {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 0.05 * spread;
        score -= 0.5 * (open_bins_count.min(50) as f64).ln() * tightness;
    }

    // Prefer bins whose residual is close to item size (best-fit core).
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 20.0 * gap * gap;

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score += 15.0 - 25.0 * large;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a non-linear (quadratic/cubic) penalty on wasted space.
    let mut score = pr * (1.0 + 0.9 * norm_pr * norm_pr);

    // Smooth polynomial coupling of tightness with stream progress:
    // early on, mild waste is tolerable; later, waste becomes costly.
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize bins whose post-residual can't fit the lookahead item (dead space),
    // smoothly scaled by how much the lookahead misses.
    if next_item_size > 0 {
        let miss = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 18.0 * miss * (1.0 + miss) * (0.6 + 0.4 * progress);
        // Reward if post-residual still accommodates next item (keeps bin usable).
        let fits_next = ((pr - next_item_size as f64).max(0.0)) / cap;
        score -= 8.0 * fits_next.sqrt();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * tightness;
    }

    // Mild penalty for opening a new bin when many bins are already open and progress is high.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Prefer bins with residual close to mean (keeps residual distribution balanced).
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += 4.0 * dev * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on a
    // "reusable" residue class are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divisible by small harmonics (10/20/25) -> very reusable
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    if post_residual % 20 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }
    // Class B: awkward small dead space (1..=9) -> penalize
    if post_residual < 10 && post_residual > 0 {
        score += 15.0 + (10 - post_residual) as f64;
    }
    // Perfect fit
    if post_residual == 0 {
        score -= 50.0;
    }

    // Fractional fill coupling: reward high fill ratio non-linearly
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 30.0 * fill * fill;

    // Lookahead harmony: if next item fits the post residual exactly or on a harmonic
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 8.0;
            } else if gap < 10 {
                score += 5.0;
            }
        } else {
            // next item cannot use this bin's leftover; slight penalty scaled by leftover size
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter ones (score already via post_residual)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    // Prefer bins below mean residual (tighter bins) mildly
    score -= 0.1 * (mean_residual - pr);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0 || (post_residual as i64 as f64) < 0.0;
        if bad_fit || pr > 0.6 * cap {
            score -= 10.0;
        } else {
            score += 25.0 + 0.2 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure to prefer existing bins when many are open.
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 1.5;
    } else {
        // New-bin candidate: penalize more when many bins are already open.
        score += open_bins_count as f64 * 3.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Deviation from mean residual: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect or near-perfect fit (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly
    // into the post residual (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize proportionally.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.5 * overshoot;
        }
    }

    // Compare post residual against mean residual across open bins:
    // leaving less than average is good (tight packing), leaving more is wasteful.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 30.0 * (1.0 - rel);
        } else {
            score += 30.0 * (rel - 1.0);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Early in the stream, tolerate more bins to keep flexibility;
    // later, consolidate aggressively.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    if progress > 0.7 {
        score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    } else if progress < 0.2 {
        // Slight preference early on for opening fresh bins on poor fits.
        if bin_residual == bin_capacity {
            score -= 20.0;
        }
    }

    // Penalize very large unusable post residuals (dead space) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny slivers are nearly useless
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: item filling most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space: post_residual too small for any item (min size 1 -> treat <12 as dead).
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > post_residual {
            // post_residual wasted relative to next item: mild penalty
            score += 8.0;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin leaves dead space
    // or residual is nearly full (good use anyway).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, opening bins is cheap; later, prefer consolidating.
        let new_bin_penalty = 15.0 + 45.0 * progress;
        // Attractiveness of this bin for a future item: high residual is good.
        let dead = (bin_residual as f64 - item_size as f64) < 12.0;
        score += if dead { new_bin_penalty * 0.4 } else { new_bin_penalty };
        // Slight reward early to spread load when many items remain.
        score -= 10.0 * (1.0 - progress) * (open_bins_count as f64).min(10.0) / 10.0;
    }

    // Global balance: prefer bins whose residual deviates from mean residual
    // in the direction that reduces fragmentation (below mean residual = fuller bin).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Prefer bins with larger residual when item is large (avoid splitting big space badly).
    if item_size > 50 {
        score -= 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer smaller post-residual (tighter fit).
    let mut score = pr;

    // Smooth non-linear reward for near-perfect fits (post_residual close to 0).
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness.powf(6.0);

    // Penalize dead space: unusable slivers relative to smallest possible item (1..100 unknown, use cap-scaled quadratic).
    score += 0.25 * (pr / cap).powf(2.0) * cap * 0.1;

    // Reward last-chance bins (fitting_bins_count == 1) more as stream progresses.
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 15.0 * last_chance * (0.3 + 0.7 * progress);

    // Lookahead: if next item fits into post_residual, reward this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let snug = 1.0 - ((pr - nx) / cap);
            score -= 8.0 * snug.powf(3.0);
        } else {
            // Next item won't fit here; mild penalty proportional to overflow smoothness.
            score += 4.0 * ((nx - pr) / cap).powf(2.0);
        }
    }

    // Prefer bins below mean residual (consolidate waste) — smooth coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev;

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Penalize opening new bins early, allow late when item is large (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score += 10.0 * (1.0 - progress) * (1.0 - item_frac.powf(2.0)) * 2.0;
        // If many open bins already fit the item, discourage new bin.
        if fitting_bins_count > 1 {
            score += 8.0;
        }
    }

    // Mild penalty for too many open bins (fragmentation) as stream progresses.
    score += 0.15 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small dead space" classes (<=10) are excellent, large leftovers are bad.
    let pr = post_residual;
    let dead_class = if pr == 0 { 0.0 }
        else if pr <= 5 { -30.0 }
        else if pr <= 10 { -20.0 }
        else if pr <= 20 { 0.0 }
        else { (pr as f64) * 0.8 };
    score += dead_class;

    // Modulo-10 harmonic: leftovers that are multiples of 10 pair well with
    // typical item sizes (10..80 multiples of 10).
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }

    // Lookahead coupling: reward leftovers that exactly fit next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 40.0;
        } else if pr >= next_item_size {
            score -= 8.0;
        } else {
            // leftover can't host next item: penalize proportionally
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // residual or open bins are already tight.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        let big_item = item_size as f64 / cap;
        score = 55.0 - 20.0 * big_item - 25.0 * (1.0 - pressure);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (bin_capacity - next_item_size) as f64 * 0.1;
        }
    }

    // Late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // Spread penalty: bins far from mean residual are less attractive.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
