        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this bin's leftover: penalize proportionally.
        let waste = next_item_size.min(post_residual);
        score += waste as f64 * 0.5;
    }

    // Compare post residual against the mean residual: leaving a bin far
    // below average residual wastes its potential.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current item is
    // large and no bin fits well (post_residual would be tiny in an open bin).
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Late in the stream, tighten packing: dead space matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.3;

