}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: post residual too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits in post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a sliver that blocks the next item.
        score += 8.0 * (next_item_size as f64 / 100.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 70.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open new bin early (many items remain) and when open bins are crowded.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        score += 0.3 * open_bins_count as f64;
        if mean_residual < item_size as f64 {
            score -= 20.0; // open bins are tight, new bin reasonable
        }
        // If next item is large, fresh bin is valuable.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier space).
    if (bin_residual as f64) > mean_residual {
        score += 4.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Dead-space penalty: small residuals that are hard to fill later
    let dead = (cap * 0.2 - pr).max(0.0) / cap;
    score += 8.0 * dead * dead;

    // Stream-progress coupling: late in the stream, tighten preference for compact placements
    score += 4.0 * progress * norm_pr * norm_pr;

    // Lookahead coupling: reward leaving space usable by the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        score += 0.35 * gap;
        if pr >= ni {
            score -= 3.0 * (ni / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mean-residual coupling: penalize bins far from the fleet mean (keeps residuals balanced)
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: mildly discourage opening new bins when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 6.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by small classes are more reusable.
    let pr = post_residual as i64;
    let mut bonus = 0.0;

    if post_residual == 0 {
        bonus -= 60.0; // perfect fit, ideal closure
    } else {
        // mod-10 harmonic classes: residuals that are multiples of 10 pair well with
        // the typical item grid, so reward them progressively.
        if pr % 10 == 0 { bonus -= 12.0; }
        if pr % 5 == 0 { bonus -= 4.0; }
        if pr % 20 == 0 { bonus -= 6.0; }

        // Integer-division thresholds: small dead space is bad, mid residual is good.
        let q = pr / 25; // coarse class 0..4
        bonus -= match q { 0 => -8.0, 1 => 6.0, 2 => 0.0, 3 => -4.0, _ => -8.0 };

        // Penalize residuals that cannot fit the next item (dead space for lookahead).
        if next_item_size > 0 {
            if post_residual < next_item_size {
                bonus += 10.0;
            } else {
                // reward exact harmonic alignment with next item
                let rem = (post_residual % next_item_size.max(1)) as f64;
                bonus -= (next_item_size as f64 - rem).min(next_item_size as f64) * 0.15;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        bonus -= 25.0;
    }

    // New-bin candidate: only attractive when current bin leaves awkward waste.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        bonus += 15.0 - 10.0 * progress;
        if post_residual > 0 && post_residual < 10 {
            bonus -= 5.0; // fresh bin keeps clean harmonic residual
        }
    }

    // Coupling with mean residual: prefer bins close to mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    bonus += dev * 0.08;

    // Tightness reward: fuller bins first.
    bonus -= (item_size as f64 / bin_capacity as f64) * 8.0;

    score += bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
