pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect two-step match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize residuals too small for the lookahead item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Mild reward when post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Penalize deviation from mean residual: avoid wasting bins with large residuals
    // while others are tight, and avoid over-tightening.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave large waste
    // or no bin fits well. Penalize opening new bins by default, scaled by stream progress.
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (step_index as f64 / total_items.max(1) as f64);
        // But if placing here would create a near-perfect lookahead match later,
        // an empty bin is fine (it starts at capacity residual).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Slight preference for tighter fits overall.
    score += (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual preferred).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize small dead space that is hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; mild penalty proportional to wasted potential.
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Global state: with many open bins, prefer consolidating into existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open new bins (score for
    // new bins relative), late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus early-stream discount.
        let mut new_bin_score = 45.0 - 25.0 * progress;
        // If item is large relative to capacity, opening fresh is safer.
        new_bin_score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If mean residual across open bins is small, existing bins are nearly full anyway.
        new_bin_score += 0.3 * mean_residual;
        // If next item is large too, a fresh bin may host both.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            new_bin_score -= 6.0;
        }
        score = new_bin_score;
    } else {
        // Existing bin: late in stream, push harder toward tight packing.
        score -= 10.0 * progress * tight;
    }

    // Mean residual coupling: if this bin is far below mean residual (already tight),
    // slight bonus to keep using it; if far above, mild penalty.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Penalize residuals that are unusable for typical items (dead space),
    // with a smooth cubic term.
    score += 8.0 * norm_pr * norm_pr * (1.0 - norm_pr) * cap;

    // Reward tight fits: low post_residual relative to item size.
    score -= 12.0 * (1.0 - norm_pr) * (item_size as f64 / cap);

    // Lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins with residuals close to the mean (balance load) smoothly.
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize opening a new bin, more so early on and
    // when existing bins fit the item well.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 20.0 + 25.0 * (1.0 - progress) + 10.0 * (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0));
        score += new_bin_penalty;
    }

    // Mild penalty for accumulating many open bins late in the stream.
    score += 0.3 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residuals are dead space
    let pr = post_residual;
    if pr > 0 {
        // penalize residuals below the smallest possible item
        if pr < 10 {
            score += 60.0;
        }
        // harmonic classes via integer division thresholds
        let class = pr / 10; // 0..10
        score += (class as f64) * 1.5;
        // modulo coupling: residuals like 50 (half-capacity) are valuable
        if pr % 50 == 0 {
            score -= 8.0;
        } else if pr % 25 == 0 {
            score -= 4.0;
        }
        // penalize odd/awkward residues in low range
        if pr < 35 && pr % 10 != 0 {
            score += 12.0;
        }
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= pr {
        score -= 15.0;
        // exact chain fit bonus
        if pr == next_item_size {
            score -= 20.0;
        }
        // next item leaves good residue too
        let post2 = pr - next_item_size;
        if post2 % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > pr && pr > 0 {
        // next item can't follow here; mildly penalize unless residual is tiny anyway
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current options are poor
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer fuller bins relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.3;

    // slight preference for bins with tighter residual than average
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 12.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual tightly matches the item (waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 30.0;

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 8.0;
    } else if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= -0 {
        score += 6.0;
    }

    // Open-bin pressure: discourage proliferation of bins, more so late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (0.5 + progress);

    // Mean-residual coupling: prefer bins close to the mean residual (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    // New-bin candidate: only attractive when this would create a large fresh residual
    // while current fit is poor; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leaving awkward residual after both
            let after_next = post_residual as i64 - next_item_size as i64;
            if after_next > 0 && after_next < 10 {
                score += 50.0; // small dead space after two placements is bad
            } else {
                score -= 30.0; // chain-friendly residual is good
            }
        } else {
            // next item does NOT fit here: penalize more if residual is small-but-not-tiny
            let r = post_residual as f64;
            if r < next_item_size as f64 {
                score += (next_item_size as f64 - r) * 0.8;
            }
        }
    }

    // Prefer tight bins relative to mean residual
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    } else if fitting_bins_count > 1 {
        score += 10.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.6 {
            score -= 120.0 * fill_frac;
        } else {
            score += 80.0; // don't open new bins for small items
        }
    }

    // Slight preference for keeping few open bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small dead space (unusable gaps)
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 15.0 * (10.0 - gap);
        }
        // Reward post_residual that could fit the next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > 0 {
            score += 4.0;
        }
    } else {
        // Perfect fit
        score -= 20.0;
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when fit is bad or stream is early
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = fit_ratio < 0.5;
        if bad_fit && progress < 0.6 {
            score -= 10.0;
        } else {
            score += 30.0 + 10.0 * (1.0 - progress);
        }
    }

    // Prefer bins with residual below mean (consolidate small gaps)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Slight preference for fewer open bins when many bins fit
    if fitting_bins_count > 2 {
        score -= 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = norm_pr * norm_pr * (1.0 + progress);
    score += norm_pr * (1.0 - progress) * 0.5;
    score -= (item_size as f64 / cap) * (1.0 - norm_pr);
    if fitting_bins_count == 1 {
        score -= 0.75;
    }
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.3 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 0.2 * norm_pr;
    }
    score += (open_bins_count as f64) * 0.01 * (1.0 - norm_pr);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit base with tightness reward: exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small leftovers are dead space.
    // Class boundaries at multiples of capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: post_residual <= 10 -> nearly perfect, strong reward.
    if post_residual <= bin_capacity / 10 {
        score -= 40.0;
    }
    // Class 2: 10 < post_residual <= 20 -> still useful for small items.
    else if post_residual <= bin_capacity / 5 {
        score -= 15.0;
    }
    // Class 3: awkward dead zone (21..=33): penalize heavily.
    else if post_residual <= bin_capacity / 3 {
        score += 25.0;
    }
    // Class 4: moderate leftover (34..=50): neutral-ish, slight penalty.
    else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    }
    // Class 5: large leftover: fine, bin stays flexible.
    else {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Reward proportionally to how well next item uses the leftover.
            let fit_ratio = next_item_size as f64 / pr;
            if fit_ratio > 0.8 {
                score -= 60.0 * fit_ratio;
            } else if fit_ratio > 0.5 {
                score -= 20.0 * fit_ratio;
            }
        } else {
            // Next item won't fit here: leftover likely wasted; penalize
            // proportionally to how close it was (frustration penalty).
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 10.0 {
                score += 30.0 - 2.5 * miss;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // all existing residuals are poor fits for the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 120.0;
        // Reward opening when few bins fit the item (scattered state).
        if fitting_bins_count <= 1 {
            score -= 150.0;
        }
        // If the item is large relative to capacity, new bin is safer.
        if (item_size as f64) > 0.6 * cap {
            score -= 40.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 * progress;
        // Many open bins with high mean residual: reuse them instead.
        if mean_residual > (item_size as f64) {
            score += 50.0;
        }
    } else {
        // Mild reward for choosing bins with residual close to item size
        // (tight packing) among open bins.
        let tightness = 1.0 - (bin_residual - item_size) as f64 / cap;
        score -= 10.0 * tightness;
        // Prefer bins that differ from mean residual (specialization).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 2.0 * (dev / cap).min(1.0);
    }

    // Harmonic modulo structure on post_residual: residues that align with
    // common item sizes (multiples of 5/10) are more reusable.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 12.0;
    } else if mod10 == 5 {
        score -= 6.0;
    } else if mod10 >= 8 || mod10 <= 2 {
        score -= 2.0;
    } else {
        score += 4.0; // residues 3,4,6,7 are awkward
    }

    // Integer-division threshold: post_residual divisible into halves of
    // typical small items is good.
    if post_residual % 2 == 0 && post_residual >= 20 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: small gaps (< 10) are unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Moderately small gaps are less flexible.
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: penalize leaving a gap that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 10.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Open bins pressure: when many bins are open, discourage spreading to new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure,
        // but relax the penalty if residuals across open bins are small (fragmented bins).
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 30.0 + pressure * 2.0 - fragmentation * 40.0;
    } else {
        // Slight preference for reusing bins over opening new ones.
        score -= 5.0;
    }

    // Mild penalty for deviating far from mean residual (prefer balanced fills).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: next item exactly fills this bin afterwards.
        if post_residual as i64 == next_item_size as i64 {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item fits here later: reward closeness of the fit.
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space relative to the next item: penalize proportionally.
            score += gap * 0.35;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are more valuable to fill.
    let rel = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * rel;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // (unless it is the fresh-bin candidate with full residual).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny unusable slivers (<10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Fresh-bin candidate: only attractive when current bins would leave large waste
    // or none fit well; mild base penalty keeps it as a fallback.
    if bin_residual == bin_capacity {
        score += 6.0;
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer bins with larger current residual consumed well (tight overall fit).
    score -= 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post-residual (subtract).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty scaled by wasted gap
            score += 3.0;
        }
    } else {
        // Last item: minimize post residual aggressively.
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        // Base cost of opening a bin, modulated by global state.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 55.0 + 25.0 * progress + 2.0 * congestion;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Prefer bins whose residual deviates from mean in a useful way (below mean = tighter bin).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.3 * open_bins_count as f64 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post-residual with stream progress:
    // tight fits (small post_residual) rewarded more strongly later in the stream.
    let tightness = (1.0 - norm_pr).powi(3);
    score -= tightness * (1.0 + progress) * 30.0;

    // Penalize very small dead space that is unlikely usable (smooth bump around tiny residuals)
    score += (1.0 - norm_pr).powi(6) * 10.0 * (1.0 - progress);

    // Reward filling a bin nearly exactly, scaled by progress
    score -= (norm_item * norm_item) * (1.0 + progress) * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead: reward residual that can fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - pr / (nxt + cap)) * (1.0 + progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure to prefer bins below mean residual (consolidate large gaps)
    score += (mean_residual - pr) * 0.05;

    // Encourage opening new bins early when item is small relative to capacity
    if bin_residual == bin_capacity {
        score += 12.0 * norm_item * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // small classes (fits common item sizes) are rewarded; dead-space classes penalized.
    let post = post_residual as i64;
    let cap = bin_capacity as f64;

    // Dead-space penalty grows super-linearly for residuals that are too small
    // to fit any plausible item (assume min item ~10).
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0; // unusable sliver
    } else {
        // Reward residuals that are exact multiples of common class sizes
        // (harmonic classes via modulo arithmetic).
        let r = post_residual;
        let mut harmony = 0.0;
        for &m in &[10u32, 20, 25, 50] {
            if r % m == 0 {
                harmony += 8.0 + m as f64 * 0.15;
            }
        }
        score -= harmony;

        // Integer-division thresholds: residual in [next_item_size, next_item_size + 15)
        // perfectly hosts the lookahead item -> strong reward.
        if next_item_size > 0 && next_item_size <= r {
            let slack = r - next_item_size;
            if slack <= 15 {
                score -= 14.0 - slack as f64 * 0.4;
            } else {
                score -= 4.0; // can at least host the next item
            }
        } else if next_item_size > 0 {
            score += 6.0; // next item cannot follow here
        }
    }

    // Fraction-of-capacity coupling: prefer filling bins past half capacity.
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    if fill_frac > 0.5 {
        score -= (fill_frac - 0.5) * 20.0;
    } else {
        score += (0.5 - fill_frac) * 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or the stream is nearly done and many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual < 10 || (next_item_size > 0 && next_item_size > post_residual);
        if !bad_fit {
            score += 30.0 + open_bins_count as f64 * 0.5 - progress * 10.0;
        } else {
            score += 5.0;
        }
    }

    // Mild pressure toward consolidating residuals near the mean.
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let tiny_gap = 12.0;
    if post_residual > 0 && post_residual < tiny_gap {
        score += (tiny_gap - post_residual as f64) * 6.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    // Penalize residual that no plausible future item can use (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item cannot fit in post_residual, mild penalty for wasted potential.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Last-chance pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, avoid fragmenting further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.4 * (0.5 + progress);

    // Prefer bins with residual close to mean residual (balance load lightly).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 18.0 - 12.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain
        } else if post_residual >= next_item_size {
            // next item fits; reward tightness of the chain
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            let dead = post_residual as f64;
            score += 0.5 * dead * (dead / 20.0).min(2.0);
        }

        // two-step lookahead: does post_residual - next fit plausible small items?
        if post_residual > next_item_size {
            let rem = (post_residual - next_item_size) as f64;
            if rem < 10.0 { score += 8.0; } // tiny unusable sliver after chain
        }
    }

    // Tight fit reward relative to capacity
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Compare against mean residual: prefer consuming below-average residual bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Early in stream: keep bins flexible; late: pack greedily
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.15 * post_residual as f64;

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact or near-exact placement is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * tightness * 40.0; // quadratic penalty for wasted space
    }

    // Penalize residuals too small to hold any plausible future item (dead space),
    // except when the fit is exact.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward;
    // if the next item would fit but this placement leaves it barely fitting, penalize.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 80.0;
        } else if (post_residual as u32) >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.15;
        } else {
            // next item cannot fit here; slightly reward leaving compact residuals
            score += 2.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is bad when the item fits well somewhere else.
        // Base cost of a new bin, discounted when many bins are already open
        // (consolidation pressure) or when the stream is near its end.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 55.0 * (1.0 - 0.3 * progress);
        if open_bins_count > 4 {
            new_bin_cost += 10.0;
        }
        // If the item is large relative to capacity, a fresh bin is more attractive.
        new_bin_cost -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // If no existing bin fits (fitting_bins_count==1 refers to the new bin itself
        // being counted), the cost is effectively zero elsewhere; keep moderate.
        score += new_bin_cost;
    }

    // Mild preference for filling bins below the mean residual (balance avoidance):
    // placing into bins with larger residuals than average keeps small bins available.
    if bin_residual < bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.05;
    }

    // Late-stream pressure: as the stream ends, prefer packing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (small post_residual), quadratic in normalized residual.
    let norm_post = post / cap;
    let mut score = post * (1.0 + 2.0 * norm_post * norm_post);

    // Smooth stream-progress coupling: later in the stream, tight fits matter more.
    score *= 1.0 + 1.5 * progress * (1.0 - progress + 0.5 * progress * progress);

    // Reward filling a large fraction of the bin with this item.
    score -= 0.6 * item * (1.0 + progress);

    // Last-chance bonus: only one bin fits; strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // Penalize bins whose residual deviates far below the mean (fragmented dead space),
    // unless this placement fixes it (small post_residual).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.2 * (dev * dev) * (1.0 - progress);

    // Lookahead: if next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0);
        // Penalize leaving a residual just barely too small for the next item.
        if post < nxt && post > 0.0 {
            score += 4.0 + 3.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: penalize opening a bin unless the item is large relative to capacity
    // or the stream is early and no good fits exist.
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * (1.0 - item / cap) - 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Slight penalty for accumulating many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes are more likely to be completed by future items.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Reward tight fits: quadratic penalty on wasted space.
    score += 0.35 * (frac * frac) * cap;

    // Dead-space penalty: residual too small for the smallest plausible item
    // (harmonic class of residue mod 10) is nearly worthless.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Modulo-class logic: residuals in [30,60) pair well with typical items;
    // reward mid-range leftovers slightly, penalize extremes.
    let class = post_residual % 30;
    if class >= 10 && class < 25 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // partial reward scaled by how much slack remains after next item
            let after = post_residual - next_item_size;
            score -= 15.0 * (1.0 - after as f64 / cap);
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    // or stream is early and many bins may pay off later.
    if bin_residual == bin_capacity {
        score += 55.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if frac > 0.75 {
            score -= 30.0; // very poor fit -> new bin is fine
        }
        if progress < 0.15 && open_bins_count < 4 {
            score -= 12.0;
        }
    }

    // Slight pressure to consolidate: prefer bins with below-average residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (dead space elimination)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 500.0;
    } else if post_residual <= 20 {
        score -= 150.0;
    }

    // 2-step lookahead: if the next item fits perfectly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 100.0;
        } else {
            // next item won't fit here: penalize leaving large unusable gap
            score += (next_item_size - post_residual as u32) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 250.0;
        // allow new bin if item is large and no tight fit available
        if item_size > 60 && fitting_bins_count <= 1 {
            score -= 400.0;
        }
    }

    // Prefer bins with below-mean residual (tighter packing targets)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight preference for fewer open bins as stream progresses
    score += open_bins_count as f64 * 0.1;

    // Mild progression term
    score += (step_index as f64 / total_items.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 24.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && post_residual < next_item_size as u32 {
            (next_item_size as u32 - post_residual) as f64
        } else {
            0.0
        };
        score += 1.6 * dead;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Prefer fullest bins (small residual relative to mean).
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Discourage opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (fitting_bins_count as f64).max(1.0);
        score += 14.0 / pressure + 6.0 * (1.0 - progress);
        // Allow new bin if item is large and existing residuals are fragmented.
        let large_item = item_size as f64 > 0.6 * cap;
        if large_item && mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with smooth polynomial shaping.
    let mut score = norm_pr * norm_pr * (2.0 + 3.0 * (1.0 - progress));

    // Dead-space penalty: residuals too small for typical items are wasted; smooth cubic.
    score += 0.6 * norm_pr * norm_pr * norm_pr * cap * 0.1;

    // Lookahead coupling: reward bins whose post_residual can hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 1.5 * (1.0 - slack) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Penalize post_residual that is close-but-too-small (awkward dead space).
        let gap = (next_item_size - post_residual) as f64 / cap;
        score += 1.2 * gap * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 + 2.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist,
    // but allow it when remaining items are large relative to residuals.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 10.0;
        } else {
            let avg_fill = 1.0 - (mean_residual / cap);
            let item_frac = item_size as f64 / cap;
            // open new bin more readily when existing bins are poorly utilized
            score += 1.0 + 2.0 * avg_fill - 0.5 * item_frac - 0.8 * progress;
        }
    }

    // Mild preference for filling bins with high residual when many bins are open.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: low-class residues (0..=10) are near-perfect fits.
    let post_class = post_residual % 25;
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else if post_class <= 10 {
        score -= 30.0 - post_class as f64;
    } else if post_class >= 15 && post_class <= 20 {
        score += 10.0; // awkward mid-range residue
    }

    // Integer-division thresholds: penalize leaving residue that next item could not use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward if next item fits with small leftover (harmonic chaining)
            let chain_left = post_residual - next_item_size;
            if chain_left <= 10 {
                score -= 25.0;
            } else {
                score -= chain_left as f64 * 0.2;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the current
    // bin would be badly fragmented (large dead residue relative to next item).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score = 60.0 + 40.0 * progress - 50.0 * fragmentation;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Mild bonus for keeping bins balanced with the mean residual.
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item
    // (assume min item ~10, but scale with stream knowledge: min possible = 1).
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // Exponential blow-up for near-zero waste
        score += (dead_threshold - post_residual as f64).powf(2.0) * 4.0;
    }

    // Perfect fit bonus: strong reward for exactly filling the bin
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: reward small post_residual relative to item size
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= (1.0 - tightness.min(1.0)) * 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave
    // a bad gap or is already well-filled. Reward new bin only for large items.
    if bin_residual == bin_capacity {
        // Neutral base for new bin: post_residual = capacity - item_size
        // Penalize so we prefer existing bins with good fits
        score += 20.0;
        // But if the item is huge relative to capacity, opening fresh is fine
        if item_size as f64 > bin_capacity as f64 * 0.7 {
            score -= 30.0;
        }
        // If no existing bins fit (this is the only candidate), fitting_bins_count
        // includes only this new bin; soften penalty
        if open_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into fewer bins,
    // penalize placements that leave large residuals when bin count is high.
    if open_bins_count > 3 {
        score += (open_bins_count as f64 - 3.0) * 0.8;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this placement
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize if next item cannot fit in post_residual but this bin could have held more
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Mean residual coupling: prefer bins whose post_residual is close to the mean
    // (keeps bin states uniform, easier future packing)
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.15;

    // Stream progression: late in the stream, be stricter about waste
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 500.0; // exact 2-step chain: perfect
        } else if next_item_size < post_residual {
            let new_post = pr - ni;
            // reward small residual after chaining, with dead-space penalty for tiny leftovers
            score -= 300.0 * (1.0 - new_post / bin_capacity as f64);
            if new_post > 0.0 && new_post < 10.0 {
                score += 80.0; // unusable sliver after chain
            }
        } else {
            // next item can't chain here; penalize proportionally to overflow gap
            score += 60.0 * (ni - pr) / 100.0;
        }
        // if next item is huge, prefer keeping small residuals for it elsewhere
        if next_item_size > 50.0 && pr < next_item_size as f64 {
            score += 40.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 120.0;
        // but if mean residual is small (all bins tight), opening is fine
        score -= 150.0 * (mean_residual / bin_capacity as f64).min(1.0);
        // large item with no good fit: new bin attractive
        if item_size > 60 {
            score -= 60.0;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Small post-residual is generally good (tight packing), scaled by progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * (50.0 + 50.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical next item.
    if post_residual < next_item_size && post_residual > 0 {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Reward using the last fitting bin before opening a new one.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits
    // very poorly in existing bins or there are no open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_penalty = (bin_capacity - item_size) as f64;
        let mut open_cost = waste_penalty * (0.5 + 0.5 * (1.0 - progress));
        // If item leaves a large hole in any existing bin anyway, allow new bin.
        if fitting_bins_count == 0 {
            open_cost -= waste_penalty;
        }
        score += open_cost;
    }

    // Prefer bins with residual close to item size (best-fit flavor) with
    // a non-linear coupling to the global mean residual.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap * gap / (bin_capacity as f64);
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Lookahead: favor bins whose post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Slight preference for filling already-open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (small post_residual), non-linearly amplified.
    let mut score = post * (1.0 + 0.8 * post / cap) + 6.0 * (post / cap).powi(3) * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space matters more.
    score += 30.0 * progress * (post / cap).powi(2) * (1.0 - progress * 0.5);

    // Reward filling a bin nearly completely (smoothly).
    score -= 25.0 * (item / cap).powi(2);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        score -= 18.0 * (1.0 - diff / cap).max(0.0);
        // Penalize leaving a gap just below the next item size (dead space).
        if post < nxt {
            score += 12.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: empty bin. Penalize opening new bins mildly, but
    // allow it when existing residuals are large relative to the item.
    if bin_residual == bin_capacity {
        let tightness = (mean_residual / cap - item / cap).max(0.0);
        score = 55.0 + 45.0 * progress - 30.0 * tightness;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
    }

    // Mild penalty for bin proliferation.
    score += 0.15 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit reward: post_residual exactly 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Classify residual into harmonic bands of capacity: (0,10], (10,25], (25,50], (50,100]
        let band = if pr <= cap * 0.10 { 0 }
                   else if pr <= cap * 0.25 { 1 }
                   else if pr <= cap * 0.50 { 2 }
                   else { 3 };
        // Penalize large dead space quadratically.
        score += band as f64 * band as f64 * 8.0;
        // Wasted fraction penalty.
        score += (pr / cap) * 40.0;
    }

    // Integer-division thresholds: can a "typical" next item (classes of 20) fit?
    let slot_class = post_residual / 20; // 0..5 harmonic slot classes
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item still fits here: reward, more if slot class is tight (good packing).
            score -= 15.0 + slot_class as f64 * 2.0;
            // Extra reward if next item leaves another near-perfect residual.
            let npr = post_residual - next_item_size;
            if npr <= 5 { score -= 20.0; }
        } else {
            // Next item won't fit: penalize, worse if this bin is the only option.
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep it attractive only when current fit is bad
    // and residuals across bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // A fresh bin has huge residual; counteract its raw score so it wins
        // only when the best existing fit is poor (large post_residual or no fit).
        score -= 70.0 + 30.0 * (1.0 - progress);
        // Penalize opening bins when many are already open with slack.
        score += open_bins_count as f64 * 3.0;
        if mean_residual > cap * 0.5 { score += 25.0; }
    }

    // Mild bonus for filling tight bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever hold
    // another item are pure waste. Penalize them super-linearly.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        // unusable sliver: dead space
        score += (10.0 - pr) * 12.0;
    } else if post_residual == 0 {
        // perfect fit: strongly reward
        score -= 40.0;
    }

    // Reward tight fits relative to item size (waste ratio).
    let waste_ratio = pr / (item_size as f64 + 1.0);
    score += waste_ratio * 6.0;

    // Penalty if this residual cannot fit the lookahead item but the bin
    // would otherwise be "almost" useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward if lookahead fits exactly into the post residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheaper.
    let ob = open_bins_count as f64;
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 15.0 + ob * 4.0 + progress * 10.0;
    } else {
        // Slight reward for using existing bins as they accumulate.
        score -= ob.min(10.0) * 0.5;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (already fragmented), penalize leaving it worse.
    let res = bin_residual as f64;
    if res < mean_residual - 20.0 {
        score += 6.0;
    } else if res > mean_residual + 20.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if next_item_size as u32 <= post_residual {
            // Next item fits: reward tight two-item packing.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize dead space that blocks lookahead.
            score += 8.0 * gap / bin_capacity as f64;
        }
    } else {
        // Last item: prefer minimal post residual.
        score += 5.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Prefer bins tighter than the mean residual (good fits), penalize looser ones.
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 20.0 * (1.0 - progress);
        // Slightly favor new bin if it would enable a perfect next-item fit.
        if next_item_size > 0 && next_item_size as u32 <= post_residual {
            score -= 15.0;
        }
    }

    // Mild preference to fill nearly-full bins to closure.
    if post_residual < 10 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave little dead space.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Reward bins whose post-residual can host the lookahead item (k=2 chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize creating dead space unusable by the next item.
        score += 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Global state coupling: many open bins with low mean residual -> consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual < item_size as f64 && bin_residual >= item_size {
        score -= 2.0 + 4.0 * progress;
    }

    // New-bin candidate handling: opening a bin is generally costly, but worth it
    // for large items or when this bin would otherwise be a poor fit.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64).powi(3);
        let scarcity = if fitting_bins_count == 0 { 15.0 } else { 0.0 };
        score += 25.0 - 20.0 * large_item_bonus - scarcity - 5.0 * progress;
    }

    // Mild penalty for leaving awkward mid-range residuals (hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: tight fits are good (low post_residual preferred).
    let mut score = post;

    // Non-linear penalty on wasted residual: quadratic in normalized waste.
    let waste_frac = post / cap;
    score += 8.0 * waste_frac * waste_frac * cap;

    // Reward near-perfect fits more aggressively (cubic suppression).
    score -= 6.0 * (1.0 - waste_frac).powi(3) * (item / cap);

    // Smooth progress coupling: late in the stream, be stricter about dead space.
    let late = progress * progress;
    score += 4.0 * late * waste_frac * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: reward if next item can use the post_residual.
    if next > 0.0 && post >= next {
        let slack = (post - next) / cap;
        score -= 3.0 * (1.0 - slack) * (next / cap);
        // Extra smooth coupling when residual matches next item closely.
        score -= 2.0 * (1.0 - slack).powi(2);
    } else if next > 0.0 {
        // Next item won't fit here: penalize proportionally to leftover gap.
        score += 2.0 * (next - post) / cap * cap * 0.05;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // or mean residual suggests poor fits elsewhere.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post).abs() / cap;
        score += 5.0; // mild default cost of opening a new bin
        score -= 4.0 * fragmentation * late * (open_bins_count as f64).ln();
        // If item is large and would leave tiny waste anyway, new bin is fine.
        score -= 3.0 * waste_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fit strongly rewarded
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Small dead space is bad; use integer-division classes on residual capacity
        let q = post_residual / 10; // decade class
        score -= 25.0 * (1.0 - (q as f64 / 10.0).min(1.0));
        // Tight fits (residual < 10) are near-perfect: extra reward
        if post_residual < 10 {
            score -= 35.0;
        }
    }

    // Lookahead: does next item fit the post residual? Reward if yes, penalize if not.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            score += 8.0;
            // waste if next item barely misses: residual just below next size
            if post_residual >= next_item_size.saturating_sub(6) {
                score += 10.0;
            }
        }
        // Harmonic pairing: post_residual + next_item_size near capacity multiples
        let pair = post_residual + next_item_size;
        if pair % 10 == 0 {
            score -= 6.0;
        }
    }

    // Last usable bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutral baseline at half-ish scale; open only if fits are poor
    if bin_residual == bin_capacity {
        // Prefer new bin when existing bins would leave large, unusable residuals
        let bad_fit = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        score = cap * 0.5 + 30.0 * bad_fit - (mean_residual - cap * 0.3).max(0.0);
        // Later in stream, slightly prefer reusing open bins
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // Many open bins: discourage opening more
        score += (open_bins_count as f64) * 1.5;
    }

    // Mild tie-break toward bins with residual close to item (best-fit flavor)
    score += (bin_residual as f64 - item_size as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=100
    // unknown distribution, so use a conservative dead-space threshold band).
    if post_residual > 0 {
        // Any leftover is "dead" if smaller than a plausible minimum item (say 10).
        // Scale penalty steeply for tiny gaps: gap 1..10 -> heavy penalty.
        let dead_threshold = 10.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 12.0;
        }
        // Mild quadratic penalty on leftover to prefer fuller packs overall.
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to residual (small waste fraction).
    if bin_residual > 0 {
        let fill_frac = item_size as f64 / bin_residual as f64;
        score -= fill_frac * 10.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, big reward (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra reward if next item nearly fills the post gap.
        let gap_fill = next_item_size as f64 / post_residual as f64;
        score -= gap_fill * 8.0;
    }
    // If next item cannot fit in the leftover, penalize large-but-unusable gaps.
    else if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // New-bin candidate (empty bin): only attractive when open bins are very full
    // on average or the current fit is terrible.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, softened by mean residual pressure.
        score = mean_residual * 0.8 + 20.0;
        if mean_residual < 15.0 {
            // Existing bins nearly full; opening a new bin is fine.
            score -= 30.0;
        }
        if fitting_bins_count == 1 {
            // An existing last-chance bin exists; prefer it.
            score += 20.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, be slightly more conservative about
    // opening new bins (amortization matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 3.0;
    }

    // Nudge toward bins whose residual is close to the item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    score += (post_residual as f64) * 0.5;

    // Aggressive 2-step lookahead: exact match of post_residual with next item is gold.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual == next_item_size {
            // Perfect chaining: this bin will be exactly filled next step.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: good, reward proportionally to closeness.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space, worse when gap is small
            // (wasted sliver) relative to item size.
            let gap = post_residual as f64;
            score += 10.0 + 15.0 * (gap / nxt).min(1.0);
        }
    }

    // Compare against mean residual across open bins: prefer bins whose post
    // residual lands near the mean (keeps a balanced residual profile).
    let pr = post_residual as f64;
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin mildly so tight existing fits win,
    // but let it win when all open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, opening fresh bins is safer (fewer chances to fix).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Slight penalty for very small unusable post_residual slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that can never be used by typical items (1..100).
    if post_residual > 0 && post_residual < 8 {
        score += 12.0; // tiny unusable sliver
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else if (post_residual as i64) > 0 {
            // waste: next item won't fit in leftover
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer filling bins with larger residuals when many bins are open
    // (consolidation), but only when this bin's residual is above mean.
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals clean); late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - tightness);

    // New-bin candidate: neutral-ish score, penalize slightly when item is small
    // and open bins exist with plenty of room, reward when item is large.
    if bin_residual == bin_capacity {
        let base = 0.5 * bin_capacity as f64;
        let mut nb = base - 0.3 * item_size as f64;
        if fitting_bins_count == 0 { nb -= 40.0; }
        if open_bins_count == 0 { nb -= 50.0; }
        if item_size > 70 { nb -= 10.0; }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual, with non-linear (quadratic) coupling.
    let mut score = post + 0.9 * (post * post) / cap;

    // Smooth interaction: post residual weighted by stream progress.
    score += 2.0 * post * progress * (1.0 - progress) * 4.0 * progress.max(0.05);

    // Reward tight fits (post_residual small relative to capacity).
    let tightness = 1.0 - post / cap;
    score -= 3.0 * tightness * tightness * item / cap * 10.0;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 6.0 * (nxt - post) * (0.5 + progress);
        } else {
            score -= 1.5 * (1.0 - (post - nxt) / cap) * progress;
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Prefer bins with below-average residual (fill emptier bins less, keep big residuals).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize mildly so it wins only when fits are poor;
    // penalty decays as stream progresses (consolidate late).
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress - 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" classes
    // (large enough to plausibly host future items), penalize dead space classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, zero waste
    } else {
        // usable if pr >= 10 (typical min item) or divisible into useful chunks
        let usable = if pr >= 10 { 1.0 } else { 0.0 };
        score -= 40.0 * usable;

        // harmonic decay: residuals divisible by common sizes (5,10,20,25,50) are reusable
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }

        // dead-space penalty for tiny unusable slivers
        if pr < 10 {
            score += 35.0 * (10 - pr) as f64;
        }

        // quadratic waste pressure: larger residuals are less urgent but less wasteful
        let frac = pr as f64 / cap;
        score += 20.0 * frac * frac;
    }

    // tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill;

    // last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr {
            score -= 15.0 * (next_item_size as f64 / pr as f64);
        } else {
            score += 8.0; // next item won't fit here; slight penalty
        }
    }

    // new-bin candidate handling: make empty bin attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open
        } else {
            // opening a new bin is discouraged unless all fits are poor
            score += 70.0 - 25.0 * crowd.min(4.0);
            if next_item_size > 0 && next_item_size as f64 > mean_residual {
                score -= 20.0; // next item may prefer a fresh bin
            }
        }
    }

    // mild stream-progression regularization
    let prog = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * prog;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual >= 1 && post_residual <= 9 {
        score += 45.0 - 4.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    } else if post_residual <= 15 {
        // Moderately small gap: mild penalty unless next item can use it.
        let gap = post_residual as f64;
        if next_item_size as f64 <= gap {
            score -= 12.0; // gap is usable by lookahead
        } else {
            score += 8.0 + (15.0 - gap) * 0.8;
        }
    }

    // Reward placing item into a bin whose residual is nearly consumed (tight packing).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Last-chance bin (only fitting bin): strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    // (penalize the new-bin candidate implicitly via residual; add pressure to spread less).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin's post-fit residual deviates far below the mean,
    // it is efficiently used; reward it. If it creates a large outlier residual, penalize mildly.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.max(0.0) - 0.10 * (-dev).min(0.0);

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size < post_residual && post_residual - next_item_size <= 5 {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it attractive only
    // when this placement would create severe dead space in an existing bin.
    if bin_residual == bin_capacity {
        // Baseline moderate score; competing bins with bad fits will exceed it.
        score = bin_capacity as f64 * 0.5 - 10.0 * (fitting_bins_count == 0) as i32 as f64;
        // Late in stream, slightly discourage opening new bins.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post residual exactly matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 300.0;
        } else if post_residual as f64 >= nxt {
            // next item fits here: mild bonus proportional to tightness
            score -= 50.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else {
            // dead space relative to next item
            score += 0.5 * (nxt - post_residual as f64);
        }
    }

    // Tightness reward relative to mean residual
    let tight = (bin_residual as f64 - item_size as f64) / cap;
    score -= 100.0 * tight;
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize choosing a fresh bin when an open bin fits well
    if bin_residual == bin_capacity {
        score += 120.0 + 0.1 * open_bins_count as f64;
    }

    // Early stream: prefer filling few bins; late stream: consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    score -= (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3) * 20.0;

    // Penalize dead space that is too small to be useful later (typical item range).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or the next item is large and would pair badly with this residual.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.5 * bin_capacity as f64;
        let lookahead_conflict = next_item_size > 0
            && (post_residual as u32) > 0
            && next_item_size > post_residual
            && next_item_size + item_size <= bin_capacity;
        if !poor_fit && !lookahead_conflict && fitting_bins_count > 0 {
            score += 25.0 + 0.5 * open_bins_count as f64;
        } else if lookahead_conflict {
            score += 5.0;
        } else {
            score -= 10.0;
        }
    }

    // Lookahead: reward bins whose post-residual accommodates the next item exactly well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize creating residual the next item cannot use.
        score += 4.0;
    }

    // Global state: if many open bins with large mean residual, prefer consolidation
    // into existing bins rather than spreading.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Time horizon: early in the stream, be slightly conservative (favor tight fits more);
    // late in the stream, prioritize closing out bins (favor bins with small residual).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * (bin_capacity as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: dead space penalized super-linearly as stream progresses
    score += 40.0 * norm_pr * norm_pr * (0.5 + t);

    // Reward tight fits (low post residual) more strongly later in the stream
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * t;

    // Last-chance bin bonus (smooth, via fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: prefer bins whose leftover can still hold the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 8.0 * (pr - ni) / cap;
        } else {
            score += 6.0 * (ni - pr) / cap;
        }
    }

    // Prefer fuller bins relative to mean residual of open bins
    score += 0.05 * (mean_residual - pr);

    // Mild penalty for spreading across many bins early
    score += 0.5 * open_bins_count as f64 * t;

    // New-bin candidate: penalize opening a new bin unless residual would be small
    if bin_residual == bin_capacity {
        score += 20.0 - 30.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets (capacity 100).
    let residue_class = (post_residual % 10) as f64;
    score += residue_class * 0.8; // prefer residuals that align to 10-grid (waste less)

    // Integer-division thresholds: how many "next item" copies fit in the leftover.
    if next_item_size > 0 && post_residual > 0 {
        let fits_next = post_residual >= next_item_size;
        let copies = post_residual / next_item_size.max(1);
        if fits_next {
            score -= 12.0 + 4.0 * (copies.min(3) as f64);
        } else {
            // leftover cannot host the lookahead item -> dead-space penalty
            score += 8.0 + 0.15 * next_item_size as f64;
        }
    } else if next_item_size == 0 {
        // last item: just minimize leftover
        score -= 20.0;
    }

    // Perfect/near-perfect fit reward (harmonic zero class).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer reusing a decent existing bin; only open new bin when
        // existing fits are poor (large post_residual) or few fitting bins.
        score += 30.0 + 0.4 * open_bins_count as f64;
        if item_size > bin_capacity / 2 {
            score -= 10.0; // big items do well in fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 15.0; // lookahead won't fit current bin anyway
        }
    }

    // Tightness coupling: reward bins whose residual is close to item size.
    let tight = (bin_residual as f64 - item_size as f64).abs();
    score -= (bin_capacity as f64 - tight) * 0.05;

    // Progress-scaled exploitation: later in stream, pack tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Mean-residual coupling: if average leftover is small, value tight fits more.
    score -= 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item (1..=100)
    // are pure waste. Penalize small-but-nonzero post_residual heavily.
    if post_residual > 0 {
        // smallest item is 1; residual < 1 is impossible, but residuals that can't
        // fit the next item are suspect dead space
        if next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // tiny unusable gaps (cannot fit even a small item later on average)
        if (post_residual as f64) < mean_residual * 0.35 {
            score += 4.0;
        }
    } else {
        // perfect closure of a bin: strongly reward
        score -= 10.0;
    }

    // Reward tight fits (small relative leftover)
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 5.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new bins
    // (raise score of the empty-bin candidate which has bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 3.0 + 0.35 * open_bins_count as f64 * (1.0 - progress);
    } else {
        score -= 0.15 * open_bins_count as f64;
    }

    // Prefer bins whose residual is near the mean (balanced packing)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: if the next item fits exactly in the post-residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual)
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: reward bins where the next item also fits the leftover
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        // penalize dead space the next item cannot use
        score += 0.15 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Compare residual to mean residual: prefer filling below-average bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.2 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight progression bias: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively near the end of the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 20.0 * (1.0 + progress);

    // Penalize creating dead space that cannot fit the next item's useful size.
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size {
            score += 8.0 + 0.25 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins whose leftover can still host the next item.
            score -= 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer bins with below-average residual (filling emptier bins keeps tight bins free).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild penalty when many bins are open, encouraging consolidation.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: make it attractive only when the item is large relative
    // to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 15.0; // forced new bin
        } else if tightness > 0.7 {
            score -= 5.0 * (tightness - 0.7) / 0.3; // big items like fresh bins
        } else {
            score += 10.0 * (1.0 - tightness); // discourage wasting fresh bins on small items
        }
        // Late in the stream, opening new bins is less useful.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: best-fit pressure with non-linear (quadratic) waste penalty.
    let mut score = 0.6 * pr + 1.4 * norm_pr * pr;

    // Smooth stream-progress coupling: later in the stream, waste matters more.
    score *= 1.0 + 0.8 * t * norm_pr;

    // Dead-space coupling with lookahead: penalize residuals too small for next item.
    let nxs = next_item_size as f64;
    if nxs > 0.0 {
        let gap = (nxs - pr).max(0.0) / cap;
        score += 25.0 * gap * gap;
        // Reward residuals that exactly accommodate the next item (smooth kernel).
        let fit_next = (pr - nxs).abs() / cap;
        score -= 12.0 * (-40.0 * fit_next * fit_next).exp();
    }

    // Interaction with mean residual: bins far below mean are "odd" -> mild penalty,
    // encouraging consolidation toward similar fill levels.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by how tight the fit is).
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // New-bin candidate (empty bin): make it attractive only when its post-residual
    // is large (small item) and alternatives are scarce; otherwise it loses to
    // tight fits because of the quadratic waste term.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - norm_pr) * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction slot does it land in?
    let frac = post_residual as f64 / bin_capacity as f64;

    // Dead-space penalty: residuals too small to be useful (below smallest item class)
    if post_residual == 0 {
        score -= 45.0; // perfect fit, reward strongly
    } else if post_residual < 10 {
        score += 60.0; // unusable sliver -> dead space
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual <= 40 {
        score -= 10.0; // sweet spot: fits medium items
    }

    // Modulo-based harmonic classes on post_residual (period 10)
    let class = post_residual % 10;
    match class {
        0 => score -= 12.0,           // round residual, very reusable
        5 => score -= 6.0,            // half-class, decent
        1 | 9 => score += 8.0,        // awkward edge residuals
        2 | 8 => score += 3.0,
        _ => {}
    }

    // Integer-division thresholds: residual quarters
    let quarter = post_residual / (bin_capacity / 4);
    match quarter {
        0 => score += 15.0, // residual < 25: risky
        1 => score -= 5.0,  // 25..49: good medium zone
        2 => score -= 8.0,  // 50..74: very flexible
        _ => score += 2.0,  // 75+: nearly empty, keep for big items
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic compatibility: reward exact/near class matches
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 30.0;
            } else if gap < 10 {
                score -= 12.0;
            } else {
                score -= 5.0;
            }
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bonus: only one bin can fit this item; using it avoids a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: fresh empty bin should only win when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - frac * bin_capacity as f64).abs();
        // Penalize opening a new bin mildly, more when open bins are roomy
        score += 35.0 + mean_residual * 0.15 - fragmentation * 0.1 - progress * 5.0;
        // Big items prefer a fresh bin
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Spread-aware tiebreak: prefer bins close to the mean residual (balanced packing)
    score += (bin_residual as f64 - mean_residual).abs() * 0.08;

    // Mild pressure against hoarding many open bins
    score += open_bins_count as f64 * 0.05;

    // Fraction-of-capacity fine tuning on residual thirds
    let third = (post_residual * 3) / bin_capacity;
    if third == 1 {
        score -= 3.0; // residual around 1/3..2/3 capacity: flexible
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        score += (10.0 - post_residual as f64) * 6.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Dead space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Open-bin pressure: discourage opening new bins when many exist,
    // encourage consolidation when few bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current bin would leave bad dead space.
        let dead = if post_residual > 0 && (post_residual as f64) < 10.0 { 1.0 } else { 0.0 };
        score += 25.0 - dead * 30.0 - (open_bins_count as f64) * 1.5;
    } else {
        score -= 5.0;
        if fitting_bins_count == 1 {
            // Last chance bin: strongly favor using it.
            score -= 20.0;
        }
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Lookahead penalty: post residual too small for next item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Mild stream progression: later in stream, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is just above item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).max(0.0) * (1.0 - tightness).max(0.0);

    // Aggressive 2-step lookahead: if next item fits in post_residual, strongly favor.
    if next_item_size > 0 {
        let next_fits = post_residual >= next_item_size;
        if next_fits {
            // Reward, scaled by how snugly the next item also fits.
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 * (slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted post_residual unless tiny.
            let waste = (post_residual as f64 - 0.0).max(0.0);
            score += 10.0 * (waste / bin_capacity as f64);
        }
        // Perfect chain: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Relative to mean residual: prefer bins that are already below-average residual
    // (consolidating waste) when post_residual is small.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 30.0 * progress;
        // But if next item is large and no open bin could chain, opening is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Mild penalty for dead space that no future item (min size 1) could use well.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize wasted space nonlinearly.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Reward using a bin whose residual was already small (compact bins).
    score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 12.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0;
        // If item is large relative to capacity, opening a fresh bin is more attractive.
        score -= 0.25 * item_size as f64;
        // If many open bins have large mean residual, prefer reusing them.
        score += 0.2 * mean_residual;
        // Fewer fitting bins -> new bin less penalized.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    // Time horizon: early in stream, be conservative (avoid fragmentation);
    // late in stream, squeeze items into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    // Prefer bins with residual close to mean (balanced usage) mildly.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;
    // non-linear coupling of post residual with stream progress
    score += 12.0 * x * x * (1.0 - x) * (t - 0.5);
    score += 8.0 * x * t * t;
    // penalize dead space relative to mean residual smoothly
    score += 0.5 * (pr - mean_residual).abs() * (1.0 + t);
    // reward last-chance bins
    if fitting_bins_count == 1 { score -= 15.0 * (1.0 + t); }
    // lookahead: reward bins whose residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (1.0 - (next_item_size as f64 / cap).max(0.0)) * (1.0 - t);
    } else if next_item_size > 0 {
        score += 4.0 * t;
    }
    // slight preference to keep new bins closed early
    if bin_residual == bin_capacity { score += 10.0 * (1.0 - t) * (1.0 - t); }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into buckets of 10
    let dead_class = post_residual / 10;
    score += (dead_class as f64) * 3.0;

    // Penalize residuals that are not "harmonic" with common item sizes (mod 10 classes)
    let r = post_residual % 10;
    if r != 0 {
        score += r as f64 * 0.7;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if next item fits into the post residual exactly or well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let after_next = post_residual - next_item_size;
            score -= (next_item_size as f64) * 0.5;
            if after_next % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when current bin would leave large dead space
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its post residual is large, so it already scores high;
        // subtract a calibrated offset so it competes when open bins fit poorly
        score -= 15.0 + 0.1 * (open_bins_count as f64);
    } else {
        // slight preference for existing bins early in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Prefer bins with residual below mean (tight packing)
    score += 0.05 * ((post_residual as f64) - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 9.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving room that can still hold the next item; penalize stranding it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Open-bins pressure: with many open bins, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly favor using it before a new bin is opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // New-bin candidate: default mild penalty so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * item_size as f64;
        // But if the item is large relative to mean residual, opening fresh is attractive.
        if (item_size as f64) > mean_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Strong reward when the leftover exactly matches the next item (2-step lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // leftover can still host the next item: mild reward proportional to slack
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space relative to next item
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Penalize deviation from mean residual (prefer balanced bins).
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin offers good lookahead room
        }
    }

    // Early in stream: be more conservative with open bins, keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that is too small for typical items (1..100 range).
    // Dead space < 10 is nearly unusable; strongly penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 10.0;
        }
        // If next item exactly fills post residual, big bonus.
        if next_item_size == post_residual {
            score -= 30.0;
        }
    } else {
        // Last item: strongly prefer filling existing bins as tightly as possible.
        score -= 20.0 * tightness;
    }

    // New-bin candidate logic: opening a new bin is wasteful unless current bins are crowded.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 35.0;
        // More open bins with high mean residual -> new bin less justified.
        if open_bins_count > 0 {
            let crowding = mean_residual / bin_capacity as f64;
            score += crowding * 20.0;
        }
        // If no existing bin fits (this call is the only candidate), allow new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mild preference for bins with residuals close to the mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Prefer larger residual bins slightly when item is small (keep big gaps for big items).
    if item_size < 40 {
        score -= bin_residual as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward near-perfect fits: subtract a smooth bump that peaks when post_residual ~ 0
    let tightness = (-pr / (0.15 * cap)).exp();
    score -= 8.0 * tightness;

    // Penalize residual that is too small to be useful later (dead space), smooth in pr
    let dead_zone = (-(cap * 0.25 - pr).abs() / (0.12 * cap)).exp();
    score += 4.0 * dead_zone * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mild penalty on opening a new empty bin, decaying as the stream progresses
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - 0.5 * progress);
        // But encourage a fresh bin when the next item is large and won't fit leftovers
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let synergy = (nxt - pr).abs() / cap;
            score += 5.0 * synergy;
        }
    }

    // Non-linear coupling with mean residual: prefer bins whose residual deviates from the mean
    // (packs tightly, keeps other bins flexible)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev * (1.0 + progress);

    // Slight preference for fuller bins late in the stream
    score += 2.0 * (pr / cap) * (1.0 - progress) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small post-residuals are valuable dead-space-wise
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Fractional capacity class: reward bins whose post residual is in a "useful" class
    // (post_residual divisible into common small item sizes: 10,20,25,50)
    if post_residual % 10 == 0 { score -= 8.0; }
    if post_residual % 20 == 0 { score -= 4.0; }
    if post_residual % 25 == 0 { score -= 4.0; }
    if post_residual % 50 == 0 { score -= 6.0; }

    // Dead-space penalty: post residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64 / cap) * 30.0;
        if post_residual == next_item_size {
            score -= 50.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0;
    }

    // Last chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate penalty: only open a new bin when current best fit is poor
    if bin_residual == bin_capacity {
        // opening fresh is good if item is large relative to capacity
        score -= (item_size as f64 / cap) * 20.0;
        // but penalize opening new bins when many bins already fit the item
        score += (fitting_bins_count as f64) * 12.0;
        // late in the stream, prefer reusing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer tighter bins overall: compare residual to mean residual
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.3;
    } else {
        score += (resid - mean_residual) * 0.3;
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.5;

    // Integer-division threshold on post_residual classes
    let class = post_residual / 10;
    score -= match class {
        0 => 5.0,
        1 => 3.0,
        2 => 1.5,
        3 => 0.5,
        4 => 0.0,
        _ => -0.5,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (min size 1, but
    // practically small gaps are wasted) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward fits that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so it gets
    // penalized here while existing bins do not).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 4.0 + 20.0;
    }

    // Prefer bins tighter than average (better packing).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect/near-perfect fit (wasted space minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 600.0; // perfect chain fit
            } else if slack <= 10 {
                score -= 250.0;
            } else {
                score -= 60.0 * (1.0 - slack as f64 / bin_capacity as f64);
            }
        } else {
            // next item won't fit here: penalize large dead space
            let dead = post_residual as f64;
            score += 0.5 * dead;
            // extra penalty if dead space is too small for even the smallest item
            if post_residual < 10 {
                score += 80.0;
            }
        }
    }

    // Penalize opening a new bin when fitting bins exist (unless last-chance logic helps)
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 40.0;
        // But if this is the only fitting option, allow new bin
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 150.0;
    }

    // Coupling with mean residual: prefer bins below-mean residual (tighter bins)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight preference for tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small post_residual that is unusable is bad,
    // but large post_residual wastes capacity. Penalize mid-range waste.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 40.0 * (10.0 - pr) / 10.0; // tiny slivers are dead space
    }

    // Reward tight fits (small post_residual relative to item size)
    score -= 25.0 * (item_size as f64) / (bin_residual as f64).max(1.0);

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item cannot follow here; slight penalty proportional to overflow
            score += 8.0 * ((next_item_size - post_residual) as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in stream, be pickier (penalize loose fits);
    // late in stream, prefer closing bins out (favor low post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins rather than spreading; encourage using this bin.
    if open_bins_count > 0 {
        let mean_r = mean_residual;
        if mean_r > (item_size as f64) * 1.5 {
            score -= 5.0;
        }
        // pressure term: more open bins -> penalize creating more slack
        score += 0.05 * (open_bins_count as f64) * (pr / bin_capacity as f64);
    }

    // New-bin candidate: opening a new bin should only win when no open bin
    // fits well. Penalize the empty-bin candidate moderately.
    if bin_residual == bin_capacity {
        score += 35.0 + 0.3 * (open_bins_count as f64);
        // allow new bin late in stream if item is large
        if item_size > 60 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize very small dead space (wasted slivers) more as stream advances
    let sliver = (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 40.0 * sliver * (1.0 - progress) * (1.0 - progress);

    // Reward tight fits (small post_residual) with a smooth quadratic bonus
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward residual that can host the next item, smoothly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 15.0 * (1.0 - gap / cap).max(0.0);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    } else {
        score += 5.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: prefer it only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64) * (mean_residual / cap);
        score += 10.0 + 12.0 * (1.0 - progress) - 0.5 * crowding;
    }

    // Mild penalty for bin proliferation early in the stream
    score += 1.5 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "usable" classes (large chunks reusable by typical items) are favored.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Penalize dead space: small leftovers that nothing (>=1) can use well.
    if post_residual > 0 && post_residual < eighth {
        score += 40.0;
    }

    // Reward post_residuals in harmonic sweet spots (multiples of 8/16/32)
    if post_residual % 16 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 8 == 0 && post_residual % 16 != 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a perfect chain placement — reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        score -= 10.0;
        if next_gap < eighth {
            score -= 6.0; // near-perfect two-item fill
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover too small for the next item: dead space risk
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Exact fit is always ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Fraction-of-capacity coupling: placing into a bin whose residual is a
    // large fraction of capacity wastes the bin; mildly prefer tighter bins.
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += residual_frac * 10.0;

    // Stream progression: late in the stream, be more conservative about
    // leaving awkward residuals (fewer chances to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < quarter {
        score += progress * 20.0;
    }

    // Mean-residual context: if this bin is far below mean residual, it is
    // already fragmented; prefer bins closer to the mean for balance.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Many open bins: discourage spreading; prefer filling existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A "dead zone" is a post_residual too small for the smallest plausible item (1..100 range),
    // so treat gaps below ~10 as wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit bonus: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Open-bin pressure: when many bins are open, prefer filling existing bins
    // (penalize the new-bin candidate implicitly through its large residual,
    // and add pressure proportional to open bins).
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when the item fits poorly everywhere else (large post_residual
    // in existing bins) or when no open bins exist.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else {
            score += 20.0 + open_bins_count as f64 * 3.0; // discourage new bins by default
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 25.0; // next item fills the gap almost perfectly
        } else {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (smaller than mean => tighter bin, fill it first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late-stream consolidation: near the end, prefer closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match with next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.35 * diff;
        // Perfect chaining: post_residual exactly equals next item size
        if post_residual == next_item_size {
            score -= 12.0;
        }
        // Next item can also fit the chained residual comfortably
        if next_item_size <= post_residual {
            score -= 3.0;
        }
    }

    // Penalize large dead space relative to mean residual (fragmentation)
    let frag = post_residual as f64 - mean_residual;
    if frag > 0.0 {
        score += 0.15 * frag;
    } else {
        score += 0.05 * frag; // slightly reward tighter-than-average bins
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Penalize creating tiny unusable residuals (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 15.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless it
    // genuinely looks better than the average open bin residual.
    if bin_residual == bin_capacity {
        // New bin starts with full residual; make it compete fairly by
        // penalizing when open bins exist with reasonable space.
        if open_bins_count > 0 {
            score += 5.0 + 0.25 * mean_residual;
        }
        // But if next item is large and no good chain exists, allow new bin
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 4.0;
        }
    }

    // Mild stream-progression pressure: tighten packing later in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.5 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical small items (<= 20).
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill, big bonus
    } else if post_residual < 20 {
        score += 6.0; // awkward small gap
    }

    // Lookahead coupling: bonus if next item fits the post residual.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after this placement; penalize more
            // if the gap left is unusable for the next item.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln() * (2.0 + 3.0 * progress);

    // Deviation from mean residual: prefer bins whose residual is below mean
    // (more filled), gently pushing toward fuller bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate handling: empty bin gets a base penalty so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream or few fitting bins, opening fresh is less bad.
        score -= 20.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear penalty on residual: dead space grows quadratically/cubically.
    let x = pr / cap; // normalized residual in [0,1]
    score += 40.0 * x * x * (1.0 + progress);

    // Reward tight fits: interaction of post_residual with item size.
    let fit_ratio = item_size as f64 / cap;
    score -= 25.0 * fit_ratio * (1.0 - x);

    // Lookahead coupling: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let snug = 1.0 - (pr - nx) / cap;
            score -= 15.0 * snug * (1.0 - progress);
        } else {
            score += 10.0 * (nx - pr) / cap * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor when only one bin fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - x);
    }

    // Penalize opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        score += 20.0 * (fitting_bins_count as f64).sqrt();
        score += 10.0 * (1.0 - progress);
        // Favor new bin when mean residual across open bins is small.
        score -= 15.0 * (mean_residual / cap);
    }

    // Mild preference for consolidating into bins below mean residual.
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap);

    // Slight stream-progress pressure to fill bins tighter later.
    score += 10.0 * progress * x * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "small residue" classes are rewarded, since small residues are hard to fill later.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional capacity bands (harmonic fractions of the bin).
    let bands: [(f64, f64); 6] = [
        (0.0, 0.10), (0.10, 0.25), (0.25, 0.40),
        (0.40, 0.55), (0.55, 0.75), (0.75, 1.01),
    ];
    let frac = pr / cap;
    let mut band_index = 5usize;
    for (i, &(lo, hi)) in bands.iter().enumerate() {
        if frac >= lo && frac < hi { band_index = i; break; }
    }
    // Reward small-residue classes (tight packing), penalize large residues.
    let band_bonus = [6.0, 4.0, 2.0, 0.0, -1.5, -3.0][band_index];
    score -= band_bonus;

    // Integer-division thresholds on post_residual: modulo arithmetic classes.
    // Residues that are multiples of common item sizes are more reusable.
    let pr_u = post_residual;
    if pr_u >= 10 {
        if pr_u % 10 == 0 { score -= 2.0; }
        else if pr_u % 5 == 0 { score -= 1.0; }
        else { score += 0.5; }
    } else if pr_u > 0 {
        // Dead space smaller than the minimum item: heavily penalize.
        score += 8.0;
    } else {
        // Perfect fill.
        score -= 10.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 3.0;
            // Harmonic check: next item exactly consumes a nice class of the residue.
            let nxt = next_item_size as f64;
            if (pr - nxt).abs() < 1e-9 { score -= 4.0; }
            else if (pr - nxt) % 5.0 == 0.0 { score -= 1.5; }
        } else {
            score += 1.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current item fits very poorly everywhere (large waste) or bins are few.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used only when justified.
        let mut nb = 14.0;
        // If the item is huge relative to capacity, prefer a fresh bin.
        if (item_size as f64) > 0.6 * cap { nb -= 8.0; }
        // If mean residual across open bins is small, existing bins are tight -> new bin ok.
        if mean_residual < (item_size as f64) * 1.15 { nb -= 6.0; }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        nb += 4.0 * progress;
        // Many open bins: discourage another one.
        nb += 0.4 * (open_bins_count as f64).min(10.0);
        score += nb;
    }

    // Mild pressure toward consolidating into fewer bins.
    score -= 0.15 * (open_bins_count as f64).recip().min(0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size)
    // are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (post_residual small relative to bin capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * tightness * tightness;

    // Penalize leaving a gap that the lookahead item could have used
    // if we place here instead of a better-fitting bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score += 4.0;
    }
    // Reward leaving exactly a gap the next item fits into.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / (10.0 + 20.0 * progress)).min(1.5);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open-bin pressure so we only open
        // a new bin when existing bins have poor fits.
        score += 25.0 + 30.0 * pressure;
        // But if remaining open bins would leave tiny dead space, opening
        // new bin becomes attractive (handled by dead-space penalty above).
        if item_size > 70 {
            score -= 10.0; // large items deserve fresh bins
        }
    } else {
        score -= 3.0 * pressure.min(1.0);
    }

    // Slight preference for bins below mean residual (keeps residuals balanced).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills leftover space.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 + 0.5 * next_item_size as f64 - 0.3 * slack;
        } else {
            // Dead space that the next item cannot use: penalize proportionally.
            let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += 10.0 + 0.4 * waste;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 5.0;
    }

    // Prefer low post_residual (tight fit) relative to mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: only this bin fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize leaving very small unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference for using existing bins over opening new ones,
    // stronger early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - 0.5 * progress);
    }

    // Slight preference for bins with smaller current residual (fuller bins).
    score += 0.2 * bin_residual as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted space
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item won't fit here; slightly penalize leaving large gap
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so if good fits exist
    // or mean residual across open bins is large enough to absorb the item.
    if bin_residual == bin_capacity {
        score += 15.0
            + 0.4 * (open_bins_count as f64)
            + 0.3 * mean_residual.max(0.0);
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // late in stream, prefer consolidating into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mildly prefer bins below mean residual (balance load, keep small gaps together).
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.08 * diff;

    // Encourage filling fuller bins earlier in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * tight * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer low post-residual, with non-linear (quadratic) emphasis
    let mut score = pr * (1.0 + 0.9 * fill * fill);

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = pr * pr / cap * (t * (1.0 - t) * 4.0);
    score += 0.35 * coupling;

    // Tight-fit reward (small post residual) grows smoother with progress
    score -= 12.0 * (1.0 - pr / cap).powi(3) * (0.5 + t);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 6.0 * (nx - pr) / cap * (1.0 + t);
        } else {
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (0.5 + t);
    }

    // Mild penalty when bin residual deviates from mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate: penalize slightly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * t - 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly preferred (quadratic).
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic classes: classify dead space by remainder mod 10.
    // Residuals < 10 are nearly unusable (items >= 1, but small items are rare);
    // penalize leaving residues in awkward classes.
    let class = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space trap
    } else if class == 0 {
        score -= 8.0; // round residues are reusable by many sizes
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of a new bin; overcome it when existing fits are bad.
        score += 35.0;
        if open_bins_count == 0 {
            score -= 60.0;
        }
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size >= bin_residual / 2 {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus
    // (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size).min(20) as f64 * 0.8;
        } else {
            // Next item won't fit here; mild penalty proportional to gap class.
            let gap = next_item_size - post_residual;
            score += (gap / 10) as f64 * 2.0;
        }
    }

    // Prefer filling bins with above-mean residual (consolidate slack).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Slight preference for using bins earlier in the stream lifecycle
    // to close them out and reduce open-bin fragmentation.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fill: strongly reward.
        score -= 100.0;
    } else {
        // Reward tightness relative to capacity.
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
    }

    // Penalize gaps that cannot fit the lookahead item (dead space for next step).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.3;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reserve space for the next item: reward.
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor dense packing.
    score += open_bins_count as f64 * 0.8;

    // Mean-residual coupling: if this bin is much tighter than average, prefer it.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual == bin_capacity - item_size here); make it costly by default.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
        // Early in stream, opening bins is cheap.
        score -= (1.0 - step_index as f64 / total_items.max(1) as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically (unusable slivers).
        if post_residual <= 10 {
            score += 200.0 - 20.0 * post_residual as f64;
        }
    }

    // 2-step lookahead: reward when next item exactly fits the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            score -= 0.5 * next_item_size as f64;
        } else {
            // Next item cannot use the leftover: penalize by gap size.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: tight fits relative to average are good.
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 250.0;
        // Early in stream, be more willing to open bins for big items.
        if item_size > 70 {
            score -= 100.0;
        }
    }

    // Mild pressure toward consolidating bins when many are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post residual), superlinearly.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 6.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize creating dead space that no future item (min size 1..10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // awkward sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: mild penalty for using scarce space in a crowded field,
    // prefer the bin whose leftover best matches the next item.
    if fitting_bins_count > 1 {
        score += 3.0;
        if next_item_size > 0 {
            let next_fit = if post_residual >= next_item_size { 0.0 } else { 1.0 };
            score += 10.0 * next_fit;
            // Reward leaving exactly enough room for the lookahead item.
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score += 0.15 * gap;
        }
    }

    // New-bin candidate handling: opening a bin is expensive; make it attractive
    // only when fits are poor or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit_penalty = (mean_residual - item_size as f64).max(0.0);
        // Base cost of a new bin.
        score += 30.0;
        // If no open bin fits at all, opening is justified.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Large items early: prefer fresh bin to preserve small residuals.
        if item_size > 60 && progress < 0.5 {
            score -= 12.0;
        }
        // If mean residual is small, open bins are nearly full anyway.
        score -= 0.2 * avg_fit_penalty;
        // Late in stream, prefer consolidating into open bins.
        score += 20.0 * progress;
    }

    // Mild preference for bins with below-average residual (keep big holes for big items).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.08 * diff;

    // Slight penalty per open bin to encourage consolidation when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + 1.5 * progress) + norm_pr * (1.0 - progress) * (1.0 - progress);
    score += 20.0 * poly;

    // Reward tight fits, stronger as stream progresses
    score -= (1.0 - norm_pr) * (1.0 + progress) * 15.0;

    // Dead space penalty: small residuals that no typical item can use
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr) as f64 / 10.0;
    }

    // Lookahead: favor bins whose post-residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 10.0 * norm_next * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 5.0 * norm_next;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_item);
    }

    // Prefer bins below mean residual (larger leftovers) to consolidate space
    score -= 3.0 * (mean_residual - pr) / cap;

    // New-bin candidate: penalize mildly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress + 10.0 * norm_item;
    }

    // Slight preference to fill older/more crowded bin sets
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" is the leftover space
    // in terms of typical item granularity (sizes 1..100).
    let cap_f = bin_capacity as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows super-linearly for tiny unusable leftovers.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 8.0; // near-unusable sliver
        } else {
            // Residual "harmonic value": reward residuals that are multiples of
            // common size classes (multiples of 10, 5), since future items
            // drawn from many distributions land on these more often.
            let mult10 = (post_residual % 10 == 0) as f64;
            let mult5 = (post_residual % 5 == 0) as f64;
            score -= 6.0 * mult10 + 3.0 * mult5;

            // Reward residuals that can host a wide range of item sizes:
            // residual >= 80 is highly reusable; residual in [10,50] moderately.
            if pr >= 80.0 {
                score -= 12.0;
            } else if pr >= 50.0 {
                score -= 6.0;
            } else if pr >= 20.0 {
                score -= 2.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            let leftover = post_residual - next_item_size;
            // Reward chains that leave a clean harmonic leftover.
            if leftover % 10 == 0 {
                score -= 10.0;
            } else if leftover < 10 {
                score += 5.0; // chain creates a sliver
            }
        } else {
            // Next item won't fit here regardless; mild bonus for tight fit now.
            score -= 3.0;
        }
    }

    // Prefer packing into bins with below-average residual (tighter bins),
    // keeping large residual bins flexible.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Late in the stream, consolidate aggressively: favor existing bins over
    // opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64).sqrt();

    // New-bin candidate: empty bin gets a baseline cost so it's chosen only
    // when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any realistic item
    // (items >= 10 in classic streams, but be conservative for unknown dists)
    // are "dead". Penalize them super-linearly.
    let dead_threshold = 9.0_f64.min(mean_residual.max(1.0)); // gap below min item size is pure waste
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    // Hard wall: a residual of exactly 0 is perfect (best possible outcome).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: fraction of the bin's residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Penalize leaving a gap that is small but not zero — the worst zone
    // (e.g., residual 1..9 after placement can never be filled).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity, so add a penalty
    // proportional to open_bins_count for that case.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
        // But if the item fits poorly everywhere else, opening may still win:
        // soften slightly when mean residual across open bins is very low.
        score -= (mean_residual * 0.5).min(15.0);
    }

    // Lookahead coupling: if the next item could exactly use the post_residual,
    // reward leaving that gap; if next item is large and post_residual is tiny,
    // slight extra penalty for wasting the bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if (next_item_size as f64) > post_residual as f64 && post_residual > 0 && post_residual < 10 {
            score += 6.0;
        }
    }

    // Mild stream-progression term: later in the stream, waste matters more
    // (less opportunity to amortize), so scale dead-space penalty up.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size is ideal.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.9;
        if post_residual as i64 == next_item_size as i64 {
            score -= 25.0; // exact chain fit: fill both this item and the next
        }
        // Penalize residuals too small for the next item (dead space).
        if (post_residual as u32) < next_item_size {
            score += 8.0;
        }
    } else {
        // Last item: minimize waste directly.
        score += 5.0;
    }

    // Favor tight fits relative to mean residual across open bins.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Penalize opening a brand-new bin when open bins could fit reasonably.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But a new bin is attractive if the item is large and fits would leave bad waste.
        if item_size as f64 > bin_capacity as f64 * 0.6 {
            score -= 15.0;
        }
    }

    // Slight preference for keeping number of open bins moderate early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the space.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity.
    score += 0.15 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * bin_capacity as f64;

    // Lookahead: if the next item can still fit in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize proportionally to wasted gap.
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Last chance: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin mildly; the tighter the alternative fits, the more this loses.
        score += 25.0;
        // Early in the stream, new bins are cheaper (more future items to co-pack).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If next item is large relative to a fresh bin's usefulness, slightly favor opening.
        if next_item_size > 0 {
            score -= 0.05 * next_item_size as f64;
        }
    } else {
        // Slight preference for bins already below mean residual (consolidate slack).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Reward using bins that are relatively full already.
        score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Mild penalty for proliferating open bins.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // smooth polynomial coupling of post_residual with stream progress
    let progress_coupling = norm_pr * (1.0 + 2.0 * t * t) * (1.0 - 0.5 * t);
    score += progress_coupling * 30.0;
    // reward near-perfect fits smoothly
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * 20.0;
    // penalize dead space relative to mean residual
    score += (pr - mean_residual) * 0.15;
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= fits_next * 15.0;
        score += (1.0 - fits_next) * gap * 0.1;
    }
    // mild penalty for spreading across many bins late in stream
    score += open_bins_count as f64 * t * 0.5;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Penalize dead space in the "unusable" band: below smallest item size,
    // or in awkward modulo classes of capacity quarters.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    let quarter = bin_capacity / 4;
    let mod_q = post_residual % quarter.max(1);
    if mod_q > 0 && mod_q < 10 {
        score += 15.0;
    }

    // Harmonic coupling with next item: if next item fits exactly into post_residual,
    // big reward; if next item almost fits (leaves tiny residue), extra reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let nxt_res = post_residual - next_item_size;
            if nxt_res <= 10 {
                score -= 80.0;
            }
            score -= 10.0;
        } else {
            // next item won't fit here; penalize proportionally to wasted anticipation
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // filling existing bins, unless existing bins have bad residuals.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.2;
    }

    // Prefer bins with residual below the mean (consolidate fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Slight pressure to close bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 45.0;
    }

    // Penalize large post_residual only mildly (usable space),
    // but couple with mean residual to avoid hoarding space.
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer new bin only when fit is terrible.
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost plus dead-space penalty for small items.
        score += 12.0;
        if item_size < 30 {
            score += 25.0;
        }
        // If lookahead item fits nicely with this one in a fresh bin, favor opening.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward tight fits relative to residual.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fill_ratio;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Slight late-stream tightening: fewer wasted gaps toward the end.
    let progress = step_index as f64 / total_items as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the post residual: strong reward scaled by fit quality.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - 0.35 * slack;
    }

    // Penalize small unusable residuals (dead space), especially if next item can't use it.
    if post_residual > 0 && next_item_size > post_residual {
        score += 15.0;
    }

    // Tightness reward: small post_residual is good.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64) * 0.0;

    // Relative to mean residual: prefer bins with below-average residual (tighter bins).
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins unless current fit is poor
    // or many bins are open (load balancing late in stream).
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64; // = capacity - item_size
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 30.0 + 0.5 * fit_quality;
        // Late in stream with many open bins, opening new bins is less costly.
        penalty -= 20.0 * progress;
        if open_bins_count == 0 {
            penalty = -100.0; // must open first bin
        }
        // If next item is large and current item is large, new bin may be better.
        if next_item_size > 0 && item_size + next_item_size > bin_capacity && post_residual < next_item_size {
            penalty -= 35.0;
        }
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio (dynamic time horizon)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward perfect or near-perfect fits (post_residual small)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
