            // Next item can still use this bin: chain potential.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + 0.15 * slack.min(50.0);
        } else {
            // Dead space unless post_residual is tiny (near-full bin is fine).
            if post_residual > 15 {
                score += 0.35 * (post_residual - next_item_size) as f64;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // When many bins can fit the item, prefer the tightest (post_residual
    // already encodes that), but mildly penalize wasting very large bins.
    if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64 - 1.0) * post_residual as f64;
    }

    // Global state: if mean residual across open bins is low, bins are
    // nearly full -> encourage consolidating into remaining space.
    if mean_residual < item_size as f64 * 1.2 {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Opening a new bin is good when current bin fit is bad (large post_residual
    // that cannot host next item) and stream is early (many items remain).
    if bin_residual == bin_capacity {
        let early_bonus = 1.0 - progress;
        // Base cost of opening a new bin decreases early, grows late.
        let mut new_bin_score = 45.0 - 20.0 * early_bonus;
        if next_item_size > 0 && post_residual >= next_item_size {
            // Existing bin can chain: new bin less attractive.
            new_bin_score += 15.0;
        }
        // If this bin is the only fitting one, don't open a new bin.
        if fitting_bins_count <= 1 {
            new_bin_score += 60.0;
        }
        score = score.max(new_bin_score);
    }

    // Mild time pressure: late in the stream, avoid spreading across many bins.
    if progress > 0.8 && open_bins_count > 3 {
        score += 0.02 * open_bins_count as f64 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post-residual (tight fit), with mild quadratic smoothing.
    let mut score = post + 0.02 * post * post / cap;

    // Reward bins whose residual was "consumed" proportionally well.
    let fill_ratio = item / cap;
    score -= 25.0 * fill_ratio * (1.0 - progress);

    // Penalize post_residual relative to the mean residual across open bins:
    // leaving more space than average wastes capacity.
    score += 0.35 * (post - mean_residual).abs();

    // Smooth non-linear coupling: post_residual * progress (later in stream,
    // dead space matters more), plus cubic interaction term.
    let t = progress;
    score += post * t * (1.0 + 0.5 * t * t);

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if nxt <= post {
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            score += 6.0 * (gap / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more so mid/late stream
    // and when other bins already fit the item.
    if bin_residual == bin_capacity {
        let mut penalty = 30.0 + 20.0 * t;
        if fitting_bins_count > 0 {
            penalty += 25.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Opening new bins early can pay off; decay the penalty quadratically.
        penalty -= 30.0 * t * (1.0 - t);
        score += penalty.max(0.0);
    }

    // Mild diversity pressure: many open bins -> prefer filling existing ones.
    score += 1.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual % 10) as f64;

    // Penalize residuals that are "almost" full (dead space hard to fill)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    // Reward residuals that exactly match likely future item sizes (multiples of 10)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Coupling with lookahead: if next item fits the post residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use remaining space; penalize proportional to wasted fraction
        score += 10.0 * (pr / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalty grows with number of open bins (encourage consolidation)
        score = cap * 0.9 + (open_bins_count as f64) * 3.0 + progress * 5.0;
        // if item is large and next item is large too, opening fresh bin is fine
        if item_size >= 50 && next_item_size >= 50 {
            score -= 20.0;
        }
        // allow new bin if no good residual class exists among fitting bins
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Tightness reward: item fills a large fraction of residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill * fill;

    // Mean residual alignment: prefer bins whose residual is near the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Harmonic integer-division threshold on post_residual
    if post_residual >= 20 && post_residual / 10 >= 2 && next_item_size > 0 && (post_residual % next_item_size.max(1)) == 0 {
        score -= 10.0;
    }

    // Small class-dependent jitter-free nudge
    score += class * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small for typical future items are wasted.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Pressure: penalize bins when many bins are open, favor consolidating.
    score += 3.0 * (open_bins_count as f64).ln().max(0.0);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing bins unless fit is poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if no bin fits well, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score += 8.0;
    }

    // Prefer bins with residual close to mean (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward proportional fit quality of the lookahead item.
            let look_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 40.0 * look_fit;
        } else {
            // Next item cannot use the leftover; penalize dead space, worse for large leftovers.
            let dead = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += 0.3 * dead;
        }
        // Perfect two-item packing: item + next fills bin exactly.
        if item_size + next_item_size == bin_residual {
            score -= 80.0;
        }
    } else {
        // Last item: strongly prefer minimal post_residual.
        score -= 30.0;
    }

    // Compare against mean residual: bins with residual far from item are less attractive.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize creating tiny unusable slivers (< 10, minimum item size).
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // New-bin candidate: prefer it only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score += 45.0;
        // But if the current item is large and would leave a small residual anywhere,
        // opening fresh is attractive (fresh bin keeps big residual for future items).
        if item_size >= 60 {
            score -= 30.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins already: discourage another one.
        score += 2.0 * open_bins_count as f64;
    }

    // Slight preference to fill bins that are already partially filled (more residual used).
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).
    // Penalize large post_residual super-linearly (dead space).
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64) * pr;

    // Lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 60.0; // perfect chaining
        } else if (next_item_size as u32) < post_residual {
            // reward proportional to how well next item uses the leftover
            score -= 30.0 * (nx / post_residual as f64);
        } else {
            // next item won't fit in leftover: mild penalty scaled by wasted space
            score += 8.0 * (pr / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many fitting bins: prefer the tightest among them (post_residual already
    // handles it, but add pressure to avoid scattering across many bins).
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening a new bin unless existing fit is bad.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Large items deserve fresh bins; small items should reuse open bins.
        score += 40.0 * (1.0 - tightness);
        // Early in the stream, opening bins is cheaper (more items to follow).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If many open bins with high mean residual, don't open another.
        score += 0.4 * open_bins_count as f64 + 0.15 * mean_residual;
    }

    // Global state: many open bins with high residuals -> consolidate into
    // existing bins rather than leaving many half-empty bins.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Small post_residual sweet spot: leftovers below min item size are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a non-linear (quartic) penalty on residual
    let mut score = pr as f64 * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on tolerate larger residuals; later punish them quadratically
    let coupling = 1.0 + 3.0 * progress * progress;
    score *= coupling;

    // Reward bins whose post-residual could host the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - progress) * (next_item_size as f64 / cap);
    }

    // Penalize dead space that cannot fit the next item, growing with progress
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 * progress * (pr / cap) * (pr / cap);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Encourage filling bins close to capacity with a smooth saturating reward
    score -= 4.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // New-bin candidate: keep neutral baseline so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) - 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: exact-fit classes are gold.
    let class = post_residual % 10;
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else if class == 0 {
        score -= 8.0;  // residual divisible by 10, reusable by common sizes
    } else if post_residual < 10 {
        score += 25.0; // dead space below minimum item size
    } else if class <= 3 {
        score += 4.0;  // awkward small class
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gain = (post_residual as f64 - next_item_size as f64).abs();
        score -= 6.0 + 12.0 * (1.0 - chain_gain / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // next item won't fit here; penalize more if this bin becomes a dead-end
        if post_residual < 10 {
            score += 10.0;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = mean_residual / bin_capacity as f64;
        let penalty = 20.0 + 30.0 * (1.0 - tightness) + 10.0 * progress;
        // allow new bin only if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            score += penalty;
        }
    }

    // Mild preference to fill fuller bins (low residual) when many bins open.
    score -= 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // future item (items >= 1) are pure waste, but tiny-but-recoverable gaps
    // (< some threshold) are the worst offenders when they can't host the
    // lookahead item either.
    if post_residual > 0 && post_residual < next_item_size as f64 {
        // dead space relative to the actual next item
        score += 25.0 + (next_item_size as f64 - post_residual as f64) * 0.6;
    }

    // Penalize very small unusable gaps regardless of lookahead
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin gets opened and this residual becomes dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless all alternatives are bad.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 2.0;
        // but if next item is huge and this item is small, opening fresh may help
        if next_item_size as f64 > item_size as f64 + post_residual as f64 && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Mild preference for bins whose residual is close to the item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    // Coupling with mean residual: if this bin's post-residual is far below
    // the mean, it's a good consolidation target.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (perfect chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact 2-step match: chain this bin
        } else if post_residual > next_item_size {
            // next item fits, but leftover after that matters
            let after_next = post_residual - next_item_size;
            score -= 30.0 - (after_next as f64).min(30.0);
        } else {
            // next item does NOT fit here -> this bin likely becomes dead space
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Penalize small unusable residuals (dead space) more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no good open fit exists. Penalize opening new bins mildly by default.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size > bin_capacity / 2 {
            score -= 10.0; // large items start fresh bins more readily
        }
        if next_item_size > 0 && next_item_size == bin_capacity - item_size {
            score -= 40.0; // fresh bin enables perfect 2-chain
        }
    }

    // Late-stream consolidation: as stream progresses, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.15;

    // Slight penalty per open bin to encourage closing bins out.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;
    // smooth polynomial coupling of post_residual with stream progress
    let prn = pr / c;
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn);
    score += poly * (20.0 + 60.0 * progress) - 8.0 * poly;
    // reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - prn) * (1.0 - prn) * it * (0.4 + 0.6 * progress);
    // penalize dead space relative to mean residual
    score += 0.15 * (pr - mean_residual).max(0.0);
    // last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }
    // lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 6.0 + 4.0 * (1.0 - prn);
    }
    // new-bin candidate: mildly penalized early, more penalized late (prefer packing)
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quarter-classification of leftover space.
    let quarter = post_residual / (bin_capacity / 4).max(1);
    let quarter_penalty = match quarter {
        0 => -30.0, // near-perfect fit: leftover < 25% capacity
        1 => -10.0, // decent leftover
        2 => 5.0,   // awkward mid leftover
        _ => 15.0,  // mostly empty bin chosen: wasteful
    };
    score += quarter_penalty;

    // Modulo-10 harmonic residue: small leftovers that pair with typical small items are good.
    let m = post_residual % 10;
    score -= (10 - m) as f64 * 0.8; // prefer leftovers close to a multiple of 10

    // Dead-space penalty if leftover can't fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // chain placement possible
            let gap = post_residual - next_item_size;
            score += gap as f64 * 0.15; // tighter chain is better
        } else {
            score += 12.0; // lookahead item won't fit here
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item lookahead favors fresh bin
        }
    }

    // Tightness coupling: reward filling a large fraction of the bin.
    let fill = item_size as f64 / cap;
    score -= fill * 20.0;

    // Progress-aware mild pressure: early stream, be choosy; late stream, pack fast.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // Mean-residual divergence: avoid bins far from the pack's typical slack.
    score += ((post_residual as f64 - mean_residual) * 0.05).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable gap" zone
    // (small but nonzero) is heavily penalized, since nothing typical fits there.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead-zone severity grows as gap shrinks below the smallest plausible item size.
        let dead_zone = if gap < 10.0 { 3.0 } else if gap < 20.0 { 2.0 } else if gap < 35.0 { 1.2 } else { 0.5 };
        score += dead_zone * (40.0 - gap.min(40.0)) * 0.8;
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Reward tight fits (post_residual small relative to bin size).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover gap: penalize leaving it.
        score += 8.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize new-bin opening implicitly via count pressure).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 12.0 + 6.0 * (open_bins_count as f64).sqrt();
        // But if mean residual across open bins is small (bins nearly full),
        // opening a new bin is more acceptable.
        score -= (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Mild stream progression term: early on, be slightly pickier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * tightness * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits (post_residual near zero)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + 20.0 * (5 - post_residual) as f64;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            score -= 100.0_f64.min(slack as f64 * 8.0);
        } else {
            // next item cannot fit: penalize dead space proportionally
            let dead = next_item_size - post_residual;
            score += dead as f64 * 3.0;
        }
    }

    // Penalize leaving residuals that are hard to fill relative to mean residual
    if post_residual as f64 > mean_residual * 1.5 {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when fits are poor
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            // fresh bin naturally accommodates lookahead
            score -= 120.0;
        } else {
            score += 60.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small dead space that nothing (min size 1) can use well; scale by fit tightness
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 20.0;

    // Penalize large post-residual relative to capacity (wasted space)
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * 30.0;

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for leaving unusable gap
            score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins
    if bin_residual < bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score -= pressure * 10.0;
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Time horizon: late in stream, consolidate more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= progress * 8.0;
    }

    // New-bin candidate handling: attractive early or when no bin fits well,
    // unattractive when an existing bin gives a tight fit
    if bin_residual == bin_capacity {
        let base = 45.0 + waste * 0.0;
        // cheaper to open new bin early in stream or when many bins are already bad
        let discount = (1.0 - progress) * 15.0 + (open_bins_count as f64).min(10.0);
        score = base - discount + tightness * 0.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin keeps room for lookahead item
        }
        // if this is the only fitting option, new bin should lose
        if fitting_bins_count <= 1 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (many items left to fill bins); later, waste is costly.
    let progress_weight = 0.5 + 2.0 * progress * progress + 1.5 * progress;
    score += 0.6 * progress_weight * norm_pr * cap * 0.1;

    // Penalize near-full-but-not-full dead space quadratically when item nearly fills bin.
    let dead = norm_pr * norm_pr * norm_pr;
    score += 40.0 * dead;

    // Reward using bins when many bins are open (consolidation pressure).
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Prefer bins whose residual is close to the mean residual (balance), smooth term.
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: make it attractive only when it truly beats poor fits.
    if bin_residual == bin_capacity {
        score += 18.0 + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 5 equal classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / (cap / 5.0)).floor().min(4.0); // 0 = tightest fit, 4 = nearly empty

    // Reward tight fits (low class) strongly, non-linearly.
    score -= (4.0 - class) * (4.0 - class) * 3.0;

    // Perfect fit gets a big reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // Chained fit is valuable, especially if it also lands in a good class.
        let next_pr = post_residual - next_item_size;
        let chain_quality = 1.0 - (next_pr as f64) / cap;
        score -= 15.0 + 10.0 * chain_quality;
    } else if next_item_size > 0 {
        // Penalize leaving a residual that just barely fails the next item.
        if next_item_size <= post_residual + 5 {
            score += 8.0;
        }
    }

    // Last chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when all
    // open fits are terrible. Penalize the fresh bin mildly, scaled by stream
    // progress and how many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * progress + 0.5 * open_bins_count as f64;
        // But if the item is large relative to capacity, a fresh bin is natural.
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item
    // (harmonic class 0 with nonzero residual) are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Modulo-10 harmonic coupling: residuals that are multiples of 10 pair
    // better with typical item granularities.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Mild preference to keep mean residual balanced: avoid filling a bin far
    // below the current mean residual (that bin was already "committed").
    score += ((mean_residual - pr).max(0.0)) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible follow-up item are pure waste -> heavy quadratic penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0;
    } else if post_residual > 0 {
        // Penalize gaps that are unlikely to be filled later.
        let dead = if post_residual < 30 { 1.0 } else { 0.0 };
        score += dead * (post_residual as f64).powi(2) * 0.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
        score -= tightness * item_size as f64 * 0.3;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += (post_residual as f64) * 0.8;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; with few bins, new bins are cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.15;

    // Prefer bins whose residual deviates favorably from the mean:
    // filling below-mean-residual bins keeps the fleet uniform.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 10.0;

    // New-bin candidate handling: an empty bin (bin_residual == bin_capacity)
    // should only win when fits are poor. Penalize it moderately, scaled by
    // how many bins already fit the item.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let fit_penalty = 12.0 + 8.0 * fitting_bins_count as f64;
        score += fit_penalty;
        // Early in the stream, opening bins is less costly.
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual exactly equals next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving space that cannot fit the next item
        if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    } else {
        // Last item: prefer minimal waste, exact fill is ideal
        score -= 20.0;
    }

    // Reward bins whose residual was already tight relative to mean residual (good fits)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize creating dead space relative to typical smallest item (1..100 unknown; use item_size scale)
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 15.0 * waste_ratio * waste_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when this would be a very poor fit elsewhere
    if bin_residual == bin_capacity {
        // Base penalty to prefer existing bins
        score += 20.0;
        // But if the item barely fits nowhere well (large item, few fitting bins), allow new bin
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * tightness * tightness;
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Late in stream with many open bins, consolidation is better than new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference to fill nearly-full bins first
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: square the post-residual penalty.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins early when open bins can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 15.0 * progress;
        // If next item is small, a fresh bin wastes potential.
        if next_item_size > 0 && next_item_size < item_size {
            score += 5.0;
        }
    } else {
        // Reward using existing bins, more when many bins are open.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Lookahead coupling: bonus if next item fits the post-residual exactly well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Global residual pressure: if mean residual is large, prefer filling bins.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Prefer larger residual bins for larger items (harmonic pairing).
    if item_size > bin_capacity / 2 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial tightening over time.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear penalty for mid-range dead space (quadratic bump centered mid-capacity).
    score += 18.0 * norm_pr * (1.0 - norm_pr) * (0.5 + progress);

    // Reward if the next item fits exactly into the post-residual (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if nxt <= pr {
            score -= 25.0 * (1.0 - gap / cap);
        } else {
            score += 6.0 * (gap / cap);
        }
    }

    // Last-chance bin: strong discount to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Many fitting bins: slight penalty so tight fits win over loose bins.
    if fitting_bins_count > 1 {
        score += 4.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Penalize bins far from the mean residual (prefer balanced residuals), smoothly.
    score += 3.0 * ((pr as f64 - mean_residual) / cap).abs();

    // New empty bin candidate: encourage only when few bins fit or late in stream.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = cap + 40.0 - 50.0 * pressure - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class boundaries at multiples of common item sizes (10, 20, 25, 50).
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -80.0 // perfect fit, ideal
    } else if pr < 10 {
        10.0 // dead space below minimum item size
    } else if pr % 10 == 0 {
        -12.0 // aligns with decade items
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        2.0
    };
    score += class_bonus;

    // Integer-division threshold: residual bucket by 20-wide bins of capacity.
    let bucket = pr / 20;
    score -= bucket as f64 * 4.0;

    // Lookahead coupling: does the leftover fit the next item well?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 25.0; // chain perfect fit
            } else if slack % 10 == 0 {
                score -= 10.0;
            } else if slack < 10 {
                score += 6.0; // would leave dead space after next item
            }
        } else {
            score += 4.0; // leftover too small for next item
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when fits are bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin; heavier penalty when decent fits exist.
        let mut penalty = 45.0 + open_bins_count as f64 * 2.0;
        if post_residual > 90 {
            penalty -= 10.0; // huge item, wasteful to squeeze elsewhere
        }
        if fitting_bins_count == 0 {
            penalty = -100.0; // must open new bin
        }
        if fitting_bins_count == 1 {
            penalty += 40.0; // there is exactly one fit; prefer it
        }
        score += penalty;
    }

    // Mean residual coupling: prefer bins deviating below mean (tighter bins).
    score -= (mean_residual - post_residual as f64).clamp(-50.0, 50.0) * 0.3;

    // Slight late-stream conservatism: keep bins tighter as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize opening a new bin when open bins exist and can fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin && open_bins_count > 0 {
        score += 25.0 + 2.0 * open_bins_count as f64;
    }
    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item almost fits (small miss), slight penalty for creating a bad gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins tighter than average (good fit relative to fleet).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild progression term: later in stream, prefer tighter fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (smaller post_residual) is better.
    // Non-linear: heavily penalize large dead space.
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly or nearly matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
        if gap == 0 {
            score -= 15.0; // chain of two perfect fits
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot fit here; leftover is likely dead space.
        score += 8.0;
    }

    // Relative-to-mean coupling: bins with residual well below mean
    // are "almost full" — favor filling them up to avoid fragmentation.
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score -= 0.15 * (-dev);
    } else {
        score += 0.10 * dev;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity / 4 {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the
    // stream is early or all fits would be poor (high post_residual).
    if bin_residual == bin_capacity {
        // Empty bin: neutral-ish baseline; discourage early on so we
        // reuse open bins, encourage late when fragmentation grows.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = post_residual as f64 + 30.0 * (1.0 - progress);
        if item_size > bin_capacity / 2 {
            score -= 10.0; // big items like a fresh bin
        }
    }

    // Mild pressure against opening many bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual small relative to item size.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 2.0 * tightness * (post_residual as f64).sqrt();

    // Penalize dead space that cannot fit plausible future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable sliver
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 3.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate handling: opening a new bin is costly early and
    // wasteful when a decent fit exists.
    if bin_residual == bin_capacity {
        let open_cost = 15.0 * (1.0 - t); // cheaper to open later in stream
        let escape_bonus = if fitting_bins_count >= 1 {
            // only open if open-bin fits are bad (large post_residual elsewhere)
            0.0
        } else {
            -10.0
        };
        score += open_cost + escape_bonus + 5.0;
    }

    // Global state: many open bins with large mean residual -> prefer
    // consolidating into bins, avoid opening new ones.
    if mean_residual > item_size as f64 * 1.5 {
        score += 4.0;
    }
    score += 0.5 * open_bins_count as f64;

    // Mild time-dependent conservatism: later in the stream, prefer
    // filling existing bins aggressively.
    score -= t * 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post residual, with non-linear decay so very small
    // residuals (dead space) are progressively penalized.
    let mut score = pr;

    // Quadratic dead-space penalty scaled by stream progress: later in the
    // stream, wasted space matters more.
    let dead = pr / cap;
    score += 40.0 * (1.0 + 2.0 * progress) * dead * dead;

    // Reward near-perfect fits smoothly (cubic dip around small residuals).
    let tight = 1.0 - (pr / cap);
    score -= 30.0 * tight * tight * tight * (1.0 + progress);

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin; smooth falloff with mismatch.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if pr >= next_item_size as f64 {
            let fit_q = 1.0 - gap / cap;
            score -= 25.0 * fit_q.max(0.0) * fit_q * (1.0 + 0.5 * (1.0 - progress));
        } else {
            score += 8.0 * (gap / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - dead);
    }

    // New-bin candidate: penalize opening new bins, more so early and when
    // many open bins still have room on average.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).ln().max(1.0);
        score += 35.0 + 20.0 * (1.0 - progress) + 10.0 * (mean_residual / cap) * crowd;
    } else {
        // Slight preference for bins whose residual deviates from the mean
        // (consolidate fragmentation): favor bins with residual below mean.
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 6.0 * dev.max(0.0);
    }

    // Mild polynomial coupling of fill ratio with progress.
    let fill = item_size as f64 / cap;
    score -= 12.0 * fill * fill * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "useful" residue classes (small leftovers that future items can fill)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Modulo-class logic: residuals divisible by common item granularities
    // (e.g. multiples of 10, 20, 25) are more reusable.
    let mut bonus = 0.0;
    if post_residual % 10 == 0 { bonus += 6.0; }
    if post_residual % 20 == 0 { bonus += 4.0; }
    if post_residual % 25 == 0 { bonus += 4.0; }
    if post_residual % 50 == 0 { bonus += 5.0; }
    score -= bonus;

    // Penalize "dead zone" residuals: too small for the smallest item (1)
    // is fine, but residuals in awkward mid-ranges are poor.
    if post_residual > 0 && post_residual < 10 {
        score += 0.0; // tiny dead space, acceptable
    } else if post_residual >= 30 && post_residual < 45 {
        score += 8.0; // awkward mid-range leftover
    }

    // Lookahead coupling: reward bins whose post_residual exactly fits
    // (or nearly fits) the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so full bins are preferred, scaled by stream progress.
        score += 35.0 + 20.0 * progress;
        // If many bins are open with slack, discourage another one.
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
        // If the item is small and next item is large, opening a fresh bin
        // now may waste it; penalize more.
        if next_item_size > 60 && item_size < 30 {
            score += 10.0;
        }
        // Occasionally a fresh bin is good for large items leaving odd residue.
        if item_size % 10 != 0 && item_size > 50 {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate into existing bins as they fill up.
    let fill_ratio = 1.0 - (bin_residual as f64 / cap);
    score -= 5.0 * fill_ratio;

    // Prefer bins whose residual is close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

