    // fits well (post_residual would be large dead space) and few bins are open.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin; its post_residual equals capacity - item
        let waste = post_residual as f64;
        score = 100.0 + 0.5 * waste;
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 1.0 {
            score -= 30.0; // fresh bin sets up a perfect next placement
        }
        if open_bins_count == 0 {
            score -= 200.0; // must open a bin
