            (bin_capacity as f64 - (item_size as f64 + next_item_size as f64).min(bin_capacity as f64)).abs()
        } else {
            bin_capacity as f64 - item_size as f64
        };
        score = 100.0 + pair_waste * 0.5 + open_bins_count as f64 * 2.0;
        // Make new bins acceptable when no open bin fits well (large dead space elsewhere).
        if mean_residual < item_size as f64 + 5.0 {
            score -= 30.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.3;

    // Lookahead coupling: prefer leaving exactly the next item's size as residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        score -= 15.0 * (1.0 - gap as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly or well
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0; // perfect chain
        } else if post_residual > next_item_size {
            score -= 100.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot fit: penalize wasted lookahead potential
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Compare against mean residual: prefer bins already below mean (tighter bins)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing open bins,
    // but allow opening if the fit is bad (large post_residual relative to capacity)
    if bin_residual == bin_capacity {
        score += 40.0 + 0.25 * (post_residual as f64);
    }

    // Late-stream tightening: as stream progresses, favor tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-perfect fits strongly.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    let tight_bonus = (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;
    score += tight_bonus;

    // Reward using a bin whose residual is close to item_size (good packing).
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score -= 12.0 / (1.0 + waste);

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here: mild penalty scaled by how much space is stranded
            score += (post_residual as f64 / bin_capacity as f64) * 8.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidation
    // into already-open bins rather than opening new ones.
    let consolidation_pressure = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when there are many open bins with slack,
        // and less as the stream progresses (fresh bins useful early).
        score += 10.0 + consolidation_pressure * 8.0 - progress * 6.0;
    } else {
        score -= consolidation_pressure * 4.0;
    }

    // Dead-space avoidance: residuals too small for any item (min size 1, but
    // realistically small slivers) are penalized nonlinearly.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.5;
    }

    // Mild time-horizon coupling: early on, keep bins flexible (prefer balanced
    // residuals); late, greedily fill bins.
    let flexibility = (post_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += flexibility * (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear fit quality: tight fits rewarded super-linearly
    let tightness = 1.0 - pr / cap;
    score -= 40.0 * tightness * tightness * tightness;

    // Penalize residuals that are unusable dead space for typical items (smooth coupling)
    let dead = (pr / cap) * (pr / cap);
    score += 25.0 * dead * (1.0 - progress);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize when open bins can fit, reward when stream is early
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score += 45.0 * (1.0 - (-fit_pressure / 3.0).exp());
        score -= 15.0 * (1.0 - progress);
        // If lookahead item would fit the leftover, opening a new bin is attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    } else {
        // Reward leaving room for the lookahead item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0 + 10.0 * (next_item_size as f64 / cap);
        }
    }

    // Stream-progress coupling: later in stream, prefer packing into existing bins
    score += (1.0 - progress) * 10.0 * (pr / cap);
    score -= progress * 8.0 * (1.0 - (pr / cap));

    // Small penalty scaled by number of open bins to discourage bin proliferation
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 5.0;

    // Interaction with mean residual: prefer bins near mean residual (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in small residues is worse
    let pr = post_residual;
    if pr > 0 {
        // residue class buckets: tiny leftovers are hard to fill
        let class = match pr {
            1..=5 => 3.0,
            6..=15 => 2.0,
            16..=30 => 1.0,
            _ => 0.0,
        };
        score += class * (cap / 20.0);
        // modular penalty: residues near multiples of common item sizes are usable
        let usable = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0) || (pr % 50 == 0);
        if usable { score -= 8.0; }
    } else {
        // perfect fill: strong reward
        score -= 40.0;
    }

    // Tight fit reward: item fills most of the bin
    let fill_frac = item_size as f64 / cap;
    if fill_frac > 0.8 { score -= 12.0; }
    else if fill_frac > 0.6 { score -= 6.0; }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0 + (next_item_size as f64 / cap) * 10.0;
    } else if next_item_size > 0 {
        // next item won't fit here; penalize leaving awkward residue
        score += 3.0;
    }

    // Prefer filling already-open bins when many are open
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate: penalize opening a new bin unless current bins are full-ish
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - (mean_residual / cap);
        if mean_fill < 0.5 {
            score += 25.0; // existing bins underused, don't open new one
        } else {
            score += 5.0;
        }
        // early in stream, opening bins is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 5.0;
    }

    // mild tie-break toward bins below mean residual (balance avoidance of fragmentation)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone = 10.0f64; // gaps below this are near-useless for typical items
    if post_residual > 0 && post_residual < 10 {
