    }
    // Reward tight fits (small post_residual) nonlinearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.004;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.15;
    }

    // Lookahead: if next item could exactly fill this bin's post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item fits the post_residual, mild reward.
    if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        score -= 3.0;
    }

    // Prefer bins whose residual is close to the item (best-fit sharpening).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect two-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Reward close matches to the next item (soft lookahead coupling)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + gap);
    }

    // Penalize dead space relative to mean residual (waste vs fleet average)
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.8;

    // Last-chance bin: strongly prefer filling it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when existing bins would leave large dead space
    if bin_residual == bin_capacity {
        let best_alternative_penalty = if next_item_size > 0 && post_residual == next_item_size { 0.0 } else { 30.0 };
        score = bin_capacity as f64 * 0.9 + best_alternative_penalty
            - if post_residual >= item_size { 0.0 } else { 0.0 };
        // discourage opening new bins when a decent fit exists elsewhere
        score += (fitting_bins_count as f64) * 15.0;
        // early in the stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 50.0;
    }

    // Small bonus for tight fits overall
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post-residual non-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space for the known next item: penalize.
            score += 4.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins (penalize
    // cramming); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;
    score += (1.0 - progress) * 6.0;

    // Global state coupling: many open bins with high mean residual -> encourage
    // filling existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= (mean_residual / bin_capacity as f64) * 3.0;
        score += open_bins_count as f64 * 0.5;
    }

    // New-bin candidate calibration: empty bin should lose unless other signals
    // (large dead-space risk) favor it.
    if bin_residual == bin_capacity {
        score += 15.0 - progress * 10.0;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    }

    // Penalize leaving awkward residuals that few item sizes can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress) - 1.2 * norm_pr * norm_pr * (0.5 + progress);

    let mut score = pr + poly * cap * 0.3;

    // Reward tight fits smoothly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize waste relative to mean residual across open bins
    score += 0.15 * (pr as f64 - mean_residual).abs();

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let gap = pr as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= 2.5 * (1.0 - gap / cap);
        } else {
            score += 0.05 * (-gap);
        }
    }

    // Mild penalty for spreading across too many bins
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: keep neutral-ish baseline, slightly discouraged early
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) + 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band it lands in.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let pr = post_residual;
    let mut class_penalty = 0.0;
    if pr == 0 {
        class_penalty -= 40.0; // perfect fill
    } else if pr < eighth {
        class_penalty -= 12.0; // near-perfect
    } else if pr < quarter {
        class_penalty -= 2.0;
    } else if pr < quarter * 2 {
        class_penalty += 4.0;
    } else if pr < quarter * 3 {
        class_penalty += 10.0;
    } else {
        class_penalty += 18.0; // large dead space
    }
    score += class_penalty;

    // Harmonic compatibility: does post_residual pair with next_item_size?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // exact pairing next step
        } else if next_item_size <= pr {
            // modularity: can the residual host the next item plus a small harmonic remainder?
            let rem = pr - next_item_size;
            let rem_class = rem % quarter;
            if rem_class == 0 {
                score -= 10.0;
            } else if rem_class < eighth {
                score -= 5.0;
            } else {
                score += rem_class as f64 * 0.15;
            }
        } else {
            // next item cannot fit here; residual must serve later items
            score += 6.0;
            if pr < next_item_size / 2 {
                score += 8.0; // tiny unusable stub
            }
        }
    }

    // Last-chance bin before opening a new one: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        // but only if the fit is decent
        if post_residual > quarter * 3 {
            score += 15.0;
        }
    }

    // New-bin candidate: penalize opening fresh bins when a reasonable fit exists,
    // unless all open fits are terrible and the item is large.
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 50.0;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 {
            // discourage new bin if any open bin leaves < eighth waste
            score += 10.0;
        }
    }

    // Tightness reward: the fuller the bin becomes, the better.
    let fill = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= fill * fill * 10.0;

    // Mean-residual coupling: prefer bins below mean residual (denser bins).
    score += (mean_residual - post_residual as f64).max(0.0) * -0.1;
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.1;

    // Stream progression: early on, keep bins open flexibly; late, pack hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Non-linear penalty: gaps below ~15 units are almost pure waste.
        if post_residual < 15 {
            score += 30.0 * (15.0 - dead);
        }
        // Penalize gaps that cannot fit a typical small item (min size 1..10 range).
        if post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize opening new bins implicitly via the new-bin candidate score).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        // Existing bin: reward more when many bins are open.
        score -= 2.0 * (open_bins_count as f64).sqrt() * (1.0 + progress);
    } else {
        // New-bin candidate: penalize unless it is a much better option.
        score += 5.0 + 3.0 * (open_bins_count as f64).sqrt();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if post_residual can fit the next item, reward;
    // if it almost fits but not quite, penalize the dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size - post_residual <= 10 {
            score += 12.0;
        }
    }

    // Mean residual coupling: prefer bins with residual below the mean
    // (fill the fullest bins first, keeping large gaps in other bins usable).
    if bin_residual != bin_capacity {
        score += 0.5 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
