    }

    // New-bin candidate handling: only open a new bin when fits are poor or many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = (post_residual as f64) / (bin_capacity as f64);
        let mut nb = 60.0;
        // If this bin (new) fits perfectly or near-perfectly, it's attractive.
        nb -= 55.0 * (1.0 - pressure);
        // When mean residual across open bins is low, opening new is reasonable.
        nb -= (mean_residual / bin_capacity as f64) * 15.0;
        // Few fitting bins => new bin less risky.
        if fitting_bins_count <= 1 {
            nb -= 20.0;
        }
        // Late in the stream, avoid proliferation of open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        nb += progress * 10.0 + open_bins_count as f64 * 1.5;
        score = nb;
    } else {
        // Prefer fuller bins relative to the fleet average residual.
        score -= (bin_residual as f64 - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress:
    // residual waste is penalized more aggressively as the stream advances.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (0.5 + progress) + pr_norm * (1.0 - progress) * 0.5;
    score += poly * bin_capacity as f64;

    // Reward tight fits (small post_residual) with a smooth non-linear bonus
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * item_size as f64 * 0.5;

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let pair_fit = 1.0 - diff / bin_capacity as f64;
        score -= pair_fit * pair_fit * next_item_size as f64 * 0.4;
        // Penalize leaving residual that is too small for the next item (dead space)
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bonus: strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= item_size as f64 * 2.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early
    // in the stream and when many bins are already open but residual exists.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score += bin_capacity as f64 * (0.6 + 0.4 * (1.0 - progress)) * (1.0 + openness * 0.5);
        // Allow new bin if mean residual of open bins is very low
        score -= mean_residual * 0.5;
    } else {
        // Mild preference for bins with residual near the mean (balance load)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill and small-dead-space classes are good.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 30.0;
    } else if pr <= 15 {
        score -= 10.0;
    } else {
        // dead space penalty grows for mid-range residuals
        score += 0.15 * (pr as f64);
    }

    // Modulo classes: residuals that are multiples of 10 are more "usable"
    // by typical item sizes; reward them.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: can next item exactly fill the post residual?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == pr {
            score -= 45.0; // chained perfect fit
        } else if next_item_size < pr && (pr - next_item_size) <= 10 {
            score -= 20.0; // near-chained fit
        } else if next_item_size > pr {
            // next item cannot use this residual: penalize wasted space
            score += 0.10 * (pr as f64);
        }
        // harmonic division: residual divisible by next item size
        if next_item_size > 0 && pr % next_item_size.max(1) == 0 && pr > 0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item barely fits nothing well.
    if bin_residual == bin_capacity {
        // base cost of opening a bin; offset by how bad existing fits are
        score += 40.0;
        if item_size as f64 / cap > 0.7 {
            score -= 20.0; // big items are fine in fresh bins
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0; // lookahead won't fit mean residual; fresh bin useful
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill;

    // Late-stream consolidation: fewer open bins preferred as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to ever hold a realistic item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Reward tight fits relative to bin capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += 0.8 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (avoid dumping into large bins).
    score += 0.15 * (bin_residual as f64 - item_size as f64).abs();

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // Dead space that next item cannot use.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // Penalize opening new bins when open bins can fit, more so late in stream.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 25.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
            // Allow new bin if all fits would be terrible (huge dead space).
            if post_residual < 10 && item_size >= 80 {
                score -= 35.0;
            }
        }
    }

    // Mild alignment with mean residual: prefer bins below mean (tighter bins).
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits heavily.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64));
        if post_residual as i64 == next_item_size as i64 {
            score -= 100.0;
        }
        // Penalize leaving a residual too small for the next item (dead space).
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 30.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate: penalize moderately so it's chosen only for poor fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if no good fit exists (large dead space everywhere), allow new bin.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() as f64 > 40.0 {
            score -= 20.0;
        }
    }

    // Early in stream: slightly favor consolidation into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = item_size as f64 / bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: larger items are more valuable to place.
    score -= fill * 18.0;

    // Strongly reward near-perfect packing (very small leftover).
    if post_residual > 0 && post_residual <= 10 {
        score -= 10.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Last-chance bin: if this is the only open bin that fits, use it
    // rather than opening a new bin (unless it's already the new-bin call).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Penalize the new-bin candidate so open bins get filled first;
    // the penalty shrinks for large items that would leave little room anyway.
    if bin_residual == bin_capacity {
        score += 26.0 - 22.0 * fill;
        // If no open bin can fit the item, a new bin is mandatory.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 9.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // leftover dead space relative to the known next item: mild penalty
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Slightly prefer bins whose residual deviates from the fleet mean,
    // consolidating space into fewer, more usable bins over time.
    score += (mean_residual - post_residual as f64).abs() * 0.08;

    // Late in the stream, be more conservative: prefer filling existing bins.
    score -= progress * 4.0 * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post_residual, with non-linear (quadratic) coupling
    let mut score = pr + (pr * pr) / cap;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: residuals that are too small to be useful later
    let min_useful = 10.0;
    if pr < min_useful && pr > 0.0 {
        score += (min_useful - pr) * 2.0;
    }

    // Lookahead coupling: reward if the next item fits into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - nxt / pr.max(1.0)) * (1.0 + progress);
        } else {
            // penalize leaving a residual that just barely misses the next item
            let miss = nxt - pr;
            if miss < 15.0 {
                score += miss * 0.8;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // slight preference for more crowded bins when alternatives exist
        score -= 2.0 * (open_bins_count as f64).recip();
    }

    // Mean-residual coupling: prefer bins deviating below mean residual (tighter bins)
    score += 0.3 * (mean_residual - pr);

    // Stream progress: later in the stream, be more aggressive about filling bins
    // (penalize opening new bins late), smooth polynomial in progress
    let new_bin_candidate = (bin_residual as f64 - cap).abs() < 0.5;
    if new_bin_candidate {
        score += 8.0 + 20.0 * progress * progress;
        // only open a new bin if no open bin gives a decent fit
        if pr <= 0.0 && bin_residual == bin_capacity {
            score += 4.0;
        }
    }

    // Small smooth progress-based tilt toward tighter fits over time
    score -= 3.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals near "useful" classes
    // Classes of 10: 0 is perfect, small residuals (1..=9) are dead space.
    let class = post_residual / 10;
    let rem = post_residual % 10;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        // tiny dead space: strong penalty
        score += 40.0 * (6 - post_residual) as f64;
    } else {
        // Reward residuals that are multiples of 10 (harmonic with capacity 100)
        if rem == 0 {
            score -= 15.0;
        }
        // Reward residuals that could hold common item sizes (multiples of 5)
        if rem % 5 == 0 {
            score -= 5.0;
        }
        // Mild penalty for odd/awkward residuals
        if rem % 2 == 1 {
            score += 3.0;
        }
        // Larger classes are better (more usable space)
        score -= class as f64 * 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 - slack as f64 * 0.2;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening new bins when open bins have plenty of room
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure from mean residual
        score += 60.0 + mean_residual * 0.5 + (open_bins_count as f64).sqrt() * 5.0;
        // If current item is large and next item is also large, opening early can help
        if item_size > 50 && next_item_size > 50 {
            score -= 25.0;
        }
    }

    // Fraction of stream processed: later, prefer consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual close to item size (tight fit)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Many fitting bins: slight penalty to encourage diversity of choice pressure
    if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the smallest
    // likely item (>=1) are unusable; penalize small-but-nonzero gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that can't fit the next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 35.0;
    }
    // Reward gaps that exactly or nearly fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins when mean
    // residual is already low; encourage closing out low-residual bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 2.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive if all open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        let bad_fit_exists = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) < 10;
        if bad_fit_exists {
            score -= 15.0; // shouldn't happen for empty bin, but guard
        }
        // Prefer new bin when current bin would leave unusable dead space.
        let dead_space = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        score += 25.0 * dead_space;
        // Early in stream, new bins are cheap; later, reuse matters more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * (1.0 - progress);
        // If many bins are open with slack, avoid opening yet another.
        score += 0.8 * open_bins_count as f64;
    }

    // Mild reward for bins whose residual is close to mean (balance load).
    score -= 1.5 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Leftover can still host the next item: reward proportionally to closeness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 {
        // Leftover cannot host next item: penalize dead space, worse when very small.
        let dead = post_residual as f64;
        score += 25.0 * (1.0 - dead / bin_capacity as f64);
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize creating dead space far below mean residual (wasted bin space).
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor or none are tight.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_next = next_item_size > 0 && next_item_size as f64 > mean_residual;
        if pressure > 0.0 || (big_next && next_item_size >= item_size) {
            score -= 55.0;
        } else {
            score += 45.0;
        }
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}
